local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["item:gyromechanic-gear"] = {n="多档齿轮",s="多档齿轮是诺莫瑞根外辐射尘中回收的一件精密工程部件。卡拉诺斯的侏儒发明家们正在寻找这种特定的齿轮，以制造一种能够逆转麻风侏儒变异的实验装置。",h="多档齿轮是诺莫瑞根外辐射尘中回收的一件精密工程部件。卡拉诺斯的侏儒发明家们正在寻找这种特定的齿轮，以制造一种能够逆转麻风侏儒变异的实验装置。",kw={"诺莫瑞根","多档齿轮","卡拉诺斯","麻风侏儒","重组行动","拉兹·滑链","重组装置","自适应齿轮"},ang={["profession:Engineering"]="侏儒的精密工程以极其复杂而闻名，依靠高公差的多档齿轮组件来调节不稳定的原型机械。",["race:Gnome"]="每一个搜寻到的齿轮都让侏儒技师们离拯救那些在诺莫瑞根外雪地中徘徊的受辐射同胞更近了一步。"},sec={{t="重组装置的组件",b="当辐射涌入诺莫瑞根以清除穴居人入侵时，它使大量幸存的侏儒人口变成了疯狂且受到辐射感染的麻风侏儒。发明家奥齐·电环和拉兹·滑链不愿放弃他们那些扭曲的同胞，于是开始起草“重组装置”的设计图——这是一种旨在消除辐射可怕影响的雄心勃勃的装置。制造原型机需要能够承受剧烈内部压力的精密机械，特别是多档齿轮和配套的稳压齿轮。由于本地制造业随着首都的陷落而崩溃，研究人员被迫直接从游荡在丹莫罗的敌对麻风侏儒身上搜寻这些精密的部件。"}},faq={{q="多档齿轮有什么用途？",a="它是卡拉诺斯的拉兹·滑链所需的核心机械组件。它与稳压齿轮一起被整合到重组装置中，这是一种旨在治愈受辐射感染的麻风侏儒的原型机器。",al={"多档齿轮用途","多档齿轮的作用","多档齿轮任务"}},{q="这些齿轮来自哪里？",a="它们是从诺莫瑞根外的麻风侏儒和丹莫罗的吉布尔威特身上搜寻到的。",al={"哪里可以找到多档齿轮","多档齿轮掉落","谁掉落多档齿轮"}},{q="重组装置真的能治愈麻风侏儒吗？",a="拉兹·滑链对奥齐的设计图始终保持无限乐观，相信通过对燃烧活塞和电胶凝胶的调整就能恢复他们的同胞。这台机器是否真的能大规模逆转灾难性的辐射中毒，仍然是一个未经测试的侏儒理论。",al={"重组装置有效吗","麻风侏儒能被治愈吗","重组是否成功"}},{q="为什么侏儒不能直接锻造新的齿轮？",a="诺莫瑞根的陷落摧毁了侏儒的工业能力，锁住了他们最先进的工具、车间和自动化铸造厂。在城市周边搜寻完好无损的战前精密硬件，通常远比手工加工零件要快得多。",al={"为什么需要搜寻齿轮","为什么不直接制造多档齿轮"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="神圣信件",s="神圣信件是一封带有女牧师安妮塔印章的正式传唤信，被送往北郡山谷中有前途的年轻牧师手中。它召唤持有者前往北郡修道院，开始对圣光的正式学习和训练。",h="神圣信件是一封带有女牧师安妮塔印章的正式传唤信，被送往北郡山谷中有前途的年轻牧师手中。它召唤持有者前往北郡修道院，开始对圣光的正式学习和训练。",kw={"安妮塔","艾尔文森林","神圣信件","圣光","北郡修道院","牧师","女牧师安妮塔"},ang={["class:Priest"]="这封信标志着你正式被认可为圣光的工具，确立了你与北郡修道院训练师之间的联系。",["race:Human"]="人类牧师自第一次战争前就在北郡山谷进行修炼；收到这封信延续了那种神圣职责的古老传统。"},sec={{t="信仰的召唤",b="神圣信件上盖有女牧师安妮塔的个人印记，它是在年轻牧师完成了针对北郡山谷狗头人营地的初次试炼后颁发给他们的。安妮塔察觉到了新手心中那一点点圣光火花，并敦促他们不要迟疑，尽快进入修道院内进行正式的宣誓。在第三次战争之后，黑暗势力依然在艾泽拉斯徘徊，牧师教团正在积极召集那些有能力治愈、保护并为这个努力维持秩序的帝国提供精神指引的人们。"}},faq={{q="什么是神圣信件？",a="这是一封由女牧师安妮塔盖章的介绍信，颁发给刚到达北郡修道院的牧师，用于召唤他们接受最初的职业指导。",al={"什么是神圣信件","神圣信件物品","北郡牧师信件"}},{q="是谁写的这封信？",a="这封信带有女牧师安妮塔的印章，她是负责指导来到北郡的年轻人类牧师的驻地训练师兼精神导师。",al={"谁寄出的信","作者是谁","信件寄信人"}},{q="为什么牧师教团现在要召集新成员？",a="世界依然处于动荡之中。燃烧军团的残党依然在艾泽拉斯阴魂不散，卡利姆多也面临着新的考验，而暴风城王国需要富有同情心的治疗者和领导者来重建和保护其人民。",al={"为什么牧师需要帮助","世界现状","牧师背景故事"}},{q="读完这封信后我该做什么？",a="带着信进入北郡修道院，与女牧师安妮塔交谈。她会接受你对圣光的誓言，并在你的旅程展开时为你提供新的牧师职业训练。",al={"我应该把信交给谁","神圣信件任务交接","找谁交谈"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="神圣符文",s="神圣符文是一块刻有铭文的石头，会交给在寒脊山谷开始训练的见习牧师。它由矮人牧师训练师布兰斯托克·卡德尔寄出，召唤有志于圣光之道的修行者前往安威玛尔，开始他们的正式受教之旅。",h="神圣符文是一块刻有铭文的石头，会交给在寒脊山谷开始训练的见习牧师。它由矮人牧师训练师布兰斯托克·卡德尔寄出，召唤有志于圣光之道的修行者前往安威玛尔，开始他们的正式受教之旅。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","神圣符文","牧师","穴居人"},ang={["class:Priest"]="神圣符文标志着一名牧师在寒脊山谷正式接受圣光之道导师教导的开始。",["race:Dwarf"]="矮人牧师将对圣光的虔诚信仰与对铁炉堡的坚定职责融为一体，挺身而出保卫他们的高山家园，对抗穴居人。"},sec={{t="圣光的召唤",b="当一名年轻的牧师在协助寒脊山谷的山地巡逻队员和守卫者时展现出决心后，布兰斯托克·卡德尔便会寄出神圣符文。这块石头上刻有圣光的教义，既是一份引荐信，也是一份邀请函。矮人见习牧师会被指引着离开雪地中的小规模冲突，向安威玛尔报到，布兰斯托克将在那里指导他们治疗伤口，并掌握对抗威胁丹莫罗的穴居人入侵者的神圣力量。"}},faq={{q="什么是神圣符文？",a="神圣符文是一块刻有指引见习牧师文字的小型圣石。它是布兰斯托克·卡德尔发出的正式召唤，旨在让见习牧师在安威玛尔内开始正式的精神与魔法教导。",al={"这是什么物品","神圣符文物品","符文用途"}},{q="是谁把神圣符文寄给你的？",a="它是由驻扎在安威玛尔内的矮人牧师训练师布兰斯托克·卡德尔寄出的。他通过寒脊山谷的盟友将它传送到那些已经在实地证明了自己的年轻牧师手中。",al={"谁寄出的符文","谁给了我这个符文","布兰斯托克的符文"}},{q="收到神圣符文后我该怎么办？",a="你应该花点时间阅读符文，然后前往安威玛尔的主大厅向布兰斯托克·卡德尔报到，他会在那里教你新的祷言和法术。",al={"我该把符文带到哪里","如何处理神圣符文"}},{q="为什么布兰斯托克希望尽快训练见习牧师？",a="寒脊山谷不断受到穴居人入侵的骚扰，山地巡逻队员需要尽其所能召集一切神圣的治疗与攻击力量来保卫丹莫罗。",al={"为什么需要牧师","穴居人问题与牧师"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="神圣卷轴",s="神圣卷轴是一份正式的传唤书，递交给丧钟镇中刚苏醒的被遗忘者牧师。它带有黑暗牧师杜斯滕的个人印记，指引这些初学者前往废弃的礼拜堂，开始他们在信仰、意志力和暗影方面的再教育。",h="神圣卷轴是一份正式的传唤书，递交给丧钟镇中刚苏醒的被遗忘者牧师。它带有黑暗牧师杜斯滕的个人印记，指引这些初学者前往废弃的礼拜堂，开始他们在信仰、意志力和暗影方面的再教育。",kw={"丧钟镇","杜斯滕","被遗忘者","神圣卷轴","圣光","牧师","提瑞斯法"},ang={["class:Priest"]="这张羊皮纸标志着与传统人类信仰的决裂，将被遗忘者牧师引向自我意志的信念，以及被遗忘的影之议会所实践的暗影艺术。",["race:Undead"]="收到这份传唤反映了丧钟镇紧急而务实的动员，确保新苏醒的亡灵能被迅速训练并整合进希尔瓦娜斯的军队中。"},sec={{t="致无信者的传唤",b="新苏醒的被遗忘者牧师发现他们与世界的联系发生了剧烈的转变。神圣卷轴在丧钟镇复垦过程中持续的混乱中被送达，指引这些新生的施法者前往定居点内废弃的礼拜堂寻求指引。这张羊皮纸上盖着黑暗牧师杜斯滕的印记，既是介绍信，也是要求正式报到的命令，引领牧师进入定义被遗忘者牧师职责的务实哲学。"},{t="自力更生之路",b="在响应卷轴的传唤后，牧师们会被立即摒弃旧有的教条。杜斯滕明确指出，传统的倚靠——对圣光的崇拜、祖先之灵或恶魔契约——已不再适用于亡灵。相反，这份卷轴标志着一种严格植根于个人意志力的内在纪律的开始。由这张羊皮纸开启的教义强调通过纯粹的信念来生存和统治，将宗教信仰转化为一种自我决定和掌控的工具。"}},faq={{q="什么是神圣卷轴？",a="神圣卷轴是递交给丧钟镇中新苏醒的被遗忘者牧师的书面信息。它指示阅读者向礼拜堂内的黑暗牧师杜斯滕报到，以开始他们正式的牧师训练。",al={"这个卷轴是什么","神圣卷轴的目的","物品神圣卷轴"}},{q="谁发送了神圣卷轴？",a="这份卷轴带有黑暗牧师杜斯滕的个人印记，他是驻扎在丧钟镇废弃教堂里的牧师训练师。",al={"谁写了神圣卷轴","谁发送了卷轴","杜斯滕的卷轴"}},{q="当你把卷轴交给黑暗牧师杜斯滕时，他教导什么？",a="杜斯滕教导说，亡灵牧师必须摒弃对圣光、祖先之灵或其他世界力量的传统依赖。他宣扬被遗忘者是单凭纯粹的个人意志力才生存下来的，并指导年轻的牧师培养自我信仰，以引导和支配他人。",al={"杜斯滕说了什么","被遗忘者牧师信仰","丧钟镇牧师背景故事"}}},fp="15,183,26.425.0,25.361.0,28.178.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="神圣符记",s="神圣符记是幽影谷年轻新手随身携带的一种刻有铭文的暗夜精灵信物。它由牧师训练师珊达派发，作为一种正式传唤，引导艾露恩的潜在仆从前往奥达希尔的古老枝干处。",h="神圣符记是幽影谷年轻新手随身携带的一种刻有铭文的暗夜精灵信物。它由牧师训练师珊达派发，作为一种正式传唤，引导艾露恩的潜在仆从前往奥达希尔的古老枝干处。",kw={"奥达希尔","神圣符记","新手","卡多雷","牧师","幽影谷","珊达","泰达希尔"},ang={["class:Priest"]="对于暗夜精灵牧师来说，神圣符记代表了他们接受The Sisterhood of Elune正式训练的第一次征召。",["race:NightElf"]="在联盟旅者刚刚开始抵达泰达希尔枝干之时，这一符记标志着卡多雷信徒服役的开始。"},sec={{t="牧师的征召",b="踏入幽影谷神圣树冠的暗夜精灵牧师新手，经常会从林间信使那里收到神圣符记。这种刻有神圣印记的信物是来自奥达希尔驻地牧师训练师珊达的亲笔信。携带并阅读该符记会指引侍僧前往奥达希尔高耸的树洞，正式将他们引荐给The Sisterhood of Elune，并在新的旅者抵达泰达希尔之际，开启他们为卡多雷服务的属灵生涯。"}},faq={{q="什么是神圣符记？",a="神圣符记是一种刻有铭文的神圣信物，颁发给幽影谷的年轻暗夜精灵牧师。它承载着一道传唤指令，要求新手去寻找他们的导师珊达。",al={"什么是神圣符记","幽影谷牧师符记"}},{q="谁派发了神圣符记？",a="它是由当地信使代表驻扎在奥达希尔巨型空心树内的牧师训练师珊达所派发的。",al={"谁派发了这枚符记","珊达牧师信物"}},{q="我应该把符记带到哪里？",a="将符记带给位于泰达希尔幽影谷中心奥达希尔内的珊达。阅读过后，将此信物呈交给她，即完成了你对牧师导师的初步报到。",al={"我在哪里上交神圣符记","神圣符记交付"}}},fp="14,133,27.414.0,27.154.0,29.105.0,30.183.0"}
P.entries["item:hallowed-tablet"] = {n="神圣石板",s="神圣石板是送给在试炼谷受训的暗矛巨魔新手牧师的铭文信息。它由精神导师肯杰派人送达，要求新手去寻找他，并开始学习如何与灵魂沟通。",h="神圣石板是送给在试炼谷受训的暗矛巨魔新手牧师的铭文信息。它由精神导师肯杰派人送达，要求新手去寻找他，并开始学习如何与灵魂沟通。",kw={"暗矛","杜隆塔尔","高内克","神圣石板","肯杰","巨魔牧师","试炼谷"},ang={["class:Priest"]="这块石板标志着一名牧师在杜隆塔尔正式训练的开始，确立了他们与职业导师肯杰之间的纽带。",["race:Troll"]="对于暗矛巨魔来说，牧师之道是与灵魂和洛阿神的亲密交流，这使得石板上铭刻的召唤成为进入祖先精神传统的邀请。"},sec={{t="来自灵魂的召唤",b="当一位有前途的巨魔牧师在试炼谷那严酷的深红色峡谷中迈出第一步时，高内克会将神圣石板交到他们手中。与其说这是一份正式的官文，不如说它是肯杰——居住在大兽穴外面的驻地牧师训练师——发出的个人邀请。肯杰解读灵魂的迹象和低语，感知何时会有具备灵魂潜力的年轻暗矛巨魔到达杜隆塔尔。石板指示新手阅读其上的文字，并前往接受指导，学习如何正确引导灵魂之力。"}},faq={{q="什么是神圣石板？",a="这是一块铭文石板，由高内克在试炼谷转交给巨魔新手牧师。它包含了一条指示新手前往寻找他们的职业训练师肯杰的信息。",al={"该物品是什么","神圣石板背景知识","石板有什么用"}},{q="谁发送了这块石板？",a="石板由居住在大兽穴外的牧师训练师肯杰发送。灵魂预言了一名新助祭的到来，促使他通过高内克传达消息。",al={"谁写的","谁给我的","石板作者"}},{q="为什么巨魔牧师需要见肯杰？",a="暗矛牧师依靠与灵魂沟通并驾驭灵魂。随着新手与灵魂的联系加深，肯杰会引导他们，确保灵魂乐于传授更强大的能力。",al={"肯杰做什么","为什么要见肯杰"}}},fp="15,147,26.442.0,28.143.0,20.154.0,41.186.0"}
P.entries["item:hand-of-dextren-ward"] = {n="迪克斯特·瓦德的手掌",s="迪克斯特·瓦德的手掌是从一名被关押在暴风城监狱里的死刑犯——一名盗墓贼身上砍下的战利品。这只手被送往夜色镇，用以证明那些亵渎了镇上亡者的人终于受到了边境正义的制裁。",h="迪克斯特·瓦德的手掌是从一名被关押在暴风城监狱里的死刑犯——一名盗墓贼身上砍下的战利品。这只手被送往夜色镇，用以证明那些亵渎了镇上亡者的人终于受到了边境正义的制裁。",kw={"夜色镇","迪克斯特·瓦德","暮色森林","ebonlocke","迪克斯特·瓦德的手掌","house of nobles","米尔斯迪普","morbent fel","监狱"},ang={["class:Mage"]="瓦德并不是施法者，但他挖掘出的尸体助长了死灵法师Morbent Fel的邪恶法术，因此他的死是对那些与死者交易的人的一次打击。",["faction:Alliance"]="关于瓦德监禁问题的摩擦暴露了暴风城遥远的House of Nobles与暮色森林被遗弃的边境定居者之间深深的裂痕。"},sec={{t="亵渎者的代价",b="迪克斯特·瓦德在暮色森林的墓地挖掘尸体并将其出售给死灵法师Morbent Fel，因此被Lord Ebonlocke判处死刑。在镇民执行处决之前，暴风城介入并将罪犯抓走投入了监狱。对于悲痛中的夜色镇家庭来说，迪克斯特·瓦德的手掌是一个实实在在的证明，表明这个亵渎者终于得到了他应得的惩罚，绕过了House of Nobles令人不满的宽大处理。"},{t="给贵族们的信息",b="除了满足当地的复仇心理外，要求获得瓦德的断手也是议员米尔斯迪普向王权表达反抗的一种方式。暮色森林感到被暴风城的精英们抛弃了，他们既不提供军事援助，又在对自己有利时行使权威。在首都最深的地牢里处决一名囚犯并索要他的断手，是一种直截了当的提醒，表明当House of Nobles辜负了夜色镇时，夜色镇议会将自行执行法律。"}},faq={{q="迪克斯特·瓦德是谁？",a="迪克斯特·瓦德是一名罪犯，他被发现从夜色镇的墓地中挖掘尸体，并将其出售给邪恶的死灵法师Morbent Fel。尽管他在暮色森林被判处斩首，但暴风城当局将他转移到了监狱，而不是执行死刑。",al={"迪克斯特·瓦德背景故事","迪克斯特·瓦德是谁","瓦德的罪行"}},{q="为什么夜色镇想要他的手？",a="议员米尔斯迪普要求获得瓦德的断手，作为他被处决的无可辩驳的证据。这为那些祖先坟墓被洗劫的家庭带来了慰藉，也向腐败的House of Nobles传达了一个反抗的信息：夜色镇的正义不容逾越。",al={"为什么要断手","为什么要砍掉瓦德的手","米尔斯迪普的证据"}},{q="迪克斯特·瓦德的手掌在哪里可以找到？",a="这只手直接从迪克斯特·瓦德本人身上获取。他被关押在暴风城监狱左侧的深处牢房里，他以战士的身份战斗，并会发出令敌人逃跑的恐惧吼叫。",al={"去哪里找瓦德","监狱里的瓦德位置","迪克斯特·瓦德的位置"}},{q="为什么暴风城要把瓦德关起来而不是处决他？",a="House of Nobles声称对瓦德拥有管辖权，并选择将他关押在监狱中，而不是允许夜色镇执行死刑。夜色镇的领导层认为此举是腐败的官僚干预，是对这座边境城镇困境的不尊重。",al={"为什么瓦德没被处决","暴风城house of nobles与瓦德","瓦德被监禁"}}},fx={["48b9455f"]={q="什么是迪克斯特·瓦德的手掌？",a="这是臭名昭著的盗墓者、亵渎死者之人迪克斯特·瓦德被砍下的手。他因将暮色森林墓地里的尸体卖给死灵法师莫本特·费尔而被捕。它是他在暴风城监狱内遭到暗杀的实物证据，也残酷地证明了伊伯洛克勋爵的死刑判决终于得到了执行。",al={"什么是迪克斯特·瓦德的手掌","迪克斯特·瓦德的手掌物品","迪克斯特·瓦德的手"}},b59a9a35={q="迪克斯特·瓦德的手掌从何而来？",a="这是你在暴风城监狱的牢房中亲手从迪克斯特·瓦德身上砍下的手掌。它并非锻造或制作而成，而是作为无可辩驳的正义战利品，送还给暮色森林的议员米尔斯迪普。",al={"迪克斯特·瓦德的手掌从何而来","谁制造了迪克斯特·瓦德的手掌","迪克斯特·瓦德的手掌来源"}}},fp="20,176,16.381.0,23.383.1,21.246.0,33.229.0,40.189.0,57.245.0"}
P.entries["item:handful-of-oats-classic"] = {n="Handful of Oats (Classic)",s="一捧燕麦是人们从西部荒野被遗弃的农场里寻得的简单谷物。它们是老布兰契这类劳役牲畜的重要饲料，这些牲畜在难民迁徙的沉重负担下步履维艰。",h="一捧燕麦是人们从西部荒野被遗弃的农场里寻得的简单谷物。它们是老布兰契这类劳役牲畜的重要饲料，这些牲畜在难民迁徙的沉重负担下步履维艰。",kw={"blanchy","弗罗尔布鲁","谷物","一捧燕麦","燕麦","燕麦麻袋","西部荒野"},ang={["faction:Alliance"]="对于途经西部荒野的联盟旅行者来说，搜集燕麦去帮助弗罗尔布鲁一家这样的受困难民，是在暴风城被遗忘的边境地区中一种微小的仁慈之举。"},sec={{t="废墟间的草料",b="西部荒野曾是暴风城王国的粮仓，但如今这里广阔的农田要么荒草丛生，要么已被迪菲亚潜行者和失控的收割傀儡所占据。尽管秩序已然崩塌，但谷仓、牲口棚和荒废的田地附近仍留有一些未被收割的谷物和燕麦。对于因货车损坏而滞留在尘土飞扬的道路上的旅行者和难民来说，收集这些残余的一捧燕麦是为疲惫的驮马提供营养的少数途径之一。"}},faq={{q="一捧燕麦有什么用？",a="它们被收集起来喂给老布兰契，这是一匹属于弗罗尔布鲁家族的疲惫母马。在他们的马车于西部荒野的道路上损坏后，它已精疲力竭，急需食物补给。",al={"燕麦的用途","为什么要收集燕麦","一捧燕麦的使用方法"}},{q="在哪里可以找到这些燕麦？",a="一捧燕麦可以从散落在西部荒野各地废弃农场周围的麻袋中获取，特别是在西南部地区。",al={"哪里可以找到燕麦","燕麦麻袋的位置","如何获得燕麦"}},{q="为什么这些燕麦麻袋无人看管？",a="迪菲亚潜行者的突然崛起和失控的收割机械的肆虐，迫使当地农民仓促逃离家园，将收割好的谷物和物资留在了田地和谷仓里。",al={"为什么麻袋会被遗弃","谁留下了燕麦"}}},fp="25,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="一份星尘",s="一份星尘是收集自灰谷南部荒野闪烁灌木丛上的一种闪亮霜状涂层。这种粉末源自古老的星尘废墟，具有冷却的天然属性，深受治疗高烧的暗夜精灵治疗者们的青睐。",h="一份星尘是收集自灰谷南部荒野闪烁灌木丛上的一种闪亮霜状涂层。这种粉末源自古老的星尘废墟，具有冷却的天然属性，深受治疗高烧的暗夜精灵治疗者们的青睐。",kw={"灰谷","阿斯特兰纳","奥雷迪尔","皮尔图拉斯","泥敷剂","蕾拉娜","星尘废墟","星尘"},ang={["profession:Herbalism"]="虽然它不是作为正式的植物试剂被收集，而是直接从闪烁的灌木丛中手工采摘，但星尘体现了暗夜精灵对罕见区域植物群在修复医学上的依赖。",["race:NightElf"]="对于保卫灰谷的卡多雷来说，获取像星尘这样的当地疗法，反映了他们古老的废墟与草药传统之间持久的和谐。"},sec={{t="一种冷却草药疗法",b="星尘表现为一种细小、发光的霜，附着在阿斯特兰纳以南古老的星尘废墟内的多叶灌木上。虽然废墟本身受徘徊的元素之灵困扰，但生长在断壁残垣间的植被吸收了一种罕见的环境发光。传统的暗夜精灵医学会利用这种霜状残留物，将其加工成泥敷剂，在普通药膏和月井之水无法彻底缓解症状时，用于驱散持续且危险的高烧。"},{t="一位父亲的希望",b="阿斯特兰纳的一位焦虑的父亲皮尔图拉斯·怀特姆恩，在草药师奥雷迪尔·阔叶的建议下寻找这种粉末。皮尔图拉斯年幼的女儿蕾拉娜受到顽固的魔法疾病和噩梦的折磨。虽然从一块受艾露恩祝福的石头上得到的初步祝福平复了她的心智，但强烈的身体发烧依然存在，促使他寻找星尘来调制一种冷却药膏以挽救孩子的生命。"}},faq={{q="在哪里可以找到一份星尘？",a="它收集自遍布星尘废墟的闪光灌木丛，这些灌木丛生长在灰谷中部阿斯特兰纳暗夜精灵定居点以南。",al={"星尘位置","在哪里找到星尘","布满星尘的灌木丛"}},{q="这种星尘有什么用途？",a="阿斯特兰纳的皮尔图拉斯·怀特姆恩使用这种粉末来准备一种舒缓的泥敷剂，旨在退去折磨他生病女儿蕾拉娜的持续高烧。",al={"星尘用途","皮尔图拉斯的疗法","星尘目的"}},{q="星尘灌木周围有什么危险？",a="星尘废墟中居住着敌对的水元素，它们潜伏在海岸线附近以及灌木生长的古老倒塌石柱之间。",al={"星尘废墟的敌人","星尘废墟的怪物"}},{q="星尘与女神艾露恩有关吗？",a="虽然暗夜精灵崇敬天界力量，且废墟拥有一个星辰般的名字，但星尘主要作为一种物理药用成分，因其冰霜和冷却的特性而被草药师推荐。",al={"星尘是魔法吗","星尘与艾露恩的联系"}}},fx={["8cce1335"]={q="什么是一份星尘？",a="一份星尘是从灰谷古老的星尘废墟中闪闪发亮的枝叶上采集的、泛着微光的霜状粉末。这种稀有的植物残留物具有舒缓、神奇的冷却特性，因此是制作强效草药膏、治疗顽固且危及生命的高烧的珍贵材料。",al={"什么是一份星尘","星尘是什么","星尘物品背景"}}},fp="19,139,23.383.0,15.368.1,39.114.0,31.116.0,42.126.0,41.160.0"}
P.entries["item:hardened-tortoise-shell"] = {n="硬化龟壳",s="硬化龟壳是从游荡在闪光平原的闪光壳龟身上采集到的极耐用的甲壳。这些粗糙的有机甲片备受沙漠赛道的侏儒赛车手们垂青，能够为极易挥发和具有腐蚀性的实验燃料提供无与伦比的抗性。",h="硬化龟壳是从游荡在闪光平原的闪光壳龟身上采集到的极耐用的甲壳。这些粗糙的有机甲片备受沙漠赛道的侏儒赛车手们垂青，能够为极易挥发和具有腐蚀性的实验燃料提供无与伦比的抗性。",kw={"硬化龟壳","沙漠赛道","火箭赛车","闪光平原","闪光壳龟","维兹尔·铜栓"},ang={["profession:Engineering"]="使用有机甲壳作为高压燃料箱虽然不走寻常路，但当侏儒酿造的燃料融化了标准合金管道时，高耐久度的天然材料往往就能派上用场。",["race:Gnome"]="只有侏儒的奇思妙想才会看到一只沙漠乌龟，就立刻想到用它来制作一种轻便且极具韧性的危险火箭燃料容器。"},sec={{t="应对高速危险的天然护甲",b="被烈日灼烤的闪光平原广袤大地是各种闪光壳龟的家园，包括咬龟和钻龟。它们的甲壳已经进化出了极其坚韧的防御能力，以抵御严酷的沙漠盐碱和四处游荡的掠食者。在盐碱地上，普通的金属合金油箱经常因侏儒实验化学制品的压力而腐蚀或破裂。像维兹尔·铜栓这样的技师重视这些甲壳，并非为了制作护甲或盾牌，而是将其作为一种坚韧的有机原材料，经过改造后制成临时的耐酸燃料箱，用来盛装极易挥发的火箭推进剂。"}},faq={{q="在哪里可以找到硬化龟壳？",a="它们是从游荡在千针石林的闪光平原开阔盐碱地上的闪光壳龟身上采集的——具体来说，是闪光壳咬龟、闪光壳钻龟和普通的闪光壳龟。",al={"哪里获取龟壳","硬化甲壳位置","闪光壳龟位置"}},{q="为什么维兹尔·铜栓需要这些甲壳？",a="维兹尔的兄弟正在设计一种威力极强且具有腐蚀性的火箭燃料，这种燃料有可能会直接融穿赛车的底盘。维兹尔打算掏空并加固这些极其耐用的龟壳，将其用作耐化学腐蚀的燃料箱。",al={"为什么需要甲壳","维兹尔的甲壳用途","甲壳有什么用"}},{q="普通的车间工具能轻易加工它们吗？",a="不能。这些甲壳的硬度高得不合常理，侏儒技师们预料在尝试切割、钻孔和将其加工成油箱的过程中，会弄坏整整一工具箱的金属器具。",al={"甲壳难加工吗","损坏工具的甲壳"}}},fx={cc86b908={q="什么是硬化龟壳？",a="这是从盐碱地上游荡的大型闪壳龟身上取得的、极其坚韧的天然外甲。这种龟壳远比普通野兽皮革或常规护甲坚硬，能够抵御摩擦、盐分和强烈的化学侵蚀。",al={"什么是硬化龟壳","硬化龟壳物品","硬化龟壳"}},["4ed6fee7"]={q="硬化龟壳来自哪里？",a="这些龟壳完全是天然形成的，并非人工制造。它们直接取自千针石林闪光平原上那些在严酷、烈日炙烤的盐碱荒地中繁衍生息的闪壳龟、钳嘴龟和钻地龟。",al={"硬化龟壳的来源","谁制作了硬化龟壳","硬化龟壳来自哪里"}}},fp="23,286,36.617.0,43.212.0,45.273.0,46.188.0"}
P.entries["item:hardened-tumor"] = {n="硬瘤",s="硬瘤是一种罕见的生物异常，采集自生活在洛丹米尔湖周围的邪鳍鱼人身上。最初是在药剂师贝拉德（现已成为阿鲁加的无脑仆从）的研究中被记录下来的，这种钙化的生长物在皇家药剂师学会酿造新瘟疫的过程中被用作一种不同寻常的试剂。",h="硬瘤是一种罕见的生物异常，采集自生活在洛丹米尔湖周围的邪鳍鱼人身上。最初是在药剂师贝拉德（现已成为阿鲁加的无脑仆从）的研究中被记录下来的，这种钙化的生长物在皇家药剂师学会酿造新瘟疫的过程中被用作一种不同寻常的试剂。",kw={"药剂师法拉尼尔","药剂师伦弗利尔","贝拉德","黎明岛","硬瘤","洛丹米尔湖","鱼人","新瘟疫","邪鳍"},ang={["race:Undead"]="获取这种肿瘤可以推进大药剂师法拉尼尔对新瘟疫的重要研究，为希尔瓦娜斯女王和被遗忘者对抗生者与亡者敌人的斗争提供帮助。"},sec={{t="一种罕见的生物异常",b="在研究银松森林东部边界的本地野生动物时，药剂师贝拉德记录了洛丹米尔湖的邪鳍鱼人体内发育的一种异常的钙化生长物。这种生长物极其罕见，仅在湖岸线和黎明岛的成年个体身上出现。邪鳍鱼人为何会产生这些硬块尚不确定，但其致密且病态的组织立即引起了皇家药剂师学会的注意。"},{t="新瘟疫的燃料",b="在阿鲁高的诅咒使贝拉德沦为无脑仆从后，他的日志在焚木村被寻回，并被送交至瑟伯切尔的药剂师伦弗利尔手中。伦弗利尔意识到贝拉德研究中的潜力，便指派被遗忘者特工去搜集硬瘤以及当地的水生苔藓。大药剂师法拉尼尔负责幽暗城的药剂区，他一直在寻找能够抵抗腐烂或改变生物物质的试剂。他将这种奇特的生长物直接纳入了学会正在进行的新瘟疫配制工作中。"}},faq={{q="什么是硬瘤？",a="这是一种异常的钙化肿块，很少在生活于洛丹米尔湖周围的邪鳍鱼人体内形成。它由被遗忘者研究员药剂师贝拉德发现，能够抵抗正常的物理降解，并具有独特的生物特性。",al={"什么是硬瘤","硬瘤背景","硬瘤掉落"}},{q="为什么皇家药剂师学会想要它？",a="大药剂师法拉尼尔和皇家药剂师学会正在搜集不寻常的毒性和生物样本以合成新瘟疫。这种肿瘤的异常弹性和细胞组成使其成为他们枯萎实验的主要候选材料。",al={"为什么药剂师需要硬瘤","死亡肿瘤配方用途","法拉尼尔与硬瘤"}},{q="这些肿瘤在哪里可以找到？",a="它们是从银松森林的邪鳍鱼人身上获取的，特别是那些栖息在洛丹米尔湖东部的黎明岛以及安伯米尔东北部村庄沿岸的鱼人。",al={"硬瘤在哪里寻找","哪种鱼人掉落硬瘤","硬瘤位置"}},{q="药剂师贝拉德是谁？",a="贝拉德是皇家药剂师学会的一名驻扎在银松森林的药剂师。在阿鲁高的诅咒使他沦为焚木村的一名无脑仆从之前，他编制了关于当地动植物和鱼人突变的详细研究，揭示了黎明岛苔藓和硬瘤的用途。",al={"谁是贝拉德","贝拉德背景","贝拉德的日志"}}},fp="14,170,25.374.0,23.486.1,25.220.0,46.215.0,29.175.0,26.291.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="鹰身人首领之戒",s="鹰身人首领之戒是贫瘠之地北部无水岭的巫翼杀手所佩戴的粗糙饰品。作为鸟群中指挥权的象征，它们被用来向十字路口的达索克·快刀证明目标已被击杀。",h="鹰身人首领之戒是贫瘠之地北部无水岭的巫翼杀手所佩戴的粗糙饰品。作为鸟群中指挥权的象征，它们被用来向十字路口的达索克·快刀证明目标已被击杀。",kw={"十字路口","达索克·快刀","无水岭","鹰身人首领之戒","贫瘠之地","巫翼","巫翼杀手"},ang={["class:Rogue"]="达索克·快刀偏好针对高价值目标的精准打击，他非常看重那些能够潜入鹰身人巢穴直接消灭指挥官的刺客。",["faction:Horde"]="巫翼鹰身人不断骚扰着杜隆塔尔、莫高雷和北部前哨站之间的补给线；瓦解她们的领导层能确保部落商队安全通过贫瘠之地。"},sec={{t="军衔徽记",b="在巫翼鹰身人的母系等级制度中，阶级维护极为残酷。虽然骚扰贫瘠之地的普通袭击者缺乏配合，但巫翼杀手作为战场上的副官，指挥着对部落旅人的突袭。为了彰显身份并确立对下属的权威，这些老练的杀手佩戴着独特的戒指。对于达索克·快刀和驻守在十字路口的守卫来说，从阵亡的鹰身人身上取下这些戒指，是确认鸟群中层指挥力量已被瓦解的唯一可靠手段。"}},faq={{q="谁携带有这些戒指？",a="这些戒指专门由巫翼杀手携带，她们是无水岭巫翼鸟群中充当副官角色的老练鹰身人。",al={"谁掉落鹰身人首领之戒","巫翼杀手之戒","哪些鹰身人有戒指"}},{q="在哪里可以找到巫翼杀手？",a="巫翼杀手栖息在无水岭，那是一片位于贫瘠之地最北端、十字路口西北方向的崎岖高地。",al={"巫翼杀手位置","鹰身人副官在哪里","无水岭鹰身人"}},{q="为什么达索克·快刀需要它们？",a="达索克想要瓦解鹰身人的指挥结构。消灭这些副官会让她们的突袭小队陷入混乱，以此惩罚鸟群掠夺贫瘠之地各处部落商队和旅人的行径。",al={"为什么要收集鹰身人戒指","达索克·快刀戒指"}},{q="普通的鹰身人袭击者会携带这些戒指吗？",a="不会。普通的袭击者只是低阶下属。戒指象征着指挥权，只有巫翼杀手才会佩戴。",al={"袭击者会掉落戒指吗","巫翼袭击者有戒指吗"}}},fp="21,160,14.357.0,24.91.0,37.94.0,38.129.0,43.100.0"}
P.entries["item:head-of-arugal"] = {n="阿鲁高的头颅",s="阿鲁高的头颅是从影牙城堡顶端那名疯狂大法师身上取下的令人毛骨悚然的战利品。将其带给瑟伯切尔的被遗忘者，是当地狼人主人已经倒下的确凿证据。",h="阿鲁高的头颅是从影牙城堡顶端那名疯狂大法师身上取下的令人毛骨悚然的战利品。将其带给瑟伯切尔的被遗忘者，是当地狼人主人已经倒下的确凿证据。",kw={"阿鲁高","阿鲁高必须死","达拉尔·道恩维沃尔","阿鲁高的头颅","瑟伯切尔","影牙城堡","银松森林"},ang={["class:Mage"]="一颗前肯瑞托大法师被砍下的头颅，作为一个严酷的警告，提醒人们即使是有天赋的施法者，如果进行失去控制且不计后果的召唤，也会导致疯狂和毁灭。",["race:Undead"]="对于被遗忘者来说，送交阿鲁高的头颅消除了他们南部门户上的一位反复无常的巫师，从而为黑暗女王确保了银松森林的安全。"},sec={{t="疯狂大法师的战利品",b="大法师阿鲁高长期在银松森林笼罩着一片黑暗的阴影，从影牙城堡的城墙上指挥着那些狼形恐怖生物。夺取他被砍下的头颅是瑟伯切尔的达拉尔·道恩维沃尔下达的终极指令。对于被遗忘者来说，这颗头颅不仅仅是一个可怕的纪念品；它象征着除掉了一位强大的施法者，正是他的野兽阻碍了希尔瓦娜斯女王对银松森林的完全统治。将其交给道恩维沃尔，证实了这位叛逃的大法师的邪恶法术终于被从这片土地上切断了。"}},faq={{q="谁需要阿鲁高的头颅？",a="驻扎在银松森林瑟伯切尔的使者达拉尔·道恩维沃尔，要求获得这颗头颅以完成任务“阿鲁高必须死”。",al={"谁需要阿鲁高的头颅","阿鲁高的头颅交任务","谁接受阿鲁高的头颅"}},{q="在哪里可以获得阿鲁高的头颅？",a="它是从大法师阿鲁高本人身上砍下来的，他就住在影牙城堡的最高点，俯瞰着焚木村和银松森林的树林。",al={"如何获得阿鲁高的头颅","阿鲁高的头颅掉落","阿鲁高的头颅在哪里"}},{q="为什么被遗忘者要杀死阿鲁高？",a="阿鲁高的存在和他率领的狼人军团阻碍了被遗忘者将银松森林变成希尔瓦娜斯女王和幽暗城的安全战略据点。",al={"为什么要杀阿鲁高","被遗忘者杀阿鲁高的原因","达拉尔为什么要杀阿鲁高"}},{q="上交头颅后会发生什么？",a="达拉尔·道恩维沃尔发誓要根除阿鲁高邪恶法术的残余，宣称银松森林终于摆脱了这位疯狂巫师的控制。",al={"阿鲁高死后","阿鲁高必须死的结果"}}},fx={c9f64370={q="什么是阿鲁高的头颅？",a="阿鲁高的头颅是大法师阿鲁高被砍下的头颅。他曾是达拉然的法师，后来陷入疯狂，并将狼人释放到银松森林。头颅取自影牙城堡，是这名疯狂的巫师终于被杀、黑暗魔法已被粉碎的确凿实物证据。",al={"什么是阿鲁高的头颅","阿鲁高的头颅物品","阿鲁高的头颅"}},["10305f38"]={q="阿鲁高的头颅来自哪里？",a="这个头颅是从影牙城堡高处的大法师阿鲁高身上取得的。攻入这座被诅咒的城堡并在战斗中击败这名疯狂的大法师后，你将他杀死并取下头颅，以确认他的死亡。",al={"在哪里能得到阿鲁高的头颅","谁会掉落阿鲁高的头颅","阿鲁高的头颅来源"}}},fp="14,157,26.355.0,29.128.0,39.145.0,37.160.0,41.147.1"}
P.entries["item:head-of-bazil-thredd"] = {n="巴基尔·斯瑞德的头颅",s="巴基尔·斯瑞德的头颅是监狱暴动主谋已被消灭的确凿证据。典狱官塞尔沃特要求获得这个残酷的战利品，以此终结迪菲亚潜行者对暴风城地下监狱的有组织控制。",h="巴基尔·斯瑞德的头颅是监狱暴动主谋已被消灭的确凿证据。典狱官塞尔沃特要求获得这个残酷的战利品，以此终结迪菲亚潜行者对暴风城地下监狱的有组织控制。",kw={"巴基尔·斯瑞德","迪菲亚潜行者","巴基尔·斯瑞德的头颅","监狱","监狱暴乱","典狱官塞尔沃特"},ang={["faction:Alliance"]="上交斯瑞德的头颅平息了首都即时的恐慌，证明了国王的正义依然可以深入反叛的监狱。"},sec={{t="叛乱终结的证明",b="当暴风城下方的监狱爆发骚乱时，巴基尔·斯瑞德迅速确立了他作为叛乱主谋的地位。斯瑞德在忠诚的迪菲亚囚犯簇拥下盘踞在牢房区，并在地牢深处指挥着这场混乱。由于对外界不信任且难以维持秩序，典狱官塞尔沃特要求得到斯瑞德的头颅，作为他已死的无可辩驳的证据，同时也是对冒险者是否真正效忠于暴风城的考验。"}},faq={{q="谁需要巴基尔·斯瑞德的头颅？",a="驻守在监狱入口的典狱官塞尔沃特要求获得这个头颅。他需要这个头颅作为首领已被击杀的绝对证据，才会愿意分享关于斯瑞德同谋者的情报。",al={"谁需要斯瑞德的头颅","斯瑞德的头颅在哪交","斯瑞德的头颅任务发布者"}},{q="巴基尔·斯瑞德是谁？",a="巴基尔·斯瑞德是迪菲亚潜行者的一名高级成员，被囚禁在暴风城下方。当囚犯们起义时，他接管了骚乱，并在东侧牢房区深处指挥这场叛乱。",al={"巴基尔·斯瑞德是谁","斯瑞德背景故事","巴基尔做了什么"}},{q="巴基尔·斯瑞德在哪里？",a="巴基尔·斯瑞德位于监狱副本的东翼。他被关押在牢房区最深处的一间中央牢房里，周围有忠于他的迪菲亚囚犯守卫。",al={"斯瑞德在哪里","斯瑞德位置","如何找到巴基尔·斯瑞德"}}},fx={["4fd859a6"]={q="什么是巴基尔·斯瑞德的头颅？",a="这是巴基尔·斯瑞德被砍下的头颅。他是在监狱深处策划叛乱的囚犯。对典狱官塞尔沃特而言，呈上这件阴森的战利品，是证明监狱暴动首领已被彻底铲除的确凿实物证据。",al={"什么是巴基尔·斯瑞德的头颅","巴基尔·斯瑞德的头颅物品","巴基尔·斯瑞德的头颅"}},fe91a8a0={q="巴基尔·斯瑞德的头颅来自哪里？",a="你在暴风城监狱的囚室中与巴基尔·斯瑞德交锋并将他杀死后，可直接从他身上取得头颅。他在那里指挥暴动，并由凶悍的守卫保护。",al={"在哪里能得到巴基尔·斯瑞德的头颅","如何获得巴基尔·斯瑞德的头颅","巴基尔·斯瑞德头颅的来源"}}},fp="20,213,22.333.0,35.173.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="卡姆·深怒的头颅",s="卡姆·深怒的头颅是那名幕后破坏萨多尔大桥的黑铁阴谋家已经伏法的冷酷证明。他在暴风城监狱的暴乱中被杀，他的死让丹莫德的矮人守卫们得以了结一桩私人恩怨。",h="卡姆·深怒的头颅是那名幕后破坏萨多尔大桥的黑铁阴谋家已经伏法的冷酷证明。他在暴风城监狱的暴乱中被杀，他的死让丹莫德的矮人守卫们得以了结一桩私人恩怨。",kw={"深怒","丹莫德","卡姆·深怒的头颅","卡姆·深怒","长须","莫特雷·加玛森","监狱","萨多尔大桥"},ang={["faction:Alliance"]="这笔悬赏展示了联盟内部日益增长的摩擦，对比了暴风城人类在法律上的谨慎与铁炉堡山地巡逻队员所要求的严酷边境正义。",["race:Dwarf"]="对于铁炉堡的矮人来说，取下深怒的首级是纯粹的氏族正义，用以清算黑铁矮人在萨多尔大桥犯下的血债。"},sec={{t="阴谋家的审判",b="卡姆·深怒因政治原因被逮捕并关押在暴风城监狱中，由于人类外交官僚体系的阻挠，他没有被立即处决。对于驻扎在丹莫德的铁炉堡山地巡逻队员来说，这种束缚令人无法接受。罗格发现的情报显示，深怒策划了针对萨多尔大桥的毁灭性袭击，这场袭击导致了麦格尼国王的士兵以及布莱德·长须的亲属丧生。由于职责在身无法离开岗位，莫特雷·加玛森委托联盟的勇士们潜入发生暴乱的监狱，取下深怒的首级，确保矮人的复仇能够在人类外交手段失效的地方得以实现。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是一名奸诈的黑铁矮人，他参与策划了针对萨多尔大桥的破坏行动。萨多尔大桥是连接湿地与阿拉希高地的关键陆路桥梁。他的阴谋导致了包括布莱德·长须的兄弟在内的多名矮人守卫丧生。",al={"卡姆·深怒背景故事","深怒是谁","卡姆·深怒的故事"}},{q="为什么卡姆·深怒被关在监狱里而不是被处决？",a="深怒因政治原因被暴风城的当局活捉并关押。虽然人类官僚对让他烂在牢房里的处理方式感到满意，但铁炉堡的山地巡逻队员们却认为这种宽容简直是无法无天的暴行，并要求以血还血。",al={"为什么深怒会被监禁","为什么是监狱"}},{q="谁想要卡姆·深怒的头颅？",a="驻扎在北湿地丹莫德的矮人莫特雷·加玛森要求得到这颗头颅。由于誓言在身，必须守在布莱德·长须身边的他无法离开岗位，因此莫特雷派遣了一位冒险者去完成他自己无法做到的事情。",al={"谁想要深怒的头颅","深怒的伏诛任务交接"}},{q="带回这颗头颅有什么意义？",a="呈上深怒的断头为丹莫德哀痛的矮人家庭带来了慰藉与公正。这不仅为布莱德·长须死去的兄弟报了仇，也证明了针对铁炉堡的罪行绝不会被掩埋在人类的政治博弈之下。",al={"为什么要带回深怒的头颅","深怒的伏诛结果"}}},fx={["42407f6f"]={q="什么是卡姆·深怒的头颅？",a="这是卡姆·深怒被砍下的头颅。他是一名被关押在暴风城监狱深处的黑铁矮人。你带回它，作为确凿无疑的实物证据，证明萨多尔大桥惨烈袭击的幕后阴谋者终于受到了惩罚。",al={"卡姆·深怒的头颅","什么是卡姆·深怒的头颅"}},ff6e9a29={q="卡姆·深怒的头颅来自哪里？",a="这个头颅是从暴风城地下监狱牢房中的卡姆·深怒身上直接取得的。虽然人类当局只是将他关押起来，并未处决他，但你必须在牢房中将他杀死才能取回头颅。",al={"在哪里能得到卡姆·深怒的头颅","谁会掉落卡姆·深怒的头颅","卡姆·深怒头颅的来源"}}},fp="16,188,23.500.0,21.240.0,57.148.0,31.183.0,44.233.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="加塞尔佐格的头颅",s="加塞尔佐格的头颅是黑石军阀已被击杀的无可辩驳的证明。取得它能够摧毁石堡要塞围攻背后的指挥体系，并为湖畔镇带来迫切的喘息之机。",h="加塞尔佐格的头颅是黑石军阀已被击杀的无可辩驳的证明。取得它能够摧毁石堡要塞围攻背后的指挥体系，并为湖畔镇带来迫切的喘息之机。",kw={"黑石","加塞尔佐格","湖畔镇","所罗门镇长","赤脊山","石堡","石堡要塞"},ang={["faction:Alliance"]="由于首都正忙于内部纷争，联盟的志愿者们必须肩负起保卫赤脊山并亲自击杀黑石领袖的重任。",["race:Human"]="对于暴风城的人民来说，除掉加塞尔佐格不仅是为了报复无辜定居者遭受的屠杀，也是为了洗刷石堡要塞沦陷的耻辱。"},sec={{t="悬赏的军阀",b="加塞尔佐格策划了残酷的黑石突袭，占领了石堡要塞，驱逐了守军，并让周边山谷遭受了无情的劫掠。在湖畔镇濒临毁灭、而暴风城几乎无法提供军事增援的情况下，所罗门镇长悬赏了这名军阀的项上人头。在石堡的防守严密的上层击杀加塞尔佐格并取得他的头颅，能够粉碎当地黑石势力的领导层，标志着为王国收复该要塞迈出了真正的第一步。"}},faq={{q="加塞尔佐格是谁？",a="加塞尔佐格是一位强大的黑石兽人军阀，他领导了对石堡要塞的征服，并指挥了针对赤脊山定居点的劫掠，将湖畔镇推向了崩溃的边缘。",al={"加塞尔佐格是谁","加塞尔佐格背景故事","石堡首领"}},{q="头颅拿到后要送往哪里？",a="头颅被直接送往湖畔镇市政厅的所罗门镇长处，作为在镇上通缉布告栏上发布的悬赏已完成的凭证。",al={"谁想要这个头颅","加塞尔佐格的头颅交还","所罗门镇长悬赏"}},{q="加塞尔佐格的死对湖畔镇意味着什么？",a="他的死剥夺了黑石入侵者在赤脊山的主要战术指挥。虽然许多黑石兽人仍然固守在石堡各处，但切断他们的指挥链让当地守军有了坚守该地区的一线生机。",al={"湖畔镇会获救吗","击杀加塞尔佐格的意义"}},{q="加塞尔佐格在哪里被发现？",a="他盘踞在石堡要塞的高处，与他的私人保镖和副官们一起躲在这座被占领的堡垒深处。",al={"加塞尔佐格在哪里","石堡要塞位置"}}},fx={["0b5a65b1"]={q="什么是加塞尔佐格的头颅？",a="这是加塞尔佐格被砍下的头颅。他是黑石兽人督军，曾指挥对石堡要塞的袭击，并组织威胁湖畔镇的劫掠。砍下他的头颅，便能确凿证明在赤脊山策划黑石兽人攻势的残暴首领终于被铲除。",al={"什么是加塞尔佐格的头颅","加塞尔佐格的头颅"}},ca6d6fe9={q="加塞尔佐格的头颅来自哪里？",a="加塞尔佐格在石堡要塞高处被杀后，你可直接从他身上取得头颅。这名督军盘踞在自己征服的要塞中，谋划着进一步侵害赤脊山居民，直到一名冒险者勇闯他的据点，将头颅作为战利品带走。",al={"加塞尔佐格的头颅来自哪里","谁取走了加塞尔佐格的头颅","加塞尔佐格头颅的来源"}},a1bebb0c={q="所罗门镇长为什么想要加塞尔佐格的头颅？",a="所罗门镇长悬赏缉拿加塞尔佐格，并要求提交其死亡的实物证据。加塞尔佐格屠杀无辜的人类，还攻占了石堡要塞。看到他的头颅被送来，湖畔镇的领袖便能确信眼前的威胁已被消除，也能为受害者讨回公道，并重燃夺回要塞的希望。",al={"所罗门为什么想要加塞尔佐格的头颅","为什么要带回加塞尔佐格的头颅","加塞尔佐格头颅的悬赏"}}},fp="19,189,18.452.0,20.188.0,39.133.0,49.230.0,28.142.0"}
P.entries["item:head-of-grimson"] = {n="格瑞姆森的头颅",s="格瑞姆森的头颅是取自格瑞姆森（苍白者）的被斩下的战利品，他是银松森林中埃利姆矿洞的腐化监工。将其带给瑟伯切尔的达拉尔·道恩维沃尔，作为矿洞领导层已被铲除的实物证据。控制该矿洞使被遗忘者能够攫取宝贵的矿产资源，为瓦里玛萨斯的军事行动提供补给。",h="格瑞姆森的头颅是取自格瑞姆森（苍白者）的被斩下的战利品，他是银松森林中埃利姆矿洞的腐化监工。将其带给瑟伯切尔的达拉尔·道恩维沃尔，作为矿洞领导层已被铲除的实物证据。控制该矿洞使被遗忘者能够攫取宝贵的矿产资源，为瓦里玛萨斯...",kw={"阿鲁高","达拉尔·道恩维沃尔","埃利姆矿洞","格瑞姆森（苍白者）","格瑞姆森的头颅","瑟伯切尔","银松森林","瓦里玛萨斯"},ang={["profession:Mining"]="埃利姆矿洞是银松森林的主要矿产点之一，如今其疯狂的监工已被铲除，原矿得以源源不断地输送至部落的补给线。",["race:Undead"]="夺取矿洞实现了幽暗城高层的战略要求，证明了被遗忘者将洛丹伦的重要基础设施从疯狂残部手中夺回的决心。"},sec={{t="控制埃利姆矿洞",b="当达拉尔·道恩维沃尔在瑟伯切尔的安全处研究大法师阿鲁高的暗影附魔时，被称为黑暗巡游者的被遗忘者侦察兵在东南面的山丘中发现了一股正在酝酿的战略威胁。阿鲁高的黑暗魔法渗入了埃利姆矿洞，腐化了那里的矿工，并驱使监工格瑞姆森（苍白者）陷入疯狂。为了将地下的财富据为瓦里玛萨斯的部队所用，道恩维沃尔派遣勇士去斩杀格瑞姆森，并带回他的头颅，作为矿洞已从邪恶魔法中解放的无可辩驳的证明。"},{t="给恐惧魔王的战利品",b="对于被遗忘者而言，残酷的战争战利品具有实际价值。夺取格瑞姆森的头颅可以确保埃利姆矿洞中的地下劳动力完全崩溃，终结他们对阿鲁高扭曲统治的任何残留忠诚。随着格瑞姆森被铲除，矿洞内丰富的矿脉便可开采，并重铸为武器和盔甲，从而支持被遗忘者在银松森林及洛丹伦邻近地区持续推进战线。"}},faq={{q="格瑞姆森（苍白者）是谁？",a="格瑞姆森（苍白者）是位于银松森林东南山丘中埃利姆矿洞的监工。由于暴露在大法师阿鲁高不断蔓延的暗影魔法之下，格瑞姆森和他的矿工同伴受到其黑暗力量的驱使，在被遗忘者介入之前，将矿洞变成了一个腐化的据点。",al={"格瑞姆森是谁","格瑞姆森（苍白者）背景故事","格瑞姆森的背景"}},{q="为什么达拉尔·道恩维沃尔需要格瑞姆森的头颅？",a="达拉尔·道恩维沃尔需要切实的证据来证明腐化的监工已被永久消灭。瓦里玛萨斯需要埃利姆矿洞的矿产财富来支持被遗忘者的战争，而杀死格瑞姆森可以打破占据矿道的腐化矿工们的抵抗。",al={"为什么达拉尔想要头颅","格瑞姆森的头颅的作用","为什么要拿走头颅"}},{q="埃利姆矿洞位于何处？",a="埃利姆矿洞位于银松森林中瑟伯切尔东南方的山丘里。它是一个重要的矿产资源点，被遗忘者与受到阿鲁高魔法控制的腐化残部在此进行争夺。",al={"埃利姆矿洞在哪里","格瑞姆森的位置","银松森林的矿洞位置"}},{q="瓦里玛萨斯在这个任务中扮演什么角色？",a="瓦里玛萨斯作为军事指挥官，在幽暗城指挥被遗忘者在洛丹伦全境的扩张。控制埃利姆矿洞的资源直接服务于他的战略目标，为他在银松森林不断壮大的战争机器提供原材料。",al={"瓦里玛萨斯的角色","为什么瓦里玛萨斯想要矿洞","瓦里玛萨斯与银松森林"}}},fp="15,223,27.437.0,26.284.1,25.197.0,46.244.0,36.162.0,45.183.0"}
P.entries["item:head-of-kelris"] = {n="克尔里斯的头颅",s="梦游者克尔里斯被斩下的头颅是黑暗深渊中暮光之锤领袖已经伏法的确凿证据。这颗头颅被从腐化的神庙废墟中带出，银色黎明的代表们急于得到它，以确认他那亵渎的献祭仪式的终结。",h="梦游者克尔里斯被斩下的头颅是黑暗深渊中暮光之锤领袖已经伏法的确凿证据。这颗头颅被从腐化的神庙废墟中带出，银色黎明的代表们急于得到它，以确认他那亵渎的献祭仪式的终结。",kw={"阿库麦尔","银色黎明","巴珊娜·符文图腾","黑暗深渊","黑暗深渊的邪恶","克尔里斯的头颅","塞尔高姆","梦游者克尔里斯"},ang={["faction:Alliance"]="将克尔里斯的头颅交给达纳苏斯的哨兵塞尔高姆，旨在为那座供奉艾露恩的古老暗夜精灵神庙遭受的亵渎复仇。",["faction:Horde"]="将头颅呈交给雷霆崖的巴珊娜·符文图腾可以赢得塞纳里奥议会的信任，证明他们致力于净化卡利姆多的腐化。"},sec={{t="毁灭的战利品",b="在艾露恩神庙被淹没的深处，梦游者克尔里斯策划了向阿库麦尔——一位上古之神的恐怖仆从——进行的黑暗献祭。带回他的头颅标志着他在黑暗深渊中对暮光之锤教徒及其纳迦盟友的残暴统治宣告终结。这份令人毛骨悚然的战利品必须被带回地表的文明社会，向领袖们证明克尔里斯的血腥仪式终于停止了。"},{t="银色黎明的证据",b="几个月来，银色黎明一直认为克尔里斯已死或失踪，没想到他那邪恶的影响力伴随着卡利姆多不断逼近的阴影再次浮现。当将其呈交给达纳苏斯或雷霆崖的代理人时，这颗头颅将解决遗留的悬赏，并证实他试图将世界重新拖入原始混乱的企图已被挫败。"}},faq={{q="谁是梦游者克尔里斯？",a="克尔里斯是盘踞在黑暗深渊中的暮光之锤教派的领袖。他与纳迦结盟，策划了将无辜者献祭给上古之神的九头蛇仆从——阿库麦尔的仪式，以追求黑暗力量和远古的混乱。",al={"克尔里斯是谁","克尔里斯背景故事","梦游者克尔里斯"}},{q="谁想要克尔里斯的头颅？",a="联盟的勇士会将头颅交给达纳苏斯的哨兵塞尔高姆，而部落的冒险者则会将其带到雷霆崖长者高地的巴珊娜·符文图腾那里。哨兵塞尔高姆服务于银色黎明，而巴珊娜·符文图腾则属于塞纳里奥议会。",al={"谁接收克尔里斯的头颅","克尔里斯的头颅交任务","克尔里斯的头颅给谁"}},{q="为什么银色黎明关心克尔里斯？",a="银色黎明追踪威胁艾泽拉斯的邪恶势力。克尔里斯是一个长期逃避追捕的知名恶棍，他崇拜上古之神并献祭无辜者的行为，对卡利姆多的平衡构成了严重威胁。",al={"为什么银色黎明针对克尔里斯","银色黎明 黑暗深渊"}},{q="这颗头颅从哪里获得？",a="它是从位于灰谷佐拉姆海岸之下，黑暗深渊地下城深处的圣殿里，从梦游者克尔里斯的尸体上斩下的。",al={"在哪里获得克尔里斯的头颅","克尔里斯的头颅位置"}}},fx={c257c517={q="什么是克尔里斯的头颅？",a="这是暮光领主克尔里斯被砍下的头颅。他是深入黑暗深渊废墟扎根的暮光之锤教徒的首领。这件战利品是令人毛骨悚然且确凿无疑的证据，证明沉没神庙中的邪恶主宰已被杀死，他的仪式也已终结。",al={"克尔里斯的头颅","什么是克尔里斯的头颅","克尔里斯的头颅物品"}},["0e645b89"]={q="克尔里斯的头颅来自哪里？",a="这个头颅是从佐拉姆海岸附近黑暗深渊深处的暮光领主克尔里斯身上直接取得的。你必须杀出一条血路，突破他狂热的教徒和畸变的仆从，在他的内殿中将这位暮光领主杀死，然后才能取走头颅。",al={"在哪里能得到克尔里斯的头颅","克尔里斯头颅的来源","如何获得克尔里斯的头颅"}}},fp="14,103,16.305.0,18.300.0,29.200.0,29.231.0,43.154.0,27.137.0"}
P.entries["item:head-of-targorr"] = {n="塔格尔的头颅",s="塔格尔的头颅是卫兵伯尔顿在湖畔镇要求的残酷证据，用来确认可怕的塔格尔的死亡。这名被俘的兽人曾是赤脊山黑石氏族督军加塞尔佐格手下的首席刽子手，他曾在暴风城监狱被判死刑，但随后的政治干预叫停了处决。",h="塔格尔的头颅是卫兵伯尔顿在湖畔镇要求的残酷证据，用来确认可怕的塔格尔的死亡。这名被俘的兽人曾是赤脊山黑石氏族督军加塞尔佐格手下的首席刽子手，他曾在暴风城监狱被判死刑，但随后的政治干预叫停了处决。",kw={"黑石氏族","加塞尔佐格","卫兵伯尔顿","塔格尔的头颅","湖畔镇","赤脊山","监狱","塔格尔","可怕的塔格尔"},ang={["faction:Alliance"]="对于保卫赤脊山的联盟勇士来说，除掉塔格尔不仅能为被屠杀的湖畔镇守军报仇，还能绕过暴风城腐败的贵族官僚机构。",["race:Human"]="人类士兵和城镇卫兵对塔格尔怀有私人仇恨，因为他在黑石氏族进攻期间对被俘的王国军队进行了残酷的折磨。"},sec={{t="延期的处决",b="可怕的塔格尔在赤脊山臭名昭著，曾是黑石氏族督军加塞尔佐格手下残酷的刽子手。塔格尔曾负责拷问和屠杀暴风王国的守军，最终被俘并被判处死刑，关押在暴风城监狱中。然而，暴风城贵族的官僚干预神秘地中止了这一判决，这让伯尔顿等当地卫兵怀疑首都存在猫腻和腐败。"},{t="边境正义",b="卫兵伯尔顿担心塔格尔会被当作政治筹码，或者策划某种越狱，于是委派了一名外部勇士潜入那座动荡的监狱，去完成法庭所推迟的处决。砍下塔格尔的头颅彻底绕过了瘫痪的法律体系，让那些在刽子手刀下受苦的湖畔镇受难家庭和被围困的守军得到了解脱。"}},faq={{q="谁是可怕的塔格尔？",a="塔格尔是赤脊山黑石氏族中臭名昭著的兽人刽子手。他曾效力于督军加塞尔佐格，因拷问并处决被俘的暴风城士兵和守军而臭名昭著。",al={"塔格尔","塔格尔背景故事","谁是塔格尔"}},{q="为什么塔格尔在监狱里被留了活口？",a="虽然塔格尔被正式判处死刑，但他的处决却被暴风城的官僚贵族神秘地叫停了。湖畔镇的卫兵怀疑其中存在政治猫腻和腐败，担心这名兽人被留作筹码。",al={"为什么没有处决塔格尔","塔格尔延期处决","监狱审判"}},{q="谁想要塔格尔的头颅？",a="驻扎在Lakeshire Inn外的卫兵伯尔顿索要这颗被砍下的头颅。在目睹了塔格尔在赤脊山造成的杀戮后，伯尔顿寻求确凿的证据，确保这名刽子手永远无法被释放。",al={"谁要塔格尔的头颅","卫兵伯尔顿","提交塔格尔的头颅"}},{q="在哪里可以找到塔格尔？",a="可怕的塔格尔被关押在暴风城监狱中，和其他骚乱的囚犯一起被锁在中心监区的铁栅栏后面。",al={"塔格尔位置","寻找塔格尔","监狱里的位置"}}},fx={["1b8c229f"]={q="塔格尔的头颅是什么？",a="这是可怕的塔格尔被砍下的头颅。他是臭名昭著的刽子手头目，曾效力于黑石氏族军阀加塞尔佐格。塔格尔因折磨并处决王国的英勇守卫而被捕，关押在暴风城监狱，等待死刑。",al={"塔格尔的头颅是什么","塔格尔的头颅信息","塔格尔的头颅描述"}},["29061798"]={q="塔格尔的头颅来自哪里？",a="这颗头颅来自可怕的塔格尔本人，他被关押在暴风城监狱深处。一位暴风城贵族叫停了原定的处决后，卫兵伯尔顿便派一名冒险者自行了断此事，潜入牢房砍下这个残暴兽人的头颅。",al={"塔格尔的头颅来自哪里","谁掉落塔格尔的头颅","塔格尔头颅的来源"}}},fp="15,260,19.382.0,16.351.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="范克里夫的头颅",s="艾德温·范克里夫那颗被斩下的头颅，是迪菲亚潜行者领袖已死的冷酷、无可辩驳的证据。将其从死亡矿井深处带回哨兵岭，代表着人民民兵来之不易的复仇。",h="艾德温·范克里夫那颗被斩下的头颅，是迪菲亚潜行者领袖已死的冷酷、无可辩驳的证据。将其从死亡矿井深处带回哨兵岭，代表着人民民兵来之不易的复仇。",kw={"死亡矿井","艾德温·范克里夫","格里安·斯托曼","范克里夫的头颅","人民民兵","哨兵岭","西部荒野"},ang={["class:Rogue"]="艾德温·范克里夫是人类历史上最致命的潜行大师之一；带回他的头颅标志着他那无可匹敌的暗影与破坏生涯的彻底终结。",["faction:Alliance"]="献上范克里夫的头颅为人民民兵提供了一场宣泄式的胜利，尽管这也突显了在西部荒野最黑暗的时刻，暴风城贵族议会却令人不安地缺席。"},sec={{t="首领陨落的证据",b="数月以来，艾德温·范克里夫在重兵把守的亡命之徒、地精工程师以及一台巨大的战争机器的保护下，在死亡矿井的最深处指挥着迪菲亚潜行者的恐怖行动。单凭言语根本无法让饱受摧残的西部荒野定居者相信他们的噩梦已经结束。人民民兵的领袖格里安·斯托曼在宣布乡村安全之前，要求提供不可否认的实物证据。将这个匪首的头颅砍下并带到光天化日之下，为疲惫不堪的守卫者提供了切实的保证，让他们知道这个毁掉他们家园的罪魁祸首再也不会威胁到西部荒野了。"},{t="残酷的胜利",b="尽管斯托曼为了西部荒野的公共利益而寻求范克里夫的死，但展示这个战利品却带有一种沉重的庄严感。范克里夫曾是受人尊敬的建筑大师，在第一次战争后重建了暴风城，但背叛和拖欠的债务迫使他和石匠工会走上了反叛的道路。他被斩下的头颅标志着西部荒野地方民兵运动的终结，但也暴露了王国在处理内部动乱方面的失败，迫使志愿农民和外来的冒险者来执行这种严酷的正义。"}},faq={{q="谁想要范克里夫的头颅？",a="西部荒野哨兵岭的人民民兵队长格里安·斯托曼需要这颗头颅来彻底终结迪菲亚潜行者运动。",al={"这个东西交给谁","谁收范克里夫的头颅","范克里夫的头颅去哪交"}},{q="为什么格里安·斯托曼专门要求他的头颅？",a="迪菲亚潜行者长期以来一直扼杀着西部荒野，如果没有绝对的实物证据，关于范克里夫死亡的传言永远不会被相信。斯托曼需要确凿的证据来安抚深受苦难的农民，并证明民兵的斗争并非徒劳。",al={"为什么要带回他的头颅","为什么是范克里夫的头颅"}},{q="这颗头颅是在哪里获得的？",a="它是从位于月溪镇下方死亡矿井尽头的秘密铁甲舰上的艾德温·范克里夫身上取下的。",al={"范克里夫的头颅在哪里获得","如何获得范克里夫的头颅"}},{q="带回范克里夫的头颅能终结迪菲亚潜行者吗？",a="斯托曼认为他的死是该兄弟会终结的开始，但分裂的团体、流氓强盗和同情者依然在西部荒野、艾尔文森林等地徘徊。",al={"迪菲亚被摧毁了吗","迪菲亚兄弟会后来怎么样了"}}},fx={["4a1d52aa"]={q="范克里夫的头颅是什么？",a="范克里夫的头颅是艾德温·范克里夫被砍下的头颅。他是藏身于死亡矿井深处的迪菲亚潜行者首脑。这颗头颅是血腥而确凿的证据，证明这场叛乱的领袖终于被击败。",al={"范克里夫的头颅是什么","范克里夫的头颅物品","艾德温·范克里夫的头颅"}}},fp="16,171,26.508.0,14.490.1,31.167.0,56.249.0,27.150.0,55.192.0"}
P.entries["item:heart-of-isha-awak"] = {n="依沙瓦克的心脏",s="依沙瓦克的心脏取自强大的长尾鲨依沙瓦克，即商旅海岸的“深海末日”。它是牛头人先知玛伦·天视所追寻的目标，是战胜海洋中最可怕掠食者之一的证明。",h="依沙瓦克的心脏取自强大的长尾鲨依沙瓦克，即商旅海岸的“深海末日”。它是牛头人先知玛伦·天视所追寻的目标，是战胜海洋中最可怕掠食者之一的证明。",kw={"深海末日","依沙瓦克的心脏","依沙瓦克","玛伦·天视","商旅海岸","棘齿城","贫瘠之地"},ang={["class:Hunter"]="在商旅海岸的波涛下追踪并征服“深海末日”，是对猎人面对水下猎物时勇气的终极考验。",["race:Tauren"]="对于牛头人猎人来说，追捕依沙瓦克是一种与大自然最凶猛的掠食者进行精神交流的行为，这是遵循了长者玛伦·天视的指引。"},sec={{t="深海末日的战利品",b="在棘齿城以南、阳光明媚的商旅海岸水域下，栖息着依沙瓦克，这是一头深受水手和沿海居民敬畏的巨大海兽。作为被称为“深海末日”的生物，它已夺去了无数闯入海岸的人类的生命。然而，对于神秘的玛伦·天视来说，这头野兽代表着一种值得尊敬的掠食者，而非毫无理智的威胁。她相信依沙瓦克的凶猛灵魂就蕴含在它的心脏中，因此指引勇敢的猎人们潜入波涛之中，在它的领地内战胜这头野兽，并夺取这颗跳动的心脏作为战利品和精神祭品。"}},faq={{q="什么是依沙瓦克的心脏？",a="它是依沙瓦克的心脏，这是一种在棘齿城以南的沿海水域出没的巨型水生长尾鲨。它是猎杀这头野兽后，向牛头人神秘主义者玛伦·天视提供的证明。",al={"依沙瓦克的心脏","这颗心脏是什么"}},{q="谁想要依沙瓦克的心脏？",a="驻扎在棘齿城以南商旅海岸的牛头人先知玛伦·天视，请求猎人们取回这颗心脏，以纪念这头野兽的力量并汲取其灵魂。",al={"谁需要这颗心脏","我应该把心脏给谁","玛伦·天视"}},{q="依沙瓦克在哪里？",a="依沙瓦克栖息在贫瘠之地东部的商旅海岸外的海域中，游弋在棘齿城地精港口的南面。",al={"依沙瓦克的位置","依沙瓦克在哪里","到哪里寻找依沙瓦克"}},{q="为什么玛伦·天视想要这颗心脏？",a="玛伦认为依沙瓦克是一位值得尊敬的猎手和强大的对手。通过猎杀这头野兽并持有它的心脏，猎人就能将这种海洋生物的灵魂吸纳到自己体内。",al={"为什么要猎杀依沙瓦克","玛伦为什么要这颗心脏"}}},fp="18,146,23.493.0,31.172.0,33.178.0,25.94.0,39.180.0"}
P.entries["item:heartswood"] = {n="同心树",s="心木是从灰谷西北部奥迪拉兰废墟中一棵神圣树木上采伐的木材。它诞生于两位古代恋人的长眠之地，其与不灭忠贞的共鸣使其成为召唤魅魔的必备诱饵。",h="心木是从灰谷西北部奥迪拉兰废墟中一棵神圣树木上采伐的木材。它诞生于两位古代恋人的长眠之地，其与不灭忠贞的共鸣使其成为召唤魅魔的必备诱饵。",kw={"anathera","灰谷","黑暗缚灵者加科因","心木","latherion","奥迪拉兰","魅魔"},ang={["class:Warlock"]="对于联盟术士来说，获取心木是在黑暗缚灵者加科因指导下的一项关键试炼，它提供了强迫并束缚魅魔仆从所需的情感诱饵。",["race:NightElf"]="这棵树代表了上古之战中一段悲剧而神圣的纪念，术士和邪教徒对它的亵渎是对逝去先祖记忆的一种恶劣冒犯。"},sec={{t="忠贞的丰碑",b="心木生长在灰谷西北部奥迪拉兰废墟的精灵石阵之中。据传说，两位名叫Anathera和Latherion的恋人在数千年前那场灾难性的上古之战中并肩倒下。在他们咽下最后一口气的土地上，一棵奇特的树生根发芽，作为他们忠贞不渝的永恒见证而绽放。即使在数千年后，从这棵树上砍下的木材依然吟唱着不灭激情的记忆，使它成为了那些研究情感与灵魂羁绊之人眼中极具好奇心的物品。"},{t="奴役的工具",b="虽然诞生于纯粹的情感，但心木也吸引了更黑暗的目光。魅魔——依靠激情、渴望和情感操纵而生存的恶魔——会被灌注了真挚且不灭之爱的神器强烈吸引。在暴风城的黑暗缚灵者加科因的指导下，人类和侏儒术士专门寻找这种稀有的木材来制作仪式诱饵。通过利用恋人牺牲所产生的内在共鸣，施法者可以诱使魅魔穿过虚空，将其拉入召唤法阵，并将其束缚在自己的意志之下。"}},faq={{q="什么是心木？",a="心木是从灰谷奥迪拉兰废墟中长出的一棵树上所采集的木材，它标志着两位古代暗夜精灵恋人在上古之战中共同丧生的地方。",al={"心木之树","什么是心木","心木背景故事"}},{q="Anathera和Latherion是谁？",a="Anathera和Latherion是一对在上古之战中并肩作战的恋人。当他们双双战死沙场时，他们最后的拥抱滋润了大地，使心木树拔地而起，成为他们忠贞不渝的永恒象征。",al={"anathera和latherion","心木恋人","谁死在心木处"}},{q="为什么术士需要心木？",a="魅魔是充满欲望和情感操纵的恶魔生物。由于心木与坚贞不渝、永恒之爱的本质产生了强烈的共鸣，术士将其用作强大的心灵诱饵，以诱惑并召唤魅魔来到物质世界。",al={"术士为什么想要心木","心木魅魔","心木用途"}},{q="在哪里可以找到心木？",a="心木可以在奥迪拉兰废墟中找到，该废墟位于灰谷森林的西北部，靠近黑海岸的边界。",al={"心木位置","心木在哪里","奥迪拉兰废墟心木"}}},fx={["61f35e8f"]={q="同心树木材来自哪里？是谁创造了它？",a="同心树木材并非凡人所制，而是采自一棵孤树。这棵树生长在灰谷西北部的奥迪拉兰废墟中。数千年前，在灾难性的上古之战期间，一对名为阿纳瑟拉和拉瑟里昂的恋人双双战死。他们咽下最后一口气的地方长出了这棵树，成为他们永恒爱情的活见证。",al={"同心树木材的来源","同心树木材来自哪里","同心树木材如何形成"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="同心树之核",s="同心树之核是一种由古树木材制成的附魔仪式法器。它由暴风城的黑暗缚灵者加科因提供，用于引导所需的魔法来穿透扭曲虚空，并将魅魔召唤到奥术召唤法阵之中。",h="同心树之核是一种由古树木材制成的附魔仪式法器。它由暴风城的黑暗缚灵者加科因提供，用于引导所需的魔法来穿透扭曲虚空，并将魅魔召唤到奥术召唤法阵之中。",kw={"黑暗缚灵者加科因","同心树之核","slaughtered lamb","暴风城","魅魔","召唤法阵","奴役仪式","术士"},ang={["class:Warlock"]="同心树之核是联盟术士的重要训练圣物，是他们召唤并驾驭第一只魅魔的工具。"},sec={{t="虚空之触的焦点",b="在暴风城法师区的“屠宰小羊”旅店下方的黑暗地穴中，术士们在远离城市卫兵窥探的地方进行着仪式。同心树之核是启动奴役仪式的必要奥术导管。此核心由采集的同心树木制成，蕴含着足以穿透世界之纱的残留魔法共鸣。通过在神圣的召唤法阵上利用木材聚焦其黑暗技艺，初学者可以撕开通往扭曲虚空的通道，强行将一只魅魔跨越位面屏障召唤过来。"},{t="奴役试炼",b="召唤恶魔只是挑战的一半；控制它则需要证明对其狡诈和魅惑本性的绝对支配力。黑暗缚灵者加科因将同心树之核交给有前途的修行者，正是为了让他们能在战斗中面对召唤出的恶魔。魅魔以弱点为食，极易压制虚弱的心智，使这次遭遇成为一场致命的试炼。只有制服了恶魔并将消耗后的核心归还给黑暗缚灵者加科因，有抱负的术士才能证明其意志足以永久地奴役这名仆从。"}},faq={{q="同心树之核有什么用途？",a="同心树之核被术士用作仪式试剂，用于在“屠宰小羊”下方的召唤法阵开启传送门。这个传送门将迫使一只魅魔从扭曲虚空进入我们的领域，以便将其击败并奴役。",al={"同心树之核的作用","同心树之核的使用","同心树之核的目的"}},{q="谁提供了同心树之核？",a="它由黑暗缚灵者加科因提供，他是一位术士大师，在暴风城法师区“屠宰小羊”旅店下方的隐藏地下墓穴中训练新手。",al={"如何获得同心树之核","谁给予同心树之核"}},{q="必须在哪里使用核心？",a="该核心必须在位于“屠宰小羊”下方深处、暴风城街道之下的符文召唤法阵中进行引导。",al={"同心树之核位置","哪里召唤魅魔"}},{q="仪式结束后会发生什么？",a="在使用核心召唤魅魔后，你必须在战斗中击败该恶魔以打破其反抗。一旦它被送回虚空，将同心树之核归还给黑暗缚灵者加科因，即可习得随意指挥该恶魔的秘密。",al={"召唤后做什么","上交同心树之核"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="沉重的铅瓶",s="沉重的铅瓶是卡拉诺斯的一位名叫奥齐·电环的研究人员所提供的带屏蔽装置的取样容器。它的设计目的是为了从诺莫瑞根深处的变异生物体内安全地抽取并盛装极其不稳定的辐射残留物，以进行持续的去污研究。",h="沉重的铅瓶是卡拉诺斯的一位名叫奥齐·电环的研究人员所提供的带屏蔽装置的取样容器。它的设计目的是为了从诺莫瑞根深处的变异生物体内安全地抽取并盛装极其不稳定的辐射残留物，以进行持续的去污研究。",kw={"诺莫瑞根","hall of gears","沉重的铅瓶","奥齐·电环","瓶子","放射性辐射尘","唯一的解药就是更多的绿色光芒"},ang={["profession:Engineering"]="这种瓶子是专门用于收集挥发性辐射尘的设备，即使有合适的容器，这个过程也可能需要尝试多次。",["race:Gnome"]="瓶中装入的每一滴挥发性辐射尘，都代表着向收复诺莫瑞根以及了解那场夺走他们家园的化学疯狂迈出的绝望一步。"},sec={{t="一个带屏蔽的容器",b="沉重的铅瓶是一种取样容器，用于从诺莫瑞根受到辐射的生物身上提取挥发性残留物。控制这种辐射尘非常困难，收集到合适的样本可能需要尝试多次。"},{t="寻求治愈方法",b="奥齐·电环提供这个瓶子是他旨在扭转麻风侏儒可怕变异的研究工作的一部分。早先从地表穴居人身上采集的样本缺乏有效化学分析所需的效力。通过对Hall of Gears里的辐射软泥和潜伏者等剧毒野兽使用这个铅瓶，研究人员希望能够分离出这座城市有毒辐射尘的活性成分，并配制出有效的解毒剂。"}},faq={{q="沉重的铅瓶有什么用途？",a="它被用于直接从诺莫瑞根内部活着的受辐射生物身上抽取浓缩的放射性排放物，为卡拉诺斯的研究人员提供用于去污试验的纯净样本。",al={"这个瓶子有什么用","瓶子的用途","什么是铅瓶"}},{q="谁提供了沉重的铅瓶？",a="侏儒研究员奥齐·电环在丹莫罗的卡拉诺斯提供了它，作为他研究如何治愈受到辐射和感染的麻风侏儒工作的一部分。",al={"谁给瓶子","我在哪里获得瓶子","瓶子任务发布者"}},{q="为什么这个瓶子是用厚重的铅制成的？",a="它被称为沉重的铅瓶，但其具体的构造并没有解释。奥齐警告说，控制放射性辐射尘非常困难，而且样本会很快失效。",al={"为什么用铅瓶","为什么需要重铅"}},{q="必须使用这个瓶子对哪些生物进行采样？",a="必须对在诺莫瑞根深处发现的活着的、发光的恐怖生物使用它，例如在Hall of Gears下层徘徊的辐射软泥、潜伏者和恐怖生物。",al={"我对什么使用它","目标生物","哪些怪物会发光"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="赫兹鲁尔的头颅",s="赫兹鲁尔的头颅是从贫瘠之地出没的考克尔半人马酋长赫兹鲁尔·血痕身上取得的恐怖战利品。将它带给十字路口西部的雷加·死门，以此作为当地掠夺者核心领导层已倒下的无可辩驳的证据。",h="赫兹鲁尔的头颅是从贫瘠之地出没的考克尔半人马酋长赫兹鲁尔·血痕身上取得的恐怖战利品。将它带给十字路口西部的雷加·死门，以此作为当地掠夺者核心领导层已倒下的无可辩驳的证据。",kw={"血痕","半人马","十字路口","死门","赫兹鲁尔","考克尔","甜水绿洲","雷加"},ang={["faction:Horde"]="取得考克尔酋长的头颅可以确保甜水绿洲的重要水源，并保护穿行于贫瘠之地的部落旅行者。",["race:Orc"]="雷加·死门认为考克尔半人马是一群缺乏纪律的暴徒，他们原始的愤怒很容易被兽人的战斗纪律所克服，因此这个战利品也证明了真正的战士荣誉。"},sec={{t="斩首考克尔",b="考克尔半人马在贫瘠之地的各处关键绿洲保持着强硬的控制，不断威胁着部落的补给线和新建定居点。赫兹鲁尔·血痕在南方的甜水绿洲指挥着他的部族。雷加·死门，一位被指派负责保卫十字路口西部领土的兽人老兵，他意识到虽然考克尔半人马拥有狂暴的力量，但他们缺乏正规的纪律。通过要求赫兹鲁尔被斩下的头颅，雷加试图瓦解该部族的指挥结构，使他们幸存的战士陷入混乱，并削弱他们对部落的协同攻击。"}},faq={{q="这个头颅属于谁？",a="这个头颅属于赫兹鲁尔·血痕，他是盘踞在贫瘠之地中部、残暴而狡诈的考克尔半人马部族的首领。",al={"赫兹鲁尔是谁","赫兹鲁尔的身份","这是谁的头颅"}},{q="在哪里可以找到赫兹鲁尔·血痕？",a="赫兹鲁尔在位于贫瘠之地十字路口南部的甜水绿洲指挥他的部众。",al={"赫兹鲁尔的位置","赫兹鲁尔在哪里","寻找赫兹鲁尔"}},{q="谁想要赫兹鲁尔的头颅？",a="雷加·死门，一名驻扎在十字路口西侧道路旁军事哨所的兽人，他要求得到这颗头颅作为该酋长已被击败的证明。",al={"上交赫兹鲁尔的头颅","谁在收集赫兹鲁尔的头颅","雷加·死门"}},{q="为什么部落需要他的头颅，而不是仅仅把他赶走？",a="部落需要确凿的证据证明赫兹鲁尔已经死亡。半人马天性易怒且容易发生内斗；消灭他们的最高酋长会瓦解其指挥结构，并降低他们对十字路口的整体威胁。",al={"为什么要杀赫兹鲁尔","为什么要拿走他的头颅","半人马威胁"}}},fp="13,178,23.466.0,29.99.0,32.85.0,24.133.0,69.190.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="高强度辐射尘",s="高强度辐射尘是一种浓缩且不稳定的辐射淤泥样本，正是这种淤泥毒害了诺莫瑞根的下层深处。在侏儒研究员的要求下，人们将这种物质收集在沉重的铅制容器中，希望以此逆向研制出治愈受感染麻风侏儒的解药。",h="高强度辐射尘是一种浓缩且不稳定的辐射淤泥样本，正是这种淤泥毒害了诺莫瑞根的下层深处。在侏儒研究员的要求下，人们将这种物质收集在沉重的铅制容器中，希望以此逆向研制出治愈受感染麻风侏儒的解药。",kw={"诺莫瑞根","绿色辉光","hall of gears","高强度辐射尘","受辐射的软泥怪","麻风侏儒","奥齐·电环"},ang={["profession:Engineering"]="容纳和运输不稳定、衰变中的放射性同位素需要专门制造的铅制药瓶，以保护携带者免受灾难性的辐射。",["race:Gnome"]="从城市深处收集的每一滴有毒尘埃，都代表着扭转诺莫瑞根陷落期间撕裂你族人的可怕变异的微弱希望。"},sec={{t="直取源头",b="虽然在城市外围的受污染拾荒者身上可以刮下少量的辐射样本，但诺莫瑞根灾难真正的核心需要浓度高得多的物质。驻扎在陷落首都之外的研究员需要从爬行在Hall of Gears最底层的受辐射恐怖怪、潜伏者和软泥怪身上直接提取原始、纯净的放射性尘埃。由于这种黏稠的淤泥在不断衰变，必须将其装入专门的铅制药瓶中，并迅速送回，以免样本完全不稳定。"},{t="寻求恢复",b="拼命搜寻这种致命物质有着紧迫的目的。奥齐·电环和他的同事们认为，解开这些辐射淤泥的秘密是研制麻风侏儒解药的唯一可行途径。由于在穴居人入侵期间下令排放有毒气体，这些悲惨的幸存者变得疯狂且畸形，他们仍被困在活生生的梦魇之中，这使得即便是进入废墟内部进行最危险的收集探险也是值得的。"}},faq={{q="这种放射性尘埃从哪里来？",a="它直接取自生活在诺莫瑞根Hall of Gears下层深处的受辐射生物——例如受辐射的软泥怪、恐怖怪和潜伏者。",al={"辐射尘获取地点","辐射尘位置","放射性尘埃来源"}},{q="为什么要这种样本？",a="包括奥齐·电环在内的侏儒研究员需要一份未经稀释、高浓度的诺莫瑞根辐射样本，以研究这种病症并尝试为他们被腐蚀的族人——麻风侏儒——制造解药。",al={"谁需要辐射尘","辐射尘用途","为什么要收集辐射尘"}},{q="为什么必须如此小心地处理它？",a="这种尘埃极其不稳定，且随着衰变迅速崩溃。它需要用沉重的铅制容器安全运输，并必须在效力退化成无用残渣之前交付给研究员。",al={"辐射尘衰变","为什么要铅制药瓶","辐射尘不稳定"}},{q="为什么以前的穴居人残渣不够用？",a="从城市外地表穴居人身上收集的残渣被证明太弱且不纯，无法用于科学测试。研究员特别需要那种只有在生活于辐射城市深处的生物体内才能找到的原始、浓缩的辐射辉光。",al={"为什么穴居人辉光不行","穴居人辐射与辐射尘的区别","之前的样本失效"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="Highborne Relic (Classic)",s="上层精灵遗物是人们从黑海岸亚米萨兰废墟中徘徊的游荡幽灵身上回收的古代魔法器具。这些遗物浸透了曾经撕裂远古卡利姆多的奥术力量，暗夜精灵学者们正设法将它们摧毁，以免它们沉睡的力量造成进一步的危害。",h="上层精灵遗物是人们从黑海岸亚米萨兰废墟中徘徊的游荡幽灵身上回收的古代魔法器具。这些遗物浸透了曾经撕裂远古卡利姆多的奥术力量，暗夜精灵学者们正设法将它们摧毁，以免它们沉睡的力量造成进一步的危害。",kw={"亚米萨兰","奥术","黑海岸","上层精灵","上层精灵的遗物","哨兵","珊蒂斯·织风"},ang={["class:Mage"]="法师们可能会觉得这些遗物的奥术工艺令人着迷，但当地的暗夜精灵当局绝不允许在销毁它们时有任何迟疑。",["race:NightElf"]="对于暗夜精灵来说，这些遗物严酷地提醒着人们，正是那灾难性的奥术傲慢撕裂了他们古老的文明。"},sec={{t="大分裂的残骸",b="一万年前，上层精灵阶层肆无忌惮地使用奥术魔法，最终导致了远古卡利姆多的毁灭。如今，他们曾经的庄园在黑海岸化为破碎的废墟。在亚米萨兰崩塌的石柱间，哀号和挣扎的幻象游荡在林地之上，无休止地依附着他们往昔魔法的实体器具。这些遗物依然是奥术污染的持续附着点，被那些拒绝放手自我毁灭工具的幽灵所紧握。"},{t="净化奥术污染",b="对于大分裂后大多摒弃了奥术魔法的现代暗夜精灵社会而言，这类文物代表着严重的隐患。像奥伯丁的珊蒂斯·织风这样的学者，根据哨兵部队的侦察报告，积极委托旅行者从受诅咒幽灵的幽灵手中夺回这些遗物。一旦收集到，这些遗物就会被系统性地销毁，以确保上层精灵的远古邪恶和灾难性错误不会重演。"}},faq={{q="上层精灵遗物从哪里来？",a="它们是从在黑海岸南部大路以东的亚米萨兰废墟中徘徊的幽灵身上回收的。受诅咒的、挣扎且哀号的上层精灵之灵在古代石柱间携带着它们。",al={"我在哪里可以找到上层精灵遗物","谁掉落上层精灵遗物","遗物位置"}},{q="为什么珊蒂斯·织风想要这些遗物？",a="珊蒂斯·织风担心这些古代物品上残留的奥术腐蚀。他收集它们是为了让它们能够被彻底拆解并销毁，防止任何人复兴危险的上层精灵魔法。",al={"为什么要收集遗物","遗物会怎么样","织风的目标"}},{q="为什么上层精灵的幽灵还在亚米萨兰？",a="这些幽灵是古代上层精灵贵族，他们在万年前世界破碎时死去。由于他们的傲慢和对奥术魔法的留恋而受诅咒，他们不安的灵魂依然束缚在他们前城市的废墟之中。",al={"为什么亚米萨兰有幽灵","谁是受诅咒的上层精灵","为什么黑海岸有幽灵"}},{q="上层精灵遗物可以安全使用吗？",a="不行。暗夜精灵认为它们被引发大分裂的污秽、失控的奥术实践所污染。它们沉睡的魔法被视为危险的，这就是为什么学者们要求销毁它们而不是进行研究。",al={"我可以使用上层精灵遗物吗","遗物危险吗"}}},fp="25,175,25.389.0,24.369.0,36.172.0,47.158.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="风巢双足飞龙的毒囊",s="风巢毒囊是从栖息在千针石林风巢高耸尖塔上的野生双足飞龙身上采集的。虽然兽人将双足飞龙视为珍贵的空中坐骑，但一些药剂师和商人对这些猛兽的毒刺的重视程度甚至超过了活体本身。",h="风巢毒囊是从栖息在千针石林风巢高耸尖塔上的野生双足飞龙身上采集的。虽然兽人将双足飞龙视为珍贵的空中坐骑，但一些药剂师和商人对这些猛兽的毒刺的重视程度甚至超过了活体本身。",kw={"菲奥拉·长耳","刺心","风巢","毒药","塞拉摩","千针石林","毒囊","双足飞龙"},ang={["class:Rogue"]="从未经驯化的千针石林双足飞龙身上采集的这种高浓度麻痹毒素，是卡利姆多最强力的天然毒素之一。",["faction:Alliance"]="对于联盟来说，打击风巢的巢穴具有双重目的：收集宝贵的生物试剂以供贸易，同时扑杀那些本可能被捕获并驯化为部落坐骑的野生种群。"},sec={{t="强效的收获",b="千针石林的高耸尖塔栖息着繁茂的野生双足飞龙群，尤其是在风巢那些高耸的岩架周围。这些长着翅膀的掠食者依靠尾部带刺毒腺分泌的强力毒素来麻痹和猎杀猎物。虽然部落经常驯化这些生物作为忠诚的风骑士，但它们的毒囊在卡利姆多的炼金术师、猎人和投机商人之间却能卖出极高的价格。"},{t="遥远的买家",b="虽然这种毒素原产于卡利姆多中部深邃的峡谷中，但它的影响力远超当地。在港口城镇塞拉摩，高等精灵菲奥拉·长耳（Fiora Longears）愿意出高价收购从风巢龙群身上采集的新鲜毒囊。她寻求的是那些肿胀的、装满毒液的样本——通常只有在幼年双足飞龙或育龄雌性双足飞龙身上才能找到——这推动了远离这些野兽天然沙漠栖息地的危险试剂贸易。"}},faq={{q="哪些生物携带这种毒囊？",a="它们直接采集自栖息在千针石林风巢的野生双足飞龙，包括风巢双足飞龙、族长、配偶，以及女族长刺心（Heartrazor）。",al={"毒囊掉落位置","谁掉落风巢毒液","双足飞龙毒液掉落"}},{q="为什么菲奥拉·长耳（Fiora Longears）要在塞拉摩收购这种毒液？",a="菲奥拉·长耳（Fiora Longears）认识到双足飞龙毒液在特定的交易圈中具有极高的价值——有时甚至比坐骑本身更有利可图。她委托前往千针石林风巢的旅行者带回完整的毒囊进行交易。",al={"为什么菲奥拉需要毒液","塞拉摩毒液买家","谁购买双足飞龙毒液"}},{q="所有的双足飞龙毒囊都一样吗？",a="毒效和容量各不相同。最值钱的毒囊通常是那些肿胀欲裂的，这通常出现在幼年双足飞龙或具有繁殖能力的雌性双足飞龙身上。",al={"双足飞龙毒液品质","肿胀的毒囊"}},{q="部落与联盟对这些双足飞龙的利用方式有何不同？",a="部落主要捕获并繁育双足飞龙，作为空中坐骑和被称为风骑士的斥候。而缺乏驯化网络的独立商人和联盟联络人，则直接为了获取致命的化学试剂而猎杀这些野兽。",al={"部落如何使用双足飞龙","兽人使用这种毒液吗"}}},fx={["98761a97"]={q="风巢双足飞龙的毒囊是什么？",a="风巢双足飞龙的毒囊是从野生双足飞龙身上采集的器官。这些双足飞龙栖息在千针石林风巢的高耸台地上。双足飞龙在卡利姆多以部落使用的飞行坐骑而闻名，但它们的毒液也因药效猛烈而备受珍视。从风巢双足飞龙身上取下的毒囊尤其饱满，富含致命毒素，因此成为炼金师和异兽材料商人的高价货品。",al={"风巢双足飞龙的毒囊是什么","风巢双足飞龙的毒囊","双足飞龙毒囊"}}},fp="19,260,16.431.0,15.401.0,38.172.0,53.257.0,36.167.0,66.246.0"}
P.entries["item:highperch-wyvern-egg"] = {n="风巢双足飞龙的蛋",s="风巢双足飞龙蛋是从千针石林高耸台地顶部的巢穴中采集而来的。部落渴望成为御风者的学徒们一直在寻找这些蛋，以便饲养和训练新的空中坐骑。",h="风巢双足飞龙蛋是从千针石林高耸台地顶部的巢穴中采集而来的。部落渴望成为御风者的学徒们一直在寻找这些蛋，以便饲养和训练新的空中坐骑。",kw={"艾鲁","乱风岗","风巢","风巢双足飞龙的蛋","千针石林","御风者","双足飞龙"},ang={["class:Hunter"]="在风巢危险的高地上穿行需要了解凶猛捕食者的习性，因为成年的双足飞龙会用锋利的爪子和带毒的刺来保卫它们的筑巢地。",["faction:Horde"]="可靠的空中旅行对于维持卡利姆多广大领土上的通讯和军事准备至关重要，这使得获取新鲜的双足飞龙种群成为了一项具有战略意义的任务。"},sec={{t="台地上的巢穴",b="千针石林风巢的高原为当地的双足飞龙提供了一个天然的栖息地，供它们筑巢并抚育后代。这些筑巢地只能通过蜿蜒陡峭的峡谷岩壁小径进入，并由成年野兽严密守护。巢中的蛋既坚固又温暖，里面孕育的幼崽能够适应卡利姆多严酷的天空。"},{t="培养新的御风者",b="随着部落不断扩张其信使和侦察网络，整个卡利姆多对训练有素的双足飞龙的需求一直供不应求。在乱风岗，像牛头人艾鲁这样的学员直接从野外巢穴中寻找完好的蛋。通过从破壳开始抚养幼崽，驯养员们希望建立起深厚的纽带，从而为部落的御风者训练出值得信赖的飞行坐骑。"}},faq={{q="这些蛋在哪里可以找到？",a="它们散落在风巢各处的巢穴中，那是一座位于千针石林西侧岩壁上的高耸台地，可以通过一条从峡谷底部通往上方的道路进入。",al={"蛋的位置","哪里可以找到双足飞龙蛋","风巢蛋的位置"}},{q="部落为什么要收集野生双足飞龙蛋？",a="部落的御风者队伍正在壮大，驯养员们难以训练出足够多的成年双足飞龙来满足需求。像艾鲁这样的学员收集这些蛋，以便从出生起就抚养幼崽，为野兽和骑手执行空中任务做好准备。",al={"为什么要偷双足飞龙蛋","这些蛋有什么用途","艾鲁交蛋任务的目的"}},{q="双足飞龙父母会对采集者怀有敌意吗？",a="是的。野生的双足飞龙对巢穴有强烈的保护欲，会猛烈攻击任何闯入风巢并试图动它们巢穴的入侵者。",al={"双足飞龙会攻击吗","双足飞龙有保护欲吗"}},{q="乱风岗里谁会接收这些蛋？",a="艾鲁，一名驻扎在乱风岗顶部的御风者学徒，他收集这些蛋是希望能开始他自己的正式坐骑训练。",al={"谁需要双足飞龙蛋","艾鲁 乱风岗"}}},fx={efbaa71b={q="风巢双足飞龙的蛋是什么？",a="这些是野生双足飞龙产下的可孵化的蛋，它们在千针石林高耸的峡谷台地上筑巢。坚硬的蛋壳中孕育着卡利姆多的飞行掠食者幼崽，许多人都想从幼年开始饲养它们，将其培养成忠诚的飞行坐骑。",al={"风巢双足飞龙的蛋是什么","双足飞龙蛋信息","这些蛋是什么"}},bbfa5024={q="风巢双足飞龙的蛋来自哪里？",a="这些蛋由野生双足飞龙产下，位于风巢的悬崖巢穴中。风巢是一片高耸于千针石林峡谷之上的高地。成年双足飞龙会凶猛地保护自己的巢穴，抵御掠食者和胆大的拾荒者。",al={"风巢双足飞龙的蛋来自哪里","谁产下了这些蛋","双足飞龙蛋的来源"}}},fp="20,202,17.386.0,23.383.0,27.183.0,44.227.0,48.156.0,40.128.0"}
P.entries["item:hildelve-s-journal"] = {n="莫里·铁钻的日记",s="《莫里·铁钻的日记》是矮人飞行员希尔德夫最后的记录，从他在丹莫罗冰冷荒野的遗骸中被发现。日记上沾满了血迹，记录了他遭遇凶猛灰熊的致命经历，并传达了他临终前的复仇遗愿。",h="《莫里·铁钻的日记》是矮人飞行员希尔德夫最后的记录，从他在丹莫罗冰冷荒野的遗骸中被发现。日记上沾满了血迹，记录了他遭遇凶猛灰熊的致命经历，并传达了他临终前的复仇遗愿。",kw={"丹莫罗","希尔德夫","冰爪熊","日记","鬃毛怪","驾驶员塞克·锤足","攻城旅"},ang={["faction:Alliance"]="找回像希尔德夫这样阵亡军人的个人物品，加强了联盟与铁炉堡攻城旅之间的纽带。",["race:Dwarf"]="这本记录向矮人飞行员那坚韧不拔的精神致敬，他们无惧严寒与野兽，守护着卡兹莫丹的高地。"},sec={{t="飞行员的临终遗言",b="当他的蒸汽坦克抛锚后，矮人飞行员希尔德夫将伙伴锤足留在了坦克旁，独自深入丹莫罗白雪皑皑的山脊，寻找传闻中的克龙矿石。根据他潦草记在日记里的内容，他被一头被称为“鬃毛怪”的凶残冰爪熊跟踪了数日，随后遭到伏击。尽管希尔德夫英勇搏斗并设法赶走了野兽，但他还是身负重伤，被困在严寒之中。日记详细记录了他痛苦的最后时刻，并在猛兽折返给予他致命一击前，留下了唯一明确的恳求：无论谁发现了他的尸体，请务必猎杀“鬃毛怪”，为他的死复仇。"},{t="回到攻城旅",b="这份被找回的日记为希尔德夫的战友——驻扎在丹莫罗东部北门哨岗附近的驾驶员塞克·锤足带来了沉痛的终结。作为铁炉堡攻城旅的一员，锤足在希尔德夫一去不返后一直深感不安。将日记连同野兽的断爪一并交还，证明了希尔德夫的灵魂得以安息，他的遗愿也得到了尊重。"}},faq={{q="希尔德夫是谁？",a="希尔德夫是隶属于铁炉堡攻城旅的一名矮人蒸汽坦克驾驶员。他的坦克损坏后，他只身前往丹莫罗的荒野寻找克龙矿石，在返回前被那头名为“鬃毛怪”的熊杀害。",al={"希尔德夫背景故事","谁是希尔德夫","矮人飞行员希尔德夫"}},{q="“鬃毛怪”是什么？",a="“鬃毛怪”是一头异常巨大且凶残的冰爪熊，徘徊在丹莫罗的雪岭之上。它在希尔德夫被困时发动了伏击，将其严重抓伤，随后又折返结束了他的生命。",al={"谁是鬃毛怪","是什么杀了希尔德夫","杀死希尔德夫的熊"}},{q="日记找到后应该交给谁？",a="日记应交给驻扎在丹莫罗东部北门哨岗附近的攻城坦克驾驶员塞克·锤足。锤足是希尔德夫的好友，一直在打听这位失踪飞行员的消息。",al={"我应该把日记交给谁","谁会收到希尔德夫的日记","提交希尔德夫的日记"}},{q="希尔德夫在日记中有什么请求？",a="希尔德夫自知伤重不治，便在日记的最后几页记录了袭击他的野兽，并请求任何发现他遗骸的旅行者猎杀“鬃毛怪”，为他报仇。",al={"希尔德夫的遗愿","日记里写了什么","飞行员的临终遗愿"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="希尔斯布莱德人类颅骨",s="一种从希尔斯布莱德丘陵各地被杀的人类防御者和镇民身上搜集来的恐怖战利品。这些头骨被驻扎在塔伦米尔的被遗忘者们收集起来，作为对当地人类定居点进行无情攻击的阴森纪念品。",h="一种从希尔斯布莱德丘陵各地被杀的人类防御者和镇民身上搜集来的恐怖战利品。这些头骨被驻扎在塔伦米尔的被遗忘者们收集起来，作为对当地人类定居点进行无情攻击的阴森纪念品。",kw={"达萨利亚","希尔斯布莱德","沙穆萨","头骨","南海镇","塔伦米尔","战利品"},ang={["faction:Alliance"]="希尔斯布莱德的农民和士兵沦为被收集的玩物，这体现了被遗忘者在洛丹伦开展的军事行动中的残酷无情。",["race:Undead"]="对于被遗忘者来说，从希尔斯布莱德获取人类头骨既是一种甜蜜的复仇，也是一种毛骨悚然的提醒，提醒他们那些仍然排斥他们的生者同胞。"},sec={{t="苦战的战利品",b="随着塔伦米尔的被遗忘者与南海镇及其周边定居点的人类居民之间的冲突愈演愈烈，被砍下的头骨成为了屠杀的实物证据。当死亡猎手和士兵们执行达萨利亚在希尔斯布莱德之战中下达的系统性清洗命令时，其他困在守卫岗位的卫兵们渴望分得一杯羹。亡灵卫兵沙穆萨热切地向一线战士索要这些战利品，并从积攒这些被遗忘者生前曾与之共存过的人们的遗骸中，获得了一种扭曲的快感。"}},faq={{q="谁想要这些人类头骨？",a="驻扎在塔伦米尔的被遗忘者哨兵，亡灵卫兵沙穆萨，会收集这些头骨。由于嫉妒那些被派往希尔斯布莱德战斗和掠夺的士兵，而自己却只能困在守卫岗位上，他要求路过的冒险者带给他三十个头骨，以充实他的私人收藏。",al={"谁想要头骨","谁在收集人类头骨","亡灵卫兵沙穆萨 头骨"}},{q="希尔斯布莱德人类头骨是在哪里收集的？",a="它们是从希尔斯布莱德丘陵各地的人类战斗人员和劳工身上搜集来的，主要集中在希尔斯布莱德之战期间遭受攻击的人类农场、矿井和城镇防御工事周围。",al={"头骨从哪里掉落","刷人类头骨","谁掉落人类头骨"}},{q="为什么被遗忘者要收集人类遗骸？",a="除了纯粹的仇恨和黑色幽默之外，收集人类死者的战利品对一些被遗忘者来说是一种阴森的消遣。像沙穆萨这样的士兵将头骨视为珍贵的奇异收藏品，也是希尔斯布莱德即将陷落的令人满意的证明。",al={"为什么被遗忘者要头骨","被遗忘者头骨收集"}}},fx={["0091f8c0"]={q="希尔斯布莱德人类颅骨是什么？",a="这些是从散落在希尔斯布莱德丘陵各处的人类守军和居民遗体上砍下的可怖战利品。塔伦米尔的被遗忘者与希尔斯布莱德的生者之间战火不断，这些骇人的信物是联盟在这片争夺之地伤亡的实物证据。",al={"希尔斯布莱德人类颅骨是什么","希尔斯布莱德颅骨物品","希尔斯布莱德人类颅骨信息"}},["9eb161fa"]={q="希尔斯布莱德人类颅骨来自哪里？是谁制作的？",a="这些颅骨直接取自居住在希尔斯布莱德丘陵的人类，由参与边境战事的部落战士收集。它们并非人工制品，而是从阵亡的士兵、农夫和居民身上取下的阴森战场遗物；这些人曾守卫当地的人类定居点，抵御被遗忘者。",al={"希尔斯布莱德人类颅骨的来源","希尔斯布莱德颅骨来自哪里","谁制作希尔斯布莱德颅骨"}},a9ea879b={q="亡灵卫兵沙穆萨为什么想要希尔斯布莱德人类头骨？",a="驻扎在塔伦米尔执行守卫任务的亡灵卫兵沙穆萨，嫉妒那些被派去劫掠并与生者作战的战士。他被困在前线后方，便收集头骨作为珍贵的私人死亡纪念品，以此间接分享屠杀希尔斯布莱德人类守军的快感。",al={"沙穆萨为什么想要头骨","谁想要希尔斯布莱德人类头骨，为什么","为什么收集希尔斯布莱德人类头骨"}}},fp="21,160,24.451.0,29.232.0,42.203.0,42.168.0"}
P.entries["item:hillsbrad-town-registry"] = {n="希尔斯布莱德城镇文档",s="希尔斯布莱德城镇文档是一份存放在希尔斯布莱德农场市政厅内的正式市政账簿。它记录了该定居点幸存的公民、土地所有者和市政档案，这使其成为被遗忘者在针对人类据点发动攻势时的关键战略目标。",h="希尔斯布莱德城镇文档是一份存放在希尔斯布莱德农场市政厅内的正式市政账簿。它记录了该定居点幸存的公民、土地所有者和市政档案，这使其成为被遗忘者在针对人类据点发动攻势时的关键战略目标。",kw={"希尔斯布莱德之战","达萨利亚","希尔斯布莱德农场","希尔斯布莱德市政厅","希尔斯布莱德城镇文档","伯恩赛德镇长"},ang={["faction:Horde"]="夺取城镇文档是打破人类在山麓丘陵的权威并巩固被遗忘者在塔伦米尔的据点的决定性一步。",["race:Human"]="这份账簿代表了希尔斯布莱德剩余镇民的正式存在和权利，它的丢失对该地区社区而言是一个毁灭性的打击。"},sec={{t="反抗记录",b="希尔斯布莱德城镇文档存放在靠近伯恩赛德镇长讲台的市政厅内，记录了希尔斯布莱德的人口、住户和行政权利。随着来自塔伦米尔的被遗忘者努力打破人类在山麓丘陵的抵抗，高级执行官达萨利亚命令部落勇士潜入市政厅，消灭议员，并夺取这份账簿。没收这份文档剥夺了希尔斯布莱德的市政秩序，并为幽暗城提供了关于幸存人口及其资产的宝贵情报。"}},faq={{q="希尔斯布莱德城镇文档存放在哪里？",a="该文档存放在希尔斯布莱德农场的市政厅内，位于通往伯恩赛德镇长平台的楼梯附近的一个角落里。",al={"文档位置","城镇文档在哪里","寻找希尔斯布莱德文档"}},{q="为什么被遗忘者想要偷走它？",a="高级执行官达萨利亚试图彻底瓦解人类在山麓丘陵的统治。夺取这份文档不仅使该城镇失去了有关其公民和财产的重要记录，还为被遗忘者提供了有关幸存社区的详细情报。",al={"为什么要偷文档","达萨利亚的文档任务","文档的目的"}},{q="谁在守卫这份文档？",a="它由伯恩赛德镇长和希尔斯布莱德议员守卫，他们挥舞着防御魔法，并在市政厅内外集结。",al={"谁保护文档","市政厅守卫者"}}},fx={["188a667c"]={q="希尔斯布莱德城镇文档是什么？",a="希尔斯布莱德城镇文档是一本官方记录簿，存放在希尔斯布莱德农场聚居地的市政厅内。它由当地人类行政机构在治安官伯恩赛德的主持下维护，记录了公民事务、人口和治理情况，记载着联盟在山麓地带尚存的一处据点。",al={"希尔斯布莱德城镇文档是什么","希尔斯布莱德城镇文档","记录簿是什么"}}},fp="23,233,20.521.0,42.133.0,37.246.0,24.138.0"}
P.entries["item:hollow-vulture-bone"] = {n="空心秃鹫骨",s="空心秃鹫骨是采集自闪光平原食腐动物的一种轻便而耐用的遗骸。在沙漠赛道，地精技师们将它们视为一种特殊的建筑材料，用以减轻火箭车的重量，同时又不会牺牲结构完整性。",h="空心秃鹫骨是采集自闪光平原食腐动物的一种轻便而耐用的遗骸。在沙漠赛道，地精技师们将它们视为一种特殊的建筑材料，用以减轻火箭车的重量，同时又不会牺牲结构完整性。",kw={"空心秃鹫骨","减轻负荷","沙漠赛道","普兹克","食腐动物","闪光平原","千针石林"},ang={["class:Hunter"]="闪光平原的秃鹫是顽强的食腐动物，这使得它们成为追踪穿过那片耀眼盐碱地的天然目标。",["profession:Engineering"]="虽然典型的蓝图依赖于沉重的铁和青铜，但使用空心禽骨展现了地精赛车创新核心那种不拘小节、追求减重的实用主义。"},sec={{t="平原上的赛车材料",b="在盐碱地上，速度就是一切，而重量是速度的死敌。虽然标准的工程学非常依赖铁和铜，但沙漠赛道的地精维修组为了获得优势，会利用沙漠中能找到的任何材料。秃鹫骨天生中空却异常坚固，为内部支架、转向装置和轻型结构支撑提供了完美的强度重量比。对于像普兹克这样的首席修理师来说，从当地的食腐动物身上采集骨头是一种既实用又廉价的捷径，能帮助赛车在赛道上缩短哪怕几秒的时间。"}},faq={{q="地精为什么需要秃鹫骨？",a="像普兹克这样的地精工程师利用空心秃鹫骨来减轻火箭车的额外重量。由于鸟类骨骼天生轻盈且出人意料地坚固，它们成为了转向装置和轻型结构框架的理想材料。",al={"为什么要用骨头","地精骨头用途","普兹克的骨头用途"}},{q="这些骨头是从哪里来的？",a="它们采集自盘旋在千针石林闪光平原上的盐碱平原食腐鸟和盐碱平原秃鹫，尤其是在散布于盐碱荒漠的巨大骨架周围。",al={"空心秃鹫骨在哪里寻找","秃鹫骨位置","如何获得秃鹫骨"}},{q="普兹克是谁？",a="普兹克是一名驻扎在沙漠赛道地精工程师兼首席机械师。他不断地调试和改装火箭车，以对抗由菲兹尔·铜栓领导的侏儒车队。",al={"普兹克是谁","普兹克赛道","谁需要这些骨头"}}},fx={["2d4c7633"]={q="空心秃鹫骨是什么？",a="这些是从盘旋于闪光平原上空的食腐鸟身上搜集来的骨头，轻巧而坚固。鸟类骨骼天生中空，有助于飞行，因此在机械工程中格外适用，尤其是需要尽可能减轻重量的场合。沙漠赛道的地精技师用它们为火箭赛车制作耐用的结构部件和转向零件。",al={"空心秃鹫骨是什么","空心秃鹫骨"}}},fp="19,273,29.540.0,38.236.0,31.201.0,14.186.0"}
P.entries["item:honorary-picks"] = {n="荣誉锄",s="“荣誉锄”是一捆在铁炉堡铸造的礼仪工具，旨在奖励矮人矿工学徒。通过狮鹫航线托付给旅者们，它们被送往塞尔萨玛的布洛克·寻石者手中，以标志他的学生们已准备好在洛克莫丹开采丰富的矿脉。",h="“荣誉锄”是一捆在铁炉堡铸造的礼仪工具，旨在奖励矮人矿工学徒。通过狮鹫航线托付给旅者们，它们被送往塞尔萨玛的布洛克·寻石者手中，以标志他的学生们已准备好在洛克莫丹开采丰富的矿脉。",kw={"布洛克·寻石者","gryth thurden","荣誉锄","铁炉堡","洛克莫丹","采矿锄","塞尔萨玛","索格拉姆·伯雷森"},ang={["profession:Mining"]="卡兹莫丹的每一位矿工都明白一把坚固的锄头的价值，获得一件荣誉工具标志着一名新手真正踏入了这一职业。",["race:Dwarf"]="对矮人而言，将铁炉堡铸造的工具赠予在边远地区工作的学徒，是一项象征亲情与技艺的受人称颂的传统。"},sec={{t="下一代的工具",b="在矮人社会中，采矿不仅仅是一种行业；它是文化基石，不仅让Great Forge持续燃烧，也为王国提供了铁和石料。“荣誉锄”代表了对在塞尔萨玛跟随布洛克·寻石者学习的见习勘探者的正式认可。这些锄头直接源自铁炉堡，颁发给那些证明了自己的敬业精神并准备好在洛克莫丹处理露天矿床的学生。"},{t="测试狮鹫航线",b="运送这些锄头对联盟的山地猎人和商人来说还有第二个目的：让信使熟悉王国的狮鹫网络。货物从铁炉堡的Great Forge直接运送给Gryth Thurden，随后飞越群山送达塞尔萨玛的索格拉姆·伯雷森手中，这次运输展示了首都如何通过迅捷的空中通道与外围哨所保持紧密联系。"}},faq={{q="“荣誉锄”有什么用？",a="“荣誉锄”是为洛克莫丹布洛克·寻石者的采矿学生们制作的。它们是颁发给准备在整个地区开采矿脉的学徒们的礼仪性工具，同时也具备实用功能。",al={"“荣誉锄”是什么","“荣誉锄”的用途","“荣誉锄”的目标"}},{q="谁寄送这些锄头，谁又负责接收？",a="这些锄头在铁炉堡准备好，并被送到城内Gryphon Roost的Gryth Thurden处。从那里，它们被空运到东边的塞尔萨玛，并亲手交付给采矿导师布洛克·寻石者。",al={"谁获得“荣誉锄”","“荣誉锄”的交付","“荣誉锄”的接收者"}},{q="为什么要用狮鹫运送这些锄头？",a="虽然可以通过北门小径步行运送，但通过狮鹫管理员Gryth Thurden运送不仅能确保快速运输，还能教会旅者们如何利用铁炉堡和洛克莫丹之间既定的联盟飞行路线。",al={"为什么要空运锄头","为什么要乘坐狮鹫","“荣誉锄”的飞行路线"}},{q="“荣誉锄”是真正的武器或可以装备的工具吗？",a="不是。信使携带它们仅仅是作为货物；它们是为布洛克·寻石者的采矿学生们准备的，他们渴望在洛克莫丹的矿床上一展身手。",al={"我可以装备“荣誉锄”吗","“荣誉锄”是物品吗","“荣誉锄”可用吗"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="阿兰其亚的角",s="阿兰其亚的角是狩猎战利品，取自游荡在莫高雷平原上的传奇科多兽阿兰其亚。在大酋长凯恩·血蹄的授意下，获取此角是证明一名有抱负的猎人拥有足够的纪律和追踪技巧，能够供养舒哈鲁族的有力证据。",h="阿兰其亚的角是狩猎战利品，取自游荡在莫高雷平原上的传奇科多兽阿兰其亚。在大酋长凯恩·血蹄的授意下，获取此角是证明一名有抱负的猎人拥有足够的纪律和追踪技巧，能够供养舒哈鲁族的有力证据。",kw={"阿兰其亚","凯恩·血蹄","阿兰其亚的角","科多兽","莫高雷","大地母亲的仪式","雷霆崖"},ang={["class:Hunter"]="追踪阿兰其亚在莫高雷广阔大地上划出的圆圈路径，是对任何真正的猎人都引以为傲的基础追踪和荒野生存技能的考验。",["race:Tauren"]="将此角呈交给大酋长凯恩，标志着一次关键的成年礼，确认你已经准备好在雷霆崖之上供养并保卫你的人民。"},sec={{t="酋长的试炼",b="尽管通过最初的大地母亲的仪式可以使年轻的牛头人在雷霆崖获得一席之地，但大酋长凯恩·血蹄仍期望他的人民不断证明自己的价值。对牛头人而言，身份认同与狩猎以及与大地长久的和谐共存直接相关。凯恩会派年轻的猎人去追踪阿兰其亚，这是一头在下方草原游荡的巨大的独行科多兽公兽，以此来考验他们。取回阿兰其亚的角，证明了猎人已经掌握了跨越广袤大地追踪猎物这一基本技艺。"},{t="供养部族",b="将角带到雷霆崖的高地不仅仅是为了展示武力，更是为了整个族群的生存。在牛头人的文化中，猎杀的野兽绝不能有任何浪费。呈交这份战利品可以告知大酋长野兽倒下的位置，让采集小队能迅速前往平原，为这座初生的首都收割阿兰其亚厚实的毛皮和丰美的肉食。"}},faq={{q="什么是阿兰其亚的角？",a="这是取自阿兰其亚的一只角，这头强大而难以捉摸的科多兽游荡在莫高雷的平原上。猎人们将其带给凯恩·血蹄，作为一种通过试炼的形式来证明他们的追踪技巧。",al={"阿兰其亚的角","阿兰其亚之角","什么是这个角"}},{q="阿兰其亚是谁？",a="阿兰其亚是一头著名的科多兽公兽，在雷霆崖东北部的草原上绕行。他以强壮的体魄和广阔的迁徙路线而闻名，对于那些想要向部族证明自己价值的猎人来说，他是一个强大的猎物。",al={"阿兰其亚","阿兰其亚是谁","阿兰其亚传说"}},{q="为什么凯恩·血蹄要索取这个战利品？",a="凯恩认为，要维持在雷霆崖的地位，就需要不断证明自己的贡献和能力。通过追踪并击倒阿兰其亚，猎人不仅证明了自己对大地母亲传统的虔诚，还为族群提供了宝贵的资源。",al={"为什么凯恩要角","凯恩 阿兰其亚","大地母亲的仪式 之角"}},{q="野兽被杀死后，剩下的部分会怎样处理？",a="按照牛头人的习俗，猎物的任何部分都不能浪费。一旦交出角来确认猎杀成功，凯恩就会派遣一支采集小队前往莫高雷，为雷霆崖收集毛皮和肉食。",al={"阿兰其亚的肉","牛头人狩猎传统","阿兰其亚的尸体"}}},fp="17,175,18.419.0,23.329.0,30.190.0,17.202.0,46.233.0,57.173.0"}
P.entries["item:horn-of-awakening"] = {n="唤醒号角",s="唤醒号角是一件放置在黑海岸南部克罗尼亚·恒影身旁箱子里的发声乐器。每当这位昏昏欲睡的德鲁伊在前往灰谷的路上陷入沉睡时，人们就会用它来唤醒他。",h="唤醒号角是一件放置在黑海岸南部克罗尼亚·恒影身旁箱子里的发声乐器。每当这位昏昏欲睡的德鲁伊在前往灰谷的路上陷入沉睡时，人们就会用它来唤醒他。",kw={"灰谷","黑海岸","利爪德鲁伊","翡翠梦境","唤醒号角","克罗尼亚·恒影","迈斯特拉岗哨"},ang={["class:Druid"]="利爪德鲁伊在兽穴中沉睡了数代，与翡翠梦境进行交流，回归清醒的现实往往会让他们感到茫然和不知所措。",["race:NightElf"]="克罗尼亚昏昏欲睡的旅程展现了暗夜精灵的德鲁伊在翡翠梦境中长期沉睡后，回归清醒世界是多么艰难。"},sec={{t="昏睡德鲁伊的补救措施",b="克罗尼亚·恒影是一位刚刚从翡翠梦境中沉睡了数个世纪后醒来的利爪德鲁伊，他在清醒的现实世界中总是感到昏昏欲睡。在向南前往迈斯特拉岗哨的旅途中，他将这只号角托付给愿意护送他的旅行者。每当他在危险的荒野小径上因疲惫而倒下时，吹响这件乐器发出的清脆声响就能让他精神一振，并在野兽或邪教徒趁他熟睡时袭击他之前，促使他重新站起来。"}},faq={{q="在哪里可以找到唤醒号角？",a="这只号角存放在克罗尼亚的箱子里，就在黑海岸南部靠近灰谷边界处克罗尼亚·恒影的营地旁边。",al={"号角位置","唤醒号角在哪里","克罗尼亚的箱子"}},{q="为什么克罗尼亚需要号角来保持清醒？",a="由于在翡翠梦境中沉睡了漫长的岁月，克罗尼亚难以适应凡人的清醒状态，在旅途中总是会陷入突如其来的深度睡眠。",al={"为什么克罗尼亚在睡觉","他为什么会睡着","翡翠梦境沉睡"}},{q="克罗尼亚要去哪里？",a="他正试图前往灰谷北部的迈斯特拉岗哨，与利拉迪斯·月河汇合。",al={"克罗尼亚的目的地","他要去哪里","迈斯特拉岗哨护送"}}},fp="17,139,26.396.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="埃其亚基的号角",s="埃其亚基的号角是由十字路口的瑟格拉·黑棘提供的一种狩猎工具。在定居点东北方的远古科多兽遗骸处吹响它，就能召唤出“白雾”，即贫瘠之地传说中的白色掠食者。",h="埃其亚基的号角是由十字路口的瑟格拉·黑棘提供的一种狩猎工具。在定居点东北方的远古科多兽遗骸处吹响它，就能召唤出“白雾”，即贫瘠之地传说中的白色掠食者。",kw={"贫瘠之地","十字路口","埃其亚基","号角","科多兽骨骸","瑟格拉·黑棘","白雾"},ang={["class:Hunter"]="对于猎人来说，召唤埃其亚基是一场具有传奇色彩的成年礼，让他们在贫瘠之地最为人称道的、近乎完美的潜行者面前考验自己的感知能力。",["race:Tauren"]="狩猎埃其亚基在牛头人中具有精神意义，他们将这头野兽迅猛且无痛的杀戮视为仁慈与残酷的死亡必然性之间的化身。"},sec={{t="召唤白雾",b="这把号角被授予那些在狩猎中考验自己勇气的初学者。号角的召唤声回荡在热带草原上，唤出埃其亚基——他的名字在牛头人语中译为“白雾”。作为热带草原猫科动物之王，埃其亚基被牛头人猎手尊为仁慈与死亡的化身，他出击迅猛，让猎物在毫无痛苦与恐惧的情况下死去。这把号角只能在巨型掠食者的巢穴处吹响，那是一处位于十字路口东北方山丘后的、被阳光晒得发白的巨型科多兽骨骸巢穴。"}},faq={{q="埃其亚基的号角有什么用？",a="这把号角用于引出埃其亚基，那只难以捉摸的白色草原猫。在十字路口东北方的巨型科多兽骨骸附近吹响号角，会激怒这头野兽并使其现身，让猎人去面对它。",al={"使用埃其亚基的号角","埃其亚基的号角有什么用"}},{q="号角是从哪里来的？",a="瑟格拉·黑棘是一位居住在贫瘠之地十字路口的兽人女猎手，她将这把号角交给那些试图证明自己敏锐度和追踪技巧的冒险者。",al={"谁给予了号角","埃其亚基的号角来源"}},{q="埃其亚基这个名字是什么意思？",a="在牛头人语中，埃其亚基的意思是“白雾”。这个名字是为了纪念这头野兽苍白的皮毛，以及他那种如同迷雾一般悄无声息、能在干草丛中潜行而不被察觉的能力。",al={"埃其亚基的意思","白雾的意思"}},{q="要在哪里吹响号角？",a="号角必须在十字路口东北方山丘后的巨型科多兽肋骨和骨骸遗迹中吹响，那里也是这头白狮的活动领地。",al={"在哪里使用号角","埃其亚基的位置"}}},fp="17,194,21.395.0,35.169.0,30.149.0,34.167.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="巨大的豺狼人爪",s="巨大的豺狼人爪是取自霍格的明确战利品，这只巨大的豺狼人在艾尔文森林的西南部徘徊。它的尺寸远超任何普通的豺狼人爪，是暴风城当局在闪金镇要求的官方死亡证明。",h="巨大的豺狼人爪是取自霍格的明确战利品，这只巨大的豺狼人在艾尔文森林的西南部徘徊。它的尺寸远超任何普通的豺狼人爪，是暴风城当局在闪金镇要求的官方死亡证明。",kw={"悬赏","艾尔文森林","闪金镇","霍格","巨大的豺狼人爪","治安官杜汉","riverpaw"},ang={["class:Hunter"]="获得这种超大型捕食者的爪子，证明了你在面对能轻易压制武装小队的野兽时，拥有顶尖的追踪和狩猎能力。",["faction:Alliance"]="取得这只爪子清除了王国腹地最臭名昭著的林地恐怖，也向治安官杜汉和闪金镇饱受困扰的驻军证明了你的英勇。"},sec={{t="赏金猎人的证明",b="数月以来，野兽霍格一直恐吓着林边空地的南部林区，它无视巡逻队，并且压制了当地驻军所有围捕或制服它的努力。由于在艾尔文森林的兵力不足且处于劣势，暴风城军队悬赏缉拿这头野兽。闪金镇的治安官杜汉在发放赏金前要求提供不可辩驳的证据，而这只野兽超大的爪子就是这片森林的恐怖存在终于倒下的确凿证明。"}},faq={{q="巨大的豺狼人爪有什么用？",a="这只爪子是霍格死亡的官方证明。直接将其带给闪金镇的治安官杜汉即可完成悬赏并领取奖励。",al={"霍格的爪子怎么用","巨大的豺狼人爪用途","谁需要爪子"}},{q="这只爪子是从哪里来的？",a="它直接取自霍格，这是一只在艾尔文森林中林边空地西南边缘的Riverpaw营地附近徘徊的精英豺狼人。",al={"爪子由谁掉落","如何获得巨大的豺狼人爪","哪里可以找到巨大的豺狼人爪"}},{q="为什么治安官杜汉要爪子而不是头颅？",a="即使对豺狼人而言，霍格也异常巨大，它巨大的爪子十分独特且一眼就能认出来。呈交一只爪子让暴风城军队确信这个臭名昭著的掠夺者确实已经被杀死了。",al={"为什么用爪子作为死亡证明","为什么不是霍格的头颅","杜汉悬赏证明"}},{q="如果我弄丢了爪子，还能再得到一个吗？",a="可以。如果你在交给治安官杜汉之前弄丢了爪子，你可以在艾尔文森林西南部再次猎杀霍格来获取替换品。",al={"丢失了巨大的豺狼人爪","能否再次获得爪子","霍格的爪子刷新"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="亨伯特的长剑",s="亨伯特的长剑是塔伦米尔的亡灵卫兵亨伯特私人的随身武器。当他在丹加洛克侦察矮人据点时，这把武器被矮人士兵从他的营地中掠走了。",h="亨伯特的长剑是塔伦米尔的亡灵卫兵亨伯特私人的随身武器。当他在丹加洛克侦察矮人据点时，这把武器被矮人士兵从他的营地中掠走了。",kw={"达萨利亚","亡灵卫兵亨伯特","丹加洛克","希尔斯布莱德","亨伯特的长剑","塔伦米尔"},ang={["faction:Horde"]="取回这把剑与部落针对丹加洛克矮人飞地的更大规模行动相吻合，其中包括收集矮人之血和军事徽章。",["race:Undead"]="高级执行官达萨利亚对希尔斯布莱德的被遗忘者部队保持着残酷的纪律，这让像亨伯特这样失职的哨兵急于掩盖他们的错误。"},sec={{t="侦察兵的大意时刻",b="高级执行官达萨利亚派遣亡灵卫兵亨伯特前往丹加洛克，在一个隐蔽的地点监视矮人的动向。一天早上，当他离开岗位去收集木柴烧水时，一队矮人巡逻兵偶然发现了他的营地，并洗劫了他所有的装备，包括他的私人佩剑。由于矮人数量众多，亨伯特不得不依靠部落特工潜入要塞，取回他丢失的武器。"},{t="矮人的战利品",b="失窃之后，亨伯特的物品被带回了丹加洛克的防御工事后方。由于矮人火枪手、山地巡逻队员和牧师在要塞内分发补给，要找到那个特定的窃贼，就必须搜查驻扎在据点战壕和堡垒中的守军。"}},faq={{q="谁拥有这把剑？",a="这把剑属于亡灵卫兵亨伯特，他是驻扎在塔伦米尔的一名被遗忘者哨兵，被指派去侦察丹加洛克。",al={"这把剑是谁的","亨伯特物主","亨伯特是谁"}},{q="矮人是怎么得到亨伯特的长剑的？",a="亡灵卫兵亨伯特在早上离开了丹加洛克外面的侦察营地去收集木柴。在他离开时，一队矮人巡逻兵洗劫了营地并抢走了他的装备。",al={"矮人是怎么拿到的","为什么矮人会有这把剑","剑是怎么被偷的"}},{q="为什么亨伯特如此迫切地想要回他的剑？",a="亨伯特需要这把武器来完成高级执行官达萨利亚交给他的监视丹加洛克的任务，而且要塞里有那么多的矮人，他不可能独自找到窃贼。",al={"为什么亨伯特想要回剑","如果亨伯特弄丢了剑会怎样","为什么亨伯特那么在意"}},{q="在哪里可以找到这把剑？",a="这把剑被驻扎在丹加洛克的矮人部队所持有，该据点位于希尔斯布莱德丘陵的东南部。可以从驻扎在据点各处的山地巡逻队员、火枪手或牧师身上取回。",al={"这把剑在哪里掉落","剑的位置","如何找到亨伯特的长剑"}}},fp="15,162,25.384.0,17.241.0,20.116.0,40.156.0,50.157.0,29.181.0"}
P.entries["item:hyacinth-mushroom"] = {n="紫蓝色蘑菇",s="紫蓝色蘑菇是一种独特的真菌，生长在泰达希尔幽影谷各处的树根旁。它们不仅因其药用价值而受到当地暗夜精灵草药师的青睐，同时也深受顽皮的格里尔和格里尔小鬼的喜爱，被视为它们的食物和储备粮。",h="紫蓝色蘑菇是一种独特的真菌，生长在泰达希尔幽影谷各处的树根旁。它们不仅因其药用价值而受到当地暗夜精灵草药师的青睐，同时也深受顽皮的格里尔和格里尔小鬼的喜爱，被视为它们的食物和储备粮。",kw={"解毒剂","迪兰妮亚·月光","格里尔","格里尔小鬼","紫蓝色蘑菇","埃沃隆","幽影谷","泰达希尔"},ang={["profession:Herbalism"]="虽然在幽影谷采集这些真菌不需要正式的训练，但任何初出茅庐的草药师都会重视它们在中和剧毒森林毒素方面的作用。",["race:NightElf"]="对于在幽影谷内训练的年轻暗夜精灵来说，采集紫蓝色蘑菇等野生植物是他们学习利用自然恩赐来维持族人生活的第一课。"},sec={{t="幽影谷的植物",b="紫蓝色蘑菇在幽影谷随处可见，在树根底部、苔藓覆盖的岩石旁以及奥达希尔那蔓延的根系所形成的潮湿阴影中生长繁茂。虽然它们在丛林药剂中很有用，但也引起了被腐蚀的格里尔的注意，这些生物经常囤积它们。当年轻的暗夜精灵哨兵或学员受到当地有毒动物（如黑丝洞中的蜘蛛）的伤害时，这些蘑菇便是森林治疗者配制的舒缓药水和抗毒剂的核心成分。"}},faq={{q="紫蓝色蘑菇有什么用途？",a="迪兰妮亚·月光用它们作为一种关键成分来配制解毒剂，用于救治埃沃隆，这是一位在探索黑丝洞时被毒蜘蛛咬伤中毒的年轻暗夜精灵。",al={"紫蓝色蘑菇用途","它有什么用","埃沃隆的解药"}},{q="紫蓝色蘑菇生长在哪里？",a="它们直接生长在泰达希尔幽影谷这片与世隔绝的山谷中，大树的树干和根部附近，以及巨石旁边。",al={"蘑菇位置","哪里可以找到紫蓝色蘑菇","幽影谷的蘑菇"}},{q="为什么格里尔会携带紫蓝色蘑菇？",a="在幽影谷南部肆虐的顽皮格里尔和格里尔小鬼对这种蘑菇情有独钟，它们会在营地里采集并囤积这些蘑菇。",al={"格里尔掉落蘑菇","为什么格里尔有蘑菇","格里尔小鬼的蘑菇"}},{q="紫蓝色蘑菇本身有毒吗？",a="没有。尽管它们外观鲜艳，且生长在阴暗的环境中，但当地治疗者可以安全地将它们用作治疗膏药和恢复性抗毒剂的成分。",al={"紫蓝色蘑菇有毒吗","有毒蘑菇"}}},fp="17,163,19.345.0,37.158.0,33.120.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="超适应齿轮",s="超适应齿轮是一件从千针石林的峡谷底部回收的奇特工程学装置。它曾悬挂在废弃大篷车中一头被关在笼子里的野兽脖子上，即使对于声称拥有它的修补匠来说，它真正的用途仍然是个谜。",h="超适应齿轮是一件从千针石林的峡谷底部回收的奇特工程学装置。它曾悬挂在废弃大篷车中一头被关在笼子里的野兽脖子上，即使对于声称拥有它的修补匠来说，它真正的用途仍然是个谜。",kw={"半人马","狂暴的黑豹","齿轮","超适应","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="帮助白沙岗哨的旅行者们协助清除了具有攻击性的半人马，并从散落在峡谷底部的废弃大篷车中找回了丢失的奇珍异宝。",["profession:Engineering"]="这个小玩意儿代表了经典的地精工程学：一个结构复杂、名字听起来很危险的装置，在还没人费心去决定它该干什么之前，就凭着巨大的热情被制造了出来。"},sec={{t="大篷车的奇异遗物",b="当半人马掠夺者伏击了一支经过千针石林的地精大篷车队时，他们掠夺了视线所及的几乎所有东西。唯一的幸存者维兹罗爬到了白沙岗哨安全脱身，却丢下了他最好的装置：超适应齿轮。奇怪的是，这个小玩意儿不知怎么被系在了一头关在运输笼里、愤怒狂暴的黑豹脖子上。袭击的半人马对那头野兽十分恐惧，以至于在燃烧的残骸中完全没有动那个笼子，无意中保护了维兹罗这个奇怪的机器。"},{t="盲目的修补",b="虽然维兹罗自豪地称该装置是他最好的小玩意儿，但在找回它时他也承认，他根本不知道这东西到底是干什么用的。和许多地精装置一样，超适应齿轮是一团野心和不稳定零件的纠结体，注定会让它的主人忙于无休止的修补，而不是发挥什么实际的、为人所知的功用。"}},faq={{q="什么是超适应齿轮？",a="这是一件属于地精维兹罗的工程学装置。尽管名字响亮，但即使是维兹罗本人也不知道它有什么功能，他打算花时间研究它以弄清楚它的用途。",al={"什么是齿轮","超适应","齿轮有什么用"}},{q="这个装置是怎么戴到黑豹脖子上的？",a="维兹罗的大篷车在千针石林北部遭到半人马的袭击和洗劫。混乱中，该装置被系在了一头关在旅行笼中、处于狂暴状态的黑豹脖子上，这使得迷信的半人马不敢掠夺它。",al={"为什么黑豹有齿轮","黑豹是怎么得到的"}},{q="谁想要回超适应齿轮？",a="在大篷车遇袭后的唯一幸存者维兹罗想要回它。他目前在白沙岗哨避难，那是一个位于千针石林西北部的牛头人营地。",al={"谁需要齿轮","维兹罗的齿轮"}},{q="为什么半人马没有偷走它？",a="半人马洗劫了整个大篷车，但非常害怕笼子里那头凶猛的黑豹。他们在废墟中完全没有动那头野兽和它脖子上的金属项圈。",al={"为什么半人马没拿走","半人马和黑豹"}}},fx={["240fe489"]={q="超适应齿轮来自哪里？是谁制作的？",a="这件装置原本由地精技师维兹罗持有。他当时正乘坐商队穿越千针石林，途中遭到半人马伏击。维兹罗称它是自己最珍爱的齿轮装置，但它的确切发明者仍是个谜——就连维兹罗也承认，他并不完全明白这台奇特机器究竟有什么用途。",al={"谁制作了超适应齿轮","超适应齿轮的来历","维兹罗从哪里得到超适应齿轮"}}},fp="20,258,25.548.0,21.349.0,33.224.0,50.250.0,40.173.0,32.179.0"}
P.entries["item:ignition-key"] = {n="打火钥匙",s="打火钥匙是荆棘谷地精在淤泥沼泽的钻探作业区中，由卢格维兹主管随身携带的一把关键控制钥匙。它被用于解锁转向柱并启动一台高级荆棘谷地精伐木机的控制系统。",h="打火钥匙是荆棘谷地精在淤泥沼泽的钻探作业区中，由卢格维兹主管随身携带的一把关键控制钥匙。它被用于解锁转向柱并启动一台高级荆棘谷地精伐木机的控制系统。",kw={"打火钥匙","伐木机","淤泥沼泽","斯布特瓦夫","卢格维兹主管","荆棘谷地精","维兹克拉克"},ang={["profession:Engineering"]="这把钥匙可以解锁一台拥有极其先进控制机制的伐木机，其速度调节和精细的机械臂铰接功能都远超普通的地精设计。"},sec={{t="间谍活动的缺失环节",b="当棘齿城的斯布特瓦夫派遣特工从淤泥沼泽窃取一台荆棘谷地精专有的伐木机时，事情并没有那么顺利。卧底飞行员维兹克拉克设法溜进了机器的驾驶舱，却发现它的运动控制柱完全被锁住了。为了不引起多疑工头的注意，他假装机器出了机械故障，等待着冒险者去取回必要的打火钥匙。这把钥匙目前被卢格维兹主管锁在中央采油井架的顶端，它控制着机器最先进的机械臂、速度和旋转机制。"}},faq={{q="在哪里可以找到打火钥匙？",a="这把钥匙由卢格维兹主管保管，他在淤泥沼泽采油井架顶部的控制室里监督钻探工作。",al={"打火钥匙位置","谁掉落打火钥匙","如何获取打火钥匙"}},{q="为什么维兹克拉克需要这把特定的钥匙？",a="与更简单的工程设备不同，这台高级荆棘谷地精伐木机有一个锁定的运动控制柱。没有合适的打火钥匙，飞行员就无法调节旋转、速度、稳定性和机械臂控制装置来将其开走。",al={"为什么需要钥匙","钥匙有什么用","伐木机钥匙用途"}},{q="是谁想要窃取这台伐木机？",a="驻扎在棘齿城的地精工程师斯布特瓦夫组织了这次行动，想要搞到荆棘谷地精那套优越的工程设计方案。",al={"谁派遣了维兹克拉克","为什么要偷伐木机","棘齿城伐木机"}},{q="钥匙交付后会发生什么？",a="一旦钥匙解锁了运动控制柱，维兹克拉克就会发动伐木机的引擎，并必须在淤泥沼泽敌对的劳工中进行绝望的冲刺，以逃往棘齿城。",al={"交还钥匙后","逃脱","接下来做什么"}}},fp="12,203,28.502.0,36.136.0,44.189.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="伊克鲁德·玛格苏尔之书",s="伊克鲁德·玛格苏尔之书是一本从灰谷腐化深处的一名危险兽人术士手中夺回的魔典。在将其交给净化者德尔格伦后，其邪恶的内容揭示了奥萨拉克斯之塔中邪教徒们更广泛的阴谋活动。",h="伊克鲁德·玛格苏尔之书是一本从灰谷腐化深处的一名危险兽人术士手中夺回的魔典。在将其交给净化者德尔格伦后，其邪恶的内容揭示了奥萨拉克斯之塔中邪教徒们更广泛的阴谋活动。",kw={"灰谷","净化者德尔格伦","火痕神殿","伊克鲁德·玛格苏尔","迈斯特拉岗哨","之书","奥萨拉克斯之塔","术士"},ang={["class:Paladin"]="回收这本之书有助于帮助德尔格伦兄弟，他是一位圣光的战士，在灰谷这片未被驯服的荒野中警惕地对抗着阴影和腐化。",["class:Warlock"]="玛格苏尔的魔典是一份珍贵的黑暗契约记录，详细记载了在被污染的火痕神殿对虚空行者和魅魔的奴役。"},sec={{t="一本魔典：腐蚀术",b="伊克鲁德·玛格苏尔是一位盘踞在灰谷西南部火痕神殿的强大兽人术士，该地点受到残留的恶魔影响而被腐化。在召唤出的仆从环绕下，玛格苏尔将他邪恶的仪式和阴暗的通讯记录在这本个人之书中。虽然银色黎明的圣骑士净化者德尔格伦早已知晓这名术士的存在，但玛格苏尔与聚集在奥萨拉克斯之塔的黑暗邪教徒之间被发现的联系，使得回收这本书成为了一项紧迫的任务。"},{t="揭开邪教的面纱",b="在从玛格苏尔的尸体上夺回这本之书后，它被送到了迈斯特拉岗哨交给德尔格伦。德尔格伦试图破译这名术士的文字，以了解在黑海岸和灰谷边界协调恶魔活动的网络。这份文本提供了关于在北卡利姆多扎根的腐化背后操纵一切的阴暗同谋者的重要情报。"}},faq={{q="谁拥有这本之书？",a="这本书属于伊克鲁德·玛格苏尔，他是一位强大的兽人术士，在灰谷西南部火痕神殿的恶魔废墟中占据了一席之地。",al={"伊克鲁德·玛格苏尔是谁","谁写了这本书","伊克鲁德·玛格苏尔"}},{q="在哪里可以找到这本之书？",a="它是直接从位于灰谷艾森娜神殿南部的火痕神殿中的伊克鲁德·玛格苏尔身上回收的。",al={"之书位置","如何获得这本之书","在哪里找到伊克鲁德"}},{q="净化者德尔格伦为什么要这本书？",a="德尔格伦试图研究玛格苏尔的文字，以揭开将当地恶魔崇拜者与居住在奥萨拉克斯之塔的邪教徒联系起来的黑暗纽带。",al={"德尔格伦为何需要这本之书","之书内容","德尔格伦的研究目的"}},{q="回收这本之书后会发生什么？",a="德尔格伦在迈斯特拉岗哨检查了这些文本，以破译玛格苏尔的恶魔通讯，并确定瓦解该邪教网络的下一步行动。",al={"上交之书","德尔格伦如何处理这本书"}}},fp="23,157,24.455.0,19.353.1,19.143.0,24.109.0,44.147.0,41.150.0"}
P.entries["item:incantations-from-the-nether"] = {n="扭曲虚空的魔法",s="“扭曲虚空的魔法”是一本恶魔魔法禁书，由潜伏在奥格瑞玛地下的灼热之刃邪教徒所持有。希尔瓦娜斯·风行者和她的恐惧魔王副官瓦里玛萨斯企图夺取这本书，以便为被遗忘者掌握其中的邪能知识。",h="“扭曲虚空的魔法”是一本恶魔魔法禁书，由潜伏在奥格瑞玛地下的灼热之刃邪教徒所持有。希尔瓦娜斯·风行者和她的恐惧魔王副官瓦里玛萨斯企图夺取这本书，以便为被遗忘者掌握其中的邪能知识。",kw={"扭曲虚空的魔法","怒焰裂谷","灼热之刃","暗影议会","暗影法术研究","希尔瓦娜斯","毁灭的力量","瓦里玛萨斯"},ang={["class:Warlock"]="直接从扭曲虚空获取的法术书蕴含着强大的邪能魔法，任何有野心的黑暗艺术修行者都会对此垂涎三尺。",["race:Undead"]="回收这本书直接有助于黑暗女王在幽暗城的核心圈子收集发动对天灾军团战争所需的黑暗知识。"},sec={{t="军团的赠礼",b="在奥格瑞玛红色的石板街道之下，一个隶属于暗影议会的地下邪教组织——灼热之刃，正在怒焰裂谷的火热隧道中活动。在他们最黑暗的宝藏中，有一本名为“扭曲虚空的魔法”的法术书，书中记载了由燃烧军团的代理人所传授的恶魔仪式。当这些邪教徒利用书中的卑劣秘密在兽人首都策划叛乱时，关于这本书的消息已经传过重洋，到达了幽暗城的皇室区域。"},{t="被遗忘者的野心",b="对于希尔瓦娜斯·风行者女士和恐惧魔王瓦里玛萨斯来说，如此强大的邪能遗物若是被他们眼中目光短浅的邪教徒所拥有，简直是暴殄天物。瓦里玛萨斯派遣忠诚的部落冒险者深入怒焰裂谷，去回收这本“扭曲虚空的魔法”，以及它的姊妹篇“暗影法术研究”。黑暗女王打算利用这本书中锻造自虚空的力量来达成她终极的十字军远征：摧毁巫妖王，并向天灾军团复仇。"}},faq={{q="在哪里可以找到“扭曲虚空的魔法”这本书？",a="这本书由潜伏在怒焰裂谷（奥格瑞玛城下方的火山洞穴网络）中的灼热之刃邪教徒和术士所携带。",al={"如何获得扭曲虚空的魔法","谁掉落扭曲虚空的魔法","扭曲虚空的魔法位置"}},{q="谁想要这本书，为什么要得到它？",a="恐惧魔王瓦里玛萨斯和希尔瓦娜斯·风行者女士正在寻找这本书。他们认为像这样的恶魔赠礼被浪费在灼热之刃那些琐屑的邪教徒手中实在是可惜，并希望利用其中的黑暗魔法来对付他们的宿敌——巫妖王。",al={"谁需要扭曲虚空的魔法","希尔瓦娜斯为什么要这本书","瓦里玛萨斯的书籍任务"}},{q="灼热之刃是什么组织？",a="灼热之刃是一个在奥格瑞玛地下活动的术士与邪教徒秘密集会，与暗影议会结盟。他们效忠于燃烧军团，在暗处活动以破坏萨尔领导的新部落。",al={"灼热之刃背景故事","谁是灼热之刃"}},{q="还有哪本书与这本书配套？",a="瓦里玛萨斯需要两本书：“扭曲虚空的魔法”以及另一本名为“暗影法术研究”的魔法禁书。为了完成他的任务，这两本书都必须从怒焰裂谷的邪教徒手中夺取。",al={"瓦里玛萨斯的另一本书","毁灭书籍的力量"}}},fp="28,182,19.393.0,17.378.1,53.116.0,28.207.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="火岩龙舌兰",s="火岩龙舌兰是一种稀有的带刺水生植物，原产于千针石林黑云峰下方的沸腾之池。当被熟练的萨满祭司附魔后，其独特的属性便能点燃圣洁的生命之火。",h="火岩龙舌兰是一种稀有的带刺水生植物，原产于千针石林黑云峰下方的沸腾之池。当被熟练的萨满祭司附魔后，其独特的属性便能点燃圣洁的生命之火。",kw={"阿莉卡拉","沸腾之池","黑云峰","火岩龙舌兰","玛加萨·野性图腾","圣洁之火","千针石林"},ang={["class:Shaman"]="这种龙舌兰需要原始的萨满元素工艺，才能从一种水生多肉植物转化为足以点燃神圣仪式火焰的强力粉末。",["profession:Herbalism"]="草药师们会发现，他们的追踪感官对于寻找隐藏在沸腾之池浑浊池底的一簇簇带刺的火岩龙舌兰至关重要。"},sec={{t="一种稀有的沙漠草药",b="火岩龙舌兰生长在千针石林沸腾之池的水中及其周围，在黑云峰的阴影下茁壮成长。由于受到游荡的蒸汽元素生物的天然守护，这种植物很难采集，在整个卡利姆多也十分稀有。尽管它是浸没在水中生长的，但它却蕴含着可以直接用于火焰仪式的强大自然元素。"},{t="圣洁之火",b="牛头人祭司知道，沉寂的圣洁生命之火不能单靠普通的火星来点燃。雷霆崖长者高地的玛加萨·野性图腾掌握着所需的萨满知识，可以将采集到的火岩龙舌兰束转化为神秘的粉末。这种粉末一旦准备就绪，便能点燃召唤复仇的风蛇阿莉卡拉所需的仪式火盆。"}},faq={{q="火岩龙舌兰生长在哪里？",a="火岩龙舌兰生长在千针石林北部黑云峰下方的沸腾之池及其周围的湖泊中。大部分植株都可以在水下的湖床上找到。",al={"在哪里可以找到龙舌兰","火岩龙舌兰位置","龙舌兰在哪里"}},{q="火岩龙舌兰有什么用途？",a="收集十束龙舌兰可以制成一种仪式粉末。在雷霆崖经由玛加萨·野性图腾附魔后，这种粉末可用于点燃圣洁的生命之火并召唤风蛇阿莉卡拉。",al={"火岩龙舌兰用途","为什么要采集龙舌兰","龙舌兰有什么作用"}},{q="谁能为火岩龙舌兰附魔？",a="玛加萨·野性图腾，这位居住在雷霆崖长者高地上颇具影响力的萨满，拥有将萨满魔法编织进原始植物材料中的仪式专长。",al={"谁来给龙舌兰附魔","玛加萨 龙舌兰","谁把龙舌兰变成粉末"}},{q="火岩龙舌兰周围有什么威胁？",a="沸腾之池的水域和岸边有充满敌意的蒸汽元素生物游荡，它们对冰霜和火焰法术有着极高的抗性。",al={"龙舌兰危险","什么守护着龙舌兰","沸腾之池的危险"}}},fp="14,136,18.287.0,15.305.1,31.165.0,32.171.0,35.124.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="火岩粉",s="火岩粉是一种经过附魔的仪式催化剂，用于点燃圣火。部落的使者将这种粉末带入千针石林，粉末经过萨满咒语的特殊处理，旨在唤醒黑云峰顶沉睡的灵兽阿里卡拉。",h="火岩粉是一种经过附魔的仪式催化剂，用于点燃圣火。部落的使者将这种粉末带入千针石林，粉末经过萨满咒语的特殊处理，旨在唤醒黑云峰顶沉睡的灵兽阿里卡拉。",kw={"阿里卡拉","黑云峰","火岩粉","莫特加·火鬃","生命圣火","千针石林","白沙岗哨"},ang={["class:Shaman"]="这种粉末展示了元素之火与精神结界是如何结合在一起，从而唤醒沉睡的先祖实体的。",["race:Tauren"]="使用仪式粉末点燃葬火，反映了尊崇神圣传统与保卫部落首领之间的微妙平衡。"},sec={{t="召唤之火花",b="火岩粉并非普通的爆炸物或闪光粉；它是一种经过净化的仪式性物质，小心地注入了萨满魔法。这种混合物由雷霆崖长者高地的玛加萨·野性图腾附魔并托付给旅者，专门设计用于与黑云峰孤立尖塔顶端沉睡的生命圣火发生反应。一旦撒在安放逝者的神圣火盆上，其炼金术与精神结界便会召唤出复仇的翼蛇阿里卡拉。"},{t="不安的征兆",b="制造和使用火岩粉的仪式源自萨满长者玛加萨·野性图腾的解读。她认为传统的改变和牛头人习俗的变迁激怒了远古灵魂，导致它们开始追猎大酋长凯恩·血蹄，因此这种粉末被赋予了魔法，以强迫这种幽灵现身并将其消灭。虽然成功召唤出了这条凶猛的巨蛇，但这场激烈的冲突却留下了令人不安的疑问：这头野兽究竟为何苏醒。"}},faq={{q="火岩粉有什么用途？",a="火岩粉是一种经过附魔的粉末，撒入千针石林黑云峰顶的生命圣火中。用这种混合物点燃圣火可以召唤出复仇的灵蛇阿里卡拉。",al={"火岩粉用途","为什么需要火岩粉","火岩粉的作用"}},{q="是谁为这种粉末注入了附魔？",a="在白沙岗哨的莫特加·火鬃传回关于阿里卡拉的消息后，玛加萨·野性图腾在雷霆崖的长者高地上将收集来的火岩龙舌兰炼制并附魔成了火岩粉。",al={"谁制造了火岩粉","谁给火岩粉附魔"}},{q="这种粉末需要在哪里使用？",a="它必须撒入黑云峰内一座孤立的墓葬石柱顶端的圣火坑中，那里高耸于千针石林的盐碱峡谷之上。",al={"火岩粉位置","在哪里投掷火岩粉","在哪里使用火岩粉"}},{q="为什么要召唤阿里卡拉？",a="玛加萨·野性图腾担心牛头人传说的改变激怒了阿里卡拉，并担心这条蛇可能正在跟踪凯恩·血蹄。她要求召唤并杀死阿里卡拉，以防凯恩受到伤害。",al={"为什么要召唤阿里卡拉","为什么要与阿里卡拉战斗"}}},fp="15,165,20.289.0,15.354.1,33.166.0,43.168.0,38.153.0,36.196.0"}
P.entries["item:insane-scribbles"] = {n="令人发狂的书页",s="这些令人发狂的书页是从令人困惑的暮光宝典上撕下来的，是黑海岸的邪教徒所携带的黑暗文献碎片。仅仅是注视着那些跳动的文字和扭曲的卷轴装饰，就会引发严重的眩晕和精神紧张。森林的古老保护者们研究这些碎片，以破译暮光之锤邪恶的动机。",h="这些令人发狂的书页是从令人困惑的暮光宝典上撕下来的，是黑海岸的邪教徒所携带的黑暗文献碎片。仅仅是注视着那些跳动的文字和扭曲的卷轴装饰，就会引发严重的眩晕和精神紧张。森林的古老保护者们研究这些碎片，以破译暮光之锤邪恶的动机...",kw={"黑海岸","令人发狂的书页","疯狂","上古之神","奥努","暮光宝典","暮光之锤"},ang={["class:Priest"]="对精神攻击和虚空能量敏感的牧师会认出这些扭曲的文字是一种危险的疯狂体现，直接与圣光的清明相对立。",["race:NightElf"]="对于暗夜精灵来说，暮光之锤的遗物是对黑海岸古老和平与神圣土地的一种腐蚀性威胁。"},sec={{t="一份令人发狂的手稿",b="凝视暮光宝典的页面对凡人的理智而言是极度危险的。文字在羊皮纸上扭动，优美的卷轴花纹在读者眼前变形为怪诞、令人不安的意象。撕下一张书页——即这些令人发狂的书页——都是一种折磨，会让持有者感到头晕目眩、失去方向感。尽管文字杂乱无章，但羊皮纸本身却散发着一种原始、极为古老的魔法，这种魔法直接与长久以来埋藏在艾泽拉斯地下的黑暗力量相连。"},{t="给古树的线索",b="当这些书页被带到奥努——那位主持古树之林的受人尊敬的古树面前时，它们揭示了困扰黑海岸的入侵行径。奥努认出附着在羊皮纸上的混沌能量正是上古之神的杰作。对于卡利姆多的守卫者们来说，拼凑起这些书页是揭开暮光之锤为何聚集在这些雾气笼罩的海岸线上的关键一步。"}},faq={{q="如果你试图阅读这些书页会发生什么？",a="这些文字难以解读。仅仅是看一眼羊皮纸，就会导致字母游动，周围的图案变形为恐怖的形状，使得任何试图解读它们的人感到突如其来的眩晕和精神疲惫。",al={"阅读令人发狂的书页","文字写了什么","你能阅读这些书页吗"}},{q="这些书页是从哪里撕下来的？",a="它们是从暮光宝典中撕下来的，那是一本由在黑海岸活动的暮光之锤邪教徒所持有的邪恶法术书。",al={"书页来自哪里","暮光宝典的起源"}},{q="谁能理解或研究这些书页？",a="知识古树奥努检查了这些找回的羊皮纸。凭借数个世纪的知识积累，奥努感知到了束缚着墨迹的古老原始魔法，并试图确定该邪教在该地区的意图。",al={"谁想要这些书页","奥努与书页"}},{q="羊皮纸散发出什么样的力量？",a="羊皮纸跳动着与上古之神相连的混沌、原始的魔法，反映了暮光之锤所崇拜的黑暗神灵。",al={"书页中蕴含什么魔法","魔法类型"}}},fp="16,270,22.417.0,22.358.1,48.217.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="刻字的树皮",s="刻字的树皮是一份活的羊皮纸，由古老的The Oracle Tree委托，负责将泰达希尔的状况传达给大德鲁伊范达尔·鹿盔。它是一份关于世界之树枝干状况及其林中挥之不去威胁的正式报告。",h="刻字的树皮是一份活的羊皮纸，由古老的The Oracle Tree委托，负责将泰达希尔的状况传达给大德鲁伊范达尔·鹿盔。它是一份关于世界之树枝干状况及其林中挥之不去威胁的正式报告。",kw={"塞纳里奥议会","达纳苏斯","范达尔·鹿盔","刻字的树皮","神谕之树","泰达希尔"},ang={["class:Druid"]="德鲁伊们认为这种刻字木片是来自古老盟友的紧急快报，凸显了困扰这棵年轻世界之树的微妙平衡与持续存在的苦难。",["race:NightElf"]="对于卡多雷来说，承载在古树树皮上的信息代表了自然与守护者之间神圣的纽带，架起了野生树林与达纳苏斯大理石露台之间的桥梁。"},sec={{t="来自神谕者的信息",b="这块刻字的树皮取自The Oracle Tree的神圣木材，充当了这位古老守护者与达纳苏斯的塞纳里奥议会领导层之间的直接通讯媒介。在冒险者清理了林间空地中不断侵袭的鹰身人之后，The Oracle Tree将此信物托付给他们，因为它不愿让普通的信使冒着危险穿过受到污染的林木小径。这封刻字信件告知大德鲁伊范达尔·鹿盔，既有近期的胜利，也有继续笼罩着泰达希尔的、更深层且令人不安的枯萎病。"}},faq={{q="什么是刻字的树皮？",a="这是一块由The Oracle Tree刻写的树皮，包含了一份关于枝干健康状况和危险的报告，旨在送交达纳苏斯的大德鲁伊范达尔·鹿盔。",al={"什么是刻字的树皮","神谕之树的树皮","刻字的树皮的用途"}},{q="谁发送了这条信息，为什么要发？",a="The Oracle Tree在冒险者将鹰身人赶出巢穴后将其托付给他们。由于担心派普通信使穿越危险的森林小径，这位古老的存在选择委托一位可靠的旅行者来传递其报告。",al={"谁写了刻字的树皮","谁给予了刻字的树皮","神谕之树的信使"}},{q="大德鲁伊范达尔·鹿盔对这条信息有何反应？",a="范达尔认可了清除鹰身人所带来的喘息机会，但沮丧地指出更深层的问题依然存在。这份报告加深了他心中挥之不去的焦虑，即他在泰达希尔所做的工作是否真的能恢复暗夜精灵失去的不朽。",al={"范达尔对树皮的反应","范达尔对树皮说了什么"}}},fp="14,189,25.340.0,23.140.0,31.202.0,58.213.1"}
P.entries["item:intact-raptor-horn"] = {n="完整的迅猛龙角",s="这是一根从潜伏在贫瘠之地稀树草原上的掠食迅猛龙身上采集的完好犄角。它保存得非常完好，正被一名想要利用迅猛龙智力传闻的创业型地精所垂涎。",h="这是一根从潜伏在贫瘠之地稀树草原上的掠食迅猛龙身上采集的完好犄角。它保存得非常完好，正被一名想要利用迅猛龙智力传闻的创业型地精所垂涎。",kw={"完好的犄角","伊萨姆哈尔","麦伯克·米希瑞克斯","迅猛龙犄角","棘齿城","智力饮料","日光镰爪龙","塔克勒"},ang={["class:Hunter"]="想要获得完整的战利品犄角，需要一次精准的击杀，这证明了你在面对稀树草原上最凶猛的掠食者时依然能保持精准。",["profession:Cooking"]="虽然麦伯克计划将这些犄角粉碎用于酒类浸泡，但实际的生存专家知道，迅猛龙的身体部位通常更适合用于制作工具，而不是作为美味佳肴。"},sec={{t="可疑的配料",b="虽然普通的猎人看重迅猛龙身上的皮、爪和战利品，但在野外很难获得完整的犄角。在棘齿城的港口小镇，一位名叫麦伯克·米希瑞克斯的古怪地精炼金术师对当地野生动物提出了一个狂野的理论：因为贫瘠之地的迅猛龙表现出了超越其他地区同类的狡猾，他怀疑它们的智力就储存在头部的犄角里。通过将完整的犄角研磨并酿造成滋补药剂，麦伯克试图将这种所谓的“天才”装进瓶子里，作为商业“智力饮料”出售。"},{t="跟踪兽群",b="完好的犄角不能简单地从任何幼兽身上敲下来。为了获取可用于酿造的有效材料，猎人必须从特别凶猛的掠食者身上获取，例如那些在南部平原和灰谷附近的北部边界徘徊的日光镰爪龙。稀树草原上著名的传奇恐怖生物，例如塔克勒和难以捉摸的伊萨姆哈尔，也长着足够结实的犄角，能够在狩猎的冲突中保持完好。"}},faq={{q="谁想要这些完好的迅猛龙犄角？",a="驻扎在棘齿城的地精商人和立志成为酿酒师的麦伯克·米希瑞克斯正在寻找它们。他相信完整的犄角是他下一个快速致富产品的关键。",al={"谁需要迅猛龙犄角","犄角买家","谁在购买迅猛龙犄角"}},{q="为什么犄角必须是完好的？",a="麦伯克打算把它们磨成细粉供人食用。被磨损、碎裂或折断的犄角要么在狩猎过程中被丢弃，要么被视为废料，缺乏地精希望在他的配方中利用的全部效力。",al={"为什么需要完好","破碎的犄角"}},{q="哪些迅猛龙长有这种犄角？",a="它们主要存在于徘徊在贫瘠之地南北极端的成年日光镰爪龙身上，以及像伊萨姆哈尔和塔克勒这样臭名昭著的独特迅猛龙身上。",al={"犄角在哪里掉落","哪些迅猛龙","谁掉落完好的犄角"}},{q="迅猛龙犄角真的能让人变聪明吗？",a="虽然贫瘠之地的迅猛龙以不同寻常的群体狡诈和协调能力而闻名，但认为它们的智力储存在犄角里——或者可以通过饮料转移——只是一个未经证实的地精阴谋。",al={"智力饮料有效吗","迅猛龙聪明吗","迅猛龙智力"}}},fp="18,161,25.396.0,19.326.0,36.151.0,35.203.0,25.175.0,42.161.0"}
P.entries["item:intrepid-strongbox-key"] = {n="无畏号的保险箱钥匙",s="无畏号的保险箱钥匙是一把锈铁钥匙，曾经被联盟遭难船只“无畏号”的指挥官哈林多尔船长视若珍宝。即使在死后，船长依然紧紧攥着它，锁住了那个为他在湿地海岸附近的船员带来毁灭的被诅咒的神器。",h="无畏号的保险箱钥匙是一把锈铁钥匙，曾经被联盟遭难船只“无畏号”的指挥官哈林多尔船长视若珍宝。即使在死后，船长依然紧紧攥着它，锁住了那个为他在湿地海岸附近的船员带来毁灭的被诅咒的神器。",kw={"哈林多尔船长","被诅咒的船员","戈罗林·钢眉","无畏号","沉船","保险箱","第三舰队","湿地"},ang={["class:Priest"]="这把钥匙开启的是一件充满了邪恶死灵能量的神器，需要米奈希尔港的牧师戈罗林·钢眉进行圣洁仪式才能净化，让船员们的灵魂得到安息。",["faction:Alliance"]="这把钥匙曾属于联盟第三舰队的一位指挥官，这支舰队在米奈希尔港海岸外的悲惨失事，至今仍是港口幸存者们心中难以愈合的伤口。"},sec={{t="船长的秘密",b="在第三舰队于湿地风暴肆虐的海岸发生海难时，战舰“无畏号”被毁，船员们也被扭曲成了躁动不安的被诅咒的灵魂。哈林多尔船长痴迷地守护着存放在船上沉重保险箱里的神秘物品。在死亡后，他那幽灵般的身影继续在浸水的甲板上徘徊，拒绝交出那把开启船舱最深处、最黑暗货物的锈铁钥匙。"},{t="打破枷锁",b="从哈林多尔船长手中夺取钥匙是打开“无畏号”被锁住的保险箱，并取回导致船员们饱受折磨的被诅咒遗物的唯一途径。只有用这把钥匙找回该物品，才能将其交给米奈希尔港的矮人牧师戈罗林·钢眉进行净化。"}},faq={{q="谁携带无畏号的保险箱钥匙？",a="这把钥匙由哈林多尔船长持有，这位幽灵指挥官就在湿地西北海岸外的一艘北部沉船的上层甲板上来回踱步。",al={"谁有钥匙","无畏号钥匙掉落","哈林多尔钥匙"}},{q="无畏号的保险箱钥匙可以打开什么？",a="它能解锁“无畏号”上锁的保险箱，该保险箱沉没在沉船船长甲板下破裂的船体内。",al={"它能打开什么","无畏号保险箱位置","箱子在哪里"}},{q="为什么保险箱要一直锁着？",a="哈林多尔船长将一件黑暗、被诅咒的物体锁在箱子里，以确保它隐蔽且安全。在舰队沉没后，其残留的邪恶力量将船员们束缚在了不死状态。",al={"箱子里有什么","为什么要锁住它"}},{q="谁能净化箱子里被诅咒的物品？",a="居住在米奈希尔港的矮人牧师戈罗林·钢眉拥有净化被诅咒神器所需的圣洁知识，一旦箱子被打开，他就能进行净化。",al={"谁来净化它","戈罗林·钢眉箱子"}}},fx={b4277111={q="什么是无畏号的保险箱钥匙？",a="这是一把生锈的船钥匙，由船长哈林多尔保管在沉船无畏号上。即使死后，这位被诅咒的船长仍严密看守着钥匙，因为它是打开船体残骸中那只加固保险箱的唯一办法。",al={"无畏号的保险箱钥匙","这把钥匙是什么","无畏号钥匙"}},["90ec2e74"]={q="为什么需要无畏号的保险箱钥匙？",a="必须用这把钥匙打开无畏号的保险箱，取回锁在里面的黑暗遗物。大副菲兹莫斯认为，这件被藏起来的物品招致了可怕的诅咒，使哈林多尔和他的船员被束缚在沉船上。打开箱子是解除诅咒的第一步。",al={"为什么需要这把钥匙","为什么要拿到这把钥匙","无畏号钥匙的用途"}}},fp="22,197,18.283.0,17.210.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="隐形水",s="隐形水是一种烈性药剂，通过炼金术注入魔法，采用在艾尔文森林中发现的罕见水晶海藻叶酿造而成。它能在短时间内让饮用者隐身，是让这对苦命鸳鸯避开家族争斗的秘密计划的关键。",h="隐形水是一种烈性药剂，通过炼金术注入魔法，采用在艾尔文森林中发现的罕见水晶海藻叶酿造而成。它能在短时间内让饮用者隐身，是让这对苦命鸳鸯避开家族争斗的秘密计划的关键。",kw={"水晶海藻","艾尔文森林","隐形水","梅贝尔·马科伦","斯通菲尔德家族世仇","逃离","托米·乔·斯通菲尔德"},ang={["class:Mage"]="虽然肯瑞托的奥术师们花费数年时间完善幻象和隐形法术，但艾尔文的当地人却用发酵的烈酒和被水浸泡的海藻，搞出了一种粗糙的仿制品。",["race:Human"]="这种药酒突显了艾尔文森林中斯通菲尔德和马科伦两个家族之间苦涩的农村世仇达到了何等荒谬的极端。"},sec={{t="给苦命鸳鸯的药水",b="斯通菲尔德家族与马科伦家族之间持续不断的世仇，使得两个家庭之间的和平接触几乎变得不可能。当年轻的托米·乔·斯通菲尔德想要在避开族人视线的情况下与梅贝尔·马科伦见面时，传统的隐蔽手段根本不够用。隐形水提供了一个不可思议的解决方案：这是一种酒精饮料，能让光线绕过饮用者，提供足够的潜行能力，从而不被察觉地溜过这片充满争议的农田。"},{t="非传统的艾尔文炼金术",b="这种药剂使用从当地鱼人出没的水域中收获的水晶海藻叶酿造，将简单的私酿酒工艺与原始的魔法试剂结合在一起。虽然它是非法的，服用起来可能还有危险，但药效确实足够强大，当梅贝尔喝下它时，她会立刻从众人的视线中消失，让她能溜进树林进行秘密幽会。"}},faq={{q="隐形水有什么用？",a="这是一种注入了魔法属性的烈性酒精饮料，能使饮用者暂时完全隐身。",al={"药酒效果","隐形药剂","它有什么用"}},{q="谁在使用隐形水？",a="这种药酒是送给梅贝尔·马科伦的，这样她就能从家人的视线中消失，并不顾两个家族之间的世仇，偷偷溜出去见她的爱人托米·乔·斯通菲尔德。",al={"谁喝它","梅贝尔·马科伦的药酒"}},{q="这种药酒是如何制作的？",a="它使用从艾尔文森林的河床和湖岸收集的水晶海藻叶酿造而成，鱼人经常在那里囤积这种魔法植物。",al={"药酒成分","水晶海藻药酒"}},{q="玩家自己能喝隐形水吗？",a="不能。这种药剂是一种特殊的任务物品，严格用于交给梅贝尔·马科伦，作为她溜出家门的计划的一部分。",al={"我能喝吗","饮用隐形水"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="铁矛",s="铁矛是原本从暴风城运往湖畔镇，用于加固止水湖大桥的坚固建筑材料。这批物资在运输途中遭到赤脊山豺狼人的伏击与抢劫，导致镇上急需的重建物资短缺。",h="铁矛是原本从暴风城运往湖畔镇，用于加固止水湖大桥的坚固建筑材料。这批物资在运输途中遭到赤脊山豺狼人的伏击与抢劫，导致镇上急需的重建物资短缺。",kw={"止水湖大桥","工头奥斯洛","铁矛","铁铆钉","湖畔镇","赤脊山豺狼人","赤脊山"},ang={["faction:Alliance"]="从野蛮的豺狼人手中夺回被窃的建筑物资，有助于确保湖畔镇交通枢纽的安全，从而使暴风城的东部边境保持对黑石兽人侵略的防御能力。",["profession:Blacksmithing"]="这些沉重的结构铁矛展现了当地铁匠所承受的压力，他们被迫将所有的原材料铁都投入到了战争武器的制造中。"},sec={{t="被窃的商队货物",b="当湖畔镇近期面临黑石兽人的攻击时，镇上的金属储备被熔化，铸造成了防御用的盔甲、利刃和弹药。为了应对短缺，当地的建筑工请求暴风城运送一批铁材补给。然而在物资抵达前，一群赤脊山豺狼人在路上劫持了这支运输商队。豺狼人将装有铁矛和铆钉的板条箱拖入北部的山丘中，导致止水湖大桥的修复工程陷入停滞。"},{t="修复桥梁",b="负责监督止水湖大桥重建工作的工头奥斯洛，指望冒险者们深入豺狼人领地，夺回被窃的五金件。如果没有这些加固石木结构的重型铁矛，湖畔镇与北部道路的连接就无法完全恢复，也更容易受到进一步的入侵。"}},faq={{q="为什么豺狼人会带着建筑用的铁矛？",a="豺狼人伏击了一支从暴风城前往湖畔镇的补给商队。它们带着装满被窃建筑五金件（包括铁矛和铆钉）的板条箱，逃入了赤脊山脉之中。",al={"为什么豺狼人有铁矛","豺狼人从哪得到的铁矛"}},{q="湖畔镇里谁需要这些铁矛？",a="工头奥斯洛需要它们来重建止水湖大桥，这座桥横跨止水湖连接着湖畔镇。由于在近期的兽人袭击中为了铸造武器和盔甲，镇上熔化了当地的储备，导致现在缺乏多余的铁材。",al={"谁想要铁矛","工头奥斯洛 铁矛"}},{q="在哪里可以找回这些铁矛？",a="它们被盘踞在湖畔镇北部山丘和山脊上的赤脊山豺狼人所持有。",al={"哪里可以找到铁矛","铁矛位置"}},{q="为什么湖畔镇不能自己锻造铁矛？",a="湖畔镇在抵御黑石兽人时耗尽了当地的铁材供应，将每一块金属碎片都熔化成了剑、子弹和防护装备。他们被迫请求暴风城提供新的建筑用铁材。",al={"为什么湖畔镇要订购铁材","湖畔镇铁材短缺"}}},fx={c6b2b586={q="什么是铁矛？",a="铁矛是一种沉重的铁制建筑桩，用来加固石砌结构。工头奥斯洛和他的工人需要这些结实的结构桩，来修复并稳固湖畔镇损毁的静水桥。",al={"什么是铁矛","铁矛是什么","赤脊山的铁矛"}}},fp="9,166,20.329.0,19.249.0,47.192.0,40.189.0,40.89.0,55.187.0"}
P.entries["item:iron-pommel"] = {n="铁质柄头",s="铁质柄头是达托尔之杖最后缺失的碎片。这根手杖由早已作古的法师达托尔所造，阿斯特兰纳的暗夜精灵们正寻求用它来减缓熊怪对他们人民的攻击。它曾被托付给朵丹尼尔兽穴的德鲁伊妥善保管，但在他们的圣所遭到屠戮并被软泥怪侵占后丢失了。",h="铁质柄头是达托尔之杖最后缺失的碎片。这根手杖由早已作古的法师达托尔所造，阿斯特兰纳的暗夜精灵们正寻求用它来减缓熊怪对他们人民的攻击。它曾被托付给朵丹尼尔兽穴的德鲁伊妥善保管，但在他们的圣所遭到屠戮并被软泥怪侵占后丢失了。",kw={"灰谷","达托尔之杖","朵丹尼尔","铁质柄头","奥索的箱子","雷恩的净化","莎尔蒂恩"},ang={["class:Druid"]="这个柄头是朵丹尼尔牺牲的德鲁伊们的阴森纪念物，他们守护的神圣职责最终在森林边缘的屠杀中终结。",["faction:Alliance"]="找回柄头完成了确保达托尔之杖的关键阶段，这是防御灰谷免受蔓延腐蚀的重要工具。"},sec={{t="被屠戮的德鲁伊之重担",b="达托尔之杖被拆分并散落在灰谷各处，以保护其神秘力量。铁质柄头被交给居住在通往贫瘠之地的蜿蜒小路旁的暗夜精灵德鲁伊看管。当那个德鲁伊圆环在朵丹尼尔兽穴遭到屠杀时，灾难降临到了这片隐蔽的聚集地，他们宁静的避难所陷入了废墟般的死寂。柄头在事后消失了，被现在徘徊在被亵渎的林地中的怪诞、冒泡的软泥怪吞噬了。"},{t="从泥沼中寻回",b="德鲁伊们已经遇难，要找到柄头就必须搜寻碎木岗哨以南那片被污染的洼地。圣物被锁在一个坚固的箱子里。冒险者们在穿过腐败的软泥怪时，会在一只软泥怪的酸性物质中发现完好无损的箱子，从而最终获得了修复手杖所需的最后一块组件。"}},faq={{q="铁质柄头有什么用？",a="铁质柄头是重新组装达托尔之杖所需的最后一个组件。把它带给月井旁的莎尔蒂恩，她就能修复这件古老的神器，使之能够被用来减缓熊怪对灰谷暗夜精灵的攻击。",al={"铁质柄头的作用","为什么需要铁质柄头","铁质柄头有什么功能"}},{q="谁最初保管着柄头？",a="它曾被托付给居住在通往贫瘠之地的大路旁的暗夜精灵德鲁伊。不幸的是，在手杖重聚之前，这个圆环就被屠杀殆尽，只留下了一片废墟。",al={"谁看守着柄头","谁拥有铁质柄头","朵丹尼尔德鲁伊"}},{q="在哪里可以找到柄头？",a="柄头被锁在一个箱子里，而箱子被一只腐败的软泥怪吞噬，这只软泥怪徘徊在主路以东、碎木岗哨以南、贫瘠之地边界以北的那片被污染的洼地中。",al={"铁质柄头位置","铁质柄头在哪里","如何获得铁质柄头"}},{q="我应该把柄头交给谁？",a="柄头必须交给莎尔蒂恩，她是照料伊瑞斯湖以东那口月井的树妖，拥有重组达托尔之杖所需的仪式知识。",al={"交付铁质柄头","铁质柄头交给谁","谁需要这个柄头"}}},fx={["9716c2ef"]={q="什么是铁质柄头？",a="铁质柄头是重组达托尔之杖所需的最后一件遗失部件。这根法杖由早已逝去的法师达托尔打造。在遭遇悲剧之前，居住在朵丹尼尔兽穴的德鲁伊受托保管这块沉重的金属部件。庇护所沦陷于腐化与暴力之中时，柄头遗失了，最终被锁在荒野中的一只旧箱子里，等待有能力的人将它寻回。",al={"什么是铁质柄头","铁质柄头的背景","达托尔之杖的柄头是什么"}}},fp="11,313,23.378.0,23.251.1,33.213.0,30.167.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="铁铆钉",s="铁铆钉是在暴风城制造的坚固建筑紧固件，用于修复湖畔镇破损的止水湖大桥。在一支补给车队遭到赤脊山豺狼人伏击并被洗劫后，这些沉重的金属组件散落在北部丘陵的豺狼人营地中。",h="铁铆钉是在暴风城制造的坚固建筑紧固件，用于修复湖畔镇破损的止水湖大桥。在一支补给车队遭到赤脊山豺狼人伏击并被洗劫后，这些沉重的金属组件散落在北部丘陵的豺狼人营地中。",kw={"止水湖大桥","工头奥斯洛","铁矛","铁铆钉","湖畔镇","赤脊山豺狼人","赤脊山"},ang={["faction:Alliance"]="回收这些被窃的补给品，可以直接援助湖畔镇当地的基础设施建设，同时遏制威胁该镇的嚣张豺狼人势力。",["profession:Blacksmithing"]="这些重型紧固件展示了暴风城的标准锻造工艺，是专门为加固石木桥梁等大型民用工程而铸造的。"},sec={{t="被窃的车队货物",b="当湖畔镇面临黑石兽人接连不断的攻击时，镇议会不得不熔化他们的铁质结构储备，以铸造急需的武器、盔甲和弹药。在紧迫的危机平息后，工头奥斯洛向暴风城请求了新的建筑物资，以修补断裂的止水湖大桥。然而，运送这批货物的补给车队在抵达城镇前遭到了当地赤脊山豺狼人的伏击。驮兽和货车被拖进了止水湖以北的丘陵，重要的建筑材料（如铁铆钉和长矛）散落在豺狼人部落中。"},{t="修复桥梁",b="没有这些沉重的铁铆钉，止水湖大桥的结构修复工作就无法安全进行。跨越湖泊的石木框架需要加固的金属紧固件，才能承受车辆和行人的重量。直接从豺狼人营地中回收这些铆钉，对于恢复湖畔镇通往西部山谷的重要通道，以及保障城镇周边免受进一步侵扰至关重要。"}},faq={{q="铁铆钉有什么用途？",a="它们是工头奥斯洛修复湖畔镇止水湖大桥所需的重型结构紧固件，该桥在与黑石兽人的战斗中丢失了最初的铁质部件。",al={"铁铆钉用途","为何需要铁铆钉","铁铆钉是干什么用的"}},{q="为什么豺狼人会有这些铆钉？",a="一支从暴风城派出的补给车队在路上被赤脊山豺狼人劫持。这些拾荒者掠走了建筑货物，将铆钉和铁长矛带回了湖畔镇北部的营地。",al={"为什么豺狼人有铆钉","豺狼人如何得到铁铆钉","谁偷了铆钉"}},{q="湖畔镇最初为什么缺少铁？",a="在最近的一次兽人入侵期间，为了在围攻中幸存下来，湖畔镇的守军不得不将所有储存的铁料熔化，制成了刀剑、子弹和盔甲。",al={"湖畔镇铁料短缺","为什么湖畔镇没有铁"}},{q="谁在寻找这些铆钉？",a="工头奥斯洛，他是监督湖畔镇止水湖大桥修复工作的总建筑师。",al={"谁想要铁铆钉","谁拿走了铁铆钉"}}},fx={["0d91405a"]={q="什么是铁铆钉？",a="铁铆钉是一种结实的金属紧固件，由王国锻造，用于重型建筑工程。暴风城曾向湖畔镇运送一批铁铆钉，帮助重建镇上损毁的基础设施，尤其是至关重要的静水桥。",al={"铁铆钉是什么","铁铆钉说明"}},a8a8e120={q="这些铁铆钉从哪里来？是谁制造的？",a="这些铆钉是暴风城派出的救援车队所运物资的一部分，车队还载有运往赤脊山的原材料和建筑用品。车队尚未抵达湖畔镇便遭到赤脊山豺狼人的伏击与洗劫，铁料散落在他们山坡上的营地里。",al={"铁铆钉从哪里来","谁制造了铁铆钉","铁铆钉的来源"}}},fp="10,144,20.381.0,18.325.0,30.167.0,36.158.0,46.116.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="铁杆",s="铁杆是达图尔的权杖的一个金属部件，达图尔的权杖是一件遗物，莱恩·狼行者的朋友泰兰尼斯曾试图寻找它，希望能以此减缓熊怪对灰谷的侵袭。它是在费伍德森林边界附近的一个锁着的箱子里找到的，对于灰谷的保卫者们修复这件遗物来说，它是至关重要的组件。",h="铁杆是达图尔的权杖的一个金属部件，达图尔的权杖是一件遗物，莱恩·狼行者的朋友泰兰尼斯曾试图寻找它，希望能以此减缓熊怪对灰谷的侵袭。它是在费伍德森林边界附近的一个锁着的箱子里找到的，对于灰谷的保卫者们修复这件遗物来说，它是...",kw={"灰谷","疯狂的古树","达图尔的权杖","费伍德森林","铁杆","莱恩的净化","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="重组达图尔的权杖与德鲁伊的职责息息相关，它使用被遗忘的工具来治愈受创的土地。",["race:NightElf"]="取回铁杆是一项沉重的职责，因为这需要消灭那些沦为从费伍德森林中渗出的恶魔枯萎病受害者的森林树人们。"},sec={{t="达图尔的权杖碎片",b="达图尔的权杖由达图尔所造，它的碎片散落在灰谷各地；其中一件甚至被交给了朵丹尼尔的德鲁伊们保管。铁杆代表了这件法器坚固的金属核心，被藏在灰谷北部边界附近一处僻静林地中一个锁着的箱子里，距离受到腐蚀的费伍德森林不远。"},{t="森林的枯萎",b="要获得铁杆，需要从曾经照料这些森林的当地树人手中取回钥匙。随着恶魔的腐蚀从费伍德森林向南蔓延，像疯狂的古树和枯萎的古树这样的古老守护者们已经陷入了疯狂。树妖莎尔蒂恩委托旅行者去获取这根铁杆，以便重铸权杖，完成已故泰兰尼斯的使命。"}},faq={{q="铁杆有什么用？",a="铁杆是达图尔的权杖的碎片，这是一件破损的遗物。收集它是为了让树妖莎尔蒂恩能够帮助重组权杖，并完成泰兰尼斯的使命，泰兰尼斯曾寻求用它来减缓熊怪对灰谷的侵袭。",al={"铁杆用途","这个铁杆是什么","为什么我需要铁杆"}},{q="在哪里可以找到铁杆？",a="它被锁在灰谷北部，通往费伍德森林之路以西一处安静林地里的箱子中。",al={"铁杆位置","寻找铁杆","箱子在哪里"}},{q="如何打开装有铁杆的箱子？",a="这个箱子需要一把木制钥匙。这把钥匙由游荡在林中树居东北部森林里的受腐蚀树人——疯狂的古树和枯萎的古树——携带。",al={"如何打开箱子","箱子钥匙","铁杆钥匙"}},{q="谁在寻找铁杆？",a="莎尔蒂恩是一位驻守在灰谷中部月井旁的树妖，她指引冒险者们收集达图尔的权杖碎片，作为净化森林行动的一部分。",al={"谁想要铁杆","铁杆任务发布者"}}},fx={ad78a81b={q="什么是铁杆？",a="铁杆是达托尔之杖的重要组成部分，这件遗物由达托尔打造。法杖的部件散落在灰谷各处，而这根铁杆被锁在费伍德森林边界附近的一只隐秘箱子里，钥匙则由附近被腐化的树人持有。",al={"什么是铁杆","铁杆物品","达托尔之杖的铁杆"}},["45340e91"]={q="铁杆从哪里来？是谁制造的？",a="它是达托尔打造的一根魔法杖的一部分。后来，法杖的部件四散而失，这根铁杆被收在一只破旧的箱子里，箱子藏在费伍德森林附近的一处林间空地上；持有箱子钥匙的被腐化树人也间接守卫着它。",al={"谁制造了铁杆","铁杆的来源","达托尔的铁杆"}},["3705c59d"]={q="为什么要寻找铁杆？",a="莱恩·狼行者和莎尔蒂恩想要重新拼合达托尔之杖。特尔尼亚斯认为，这根法杖能够减缓灰谷暗夜精灵遭受的熊怪袭击。要重组这件遗物，就必须找齐失落的部件；这根结实的铁杆是法杖的中央握柄与核心，能将法杖的魔法宝石和柄头固定在一起。",al={"他们为什么要找铁杆","为什么要收集铁杆","寻找铁杆的任务原因"}}},fp="10,147,23.257.0,19.281.1,32.194.0,30.104.0,47.138.0,34.133.0"}
P.entries["item:ironband-s-progress-report"] = {n="铁环挖掘场的进度报告",s="《铁环挖掘场的进度报告》是一份书面快报，详细说明了勘察员基恩萨·铁环在洛克莫丹东部的挖掘现场所面临的困境。报告中既记述了挖掘进度因遭受穴居人袭击而缓慢受阻的情况，也发出了对更多爆炸火药的紧急请求。",h="《铁环挖掘场的进度报告》是一份书面快报，详细说明了勘察员基恩萨·铁环在洛克莫丹东部的挖掘现场所面临的困境。报告中既记述了挖掘进度因遭受穴居人袭击而缓慢受阻的情况，也发出了对更多爆炸火药的紧急请求。",kw={"爆炸火药","探险者协会","基恩萨·铁环","吉恩·角盔","洛克莫丹","勘察员塔伯斯·雷矛","塞尔萨玛","穴居人"},ang={["profession:Mining"]="矿工们非常清楚在清理顽固岩层时爆炸火药的重要性——以及当补给在穴居人领地丢失时的危险。",["race:Dwarf"]="对于矮人探险家和矿工来说，这份快报体现了在卡兹莫丹中心地带挖掘泰坦遗迹所面临的危险现实。"},sec={{t="请求火药",b="勘察员基恩萨·铁环在洛克莫丹的挖掘工作不断受到当地穴居人的干扰。为了让项目继续推进，铁环汇编了这份进度报告，重申了他对爆炸火药的迫切需求。报告先是被送往塞尔萨玛的吉恩·角盔处，随后转交给铁炉堡的探险者协会，记录了现场的停滞情况并要求提供重型弹药。这份快报迅速引起了协会领导层的警觉，因为几周前他们已经向铁环运送了充足的爆炸火药，上级不禁怀疑之前的补给究竟去了哪里。"}},faq={{q="什么是铁环挖掘场的进度报告？",a="这是一份由勘察员基恩萨·铁环撰写的官方实地报告，主要涉及他在洛克莫丹的挖掘现场状况，特别强调了穴居人造成的干扰，并要求提供更多爆炸火药。",al={"进度报告","铁环的报告","这份报告是什么"}},{q="谁会收到这份报告？",a="报告首先被递交给塞尔萨玛的当地联络人吉恩·角盔。随后，角盔指引信使将报告直接送交铁炉堡探险者协会总部的勘察员塔伯斯·雷矛。",al={"谁收到报告","我把报告交给谁","递交进度报告"}},{q="为什么铁环需要更多的爆炸火药？",a="铁环声称他需要火药来辅助考古挖掘，但附近穴居人的频繁袭击表明他可能还需要炸药用于防御。奇怪的是，角盔和雷矛都认为他们几周前已经向他发送了充足的爆炸火药。",al={"为什么需要火药","火药发生了什么","火药短缺"}},{q="勘察员塔伯斯·雷矛对这份报告有什么反应？",a="雷矛对缓慢的进度感到愤怒，而且对铁环在报告中只字未提之前运送的大量爆炸火药感到困惑，质疑这些丢失的弹药去了哪里。",al={"雷矛的反应","雷矛生气了吗"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ishamuhale-s-fang"] = {n="伊沙姆哈尔的牙齿",s="伊沙姆哈尔的牙齿是一种狩猎战利品，取自贫瘠之地的臭名昭著的日光鳞迅猛龙，人称“长矛牙”。将其带给陶拉祖营地的乔恩·天视，这颗牙齿就是战胜卡利姆多最致命的天然捕食者之一的证明。",h="伊沙姆哈尔的牙齿是一种狩猎战利品，取自贫瘠之地的臭名昭著的日光鳞迅猛龙，人称“长矛牙”。将其带给陶拉祖营地的乔恩·天视，这颗牙齿就是战胜卡利姆多最致命的天然捕食者之一的证明。",kw={"贫瘠之地","獠牙","伊沙姆哈尔","乔恩","迅猛龙","赛格拉","长矛牙","日光鳞","陶拉祖"},ang={["class:Hunter"]="夺取长矛牙的獠牙是贫瘠之地的一项重要成人礼，考验着追踪者引诱、对抗并战胜狡猾顶级野兽的能力。",["race:Tauren"]="对于陶拉祖的猎人来说，夺取这颗牙齿并非为了无谓的屠戮，而是在保持纪律与平衡的同时，吸收捕食者原始的力量。"},sec={{t="长矛牙的战利品",b="伊沙姆哈尔在整个中部草原闻名遐迩，被视为最凶猛的日光鳞迅猛龙，这种顶级捕食者据说纯粹出于狩猎的激情而非仅仅为了饥饿而杀戮。在棘齿城西北方的一棵枯树旁，用新鲜的斑马肉将其引诱出来，这头野兽绝不会手下留情。割下它巨大的獠牙向部落的狩猎指导者证明，旅行者不仅征服了一头野兽，更征服了平原上纯粹的野性。"},{t="节制的教训",b="当呈交给陶拉祖营地的乔恩·天视时，这颗獠牙被视为远超象牙和血肉的存在。对于营地的牛头人来说，夺取伊沙姆哈尔的牙齿意味着将捕食者的狂野力量转移给战胜它的猎人。随之而来的真正考验是节制：掌握那种野蛮的狂怒，而不是让它控制猎人的灵魂。"}},faq={{q="什么是伊沙姆哈尔的牙齿？",a="这是从伊沙姆哈尔的尸体上获取的战利品，伊沙姆哈尔就是那头在贫瘠之地徘徊、臭名昭著的“长矛牙”日光鳞迅猛龙。",al={"伊沙姆哈尔的牙齿","长矛牙的獠牙","贫瘠之地迅猛龙獠牙"}},{q="谁想要伊沙姆哈尔的牙齿？",a="这颗牙齿被带到陶拉祖营地的乔恩·天视处，作为在十字路口的赛格拉·黑刺手下开始的狩猎试炼的一部分。",al={"伊沙姆哈尔的牙齿交给谁","伊沙姆哈尔的牙齿上交","伊沙姆哈尔的牙齿有什么用"}},{q="如何找到野兽伊沙姆哈尔？",a="伊沙姆哈尔不会公开游荡。猎人必须猎杀一头新鲜的斑马，并将其尸体放在棘齿城西北方的一棵死树旁，以此将这头迅猛龙引出藏身处。",al={"如何召唤伊沙姆哈尔","召唤伊沙姆哈尔","伊沙姆哈尔在哪里"}},{q="对于牛头人来说，夺取这颗獠牙代表着什么？",a="根据乔恩·天视的说法，夺取这一战利品象征着伊沙姆哈尔的传奇力量现在寄宿在猎人体内，猎人必须背负起以节制和荣誉运用这种力量的重担。",al={"獠牙的含义","牛头人猎人仪式伊沙姆哈尔"}}},fp="17,195,20.398.0,22.295.1,26.117.0,28.126.0,34.105.0,52.159.0"}
P.entries["item:ivar-s-head"] = {n="伊瓦的头颅",s="伊瓦的头颅是铲除银松森林中贪婪的食尸鬼“污秽者”伊瓦的惨烈证据。死亡猎手兰妮·尤瑞克需要它，以确保她受伤的兄弟奎恩能安全康复。",h="伊瓦的头颅是铲除银松森林中贪婪的食尸鬼“污秽者”伊瓦的惨烈证据。死亡猎手兰妮·尤瑞克需要它，以确保她受伤的兄弟奎恩能安全康复。",kw={"死亡猎手","伊瓦农场","污秽者伊瓦","伊瓦的头颅","奎恩·尤瑞克","兰妮·尤瑞克","银松森林"},ang={["faction:Horde"]="消灭像伊瓦这样的天灾军团残党，可以保护穿过银松森林北部前往瑟伯切尔的部落信使。",["race:Undead"]="对于被遗忘者侦察兵来说，野生的食尸鬼是破坏军事侦察并威胁洛丹伦初建的安全防线的无脑累赘。"},sec={{t="被斩断的威胁",b="在奉高级执行官哈德瑞克的命令于银松森林北部进行侦察时，被遗忘者死亡猎手兰妮和奎恩·尤瑞克在一处废弃的农场遭到了名为“污秽者”伊瓦的野性食尸鬼的伏击。尽管姐弟俩成功击退了这只恶魔，但奎恩在战斗中受了重伤。在兄弟恢复期间，被困在废弃农场的兰妮无法在无人照看奎恩的情况下离开，去完成他们的任务。斩下伊瓦的头颅可以作为决定性的证据，证明这头野兽永远不会再威胁到这片庄园，也能让奎恩在兰妮的注视下获得必要的休养时间。"}},faq={{q="这是谁的头颅？",a="这颗头颅属于“污秽者”伊瓦，那是一只盘踞在银松森林北部一处被称为伊瓦农场的废弃农舍里的野蛮食尸鬼。",al={"谁是伊瓦","伊瓦头颅的身份","什么是伊瓦"}},{q="为什么兰妮·尤瑞克想要伊瓦的头颅？",a="兰妮需要实物证据来证明伊瓦已被消灭。她的兄弟奎恩被这只生物严重抓伤，需要在不担心再次遭受伏击的情况下进行疗伤，然后他们才能回到高级执行官哈德瑞克身边复命。",al={"为什么兰妮想要头颅","伊瓦的头颅交还","为什么要杀死伊瓦"}},{q="“污秽者”伊瓦在哪里被发现？",a="“污秽者”伊瓦潜伏在伊瓦农场破败的谷仓里，监视并等待着受伤的死亡猎手们放松警惕。",al={"伊瓦的位置","伊瓦在哪里"}}},fp="11,135,16.459.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Iverron's Antidote (item)",s="埃沃隆的解毒药是迪兰妮亚·月光在幽影谷调制的一种精致药剂。该药剂专为中和当地织木蜘蛛的剧毒而酿造，性质极不稳定，制成后会迅速变质。",h="埃沃隆的解毒药是迪兰妮亚·月光在幽影谷调制的一种精致药剂。该药剂专为中和当地织木蜘蛛的剧毒而酿造，性质极不稳定，制成后会迅速变质。",kw={"奥达希尔","迪兰妮亚·月光","埃沃隆","埃沃隆的解毒药","幽影谷","蜘蛛毒液","泰达希尔","织木毒液"},ang={["profession:Herbalism"]="这种药剂展示了泰达希尔原生试剂的极端挥发性，突显了某些草药疗法必须在酿制后立即使用的必要性。",["race:NightElf"]="对于在幽影谷开启冒险旅程的年轻暗夜精灵来说，争分夺秒将解毒药送到埃沃隆手中，体现了在这个社区面对泰达希尔枝干间蔓延的腐蚀时，对快速行动和草药知识的依赖。"},sec={{t="脆弱的疗法",b="这种解毒药由奥达希尔的迪兰妮亚·月光酿制，专门用于抵消导致年轻暗夜精灵埃沃隆中毒的强效毒液。由于其成分和草药催化剂的挥发性，该药剂的保质期极短，酿造后仅有五分钟的有效期。送信者必须立即向北奔向织木蜘蛛洞穴，在药剂分解成无用的泥浆之前将其送达。"}},faq={{q="埃沃隆的解毒药有什么用途？",a="它用于治愈埃沃隆因幽影谷北部织木蜘蛛洞穴外的织木蜘蛛叮咬而中的毒。",al={"解毒药用途","埃沃隆的解毒药有什么用"}},{q="为什么解毒药有时间限制？",a="迪兰妮亚·月光指出，这种药剂非常脆弱，配制后仅能保持五分钟的效力。如果不尽快使用，它的药性会完全失效。",al={"为什么是五分钟","解毒药计时器","为什么会过期"}},{q="谁酿制了解毒药？",a="迪兰妮亚·月光，一位驻扎在幽影谷奥达希尔的暗夜精灵治疗者，她使用收集来的材料酿制了这瓶药剂以拯救埃沃隆。",al={"谁制作了解毒药","解毒药制作者"}},{q="如果解毒药过期了会怎样？",a="如果计时结束，药剂就会变质，无法继续使用。送信者必须返回奥达希尔找迪兰妮亚·月光重新获取一批。",al={"解毒药过期","计时结束"}}},fp="25,195,16.286.0,36.115.0,40.143.0,23.127.0,37.146.0"}
P.entries["item:jade-phial"] = {n="翡翠瓶",s="翡翠瓶是由多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒所提供的一种特制容器。它的设计目的是为了安全地汲取并运输泰达希尔月亮井中的圣水，以补充达纳苏斯德鲁伊核心月亮井的消耗。",h="翡翠瓶是由多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒所提供的一种特制容器。它的设计目的是为了安全地汲取并运输泰达希尔月亮井中的圣水，以补充达纳苏斯德鲁伊核心月亮井的消耗。",kw={"科瑞萨斯·月怒","crown of the earth","多兰纳尔","翡翠瓶","月亮井","星风村","泰达希尔"},ang={["class:Druid"]="对于年轻的德鲁伊来说，携带翡翠瓶是学习管理自然的第一课，这强调了泰达希尔月亮井的生命力需要不断的敬畏与呵护。",["race:NightElf"]="月亮井象征着卡多雷与艾露恩之间永恒的纽带；使用像翡翠瓶这样的容器来照料它们，是每一位暗夜精灵的神圣职责。"},sec={{t="圣水的容器",b="泰达希尔各处散布着月亮井，它们引导着对暗夜精灵社会和德鲁伊崇拜至关重要的月球与自然能量。作为维持这种和谐的一部分，达纳苏斯德鲁伊所使用的核心月亮井必须定期从这棵巨木边缘的月亮井中补充圣水。科瑞萨斯·月怒会将翡翠瓶托付给年轻的受教者，这是一种经过精心准备的容器，可以收集星风村附近月亮井中的纯净之水，而不会干扰其微妙的精神效力。"}},faq={{q="翡翠瓶是用来做什么的？",a="翡翠瓶用于收集星风村外围月亮井中的圣水。装满后，必须将其交还给多兰纳尔的科瑞萨斯·月怒，以帮助补充达纳苏斯德鲁伊的月亮井。",al={"翡翠瓶用途","为什么需要翡翠瓶","翡翠瓶的作用"}},{q="谁提供了翡翠瓶？",a="驻扎在多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒，会将此瓶交给正在进行名为Crown of the Earth仪式的冒险者。",al={"谁给的翡翠瓶","在哪里获得翡翠瓶","科瑞萨斯 翡翠瓶"}},{q="这个瓶子里的水最终去了哪里？",a="收集在瓶中的水会被运往首都达纳苏斯，用于维持和补充塞纳里奥德鲁伊所维护的核心月亮井。",al={"月亮井的水去哪了","翡翠瓶目的地","谁使用这些水"}}},fp="10,183,26.456.0,32.207.0,28.143.0,44.124.0"}
P.entries["item:jennea-s-flask"] = {n="詹妮亚的瓶子",s="詹妮亚的瓶子是暴风城Mage Quarter的法师詹妮亚·坎农交给有抱负的法师的一个空容器。它被用来从明镜湖采集水样，以研究当地魔网的扰动。",h="詹妮亚的瓶子是暴风城Mage Quarter的法师詹妮亚·坎农交给有抱负的法师的一个空容器。它被用来从明镜湖采集水样，以研究当地魔网的扰动。",kw={"艾尔文森林","詹妮亚·坎农","詹妮亚的瓶子","明镜湖","暴风城","水样","巫师圣殿"},ang={["class:Mage"]="对于初级法师来说，携带这个瓶子代表了你为巫师圣殿完成的第一个实地任务，证明你可以处理精细的奥术研究并监测魔网的稳定性。"},sec={{t="奥术研究的容器",b="在艾泽拉斯发生灾难性的魔法斗争后，奥术流的自然流动已经脱离了古老的渠道。在暴风城，詹妮亚·坎农试图了解这些神秘的转变对艾尔文森林的影响有多深。她将这个简单的玻璃瓶交给有前途的学徒，派他们前往首都大门西南方，从明镜湖瀑布底部提取新鲜的水。一旦装满，这个容器就能保护脆弱的样本，以便完好无损地带回巫师圣殿进行奥术分析。"},{t="守护水源",b="使用这个瓶子主要出于公共安全的考虑。如果波动的魔网开始将魔法污秽渗入明镜湖，周围的生态系统和任何饮用湖水的人都可能遭受奇怪或有害的影响。在詹妮亚的瓶子中收集原始样本，可以让暴风城的法师在被污染的水流蔓延到整个乡村之前，就检测到无形的魔法残留。"}},faq={{q="詹妮亚的瓶子是用来做什么的？",a="这是一个空容器，给你用来收集艾尔文森林明镜湖瀑布的水样。",al={"瓶子用途","瓶子的作用","瓶子怎么用"}},{q="是谁给你的这个瓶子？",a="它是由詹妮亚·坎农提供的，她是驻扎在暴风城巫师圣殿里的一位法师训练师。",al={"谁给的瓶子","詹妮亚瓶子来源"}},{q="为什么詹妮亚想要明镜湖的水？",a="最近的神秘冲突扰乱了世界各地的魔法流动。詹妮亚担心这些杂乱的魔流正渗入艾尔文的自然水域，这可能会危及任何饮用湖水的人。",al={"为什么是明镜湖的水","为什么要水样"}},{q="在哪里装满瓶子？",a="你必须带着瓶子前往流入明镜湖的瀑布底部，它位于艾尔文森林中，暴风城主城门西南方。",al={"在哪里装瓶","瓶子位置","湖泊位置"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jitters-completed-journal"] = {n="基特斯的日记",s="基特斯的日记是一份手写记录，详述了Duskwood发生的惨剧，特别是斯温·约根农场的屠杀事件。为了避免遭到报复，隐居的基特斯交出了写完的日记，以洗清自己的名声，并揭露萦绕在这个地区的邪恶力量。",h="基特斯的日记是一份手写记录，详述了Duskwood发生的惨剧，特别是斯温·约根农场的屠杀事件。为了避免遭到报复，隐居的基特斯交出了写完的日记，以洗清自己的名声，并揭露萦绕在这个地区的邪恶力量。",kw={"主教法席恩","cathedral of light","黑暗骑手","暮色森林","荒弃鬼屋","基特斯","日记","morbent fel","斯温·约根"},ang={["class:Priest"]="将日记送到Cathedral of Light的主教法席恩手中，使牧师们可以直接通过圣物来净化邪恶的污染。",["faction:Alliance"]="这本日记是一个严酷的提醒，时刻警示着当暴风城的领导层忙于他顾时，Duskwood已经陷入了多么深重的危机。"},sec={{t="懦夫的自白",b="当斯温的农场遭到袭击时，基特斯在惊恐中逃跑了，将写了一半的日记遗弃在废墟中。这本完整的日记补全了那可怕一天的缺失片段，讲述了神秘的黑暗骑手是如何屠杀斯温一家的。在Duskwood躲藏的数周里，这本日记成了基特斯唯一的慰藉。他自愿交出这本完整的日记，迫切地想要解释真相，并希望通过这书写的真相对斯温的愤怒带来一丝宽恕。"},{t="揭开黑暗的真相",b="这本日记的作用不仅仅是抚平旧日的伤痛：它还促使斯温透露，他曾见过那些身披黑袍的骑手在荒弃鬼屋与法师Morbent Fel交谈。斯温让旅行者带着这本完整的手稿向北前往暴风城的Cathedral of Light。在那里，主教法席恩读到了基特斯写下的文字，从而了解了在Duskwood滋生的邪恶腐化，并利用其中的启示来协助制作能够刺穿Morbent Fel黑暗结界的圣物。"}},faq={{q="基特斯为什么要交出他的日记？",a="基特斯在袭击发生时从斯温的农场逃走，留下了尚未完成的日记。他将完整版交给了冒险者，希望他们能把它带给斯温，期望完整的真相能证明他的清白，并让他免受斯温怒火的伤害。",al={"为什么基特斯要交出日记","基特斯的日记","基特斯为什么要写这个"}},{q="这本日记揭示了关于斯温农场的什么信息？",a="它提供了基特斯关于斯温·约根农场惨剧的完整目击记录，填补了他那本未完成的日记留下的空白。",al={"斯温农场发生了什么","斯温一家遇袭","斯温农场的黑暗骑手"}},{q="Morbent Fel是谁，他与这本日记有什么联系？",a="Morbent Fel是一位居住在荒弃鬼屋的死灵法师。这本日记促使斯温分享了信息，将调查引向了他。",al={"与morbent fel的关联","morbent fel是谁","荒弃鬼屋的法师"}},{q="为什么要将日记带到暴风城？",a="斯温指引冒险者将日记带给Cathedral of Light的主教法席恩。由于暴风城在很大程度上忽视了夜色镇的防御，法席恩的智慧和神圣专长对于制作能够刺穿Morbent Fel魔法结界的武器是必不可少的。",al={"为什么找主教法席恩","把日记带到教堂","寻求日记中的智慧"}}},fx={["3f8dfebe"]={q="什么是基特斯的日记？",a="这是基特斯留下的完整个人纪事。基特斯是个躲藏在暮色森林中的惊恐流浪者。与他逃离斯温·约根的农场时遗落的零散笔记不同，这份完整手稿详述了降临在那座农场上的一系列悲剧、森林中日益逼近的恐怖，以及在阴影中活动的邪恶身影。",al={"基特斯的日记","这本日记是什么"}},e7121643={q="基特斯的日记从何而来？是谁写的？",a="这本日记是基特斯亲笔写下的。在逃离斯温的农场遭遇的屠杀并丢下早先的一本日记后，他躲藏了数周，惊慌地记录自己的想法，以及在暮色森林中徘徊的邪恶势力。他一直将写完的日记作为唯一的伴侣，直到为了避免面对斯温·约根的怒火，才把它交了出去。",al={"谁写了基特斯的日记","基特斯日记的来历","这本日记从何而来"}},["5c3c5710"]={q="为什么有人想要基特斯的日记？",a="斯温·约根想要这本日记，因为其中记载了基特斯对农场悲剧的亲眼见闻。后来，光明大教堂的主教法席恩也会研读它，以帮助一位冒险者做好准备，对抗侵扰暮色森林的邪恶。",al={"为什么他们想要这本日记","基特斯的日记为何重要","谁想要这本日记"}}},fp="26,205,21.356.1,23.385.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="乔汉的研究成果",s="“乔汉的研究成果”是一捆由布瑞尔的药剂师乔汉撰写的研究文件。这些笔记被委托给一名前往南方的信使，旨在将提瑞斯法林地近期的炼金术进展传达给瑟伯切尔的药剂师伦弗利尔。",h="“乔汉的研究成果”是一捆由布瑞尔的药剂师乔汉撰写的研究文件。这些笔记被委托给一名前往南方的信使，旨在将提瑞斯法林地近期的炼金术进展传达给瑟伯切尔的药剂师伦弗利尔。",kw={"药剂师乔汉","药剂师伦弗利尔","布瑞尔","乔汉","乔汉的研究成果","新瘟疫","皇家药剂师学会","瑟伯切尔"},ang={["faction:Horde"]="携带研究资料南下，标志着一名旅行者从熟悉的提瑞斯法林地，跨入了银松森林更黑暗的冲突之中。",["race:Undead"]="这些研究成果反映了皇家药剂师学会那唯一且迫切的野心：交付向黑暗女王承诺的“新瘟疫”（The New Plague）。"},sec={{t="药剂师通讯",b="皇家药剂师学会承受着希尔瓦娜斯·风行者（Sylvanas Windrunner）施加的巨大压力，必须研发出一种既能消灭生者、又能摧毁天灾军团的“新瘟疫”（The New Plague）。由于研究人员分散在洛丹伦各处的废墟之中，保持各前哨站之间的数据流通至关重要。药剂师乔汉在布瑞尔汇总了他当地的测试笔记，并将其送往南方，交予在银松森林的瑟伯切尔指挥学会行动的药剂师伦弗利尔。这些记录代表了学会为磨炼其致命药剂所做的集体努力的一小部分。"}},faq={{q="什么是“乔汉的研究成果”？",a="这是一份由布瑞尔的药剂师乔汉汇编的炼金笔记和研究资料。这些文件详细记录了他近期在提瑞斯法林地进行的测试和实验。",al={"乔汉的研究成果","什么是乔汉的研究成果","乔汉的研究文件"}},{q="谁应该接收这个物品？",a="这些研究成果是发给药剂师伦弗利尔的，他是皇家药剂师学会的高级成员，驻扎在银松森林北部的瑟伯切尔。",al={"谁接收乔汉的研究成果","我该把乔汉的研究成果交给谁","伦弗利尔的交付"}},{q="为什么药剂师之间要共享这些研究？",a="皇家药剂师学会依靠其分散的研究人员之间的知识共享来加速工作进程。希尔瓦娜斯·风行者（Sylvanas Windrunner）要求迅速开发“新瘟疫”（The New Plague），因此银松森林的研究人员必须及时了解提瑞斯法林地取得的突破进展。",al={"为什么要分享研究成果","乔汉的研究成果的用途","皇家药剂师学会研究"}},{q="谁撰写了这些文件？",a="药剂师乔汉，一位常驻在布瑞尔绞刑架附近的皇家药剂师学会炼金术士。他通过对当地样本进行实验性测试，以推进被遗忘者的炼金目标。",al={"谁是药剂师乔汉","谁写了这个","药剂师乔汉"}}},fp="17,182,25.532.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="乔汉的特制饮料",s="乔汉的特制饮料是由布瑞尔的药剂师乔汉调制的一种致命混合物。它被伪装成普通的饮料，实际上是皇家药剂师学会正在研发的瘟疫的实地测试品。",h="乔汉的特制饮料是由布瑞尔的药剂师乔汉调制的一种致命混合物。它被伪装成普通的饮料，实际上是皇家药剂师学会正在研发的瘟疫的实地测试品。",kw={"药剂师乔汉","布瑞尔","被俘虏的巡山人","恐惧之末旅店","乔汉","乔汉的特制饮料","新瘟疫"},ang={["race:Dwarf"]="这种混合物揭示了那些徘徊在提瑞斯法林地附近的矮人侦察兵所面临的残酷命运，他们被俘虏后成为了实验室的试验品。",["race:Undead"]="对于被遗忘者来说，运送乔汉的药剂代表着对皇家药剂师学会以及Lady Sylvanas针对生者宏伟计划的实际贡献。"},sec={{t="有毒的酿造",b="乔汉的特制饮料是在布瑞尔的酿造锅中炼制而成的，它根本不是什么旅店饮料。药剂师乔汉通过将各种有毒成分和当地试剂精炼成一种药剂，专门用于测试其对活体生理机能的杀伤力。这杯饮料以解渴为名递给俘虏，代表了被遗忘者药剂师们正在进行的野心，他们致力于制造出足够强大的武器，以实现Sylvanas Windrunner对艾泽拉斯的计划。"},{t="地窖审判",b="这种饮料最终被送到了恐惧之末旅店下方的昏暗地窖中，那里被死亡卫士当作临时关押外来者的牢房。当它被递给那个戴着镣铐、口渴难耐的被俘虏的巡山人时，他以为这是劣质麦芽酒，便迫不及待地喝了下去。药剂立刻生效，让矮人当场毙命，并向皇家药剂师学会证明了他们最新的毒株可以迅速消灭活体受害者。"}},faq={{q="什么是乔汉的特制饮料？",a="这是由布瑞尔的药剂师乔汉创造的一种致命混合物。虽然它被包装成饮料，但实际上注入了被遗忘者正在研发的瘟疫毒株，旨在测试其对活体生物的致命效力。",al={"什么是乔汉的饮料","乔汉饮料","这个物品是什么"}},{q="这杯饮料是给谁喝的？",a="这杯饮料被带到了布瑞尔的恐惧之末旅店地窖中，并交给了被当地死亡卫士俘虏的被俘虏的巡山人。",al={"谁喝了它","我应该把饮料交给谁","饮料目标"}},{q="喝下它会发生什么？",a="俘虏喝下了液体，以为这能解渴，结果却因为饮料中剧烈的毒素而立即倒地身亡。",al={"矮人死了吗","饮料的效果","它有什么作用"}},{q="药剂师乔汉为什么要制作这种饮料？",a="药剂师乔汉正在为皇家药剂师学会的新瘟疫进行试验。他利用这名被俘虏的矮人作为不知情的活体测试对象，以观察这种混合物在抹杀凡人生命方面的效果。",al={"乔汉为什么制作它","药剂师乔汉的动机","为什么要测试瘟疫"}}},fp="22,161,12.403.0,16.316.1,31.116.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="乔丹的矿石",s="乔丹的矿石是一箱矿石，本应由白洛尔·石手加工成合金，供铁匠乔丹·斯迪威尔使用。这批矿石由商队从湿地运送而来，但在洛克莫丹东北部的山丘中被摩戈什食人魔拦截并洗劫。",h="乔丹的矿石是一箱矿石，本应由白洛尔·石手加工成合金，供铁匠乔丹·斯迪威尔使用。这批矿石由商队从湿地运送而来，但在洛克莫丹东北部的山丘中被摩戈什食人魔拦截并洗劫。",kw={"合金","白洛尔·石手","乔丹·斯迪威尔","乔丹的矿石","洛克莫丹","摩戈什","正义试炼"},ang={["class:Paladin"]="从摩戈什食人魔手中夺回这批被盗的合金是乔丹·斯迪威尔委托的重要一步，以此证明你在正义试炼中的奉献精神。",["profession:Blacksmithing"]="白洛尔·石手特制的合金代表了精湛的矮人冶金工艺，乔丹·斯迪威尔非常看重它，拒绝用普通的替代品来制作他的工艺品。"},sec={{t="被伏击的货物",b="这些矿石本应由矮人白洛尔·石手提炼成他特制的合金，并承诺交给乔丹·斯迪威尔用于金属锻造。在从湿地南下穿越山脉进入洛克莫丹的过程中，补给商队遭到了摩戈什食人魔的猛烈伏击。货物被拖进了食人魔的荒野据点，幸存的守卫因伤而死，乔丹的锻造计划也因此搁置，直到有冒险者能从这群野兽手中夺回它。"}},faq={{q="货物里有什么？",a="这批货物里装的是矿石，矮人白洛尔·石手会将其提炼成特制合金，并交给铁匠乔丹·斯迪威尔，用于他在铁炉堡的金属工艺制作。",al={"乔丹的矿石里有什么","这是什么矿石","乔丹的矿石内容物"}},{q="是谁偷走了乔丹的矿石？",a="当补给商队从湿地向南行进时，摩戈什食人魔发动了伏击，屠杀了护卫并将板条箱拖回了洛克湖东北部的领地。",al={"谁抢走了矿石货物","谁偷了它","食人魔矿石货物"}},{q="白洛尔·石手是谁？",a="白洛尔·石手是一位驻扎在洛克莫丹的矮人工匠，也是乔丹·斯迪威尔的老友。他安排了这批合金的运输，随后货物被食人魔抢走。",al={"白洛尔·石手","白洛尔是谁"}},{q="为什么这批货物对圣骑士很重要？",a="进行正义试炼的圣骑士需要这种合金，以帮助乔丹·斯迪威尔铸造一把圣光武器。",al={"圣骑士矿石货物","正义试炼矿石","为什么圣骑士需要这个"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="乔丹的精炼矿石",s="“乔丹的精炼矿石”是一箱专门为铁匠乔丹·斯迪威尔准备的高级金属。作为圣骑士神圣试炼的一部分，它是锻造一把充满美德的神圣武器所必需的基本材料。",h="“乔丹的精炼矿石”是一箱专门为铁匠乔丹·斯迪威尔准备的高级金属。作为圣骑士神圣试炼的一部分，它是锻造一把充满美德的神圣武器所必需的基本材料。",kw={"贝洛","铁炉堡","乔丹·斯迪威尔","圣骑士武器","精炼矿石","正义之试"},ang={["class:Paladin"]="获取这批精炼矿石是对圣骑士耐心与奉献精神的考验，也是他们锻造象征圣光的武器时所必须经历的身体试炼之一。",["profession:Blacksmithing"]="每一位工匠都明白，锻造杰作需要的是无瑕且经过精心准备的金属锭，而非未经加工的野外矿石。"},sec={{t="铁匠的材料",b="当乔丹·斯迪威尔着手打造一把配得上圣骑士称号的武器时，普通的材料显然无法满足要求。这位铁匠需要一系列稀有且苛刻的组件：一颗净化过的科尔宝石、坚固的白石橡木、他自己丢失的锻造锤，以及一批特制的精炼矿石。这批货物构成了这项神圣工作的金属基础，并被运往铁炉堡以完成正义之试。"}},faq={{q="乔丹的精炼矿石有什么用？",a="这些精炼矿石被送到铁炉堡外的乔丹·斯迪威尔手中，是圣骑士进行正义之试时锻造杰作武器所需的四种关键组件之一。",al={"精炼矿石的用途","乔丹用矿石做什么","矿石货物的用途"}},{q="谁准备了这些精炼矿石？",a="这批货物是由贝洛负责安排的，他监督着乔丹·斯迪威尔所需专业金属的精炼和调度工作。",al={"谁制作了矿石","贝洛矿石","谁精炼了乔丹的矿石"}},{q="为什么乔丹需要这批特殊的货物？",a="乔丹·斯迪威尔打算锻造一个象征圣骑士身份与圣光的信物，这需要超越普通锻造废料的优质材料。这种经过特殊处理的金属能确保刀刃或锤头拥有配得上圣骑士身份的平衡感与纯度。",al={"为什么矿石很特殊","为什么乔丹不能使用普通铁矿","精炼矿石的原因"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="乔丹的铁锤",s="乔丹的铁锤是一件珍贵的传家宝，由人类铁匠乔丹·斯迪威尔的父亲传给他。从影牙城堡那闹鬼的大厅中找回它，对于锻造一把献给圣光的圣洁武器至关重要。",h="乔丹的铁锤是一件珍贵的传家宝，由人类铁匠乔丹·斯迪威尔的父亲传给他。从影牙城堡那闹鬼的大厅中找回它，对于锻造一把献给圣光的圣洁武器至关重要。",kw={"丹莫罗","铁炉堡","乔丹·斯迪威尔","圣骑士武器","影牙城堡","铁匠锤","正义试炼"},ang={["class:Paladin"]="找回这把传家之锤是正义试炼中艰巨考验的一部分，证明了圣骑士为了获得圣洁工艺的工具而冒险进入危险之地的决心。",["profession:Blacksmithing"]="每一位铁匠都能理解一位锻造大师与先辈传下来的锤子之间那份情感与实用的纽带。"},sec={{t="工匠的遗产",b="对于普通观察者来说，乔丹的铁锤可能看起来只是一把普通的铁匠锤，但对于乔丹·斯迪威尔来说，它代表着传承与命运。这件工具从他父亲那里继承而来，是乔丹作为铁炉堡外的一位锻造大师身份的核心。它不知何故落在了银松森林的影牙城堡那被遗弃的石墙内，必须先将其收回，乔丹才能开始尝试他的杰作——一件适合圣洁勇士的圣武。"}},faq={{q="乔丹的铁锤在哪里？",a="这把锤子位于影牙城堡那被诅咒的墙内，坐落在黑暗的银松森林中。进行正义试炼的圣骑士必须冒险进入这座被占领的堡垒将其找回。",al={"锤子位置","乔丹的锤子在哪里","去哪里找乔丹的铁锤"}},{q="为什么这把锤子对乔丹·斯迪威尔如此重要？",a="这把锤子是由乔丹的父亲传给他的。它承载着深厚的情感价值，是他锻造自己最伟大作品——一把圣光的圣洁武器——所需的工具。",al={"乔丹为什么想要这把锤子","乔丹·斯迪威尔的锤子传说"}},{q="这把锤子找回后有什么用途？",a="一旦连同木材、矿石和宝石一起被带回到铁炉堡大门外的乔丹身边，他就会用它来锻造一件宏伟的圣洁武装，以奖励协助他的圣骑士。",al={"这把锤子能制造什么","正义试炼锤子的用途"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:kadrak-s-flag"] = {n="卡德拉克的旗子",s="卡德拉克的旗子是部落的象征，由侦察兵卡德拉克在贫瘠之地与灰谷的边界处交给玩家。在消灭了钥匙保管者林莎瑞尔后，这面旗帜被直接插在猛禽洞穴中，作为对石爪峰暗夜精灵和树妖的严正警告。",h="卡德拉克的旗子是部落的象征，由侦察兵卡德拉克在贫瘠之地与灰谷的边界处交给玩家。在消灭了钥匙保管者林莎瑞尔后，这面旗帜被直接插在猛禽洞穴中，作为对石爪峰暗夜精灵和树妖的严正警告。",kw={"贫瘠之地","部落势力","卡德拉克","卡德拉克的旗子","林莎瑞尔","石爪","石爪峰","猛禽洞穴"},ang={["faction:Horde"]="将这面旗帜深插在猛禽洞穴中，是对领土力量的强硬宣示，证明了部落在受到挑衅时，会直接反击暗夜精灵的圣地。",["race:NightElf"]="用血红色的部落旗帜玷污猛禽洞穴，是对石爪峰守护者赤裸裸的侮辱和挑衅。"},sec={{t="反抗的标记",b="卡利姆多的边境局势紧张，联盟的信使和哨兵经常试探部落领地的边界。当一份破译的卷轴揭露了来自猛禽洞穴钥匙保管者、树妖林莎瑞尔的通讯后，卡德拉克认为仅仅杀掉她是不够的。他交出这面绯红色的旗帜，要求将其插在石爪峰顶的洞穴深处。通过将部落的旗帜插在暗夜精灵的神圣山地堡垒之一中，卡德拉克意在传达一个明确的信息：对贫瘠之地的侵犯将会招致联盟领土上的猛烈报复。"}},faq={{q="卡德拉克的旗子有什么用？",a="在击杀钥匙保管者林莎瑞尔后，旗子被插在石爪峰顶的猛禽洞穴内。将部落的旗帜插在她们的据点中，旨在警告暗夜精灵不要再派遣侦察兵和信使进入贫瘠之地。",al={"旗子的用途","为什么插旗","旗子有什么作用"}},{q="是谁给了你这面旗子？",a="卡德拉克，一名驻扎在北部贫瘠之地与灰谷边界哨所的兽人侦察兵，作为他确保该地区安全行动的一部分，将这面旗帜交给了部落的冒险者。",al={"谁给了旗子","在哪里获取旗子","卡德拉克位置"}},{q="旗子插在哪里？",a="这面旗帜被插在猛禽洞穴内，这是一个位于石爪山脉中石爪峰西坡的洞穴圣地。",al={"我该把旗子插在哪里","旗帜位置","猛禽洞穴插旗点"}},{q="林莎瑞尔是谁？",a="林莎瑞尔是一名担任猛禽洞穴钥匙保管者的树妖。她一直负责协调信使进入部落领地，直到卡德拉克拦截了她的通讯并下令将其除掉。",al={"树妖林莎瑞尔","林莎瑞尔是谁","钥匙保管者"}}},fp="13,174,18.412.0,31.201.0,23.143.0,26.127.0,18.161.0"}
P.entries["item:keg-of-shindigger-stout"] = {n="矿工烈酒",s="矿工烈酒是驻守在丹加洛克的火枪手与士兵们所酿造并守护的一种强力矮人烈酒。塔伦米尔的皇家药剂师协会对它垂涎三尺，但这并非为了把它当作晚间饮品，而是将其作为传播新合成瘟疫的伪装载体。",h="矿工烈酒是驻守在丹加洛克的火枪手与士兵们所酿造并守护的一种强力矮人烈酒。塔伦米尔的皇家药剂师协会对它垂涎三尺，但这并非为了把它当作晚间饮品，而是将其作为传播新合成瘟疫的伪装载体。",kw={"药剂师林度恩","丹加洛克","矮人烈酒","苦痛药剂","矿工烈酒","塔伦米尔"},ang={["faction:Horde"]="袭击丹加洛克可以破坏坐落在希尔斯布莱德丘陵东南部山区的一个危险的联盟军事立足点。",["race:Undead"]="对于被遗忘者来说，窃取一桶珍贵的矮人烈酒纯粹是实用的炼金术：酒精可以掩盖为希尔瓦娜斯女士研制的致命混合物的气味和味道。"},sec={{t="矮人的最爱",b="丹加洛克是位于希尔斯布莱德丘陵东南部的一座险峻的矮人堡垒，由铁炉堡的矮人们坚决守卫着。在坚固的军营和食堂里，坚韧的守军们分享着矿工烈酒，以此抵御严寒以及针对地区敌人的持久围攻。这种酒口感浓烈且存量充足，是该驻军日常生存的必需品。"},{t="药剂师林度恩的毒药容器",b="尽管矮人们将矿工烈酒视为战斗后的诚实奖赏，但塔伦米尔的药剂师林度恩却将其视为散布恐怖的理想载体。林度恩受命开发被遗忘者邪恶的苦痛药剂，但他拒绝在野兽身上测试这种致命配方。相反，他寻求一桶完好的烈酒，将其混入药剂中，制造出一种受污染的贡品，意图用来对付被关押在塔伦米尔的人类农夫。"}},faq={{q="矿工烈酒有什么用途？",a="塔伦米尔的药剂师林度恩想要这桶矿工烈酒来测试他刚提炼出来的苦痛药剂。他并不想把这种剧毒浪费在实验动物身上，而是打算将其掺入矮人烈酒中，对类人生物目标进行致命的实地测试。",al={"为什么要获取矿工烈酒","矿工烈酒的用途","林度恩用酒桶做什么"}},{q="在哪里可以找到矿工烈酒？",a="矿工烈酒桶储存在位于希尔斯布莱德丘陵东南部的丹加洛克矮人要塞深处。它们通常放在矮人步兵驻扎的食堂和下层营房里。",al={"酒桶位置","矿工烈酒在哪里","寻找烈酒"}},{q="谁酿造了矿工烈酒？",a="它是由丹加洛克的矮人们酿造并保存的，他们代表铁炉堡在希尔斯布莱德丘陵维持着一座防御森严的驻军据点。",al={"谁酿造矿工烈酒","这是矮人烈酒吗"}},{q="为什么药剂师林度恩不自己酿酒来做实验？",a="林度恩索要一桶丹加洛克已有的烈酒，以便将其用于实验；任务中并未描述他自己酿造酒精。",al={"为什么要偷矮人啤酒","为什么要丹加洛克的啤酒"}}},fx={b55cb0ca={q="什么是矿工烈酒？",a="矿工烈酒是一桶浓烈的矮人麦酒，由驻扎在丹加洛克要塞中的铁炉堡矮人保存。这桶酒原本是供驻守希尔斯布莱德丘陵的矮人士兵饮用的，但其烈性酒液也使它成为药剂师林度恩代表皇家药剂师协会进行试验的理想媒介。",al={"什么是矿工烈酒","矿工烈酒桶的信息"}}},fp="23,173,18.261.0,32.225.1,34.154.0,45.162.0,27.125.0,63.172.0"}
P.entries["item:ken-zigla-s-draught"] = {n="肯兹格拉的伤药",s="肯兹格拉的伤药是一种药力强大、味道苦涩的药剂，由石爪山脉的肯兹格拉调制。它的配方旨在让受重伤的人恢复足够的体力，从而能在不因流血过多而死亡的情况下进行移动。",h="肯兹格拉的伤药是一种药力强大、味道苦涩的药剂，由石爪山脉的肯兹格拉调制。它的配方旨在让受重伤的人恢复足够的体力，从而能在不因流血过多而死亡的情况下进行移动。",kw={"陶拉祖营地","多格拉","步兵劳格玛","肯兹格拉的伤药","肯兹格拉","石爪山脉","魅魔任务","贫瘠之地"},ang={["class:Warlock"]="获取并运送这种伤药是召唤和契约魅魔的试炼中的关键一步，这证明了术士在贫瘠之地上的足智多谋与追踪能力。",["faction:Horde"]="由于陶拉祖营地因后勤巡逻而人手不足，这种伤药成了营救这名被困在野猪人敌后的特工的唯一生命线。"},sec={{t="苦涩的良药",b="这种强力药剂由石爪山脉的肯兹格拉调制，是供垂死之人使用的紧急复苏手段。这种药剂药力极强，必须小心控制用量；一次服用超过半剂可能会导致病人的循环系统过载，从而引发致命的失血。服用半剂能提供足够的体力来移动并逃离迫在眉睫的危险，剩下的部分则必须等到病人经过一整夜的休息、身体状态趋于稳定后才能服用。"},{t="贫瘠之地的慈悲",b="这种伤药在寻找多格拉（Dogran）的过程中起到了至关重要的作用。多格拉是一名被陶拉祖营地北部的野猪人俘虏并折磨的特工。部落术士在寻找魅魔的信物时，将这种苦涩的合剂直接送到了敌对的剃刀鬃毛营地。饮下药剂后，多格拉重获了一丝生机，让他得以蹒跚着逃离俘虏他的敌人，尽管他因伤势过重而永久地失去了肢体的行动能力。"}},faq={{q="肯兹格拉的伤药有什么用途？",a="这是一种药力强大的药剂，旨在为垂死或重伤的人恢复体力。正确服用的话，能让伤者获得足够的精力站起来并逃离囚禁，同时不会导致致命的失血。",al={"肯兹格拉的伤药有什么用","伤药的用途","我为什么需要肯兹格拉的伤药"}},{q="是谁制作了这种伤药？",a="它由肯兹格拉调制，这是一位住在石爪山脉的药剂师或草药师，他调制此药正是预见到会有人来为多格拉寻求援助。",al={"谁调制了伤药","肯兹格拉是谁","肯兹格拉的位置"}},{q="为什么伤药必须分两次，每次只服用一半？",a="这种调合物对身体的影响极其猛烈。半剂剂量能赋予病人足够的活力以进行移动，且不会引起严重的出血；而剩下的半剂必须在病人休息一晚之后才能服用，以避免致命的身体负荷。",al={"如何服用肯兹格拉的伤药","半剂伤药","伤药说明"}},{q="谁会服用这种伤药？",a="它最终被送到了多格拉手中。他是一名特工，被关押在贫瘠之地陶拉祖营地北部的一个野猪人营地中，且身受重伤。",al={"谁喝了伤药","多格拉是谁","在哪里交付伤药"}},{q="为什么术士要被派去取这种药？",a="寻找魅魔的部落术士被指引去寻找多格拉，他身上持有一件带有强烈情感共鸣的物品。协助运送伤药是接近他并获取召唤仪式所需之物的必要条件。",al={"为什么术士需要这个","魅魔任务伤药","术士任务肯兹格拉"}}},fx={["6eadaa9a"]={q="什么是肯兹格拉的伤药？",a="这是石爪山脉的巨魔药剂师肯兹格拉调制的一剂强效苦涩药剂。它旨在帮助伤者承受严重创伤，药效强大到足以恢复一名身受致命重伤的士兵的活力，让其能够行动，不过使用时必须格外谨慎。",al={"什么是伤药","肯兹格拉的伤药","肯兹格拉的药剂"}},["42d17912"]={q="为什么需要肯兹格拉的伤药？",a="一个名叫多格兰的兽人被贫瘠之地的野猪人抓获并残酷折磨。他身受重伤、濒临死亡，被囚禁期间若没有伤药的恢复魔力，就无法活下来或逃脱。陶拉祖营地的步兵劳格玛急需这种药剂，好让多格兰支撑着伤势逃离俘虏。",al={"为什么需要伤药","谁需要肯兹格拉的伤药","为什么要制作伤药"}}},fp="19,184,15.354.0,20.294.1,37.180.0,22.71.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khazgorm-s-journal"] = {n="卡兹戈姆的日记",s="卡兹戈姆的日记是勘探员卡兹戈姆所保存的个人实地记录，他是铁炉堡矮人在南贫瘠之地巴尔莫丹发掘工作的领队。该日记详细记载了探险者协会在石塔牛头人部落所宣称的领地上进行入侵活动的细节。",h="卡兹戈姆的日记是勘探员卡兹戈姆所保存的个人实地记录，他是铁炉堡矮人在南贫瘠之地巴尔莫丹发掘工作的领队。该日记详细记载了探险者协会在石塔牛头人部落所宣称的领地上进行入侵活动的细节。",kw={"巴尔莫丹","贫瘠之地","矮人","探险者协会","加恩·石塔","日记","卡兹戈姆","勘探员"},ang={["faction:Horde"]="回收这本书有助于加恩·石塔保卫卡利姆多，抵御深入部落主权领地的入侵性联盟探险队。",["race:Tauren"]="这本日记是铁炉堡入侵者冷酷无情的有力证据，他们炸毁了神圣的祖先土地，完全不顾及石塔部族。"},sec={{t="破坏的记录",b="这本日记属于勘探员卡兹戈姆，他指挥着在南贫瘠之地山坡上进行挖掘的大型机械和爆破作业。这些笔记所反映的并非探险者协会宣称的那种田园牧歌式的知识探寻，而是一场残酷的发掘运动，导致石塔部族流离失所。牛头人试图通过和平手段解决问题的尝试遭到了拒绝，使得这本日记成为了加恩·石塔梦寐以求的战利品，他正试图通过日记来了解并拆解矮人在他家园的势力。"},{t="战术的转变",b="这本日记是从挖掘现场帐篷和石柱间卡兹戈姆的遗骸中回收的，它为加恩提供了关于矮人探险队结构、装备和弱点的关键见解。通过审阅这位勘探员的个人笔记，加恩得以改变策略，从单纯地驱逐工人转变为对挖掘机械进行有针对性的破坏，这使该日记成为了巴尔莫丹争端的一个转折点。"}},faq={{q="这本日记属于谁？",a="这本日记属于勘探员卡兹戈姆，他是驻扎在南贫瘠之地巴尔莫丹发掘现场的铁炉堡矮人挖掘队的领队。",al={"谁拥有这本日记","卡兹戈姆","勘探员卡兹戈姆"}},{q="加恩·石塔为什么要这本书？",a="加恩·石塔寻求这本日记是为了探查那些驱逐了他部族的矮人入侵者的计划与秘密，并利用卡兹戈姆的笔记来策划对巴尔莫丹营地的进一步打击。",al={"加恩为什么要日记","加恩任务日记","加恩的回收之书"}},{q="在哪里可以找到这本日记？",a="这本日记由勘探员卡兹戈姆本人携带，可以在巴尔莫丹以南的现行发掘现场的帐篷和岩柱间找到他。",al={"卡兹戈姆的日记在哪里","寻找卡兹戈姆的日记","卡兹戈姆位置"}},{q="这本日记揭露了关于矮人的什么信息？",a="它揭露了探险者协会不那么学术的一面，展示了他们对埋藏文物和泰坦遗产的追求，往往是以石塔牛头人等原住民部族的直接、暴力牺牲为代价的。",al={"贫瘠之地探险者协会","矮人挖掘场秘密","巴尔莫丹目的"}}},fp="18,195,23.431.0,18.361.1,31.127.0,40.186.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="克拉文·摩特维克的日记",s="《克拉文·摩特维克的日记》是军情七处特工从西部荒野东北部的迪菲亚塔楼中回收的一份情报报告。这本日记被锁在从暮色森林运出的一个箱子里，详细记录了迪菲亚潜行者试图制造能够让死者复生的炼金药剂的秘密企图。",h="《克拉文·摩特维克的日记》是军情七处特工从西部荒野东北部的迪菲亚塔楼中回收的一份情报报告。这本日记被锁在从暮色森林运出的一个箱子里，详细记录了迪菲亚潜行者试图制造能够让死者复生的炼金药剂的秘密企图。",kw={"迪菲亚塔楼","暮色森林宝箱","日记","克拉文·摩特维克","mathias shaw","毒药","军情七处","赞吉尔"},ang={["class:Rogue"]="潜入塔楼夺取摩特维克的日记是军情七处潜行者的试炼场，旨在展示开锁和潜行的熟练程度，并引入制作致命毒药的工艺。",["faction:Alliance"]="这本日记为暴风城的谍报头目们提供了确凿证据，证明迪菲亚潜行者的起义已不仅仅局限于心怀不满的劳工，还涉及与巨魔巫医和炼金亡灵法术的勾结。"},sec={{t="恐怖的配方",b="军情七处长期监视着西部荒野北部山脊上耸立的那座迪菲亚塔楼，并注意到从暮色森林阴暗边界运来的奇怪货物，以及守卫在塔楼旁那些扭曲的非人生物。在最顶层的箱子里发现的这本日记属于克拉文·摩特维克，它揭示了这些货物背后的目的。摩特维克记录的炼金研究显示，与荆棘谷赞吉尔巨魔有关联的炼金术士发现了一种利用特殊毒药和药剂复活无心智亡灵仆从的方法，迪菲亚潜行者正试图效仿这种做法，以扩充自己的队伍。"},{t="军情七处的情报",b="暴风城情报机构首领马迪亚斯·肖尔优先回收了摩特维克的日记，以拼凑出迪菲亚潜行者更广泛的联盟网络。这些记录不仅证实了黑暗的复生实验，还揭示了连接暮色森林、荆棘谷地精和迪菲亚潜行者的非法后勤支持。对于效忠王国的潜行者特工而言，回收这份黑暗研究标志着他们掌握毒药艺术的关键转折点。"}},faq={{q="什么是《克拉文·摩特维克的日记》？",a="这是一本由克拉文·摩特维克编写的研究笔记，他是西部荒野东北部迪菲亚塔楼内的一名特工。书中包含关于炼金亡灵法术和非法补给路线的记录。",al={"克拉文的日记是什么","摩特维克的日记","这个物品是什么"}},{q="这本日记在哪里可以找到？",a="它被锁在西部荒野北部迪菲亚塔楼顶层的一个暮色森林宝箱中，由亡灵守卫看守，必须从克拉文的一个怪物守卫身上获得钥匙才能打开。",al={"哪里可以找到克拉文的日记","克拉文日记的位置","暮色森林宝箱位置"}},{q="日记里写了什么秘密？",a="文本显示，荆棘谷的赞吉尔巨魔已经研制出能够复活并控制死者的毒药，这是迪菲亚潜行者一直在积极获取并试图部署的一种致命配方。",al={"日记里说了什么","日记中的秘密","赞吉尔毒药"}},{q="谁需要这本日记？",a="暴风城军情七处情报机构的首领马迪亚斯·肖尔请求获得这份文件，以监视迪菲亚潜行者的后勤动向，并指导王国特工了解战术毒药的危险与用途。",al={"谁来接收克拉文的日记","我该把日记给谁","马迪亚斯·肖尔 日记"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-horn"] = {n="科多兽角",s="科多兽角是取自漫步在贫瘠之地北部的野兽身上的坚固天然试剂。对于塞纳里奥德鲁伊来说，它们致密的成分为实验性草药混合物提供了必要的强度和效力，最显著的用途是制作治疗中毒野生动物的药膏。",h="科多兽角是取自漫步在贫瘠之地北部的野兽身上的坚固天然试剂。对于塞纳里奥德鲁伊来说，它们致密的成分为实验性草药混合物提供了必要的强度和效力，最显著的用途是制作治疗中毒野生动物的药膏。",kw={"贫瘠之地","塞纳里奥","地根草","瞪羚","科多兽角","毒药","图加·符文图腾"},ang={["class:Druid"]="对于年轻的部落德鲁伊来说，在图加·符文图腾的指导下收集这些兽角是一项关键的成人礼，能让他们逐步掌握对自然界毒素的驾驭能力。",["race:Tauren"]="牛头人对科多兽怀有崇高的敬意，从它们身上索取时也始终保持敬意和目的——在这种情况下，是为了保护贫瘠之地脆弱的生态系统。"},sec={{t="平原上的试剂",b="尽管科多兽因其耐力和力量而受到贫瘠之地牛头人的崇敬，但它们的角也具有实际的药用价值。在十字路口工作的图加·符文图腾利用完整的兽角来增强他草药疗法的效力。碎片和残渣不足以提炼这些药膏；只有从漫步在干旱平原上的成年科多兽身上采集的完整兽角才具备足够的强度来巩固治疗效果。"}},faq={{q="科多兽角有什么用途？",a="图加·符文图腾将它们与地根草和纯净水一起使用，酿制成一种治疗药膏。这种混合物是专门为治疗贫瘠之地各地中毒的瞪羚而配制的，是德鲁伊学习掌握对抗毒药的自然疗法过程中关键的一步。",al={"科多兽角用途","为什么收集科多兽角","科多兽角的使用"}},{q="这些兽角在哪里采集？",a="它们采集自漫步在贫瘠之地北部地区的贫瘠之地科多兽和迷失的贫瘠之地科多兽，通常在十字路口和周围灌木丛之间觅食。",al={"哪里可以找到科多兽角","科多兽角位置","哪些科多兽掉落兽角"}},{q="为什么德鲁伊不能使用兽角碎片？",a="图加·符文图腾指出，仅仅是碎片和残渣缺乏调配药膏所需的效力。这种疗法需要完整、无损的兽角来配制出足以抵御剧毒的强力药剂。",al={"为什么不能用断裂的兽角","兽角碎片"}},{q="对于德鲁伊来说，猎杀科多兽被认为是尊重的表现吗？",a="是的，只要它是为了服务于更宏大的自然平衡。德鲁伊只会从土地及其生物身上索取治愈大灾难所需的东西，例如困扰当地瞪羚群的神秘中毒现象。",al={"德鲁伊猎杀科多兽","平衡与科多兽"}}},fp="9,131,23.270.0,29.196.0,32.140.0,44.160.0,51.171.0"}
P.entries["item:kodo-liver"] = {n="科多兽的肝脏",s="科多兽的肝脏是一种从徘徊在贫瘠之地平原上的巨型科多兽身上采集到的硕大器官。虽然这绝非标准的烹饪食材，但棘齿城的酿酒师德罗恩却需要它，作为发酵一种从游历四方的酿酒大师陈·风暴烈酒那里学到的非正统穴居人麦酒的必备原料。",h="科多兽的肝脏是一种从徘徊在贫瘠之地平原上的巨型科多兽身上采集到的硕大器官。虽然这绝非标准的烹饪食材，但棘齿城的酿酒师德罗恩却需要它，作为发酵一种从游历四方的酿酒大师陈·风暴烈酒那里学到的非正统穴居人麦酒的必备原料。",kw={"贫瘠之地","酿造","陈·风暴烈酒","德罗恩","科多兽","科多兽的肝脏","棘齿城","穴居人麦酒"},ang={["profession:Cooking"]="虽然普通的科多兽肉在卡利姆多中部是主要的口粮来源，但科多兽的肝脏却被认为过于腥臭刺鼻，不适合标准的家庭烹饪——这使得它被掺入棘齿城的穴居人麦酒中显得更加臭名昭著。",["race:Tauren"]="牛头人尊重他们捕猎的科多兽的每一个部位，但即使是最老练的平原奔跑者，对于棘齿城的那些地精和外乡人将神圣的科多兽内脏酿成新奇麦酒的行为，也会侧目而视。"},sec={{t="一种怪异的酿造试剂",b="贫瘠之地的伟大科多兽主要被牛头人和游荡的掠食者捕猎，以获取其坚韧的皮革和营养丰富的肉。然而，新鲜的科多兽的肝脏在棘齿城港口小镇却有着更为怪癖的用途。酿酒师德罗恩将这种器官与雷鹰唾液腺和雷霆腺一起使用，重现了陈·风暴烈酒教给他的强力酒水：穴居人麦酒。德罗恩声称这种不寻常的混合配方劲头十足，为冒险的旅人们提供了一种直接来自卡利姆多中心荒野的浓烈特饮。"}},faq={{q="科多兽的肝脏有什么用途？",a="科多兽的肝脏会被送往棘齿城的酿酒师德罗恩那里。他将这种器官加入到一种强力的穴居人麦酒配方中，而这最初是由著名的熊猫人酿酒大师陈·风暴烈酒传授给他的。",al={"科多兽的肝脏用途","为什么需要科多兽的肝脏","科多兽的肝脏是做什么用的"}},{q="哪些生物会掉落科多兽的肝脏？",a="它可以通过剥取在贫瘠之地开阔草原上徘徊的各种科多兽获得，包括普通的贫瘠之地科多兽、毛皮科多兽、迷路的科多兽、大型科多兽，以及稀有野兽，如拉克塔曼尼和布隆图斯。",al={"哪里获得科多兽的肝脏","谁掉落科多兽的肝脏","科多兽的肝脏来源"}},{q="为什么会有人把动物器官放进麦酒里？",a="酿酒师德罗恩酿酒所依据的是陈·风暴烈酒传授的那些充满异域风情和怪诞古怪的配方。对于穴居人麦酒来说，诸如科多兽的肝脏和元素腺体之类的生鲜器官，赋予了这种饮料其著名的劲头和令人印象深刻的独特风味。",al={"为什么啤酒里放肝脏","酒里的科多兽的肝脏"}}},fp="10,140,25.380.0,30.96.0,35.129.0,42.181.0"}
P.entries["item:kodobane-s-head"] = {n="科多班恩的战利品",s="科多班恩的战利品是考尔克半人马部落狡猾的酋长巴拉克·科多班恩被斩下的头颅。作为他已死的证明，这个头颅被带给了兽人督军雷加·死门，以证明遗忘之池附近的半人马威胁已被铲除。",h="科多班恩的战利品是考尔克半人马部落狡猾的酋长巴拉克·科多班恩被斩下的头颅。作为他已死的证明，这个头颅被带给了兽人督军雷加·死门，以证明遗忘之池附近的半人马威胁已被铲除。",kw={"巴拉克","贫瘠之地","半人马","十字路口","死门","遗忘之池","科多班恩","考尔克","雷加"},ang={["faction:Horde"]="贫瘠之地的十字路口是连接奥格瑞玛和雷霆崖的重要陆路枢纽；压制像科多班恩这样的半人马首领对于保障商队路线的安全至关重要。",["race:Tauren"]="数代以来，半人马一直在卡利姆多追杀游牧的牛头人，几乎将其逼入绝境。击杀巴拉克·科多班恩不仅报了数个世纪的血海深仇，也保护了莫高雷和贫瘠之地的牧场。"},sec={{t="战争的战利品",b="贫瘠之地的考尔克半人马一直以来都是一群四分五裂、杂乱无章的麻烦制造者，但野心勃勃的督军们的崛起有可能将这些劫掠的部落联合成一支军队。巴拉克·科多班恩在郁郁葱葱的遗忘之池建立了营地，切断了重要的绿洲资源，并袭击了附近的道路。驻扎在十字路口以西地堡中的雷加·死门要求得到他被斩下的头颅，以此作为确凿的证据，证明这名指挥官再也无法集结他的族人为祸部落。"}},faq={{q="巴拉克·科多班恩是谁？",a="巴拉克·科多班恩是考尔克半人马中一位著名的酋长。与他那些纪律涣散的族人不同，巴拉克拥有组织战团所需的狡诈和气度，他在遗忘之池周围扎营，以确立考尔克在贫瘠之地北部的统治地位。",al={"巴拉克·科多班恩","科多班恩是谁","巴拉克背景故事"}},{q="为什么雷加·死门想要他的头颅？",a="雷加·死门的任务是保卫部落在贫瘠之地的领土。由于半人马通常各自为政，那些具有真正战术眼光的首领便成了被清除的目标。要求得到科多班恩的头颅可以确保这名酋长是确实被杀，而不是仅仅被驱逐了。",al={"为什么要拿头颅","雷加·死门头颅","科多班恩悬赏"}},{q="巴拉克·科多班恩在哪里？",a="巴拉克·科多班恩将他的营地设在被称为遗忘之池的北部绿洲附近，就在贫瘠之地十字路口的西北方。",al={"巴拉克位置","科多班恩在哪里","巴拉克刷新"}},{q="杀死巴拉克能阻止考尔克的威胁吗？",a="不能。巴拉克·科多班恩只是集结考尔克的几位督军中的第一人。他的死扰乱了他们在遗忘之池的部署，但像狂躁的维罗格和赫兹鲁尔·血印这样的其他首领仍在指挥半人马在整个贫瘠之地进行侵略活动。",al={"半人马被打败了吗","巴拉克死后会发生什么"}}},fp="15,195,15.436.0,23.245.0,41.250.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="克拉维尔的箱子",s="“克拉维尔的箱子”是一个沉重的包裹，由身处闪光平原沙漠赛道的克拉维尔·浓须寄出。它原本是要送往荆棘谷的奈辛瓦里远征队，其中装着专门用于猎杀丛林中最致命猎物的特制狩猎弹药。",h="“克拉维尔的箱子”是一个沉重的包裹，由身处闪光平原沙漠赛道的克拉维尔·浓须寄出。它原本是要送往荆棘谷的奈辛瓦里远征队，其中装着专门用于猎杀丛林中最致命猎物的特制狩猎弹药。",kw={"弹药","赫米特·奈辛瓦里","克拉维尔·浓须","克拉维尔的箱子","沙漠赛道","闪光平原","荆棘谷"},ang={["class:Hunter"]="该箱子包含专门为高端矮人狩猎步枪设计的特制重型弹药，专为大型猎物远征而定做。",["race:Dwarf"]="这次投递完全是矮人之间的事务，连接着克拉维尔·浓须在盐碱地的商业交易与东部王国著名的奈辛瓦里狩猎队。"},sec={{t="丛林投递",b="“克拉维尔的箱子”由精明的商人克拉维尔·浓须在沙漠赛道发出，代表着一笔跨越大陆尚未完成的商业交易。该货物由一位富有的矮人顾客在几周前订购，但由于延误，买家早已离开了卡利姆多。为了不失去这位已经支付了运费的富有顾客的好感，克拉维尔委托过往的冒险者将这个箱子一路运送到北荆棘谷。"},{t="特制口径弹药",b="尽管这个箱子外表平平无奇，还沾着闪光平原的盐尘，但里面装着的是致命的货物：专为狩猎步枪设计的重型特制口径弹药。当货物送达格罗姆高营地北部的远征队营地时，收货人指出，这些强力的子弹深受大型猎物猎人的青睐，对于在丛林树冠中生存至关重要。"}},faq={{q="克拉维尔的箱子里装着什么？",a="箱子里装着特制口径的狩猎弹药。这些大口径弹药是专门为猎杀野外危险野兽的大型猎物步枪所准备的。",al={"箱子里有什么","箱子内容物","克拉维尔的箱子里是什么"}},{q="是谁寄出了克拉维尔的箱子？",a="它是由克拉维尔·浓须寄出的，他是一位在千针石林闪光平原的赛车和赌博活动中做生意的矮人商人。",al={"谁给的箱子","谁拥有克拉维尔的箱子"}},{q="这个箱子需要送到哪里？",a="这个箱子必须运送到北荆棘谷的奈辛瓦里狩猎远征队营地，该营地位于格罗姆高营地以北的河流沿岸。",al={"哪里交付箱子","箱子目的地","谁接收克拉维尔的箱子"}},{q="为什么投递会被延误？",a="包裹花了几周时间才到达千针石林的盐碱地，在此期间，顾客已经收拾行囊出发前往荆棘谷的丛林了。",al={"为什么克拉维尔花了这么久","为什么延误"}}},fx={["3beca7b7"]={q="什么是克拉维尔的箱子？",a="这是克拉维尔·浓须在闪光平原的沙漠赛道保管的一件沉重货物。箱子经过妥善包装，适合长途运输，准备横越卡利姆多和无尽之海，里面装着专门的狩猎补给品，供前往荆棘谷荒野的探险队使用。",al={"什么是克拉维尔的箱子","克拉维尔的箱子信息","克拉维尔的箱子物品"}},["6061fde3"]={q="为什么有人想要克拉维尔的箱子？",a="箱子里装着专为大型猎物狩猎订购的特殊口径弹药。荆棘谷的奈辛瓦里狩猎队依靠沉重可靠的弹药猎杀丛林中最凶猛的野兽，因此这批延误的货物对他们营地的补给至关重要。",al={"奈辛瓦里为什么想要箱子","克拉维尔的箱子为什么重要","克拉维尔的箱子用途"}}},fp="14,270,24.473.0,24.405.0,30.174.0,24.158.0,33.152.0,29.176.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="克里尼格·糟鼻的獠牙",s="克里尼格·糟鼻的獠牙是一件残酷的战利品，取自北部贫瘠之地的刺鬃野猪人掠夺者首领。割下这枚獠牙，对于十字路口的索克来说，是威胁部落补给线的祸害已被铲除的不容置疑的证据。",h="克里尼格·糟鼻的獠牙是一件残酷的战利品，取自北部贫瘠之地的刺鬃野猪人掠夺者首领。割下这枚獠牙，对于十字路口的索克来说，是威胁部落补给线的祸害已被铲除的不容置疑的证据。",kw={"贫瘠之地","十字路口","克里尼格","野猪人","刺鬃","糟鼻","索克","獠牙"},ang={["faction:Horde"]="运送武器、物资和来自杜隆塔尔的定居者的车队是部落在贫瘠之地扩张的命脉。上交这枚獠牙可以保护这些至关重要的生命线。",["race:Orc"]="从被击败的指挥官身上取走战利品，反映了十字路口的兽人们所推崇的残酷而务实的战争风格，既展示了力量，又在敌人心中播下了恐慌。"},sec={{t="破碎野心的战利品",b="从杜隆塔尔向西进入贫瘠之地的补给车队一直面临着不断的骚扰，但在一位名叫克里尼格·糟鼻的凶猛刺鬃领袖的策划下，近期的袭击变得越发猖獗。为了削弱野猪人的协调能力，十字路口守卫指挥官索克下令铲除糟鼻。取下这位酋长的獠牙不仅提供了他已毙命的确凿证据，更是对刺鬃部族蓄意的侮辱，粉碎了他们的意志，使他们的战士群龙无首。"}},faq={{q="谁是克里尼格·糟鼻？",a="克里尼格·糟鼻是驻扎在十字路口东北部的刺鬃野猪人中的一位重要领袖。他组织了针对沿杜隆塔尔主路行进的部落补给车队的疯狂袭击，在他的死期来临前，他使这条补给线变成了一条险途。",al={"克里尼格·糟鼻","克里尼格是谁","糟鼻背景故事"}},{q="为什么索克一定要这枚獠牙？",a="索克要求这枚獠牙，既是作为克里尼格已死的铁证，也是对刺鬃部族的一种尖锐侮辱。割下阵亡野猪人酋长的獠牙会挫伤他们的自尊，令幸存的掠夺者士气低落。",al={"为什么需要獠牙","为什么要带獠牙给索克","索克的獠牙"}},{q="这枚獠牙取自何处？",a="这枚獠牙取自克里尼格·糟鼻的营地，营地位于十字路口东北部，坐落在杜隆塔尔进入贫瘠之地的主路以南的山脚附近。",al={"克里尼格在哪里","如何获得獠牙","糟鼻的位置"}},{q="除掉克里尼格对贫瘠之地有什么影响？",a="通过铲除克里尼格，索克认为刺鬃掠夺者将失去领导而陷入混乱。除掉他们的指挥官会导致其队伍内部大乱，并极大程度地遏制对重要补给运输的进一步袭击。",al={"袭击停止了吗","克里尼格之死的后果"}}},fp="25,172,28.413.0,27.217.0,42.176.0,26.170.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="克鲁恩的护身符",s="克鲁恩的护身符是一件属于克鲁恩的私人物品。克鲁恩是一名来自杜隆塔尔的年轻兽人猎人，他在怒水河沿岸失踪了。",h="克鲁恩的护身符是一件属于克鲁恩的私人物品。克鲁恩是一名来自杜隆塔尔的年轻兽人猎人，他在怒水河沿岸失踪了。",kw={"护身符","恐螯鳄","克鲁恩","米莎·托克伦","剃刀岭","怒水河"},ang={["class:Hunter"]="对于任何有抱负的追踪者来说，这是一个严酷的教训，揭示了低估陌生河流领地中凶猛野兽的危险性。",["race:Orc"]="克鲁恩的命运是一个悲剧性的提醒：虽然骄傲和尚武的荣耀驱动着兽人的传统，但鲁莽和忽视长者的智慧可能会导致迅速而毫无意义的死亡。"},sec={{t="怒水河畔的悲剧",b="克鲁恩是剃刀岭西北部一座农场里的一名倔强的年轻兽人。他急于证明自己的实力，对危险不屑一顾，于是冲出去猎杀潜伏在杜隆塔尔与贫瘠之地交界处怒水河里的凶猛恐螯鳄。他无视母亲米莎·托克伦的警告，固执的骄傲使他直接落入了河中捕食者的口中。他再也没有回来，只留下了这件被吞下的饰品，无声地证明他已经遇害并被吞噬。"}},faq={{q="克鲁恩是谁？",a="克鲁恩是一名冲动的年轻兽人猎人，他与母亲米莎·托克伦住在剃刀岭西北部的一座农场里。为了测试自己的力量，他无视关于野兽凶猛的警告，独自一人外出狩猎。",al={"克鲁恩是谁","克鲁恩背景故事","克鲁恩背景知识"}},{q="在哪里可以找到克鲁恩的护身符？",a="这枚护身符是从潜伏在杜隆塔尔怒水河岸边的恐螯鳄和受污染的恐螯鳄腹中找回的。",al={"在哪里可以找到护身符","克鲁恩的护身符位置","谁掉落克鲁恩的护身符"}},{q="谁想要找回克鲁恩的护身符？",a="他悲痛欲绝的母亲米莎·托克伦正在剃刀岭西北部的农场里等待儿子的消息。这枚护身符能给她带来最后痛苦的解脱，让她开始哀悼。",al={"谁需要护身符","在哪里上交克鲁恩的护身符","米莎·托克伦"}}},fx={["5d838632"]={q="什么是克鲁恩的护身符？",a="这件私人物品属于克鲁恩，他是剃刀岭西北方一座农场里的年轻兽人。他心高气傲，急于证明自己的实力，于是独自前往怒水河，想猎杀贫瘠之地边境附近凶猛的恐怖利口鳄。他没有凯旋而归，反而成了自己想要猎杀的野兽的猎物。这枚护身符连同他的遗骸一起被吞下，是这位年轻猎人仅存的遗物，也能证明他惨死的结局。",al={"什么是护身符","克鲁恩的护身符背景","护身符属于谁"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kuz-s-skull"] = {n="卡兹的颅骨",s="卡兹的颅骨是卡兹被砍下的头颅，它是南贫瘠之地一位著名的剃刀鬃毛野猪人掠夺者。卡兹从剃刀沼泽被带出来，曾协助策划了针对部落前哨站的暴力突袭，后来被一位曾是其同族、如今身陷囹圄的俘虏盯上并被除掉。",h="卡兹的颅骨是卡兹被砍下的头颅，它是南贫瘠之地一位著名的剃刀鬃毛野猪人掠夺者。卡兹从剃刀沼泽被带出来，曾协助策划了针对部落前哨站的暴力突袭，后来被一位曾是其同族、如今身陷囹圄的俘虏盯上并被除掉。",kw={"贫瘠之地","陶拉祖营地","卡兹","卡兹的颅骨","洛克·兽人克星","碎牙","纳克","剃刀鬃毛"},ang={["faction:Horde"]="带回卡兹的头颅可以直接保护十字路口和陶拉祖营地等部落定居点免受有组织的野猪人战争侵害。"},sec={{t="苦涩的宿怨",b="南贫瘠之地的平原上遍布着剃刀鬃毛部族，但他们有组织的侵略行动源于直接从剃刀沼泽派出的特定首领。卡兹与纳克（Nak）以及他们冷酷的首领洛克·兽人克星（Lok Orcbane）一起，协调了针对旅行者和诸如十字路口等定居点的残酷入侵。然而，他们内部的背叛最终导致了自己的毁灭。他们背叛了同为野猪人的碎牙，并将他抛弃在陶拉祖营地的笼中等死，这让他们结下了一个复仇心切的敌人。碎牙向部落勇士透露了卡兹的位置，这些勇士乐于砍下这位掠夺者的头颅，一劳永逸地终结他的袭击。"},{t="复仇的证据",b="将卡兹的颅骨带回陶拉祖营地，是这一南部战团三分之一指挥层已被摧毁的冷酷证明。对碎牙来说，这个头颅是对抛弃他的部族的甜蜜报复。对于驻扎在整个贫瘠之地的部落而言，卡兹的死打断了剃刀鬃毛部族协同攻势的脊梁，瓦解了他们的领导层，并使连接平原的补给道路获得了暂时的喘息之机。"}},faq={{q="卡兹是谁？",a="卡兹是从剃刀沼泽派往南贫瘠之地的三名狡猾的剃刀鬃毛野猪人之一。她与纳克和洛克·兽人克星一起，协助指挥了针对部落营地和补给线的致命伏击与突袭。",al={"卡兹是谁","卡兹背景故事","卡兹 剃刀鬃毛"}},{q="为什么碎牙想要卡兹的颅骨？",a="碎牙被他自己的同族背叛，并被抛弃在陶拉祖营地的笼中等死。在面对自己的末日之前，他渴望复仇，于是引导部落冒险者屠杀那些背信弃义的竞争对手，并带回他们的头颅作为证明。",al={"为什么碎牙想要卡兹死","碎牙的复仇"}},{q="卡兹在贫瘠之地的什么地方？",a="卡兹在贫瘠之地南部的深处游荡，与陶拉祖营地以南、靠近荆棘密布的边境地区的剃刀鬃毛野猪人一起驻扎。",al={"卡兹位置","哪里可以找到卡兹"}},{q="卡兹被杀后会发生什么？",a="将卡兹的颅骨以及纳克和洛克·兽人克星的头颅一同带给碎牙，便瓦解了引导剃刀鬃毛部族入侵的领导层，为保障南部贸易路线的安全铺平了道路。",al={"卡兹任务奖励","内部背叛的结果"}}},fp="11,197,13.445.0,20.314.1,12.193.0,38.228.0,34.119.0,32.170.0"}
P.entries["item:laced-pumpkin"] = {n="斑纹南瓜",s="斑纹南瓜是一种经过布瑞尔的药剂师乔汉研制的致命混合物处理过的普通葫芦。它被伪装成食物交给一名饥肠辘辘、被囚禁的血色十字军俘虏，作为被遗忘者日益增长的炼金武器库的一场实战测试。",h="斑纹南瓜是一种经过布瑞尔的药剂师乔汉研制的致命混合物处理过的普通葫芦。它被伪装成食物交给一名饥肠辘辘、被囚禁的血色十字军俘虏，作为被遗忘者日益增长的炼金武器库的一场实战测试。",kw={"药剂师乔汉","布瑞尔","血色十字军俘虏","恐惧之末","斑纹南瓜","皇家药剂师学会","提瑞斯法林地"},ang={["faction:Alliance"]="被俘狂热者的命运是对任何在被遗忘者领地被活捉的人类所面临的可怕命运的鲜明提醒。",["race:Undead"]="对于被遗忘者来说，将普通食物变成武器展示了皇家药剂师学会为确保提瑞斯法免受狂热活人十字军侵害而采取一切必要手段的实用主义。"},sec={{t="苦涩的收成",b="在未经训练的人眼中，斑纹南瓜看起来是从提瑞斯法林地枯萎的土壤中搜寻出的普通农产品。然而，在布瑞尔的药剂师乔汉的监督下，这种蔬菜被施加了旨在充分发挥不死潜力的实验性毒素。皇家药剂师学会不断寻找新的武器来击退北方的天灾军团以及从南方推进的活人部队，甚至将简单的收获品变成了感染和化学死亡的媒介。"},{t="地窖实验",b="斑纹南瓜的主要目的是对活体对象进行实战测试。在恐惧之末旅店阴暗潮湿的地窖里，被遗忘者俘虏者关押着一名饥饿的血色十字军俘虏。由于极度渴望食物，囚犯如释重负地接受了这份被污染的供品。在食用南瓜后，药剂师的混合物引发了剧烈的变异，将这名人类狂热者扭曲成了一只无脑的食尸鬼，他在痛苦中蹒跚了一会儿，便倒在冰冷的石地板上死去了。"}},faq={{q="什么是斑纹南瓜？",a="这是一个注入了布瑞尔的药剂师乔汉配制的实验性配方的田间南瓜，旨在测试被遗忘者炼金术对活体对象的影响。",al={"斑纹南瓜","毒南瓜","乔汉的南瓜"}},{q="谁吃了斑纹南瓜？",a="一名被关押在布瑞尔恐惧之末旅店地窖中的血色十字军俘虏，在被俘虏者饿了很久之后吃下了它。",al={"谁吃了它","南瓜目标","喂食南瓜"}},{q="当有人吃下南瓜后会发生什么？",a="南瓜被交给被俘的狂热者，作为乔汉最新配方的测试。当囚犯吃下它时，其精确的效果就会显现出来。",al={"南瓜效果","狂热者怎么了","狂热者食尸鬼"}},{q="被遗忘者为什么要制造这个？",a="药剂师乔汉和皇家药剂师学会正在测试新的生物混合物，以对抗北方的天灾军团和入侵的活人，并利用被俘的敌人作为测试对象。",al={"为什么制作毒南瓜","被遗忘者瘟疫测试"}}},fp="13,204,16.386.0,21.404.1,26.199.0,27.160.0,43.170.1,31.205.0"}
P.entries["item:laird-s-response"] = {n="莱尔德的回信",s="“莱尔德的回信”是由奥伯丁沿海港口的鱼类腌制工莱尔德所写的一封密封快件。这封信是写给鲁瑟兰村的娜莎·影歌的，详细介绍了大陆海洋生物与泰达希尔海岸周围异常肥硕的鱼类之间奇特的生态差异。",h="“莱尔德的回信”是由奥伯丁沿海港口的鱼类腌制工莱尔德所写的一封密封快件。这封信是写给鲁瑟兰村的娜莎·影歌的，详细介绍了大陆海洋生物与泰达希尔海岸周围异常肥硕的鱼类之间奇特的生态差异。",kw={"奥伯丁","黑海岸","钓鱼","莱尔德","莱尔德的回信","娜莎·影歌","鲁瑟兰村","泰达希尔"},ang={["race:NightElf"]="对于照料泰达希尔海岸的暗夜精灵来说，莱尔德的笔记提供了一个有趣且略带不安的线索，暗示着年轻的世界之树已经开始对周围的自然环境产生某种非自然的影响。"},sec={{t="关于鳞片与根须的问题",b="在查阅了笼罩之海各地的渔获报告后，奥伯丁的莱尔德注意到了一个显著的差异：从泰达希尔海岸捕获的鱼类明显比黑海岸大陆沿岸捕获的鱼类更大、更多。在这封写给娜莎·影歌的回信中，莱尔德分享了他的工作理论——新栽种的世界之树所散发的非自然气息和原始生命力，可能正在改变并刺激着周围的海洋生物。这封信由往返于海上的旅人传递，在鲁瑟兰村的渔民中引起了惊奇与好奇。"}},faq={{q="什么是“莱尔德的回信”？",a="这是一封由驻扎在奥伯丁的鱼类商人和腌制工莱尔德所写的快件，旨在回应泰达希尔的娜莎·影歌的询问。",al={"这是什么物品","莱尔德的回信","什么是莱尔德的回信"}},{q="莱尔德写信给谁？",a="这封回信是寄给住在泰达希尔南麓鲁瑟兰村的暗夜精灵娜莎·影歌的。",al={"谁收到了莱尔德的回信","谁收到了这封信","娜莎与莱尔德的信"}},{q="信中关于鱼类说了些什么？",a="莱尔德指出，在泰达希尔海岸捕获的鱼类明显比黑海岸大陆发现的鱼类更大、更丰富，这表明世界之树本身可能正在影响当地的海洋生物。",al={"为什么鱼那么大","黑海岸与泰达希尔的鱼类差异","莱尔德发现了什么"}},{q="这封信是如何传回鲁瑟兰村的？",a="信使可以搭乘从奥伯丁码头出发的定期渡轮，或者安排与飞行管理员凯莱斯·月羽的角鹰兽飞行。",al={"如何回到娜莎那里","鲁瑟兰到黑海岸的船","到娜莎那里的奥伯丁渡轮"}}},fp="16,164,28.464.0,25.136.0,24.105.0,40.175.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="湖岸爬行者苔藓",s="湖岸爬行者苔藓是一种有机化合物，是从栖息在洛丹米尔湖中黎明岛水域的爬行生物身上采集而来的。它是皇家药剂师学会所寻求的重要试剂，用于他们研制一种致命的新瘟疫的工作。",h="湖岸爬行者苔藓是一种有机化合物，是从栖息在洛丹米尔湖中黎明岛水域的爬行生物身上采集而来的。它是皇家药剂师学会所寻求的重要试剂，用于他们研制一种致命的新瘟疫的工作。",kw={"贝拉德","黎明岛","长老湖岸爬行者","法拉尼尔","湖岸爬行者","湖岸爬行者苔藓","洛丹米尔湖","新瘟疫","皇家药剂师学会"},ang={["profession:Herbalism"]="虽然这种苔藓是附着在水生野兽身上，而不是生长在普通的土壤中，但它代表了洛丹伦植物群中更为阴暗、更具实验性质的一部分，被采集用于药剂研究。",["race:Undead"]="带到药剂师区的每一份湖泊苔藓样本都让被遗忘者离完善新瘟疫更近了一步，从而确保对天灾军团和活人进行复仇。"},sec={{t="炼金收成",b="湖岸爬行者苔藓生长在洛丹米尔湖南部黎明岛附近徘徊的凶猛淡水兽类的皮上，由于洛丹伦被污染的水域环境，它具有独特的性质。药剂师贝拉德在阿鲁高的诅咒侵蚀他的心智之前，曾在日记中记录过它，并指出这种苔藓与湖中因古代瘟疫而死的生物化石上的痕迹物质相似。当被被遗忘者特工回收后，样本会被直接送往幽暗城的药剂师区，为大药剂师法拉尼尔的黑暗研究提供燃料。"},{t="助长新瘟疫",b="这种苔藓不仅仅是一种奇特的水生植物；它构成了被遗忘者标志性武器研发的关键阶段。除了从湖岸潜藏者身上采集的相关苔藓和从当地邪鳍鱼人身上获取的病变硬瘤外，爬行者苔藓还提供了精炼一种足以消灭活体组织和天灾军团菌株所需的有机基础。尽管发现其用途的药剂师已经失踪，但皇家药剂师学会仍在为了黑暗女王的服务而继续酿造他的配方。"}},faq={{q="湖岸爬行者苔藓有什么用途？",a="它是大药剂师法拉尼尔和皇家药剂师学会在幽暗城用于酿造和精炼他们的新瘟疫时所使用的炼金试剂。",al={"爬行者苔藓用途","为什么要采集湖岸爬行者苔藓","湖岸爬行者苔藓用法"}},{q="这种苔藓来自哪里？",a="它采集自栖息在洛丹米尔湖东部黎明岛南部水域周围的湖岸爬行者和长老湖岸爬行者身上。",al={"哪里获得爬行者苔藓","爬行者苔藓位置","湖岸爬行者位置"}},{q="是谁发现了这种苔藓的炼金价值？",a="药剂师贝拉德在阿鲁高的诅咒使他成为焚木村中一个没有思想的仆从之前，曾在他的野外日记中记录了这种苔藓的独特属性。他的笔记后来被药剂师伦弗利尔回收。",al={"谁发现了苔藓","贝拉德 苔藓","谁写了关于爬行者苔藓的记录"}},{q="谁会接收采集来的苔藓？",a="大药剂师法拉尼尔在幽暗城的药剂师区接收这些苔藓，并将其与湖岸潜藏者苔藓和硬瘤结合起来以推进他的研究。",al={"谁需要爬行者苔藓","上交爬行者苔藓","法拉尼尔 苔藓"}}},fp="17,204,18.499.0,22.441.1,35.160.0,31.139.0,43.205.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="湖岸潜藏者苔藓",s="湖岸潜藏者苔藓是一种生物试剂，采集自栖息在洛丹米尔湖北岸的沼泽兽。在阿鲁高的诅咒摧毁他的神智之前，药剂师贝拉德就已经认定它是皇家药剂师协会研发新瘟疫的关键有机成分。",h="湖岸潜藏者苔藓是一种生物试剂，采集自栖息在洛丹米尔湖北岸的沼泽兽。在阿鲁高的诅咒摧毁他的神智之前，药剂师贝拉德就已经认定它是皇家药剂师协会研发新瘟疫的关键有机成分。",kw={"贝拉德","黎明岛","法拉尼尔","洛丹米尔湖","湖岸潜藏者","湖岸潜藏者苔藓","新瘟疫","伦弗利尔"},ang={["race:Undead"]="每一批采集到的苔藓都让皇家药剂师协会向完善新瘟疫更近了一步，这是被遗忘者对抗天灾军团和生者的最强武器。"},sec={{t="一种瘟疫试剂",b="这种潮湿的水生苔藓采集自黎明岛的湖岸潜藏者和年长的湖岸潜藏者身上，被被遗忘者炼金师视为珍宝。在阿鲁高的诅咒摧毁他的神智之前，药剂师贝拉德曾细致地记录了银松森林东部的动植物，并在他的日志中得出结论：湖岸潜藏者苔藓和湖岸爬行者苔藓都可以作为稳定剂或反应剂使用。贝拉德成为阿鲁高的无脑仆从后，他的日志在焚木村被找回并交给了药剂师伦弗利尔，后者指示被遗忘者的勇士去收集苔藓样本，同时收集当地邪鳍鱼人的稀有肿瘤，并直接送交幽暗城的大药剂师法拉尼尔。"}},faq={{q="湖岸潜藏者苔藓有什么用途？",a="它被幽暗城的皇家药剂师协会用作调配新瘟疫的有机基础成分，服务于Sylvanas Windrunner女王和被遗忘者的目标。",al={"苔藓用途","为什么要收集潜藏者苔藓","潜藏者苔藓有什么作用"}},{q="这种苔藓来自哪里？",a="这种苔藓是从湖岸潜藏者和年长的湖岸潜藏者身上刮下来的，这些水生野兽栖息在银松森林海岸外、洛丹米尔湖东北部的黎明岛水域周围。",al={"在哪里获得潜藏者苔藓","潜藏者苔藓位置","谁掉落湖岸潜藏者苔藓"}},{q="谁发现了这种苔藓的用途？",a="药剂师贝拉德在银松森林进行野外考察时首次发现了它的潜力。尽管阿鲁高的诅咒使贝拉德变成了无脑的仆从，但他留下的日志指引着药剂师伦弗利尔和大药剂师法拉尼尔继续他的实验。",al={"谁发现了这种苔藓","贝拉德苔藓","药剂师贝拉德的研究"}},{q="谁需要这种试剂？",a="居住在幽暗城药剂师区的皇家药剂师协会领袖大药剂师法拉尼尔，需要这种苔藓来推进他的生物战计划。",al={"谁需要潜藏者苔藓","法拉尼尔潜藏者苔藓"}}},fp="17,222,16.615.0,35.180.0,31.165.0,37.230.0,26.151.0"}
P.entries["item:large-candle"] = {n="大蜡烛",s="“大蜡烛”是艾尔文森林的矿洞中，那些狗头人珍视并随身携带的蜡烛。这些粗制的烛火安装在他们的头顶，既能在地底隧道中提供照明，也是人类药剂师获取原材料蜡的可靠来源。",h="“大蜡烛”是艾尔文森林的矿洞中，那些狗头人珍视并随身携带的蜡烛。这些粗制的烛火安装在他们的头顶，既能在地底隧道中提供照明，也是人类药剂师获取原材料蜡的可靠来源。",kw={"法戈第矿洞","闪金镇","金牙","玉石矿洞","狗头人蜡烛","大蜡烛","蜡","威廉·匹斯特"},ang={["faction:Alliance"]="通过从艾尔文森林的狗头人身上搜刮蜡烛，联盟的冒险者不仅削弱了侵扰矿洞的害虫，还为暴风城的药剂业提供了关键物资。",["profession:Mining"]="在法戈第和玉石矿洞工作的矿工经常会遭遇狗头人的侵扰，这些狗头人既贪图金矿，也贪图大蜡烛那摇曳的烛光。"},sec={{t="地底烛火与蜡",b="在艾尔文森林地底挖掘的狗头人依靠烛火在漆黑的地下通道中穿行，他们将蜡烛直接固定在自己的头上。狗头人矿工、挖掘工和地卜师会为了守护自己的蜡烛而拼死抵抗闯入者。尽管大蜡烛制造粗糙，但法戈第矿洞和玉石矿洞深处的这些蜡烛含有贵重的蜡，这种蜡地面上的商人很难批量生产，从而使这种随处可见的怪物工具变成了炼金术的商品。"},{t="贸易与药剂学",b="来自暴风城的药剂师威廉·匹斯特在闪金镇的Lion's Pride Inn收集这些超大号蜡烛。为了他家族药剂店所需的制剂、药膏和软膏，威廉·匹斯特雇佣路过的冒险者去清理那些受灾严重的矿洞，并从这些地底入侵者身上搜集蜡烛。"}},faq={{q="大蜡烛有什么用途？",a="威廉·匹斯特在闪金镇收集大蜡烛，供他和兄弟在暴风城经营的药剂店使用。他们的生意就是将收集来的蜡烛提炼，并将蜡作为各种药膏、软膏和炼金配方的原料。",al={"大蜡烛用途","为什么要收集大蜡烛","谁需要大蜡烛"}},{q="在哪里可以找到大蜡烛？",a="它们由栖息在艾尔文森林矿洞中的狗头人携带，主要分布在闪金镇南部的法戈第矿洞和东部的玉石矿洞。挖掘工、矿工和地卜师都会携带它们。",al={"大蜡烛位置","在哪获取大蜡烛","狗头人蜡烛掉落"}},{q="为什么狗头人要把蜡烛顶在头上？",a="狗头人居住在漆黑的地下隧道中，挖掘和穿行都需要光亮。他们把蜡烛固定在头上，这样就能腾出手来使用十字镐、施展地卜法术和挥舞武器。",al={"为什么狗头人有蜡烛","狗头人头顶蜡烛背景"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位来自暴风城的药剂师，他在闪金镇的Lion's Pride Inn进行业务活动。他从当地的荒野和矿洞收集原材料，以供应他和兄弟一起经营的药剂店。",al={"威廉·匹斯特背景","闪金镇的药剂师是谁"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="索兰鲁克宝珠的大碎片",s="索兰鲁克宝珠的大碎片是一件古代法器留下的巨大残片，上面束缚着恶魔的能量。这块碎片最初囚禁着一个失宠的燃烧军团恶魔的灵魂，后来落入了影牙城堡那闹鬼的墙壁内，被一群邪恶的施法者所掌握。",h="索兰鲁克宝珠的大碎片是一件古代法器留下的巨大残片，上面束缚着恶魔的能量。这块碎片最初囚禁着一个失宠的燃烧军团恶魔的灵魂，后来落入了影牙城堡那闹鬼的墙壁内，被一群邪恶的施法者所掌握。",kw={"燃烧军团","杜安·卡汉","索兰鲁克宝珠的大碎片","索兰鲁克宝珠","影牙城堡","索兰鲁克"},ang={["class:Warlock"]="回收索兰鲁克宝珠的大碎片能让你掌控其中被囚禁的恶魔灵魂，并协助杜安·卡汉重构一件专为恶魔艺术打造的强力武器。"},sec={{t="索兰鲁克的遗产",b="当燃烧军团的恶魔失宠于他们的黑暗主宰时，它们的灵魂有时会被判处终身监禁在受过附魔的宝珠之中。这些容器随后被分发给效忠于军团的法师和术士，他们可以汲取囚禁在其中的强大邪能。即使破碎成碎片，被束缚的魔鬼所残留的本质依然散发着力量，这使得每一块碎片都成为了暗影魔法野心家们眼中的珍宝。"},{t="影牙城堡的碎片",b="索兰鲁克宝珠很久以前就裂成了两半。其中一部分被进一步粉碎并分散到各处的邪教徒手中，而较大的一半则被居住在影牙城堡这座被诅咒的堡垒中的一名术士所占据。在那里，索兰鲁克宝珠的大碎片由邪恶的影牙暗魂法师携带，引导着恶魔的力量，直到被那些希望重铸这件古代容器的人寻找并夺取。"}},faq={{q="什么是索兰鲁克宝珠的大碎片？",a="它是索兰鲁克宝珠的主要部分，这是一件古代的魔法容器，里面囚禁着一个来自燃烧军团的失宠恶魔的灵魂。",al={"索兰鲁克宝珠的大碎片","索兰鲁克大碎片","这个碎片是什么"}},{q="在哪里可以找到这块碎片？",a="这块碎片由影牙暗魂法师持有，他们是居住在银松森林影牙城堡这座闹鬼要塞中的邪恶施法者。",al={"在哪里能找到大碎片","大碎片位置","谁掉落索兰鲁克宝珠的大碎片"}},{q="宝珠为什么要被打碎？",a="原来的宝珠被分成了两块主要部分。较小的一半被击碎成更小的碎片，并被带到了黑暗深渊的海岸洞穴中，而这块较大的部分则被影牙城堡的黑暗巫师所保留。",al={"宝珠是如何破碎的","为什么宝珠会破碎","索兰鲁克宝珠历史"}},{q="谁想要重新组装它？",a="杜安·卡汉是一位居住在贫瘠之地南部边界的隐士，他毕生致力于研究和重构燃烧军团那些失落的宝珠。",al={"谁需要大碎片","谁会重组宝珠"}}},fp="24,147,23.348.0,23.324.0,37.152.0,28.103.0,23.205.0,27.145.0"}
P.entries["item:laughing-sister-s-hair"] = {n="欢笑姐妹的头发",s="欢笑姐妹的头发由采自灰谷魔法森林中树妖的柔软魔法发丝组成。这种发丝深受技艺高超的织工追捧，天生具备神秘的特质，是制作精良长袍的理想材料。",h="欢笑姐妹的头发由采自灰谷魔法森林中树妖的柔软魔法发丝组成。这种发丝深受技艺高超的织工追捧，天生具备神秘的特质，是制作精良长袍的理想材料。",kw={"灰谷","布料","十字路口","迪诺","树妖","头发","基尔哈拉","欢笑姐妹","林中树居"},ang={["faction:Horde"]="获取这些发丝需要深入灰谷的暗夜精灵领地猎杀林地灵魂，这表明了部落愿意通过武力获取当地魔法资源的意图。",["profession:Tailoring"]="树妖飘逸的发丝是卡利姆多最奇异的丝线来源之一，因能将天生的自然魔法编织进布料中而备受珍视。"},sec={{t="一种稀有的纺织材料",b="这些头发采自灰谷林中树居附近的被称为欢笑姐妹的树妖，蕴含着非凡的自然魔法。虽然树妖是与塞纳留斯和暗夜精灵有关的神圣林地守护者，但部落的工匠们仅仅将她们的头发视为一种强力的制作材料。十字路口的巨魔裁缝基尔哈拉会将收集来的这些发丝纺成魔法长袍，供奥术的初学者使用。"}},faq={{q="欢笑姐妹的头发从哪里来？",a="这种头发是从欢笑姐妹身上采集的，她们是游荡在灰谷中部林中树居附近魔法树林里的树妖。",al={"如何获得欢笑姐妹的头发","欢笑姐妹的头发位置","树妖头发来源"}},{q="基尔哈拉为什么要寻找树妖的头发？",a="基尔哈拉是一位驻扎在贫瘠之地十字路口的专业裁缝。他利用这些带有魔法的发丝，代表迪诺有前途的学生们编织魔法布袍。",al={"为什么基尔哈拉需要头发","欢笑姐妹的头发用途","巨魔裁缝与树妖头发"}},{q="欢笑姐妹会心甘情愿交出她们的头发吗？",a="不会。欢笑姐妹是凶猛的自然守护者，也是灰谷的誓约保护者。正如基尔哈拉冷淡地指出的那样，树妖永远不会自愿将头发交给部落的特工。",al={"可以向树妖索要头发吗","树妖会捐赠头发吗"}}},fx={["3a458879"]={q="什么是欢笑姐妹的头发？",a="欢笑姐妹的头发是从欢笑姐妹身上剪下的发束。她们是居住在灰谷林中树居附近的林地树妖。这些发丝蕴含着塞纳留斯女儿们的自然优雅与魔力，技艺精湛的裁缝将其视为珍贵的织布材料，可用来制作强大的施法衣物。",al={"什么是欢笑姐妹的头发","欢笑姐妹的头发信息","树妖头发材料"}}},fp="22,153,24.358.0,44.122.0,39.138.0,55.149.0"}
P.entries["item:legacy-of-the-aspects"] = {n="巨龙的遗产",s="《巨龙的遗产》是一本隐藏在灰谷南部朵丹尼尔兽穴深处的古老书籍。这本书是在部落的一次智力试炼中被寻回的，其中包含了关于塑造了古代艾泽拉斯的守护巨龙的重要传说。",h="《巨龙的遗产》是一本隐藏在灰谷南部朵丹尼尔兽穴深处的古老书籍。这本书是在部落的一次智力试炼中被寻回的，其中包含了关于塑造了古代艾泽拉斯的守护巨龙的重要传说。",kw={"灰谷","兽穴","布劳格·幽魂","朵丹尼尔","巨龙的遗产","石爪小径","学识试炼"},ang={["class:Druid"]="这本书位于朵丹尼尔兽穴深处，周围徘徊着悲惨而受折磨的暗夜精灵德鲁伊的灵魂。",["faction:Horde"]="这本典籍是传统成人礼的核心，用于测试部落冒险者是否具备与其肉体力量相匹配的智慧和知识。"},sec={{t="智力试炼",b="虽然牛头人长者们设下的早期试炼是为了考验身体耐力和意志，但寻找《巨龙的遗产》则是为了挑战智力。在石爪山脉的石爪小径入口处，布劳格·幽魂会给渴望者下达任务，要求他们深入闹鬼的朵丹尼尔兽穴。那本古老的文献被放置在一个石台上，由倒下的德鲁伊的不安灵魂以及杀死他们的凶残生物所守卫。取回这本书仅仅是第一步；寻求者必须在交出书籍之前将其内容铭记于心，因为他们随后会接受关于书中历史教训的考核。"}},faq={{q="这本书在哪里？",a="这本书放在灰谷南部、碎木岗哨以南的朵丹尼尔兽穴下层密室的一个石台上。",al={"寻找巨龙的遗产","书籍位置","书在哪里"}},{q="布劳格·幽魂为什么要这本书？",a="布劳格·幽魂使用这本典籍来进行学识试炼。与体能挑战不同，这项试炼旨在考察冒险者是否具备学习和回忆重要历史知识的智力和专注力。",al={"布劳格为什么需要书","学识试炼的目的"}},{q="如果拿了书没有在和布劳格交谈前学习内容会怎样？",a="在收集到书后，布劳格会立即询问寻求者书中记载的传说。如果回答错误，就会受到魔法的迅速放逐，并将没有准备的请愿者传送回贫瘠之地的陶拉祖营地。",al={"回答错误的后果","试炼失败"}}},fx={["32a02485"]={q="什么是巨龙的遗产？",a="巨龙的遗产是一部古老而珍贵的典籍，深藏在灰谷南部的朵丹尼尔兽穴中。它由陨落德鲁伊的躁动灵魂和杀害他们的邪恶生物把守，书中记载着关于巨龙守护者的历史传说。想要取回它的人，必须经受严格的智慧与记忆考验。",al={"什么是巨龙的遗产","巨龙的遗产典籍","这本书是什么"}}},fp="21,249,18.619.0,26.148.0,40.234.0,68.231.0"}
P.entries["item:letter-to-delgren"] = {n="写给德尔格伦的信",s="《写给德尔格伦的信》是一份紧急公文，由巴苏尔·影击在Darkshore北部的奥萨拉克斯之塔附近草拟。信件是写给他的导师，圣骑士净化者德尔格伦的，详细描述了恶魔崇拜组织“Dark Strand”邪恶的行动。将这封信送往灰谷的迈斯特拉岗哨，意味着传递了至关重要的情报。",h="《写给德尔格伦的信》是一份紧急公文，由巴苏尔·影击在Darkshore北部的奥萨拉克斯之塔附近草拟。信件是写给他的导师，圣骑士净化者德尔格伦的，详细描述了恶魔崇拜组织“Dark...",kw={"灰谷","巴苏尔·影击","dark strand","darkshore","净化者德尔格伦","写给德尔格伦的信","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="这封公文凸显了一种非同寻常的友谊：一位人类圣骑士在教导一位暗夜精灵学生圣光之道，将古老的卡多雷土地与东部王国的武力信仰联系在了一起。",["faction:Alliance"]="这封信反映了联盟内部日益加强的合作，人类勇士与暗夜精灵哨兵联手对抗渗透进卡利姆多北部的恶魔邪教。"},sec={{t="送往南方的警告",b="当Dark Strand的邪教徒聚集在奥萨拉克斯之塔的废墟周围时，暗夜精灵巴苏尔·影击一直在监视着他们日益增长的恶意。由于缺乏独自铲除该邪教的武力，巴苏尔起草了这份公文，向他的圣光导师，净化者德尔格伦请求援助。由于该邪教的肮脏仪式所威胁的不只是Darkshore的海岸线，因此这封信必须被带到整个地区，进入灰谷西部，那里德尔格伦正与暗夜精灵哨兵合作，追捕恶魔和亡灵威胁。"}},faq={{q="什么是《写给德尔格伦的信》？",a="这是一封由巴苏尔·影击亲笔书写的密封信件，报告了恶魔崇拜组织Dark Strand在奥萨拉克斯之塔日益猖獗的活动。信件的收件人是圣骑士净化者德尔格伦。",al={"这封信是什么","写给德尔格伦的信","巴苏尔的信"}},{q="谁是净化者德尔格伦？",a="德尔格伦是一位驻扎在灰谷西部迈斯特拉岗哨的人类圣骑士。他致力于圣光之道，并贡献自己的武艺来协助暗夜精灵哨兵清除古老森林中的恶魔和亡灵，同时指导巴苏尔进行神圣战争。",al={"谁是德尔格伦","德尔格伦背景故事","德尔格伦在哪里"}},{q="为什么巴苏尔要把信送到那么远的地方？",a="巴苏尔是德尔格伦的学生，他特别指望自己的导师在对抗恶魔腐蚀方面的专业知识。德尔格伦既拥有战斗实力，又在迈斯特拉岗哨拥有当地哨兵部队的支持，足以组织起对Dark Strand黑暗仪式的回击。",al={"为什么要送到灰谷","为什么不告诉奥伯丁"}},{q="这封信需要送到哪里？",a="这封信必须一路南下，穿过整个Darkshore，跨过边界进入灰谷，沿着西侧道路送达迈斯特拉岗哨。",al={"我要把信送到哪里","信件投递地点"}}},fp="17,213,20.424.0,30.182.0,28.222.0,47.214.0,44.120.0"}
P.entries["item:letter-to-ello"] = {n="写给艾尔罗的信",s="“写给艾尔罗的信”是一封由亚伯克隆比所写的密封信件，这位古怪的隐士住在暮色森林乌鸦岭墓地北边的一间小屋里。这封信是寄给夜色镇的镇长艾尔罗·埃伯洛克的，隐士声称他们是旧友，但信中的内容是用一种古老的文字写成的。",h="“写给艾尔罗的信”是一封由亚伯克隆比所写的密封信件，这位古怪的隐士住在暮色森林乌鸦岭墓地北边的一间小屋里。这封信是寄给夜色镇的镇长艾尔罗·埃伯洛克的，隐士声称他们是旧友，但信中的内容是用一种古老的文字写成的。",kw={"亚伯克隆比","夜色镇","暮色森林","艾尔罗·埃伯洛克","写给艾尔罗的信","致镇长的信","希拉·沃宁迪"},ang={["faction:Alliance"]="在暮色森林的旅行者看来，在古怪的隐士和当地镇长之间传递信件是标准职责，尽管夜色镇的官员们对这些奇怪的信件总是保持警惕。"},sec={{t="离奇的问候",b="当冒险者协助隐士亚伯克隆比在暮色森林完成了一些任务后，这位老隐士便将这封信托付给他们，声称镇长艾尔罗·埃伯洛克是一位老朋友，会为所取得的成就感到高兴。实际上，夜色镇的镇长根本不记得有什么叫亚伯克隆比的人。在拆开封印后，埃伯洛克镇长发现他根本无法辨认这古老文字中的任何一个词句，于是他决定将信送到夜色镇的学者希拉·沃宁迪那里进行翻译。"},{t="黑暗的预兆",b="这个看似无辜的差事掩盖了隐士真正可怕的意图。亚伯克隆比所书写的远古符文绝非旧识之间的友好交流，而是注定了整个夜色镇的毁灭。"}},faq={{q="是谁写了“写给艾尔罗的信”？",a="这封信是由亚伯克隆比写的，他是一位住在暮色森林西部乌鸦岭墓地附近破旧小屋里的隐士。",al={"谁写了这封信","写给艾尔罗的信作者","谁寄出了这封信"}},{q="艾尔罗·埃伯洛克镇长能读懂这封信吗？",a="不能。当这封信送到夜色镇的埃伯洛克镇长手中时，他发现上面的文字完全无法辨认，并指出这似乎是一种古老且无法识别的语言。",al={"艾尔罗能读懂吗","为什么艾尔罗读不懂这封信","艾尔罗信件语言"}},{q="谁能翻译这封信？",a="埃伯洛克镇长指示信使将这封信带给希拉·沃宁迪，她是夜色镇的一位常驻学者，精通各种古老文字和深奥的语言。",al={"谁翻译了这封信","翻译亚伯克隆比的信","谁能读懂这封信"}},{q="埃伯洛克镇长真的认识亚伯克隆比吗？",a="尽管亚伯克隆比声称他和镇长是旧友，但艾尔罗·埃伯洛克坚称他从未听说过任何叫亚伯克隆比的人。",al={"艾尔罗认识亚伯克隆比吗","艾尔罗和亚伯克隆比是朋友吗","亚伯克隆比艾尔罗旧友"}}},fx={["74d18927"]={q="写给艾尔罗的信是什么？",a="写给艾尔罗的信是一封神秘信件，由隐士亚伯克隆比用一种古老而难以辨认的语言写成。信直接寄给夜色镇镇长艾尔罗·埃伯洛克，隐士声称，这封信会让他的“老朋友”知道你在墓地里所做的事。",al={"写给艾尔罗的信","写给艾尔罗的信是什么","亚伯克隆比的便条"}},ee8215fa={q="艾伯洛克镇长为什么想要写给艾尔罗的信？",a="艾伯洛克镇长想要这封信，只是因为你带来了消息，说一位名叫亚伯克隆比的老朋友寄信给他。然而收到信后，镇长发现自己看不懂上面的古老文字，于是急切地想找人翻译，以弄清隐士的真实意图。",al={"艾尔罗为什么想要这封信","为什么想要写给艾尔罗的信","为什么要把信送给艾尔罗"}}},fp="14,205,18.399.0,10.165.1,29.117.0,41.155.0,27.151.0,47.119.1"}
P.entries["item:letter-to-jin-zil"] = {n="写给金吉尔的信",s="《写给金吉尔的信》是由位于十字路口的兽人达索克·快刀所写的一封信。在击败Serena Bloodfeather之后，这封信被交给了一位冒险者，信中向位于石爪山脉的暗矛巫医金吉尔传达了北部贫瘠之地已经肃清Bloodfeather威胁的消息。",h="《写给金吉尔的信》是由位于十字路口的兽人达索克·快刀所写的一封信。在击败Serena...",kw={"达索克·快刀","鹰身人","金吉尔","写给金吉尔的信","玛拉卡金","rokhan","serena bloodfeather","石爪山脉"},ang={["faction:Horde"]="这封信是部落冒险者从守卫贫瘠之地转向处理石爪山脉深处酝酿的冲突的一座桥梁。",["race:Troll"]="递送这封信会将暗矛的旅行者直接引向巫医金吉尔，他是一位在回音群岛之外传承传统巫术的资深修行者。"},sec={{t="前往石爪山脉的信使",b="在根除了无水岭的鹰身人瘟疫并击杀Serena Bloodfeather后，达索克·快刀起草了这封给老战友的信件。达索克意识到贫瘠之地的鹰身人原本栖息在石爪山脉的巅峰，他利用这封信将一位有前途的勇士介绍给更广阔的边境，同时通知巫医金吉尔这位鹰身人女族长已经伏诛。"},{t="玛拉卡金的旧日回忆",b="在将信送达玛拉卡金的洞穴后，金吉尔怀着怀旧的满足感欢迎了这一消息。Serena的死让这位老巫医回想起了第三次战争后杜隆塔尔的建立，当时他的朋友Rokhan与半食人魔兽王雷克萨联手击杀了Serena的姐姐Bloodfeather。如今Serena也已伏诛，金吉尔认为Bloodfeather一族的复仇已彻底终结。"}},faq={{q="谁写了《写给金吉尔的信》？",a="这封信由驻扎在贫瘠之地十字路口的兽人达索克·快刀所写，他负责协调针对劫掠鹰身人聚落的防御工作。",al={"谁写的","发信人","达索克信件"}},{q="金吉尔在哪里？",a="巫医金吉尔居住在玛拉卡金的一个洞穴里，这是一个坐落在石爪山脉东南岩架上的暗矛巨魔前哨站。",al={"金吉尔在哪里","金吉尔位置","寻找金吉尔"}},{q="信里包含什么消息？",a="消息告知金吉尔，进入北部贫瘠之地的鹰身人首领Serena Bloodfeather已经被杀，从而确保了十字路口北部的周边安全。",al={"信里写了什么","信件内容"}},{q="金吉尔为什么关心Bloodfeather？",a="金吉尔记得第三次战争后杜隆塔尔的建立，当时他的同伴Rokhan和半食人魔战士雷克萨杀死了Serena的姐姐。从那时起，Serena就一直寻求向部落复仇，她的倒下是一个令人欣慰的结局。",al={"为什么金吉尔关心鹰身人","bloodfeather历史","rokhan与bloodfeather"}}},fx={f9426e82={q="金吉尔为什么要你把写给金吉尔的信送给他？",a="这封信带来了他久未谋面的老友达索克·快刀从贫瘠之地寄来的消息。金吉尔多年没有达索克的音讯，而信中确认了塞蕾娜·血羽的死讯，终结了长期侵扰贫瘠之地和石爪山的鹰身人族母的威胁。",al={"为什么要把信送给金吉尔","谁想要写给金吉尔的信","金吉尔为什么在意这封信"}}},fp="17,239,25.335.0,26.353.1,32.137.0,25.116.0,41.183.0,46.248.1"}
P.entries["item:letter-to-jorgen"] = {n="写给乔贞的信",s="“写给乔贞的信”是一份旨在招募暴风城一位旧识的机密信件。在针对一起高层外交失踪案的初步调查阶段，这封信是特工用来引荐身份的凭证。",h="“写给乔贞的信”是一份旨在招募暴风城一位旧识的机密信件。在针对一起高层外交失踪案的初步调查阶段，这封信是特工用来引荐身份的凭证。",kw={"jaina proudmoore","乔贞","写给乔贞的信","失踪外交官","暴风城","塞拉摩","英雄谷"},ang={["class:Rogue"]="通过秘密的信件和不情愿的底层线人行事，而非动用城市卫队，是揭露首都阴谋诡计的惯用且必要的方法。",["faction:Alliance"]="这封信触及了联盟脆弱的稳定局势，试图私下处理一起威胁到暴风城与塞拉摩之间外交关系的事件。"},sec={{t="冷漠的传唤",b="当一名原定前往塞拉摩与吉安娜·普罗德摩尔举行会谈的高级外交官未能如期抵达时，皇室调查人员为了封锁消息而忙得不可开交。尽管官方特工开始在首都进行搜查，但秘密渠道也已悄然启动。这封密封的信件旨在绕过常规的军事官僚程序，专门寄给乔贞——一位在英雄谷巨型雕像下消磨时光的粗犷老兵。信件援引了往日的义务，将一个不情愿的联络人卷入了一场涉及迪菲亚潜行者阴谋的秘密调查中。"}},faq={{q="这封信的目的是什么？",a="这封信起到引荐和要求履行旧日义务的作用。它指引携带者前往英雄谷，寻找特工乔贞，以便在不惊动公众的情况下，引入独立视角来调查外交官失踪一案。",al={"写给乔贞的信有什么用","为什么要有写给乔贞的信","信件目的"}},{q="乔贞是谁？",a="乔贞是一位住在暴风城大门内的隐居联络人，平时总是在英雄谷的水边钓鱼。虽然他很讨厌被打扰，但只要出示这封信，受困于往日的人情债，他必须提供协助。",al={"乔贞是谁","乔贞npc","乔贞暴风城"}},{q="这封信涉及哪起失踪案？",a="一名重要外交官在离开暴风城前往塞拉摩会见吉安娜·普罗德摩尔的途中失踪了。怀疑指向了迪菲亚潜行者，尽管该阴谋的全貌仍被严密封锁。",al={"哪位外交官失踪了","谁失踪了","失踪的外交官"}},{q="这封信要送到哪里？",a="这封信被送往英雄谷，那是暴风城宏伟的入口，两旁矗立着第二次战争英雄的纪念碑。乔贞就在正门附近的水边。",al={"我该把信交给谁","乔贞位置","乔贞在哪里"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="刘易斯的便笺",s="《刘易斯的便笺》是哨兵岭的军需官刘易斯写下的一份紧急物资征用函。它由信使通过狮鹫飞行携带，请求从暴风城Old Town的一位私人军械商那里运送关键的防护装备。",h="《刘易斯的便笺》是哨兵岭的军需官刘易斯写下的一份紧急物资征用函。它由信使通过狮鹫飞行携带，请求从暴风城Old Town的一位私人军械商那里运送关键的防护装备。",kw={"狮鹫","刘易斯的便笺","有限免疫","old town","奥斯瑞克·斯图恩","军需官刘易斯","哨兵岭","索尔"},ang={["race:Human"]="运送这份征用函教会了年轻的人类冒险者如何使用王国的狮鹫网络，同时也揭示了暴风城的统治者在装备西部荒野防卫者方面所做甚少的残酷现实。"},sec={{t="对钢铁的恳求",b="哨兵岭的人民民兵组织预算捉襟见肘，几乎没有得到暴风城贵族议会的正式支持。面对与迪菲亚潜行者的持续小规模冲突，守备队经常耗尽其本就匮乏的装备库存。为了让防卫者有装备可用，军需官刘易斯不得不依靠私人商业安排，而非王国的后勤补给。这份征用便笺完全绕过了官方军事渠道，委托一名联盟信使乘坐狮鹫飞往Old Town，并将订单直接交给“有限免疫”商店的老板奥斯瑞克·斯图恩。"}},faq={{q="什么是《刘易斯的便笺》？",a="这是一份来自哨兵岭军需官刘易斯的书面订单，要求暴风城的军械商奥斯瑞克·斯图恩为困境中的西部荒野守备队运送更多的防护装备。",al={"这是什么物品","刘易斯的便笺用途","便笺的作用是什么"}},{q="谁写了这张便笺？",a="它由军需官刘易斯撰写，他是负责管理驻扎在哨兵岭的人民民兵的补给、给养和军备的军官。",al={"谁是刘易斯","军需官刘易斯"}},{q="谁收到了这张便笺？",a="这张便笺首先被送到哨兵岭的狮鹫管理员索尔那里，然后被直接送到位于暴风城Old Town区的“有限免疫”盔甲店，交到奥斯瑞克·斯图恩手中。",al={"便笺送到哪里","谁收到了刘易斯的便笺","奥斯瑞克·斯图恩便笺"}},{q="为什么守备队不直接从王国获得盔甲？",a="王国的政府在很大程度上忽视了西部荒野，让当地的防卫者在没有直接军事拨款或王国供应盔甲的情况下自谋生路。刘易斯必须依靠奥斯瑞克·斯图恩这样的私人贸易联系人来维持民兵的装备需求。",al={"为什么向奥斯瑞克购买","为什么暴风城不提供帮助","暴风城援助西部荒野"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="军官的徽章",s="军官的徽章是隐藏在杜隆塔尔内的火刃氏族邪教高阶成员所佩戴的徽章。它由部落冒险者回收，是邪教在奥格瑞玛附近危险活动的有力证据。",h="军官的徽章是隐藏在杜隆塔尔内的火刃氏族邪教高阶成员所佩戴的徽章。它由部落冒险者回收，是邪教在奥格瑞玛附近危险活动的有力证据。",kw={"火刃氏族","cleft of shadow","杜隆塔尔","隐藏的敌人","军官的徽章","neeru fireblade","暗影议会","骷髅石","萨尔"},ang={["class:Warlock"]="这枚徽章展示了火刃氏族是如何滥用邪能魔法来为燃烧军团服务的，这直接让萨尔对合法部落术士的宽容态度变得更加棘手。",["faction:Horde"]="对于年轻的部落来说，这枚徽章代表了试图从内部颠覆萨尔新国家的恶魔腐化的隐患。"},sec={{t="邪教的标志",b="军官的徽章是从杜隆塔尔东岸骷髅石内盘踞的邪教徒手中回收的，它能标明佩戴者是火刃氏族的军官。虽然萨尔大酋长绝不容忍他的新国家内出现叛徒，但彻底的清洗只会让邪教在他们的主子被揭露之前就四散逃跑。相反，萨尔将这枚徽章变成了一件伪造的证件，交回给一位值得信赖的勇士，以此来测试潜伏在奥格瑞玛地下的可疑渗透者是否忠诚。"},{t="Cleft of Shadow",b="萨尔指示他的特工带着信物进入Cleft of Shadow，并将其展示给术士Neeru Fireblade。Neeru以为自己是在迎接一名新晋升的下属，完全上当了。这名术士被傲慢冲昏了头脑，公开吹嘘火刃氏族是暗影议会和燃烧军团的直接工具，无意中给了萨尔揭露埋藏在城市地下的腐败所需要的突破口。"}},faq={{q="军官的徽章从哪里来？",a="它从杜隆塔尔奥格瑞玛东海岸的一个洞穴——骷髅石内活动的火刃氏族狂热者和学徒身上回收。",al={"如何获得军官的徽章","谁会掉落军官的徽章","军官的徽章来源"}},{q="军官的徽章有什么用？",a="萨尔大酋长利用这枚徽章为他的特工建立伪装。带着它，一名年轻的冒险者可以冒充火刃氏族的军官，去到萨尔的特工无法涉足的地方，以查明到底是谁在领导这个邪教。",al={"为什么需要军官的徽章","军官的徽章任务用途","徽章有什么用"}},{q="Neeru Fireblade是谁？",a="Neeru Fireblade是一位居住在奥格瑞玛Cleft of Shadow的兽人术士。他声称通过证明术士可以帮助部落来效忠萨尔，实际上却是火刃氏族在当地的领导者。",al={"谁是neeru","neeru fireblade背景故事"}},{q="为什么萨尔不立即杀了Neeru Fireblade？",a="萨尔知道Neeru是个叛徒，但过早地动手只会惊动邪教的真正主子并导致他们的网络四散。萨尔更愿意操纵Neeru作为不知情的线人，以揭露暗影议会在杜隆塔尔更广泛的活动。",al={"为什么萨尔不杀neeru","为什么要留着neeru","为什么要渗透neeru"}}},fx={["2e1cfb76"]={q="军官的徽章是什么？",a="这是火刃氏族成员携带的一种徽记，表明持有者是氏族认可的高阶军官。在杜隆塔尔各处秘密活动的恶魔邪教徒会以此信物表明自己对暗影议会网络的忠诚、地位与权威。",al={"军官的徽章是什么","军官徽章是什么东西","火刃氏族徽章"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="闪电腺",s="闪电腺是从徘徊在贫瘠之地平原上的风暴兽身上获取的。它们浸润着天然的元素电荷，酿酒师德罗恩在棘齿城寻找它们，以便酿造一种他从游历的熊猫人陈·风暴烈酒那里学到的烈性穴居人啤酒。",h="闪电腺是从徘徊在贫瘠之地平原上的风暴兽身上获取的。它们浸润着天然的元素电荷，酿酒师德罗恩在棘齿城寻找它们，以便酿造一种他从游历的熊猫人陈·风暴烈酒那里学到的烈性穴居人啤酒。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","闪电腺","棘齿城","风暴兽","穴居人啤酒"},ang={["profession:Cooking"]="虽然不是标准的烹饪配料，但闪电腺展示了陈·风暴烈酒和酿酒师德罗恩的前沿酿酒理念，即将生猛的野兽器官直接注入烈酒之中。"},sec={{t="令人震惊的配料",b="贫瘠之地的草原上栖息着各种受到元素影响的掠食者，其中包括风暴兽。在它们的血肉中隐藏着闪电腺，这是一个搏动着潜在电能的器官。虽然这些不稳定的腺体并不适合普通食物，但却受到那些欣赏带有真正刺痛感的佳酿的古怪酿酒师们的青睐。"},{t="德罗恩的穴居人啤酒",b="在棘齿城港口小镇，酿酒师德罗恩继续着陈·风暴烈酒传授给他的酿酒传统。为了调制一种被称为穴居人啤酒的烈性酒，德罗恩需要五个闪电腺，外加一个雷鹰的唾液腺和一个新鲜的科多兽的肝脏。酿出的酒带有令人无法忽视的冲击力，冒险者们发现它既能振奋精神又劲头十足。"}},faq={{q="什么生物带有闪电腺？",a="闪电腺是从徘徊在贫瘠之地广阔草原上的风暴兽身上收集的。",al={"在哪里获取闪电腺","谁掉落闪电腺","风暴兽 闪电腺"}},{q="谁需要闪电腺，为什么？",a="棘齿城的酿酒师德罗恩收集它们是为了酿造一批穴居人啤酒，这是一个由游历的酿酒大师陈·风暴烈酒传授给他的配方。",al={"谁需要闪电腺","闪电腺交还任务","闪电腺用途"}},{q="除了闪电腺，还需要什么？",a="德罗恩的配方需要五个闪电腺、一个来自大型雷鹰的雷鹰的唾液腺，以及一个从贫瘠之地的野兽身上取下的新鲜科多兽的肝脏。",al={"德罗恩 穴居人啤酒 配料","陈的酒桶 3件物品"}}},fp="15,181,21.259.0,17.283.0,38.63.0,35.133.0,50.143.0"}
P.entries["item:logging-rope"] = {n="伐木绳",s="伐木绳是战歌氏族在灰谷进行伐木作业时必不可少的重型绳索。这些坚固的绳索在运输途中遭到了当地熊怪部落的伏击和抢夺，他们暴力反抗部落在古老森林中的扩张。",h="伐木绳是战歌氏族在灰谷进行伐木作业时必不可少的重型绳索。这些坚固的绳索在运输途中遭到了当地熊怪部落的伏击和抢夺，他们暴力反抗部落在古老森林中的扩张。",kw={"灰谷","刺毛熊怪","洛克·奥卡尔","伐木绳","碎木岗哨","蓟皮熊怪","战歌伐木营地","战歌补给品"},ang={["faction:Horde"]="找回伐木绳对于让战歌氏族的战争机器在不断的伏击中仍有木材供应至关重要。",["race:Orc"]="兽人在卡利姆多的定居点完全依赖灰谷的木材，因此每一箱被劫走的伐木工具都是一种必须予以报复的侮辱。"},sec={{t="被窃的绳索",b="维护战歌伐木营地的地精制造的机械和锯木厂，需要大量的耐用伐木绳。这些关键物资未能送达营地的伐木工手中，而是被刺毛熊怪和蓟皮熊怪部落拦截了。这些熊怪因腐化而陷入疯狂，拼命捍卫着他们祖祖辈辈居住的森林，并将抢来的绳索囤积在灰谷北部和中部的营地里。"},{t="支援战争物资",b="碎木岗哨的洛克·奥卡尔负责找回这些丢失的后勤物资，以免战歌伐木营地的工作陷入停滞。直接从熊怪巢母和战士手中夺回重型绳索，能让部落确保有足够的木材来砍伐、捆绑圆木，并固定锯木机械，从而应对森林原住民不断的游击抵抗。"}},faq={{q="伐木绳有什么用？",a="这是战歌伐木营地所需的粗壮工业级绳索，用于捆绑收获的木材、在崎岖的地形上拖运圆木，以及加固灰谷内的重型机械。",al={"伐木绳用途","战歌氏族为何需要绳索","战歌伐木绳"}},{q="是谁偷走了伐木绳？",a="运输队遭到了当地刺毛熊怪和蓟皮熊怪的袭击，他们将抢走的绳索带回了遍布灰谷的村落巢穴和营地中。",al={"谁拿走了绳索","绳索窃贼","哪些熊怪有绳索"}},{q="谁需要找回这些绳索？",a="驻扎在碎木岗哨的洛克·奥卡尔请求找回这些绳索以及其他丢失的物资，以确保战歌伐木营地的作业不会中断。",al={"谁需要伐木绳","伐木绳任务发布者"}},{q="为什么熊怪要偷窃伐木物资？",a="熊怪强烈反对部落在灰谷进行皆伐作业。拦截运输队不仅能干扰锯木厂的运作，还能以此报复对他们领地的入侵。",al={"熊怪动机","为什么熊怪袭击运输队"}}},fx={["26f07746"]={q="伐木绳是什么？",a="伐木绳是战歌氏族在灰谷开展大规模伐木作业时不可或缺的重型绳索。它用于固定、拖运和捆绑砍伐下来的巨木，是伐木营地日常采伐作业的重要物资。",al={"伐木绳是什么","伐木绳信息","战歌氏族伐木绳"}}},fp="12,186,12.338.0,24.242.0,30.118.0,27.128.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="洛克·奥克班恩的颅骨",s="洛克·奥克班恩的颅骨是洛克·奥克班恩的断头，他是一位凶猛的Razormane战士，曾领导残酷的野猪人突袭，劫掠南贫瘠之地的部落补给线。被囚禁的野猪人碎牙为了复仇而寻求这颗头颅，它是突袭者首领已被击败的无可辩驳的证据。",h="洛克·奥克班恩的颅骨是洛克·奥克班恩的断头，他是一位凶猛的Razormane战士，曾领导残酷的野猪人突袭，劫掠南贫瘠之地的部落补给线。被囚禁的野猪人碎牙为了复仇而寻求这颗头颅，它是突袭者首领已被击败的无可辩驳的证据。",kw={"内部的背叛","陶拉祖营地","十字路口","洛克·奥克班恩","洛克·奥克班恩的颅骨","碎牙","razormane","索克"},ang={["faction:Horde"]="取走洛克·奥克班恩的颅骨能够瓦解南部野猪人的领导层，正是这群家伙不断骚扰着陶拉祖营地与十字路口之间的补给商队。",["race:Orc"]="展示这颗名为“奥克班恩”的野猪人酋长的头颅，能为保卫贫瘠之地的兽人们带来深层的个人满足感和安全感。"},sec={{t="首领的陨落",b="洛克·奥克班恩从剃刀沼泽走出，进入南贫瘠之地，与他的副官Nak和Kuz一道，带头对部落补给线发起了激进的Razormane野猪人袭击。在背叛并抛弃了碎牙，使其被囚禁在陶拉祖营地后，洛克在兽人守军中恶名昭彰，他们一直难以遏制他那残酷的突袭。夺取洛克的颅骨不仅能为指引部落勇士前往洛克营地的受困者复仇，还能粉碎推动Razormane攻势的核心领导层。"},{t="十字路口的证据",b="虽然碎牙要求所有三名同谋者的颅骨以满足他的复仇心，但他交还了洛克的颅骨，以便将其带往北方的十字路口交给索克。索克和部落指挥部曾怀疑有另一名野猪人在策划这些袭击，因此这一令人毛骨悚然的战利品让他们深感意外，并成为了对贫瘠之地中部贸易路线的威胁已被彻底切断的决定性证据。"}},faq={{q="洛克·奥克班恩是谁？",a="洛克·奥克班恩是一位强大的Razormane战士，他从剃刀沼泽走出，指挥野猪人突袭队在南贫瘠之地横行。他以仇恨兽人和狡诈的战术而闻名，并与他信任的盟友Nak和Kuz一起组织了对部落商队和哨所的激进袭击。",al={"洛克是谁","洛克·奥克班恩背景故事","洛克·奥克班恩是谁"}},{q="碎牙为什么想要洛克·奥克班恩的颅骨？",a="洛克·奥克班恩和他的同伙背叛了碎牙，抛弃了他，让他被陶拉祖营地的牛头人俘虏并关押。明知自己难逃一死，碎牙便指引部落冒险者去处决他昔日的战友，以此向背弃他的族人复仇。",al={"碎牙为何想要颅骨","碎牙的复仇","为什么要杀洛克"}},{q="为什么要将这颗颅骨带给十字路口的索克？",a="索克负责监督十字路口的防御，并致力于保护重要的部落补给线免受野猪人的入侵。将洛克的颅骨交给这位兽人指挥官，证明了南部袭击背后的真正主谋已被击杀，从而为该地区的旅行者带来了安宁。",al={"为什么要将颅骨带给索克","索克 洛克的颅骨","谁会得到洛克的颅骨"}},{q="Nak和Kuz是谁？",a="Nak和Kuz是洛克·奥克班恩在南贫瘠之地的突袭同僚。碎牙称其中一人是施法者，另一人是追踪者，他们用这些能力支持洛克的战士实力，共同策划对部落的突袭。",al={"nak和kuz","洛克·奥克班恩的副官","kuz和nak"}}},fp="11,183,18.470.0,24.322.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="亨里格·独眉的日记",s="亨里格·独眉的日记是一本饱经风霜的日记，在升降梯底部的矮人探险家亨里格·独眉的骸骨中被发现。日记详细记录了独眉穿过贫瘠之地的最后一段凄惨旅程，并指出了潜伏在剃刀沼泽内的危险。",h="亨里格·独眉的日记是一本饱经风霜的日记，在升降梯底部的矮人探险家亨里格·独眉的骸骨中被发现。日记详细记录了独眉穿过贫瘠之地的最后一段凄惨旅程，并指出了潜伏在剃刀沼泽内的危险。",kw={"沼泽巫婆","法芬德尔","升降梯","亨里格·独眉","剃刀沼泽","萨兰纳尔","千针石林"},ang={["faction:Alliance"]="亨里格·独眉的最后笔记在联盟侦察兵和守护菲拉斯边境的德鲁伊之间建立了一个关键的联系，以召集援助对抗野猪人的威胁。",["race:Dwarf"]="在如此偏远、充满敌意的土地上发现倒下的同胞，让人不禁沉重地想起矮人探险家在卡兹莫丹之外进行侦察时所面临的危险。"},sec={{t="升降梯的临终遗愿",b="亨里格·独眉在连接贫瘠之地和千针石林的升降梯底部附近遭遇了不幸。他的遗骸被遗弃在一处岩石平台上，手中仍紧紧抓着这本饱经风霜的日记。这本日记见证了他最后的旅程，并指示发现它的人将消息带给位于萨兰纳尔的暗夜精灵德鲁伊法芬德尔，那里是通往菲拉斯的边境哨所。独眉的笔记揭示了南贫瘠之地正在酝酿的野猪人威胁的关键信息。"},{t="与剃刀沼泽的联系",b="当交给法芬德尔时，独眉的记录证实了联盟对剃刀沼泽野猪人的日益担忧。日记的内容直接引出了一项号召英雄们深入棘刺巢穴中心，击败作为野猪人威胁幕后主使的沼泽巫婆卡尔加·刺肋的任务。"}},faq={{q="亨里格·独眉是谁？",a="亨里格·独眉是一位矮人旅行者，死于千针石林的升降梯脚下。他死时紧握着他的日记，意图将其内容传达给驻扎在萨兰纳尔的暗夜精灵。",al={"亨里格·独眉","谁是独眉","升降梯处的死去的矮人"}},{q="在哪里可以找到这本日记？",a="这本日记位于千针石林北部，升降梯底部坡道旁的一处低矮岩石平台上，就在亨里格·独眉的骸骨旁边。",al={"独眉的日记在哪里","寻找独眉的日记","升降梯处的骸骨"}},{q="谁应该接收亨里格·独眉的日记？",a="这本日记应该被带到千针石林西侧，交给驻扎在菲拉斯边境萨兰纳尔的暗夜精灵德鲁伊法芬德尔。",al={"我应该把日记交给谁","法芬德尔","日记在哪里上交"}},{q="这本日记会导致什么结果？",a="阅读日记并向法芬德尔汇报，可以获得关于野猪人的情报，从而引出一个进入剃刀沼泽击败巫婆卡尔加·刺肋的任务。",al={"沼泽巫婆任务","独眉的日记后续"}}},fx={a9190e03={q="亨里格·独眉的日记是什么？",a="亨里格·独眉的日记是一册饱经风霜的私人日志，发现时正握在矮人亨里格·独眉的骷髅手中。它在千针石林升降梯脚下被发现，记录了他在峡谷中丧命前的旅途与遗愿。",al={"亨里格·独眉的日记是什么","这本书是什么","亨里格·独眉的日记"}},["090ee1d4"]={q="亨里格·独眉的日记来自哪里？是谁写的？",a="这本日记由矮人旅行者亨里格·独眉写成，他曾穿行于千针石林危机四伏的峡谷之中。他一直随身携带日记，直到在升降梯附近丧命；后来，人们在那里发现了他的遗骸和这本日记。",al={"谁写了亨里格·独眉的日记","亨里格·独眉日记的作者","这本日记来自哪里"}},ea8f453f={q="为什么有人想要亨里格·独眉的日记？",a="送交日记是为了完成这位已故矮人的遗愿。驻扎在菲拉斯边境萨兰纳尔的暗夜精灵德鲁伊法芬德尔，想要阅读日记内容，了解亨里格的遭遇，并查明剃刀沼泽中正在酝酿的危险。",al={"为什么要送交亨里格·独眉的日记","谁需要亨里格·独眉的日记","为什么想要亨里格·独眉的日记"}}},fp="18,277,30.495.0,20.327.1,24.221.0,27.151.0,38.150.0,30.175.1"}
P.entries["item:lorgalis-manuscript"] = {n="洛迦里斯手稿",s="《洛迦里斯手稿》是一部与古神崇拜和传说相关的古老文本，从灰谷地下的暗夜精灵废墟中保存至今。它隐藏在黑暗深渊那沉没的神庙建筑群中，蕴藏着那些试图唤醒沉睡远古力量的黑暗学者所觊觎的秘密。",h="《洛迦里斯手稿》是一部与古神崇拜和传说相关的古老文本，从灰谷地下的暗夜精灵废墟中保存至今。它隐藏在黑暗深渊那沉没的神庙建筑群中，蕴藏着那些试图唤醒沉睡远古力量的黑暗学者所觊觎的秘密。",kw={"黑暗深渊","forlorn cavern","葛利·硬骨","铁炉堡","洛迦里斯","手稿","古神","沉睡者"},ang={["class:Warlock"]="这份手稿是通往古神和深渊存在之禁忌传说的一扇罕见窗口，为那些在黑暗艺术中往来的人们提供了梦寐以求的见解。",["race:NightElf"]="这部文本位于暗夜精灵曾经居住的沉没废墟中，它对阿库麦尔和古神的崇拜，揭示了在那些没落的大厅中已经扎根的黑暗信仰。"},sec={{t="沉睡者之书",b="《洛迦里斯手稿》静静地躺在黑暗深渊的底部，那是这座古老城市覆灭前，早已亡故的精灵们曾经居住的沉没废墟。这部手稿由洛迦里斯所著，讲述了当世界伊始时，曾在艾泽拉斯肆虐，如今却被枷锁囚禁并陷入沉睡的古神。它赞颂着居住在深渊中的古神仆从——阿库麦尔。据传，其中记载的知识能够开启神秘的门户，并惊动那些沉睡在世界深处远古存在。它被存放在淹没走廊中一个坑坑洼洼的铁箱里，吸引了邪教徒和暗影学者的注意。"},{t="暗影之眼",b="在铁炉堡的Forlorn Cavern中，一位名叫葛利·硬骨的古怪收藏家积极雇佣勇敢的冒险者横跨海洋去寻回这部文本。葛利·硬骨虔诚地谈论着“末日”以及沉睡神灵的觉醒。一旦找回，他打算将文本誊抄并与他那阴暗的兄弟姐妹圈子分享，传播那些地表居民本不该理解的禁忌洞见。"}},faq={{q="什么是《洛迦里斯手稿》？",a="这是一部由洛迦里斯所写的古老文本，包含了有关古神的黑暗而深奥的知识。据传其内容掌握着开启门户和唤醒沉睡太古存在的必要秘密。",al={"什么是洛迦里斯手稿","洛迦里斯之书传说","手稿的作用"}},{q="这份手稿在哪里？",a="该手稿存放于黑暗深渊深处一个被淹没的坑洼铁箱中。黑暗深渊是一座位于灰谷佐拉姆海岸的暗夜精灵废墟神庙。",al={"哪里寻找洛迦里斯手稿","手稿位置","黑暗深渊宝箱"}},{q="谁想要这份手稿？",a="铁炉堡Forlorn Cavern的神秘知识守护者葛利·硬骨，他委托冒险者去寻回此物。他计划将其中记载的古老教义誊抄并分发给与他志同道合的隐秘同僚们。",al={"谁想要洛迦里斯手稿","葛利·硬骨任务","谁是硬骨"}},{q="为什么葛利·硬骨谈论末日？",a="葛利·硬骨与那些研究并崇拜古神的人们同流合污。他对古老精灵文字的兴趣聚焦于那些能够唤醒“沉睡者”的知识，他将此视为预示着即将来临的末日。",al={"葛利·硬骨末日","硬骨邪教徒","硬骨古神"}}},fx={["61ae2bf7"]={q="洛迦里斯手稿来自哪里？是谁写的？",a="这份手稿由一位名叫洛迦里斯的人写成，藏在黑暗深渊底部的沉没废墟中。那座城市陷落之前，早已逝去的精灵曾在那里居住。关于洛迦里斯的身份，并无记载。手稿记述了上古之神和沉睡者的禁忌秘闻，并赞颂了居住在深渊中的上古之神仆从阿库麦尔。它被锁在洪水淹没的大厅里一只布满凹坑的铁箱中。",al={"洛迦里斯手稿的来源","谁写了洛迦里斯手稿","洛迦里斯手稿写于何处"}}},fp="19,194,25.546.0,19.401.1,32.172.0,32.139.0,25.166.0,49.155.0"}
P.entries["item:lunar-fungus"] = {n="月亮菇",s="月亮菇是一种强效的药用植物，采摘自黑海岸洞穴深处的真菌丛。德鲁伊学徒会将这些蘑菇与常见的草药混合，调制出一种可以治疗患病野生动物的疗伤药膏。",h="月亮菇是一种强效的药用植物，采摘自黑海岸洞穴深处的真菌丛。德鲁伊学徒会将这些蘑菇与常见的草药混合，调制出一种可以治疗患病野生动物的疗伤药膏。",kw={"奥兰达利亚·夜歌","奥伯丁","治疗毒素","黑海岸","地根草","月亮菇丛","月亮菇"},ang={["class:Druid"]="年轻的德鲁伊在黑海岸的洞穴中寻找月亮菇，作为他们掌握治疗魔法和治愈中毒野生动物的基础仪式的一部分。",["race:NightElf"]="用月亮菇等本土疗法护理奥伯丁周围被腐蚀的林地生物，是黑海岸守护者们的长期职责。"},sec={{t="特性与生态",b="这种独特的真菌采自月亮菇丛，生长在黑海岸各处阴暗的地下洞穴中。塞纳里奥议会非常看重它的增效作用；当它与舒缓的水基底和常见的地根草混合时，这种真菌能提供必要的药力，配制出对抗虚弱疾病的有效解毒剂。由于它主要生长在潮湿的地下空间，且常有领地意识极强的枭兽出没，因此采集它需要小心地穿过这片原始荒野。"},{t="治疗课程",b="在奥伯丁，奥兰达利亚·夜歌指导年轻的德鲁伊们采集月亮菇，作为他们学习自然疗法的一部分。通过观察这种真菌等物质试剂如何对抗当地鹿群身上的剧毒，学徒们在学会通过变形和原始精神力量引导天然解毒剂之前，先掌握了草药疗法的基本原理。"}},faq={{q="月亮菇有什么用途？",a="月亮菇在调制疗伤药膏时能提供治疗效力。奥兰达利亚·夜歌将它与地根草和净水混合，以治疗黑海岸荒野中患病的鹿。",al={"月亮菇用途","月亮菇的作用","为什么要收集月亮菇"}},{q="月亮菇生长在哪里？",a="它生长在黑海岸奥伯丁以东的洞穴中，从月亮菇丛里萌发出来。这些黑暗的洞穴里同时也居住着易怒的枭兽，它们会守护领地，驱逐入侵者。",al={"月亮菇位置","在哪里可以找到月亮菇","月亮菇丛"}},{q="奥伯丁有谁需要这种真菌？",a="德鲁伊奥兰达利亚·夜歌要求荒野的学生采集月亮菇作为训练的一部分，利用其天然的药用特性为患病的森林动物配制疗法。",al={"谁需要月亮菇","奥伯丁草药任务"}},{q="为什么德鲁伊学徒必须采集实体草药来解毒？",a="了解物理性质的解毒剂是德鲁伊教育的基础步骤。通过收集像月亮菇这样的野外试剂，并观察特定成分如何对抗特定的毒素，学生们在学习通过精神魔法直接净化毒素之前，先掌握了治疗的基本原则。",al={"为什么德鲁伊要采集草药","德鲁伊解毒训练"}}},fp="12,145,22.360.0,19.340.0,30.153.0,29.166.0,38.160.0,68.264.0"}
P.entries["item:lurker-venom"] = {n="潜伏者的毒液",s="潜伏者的毒液是一种强效的天然毒素，从潜伏在洛克莫丹岩石山丘和树林中的掠食性蜘蛛身上采集而来。矮人防御者需要这种腐蚀性毒液作为关键成分，以制备一种用于应对黑铁破坏活动的化学中和剂。",h="潜伏者的毒液是一种强效的天然毒素，从潜伏在洛克莫丹岩石山丘和树林中的掠食性蜘蛛身上采集而来。矮人防御者需要这种腐蚀性毒液作为关键成分，以制备一种用于应对黑铁破坏活动的化学中和剂。",kw={"首席工程师hinderweir","cliff lurker","洛克莫丹","潜伏者的毒液","织网者珊达","蜘蛛毒液","巨石水坝","wood lurker"},ang={["profession:Engineering"]="在战场条件下，使用有机毒素来禁用敌方军械展示了矮人工程学中一种临时且具有反应性的分支。",["race:Dwarf"]="洛克莫丹的登山者和防御者经常利用当地的荒野危险来保护卡兹莫丹重要的基础设施，抵御黑铁氏族。"},sec={{t="一种挥发性试剂",b="洛克莫丹周围的山丘和悬崖上到处都是掠食性蛛形纲动物——从常见的Wood Lurkers到臭名昭著的蛛后Shanda the Spinner。尽管它们的叮咬对登山者和旅行者构成了持续的威胁，但炸药专家阿什兰·暗石将它们那致命的毒液列为拆弹剂的成分之一，这种拆弹剂由首席工程师Hinderweir负责配制。潜伏者的毒液与稀有矿物以及从洛克湖鳄鱼身上采集的泪液混合后，会形成一种反应溶剂，能够解除复杂的黑铁炸药。"}},faq={{q="潜伏者的毒液从哪里来？",a="它提取自洛克莫丹本土的各种潜伏蜘蛛，包括Cliff Lurkers、Forest Lurkers、Wood Lurkers以及它们的蛛后Shanda the Spinner。",al={"如何获取潜伏者的毒液","潜伏者的毒液掉落来源","在哪里寻找潜伏者的毒液"}},{q="潜伏者的毒液有什么用途？",a="首席工程师Hinderweir将这种毒液作为一种专用化学混合物的一部分，用于中和并拆除黑铁渗透者在巨石水坝周围部署的爆炸装置。",al={"为什么需要潜伏者的毒液","潜伏者的毒液用途","hinderweir如何使用毒液"}},{q="为什么要用毒液来拆除炸药？",a="矮人工程师经常依靠反应性、酸性或腐蚀性混合物来溶解精密机械部件，或在中和不稳定的爆破粉末时不引爆它们。",al={"为什么要用蜘蛛毒液处理炸弹","毒液如何停止黑铁炸弹"}},{q="Shanda the Spinner是唯一的来源吗？",a="不是。虽然珊达携带这种毒液，但任何栖息在洛克莫丹林地和岩石悬崖中的常见野生潜伏蜘蛛都可以产生它。",al={"必须杀死珊达吗","珊达 潜伏者的毒液"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="林度恩的毒药",s="林度恩的毒药是药剂师林度恩在塔伦米尔合成的一种炼金配方，旨在破坏荆棘谷地精在石爪山脉的乱砍滥伐。部落冒险者受托将它送往雷霆崖的药剂师扎玛手中，以便她设计出一种有效的投送装置。",h="林度恩的毒药是药剂师林度恩在塔伦米尔合成的一种炼金配方，旨在破坏荆棘谷地精在石爪山脉的乱砍滥伐。部落冒险者受托将它送往雷霆崖的药剂师扎玛手中，以便她设计出一种有效的投送装置。",kw={"药剂师林度恩","药剂师扎玛","林度恩的毒药","皇家药剂师学会","雷霆崖","剧毒粮草","荆棘谷地精"},ang={["race:Tauren"]="虽然牛头人欢迎外界帮助对抗荆棘谷地精对自然的破坏，但皇家药剂师学会的化学手段触及了他们萨满教义的底线。",["race:Undead"]="林度恩的毒药的运输体现了皇家药剂师学会深远的联络网，通过协调洛丹伦和卡利姆多之间的实地研究，向盟友展示了被遗忘者的价值。"},sec={{t="皇家药剂师学会的解决方案",b="这种致命的化合物由希尔斯布莱德丘陵的药剂师林度恩开发，旨在对抗在石爪山脉肆意破坏的荆棘谷地精伐木工。据林度恩所言，这种配方接触后会产生致命且具有潜在传染性的效果。然而，在能被用于对付狂风峭壁周围的地精行动之前，它必须跨越大陆运送到雷霆崖，交给皇家药剂师学会驻雷霆崖的代表药剂师扎玛。扎玛需要这种原始混合物来研制一种大范围扩散装置——剧毒粮草，以确保这种药剂在消灭那些剥削性的伐木工的同时，不会对部落资产造成不必要的威胁。"}},faq={{q="林度恩的毒药有什么用途？",a="这种毒药是药剂师林度恩为了打破荆棘谷地精对狂风峭壁地区的控制而调制的。它被设计成对破坏性的地精劳工具有毁灭性和潜在的传染性。",al={"林度恩毒药用途","毒药的作用","制作林度恩毒药的原因"}},{q="药剂师林度恩是谁？",a="药剂师林度恩是皇家药剂师学会的一员，驻扎在希尔斯布莱德丘陵的塔伦米尔。他专门研制剧毒和实验性化合物，以推进被遗忘者的目标。",al={"林度恩是谁","药剂师林度恩","林度恩的创造者"}},{q="为什么毒药需要送到雷霆崖？",a="尽管林度恩完善了化学混合物，但它缺乏一种实际的大规模部署方法。药剂师扎玛居住在雷霆崖的灵魂高地，负责研究当地植物群并协调学会在卡利姆多的工作；她负责将毒药改造为便携式的喷雾投送系统。",al={"为什么去雷霆崖","为什么要将毒药带给扎玛","药剂师扎玛的用途"}},{q="扎玛收到毒药后会发生什么？",a="在收到药瓶后，药剂师扎玛将该药剂加工成一种名为剧毒粮草的加压气溶胶装置，使特工能够将其散布到荆棘谷地精营地的中心地带。",al={"剧毒粮草的制作","扎玛如何处理毒药"}}},fp="13,220,27.482.0,31.158.0,24.179.0,47.229.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="马克格拉恩的干肉",s="马克格拉恩的干肉是猎人图德拉·马克格拉恩为了在严酷的丹莫罗寒冬中生存而准备的一个月的腌制口粮。这些补给储存在一个加固的瑟银肉箱里，但整个储藏物被凶猛的雪人Old Icebeard抢走了。",h="马克格拉恩的干肉是猎人图德拉·马克格拉恩为了在严酷的丹莫罗寒冬中生存而准备的一个月的腌制口粮。这些补给储存在一个加固的瑟银肉箱里，但整个储藏物被凶猛的雪人Old Icebeard抢走了。",kw={"寒风峡谷","丹莫罗","马克格拉恩的干肉","肉箱","old icebeard","图德拉·马克格拉恩"},ang={["profession:Cooking"]="腌制和熏制野味是丹莫罗一项必不可少的生存烹饪技术，它能让像马克格拉恩这样的猎人将肉类保存数月，而不会在严寒中变质。",["race:Dwarf"]="矮人登山者非常清楚，在高海拔山峰上，做好准备意味着生存，而失去冬季储备可能意味着生与死的区别。"},sec={{t="一份冬季储备",b="在丹莫罗冰冷的峭壁中生活需要仔细的规划。为了应对寒冷季节的暴风雪，矮人猎人图德拉·马克格拉恩花了数周时间狩猎野味、腌制肉类，并将其锁在一个坚固的箱子里。由于意识到食腐熊和潜行的掠食者经常侵扰他的家园，马克格拉恩不敢大意，将食物储存在一个瑟银肉箱中。即便采取了这些预防措施，他也没有预料到会有入侵者强大到能把整个箱子扛走，而不是当场撬开它。"},{t="进入雪人之穴",b="当马克格拉恩外出追踪鹿群时，臭名昭著的雪人Old Icebeard突袭了猎人的营地，并将沉重的箱子拖回了他在寒风峡谷的巢穴。虽然这头野兽没有办法破坏坚固的瑟银外壳，但马克格拉恩受伤的腿使他无法迅速冲进洞穴进行营救。如果没有外界的帮助在冬季来临前取回这些补给，这位受困的猎人将面临在山间雪地中饿死的危险。"}},faq={{q="什么是马克格拉恩的干肉？",a="它们是图德拉·马克格拉恩为度过丹莫罗苦寒的冬天而保存的一个月的腌制口粮。",al={"马克格拉恩的干肉是什么","图德拉的肉","马克格拉恩的肉类储备"}},{q="为什么要将肉锁在箱子里？",a="丹莫罗到处都是像山地熊这样饥饿的掠食者。马克格拉恩将他的干肉锁在一个加固的瑟银肉箱里，这样食腐的野兽就无法破坏他的冬季食物储备。",al={"为什么要锁住肉","为什么要用瑟银箱","马克格拉恩的箱子"}},{q="谁偷走了肉箱？",a="一个名叫Old Icebeard的邪恶雪人在马克格拉恩外出猎鹿时偷走了整个箱子，并将这个沉重的容器拖回了他在寒风峡谷的洞穴巢穴中。",al={"谁拿走了肉","谁偷了它","肉箱窃贼"}},{q="为什么图德拉·马克格拉恩不能自己取回干肉？",a="马克格拉恩的腿受了伤，这使他失去了潜入Old Icebeard巢穴并在凶猛的雪人围攻他之前逃脱所需的速度和隐蔽性。",al={"为什么马克格拉恩不去取回","为什么图德拉需要帮助","图德拉受伤"}}},fp="22,76,14.284.0,20.360.0,32.102.0,37.177.0,26.124.0,53.78.0"}
P.entries["item:mackreel-s-moonshine"] = {n="马克里尔的月光酒",s="“马克里尔的月光酒”是由醉鬼马克里尔酿造的一种烈性矮人酒，他驻扎在湿地以北断开的萨多尔大桥上。这种酒烈到能让值班的哨兵直接倒下，甚至远在北方的南海镇也对其推崇备至，酿酒师布鲁米·比格尔甚至接受它作为偿还债务的抵扣物。",h="“马克里尔的月光酒”是由醉鬼马克里尔酿造的一种烈性矮人酒，他驻扎在湿地以北断开的萨多尔大桥上。这种酒烈到能让值班的哨兵直接倒下，甚至远在北方的南海镇也对其推崇备至，酿酒师布鲁米·比格尔甚至接受它作为偿还债务的抵扣物。",kw={"布鲁米·比格尔","矮人酿造","醉鬼马克里尔","马克里尔的月光酒","月光酒","南海镇","湿地"},ang={["profession:Cooking"]="虽然它只是作为粗糙的月光酒而非精致的烹饪美酒来蒸馏的，但像马克里尔酿造的这种强劲的地区性烈酒，在边境酒馆中都是主要的贸易商品。",["race:Dwarf"]="矮人们闻一闻就知道什么是好酒，马克里尔的月光酒显然劲儿大到足以把一名山地探险者撂倒。"},sec={{t="烈性酿造",b="这种月光酒由驻扎在萨多尔大桥上的守卫醉鬼马克里尔酿造，以其极高的烈度而声名狼藉。即便是久经沙场的矮人哨兵，在饮用过一晚之后也会被放倒，醒来时头痛欲裂，感觉就像有一整支攻城器械旅从头顶碾过。尽管它后劲极强，但它在帮助旅行者抵御洛丹伦和卡兹莫丹的潮湿寒冷方面却极具价值。"},{t="支付给南海镇",b="醉鬼马克里尔欠了南海镇的酒馆老板兼酿酒大师布鲁米·比格尔一笔未结清的债务。为了清偿账单，马克里尔用他的一批月光酒代替钱币进行抵债。比格尔欣然接受了用这种酒代替金币，急于将马克里尔的烈酒加入他的库存，以应对希尔斯布莱德丘陵寒冷的海边日子。"}},faq={{q="谁酿造了马克里尔的月光酒？",a="它是由醉鬼马克里尔蒸馏的，他是一名矮人哨兵，驻扎在湿地和阿拉希高地之间萨多尔大桥的断裂处。",al={"马克里尔的月光酒创造者","谁酿造的","醉鬼马克里尔烈酒"}},{q="为什么要将这种月光酒送到南海镇？",a="醉鬼马克里尔欠了南海镇酿酒师布鲁米·比格尔一笔债。为了清偿逾期债务，他同意不付钱，而是给比格尔送去一批他新酿的月光酒。",al={"为什么去南海镇","月光酒运送","酿酒师布鲁米·比格尔债务"}},{q="马克里尔的月光酒有多烈？",a="它非常烈。马克里尔承认他在喝了这酒后，曾在值班时昏迷不醒，事后抱怨说头痛得就像有一整支攻城器械旅在他的头骨上隆隆作响。",al={"它有多烈","月光酒强度","马克里尔的月光酒效果"}},{q="为什么这批货需要紧急送达？",a="马克里尔喝得烂醉如泥，在睡梦中错过了值班时间，直到醒来才发现离他与酿酒师布鲁米·比格尔约定的债务期限仅剩几分钟了。",al={"为什么有时限","任务是否有时间限制","为什么要赶时间"}}},fx={abca7076={q="马克里尔的月光酒是什么？",a="马克里尔的月光酒是醉鬼马克里尔在湿地酿造的一种烈性手工酒。它以酒劲惊人而臭名昭著，甚至能让强壮的矮人宿醉不已，仿佛一队攻城器械从他脑袋上碾过。除了酒劲十足，它还是颇受欢迎的交易品，远至希尔斯布莱德丘陵的人们也会在寒冷的日子里买来暖身。",al={"马克里尔的月光酒是什么","马克里尔的月光酒","醉鬼马克里尔酿的酒"}}},fp="20,161,13.340.0,21.313.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="蛆眼的爪子",s="蛆眼的爪子是从加伦鬼屋的豺狼人首领蛆眼身上取下的可怕战利品。将其带回布瑞尔，可以作为该野兽因替天灾军团盗墓而被处决的实物证明。",h="蛆眼的爪子是从加伦鬼屋的豺狼人首领蛆眼身上取下的可怕战利品。将其带回布瑞尔，可以作为该野兽因替天灾军团盗墓而被处决的实物证明。",kw={"悬赏","布瑞尔","执行官塞加德","加伦鬼屋","豺狼人","蛆眼","蛆眼的爪子","提瑞斯法林地"},ang={["race:Undead"]="对于布瑞尔的被遗忘者来说，带回蛆眼的爪子是对那些向可恨的巫妖王提供原材料的盗尸贼的一次直接打击。"},sec={{t="处决证明",b="蛆眼因在加伦鬼屋附近劫掠坟墓、洗劫乡野，并将尸体提供给巫妖王的军队而招致了被遗忘者的严厉惩罚。为此，布瑞尔镇发布了正式的死刑判决和悬赏令。由于对于像执行官塞加德这样的军事行政官来说，仅仅听到死讯是不够的，赏金猎人必须砍下恶棍的爪子带回镇上，才能领取奖励并结束悬赏任务。"}},faq={{q="为什么执行官塞加德想要蛆眼的爪子？",a="执行官塞加德需要不可辩驳的证据，以证明这只被判死刑的豺狼人确实已经被除掉。一只被砍下的爪子可以作为处决的实物确认，之后布瑞尔才会发放赏金。",al={"为什么需要爪子","蛆眼悬赏证明","塞加德爪子"}},{q="蛆眼对被遗忘者犯下了什么罪行？",a="蛆眼带领掠夺者在提瑞斯法林地的北部地区进行劫掠，专门从加伦鬼屋等农场盗取埋葬的尸体，以供应巫妖王的军队。",al={"蛆眼的罪行","为什么通缉蛆眼","蛆眼做了什么"}},{q="蛆眼在哪里可以找到？",a="蛆眼居住在提瑞斯法林地布瑞尔以北的加伦鬼屋，那是一处废弃的农场，他通常潜伏在破旧的农舍里。",al={"蛆眼位置","去哪找蛆眼","加伦鬼屋豺狼人"}},{q="为什么豺狼人要与巫妖王的部队合作？",a="虽然豺狼人天性就是投机取巧的食腐动物，但提瑞斯法林地的一些流寇团伙已经与天灾军团结盟或受到其控制，他们劫掠人类和被遗忘者的坟墓，并将尸体运送给通灵师。",al={"豺狼人与天灾军团","为什么豺狼人偷尸体","天灾豺狼人"}}},fp="16,163,18.347.0,47.144.0,55.161.0,26.138.0,51.161.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="马格兰的信件",s="马格兰的信件是马格兰在烈日石居写的一份正式公文。它被送往卡利姆多的升降梯，让一名驻守的哨兵得到了期待已久的轮换，得以回家探望家人。",h="马格兰的信件是马格兰在烈日石居写的一份正式公文。它被送往卡利姆多的升降梯，让一名驻守的哨兵得到了期待已久的轮换，得以回家探望家人。",kw={"贫瘠之地","大地之缚","瑞什","信件","升降梯","远行者","马格兰","预备役","石爪"},ang={["faction:Horde"]="这封公文突显了部落在战后为关照分散的部队所做的努力，通过轮换新鲜的预备役人员前往卡利姆多各处的遥远前哨站。"},sec={{t="被解职的哨兵",b="在卡利姆多广袤崎岖的土地上维持前哨站需要高度的警惕，但部落的领导者们深知，长期的值守会对士气造成沉重的打击。这封简单的公文由马格兰在烈日石居的高耸岩架上亲笔书写，正式通知瑞什·远行者已经派遣了一名替换战士前往升降梯接替他的岗哨。对于守望在遥远南方高耸木质绞盘上的孤独卫兵来说，这封信承诺了在乱世中罕见的东西：准予光荣休假，以便与家人团聚。"}},faq={{q="马格兰的信件有什么用途？",a="这封信包含马格兰下达的正式命令，将哨兵瑞什·远行者从南贫瘠之地的升降梯岗位上撤下，允许他回家探望家人。",al={"这封信的作用","马格兰信件的用途","为什么要送信"}},{q="是谁写了这封信？",a="这封信是由石爪山脉烈日石居的长者马格兰所写。",al={"作者是谁","预备役信件的作者","马格兰"}},{q="谁是这封信的收件人？",a="这封信的收件人是瑞什·远行者，他是驻扎在连接南贫瘠之地和千针石林的升降梯顶部的部落卫兵。",al={"谁收到信","信件接收者","信送到哪里"}},{q="这封信被送到了哪里？",a="信件必须穿过贫瘠之地南下，送到千针石林峡谷边缘的升降梯处。",al={"投递地点","瑞什在哪里","升降梯位置"}}},fx={["419ae143"]={q="马格兰的信件是什么？",a="这是一封由马格兰在石爪山脉的烈日石居亲笔写下的正式公文。信中告知驻守的部落卫兵瑞什·远行者，一名预备队战士即将前来接替他的岗位，让他得以休假探望家人。",al={"马格兰的信件是什么","马格兰的信件","预备队信件"}},eb8a36e5={q="瑞什·远行者为什么想要马格兰的信件？",a="瑞什早就请求有人接替他的岗位，因此一直盼着收到消息。在南贫瘠之地看守升降梯是一项单调的差事，而这封信正式批准由一名预备队战士接替他，终于让他得以盼来已久地休假探亲。",al={"瑞什为什么想要这封信","为什么需要这封预备队信件","为什么需要马格兰的信件"}}},fp="24,155,17.345.0,48.154.0,21.101.0,27.155.0,30.114.0"}
P.entries["item:mangy-claw"] = {n="肮脏的爪子",s="肮脏的爪子是从丹莫罗的巨型冰爪熊“脏爪”身上切下来的一只爪子。它是一个冷酷的证明，说明导致一名受困的矮人飞行员死亡的致命野兽终于被杀死了。",h="肮脏的爪子是从丹莫罗的巨型冰爪熊“脏爪”身上切下来的一只爪子。它是一个冷酷的证明，说明导致一名受困的矮人飞行员死亡的致命野兽终于被杀死了。",kw={"丹莫罗","莫里·铁钻","冰爪熊","脏爪","肮脏的爪子","驾驶员塞克·锤足","攻城小队"},ang={["class:Hunter"]="在残酷的山地暴风雪中追踪像脏爪这样臭名昭著的掠食者，是对猎人狩猎这种危险的领地性野兽能力的考验。",["race:Dwarf"]="对于矮人来说，实现阵亡同伴的临终遗愿并为铁炉堡攻城小队的一员复仇，是涉及深刻的个人荣誉和氏族荣誉的大事。"},sec={{t="垂死飞行员的遗愿",b="当莫里·铁钻飞行员的蒸汽坦克在丹莫罗的冰冻山丘上抛锚时，他只能徒步继续搜寻矿石，却独自面对了荒凉的山地。根据他被找回的日记记载，莫里·铁钻曾设法击退了一头名为“脏爪”的巨大冰爪熊的初期攻击，但在搏斗中受了重伤。这头野兽后来又折返回来，杀死了虚弱的飞行员。莫里·铁钻在日记的最后一篇条目中请求为他向这只掠食者复仇，从这只倒下的熊身上取下肮脏的爪子，便完成了这一任务。"},{t="为攻城小队复仇",b="将肮脏的爪子交给驾驶员塞克·锤足，为铁炉堡攻城小队画上了一个句号。塞克·锤足曾派出搜索队进入积雪中，希望能活着找到他的朋友，却得知了其悲惨的命运。提交莫里·铁钻的日记和掠食者断下的爪子，证明了莫里·铁钻临终的请求已经得到满足，让他得以安息，并赢得了铁炉堡飞行员们的感激。"}},faq={{q="什么是肮脏的爪子？",a="这是从潜伏在丹莫罗的凶猛冰爪熊“脏爪”身上切下的战利品。它作为实物证据，证明了这只野兽已被猎杀。",al={"肮脏的爪子用途","这只爪子是什么","脏爪物品"}},{q="谁想要肮脏的爪子？",a="驻扎在丹莫罗山口附近的驾驶员塞克·锤足，他在寻找这只爪子以及他已故的朋友莫里·铁钻的日记，以确认杀死朋友的熊已被除掉。",al={"谁会收下肮脏的爪子","肮脏的爪子交还","驾驶员塞克·锤足交还"}},{q="为什么要猎杀脏爪？",a="一名叫莫里·铁钻的矮人飞行员在蒸汽坦克抛锚后徒步搜寻矿石时，被脏爪袭击并最终杀害。莫里·铁钻在个人日记中写下的临终遗愿，是希望有人能为他向这只野兽复仇。",al={"为什么要杀脏爪","谁死于脏爪之手","莫里·铁钻背景故事"}},{q="脏爪出没在哪里？",a="脏爪在丹莫罗的雪岭和山丘间徘徊，距离发现莫里·铁钻遗骸的地方不远。",al={"脏爪位置","脏爪在哪里","脏爪 丹莫罗"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="治安官哈迦德的徽章",s="治安官哈迦德的徽章是治安官哈迦德在暴风城服役期间携带的军衔与权力的象征。在被迪菲亚潜行者强盗Dead-tooth Jack通过诡计窃取后，这枚徽章作为冒充城市官员的工具，构成了危险的威胁。",h="治安官哈迦德的徽章是治安官哈迦德在暴风城服役期间携带的军衔与权力的象征。在被迪菲亚潜行者强盗Dead-tooth Jack通过诡计窃取后，这枚徽章作为冒充城市官员的工具，构成了危险的威胁。",kw={"dead-tooth jack","迪菲亚","艾尔文森林","治安官杜汉","治安官哈迦德","治安官哈迦德的徽章","暴风城","保险箱"},ang={["class:Warrior"]="找回哈迦德的徽章可以向这位暴风城军队的老兵证明你的勇气，他会用自己战斗时期精心保养的剩余武器来奖励有前途的战士。",["faction:Alliance"]="找回徽章可以维护暴风城军事指挥系统的完整性，并防止迪菲亚潜行者从内部破坏当地的防御。"},sec={{t="被盗的徽章",b="虽然治安官哈迦德早已退休，回到了艾尔文森林山丘中的小农场，但他那枚旧的暴风城治安官徽章依然具有官方效力。在夜色的掩护下，一名名为Dead-tooth Jack的迪菲亚潜行者盗贼穿上暴风城战袍，假扮成闪金镇的驻军指挥官治安官杜汉。年迈的哈迦德信以为真，以为昔日的同僚需要这枚徽章来处理公务，便毫无怀疑地将其交出。在退休的军官察觉骗局之前，Jack已经逃进了森林。在迪菲亚潜行者手中，这枚暴风城权力的象征可能会让不法之徒溜过检查站，或在当地巡逻队中制造混乱。"}},faq={{q="什么是治安官哈迦德的徽章？",a="这是治安官哈迦德在暴风城服役期间的官方军衔徽章。即使在退休后，保留这样一枚徽章也象征着过去的军职地位，并具有真正的权威。",al={"哈迦德的徽章","治安官徽章"}},{q="Dead-tooth Jack是如何得到这枚徽章的？",a="Dead-tooth Jack在夜色的掩护下，身穿暴风城战袍接近了治安官哈迦德的家。在昏暗的灯光下，哈迦德误以为他是闪金镇的治安官杜汉，并在被索要时交出了徽章。",al={"徽章是如何被盗的","谁偷了徽章","dead-tooth jack的诡计"}},{q="为什么这枚徽章落在迪菲亚潜行者手中会很危险？",a="有了真正的治安官徽章和伪装的制服，迪菲亚潜行者特工可以冒充暴风城的高级官员，从而绕过哨兵、潜入驻军或向城镇卫兵发布虚假命令。",al={"jack为什么要这枚徽章","迪菲亚潜行者的徽章用途","徽章的危险性"}},{q="徽章被放在哪里？",a="Dead-tooth Jack把被盗的徽章锁在他的保险箱里，藏在艾尔文森林治安官哈迦德的农场南面的营地中。",al={"徽章的位置","去哪里找徽章","dead-tooth的保险箱"}}},fp="23,205,17.489.0,32.160.0,38.185.0,54.192.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="玛丽的眼镜",s="玛丽的眼镜曾是盲眼玛丽的珍宝，但在那场夺走她双眼与生命的悲剧发生之前，它被遗弃了。这面镜子被丢弃在暮色森林闹鬼的丛林中，被一只游荡的食尸鬼捡走，后来有人为了完成维克托·安特拉斯的望远镜而特意寻找它。",h="玛丽的眼镜曾是盲眼玛丽的珍宝，但在那场夺走她双眼与生命的悲剧发生之前，它被遗弃了。这面镜子被丢弃在暮色森林闹鬼的丛林中，被一只游荡的食尸鬼捡走，后来有人为了完成维克托·安特拉斯的望远镜而特意寻找它。",kw={"盲眼玛丽","夜色镇","暮色森林","疯狂的食尸鬼","仰望星空","镜子","玛丽的眼镜","静谧花园墓场","维克托·安特拉斯"},ang={["faction:Alliance"]="从潜伏在静谧花园墓场的恐怖生物手中夺回遗物，为夜色镇饱受困扰的市民们带来了一丝慰藉，并对城镇的各种项目有所帮助。",["profession:Engineering"]="工程师们想必会欣赏维克托的独创性，他将一面古董家用镜子改造成了天文观测设备中功能完备的光学反射镜。"},sec={{t="被遗弃的宝物",b="在遭遇可怕的命运之前，盲眼玛丽视这面打磨光亮的镜子为珍宝。在她死后并失去双眼，再次审视自己的倒影成了一种令她痛苦的提醒，让她想起了自己所失去的一切。她将镜子扔到了谷仓后面，任由它被暮色森林那不断蔓延的阴霾所吞噬。在那里，镜子落入了徘徊在废墟边缘的一只疯狂的食尸鬼手中，被带到了南方的静谧花园墓场陵墓里。"},{t="仰望星空",b="在夜色镇，古怪的观星者维克托·安特拉斯梦想着能透过暮色森林永恒的黄昏，窥视上方纯净的苍穹。建造他的望远镜需要专门的光学透镜和反射镜。在得知他的需求后，玛丽指引冒险者们去猎杀那些潜伏在墓场废弃教堂里的野性亡灵，取回这面镜子，作为他宏伟观星装置中的光学反射镜。"}},faq={{q="玛丽为什么要扔掉这面镜子？",a="这面镜子曾是玛丽最珍贵的财宝之一，但在发生了一件她没有详细描述的事件后，她将其丢弃在谷仓后面。在另一次交谈中她解释说，由于无法忍受自己的容貌，她挖出了自己的双眼。",al={"玛丽为什么扔掉它","为什么要丢弃镜子","盲眼玛丽镜子背景故事"}},{q="玛丽扔掉镜子后，它落到了谁手里？",a="一只在玛丽旧农舍后方的树林中游荡的疯狂的食尸鬼捡走了这面被丢弃的镜子。这只癫狂的亡灵最终在静谧花园墓场的废弃教堂中安了家。",al={"谁拿着镜子","谁掉落了镜子","镜子在哪里"}},{q="为什么维克托·安特拉斯想要玛丽的眼镜？",a="维克托正在建造一台复杂的望远镜，以穿透暮色森林的阴霾来研究群星。他需要一个精细的反射面来引导光线穿过设备，而玛丽保存下来的镜子完美契合了他的设计。",al={"为什么维克托需要镜子","维克托镜子的用途","望远镜镜片"}},{q="在哪里可以找到持有镜子的疯狂的食尸鬼？",a="这只疯狂的食尸鬼潜伏在暮色森林的最东南角，通常在静谧花园墓场内部那座废弃的石砌教堂里游荡。",al={"疯狂的食尸鬼位置","疯狂的食尸鬼在哪里","静谧花园墓场的食尸鬼"}}},fx={afb2ba8d={q="玛丽的眼镜是什么？",a="玛丽的眼镜是一面手持镜子，曾属于盲眼玛丽。玛丽视它为自己最珍贵的私人物品之一，后来在一场可怕的事故发生后，她把它扔在了谷仓后面。之后，这面镜子落入了一只在暮色森林游荡的亡灵食尸鬼手中。",al={"玛丽的眼镜是什么","玛丽的眼镜物品","盲眼玛丽的眼镜"}}},fp="20,81,19.354.0,19.372.0,42.247.0,53.196.0,56.195.0,55.124.0"}
P.entries["item:mathystra-relic"] = {n="黑暗深渊遗物",s="黑暗深渊遗物是散落在黑海岸北部玛塞斯特拉废墟中，被植被覆盖的古老暗夜精灵神器。尽管它们只是精灵堡垒陷落后的遗迹，但仍蕴藏着沉睡的魔法碎片，这些碎片引起了暮光之锤教派的兴趣。",h="黑暗深渊遗物是散落在黑海岸北部玛塞斯特拉废墟中，被植被覆盖的古老暗夜精灵神器。尽管它们只是精灵堡垒陷落后的遗迹，但仍蕴藏着沉睡的魔法碎片，这些碎片引起了暮光之锤教派的兴趣。",kw={"黑海岸","古树之林","主宰之剑","玛塞斯特拉","黑暗深渊遗物","奥诺","玛塞斯特拉废墟","暮光之锤"},ang={["class:Druid"]="德鲁伊与像奥诺这样的古树密切合作，通过确保被遗忘的魔法残余不会助长黑暗召唤，来帮助维护黑海岸脆弱的平衡。",["race:NightElf"]="对于卡多雷而言，找回这些遗物既是为了防止危险的古代奥术落入暮光之锤手中，也是为了纪念那座在大分裂中失落的城市的遗产。"},sec={{t="陷落堡垒的遗迹",b="在大分裂之前，玛塞斯特拉曾是一座屹立在卡利姆多海岸的骄傲城市，也是精灵文明的堡垒。如今，这里倒塌的圆柱和破碎的石块被灌木丛和海雾半掩，游荡着躁动不安的灵魂与潜伏的野兽。散落在废墟各处的，是追溯到那个黄金时代的古老遗物。尽管经历了万年的荒废与磨损，这些神器依然保留着暗夜精灵奥术工艺的微弱痕迹，若任其遗弃，它们将会成为危险的奖品。"},{t="逼近的威胁",b="古树之林的古树奥诺在发现邪恶的暮光之锤教派试图将主宰之剑出土的被遗忘的精灵文字武器化之后，开始寻找这些遗物。邪教徒们企图利用古老的卡多雷魔法来加速他们黑暗主宰的回归。通过研究这些散落的遗迹，奥诺和黑海岸的守护者们希望解开教派的企图，并保护玛塞斯特拉那逐渐消逝的力量，以免其被用于黑暗目的。"}},faq={{q="什么是黑暗深渊遗物？",a="它们是古老暗夜精灵城市玛塞斯特拉留下的碎片和神器。尽管已经历了数千年的时光，它们仍然保留着大分裂前精灵文明的魔法工艺残余。",al={"什么是黑暗深渊遗物","玛塞斯特拉的精灵遗物","这些遗物是什么"}},{q="这些遗物在哪里可以找到？",a="它们散落在玛塞斯特拉废墟的断壁残垣、倒塌的石柱和高耸的草丛之中，位于黑海岸的北部地区。",al={"黑暗深渊遗物的位置","去哪里寻找遗物","遗物位置"}},{q="谁想要黑暗深渊遗物？",a="居住在黑海岸南部古树之林的知识古树奥诺，请求旅行者收集这些遗物以供研究。",al={"谁需要遗物","我该把遗物带给谁","奥诺 遗物"}},{q="为什么暮光之锤对它们感兴趣？",a="该教派一直在破译附近主宰之剑出土的古代精灵文献。他们试图扭曲并利用古代精灵的魔法秘密，以协助召唤他们阴影中的主宰降临世间。",al={"为什么暮光之锤想要遗物","暮光之锤 玛塞斯特拉"}}},fp="15,171,28.454.0,15.410.1,30.201.0,29.128.0,31.132.0,48.184.0"}
P.entries["item:melenas-head"] = {n="迈雷纳斯的头颅",s="迈雷纳斯的头颅是取自萨特指挥官迈雷纳斯大人的被斩下的赏金首级，他曾盘踞在地狱石内。作为他死亡的绝对证据带回，这个战利品标志着泰达希尔枝干上一个挥之不去的恶魔威胁被悄然消除了。",h="迈雷纳斯的头颅是取自萨特指挥官迈雷纳斯大人的被斩下的赏金首级，他曾盘踞在地狱石内。作为他死亡的绝对证据带回，这个战利品标志着泰达希尔枝干上一个挥之不去的恶魔威胁被悄然消除了。",kw={"地狱石","格里尔","迈雷纳斯大人","迈雷纳斯的头颅","萨特","泰达希尔","twisted hatred"},ang={["class:Warrior"]="带着敌方督军的头颅提供了最确凿、最原始的证明，表明一个危险的对手及其格里尔大军已被击溃。",["race:NightElf"]="萨特代表了古老暗夜精灵血统的悲剧性恶魔扭曲，这使得对迈雷纳斯大人的秘密处决既是必要之举，也是一种文化耻辱。"},sec={{t="难以启齿的耻辱",b="对于守卫幽影谷和泰达希尔周边地区的暗夜精灵来说，萨特在他们新生的世界之树上的存在本身就是一种痛苦的耻辱。迈雷纳斯大人选择在地狱石那扭曲的洞穴内安营扎寨，就在精灵定居点的北面，并将好战的格里尔勇士招致麾下。由于卡多雷在处理其核心领地附近的腐化时非常注重保密，这颗血淋淋的头颅便是他阴谋诡计在扩散之前被彻底终结的私密证据。"}},faq={{q="迈雷纳斯大人是谁？",a="迈雷纳斯大人是一名前潜伏在泰达希尔地狱石洞穴中的萨特指挥官。他召集了一支格里尔战团，在自己麾下密谋对抗附近的卡多雷哨所。",al={"迈雷纳斯大人背景故事","迈雷纳斯是谁","迈雷纳斯的故事"}},{q="为什么他的死必须保持低调？",a="萨特——那些被恶魔腐化而扭曲的古老暗夜精灵——出现在距离泰达希尔神圣枝干如此近的地方，被卡多雷当局视为一种极大的尴尬。迅速而隐秘地解决掉他可以防止恐慌并尽可能减少耻辱。",al={"为什么需要保密","twisted hatred秘密","为什么悄悄进行"}},{q="迈雷纳斯的头颅是从哪里取下的？",a="这颗头颅是在地狱石深处取下的，那是一个位于泰达希尔中部、多兰纳尔以北的腐化洞穴。",al={"哪里能找到迈雷纳斯","地狱石位置","迈雷纳斯位置"}}},fp="13,184,20.444.0,21.159.0,32.259.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="米奈希尔雕像",s="米奈希尔雕像是一尊罕见的银色小雕像，刻画了已故国王泰瑞纳斯·米奈希尔二世年轻时作为圣骑士高举战锤的形象。这尊雕像在湿地海岸的一场海难中遗失，是洛丹伦亡国君主极为稀少的纪念物。",h="米奈希尔雕像是一尊罕见的银色小雕像，刻画了已故国王泰瑞纳斯·米奈希尔二世年轻时作为圣骑士高举战锤的形象。这尊雕像在湿地海岸的一场海难中遗失，是洛丹伦亡国君主极为稀少的纪念物。",kw={"盲公主号","蓝腮鱼人","bolvar fordragon","cathedral of light","格雷森·沙东布瑞克","米奈希尔雕像","泰瑞纳斯·米奈希尔","湿地"},ang={["class:Paladin"]="雕像展现了已故的泰瑞纳斯国王作为年轻的圣光战士，举起战锤的英姿，对于哀悼亡国的圣骑士们来说，这不仅是一幅肖像，更是一段深刻的回忆。",["faction:Alliance"]="泰瑞纳斯是创立大联盟的统一领袖，这使得任何保存下来的纪念物都成为了这个破碎世界中鼓舞人心的瑰宝。"},sec={{t="洛丹伦的珍稀遗物",b="这尊雕像刻画了泰瑞纳斯·米奈希尔二世国王早年的形象，描绘了一位长发的圣骑士将战锤举向天空。泰瑞纳斯在位时以谦逊闻名，不喜欢个人纪念碑，因此很少有雕像或肖像画是为纪念他而作。随着洛丹伦王国在天灾军团的铁蹄下覆灭，几乎所有此类遗物都被摧毁，这使得这尊幸存的雕像对联盟而言极其珍贵。"},{t="沼泽中的失落",b="该雕像曾是商船“盲公主号”上的货物，目的地是联盟的米奈希尔港。当这艘船在沼泽海岸附近遭到好斗的蓝腮鱼人袭击时，货物散落一地，雕像最终被困在岸边的一个半掩的桶里。随着龙喉兽人等当地威胁在附近徘徊，当地守军急忙将找回的圣物送往南方的暴风城，伯瓦尔·弗塔根公爵将其托付给了圣光大教堂。"}},faq={{q="雕像上的人是谁？",a="它刻画的是泰瑞纳斯·米奈希尔二世国王，他是洛丹伦的前任统治者，也是最初联盟的缔造者。他展示的并非年迈的君主形象，而是年轻时手持战锤的圣骑士形象。",al={"雕像上是谁","雕像描绘了什么","谁是米奈希尔雕像"}},{q="雕像是如何丢失的？",a="它在被商船“盲公主号”运送过无尽之海时遗失。当该船在湿地遭到蓝腮鱼人袭击后，货物被冲上岸并埋入了泥土中。",al={"它是如何丢失的","谁丢失了雕像","湿地海难雕像"}},{q="为什么泰瑞纳斯国王的雕像如此罕见？",a="泰瑞纳斯国王是一位谦逊的统治者，他不喜欢夸耀自己的纪念物，因此很少有人为他雕刻雕像。北方几乎所有残存的肖像画和雕像都在天灾军团对洛丹伦的毁灭中被摧毁了。",al={"为什么泰瑞纳斯的雕像很少","泰瑞纳斯纪念物"}},{q="雕像最终在哪里？",a="在湿地被寻回后，它被送到了暴风城要塞的伯瓦尔·弗塔根公爵手中。伯瓦尔意识到圣光已经在遗物中凝聚，并指示将其交由圣光大教堂的格雷森·沙东布瑞克公爵妥善保管。",al={"我应该把雕像带到哪里","谁保管着雕像","大教堂雕像"}}},fx={["00c7d589"]={q="米奈希尔雕像是什么？",a="米奈希尔雕像是一尊银色小雕像，刻画的是年轻时的泰瑞纳斯·米奈希尔二世：他留着长发，举起战锤，身着圣骑士装束。除了精妙再现这位已故洛丹伦君王的形象，这件遗物似乎还凝聚着圣光，使它既是珍贵的历史纪念物，也是受祝福的圣物。",al={"米奈希尔雕像是什么","米奈希尔雕像","这尊小雕像是什么"}},["0d8a0354"]={q="为什么人们如此渴求米奈希尔雕像？",a="泰瑞纳斯国王厌恶个人纪念碑和纪念物，因此留存下来的肖像极少；其中几乎所有都在洛丹伦被天灾军团攻陷时遭到毁坏。它的稀有性、蕴含的圣光，以及它与联盟创始者之间深厚的情感联系，使其成为无可替代的传家宝。如果无人看守，像当地龙喉兽人这样的敌人定会乐于亵渎或掠走它。",al={"为什么人们想要米奈希尔雕像","为什么这尊小雕像很值钱","谁想要这尊小雕像"}}},fp="18,131,25.334.0,16.428.0,30.165.0,27.174.0,43.197.0,32.222.1"}
P.entries["item:merrin-s-letter"] = {n="麦琳的信件",s="麦琳的信件是一封由麦琳·石纹写下的紧急信件，她是一位被困在湿地挖掘场的考古学家。信中描述了他们的考古探险队被凶猛的迅猛龙袭击的惨状，并向她的爱人保证自己目前平安。",h="麦琳的信件是一封由麦琳·石纹写下的紧急信件，她是一位被困在湿地挖掘场的考古学家。信中描述了他们的考古探险队被凶猛的迅猛龙袭击的惨状，并向她的爱人保证自己目前平安。",kw={"探险者协会","麦琳·石纹","麦琳的信件","杂斑迅猛龙","塔雷尔·石纹","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="送达这封信为在湿地公路沿线守卫的联盟哨兵带来了重要的情报，也带来了一丝苦乐参半的安慰。",["race:Dwarf"]="这封信强调了探险者协会在卡兹莫丹危险的荒野中发掘古代历史所付出的沉重个人代价。"},sec={{t="来自废墟的急报",b="在湿地的维尔加挖掘场发掘巨大的史前化石和文物时，矮人探险队惊动了一窝凶猛的杂斑迅猛龙。野兽成群地涌入沟渠，屠杀了数名工人，并切断了幸存研究员的逃生之路。在混乱之中，麦琳·石纹写下了这封信，通知她身在米奈希尔港的丈夫塔雷尔：虽然挖掘场已经化为废墟，但她本人、勘察员维尔加和奥莫尔·铁衣设法躲在临时搭建的庇护所中幸存了下来。"}},faq={{q="是谁写了麦琳的信件？",a="这封信是由麦琳·石纹所写，她是一位参与了米奈希尔港以东湿地挖掘场考古探险的探险家。",al={"麦琳的信件作者","谁是麦琳"}},{q="这封信是寄给谁的？",a="信是寄给塔雷尔·石纹的，他正焦急地在米奈希尔港的桥上等待消息。",al={"麦琳的信件收件人","谁收到麦琳的信件"}},{q="挖掘队发生了什么事？",a="在挖掘巨大的化石骨骼时，考古队遭到了成群杂斑迅猛龙的伏击和围攻。许多矮人工人遇难，仅剩极少数幸存者躲在一个临时营地中。",al={"挖掘场发生了什么","为什么探险队失败了"}},{q="是谁帮助麦琳在袭击中幸存下来？",a="奥莫尔·铁衣英勇奋战，保护了麦琳和首席勘察员，使他们得以撤退并躲进掩体，而挖掘场的其他部分则沦陷在迅猛龙的爪牙之下。",al={"谁救了麦琳","奥莫尔·铁衣"}}},fx={bce088a8={q="麦琳的信件是什么？",a="麦琳的信件是一封由麦琳·石纹写下的紧急消息。她是湿地挖掘现场遭到迅猛龙袭击后的幸存者。信是写给她深爱的塔雷尔·石纹的，叙述了他们的挖掘队遭遇的灾难，并确认她、勘察员维尔加和奥莫尔·铁衣都侥幸逃过一劫。",al={"麦琳的信件","麦琳的信件是什么","麦琳的便笺"}},ded8799c={q="塔雷尔为什么想要麦琳的信件？",a="塔雷尔·石纹派你前往危险的沼泽，专门打探他爱人的消息，以及失踪的挖掘队员的下落。麦琳的信件确认她仍然活着，这对他至关重要；信中还详细讲述了挖掘现场的惨重损失，以及他们为躲避周围的迅猛龙而逃往何处。",al={"为什么要送交麦琳的信件","塔雷尔为什么想要这封信","麦琳信件的用途"}}},fp="15,177,25.470.0,26.142.0,31.112.0,37.193.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="基尔卡克钥匙的中部",s="基尔卡克钥匙的中部是一块破损的金属碎片，属于遭遇海难的侏儒海盗基尔卡克·旋杆。在他的船只在黑海岸沿岸沉没后，这一中心部分被当地的灰雾鱼人拾荒者夺走。",h="基尔卡克钥匙的中部是一块破损的金属碎片，属于遭遇海难的侏儒海盗基尔卡克·旋杆。在他的船只在黑海岸沿岸沉没后，这一中心部分被当地的灰雾鱼人拾荒者夺走。",kw={"发条装置","黑海岸","基尔卡克·旋杆","灰雾","基尔卡克钥匙的中部","鱼人","沉船"},ang={["profession:Engineering"]="这把钥匙是一个定制的机械组件，旨在为发条大副上弦和操作，即使在海盗手中也展示了经典的侏儒独创性。"},sec={{t="淤泥中的碎片",b="当基尔卡克·旋杆的船被狂暴的利齿龙拖入海底时，这名侏儒海盗翻滚着冲上岸，他最珍贵的财物在岩石浅滩上摔得粉碎。残骸中有一把专门为他的机械大副设计的发条钥匙。在大灾难中，这把钥匙断成了三个不同的碎片，散落在海滩上。虽然顶部和底部被沿海野兽带走，但中间部分引起了在黑海岸浪潮中游荡的灰雾鱼人的注意，他们很快将这块闪亮的金属碎片囤积在自己的营地和残骸堆中。"}},faq={{q="基尔卡克钥匙的中部有什么用途？",a="这是遭遇海难的海盗基尔卡克·旋杆在黑海岸沿岸所需的三个碎片之一。一旦与顶部和底部碎片重新组装，完整的钥匙将用于重新激活他的机械大副。",al={"基尔卡克钥匙的作用","基尔卡克钥匙中部的用途","为什么我需要这把钥匙"}},{q="这个钥匙碎片最后在哪里？",a="中间的碎片被灰雾鱼人部落搜刮走了。可以从在黑海岸海滩和沉船点游荡的灰雾袭击者、神谕者、织网者、潮汐猎人以及其他部落成员身上夺回。",al={"谁拥有中间的钥匙","哪里可以找到基尔卡克钥匙的中部","中间钥匙的掉落来源"}},{q="这把钥匙起初为什么会断裂？",a="基尔卡克的船在近海被好斗的利齿龙击沉了。当这名侏儒在破碎的残骸中被冲上岸时，钥匙撞击在海岸岩石上并断成了三块，随后被当地的拾荒者带走。",al={"钥匙是怎么断的","为什么它会分成碎片"}}},fp="22,150,22.474.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="米莉的葡萄",s="米莉的葡萄是指米莉·奥斯沃斯在北郡农场采摘并装在板条箱和木桶里的新鲜葡萄。当迪菲亚潜行者占领了这些农场时，收获的葡萄被遗弃了，面临着被盗贼偷走，或是被修道院卫兵踩烂的风险。",h="米莉的葡萄是指米莉·奥斯沃斯在北郡农场采摘并装在板条箱和木桶里的新鲜葡萄。当迪菲亚潜行者占领了这些农场时，收获的葡萄被遗弃了，面临着被盗贼偷走，或是被修道院卫兵踩烂的风险。",kw={"迪菲亚","艾尔文森林","葡萄","米莉·奥斯沃斯","米莉的葡萄","北郡修道院","北郡农场"},ang={["faction:Alliance"]="北郡普通农民所面临的威胁突显了暴风城的驻军力量是多么薄弱，使得普通公民不得不依赖过路的冒险者来守护他们的生计。",["race:Human"]="对于在北郡开启冒险之旅的人类来说，回收米莉的作物往往是他们首次直接接触到迪菲亚潜行者在本土领土上日益猖獗的无法无天行径。"},sec={{t="脆弱的收成",b="北郡山谷肥沃的土壤产出的葡萄，对当地酿酒师和修道院社区至关重要。收获季节到来时，米莉·奥斯沃斯在葡萄藤间忙碌，将新鲜的水果收集进储藏桶中。但一群戴着红色面具的武装强盗闯入了农场，暴力地打断了她的工作，迫使她丢下散落在田垄间的作物，逃回了修道院。"},{t="附带损害",b="虽然暴风城的卫兵守卫着山谷入口，但人力短缺使北郡变得脆弱。尽管驻军承诺会将迪菲亚潜行者赶出去，但米莉担心身穿重甲的卫兵与凶残的盗贼之间任何旷日持久的冲突，都会导致她的劳动成果毁于一旦。在这些葡萄被践踏或被当作补给品抢走之前将其收回，才能确保北郡这少有的和平收成不至于化为乌有。"}},faq={{q="什么是米莉的葡萄？",a="这是一批新鲜采摘并装入板条箱和木桶的葡萄，米莉·奥斯沃斯在迪菲亚暴徒占领北郡农场时不得不将其遗弃。",al={"米莉的葡萄","什么是收成","米莉·奥斯沃斯的葡萄"}},{q="为什么板条箱会被留在农场里？",a="迪菲亚强盗在米莉收获葡萄的过程中袭击了农场，迫使她不得不放弃作物，逃回北郡修道院寻求庇护。",al={"为何被遗弃","为什么米莉丢下了葡萄","为什么要丢下收成"}},{q="为什么北郡的卫兵不能收回这些收成？",a="北郡的卫兵因应对迪菲亚潜行者的入侵和当地威胁而疲于奔命。米莉还担心，即便卫兵赶走了强盗，他们沉重的靴子也会踩烂娇嫩的葡萄。",al={"为什么不是卫兵","为什么卫兵拿不到","暴风城卫兵北郡"}},{q="是谁在威胁这些作物？",a="闯入者是迪菲亚潜行者的暴徒，这是一个由亡命之徒和强盗组成的团体，在整个艾尔文森林造成了广泛的动荡。",al={"谁占领了农场","谁在攻击农场","农场强盗"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:miners-gear"] = {n="矿工装备",s="矿工装备包括了存放在银泉矿洞内的坚固矮人镐、铲以及挖掘工具。在一群害虫侵扰之后，矿工联盟指派探险者们在当地卫兵发起进攻之前取回这些贵重的器械。",h="矿工装备包括了存放在银泉矿洞内的坚固矮人镐、铲以及挖掘工具。在一群害虫侵扰之后，矿工联盟指派探险者们在当地卫兵发起进攻之前取回这些贵重的器械。",kw={"肮脏的爪子","狗头人","洛克莫丹","矿工装备","矿工联盟","巡山人卡尔·雷矛","银泉矿洞"},ang={["profession:Mining"]="每一个矿工都知道锻造精良的矮人铁器的价值；让高等级的镐和铲落入这些点蜡烛的拾荒者手中，被视为一场小型的悲剧。",["race:Dwarf"]="对于矮人来说，狗头人用它们肮脏的爪子触碰矮人的工艺品是无法容忍的侮辱，这足以成为立刻清空矿洞的理由。"},sec={{t="矿工联盟的补给品",b="当位于洛克莫丹北部的银泉矿洞矿产枯竭后，矿工联盟将这些安静的隧道改造成了存放采矿设备的地下仓库。不幸的是，居住在隧道里的狗头人迅速占领了该设施，抢走了存储的货物并在板条箱中筑巢。由于担心这些贵重的矮人装备会在巡山人发起的全面突袭中被损毁，或者被这些拾荒者糟蹋，联盟只能依靠勇敢的探险者们深入矿洞，将这些板条箱搬运到安全的地方。"}},faq={{q="什么是矿工装备？",a="矿工装备指的是属于矿工联盟的矮人挖掘工具板条箱——例如镐和铲——它们被存放在银泉矿洞干燥的隧道中。",al={"什么是矿工装备","矿工装备物品","洛克莫丹的矿工装备"}},{q="为什么装备会留在矿洞里？",a="在银泉矿洞的矿产枯竭后，矿工联盟将废弃的隧道改成了存储仓库。直到狗头人意外地侵入这些矿道之前，装备一直存放在那里。",al={"为什么装备在银泉矿洞","为什么把装备留在那里"}},{q="谁想要取回这些装备？",a="巡山人卡尔·雷矛代表矿工联盟协调这次回收行动。他希望在同伴们进军消灭狗头人之前挽救这些工具。",al={"谁想要矿工装备","谁需要这些装备","巡山人卡尔·雷矛的装备"}},{q="矿工装备在哪里可以找到？",a="这些装备被装在矿工联盟板条箱里，散布在银泉矿洞的矿道各处，该矿洞位于洛克莫丹的北部山丘，奥加兹岗哨的东边。",al={"矿工装备位置","在哪里找到矿工装备","矿工联盟板条箱位置"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="矿业工会会员卡",s="矿业工会会员卡曾经是月溪镇地下矿脉劳工所持有的身份证明。在一次导致矿道一侧坍塌的重大灾难后，这些代币如今散落在徘徊于黑暗矿道中的不安的骷髅尸骸身上。",h="矿业工会会员卡曾经是月溪镇地下矿脉劳工所持有的身份证明。在一次导致矿道一侧坍塌的重大灾难后，这些代币如今散落在徘徊于黑暗矿道中的不安的骷髅尸骸身上。",kw={"坍塌","收集回忆","死亡矿井","矿业工会会员卡","月溪镇","骷髅矿工","暴风城","工会会员卡"},ang={["faction:Alliance"]="回收这些遗失的代币能让暴风城王国中那些从未得知亲人真正下落的家庭得到慰藉。",["profession:Mining"]="对于勘探者和挥舞镐头的工人们来说，这些卡片是对地下坍塌和管理不善的矿井所带来致命风险的残酷提醒。"},sec={{t="深处的悲剧",b="在迪菲亚潜行者完全控制月溪镇很久之前，劳工们曾在矿工工会的旗帜下在地下辛勤劳作，为王国开采贵重矿石。然而一场严重的矿道坍塌摧毁了主要矿井，数十名工人被困在数吨重的岩石下丧生，一切随之终结。这些死难者并未获得安宁的墓穴，而是化作了骷髅矿工、挖掘者和爆破手重新站起。他们骨质口袋中紧紧攥着的工会会员卡成了他们身份唯一的遗存，在暴风城的幸存同事们正设法找回这些卡片，希望能给悲痛的家属一个交代。"}},faq={{q="什么是矿业工会会员卡？",a="这是一张属于曾经在月溪镇矿井开采的工会成员的官方身份证明。幸存的工人们使用这些卡片来确认谁在地下灾难中丧生。",al={"什么是工会会员卡","矿工卡","工会会员卡"}},{q="这些卡片来自哪里？",a="它们是从徘徊在月溪镇地下死亡矿井坍塌矿道中的亡灵劳工身上回收的，例如骷髅矿工、亡灵挖掘者和亡灵爆破手。",al={"在哪里能找到工会会员卡","谁掉落矿工卡","卡片掉落位置"}},{q="为什么矿工变成了亡灵？",a="一场毁灭性的坍塌将他们封死在深井之中。究竟是什么原因让他们变成了亡灵尚不清楚；他们的遗骸如今正徘徊在月溪镇下方的坍塌矿道中。",al={"为什么有骷髅矿工","矿工是如何死亡的","死亡矿井亡灵"}},{q="谁想要取回这些卡片？",a="那些逃脱坍塌的幸存工友如今居住在暴风城，他们收集这些卡片以便通知死者的家属，让他们得到安息。",al={"谁接收工会会员卡","收集回忆任务发布者","上交工会会员卡"}}},fp="18,176,19.474.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:minshina-s-skull"] = {n="明希纳的颅骨",s="明希纳的颅骨中囚禁着暗矛巨魔明希纳的灵魂，他是加德林大师的兄弟。这颗颅骨被流亡的巫医扎拉赞困在回音群岛，成为了助长黑暗仪式魔法的可怖容器。",h="明希纳的颅骨中囚禁着暗矛巨魔明希纳的灵魂，他是加德林大师的兄弟。这颗颅骨被流亡的巫医扎拉赞困在回音群岛，成为了助长黑暗仪式魔法的可怖容器。",kw={"力量法阵","暗矛部族","回音群岛","加德林","明希纳","森金村","颅骨","扎拉赞"},ang={["faction:Horde"]="找回这颗颅骨是对扎拉赞在杜隆塔尔海岸外回音群岛上那扭曲统治的一次早期打击。",["race:Troll"]="对于暗矛部族来说，扎拉赞对明希纳的亵渎是对先祖传统的严重冒犯，因此找回他的颅骨成为了关乎部族荣誉的大事。"},sec={{t="被囚禁的灵魂",b="当扎拉赞夺取了回音群岛的控制权并驱逐了暗矛部族时，明希纳是其中被捕并遭到杀害的受害者之一。这位背叛者巫医并没有让他的猎物安然死去，而是将明希纳的灵魂禁锢在他自己被砍下的颅骨中。这颗颅骨被放置在群岛最南端一个邪恶的力量法阵内，成为了魔法奴役的纽带。加德林大师在梦中受到兄弟痛苦呼唤的指引，寻求勇敢的旅行者前往被占领的岛屿，找回这件圣物，并粉碎扎拉赞对他兄弟灵魂的控制。"}},faq={{q="明希纳是谁？",a="明希纳是一名暗矛巨魔，也是森金村加德林大师的兄弟。他在回音群岛扎拉赞叛乱引发的动荡中被谋杀。",al={"明希纳背景故事","明希纳是谁","加德林大师的兄弟"}},{q="为什么明希纳的灵魂会被困在他的颅骨里？",a="扎拉赞使用黑暗魔法直接将明希纳的灵魂束缚在他被砍下的头颅中。被囚禁的灵魂被安置在主岛上的一个仪式力量法阵内，无法前往先祖之地，只能被迫听命于扎拉赞。",al={"为什么要禁锢他的灵魂","扎拉赞颅骨仪式","灵魂禁锢在颅骨中"}},{q="这颗颅骨在哪里？",a="这颗颅骨位于回音群岛最大、最南端的岛屿上。它坐落在一座小山顶上，周围环绕着法阵、蜡烛、仪式标记以及其他被扎拉赞的奴仆守护着的颅骨。",al={"明希纳的颅骨在哪里","力量法阵位置","回音群岛颅骨位置"}},{q="把这颗颅骨带给加德林大师会发生什么？",a="将颅骨归还给森金村的加德林大师可以破除黑暗的咒语。随着邪恶束缚的解除，明希纳的灵魂形态会短暂显现，他将鞠躬致谢，随后平静地前往先祖之地。",al={"解放明希纳","加德林颅骨任务奖励","明希纳会怎样"}}},fp="16,225,16.509.0,17.143.0,44.219.0,27.188.0,56.207.1"}
P.entries["item:mirror-lake-water-sample"] = {n="明镜湖水的样本",s="明镜湖水的样本是一瓶采集自艾尔文森林瀑布底部的淡水。这是由暴风城Mage Quarter的詹妮亚·坎农委托初级法师们收集的，用于调查改变后的奥术电流是否渗入了当地的水源。",h="明镜湖水的样本是一瓶采集自艾尔文森林瀑布底部的淡水。这是由暴风城Mage Quarter的詹妮亚·坎农委托初级法师们收集的，用于调查改变后的奥术电流是否渗入了当地的水源。",kw={"奥术污染","艾尔文森林","瓶子","詹妮亚·坎农","明镜湖","暴风城","水样","巫师圣殿"},ang={["class:Mage"]="采集样本是联盟法师在巫师圣殿训练期间的早期职责仪式，教会他们监测环境地脉并识别野生的魔法渗漏。"},sec={{t="测试艾尔文的湖水",b="在席卷全球的灾难性冲突扰乱了世界神秘通道的稳定轨道之后，暴风城巫师圣殿的法师们对残留的奥术干扰深感忧虑。詹妮亚·坎农指派有前途的学徒在位于Stormwind Gate西南方的明镜湖瀑布底部装满一个特制的瓶子。通过分析这份水样，法师们试图检测是否有游离的魔法污染渗入了周围民众所依赖的天然水道。"}},faq={{q="什么是明镜湖水的样本？",a="它是一瓶从艾尔文森林明镜湖瀑布中舀出的水，装在詹妮亚的瓶子中。初级法师们收集它，以便巫师圣殿可以检测是否存在魔法污染。",al={"明镜湖样本","水样物品","詹妮亚的水"}},{q="为什么詹妮亚·坎农想要这份水样？",a="艾泽拉斯各地最近发生的神秘动荡扰乱了稳定的魔法电流。詹妮亚·坎农担心游离的魔法能量可能正在改变自然环境并污染当地的饮用水。",al={"为什么要测试明镜湖","詹妮亚·坎农的目的","魔法污染水"}},{q="样本是在哪里采集的？",a="它是在艾尔文森林中，位于Stormwind Gate西南方的明镜湖瀑布底部采集的。",al={"哪里获取样本","明镜湖位置","样本瀑布"}},{q="如果水被发现受到魔法污染会怎样？",a="詹妮亚·坎农担心，如果地脉电流已经污染了水源，那么长期饮用明镜湖水的人可能会遭受不良的魔法影响。",al={"污染水的影响","明镜湖有毒吗"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="迷雾之纱号的保险箱",s="迷雾之纱号的保险箱是一个坚固的储物箱，静静地躺在黑海岸附近海域的一艘暗夜精灵船只“迷雾之纱号”的残骸之中。它装有船长的航海日志和个人物品，这些东西是在船只遭到沿海鱼人伏击并沉没时遗失的。",h="迷雾之纱号的保险箱是一个坚固的储物箱，静静地躺在黑海岸附近海域的一艘暗夜精灵船只“迷雾之纱号”的残骸之中。它装有船长的航海日志和个人物品，这些东西是在船只遭到沿海鱼人伏击并沉没时遗失的。",kw={"奥伯丁","黑海岸","高尔博德·钢手","保险箱","迷雾之纱号","鱼人","沉船","silver dawning"},ang={["faction:Alliance"]="找回这个箱子既是对牺牲船员的纪念，也为驻扎在奥伯丁、处境艰难的航海群体提供了帮助。",["race:NightElf"]="这位牺牲的船长是一位受人尊敬的暗夜精灵水手，找回他们的航海日志有助于让这一受人尊敬的灵魂在黑海岸的水域中安息。"},sec={{t="沉入深海",b="暗夜精灵船只“迷雾之纱号”在驶往奥伯丁的危险沿海水域中走向了终结。它与其姊妹船“Silver Dawning”一同遭到敌对鱼人的伏击，船只不堪重负，沉入了海底。船长在袭击中丧生，留下的航海日志和珍贵的个人物品被封存在了这个保险箱里。这个箱子静静地躺在被水淹没的船舱内，成为被那些造成灾难的生物所包围的阴郁战利品。"},{t="给船员以安息",b="对于成功抵达奥伯丁的幸存水手来说，船只和指挥官的损失依然是一道未愈的伤疤。高尔博德·钢手希望能找回迷雾之纱号的保险箱，这样船长的遗物就能得到妥善安置，使其得到安息。冒险进入被水淹没的废墟打捞箱子，为滞留在陆地上的悲痛幸存者带来了一丝慰藉。"}},faq={{q="迷雾之纱号的保险箱里装了什么？",a="保险箱里装有船长的航海日志和个人物品。船长在船只沉没时丧生，留在奥伯丁的幸存船员希望找回这些遗物，以纪念他们牺牲的领袖。",al={"迷雾之纱号保险箱的内容","保险箱里装了什么","箱子里有什么"}},{q="迷雾之纱号是怎么沉没的？",a="迷雾之纱号在驶往奥伯丁的水域中遭到了沿海鱼人的伏击。在这些生物的围攻下，船只沉没到了海底，与其同行的船只“Silver Dawning”一同葬身大海。",al={"船为什么会沉没","谁击沉了迷雾之纱号","迷雾之纱号发生了什么"}},{q="保险箱在哪里可以找到？",a="它位于奥伯丁以北、黑海岸附近的水下。储物箱就在沉没的迷雾之纱号那被水淹没的船体内，那里聚集了大量的鱼人。",al={"迷雾之纱号的保险箱在哪里","迷雾之纱号的位置","保险箱的位置"}},{q="谁想要找回这个保险箱？",a="奥伯丁的高尔博德·钢手代表幸存的船员寻找这个保险箱，希望能让牺牲的船长的记忆得到安宁与慰藉。",al={"谁要这个保险箱","谁发布的任务","高尔博德的保险箱任务"}}},fp="19,176,18.321.0,17.300.0,35.201.0,27.155.0,27.131.0,32.129.0"}
P.entries["item:mo-grosh-crystal"] = {n="莫格罗什水晶",s="莫格罗什水晶是莫格罗什食人魔在洛克莫丹东北部开采并囤积的稀有矿物。因其独特的炼金特性而备受珍视，是中和黑铁爆破材料的重要成分。",h="莫格罗什水晶是莫格罗什食人魔在洛克莫丹东北部开采并囤积的稀有矿物。因其独特的炼金特性而备受珍视，是中和黑铁爆破材料的重要成分。",kw={"黑暗威胁临近","辛德维尔","洛克莫丹","莫格罗什水晶","莫格罗什","巨石水坝"},ang={["profession:Mining"]="虽然是在食人魔领地深处挖掘出来的，但这些原始矿物标本在与有机试剂结合时表现出了独特的化学反应性。",["race:Dwarf"]="巨石水坝的防御取决于矮人的独创性，他们将一个食人魔氏族开采的宝藏变成了抵御黑铁背叛的保障。"},sec={{t="一种稀有的食人魔商品",b="莫格罗什食人魔躲在洛克莫丹东北部的岩缝中，从他们的要塞里挖掘出这些独特的晶体。虽然这些头脑简单的食人魔很少研究精细的冶金术，但莫格罗什水晶却是他们氏族中珍视的宝物，无论是普通的执法者、神秘的萨满，还是他们高大的首领，身上都带着这种东西。这种水晶相对少见，因此在莫格罗什要塞内属于被严密看管的财产。"},{t="应对黑铁威胁",b="当情报显示黑铁破坏者正密谋对付巨石水坝时，总工程师辛德维尔需要寻找莫格罗什水晶，以及潜伏者的毒液和鳄鱼人的眼泪。通过将这种结晶矿物与这些反应性试剂结合，矮人工程师们可以配制出一种特殊的化合物，能在山谷被淹没之前解除和拆除不稳定的黑铁炸药。"}},faq={{q="莫格罗什水晶来自哪里？",a="它们是由洛克莫丹东北部的莫格罗什食人魔开采并持有的。莫格罗什要塞内的任何氏族成员——包括神秘者、蛮兵、执法者和萨满——身上都可能带着这种水晶。",al={"莫格罗什水晶位置","哪里寻找莫格罗什水晶","谁掉落莫格罗什水晶"}},{q="这种水晶有什么用途？",a="巨石水坝的总工程师辛德维尔需要这种水晶来制备一种中和混合物。将其与潜伏者的毒液和鳄鱼人的眼泪混合后，可以用来拆除旨在破坏水坝的黑铁炸药。",al={"莫格罗什水晶有什么用","莫格罗什水晶的用途","为什么辛德维尔需要水晶"}},{q="为什么食人魔要开采这些水晶？",a="莫格罗什食人魔在他们要塞周围的山丘中开采这些水晶，即使在食人魔内部，这种水晶也是非常稀有的商品。食人魔自己用它们来做什么并没有记载。",al={"为什么食人魔有水晶","食人魔水晶背景故事"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="莫德尔碎片",s="莫德尔碎片是戈阿兹之石缺失的四块碎片之一，这件古老的泰坦圣物在湿地出土。它在维尔加挖掘场被发现，夹杂在圣物和松散的泥土中，上面刻有的古老泰坦文字对于解读一段被遗忘的预言至关重要。",h="莫德尔碎片是戈阿兹之石缺失的四块碎片之一，这件古老的泰坦圣物在湿地出土。它在维尔加挖掘场被发现，夹杂在圣物和松散的泥土中，上面刻有的古老泰坦文字对于解读一段被遗忘的预言至关重要。",kw={"ados","挖掘","戈阿兹之石","golm","莫德尔碎片","neru","上古之神","泰坦","湿地","维尔加"},ang={["faction:Alliance"]="联盟的旅行者协助勘察员维尔加勇敢地进入被占领的挖掘场，以便为铁炉堡保存宝贵的历史研究资料。",["race:Dwarf"]="对于矮人的探险者协会来说，找回像莫德尔碎片这样丢失的部件，对于破译泰坦遗产和揭开他们种族深厚的历史至关重要。"},sec={{t="戈阿兹之石的碎片",b="在凶猛的迅猛龙将探险者协会赶出他们在湿地的挖掘点之前，勘察员维尔加发掘出了戈阿兹之石——一块刻有古老泰坦文字的巨型石板。其译文在四处明显的缺口处戛然而止，掩盖了有关神圣计划和毁灭预言的警告。莫德尔碎片正是那四块丢失的碎片之一，当挖掘者被迫逃命时，它被遗弃在古老的圣物和翻开的土壤之中。"},{t="大地之下的秘密",b="将莫德尔碎片与Ados、Golm和Neru碎片重新组合，勘察员维尔加终于能够复原完整的碑文。翻译出的文字揭示了世界诞生之初令人震惊的传说，明确提到了“上古之神……被锁在大地之下”。这场在沼泽地中开始的简单考古发掘，反而暴露了锁在土壤之下的一场远古斗争的残余。"}},faq={{q="什么是莫德尔碎片？",a="它是一块从戈阿兹之石上断裂下来的铭文石片，这是一种在湿地的维尔加挖掘场发现的古老泰坦圣物。",al={"莫德尔碎片","什么是莫德尔","莫德尔圣物"}},{q="谁在寻找这块碎片？",a="勘察员维尔加，一名驻扎在迅猛龙出没的挖掘场边缘的探险者协会考古学家，为了补全石板上缺失的文字而寻找它。",al={"谁想要莫德尔碎片","维尔加碎片任务"}},{q="集齐全部四块碎片后会发生什么？",a="将莫德尔碎片与Ados、Golm和Neru碎片重新汇合，使勘察员维尔加得以修复戈阿兹之石。在读完完整的泰坦文字后，他发现了关于“上古之神……被锁在大地之下”的警告。",al={"戈阿兹之石完成","揭开过去的结局","戈阿兹之石上写了什么"}},{q="这块碎片在哪里可以找到？",a="它散落在米奈希尔港以东的湿地内的维尔加挖掘场中，隐藏在古老的圣物陶罐或松散的泥土中，由极具攻击性的迅猛龙守护着。",al={"莫德尔碎片位置","去哪找莫德尔"}}},fx={c1df2f2b={q="莫德尔碎片来自哪里？是谁制造的？",a="莫德尔碎片是戈阿兹之石的一部分。这件古老遗物是在湿地米奈希尔港以东的挖掘场发现的。石上刻有泰坦文字，是泰坦留下的遗物。泰坦在远古时代塑造了世界，并留下了关于其神圣计划和末日预言的神秘记录。",al={"莫德尔碎片的来源","谁制造了莫德尔碎片","莫德尔碎片来自哪里"}}},fp="13,184,25.444.0,25.334.1,26.167.0,33.180.0,50.181.1,28.198.0"}
P.entries["item:moldy-tome"] = {n="发霉的书籍",s="发霉的书籍是一件受损的残片，包含了最初的《卡巴尔之书》的一半内容。它在希尔斯布莱德丘陵海岸的一场海难中遗失，书中记载着渴望掌握恶魔召唤术的术士们所梦寐以求的黑暗秘法。",h="发霉的书籍是一件受损的残片，包含了最初的《卡巴尔之书》的一半内容。它在希尔斯布莱德丘陵海岸的一场海难中遗失，书中记载着渴望掌握恶魔召唤术的术士们所梦寐以求的黑暗秘法。",kw={"碧玉矿洞","地狱犬","希尔斯布莱德","发霉的书籍","南海镇","破损的手稿","卡巴尔之书","术士"},ang={["class:Warlock"]="找回这本湿透的魔典，是那些寻求拼凑出奴役地狱犬所需仪式的术士们必须经历的关键仪式。"},sec={{t="迷失在浪潮中",b="《卡巴尔之书》曾是一部珍藏在洛丹伦王国、独一无二且无法替代的黑暗艺术论著。在它那模糊不清的历史中，这部魔典曾惨遭毁坏，被一分为二。现在被称为“发霉的书籍”的这一部分当时正由船只运往南方的米奈希尔港和铁炉堡。这艘船从未抵达目的地，在南海镇以西险恶的水域中沉没。这半本残卷被冲上了碧玉矿洞以南的岸边，在希尔斯布莱德海岸游荡的鱼人抢掠者中，受潮且破损不堪。"},{t="重获黑暗著作",b="尽管羊皮纸已经发霉腐烂，但发霉的书籍仍保留着强大的恶魔知识。黑暗艺术的修行者们在铁炉堡的克罗姆·粗臂或幽暗城的约拉·安尼森等导师的指引下，勇敢地深入沿海营地寻找它。与在千针石林的尘封洞穴中找到的另一半——破损的手稿合二为一后，这本修复后的著作提供了召唤并奴役地狱犬所需的精确咒语。"}},faq={{q="发霉的书籍是什么？",a="它是稀有的《卡巴尔之书》的一半，那是一部包含恶魔召唤仪式的神秘魔典。由于被水浸泡且腐烂，它是原书中在海难中幸存下来的那一部分。",al={"发霉的书籍","这是什么物品","发霉的书籍背景故事"}},{q="发霉的书籍最终流落到了哪里？",a="它被冲上了希尔斯布莱德丘陵的海岸，位于南海镇以西，碧玉矿洞以南。它落入了当地海岸鱼人的手中，被囤积在他们的营地里。",al={"发霉的书籍位置","发霉的书籍在哪里","如何找到发霉的书籍"}},{q="为什么这本书会在船上？",a="最初保存在洛丹伦，这一部分被装上一艘开往米奈希尔港的船，准备送交铁炉堡的学者。船只在希尔斯布莱德海岸沉没，未能完成航程。",al={"为什么它会在海上遗失","海难书籍","书籍运输"}},{q="怎样才能凑齐《卡巴尔之书》？",a="发霉的书籍必须与破损的手稿重新合并，那是这本书缺失的另一半，最终被带到了远处的千针石林的裂蹄堡中。",al={"书籍的另一半","缺失的书页","卡巴尔之书的组成部分"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:moonpetal-lily"] = {n="月牙百合花",s="月牙百合花是一种生长在泰达希尔的大型发光植物，盛开在淡水池塘周围。它们因其强大的恢复特性而闻名，其花瓣被视为天然药物和治疗药剂的关键成分。",h="月牙百合花是一种生长在泰达希尔的大型发光植物，盛开在淡水池塘周围。它们因其强大的恢复特性而闻名，其花瓣被视为天然药物和治疗药剂的关键成分。",kw={"奥达希尔","解毒剂","迪兰妮亚·月光","埃沃隆","月牙","月牙百合花","幽影谷","泰达希尔"},ang={["profession:Herbalism"]="虽然在紧急危机中可以直接手工采集，但月牙百合花清楚地展示了泰达希尔丰富的植物恢复潜力。",["race:NightElf"]="对于在幽影谷训练的年轻卡多雷来说，学习像月牙百合花这样的本地植物的恢复特性，是学习与自然和谐相处的重要早期课程。"},sec={{t="池塘植物",b="月牙百合花只生长在淡水池塘潮湿的岸边，尤其喜欢生长在奥达希尔西北部的幽影谷。像在这棵新世界之树上繁茂生长的许多植物一样，它们吸收了泰达希尔隐秘林地的独特精华。它们宽大的花瓣柔和而璀璨，在平静的水边很容易被发现，那里的天然水分让它们得以茁壮成长。"},{t="天然解毒剂",b="暗夜精灵治疗者和草药师非常看重月牙百合花，因为它具有非凡的治疗功效。当与森林中的其他植物（例如Hyacinth Mushrooms）结合使用时，这种百合花可以作为一种强效的舒缓和稳定剂。这种恢复特性使其成为酿造解毒剂以抵消致命毒素（特别是潜伏在黑丝洞中的树林蜘蛛所产生的剧毒）的重要成分。"}},faq={{q="月牙百合花生长在哪里？",a="它们生长在泰达希尔的奥达希尔西北部、幽影谷内的两个淡水池塘岸边。",al={"哪里能找到月牙百合花","月牙百合花位置","百合花地点"}},{q="月牙百合花有什么用途？",a="这种百合花具有显著的恢复和治疗特性。在幽影谷，迪兰妮亚·月光将它们与Hyacinth Mushrooms和树林蜘蛛的脓液结合使用，来酿造一种针对蜘蛛毒液的强效解毒剂。",al={"月牙百合花用途","月牙百合花的作用"}},{q="谁需要用这种百合花制作的解毒剂？",a="一位名叫埃沃隆的暗夜精灵在黑丝洞附近被树林蜘蛛咬伤中毒，需要用月牙百合花调制的解毒剂才能活下去。",al={"解毒剂是给谁用的","埃沃隆中毒"}},{q="月牙百合花可以在泰达希尔之外采集吗？",a="它们直接与泰达希尔隐蔽的池塘相关联，并且在幽影谷的庇护林荫中广为人知。",al={"百合花在其他地方生长吗","月牙百合花其他区域"}}},fx={["1aae6896"]={q="月牙百合花是什么？",a="月牙百合花是一种大型水生花卉，原生于泰达希尔宁静的水域。它以强效的天然治疗能力而闻名，常生长在阴凉林间水池和池塘边潮湿的土壤中，例如幽影谷奥达希尔附近的水池。",al={"月牙百合花是什么","月牙百合花信息","关于月牙百合花"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="月夜猛虎的牙齿",s="月夜豹尖牙是从在黑海岸迷雾森林中徘徊的掠食性月夜豹身上获取的锋利犬齿。协助维兹班恩·曲针维护其自动采样设备的旅行者们会收集这些尖牙。",h="月夜豹尖牙是从在黑海岸迷雾森林中徘徊的掠食性月夜豹身上获取的锋利犬齿。协助维兹班恩·曲针维护其自动采样设备的旅行者们会收集这些尖牙。",kw={"嗡鸣箱323型","黑海岸","月夜豹","月夜猛虎的牙齿","影爪","维兹班恩·曲针"},ang={["class:Hunter"]="击败月夜豹需要保持敏锐的感官，以防范那些自然融入海岸昏暗树冠中的伏击掠食者。",["race:Gnome"]="维兹班恩·曲针古怪的远程通讯设备展现了典型的侏儒工程学，尽管他含糊不清的言语和奇异的采样选择令人侧目。"},sec={{t="研磨装置",b="月夜豹是潜伏在黑海岸森林边缘的隐秘剑齿猫科动物，在阴影笼罩的松树间跟踪猎物。它们修长的尖牙是强大的狩猎武器，能够切开血肉和骨头。然而，对于古怪的侏儒技师维兹班恩·曲针来说，这些牙齿有着完全不同的机械用途。他的自动装置“嗡鸣箱323型”位于奥伯丁以北靠近桥梁的地方，其校准功能专门用于将这些坚硬的尖牙研磨成粉末，这是他古怪生态调查的一部分。"}},faq={{q="月夜豹尖牙从何而来？",a="它们是从黑海岸当地的各种月夜豹身上采集的，包括月夜豹幼崽、成年月夜豹、月夜豹之父、月夜豹族母以及被称为影爪的难以捉摸的潜行者。",al={"哪里获得月夜豹尖牙","谁掉落月夜豹尖牙","尖牙来源"}},{q="谁需要月夜豹尖牙？",a="侏儒工程师维兹班恩·曲针需要六颗这样的尖牙来喂给“嗡鸣箱323型”，这是一个位于奥伯丁以北靠近河桥的自动监控设备。",al={"谁需要尖牙","什么任务使用尖牙","嗡鸣箱323型上交"}},{q="尖牙在机器里会发生什么？",a="一旦放入“嗡鸣箱323型”，内部齿轮就会启动并立即将坚硬的尖牙研磨成细粉，以推进维兹班恩奇怪的实地实验。",al={"嗡鸣箱323型有什么用","为什么要研磨尖牙"}}},fp="16,145,20.318.0,37.126.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="月亮井水瓶",s="一瓶装满从奥伯丁月亮井中取出的圣水。其强大的净化自然魔法被用于测试并引发黑海岸东部山脊上一块神秘红色水晶的反应。",h="一瓶装满从奥伯丁月亮井中取出的圣水。其强大的净化自然魔法被用于测试并引发黑海岸东部山脊上一块神秘红色水晶的反应。",kw={"当水流过时","奥伯丁","黑海岸","空水瓶","费伍德森林","月亮井水瓶","红色水晶"},ang={["class:Druid"]="德鲁伊们认为月亮井水是自然平衡的重要载体，非常适合抵消非自然的腐化。",["race:NightElf"]="使用月亮井的圣水来探查外来的腐化，体现了卡多雷对艾露恩恩典的依赖，以此揭示隐藏的真相。"},sec={{t="净化之水容器",b="月亮井水瓶中装满了直接取自奥伯丁月亮井的液体，浸润着艾露恩的赐福能量。月亮井是暗夜精灵定居点的神圣魔法和纯净能量储备库，即使是小小一瓶，其对于腐蚀或未知神秘现象也具有显著的效力。"},{t="调查红色水晶",b="这个水瓶是专门为了测试黑海岸东部悬崖边出现的一块巨大的异界红色水晶而准备的。由于费伍德森林那腐化的山巅就在高墙之上，研究人员担心这块深红色的结构有着邪恶的来源。当圣水流过水晶的切面时，魔法会迫使不透明的晶体短暂变得透明，从而揭示出锁在内部的嗡鸣奥秘。"}},faq={{q="水是从哪里取来的？",a="这些水直接取自位于黑海岸西海岸的暗夜精灵避难所奥伯丁的神圣月亮井。",al={"我在哪里灌满水瓶","水瓶来源","奥伯丁月亮井水"}},{q="为什么要用月亮井水测试红色水晶？",a="月亮井水蕴含着浓郁的自然和月亮魔法。将其倾倒在怪异的红色水晶上可以测试其神秘成分，引发一种空灵的反应，使不透明的矿物表面瞬间变得透明。",al={"为什么要用月亮井水","水瓶的用途","水有什么作用"}},{q="为什么研究人员对水晶感到担忧？",a="这块水晶正好位于毗邻费伍德森林的东部山脉之下。考虑到费伍德森林深重的恶魔污染，学者们担心这个异界结构可能是那种腐化蔓延至黑海岸的延伸。",al={"为什么要测试水晶","红色水晶的危险","费伍德森林的联系"}}},fp="19,159,28.209.0,29.349.1,30.106.0,42.179.0,52.180.0"}
P.entries["item:mossy-tumor"] = {n="青苔之瘤",s="青苔之瘤是一种肮脏、有毒的赘生物，它长在泰达希尔那些被腐蚀的树木精怪的树皮和躯干上。这种赘生物主要出现在涌泉湖附近，它们预示着一种令人不安的邪恶力量正在这棵新生的世界之树中蔓延。",h="青苔之瘤是一种肮脏、有毒的赘生物，它长在泰达希尔那些被腐蚀的树木精怪的树皮和躯干上。这种赘生物主要出现在涌泉湖附近，它们预示着一种令人不安的邪恶力量正在这棵新生的世界之树中蔓延。",kw={"腐蚀","达纳苏斯","青苔之瘤","瑞利安·绿火","泰达希尔","树木精怪","涌泉湖"},ang={["class:Druid"]="对于致力于维护自然平衡的德鲁伊来说，看到像树木精怪这样的植物守护者长出有毒的肿瘤，是一个令人不安的迹象，说明泰达希尔出了大问题。",["race:NightElf"]="暗夜精灵种植泰达希尔是为了恢复他们与自然的联系，因此这种病变在他们的新家园迅速出现，是一个令人担忧的预兆。"},sec={{t="泰达希尔病症的征兆",b="泰达希尔的树木精怪原本是为了培育和照料这棵大树的枝叶而创造的，但如今许多树木精怪已变得充满敌意并染上了疾病。这些青苔之瘤就是这种内在病变的具体体现。这些赘生物蕴含着剧毒，在徘徊于涌泉湖的泥沼野兽、践踏者和古老树木精怪的躯体上四处蔓延。瑞利安·绿火和达纳苏斯的守护者们委托旅行者去切除这些赘生物，以便将它们彻底焚毁，防止毒素在岛屿的土壤中进一步扎根。"}},faq={{q="什么是青苔之瘤？",a="它是一种从受污染的树木精怪躯体上采集而来的病变赘生物。这些肿瘤充满了肮脏的毒素，表明泰达希尔的自然之灵正遭受着非自然的腐蚀。",al={"青苔之瘤","这个肿瘤是什么","树木精怪的肿瘤"}},{q="在哪里可以找到青苔之瘤？",a="它们是从在泰达希尔北部涌泉湖附近徘徊的受腐蚀树木精怪（例如树木精怪践踏者、泥沼野兽和古老树木精怪）身上采集到的。",al={"在哪里可以获得肿瘤","青苔之瘤掉落","树木精怪位置"}},{q="为什么瑞利安·绿火需要这些肿瘤？",a="瑞利安试图遏制泰达希尔所遭受的腐蚀。通过收集这些肿瘤并将其烧成灰烬，他确保了其中浓缩的毒素不会再次渗入土壤和水源中。",al={"瑞利安·绿火的肿瘤","为什么要焚烧肿瘤"}},{q="为什么树木精怪会染病？",a="一股黑暗的邪恶力量已经开始在泰达希尔蔓延，扭曲了它的看护者和野生生物。虽然暗夜精灵们正在积极调查疾病的真正来源，但那些长有明显肿瘤的树木精怪已被认定无法挽救。",al={"为什么树木精怪会生病","树木精怪腐蚀"}}},fp="11,215,33.459.0,22.159.0,31.161.0,46.195.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="山地狮的血液",s="山地狮的血液是一种从希尔斯布莱德丘陵的潜行掠食者和奥特兰克山脉的雪坡上收集的试剂。塔伦米尔的药剂师林度恩需要这种新鲜血液来配制皇家药剂师学会可怕的痛苦药剂。",h="山地狮的血液是一种从希尔斯布莱德丘陵的潜行掠食者和奥特兰克山脉的雪坡上收集的试剂。塔伦米尔的药剂师林度恩需要这种新鲜血液来配制皇家药剂师学会可怕的痛苦药剂。",kw={"奥特兰克","药剂师林度恩","痛苦药剂","希尔斯布莱德","山地狮的血液","皇家药剂师学会","塔伦米尔"},ang={["faction:Horde"]="在塔伦米尔附近采集野兽试剂可以直接加强部落在希尔斯布莱德对抗敌对人类据点的防御力量。",["race:Undead"]="收集的每一瓶血液都能帮助皇家药剂师学会开发毁灭性的生物武器，从而确保洛丹伦属于被遗忘者。"},sec={{t="丘陵试剂",b="在希尔斯布莱德和奥特兰克两侧的高地和丘陵上，游荡着野性而饥饿的山地狮。虽然普通的猎人为了毛皮和爪子而狩猎这些掠食者，但皇家药剂师学会的被遗忘者却看中了它们血管中流淌的东西。新鲜的山地狮血液拥有特殊的生物学特性，塔伦米尔的药剂师林度恩认为它可以作为一种强效新毒药的基础，专门用来给活人带来苦难。"},{t="助力新瘟疫",b="药剂师林度恩在塔伦米尔进行的实验直接服务于皇家药剂师学会的总体任务：完善被遗忘者的新瘟疫。通过采集活力充沛的野兽血液，林度恩试图提炼出他所谓的痛苦药剂，并测试当地的强效有机化合物如何被武器化，以对付黑暗女王的敌人。"}},faq={{q="山地狮的血液有什么用？",a="塔伦米尔的药剂师林度恩需要十瓶山地狮的血液来提炼一种致命的混合物，即痛苦药剂，这是皇家药剂师学会针对新型疾病研究的一部分。",al={"山地狮的血液有什么用","谁需要狮血","痛苦药剂 血液"}},{q="哪里可以收集到山地狮的血液？",a="它可以在希尔斯布莱德丘陵和邻近的奥特兰克山脉积雪峭壁上狩猎的山地狮身上采集到。",al={"哪里能找到山地狮的血液","山地狮的血液位置","哪些狮子掉落血液"}},{q="为什么药剂师林度恩特别需要野猫的血？",a="林度恩认为，这种具有攻击性且生命力顽强的山地狮的生命体液，为调制一种专门针对希尔斯布莱德活人居民、极其痛苦的毒药提供了理想的生物学基础。",al={"为什么需要狮血","为什么林度恩想要狮血"}},{q="山地狮的血液对炼金配方有用吗？",a="没用。它只是药剂师林度恩个人研究工作所需的实验性试剂，并非标准炼金专业技能的原料。",al={"炼金术师能用山地狮的血液吗","狮血是用于炼金的吗"}}},fx={dcf44a54={q="山地狮的血液是什么？",a="这是从在希尔斯布莱德丘陵和奥特兰克山脉崎岖山坡上游荡的山地狮身上采集的新鲜血液。它对普通炼金术士或工匠毫无用处，却具有皇家药剂师协会重视的生物特性，可用于致命的炼金实验。",al={"山地狮的血液是什么","山地狮血液的背景","这是什么血"}},["7c379830"]={q="山地狮的血液来自哪里？是谁制造的？",a="它并非经制作或加工而成，而是直接从洛丹伦北部土生土长的野猫身上采集的。游荡在希尔斯布莱德和奥特兰克之间高地上的山地狮，会被为驻扎在塔伦米尔的被遗忘者药剂师效力的代理人猎杀并放血。",al={"山地狮的血液来自哪里","山地狮血液的来源","谁制造了山地狮的血液"}}},fp="19,191,20.332.0,22.317.0,37.149.0,43.128.0,59.162.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="沾满泥污的日记书页",s="多年前，人们在暮色森林的一处凶案现场找到了沾满泥污的日记书页。书页已经破旧，沾满泥土，旅店老板斯密茨一直将它们留作一桩尚未侦破的本地案件的证据，但无法证明作者是谁。",h="多年前，人们在暮色森林的一处凶案现场找到了沾满泥污的日记书页。书页已经破旧，沾满泥土，旅店老板斯密茨一直将它们留作一桩尚未侦破的本地案件的证据，但无法证明作者是谁。",kw={"夜色镇","埃伯洛克","哈加德","沾满泥污的日记书页","斯密茨"},ang={["class:Rogue"]="拼凑被遗忘的笔迹样本和风化的日记残片，展示了在击倒隐藏的杀手之前所必需的有条不紊的法医调查工作。",["faction:Alliance"]="揭开暴风城贵族遇害背后的谜团，为暮色森林饱经战乱的定居点中这桩悬而未决的陈年旧案带来了迟来的了结。"},sec={{t="大屠杀的证据",b="在当前的危机笼罩暮色森林多年前，一群来访的贵族在荒野中惨遭杀害。旅店老板斯密茨陪同调查员哈加德来到血腥的现场，并从泥沼中抢救出了这些沾满泥污的日记书页。当时，镇上缺乏笔迹样本和确凿的记录，无法将文本直接与任何嫌疑人联系起来。斯密茨默默地将这些书页保留在夜色镇的旅店里，等待着一位调查员在南方王国各处发掘出足够的零散记录，从而将笔迹与居住在森林深处的隐居者联系起来。"}},faq={{q="这些沾满泥污的日记书页是在哪里发现的？",a="它们是多年前由旅店老板斯密茨和哈加德在暮色森林的树林中，一户来访贵族家庭被屠杀的现场发现的。",al={"斯密茨在哪里找到的书页","沾满泥污的书页来源","沾满泥污的日记位置"}},{q="为什么斯密茨最初发现这些书页时无法使用它们？",a="虽然这些书页是从犯罪现场找回的，但当地的调查员无法核实笔迹。由于没有可供比对的笔迹样本，镇上的守卫无法将这些书页与任何嫌疑人联系起来。",al={"为什么要保密这些书页","为什么斯密茨没有上交它们","斯密茨的证据问题"}},{q="谁需要查看这些书页？",a="必须将它们直接交给夜色镇守夜人指挥官阿尔泰娅·埃伯洛克，以便正式汇报针对来访贵族屠杀案调查的最终结果。",al={"我该把沾满泥污的书页交给谁","上交沾满泥污的日记书页","埃伯洛克 沾满泥污的书页"}},{q="这些书页关联到什么罪行？",a="它们关联到多年前在暮色森林的树林中，一群来访贵族被屠杀的案件，这是夜色镇当时一直未能查清的罪行。",al={"什么大屠杀","斯塔文做了什么","来访贵族被屠杀"}}},fx={["7e79311d"]={q="沾满泥污的日记书页是什么？",a="这些是沾满污渍、被撕破的日记页，多年前在暮色森林一场残酷的贵族惨案现场被发现。它们由斯塔文·密斯特曼托所写，记录了他堕落的过程，也提供了人们苦苦寻觅的书面证据，证明他曾在屠杀现场，并已陷入疯狂。",al={"沾满泥污的日记书页是什么","沾满泥污的日记书页","这个物品是什么"}},bcc5553e={q="沾满泥污的日记书页来自哪里？是谁写的？",a="这些书页由斯塔文·密斯特曼托写下，在那些贵族遭到谋杀时遗落在泥泞中。旅店老板斯密茨和哈格德调查这场血案时发现了它们，但斯密茨一直保留多年，因为他没有笔迹样本，无法确认书页的作者。",al={"谁写了沾满泥污的日记书页","泥污书页来自哪里","沾满泥污的日记书页的作者"}},f7c3dc88={q="指挥官埃伯洛克为什么需要沾满泥污的日记书页？",a="指挥官阿尔泰娅·埃伯洛克负责夜色镇的防务，在对森林中的威胁采取行动前，需要确凿证据。结合你在王国各处收集到的笔迹证据，这些书页足以确证斯塔文有罪，并促使守夜人终于对付他。",al={"为什么把书页交给埃伯洛克","谁想要沾满泥污的日记书页","泥污书页为什么重要"}}},fp="19,238,28.594.1,41.160.0,59.209.0,29.201.1,37.160.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="泥头花是生长在希尔斯布莱德丘陵的奈杉德哨岗的一种气味刺鼻、有毒的真菌。这种恶臭的蘑菇受到当地豺狼人的守卫，并被皇家药剂师学会收集，用于药剂师林度恩的药剂研究。",h="泥头花是生长在希尔斯布莱德丘陵的奈杉德哨岗的一种气味刺鼻、有毒的真菌。这种恶臭的蘑菇受到当地豺狼人的守卫，并被皇家药剂师学会收集，用于药剂师林度恩的药剂研究。",kw={"药剂师林度恩","苦痛药剂","希尔斯布莱德丘陵","mudsnout blossom","泥头豺狼人","奈杉德哨岗","塔伦米尔"},ang={["profession:Herbalism"]="虽然植物学家和草药师可能会因其名称而将其误认为是一种普通的花，但 Mudsnout Blossom 实际上是一种挥发性的、恶臭的真菌，受到毒理学家和黑暗炼金术士的青睐。",["race:Undead"]="被遗忘者广泛利用这种花的毒性，通过采集它来为皇家药剂师学会提炼生化武器。"},sec={{t="一种有毒真菌",b="尽管名字里带有花字，泥头花实际上是一种大型的、恶臭的蘑菇，主要在塔伦米尔以南的奈杉德哨岗那受污染的土壤中茁壮成长。它们生长在当地泥头豺狼人的营地之中，而这些豺狼人会拼死保卫这片领地。对于活体生物来说，这种蘑菇的孢子和菌肉是一种剧毒，会导致剧痛和快速的生物机体衰退。"},{t="皇家药剂师学会的原料",b="在塔伦米尔，药剂师林度恩寻找泥头花作为他化学实验的原材料。在 Sylvanas Windrunner 女士的授意下，皇家药剂师学会不懈地致力于研制一种能够根除天灾军团和活体人类的新瘟疫。这些蘑菇所具有的腐蚀性、能使血肉枯萎的特性，使其成为林度恩酿造臭名昭著的苦痛药剂的理想基础成分。"}},faq={{q="什么是 Mudsnout Blossom？",a="尽管被称为花，它实际上是一种大型的、气味刺鼻的有毒蘑菇，发现于希尔斯布莱德丘陵潮湿的土壤中。",al={"mudsnout blossom 背景知识","mudsnout blossom 是花吗","mudsnout blossom 是什么植物"}},{q="泥头花生长在哪里？",a="它们生长在整个奈杉德哨岗，这是一处位于塔伦米尔以南、南海镇河流以东的废弃农场。该地区充斥着大量的泥头豺狼人。",al={"mudsnout blossom 位置","哪里可以找到泥头花","奈杉德哨岗的蘑菇"}},{q="为什么皇家药剂师学会要收集它们？",a="塔伦米尔的药剂师林度恩需要它们来酿造苦痛药剂。被遗忘者正在研究毒素，以帮助制造一种能够消灭活体生物和天灾军团的新瘟疫。",al={"林度恩为什么需要泥头花","苦痛药剂原料","药剂师林度恩的蘑菇"}},{q="皇家药剂师学会用这些花做什么？",a="药剂师林度恩收集这些恶臭的蘑菇用于他的下一种药剂，作为被遗忘者对疾病和毒药研究的一部分。",al={"mudsnout blossom 实验","mudsnout blossom 药剂用途"}}},fx={f0998bd9={q="泥头花来自哪里？",a="泥头花是一种大型、气味恶臭的蘑菇，生长在希尔斯布莱德丘陵南部的奈杉德哨岗田野中。它们在当地泥头豺狼人居住的地方茁壮生长；豺狼人会凶狠地守护这片区域，不过它们究竟是有意栽培这些刺鼻的真菌，还是只是在其中筑巢，目前尚不确定。",al={"泥头花的来源","泥头花来自哪里","谁制作了泥头花"}}},fp="16,170,14.327.0,37.321.1,27.123.0,32.184.0,52.183.0,60.131.0"}
P.entries["item:mudsnout-composite"] = {n="泥头花药",s="泥头花药是由塔伦米尔的药剂师林度恩从采集的泥头花中调配而成的一种炼金药膏。它是一种必要的基底材料，需要运往幽暗城的药剂师区，供皇家药剂师学会用于新型瘟疫的研究。",h="泥头花药是由塔伦米尔的药剂师林度恩从采集的泥头花中调配而成的一种炼金药膏。它是一种必要的基底材料，需要运往幽暗城的药剂师区，供皇家药剂师学会用于新型瘟疫的研究。",kw={"apothecarium","药剂师林度恩","痛苦药剂","大药剂师法拉尼尔","mudsnout blossom","泥头花药","皇家药剂师学会"},ang={["profession:Herbalism"]="泥头花证明了即使是不起眼的本土植物，在药剂师老练的眼光下也能被压碎并武器化。",["race:Undead"]="每一批像这样的药剂都直接有助于实现黑暗女王的使命：通过开发一种摧毁生者与天灾军团的瘟疫，来确保被遗忘者的未来。"},sec={{t="衰败之基",b="这种精细的复合物由药剂师林度恩在野外制作，直接取自希尔斯布莱德丘陵采集的泥头花。虽然它本身就有毒性，但这种糊状物还需要一种由大药剂师法拉尼尔亲自调制的特殊衰败胶体，才能激活其更致命的特性。一旦结合，该混合物就构成了开发黑暗女王的痛苦药剂的关键化学成分。"},{t="药剂师信件",b="将药剂从塔伦米尔运送到幽暗城的药剂师区，体现了被遗忘者炼金术分散式、迭代式的特点。野外研究员不断收集区域试剂，并将样本送回首都供大师们精炼。尽管希尔瓦娜斯女士对针对活人与天灾军团的研究成果有着迫切的需求，但法拉尼尔仍称赞这种药剂是实现他们终极目标的巧妙基础。"}},faq={{q="泥头花药有什么用？",a="它是由泥头花制成的中间体药膏。它需要由幽暗城的大药剂师法拉尼尔用衰败胶体进行处理，以帮助调制痛苦药剂。",al={"泥头花药用途","泥头花药的作用"}},{q="是谁创造了这种药剂？",a="驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者研究员药剂师林度恩，在将其向北运送之前，压碎了新鲜花朵并混合成了这种药膏。",al={"谁制作了泥头花药","泥头花药创造者"}},{q="大药剂师法拉尼尔为什么需要它？",a="法拉尼尔负责监管皇家药剂师学会研制新型瘟疫的重大工作。林度恩的药剂提供了推进他们致命毒素研究所需的特定草药基底。",al={"为什么要带给法拉尼尔","法拉尼尔与泥头花"}}},fp="18,225,16.331.0,25.390.1,40.175.0,26.143.0,44.181.0"}
P.entries["item:mudsnout-mixture"] = {n="泥头花水",s="泥头花水是幽暗城的大药剂师法拉尼尔调制的一种剧毒炼金基剂。它是将泥头花药与一种腐蚀性炼金胶体混合而成，是皇家药剂师学会用来制造致命的苦痛药剂的基础。",h="泥头花水是幽暗城的大药剂师法拉尼尔调制的一种剧毒炼金基剂。它是将泥头花药与一种腐蚀性炼金胶体混合而成，是皇家药剂师学会用来制造致命的苦痛药剂的基础。",kw={"药剂师","腐蚀胶体","苦痛药剂","法拉尼尔","希尔斯布莱德","林度恩","泥头花水","幽暗城"},ang={["faction:Horde"]="在塔伦米尔工作的部落冒险者充当着信使和外勤特工的角色，他们将这些有毒的混合物运过洛丹伦，以巩固被遗忘者在希尔斯布莱德的立足点。",["race:Undead"]="这种混合物展现了皇家药剂师学会冷酷的独创性，将基础的荒野材料提炼成旨在消灭活人的化学武器。"},sec={{t="腐蚀胶体",b="当塔伦米尔的药剂师林度恩想要制造一种致命的新型生物武器时，他会收集一种基础泥头花药，即来自狗头人盘踞的奈杉德哨岗的毒蘑菇，并将其运往北方的幽暗城。大药剂师法拉尼尔对这种药剂的潜力印象深刻，于是他将自己调制的腐蚀胶体加入其中，制造出了极不稳定的泥头花水。这种溶液在稳定了蘑菇化合物的同时，也为其在山麓丘陵进一步的催化提纯做好了准备。"},{t="催化苦痛",b="虽然泥头花水本身药效强劲，但如果没有关键的催化剂来激活其污染因子，它就是惰性的。法拉尼尔会派遣信使将小瓶带回塔伦米尔，并附上一瓶强效巨魔之血药剂、毒刺纳迦鳞片以及撕鳍鱼人的眼睛。一旦经过林度恩的催化，这种混合物就会形成致命的苦痛药剂——这是一种旨在向被遗忘者的活人敌人们散布毁灭的招牌毒药。"}},faq={{q="泥头花水有什么用途？",a="它是苦痛药剂的中间化学基剂，苦痛药剂是塔伦米尔的药剂师林度恩正在完善的一种实验性毒药，用于屠杀被遗忘者的敌人。",al={"泥头花水用途","泥头花水的作用","泥头花水使用"}},{q="谁制造了泥头花水？",a="皇家药剂师学会的领袖、居住在幽暗城药剂师区的药剂师法拉尼尔，通过将未经处理的泥头花药与他自己的腐蚀胶体混合，制造出了泥头花水。",al={"谁制造泥头花水","泥头花水创作者"}},{q="为什么需要狗头人材料？",a="尽管名字如此，但其实并不需要。该药剂的成分来自泥头花，这是一种生长在奈杉德哨岗泥头花狗头人聚居地附近的毒蘑菇；药剂师林度恩会先将它们混合成药，然后法拉尼尔再加入他的腐蚀胶体。",al={"为什么叫泥头花","狗头人毒药背景"}},{q="这种混合物是如何激活的？",a="为了唤醒混合物中休眠的污染因子，药剂师林度恩需要一瓶强效巨魔之血药剂，以及在希尔斯布莱德海岸采集的毒刺纳迦鳞片和撕鳍鱼人眼睛。",al={"激活泥头花水","苦痛药剂试剂"}}},fp="16,158,18.472.0,20.410.1,38.169.0,33.128.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="鱼人的头颅",s="鱼人的头颅是从徘徊在希尔斯布莱德丘陵西部海岸的这种两栖生物身上割下的阴森战利品。南海镇的法尔林·奥里涅尔中尉需要这些战利品作为铲除威胁的实质证据，以满足他的上司治安官雷德帕斯。",h="鱼人的头颅是从徘徊在希尔斯布莱德丘陵西部海岸的这种两栖生物身上割下的阴森战利品。南海镇的法尔林·奥里涅尔中尉需要这些战利品作为铲除威胁的实质证据，以满足他的上司治安官雷德帕斯。",kw={"法尔林·奥里涅尔","法尔林的证明","希尔斯布莱德丘陵","治安官雷德帕斯","鱼人","鱼人的头颅","南海镇","西部海岸"},ang={["faction:Alliance"]="清理西部海岸保护了南海镇脆弱的渔业经济，并为洛丹伦一个脆弱的联盟据点确保了海岸线的安全。"},sec={{t="更恐怖的证据",b="南海镇四面受敌，但聚集在西部海岸的侵略性鱼人对当地渔民和沿海旅行者构成了直接威胁。虽然联盟的冒险者经常扫荡海滩以捕杀这些生物，但治安官Marcus Redpath在签署防御报告前要求无可辩驳的验证。为了应付官僚主义，法尔林·奥里涅尔中尉只能雇佣战士运回冰冷、滴着血的鱼人头颅——这是一项法尔林本人觉得极其恶心的任务，尤其是因为这种景象彻底破坏了他对南海镇当地海鲜的胃口。"}},faq={{q="为什么法尔林·奥里涅尔想要鱼人的头颅？",a="治安官Marcus Redpath对关于鱼人已被从海滩上清除的简单报告并不满意。为了确认威胁确实已减少，他要求提供实质证据，迫使法尔林中尉收集断头作为证明。",al={"法尔林的证据","为什么需要鱼人的头颅","南海镇谁想要鱼人的头颅"}},{q="这些鱼人在哪里被发现？",a="它们是从盘踞在西部海岸（即希尔斯布莱德丘陵南海镇以西的海岸线）的鱼人部落中收集的。",al={"鱼人的头颅位置","希尔斯布莱德鱼人头颅获取","西部海岸鱼人"}},{q="为什么法尔林对它们如此反感？",a="法尔林觉得会走路的鱼本身就不自然，令人作呕。看到黏糊糊、流着血的断头滴在地板上让他感到非常恶心，以至于他拒绝吃鱼，而鱼类是像南海镇这样的港口城镇的主要食物来源。",al={"法尔林的反应","法尔林吃鱼"}},{q="收集头颅能解决南海镇的鱼人问题吗？",a="这些头颅提供了治安官雷德帕斯所要求的证据。他接受了这些物品，然后指示法尔林将注意力转向东部海滩的威胁。",al={"鱼人会停止攻击吗","法尔林任务链"}}},fx={ab7abae9={q="什么是鱼人的头颅？",a="这是在希尔斯布莱德丘陵海岸被杀死的鱼人那颗刚砍下的头颅。它冰冷、黏滑，还渗着恶臭的液体，是在保卫南海镇时斩杀怪物的确凿物证。",al={"鱼人的头颅是什么","鱼人的头颅信息","鱼人的头颅物品"}},["598cfa24"]={q="鱼人的头颅从哪里来？",a="它们是从南海镇以西、西部海岸出没的鱼人身上直接砍下来的。这些不是制作出来的物品，而是从侵扰联盟驻军的海岸掠袭者身上取得的血腥战利品。",al={"鱼人的头颅在哪里掉落","谁制造了鱼人的头颅","鱼人的头颅来源"}}},fp="11,229,24.424.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="麝鼠根",s="麝鼠根是一种罕见的植物标本，只生长在湿地巨石水坝下方的巨大瀑布底部，潮湿的泥土中。它是隐藏在暴风城地下的一群邪教徒所配制药剂的关键成分。",h="麝鼠根是一种罕见的植物标本，只生长在湿地巨石水坝下方的巨大瀑布底部，潮湿的泥土中。它是隐藏在暴风城地下的一群邪教徒所配制药剂的关键成分。",kw={"贵族药剂","威肖克勋爵","麝鼠根","巨石水坝","蒂罗亚之泪","湿地","加尔德斯"},ang={["class:Warlock"]="对于在屠夫之羊地下活动的术士们来说，获得这种根茎对于让爱管闲事的贵族闭嘴，以及保护他们在城内脆弱的藏身处至关重要。",["profession:Herbalism"]="虽然它不是一种标准的贸易草药，但这种根茎展示了像巨石水坝底部这样的特定微气候如何孕育出独特且危险的植物。"},sec={{t="一种稀有的草药",b="麝鼠根生长在终年被薄雾笼罩、巨石水坝的瀑布倾泻而下的湿地地面上。由于其生长环境隐蔽且潮湿，采集难度极大。虽然普通草药师很少寻找这种植物，但某些黑魔法的修习者却因其强大的化学和炼金属性而对这种植物青睐有加。"},{t="术士的阴谋",b="在暴风城的街道之下，在被称为“屠夫之羊”的阴暗区域，黑爪加尔德斯正在寻找这种根茎以及蒂罗亚之泪。这些稀有的植物组合在一起，成为了一种精心调配的药剂的基础，旨在制服威肖克勋爵。这位贵族议会的成员已经开始插手城内隐藏的术士集会之事。"}},faq={{q="哪里可以找到麝鼠根？",a="麝鼠根只生长在湿地，位于巨石水坝下方的巨大瀑布底部。",al={"麝鼠根在哪里","麝鼠根位置","如何找到麝鼠根"}},{q="麝鼠根有什么用？",a="黑爪加尔德斯要求收集它和蒂罗亚之泪，用于配制一种药剂，目的是让威肖克勋爵无暇他顾，并阻止他推动对暴风城术士集会的调查。",al={"麝鼠根有什么用","麝鼠根的用途","我为什么需要麝鼠根"}},{q="谁想要采集这种根茎？",a="黑爪加尔德斯，一位居住在暴风城法师区屠夫之羊地下墓穴中的术士，指使代理人去获取它。",al={"谁需要麝鼠根","麝鼠根任务发布者","谁要求寻找麝鼠根"}},{q="威肖克勋爵是谁？",a="威肖克勋爵是暴风城贵族议会的一名成员，他发现了城内运作的术士集会，并开始游说议会进行正式调查。",al={"威肖克是谁","威肖克勋爵"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-fossil"] = {n="神秘的化石",s="神秘的化石是由勘察员雷姆塔维尔在黑海岸沿岸发掘出的一件古代标本。它奇特的特性引起了矮人探险者协会浓厚的兴趣，促使学者们将其跨海转运，以揭开其隐藏的秘密。",h="神秘的化石是由勘察员雷姆塔维尔在黑海岸沿岸发掘出的一件古代标本。它奇特的特性引起了矮人探险者协会浓厚的兴趣，促使学者们将其跨海转运，以揭开其隐藏的秘密。",kw={"黑海岸","探险者协会","弗拉冈特","杜瑟·灰须","米奈希尔港","神秘的化石","雷姆塔维尔"},ang={["faction:Alliance"]="这件遗物的转运凸显了连接联盟前哨站的重要后勤链条，将黑海岸的野外侦察兵与达纳苏斯和米奈希尔港的学者们联系在了一起。",["race:Dwarf"]="对于矮人来说，这块化石是探险者协会为拼凑古代泰坦遗产和发掘被遗忘的谜团而不懈努力的又一块缺失拼图。"},sec={{t="一次奇妙的发现",b="勘察员雷姆塔维尔在黑海岸的荒野海岸进行实地考察时，发现了一块与卡利姆多随处可见的普通石化石迥然不同的化石。雷姆塔维尔认为它具有重大的历史意义，因此安排将其送往矮人学者手中，而不是让它在荒野中被遗忘。当这件遗物被送到达纳苏斯的首席考古学家杜瑟·灰须面前时，它立刻显现出非同寻常的价值。"},{t="跨海的联系",b="首席考古学家杜瑟·灰须指出，这件标本与曾经在铁炉堡的一次探险者协会聚会上展出过的另一件罕见化石有着惊人的相似之处。那件早期的展品曾由考古学家弗拉冈特研究过，他怀疑这块石头蕴含着等待被唤醒的潜能。为了确认其起源并解锁其潜在的秘密，杜瑟·灰须指示信使将化石运过海洋，送交目前正在米奈希尔港的深水旅店等候转运的弗拉冈特手中。"}},faq={{q="神秘的化石是在哪里发现的？",a="这块化石是勘察员雷姆塔维尔在卡利姆多北部海岸进行实地考察时，在黑海岸发现的。",al={"化石位置","在哪里发现","化石起源"}},{q="为什么探险者协会想要这块化石？",a="探险者协会致力于研究古代文物和世界的起源。首席考古学家杜瑟·灰须认为该标本与考古学家弗拉冈特提出的研究有关，后者推测此类化石可能蕴含着可被解锁的力量。",al={"为什么矮人想要它","探险者协会的兴趣","化石的作用"}},{q="考古学家弗拉冈特是谁？",a="考古学家弗拉冈特是探险者协会的一名研究员。他以研究类似的石化遗物而闻名，目前正住在米奈希尔港的深水旅店，等待前往湿地韦尔加挖掘场的护送。",al={"弗拉冈特是谁","弗拉冈特的位置","弗拉冈特在哪里"}},{q="首席考古学家杜瑟·灰须是谁？",a="首席考古学家杜瑟·灰须是探险者协会驻达纳苏资深代表，负责监督矮人在整个卡利姆多北部的研究和考古工作。",al={"杜瑟·灰须","杜瑟·灰须是谁","达纳苏斯矮人考古学家"}}},fp="17,134,19.282.0,21.388.1,38.104.0,48.172.0,31.232.0,39.182.0"}
P.entries["item:nak-s-skull"] = {n="纳克的颅骨",s="纳克的颅骨是一个残酷的猎物战利品，从纳克身上割下。他是南贫瘠之地三个指挥战群的著名刺鬃野猪人指挥官之一。作为袭击者战败的证明，被俘的野猪人碎牙想要得到它，以报复残酷的部落背叛。",h="纳克的颅骨是一个残酷的猎物战利品，从纳克身上割下。他是南贫瘠之地三个指挥战群的著名刺鬃野猪人指挥官之一。作为袭击者战败的证明，被俘的野猪人碎牙想要得到它，以报复残酷的部落背叛。",kw={"贫瘠之地","内部背叛","陶拉祖营地","kuz","lok orcbane","碎牙","纳克","纳克的颅骨","野猪人","刺鬃"},ang={["faction:Horde"]="砍下像纳克这样的刺鬃军阀的头颅，可以减轻连接陶拉祖营地和十字路口的部落补给线的巨大压力。"},sec={{t="复仇的信物",b="从剃刀沼泽中崛起，由纳克、Kuz和Lok Orcbane组成的三人组对贫瘠之地的部落定居点和道路发动了恶毒的袭击。十字路口的守军并不知道，这些军阀策划的攻击比一般的部落冲突要狡猾得多。当刺鬃囚犯碎牙在陶拉祖营地被遗弃在笼子里等死时，他对复仇的渴望转向了他以前的同胞。碎牙要求纳克死亡的实质证明，并请求部落冒险者将这颗被割下的头颅连同他同伙的头颅一起带回来，以挫败南部袭击小队的锐气。"}},faq={{q="纳克是谁？",a="纳克是一位狡猾的刺鬃野猪人领袖，与Kuz和Lok Orcbane一起从剃刀沼泽中崛起。这三人共同指挥了针对南贫瘠之地各地部落旅行者和定居点的致命冲突和袭击。",al={"纳克是谁","纳克背景故事","纳克贫瘠之地"}},{q="谁想要纳克的颅骨？",a="这颗头颅是碎牙索要的，他是一个被关在陶拉祖营地木笼子里的被俘刺鬃野猪人。被自己的族人抛弃并任其自生自灭后，碎牙心怀怨恨，寻求对背叛他的领袖们进行血腥的复仇。",al={"谁想要这颗颅骨","纳克的颅骨交给谁","碎牙颅骨"}},{q="为什么碎牙想要他自己族人的头颅？",a="纳克、Kuz和Lok Orcbane背弃了碎牙，将他留在囚禁中等死。为了报复他们的背叛，碎牙通过揭露他们的行踪并要求将他们被割下的头颅作为他们灭亡的证明来协助部落。",al={"为什么背叛他的部落","碎牙的动机","为什么碎牙想要头颅"}},{q="收集纳克的颅骨有助于保护十字路口吗？",a="是的。根据碎牙的说法，纳克和他的同伙是刺鬃激进袭击背后的狡猾主谋，这些袭击给十字路口和中部贸易路线带来了压力。消灭他们对该部落的协同作战是一个毁灭性的打击。",al={"十字路口安全","阻止野猪人袭击"}}},fp="11,168,20.588.0,12.189.0,22.158.0,55.171.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="纳克罗什的头颅",s="纳克罗什的头颅是龙喉氏族酋长纳克罗什倒下的令人毛骨悚然的证据，他是沼泽地龙喉氏族的领袖。这件战利品由联盟冒险者获取，并被送交斯托菲队长，以确认威胁米奈希尔港的兽人威胁已被粉碎。",h="纳克罗什的头颅是龙喉氏族酋长纳克罗什倒下的令人毛骨悚然的证据，他是沼泽地龙喉氏族的领袖。这件战利品由联盟冒险者获取，并被送交斯托菲队长，以确认威胁米奈希尔港的兽人威胁已被粉碎。",kw={"斯托菲队长","酋长","龙喉","米奈希尔","纳克罗什","湿地"},ang={["faction:Alliance"]="将这件冷酷的战利品呈交给斯托菲队长可以确保米奈希尔港免受迫在眉睫的攻击，并能获得铁炉堡王国的重要青睐。",["race:Dwarf"]="龙喉氏族自第二次战争以来一直困扰着卡兹莫丹；带着酋长被砍下的头颅，为沼泽地的防御者们带来了期待已久的正义。"},sec={{t="决定性的一击",b="龙喉氏族在整个沼泽地构成了持续的危险，他们集结了部队和攻城武器，威胁着联盟港口米奈希尔港。在烧毁了他们的投石车之后，港口的防御关键就在于击杀纳克罗什酋长本人。砍下他的头颅为斯托菲队长和铁炉堡当局提供了确凿的证据，证明这位军阀对沼泽地的统治已被打破。"}},faq={{q="纳克罗什是谁？",a="纳克罗什是统领沼泽地内残余龙喉氏族的酋长，负责指挥针对附近联盟领土的袭击和战争行动。",al={"纳克罗什是谁","纳克罗什酋长"}},{q="谁想要纳克罗什的头颅？",a="负责指挥米奈希尔港防御的斯托菲队长需要这颗头颅作为酋长已死的实物证明，随后他会代表铁炉堡奖励这位勇士。",al={"谁收走头颅","纳克罗什头颅上交","在哪里上交纳克罗什的头颅"}},{q="为什么纳克罗什被列为刺杀目标？",a="纳克罗什指挥了威胁米奈希尔港的龙喉部队。通过摧毁他们的攻城武器并消灭他们的酋长，联盟旨在对该氏族在这一地区的势力造成重创。",al={"为什么要杀纳克罗什","为什么要击败纳克罗什"}}},fx={e464fcda={q="什么是纳克罗什的头颅？",a="这是纳克罗什酋长被砍下的头颅。他是指挥湿地龙喉氏族的军阀。这颗头颅是令人毛骨悚然却无可辩驳的证据，证明铁炉堡山地卫兵在当地最大的敌人终于被杀死了。",al={"纳克罗什的头颅是什么","纳克罗什的头颅物品","纳克罗什被砍下的头颅"}},["160e4c8d"]={q="纳克罗什的头颅来自哪里？是谁制造的？",a="你在湿地的龙喉营地击败纳克罗什酋长后，可以从他身上直接取得这颗头颅。它不是制作或制造出来的，而是从倒下的兽人酋长身上砍下，作为战利品和他死讯的凭证。",al={"纳克罗什的头颅来自哪里","如何获得纳克罗什的头颅","纳克罗什的头颅来源"}},ce210494={q="斯托菲队长为什么要纳克罗什的头颅？",a="斯托菲队长需要无可辩驳的证据，证明龙喉氏族的首领已经倒下。纳克罗什已死，他们的战争投石车也已被摧毁，斯托菲知道龙喉氏族很难恢复元气，米奈希尔港和湿地终于可以免受有组织的袭击。",al={"斯托菲为什么要纳克罗什的头颅","他们为什么要纳克罗什的头颅","纳克罗什的头颅有什么用"}}},fp="15,166,17.351.0,17.147.0,26.159.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="奈尔鲁碎片",s="奈尔鲁碎片是戈阿兹之石的四块古代雕刻石片之一，这是一件在湿地的维尔加挖掘场中发现的文物。它从被扰动的泥土中被挖掘出来，上面记载着一段泰坦楔形文字，详细描述了艾泽拉斯的远古历史。",h="奈尔鲁碎片是戈阿兹之石的四块古代雕刻石片之一，这是一件在湿地的维尔加挖掘场中发现的文物。它从被扰动的泥土中被挖掘出来，上面记载着一段泰坦楔形文字，详细描述了艾泽拉斯的远古历史。",kw={"挖掘","戈阿兹之石","松软的泥土","奈尔鲁碎片","勘察员维尔加","揭示过去","湿地"},ang={["race:Dwarf"]="对于探险者协会来说，找回像奈尔鲁碎片这样的石板残片，对于发掘泰坦秘密以及拼凑出矮人种族的起源至关重要。"},sec={{t="戈阿兹之石的碎片",b="在勘察员维尔加领导的矮人考古探险队发现戈阿兹之石后，它碎裂成了四块不同的残片：阿多斯、莫德、戈尔姆和奈尔鲁碎片。当迅猛龙群占领了挖掘场后，工作被迫中止，导致奈尔鲁碎片被遗弃在凶猛野兽出没的松软泥土之下。找回这块碎片对于拼凑石板至关重要，这将使矮人学者能够解读一份被遗忘的记录，其中幸存的文字提到了一个神圣计划和一则注定失败的预言。"},{t="阅读修复后的石板",b="一旦四块碎片拼凑好戈阿兹之石，勘察员维尔加就会继续翻译其上的泰坦文字。新解读出的文字讲述了被锁在大陆之下的上古之神。"}},faq={{q="什么是奈尔鲁碎片？",a="它是一块从名为戈阿兹之石的巨大文物上碎裂下来的古代石片。它是在矮人探险队在湿地挖掘时发现的，随后他们的挖掘场被迅猛龙占领了。",al={"奈尔鲁碎片背景故事","什么是奈尔鲁碎片","奈尔鲁石板碎片"}},{q="这块碎片在哪里能找到？",a="它散落在米奈希尔港以东的湿地内的维尔加挖掘场中，这里到处都是迅猛龙。它通常埋在松软的泥土下，或是隐藏在废弃的器物之中。",al={"哪里能找到奈尔鲁碎片","奈尔鲁碎片位置","如何获得奈尔鲁碎片"}},{q="当四块碎片集齐后会发生什么？",a="勘察员维尔加会将戈阿兹之石拼凑完整，这样他就可以继续翻译其上的泰坦文字，并调查其幸存文字所暗示的谜团。",al={"完整的戈阿兹之石","戈阿兹之石上写了什么","揭示过去任务结局"}}},fx={["1f660d59"]={q="奈尔鲁碎片来自哪里？是谁制造的？",a="这块碎片来自在湿地维尔加挖掘场出土的古老戈阿兹之石。石上的铭文使用泰坦文字，但现存的任务文本并未说明它的制作者。",al={"奈尔鲁碎片的来源","谁制造了奈尔鲁碎片","奈尔鲁碎片来自哪里"}},b6f45f31={q="勘察员维尔加为什么需要奈尔鲁碎片？",a="勘察员维尔加刚发掘出戈阿兹之石，挖掘场就被迅猛龙攻陷了；他发现铭文有四处明显断裂。他急需奈尔鲁碎片和另外三块残片来拼合石板，继续解读其中关于神圣计划和注定覆灭的预言。",al={"为什么要寻找奈尔鲁碎片","维尔加为什么需要奈尔鲁碎片","奈尔鲁碎片的用途"}}},fp="13,220,23.442.0,27.187.1,26.171.0,28.175.0,50.191.1"}
P.entries["item:nessa-s-collection"] = {n="尼莎的货物",s="在鲁瑟兰村，人们收集附近水域的鱼骨和鱼鳞，交由奥伯丁的莱尔德研究。尼莎的货物展现了泰达希尔根部周围水生生物的惊人个头。",h="在鲁瑟兰村，人们收集附近水域的鱼骨和鱼鳞，交由奥伯丁的莱尔德研究。尼莎的货物展现了泰达希尔根部周围水生生物的惊人个头。",kw={"奥伯丁","鱼骨","莱尔德","尼莎·影歌","尼莎的货物","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["race:NightElf"]="作为一名暗夜精灵，你可以从这批货物中看出泰达希尔周围的水域与大陆水域有何不同。"},sec={{t="世界之树的馈赠",b="尼莎·影歌住在泰达希尔山脚下的鲁瑟兰村。她收集鱼骨和鱼鳞，以比较岛上的海洋生物与卡利姆多大陆上的种类。大树周围水域捕获的鱼，个头大得惊人。尼莎将实物证据寄给了莱尔德，他是奥伯丁码头的一名鱼贩。包裹由鲁瑟兰村的角鹰兽管理员维斯派塔斯负责运送，也为泰达希尔日益焕发的生机提供了切实证据。"},{t="奇特的比较",b="在黑海岸，莱尔德发现这些标本的个头远超大陆上的同类。货物中有些鱼的下颚骨几乎是黑海岸原生鱼类的两倍大，鱼鳞则有握紧的拳头那么大。对于沿海的暗夜精灵来说，这批货物清楚地展现了泰达希尔周围水域与卡利姆多北部阴郁海岸的巨大差异。"}},faq={{q="尼莎的货物里装着什么？",a="货物中有鱼骨和鱼鳞，包括几乎是黑海岸原生鱼类两倍大的下颚骨，以及有握紧的拳头那么大的鱼鳞。这些鱼捕自鲁瑟兰村周围的水域。",al={"尼莎的货物内容","包裹里有什么","鱼骨包裹"}},{q="这批货物要寄给谁？",a="尼莎将货物寄给莱尔德。他是黑海岸奥伯丁码头的一名暗夜精灵鱼贩。",al={"谁收尼莎的货物","莱尔德是谁","送货地点"}},{q="尼莎为什么收集这些鱼类标本？",a="尼莎收集这些标本，是为了比较泰达希尔周围繁盛的大鱼与卡利姆多大陆上的海洋生物。",al={"为何寄送鱼骨","尼莎的鱼类比较","泰达希尔的馈赠缘由"}},{q="这批货物如何送到奥伯丁？",a="你将包裹交给鲁瑟兰村的角鹰兽管理员维斯派塔斯，由他安排包裹渡水前往奥伯丁，交给莱尔德。",al={"如何运送","维斯派塔斯运送","角鹰兽包裹"}}},fx={["6bde19ac"]={q="什么是尼莎的货物？",a="尼莎的货物是一包从鲁瑟兰村周边水域收集来的鱼骨和鱼鳞。它展现了泰达希尔世界之树根部繁盛的奇特海产，并被妥善包装，准备运过海洋送往卡利姆多大陆。",al={"尼莎的货物是什么","尼莎的货物","尼莎的货物物品"}},eb414ab6={q="尼莎的货物来自哪里？是谁收集的？",a="这批货物由居住在泰达希尔南部山脚下鲁瑟兰村的暗夜精灵尼莎·影歌收集。当地岛民渔夫捕获的鱼类个头大得惊人，她从中挑选了珍贵的标本，准备运往海外。",al={"谁收集了尼莎的货物","尼莎的货物来自哪里","尼莎货物的来源"}},d01c5154={q="谁需要尼莎的货物？",a="奥伯丁一位名叫莱尔德的鱼贩正等着这些标本，好对它们进行研究。尼莎希望将鲁瑟兰村渔获惊人的体型与活力同大陆上的鱼类作比较，而莱尔德也很想检查那些尺寸是平常两倍的颌骨，以及有拳头那么大的鳞片。",al={"莱尔德为什么要尼莎的货物","为什么要运送尼莎的货物","尼莎货物的用途"}}},fp="18,201,24.462.0,20.375.0,34.235.0,36.106.0,42.120.0,40.146.0"}
P.entries["item:nether-gem"] = {n="虚空宝石",s="虚空宝石是一块被来自澈水湖的一位神秘人物所托付的附魔奥术石。它被注入了魔法力量，充当长距离的媒介，使它的主人能够展现奥术投影，并与幽暗城的比索·埃斯沙德直接交流，尽管他们之间联系的全部本质仍未被揭示。",h="虚空宝石是一块被来自澈水湖的一位神秘人物所托付的附魔奥术石。它被注入了魔法力量，充当长距离的媒介，使它的主人能够展现奥术投影，并与幽暗城的比索·埃斯沙德直接交流，尽管他们之间联系的全部本质仍未被揭示。",kw={"比索·埃斯沙德","澈水湖","冈瑟尔·阿坎努斯","虚空宝石","浪子巫妖","幽暗城"},ang={["class:Mage"]="对于奥术修行者来说，虚空宝石展示了法师大师们如何通过魔法探知和投影幻象来跨越遥远的距离，而不必冒长途跋涉的风险。",["race:Undead"]="这块石头的交付标志着被遗忘者在外交上的一次重大胜利，使强大的冈瑟尔·阿坎努斯成为了对抗天灾军团和血色十字军的盟友。"},sec={{t="奥术沟通的媒介",b="虚空宝石由冈瑟尔·阿坎努斯在他位于澈水湖的孤岛上锻造或附魔，它是横跨提瑞斯法林地的神秘纽带。冈瑟尔凭借纯粹的意志力摆脱了巫妖王的控制，由于猜疑，他长期回避着新生的被遗忘者。在找回他遗失的法术书后，他将这颗宝石作为善意的表示委托给了一位使者。一旦被带到幽暗城Magic Quarter上方的比索·埃斯沙德处，这块石头就会将冈瑟尔的魔法幻象直接投射在法师公会领袖面前，为这位离群的法师与希尔瓦娜斯女士及被遗忘者结盟铺平了道路。"}},faq={{q="虚空宝石有什么用？",a="虚空宝石允许冈瑟尔·阿坎努斯与比索·埃斯沙德进行长距离交流。当比索在幽暗城向这块石头注入魔法时，它会投射出冈瑟尔的灵体幻象，使这两位强大的法师能够直接对话。",al={"虚空宝石用途","什么是虚空宝石","虚空宝石的作用"}},{q="谁制造了虚空宝石？",a="这颗宝石由冈瑟尔·阿坎努斯提供，他是一位居住在澈水湖某座岛屿上的强大死灵法师。在他遗失的法术书被归还后，他将其交给一位冒险者，让他送给他的老战友比索。",al={"谁制作了虚空宝石","虚空宝石的来源","冈瑟尔的宝石"}},{q="为什么虚空宝石对被遗忘者很重要？",a="它是成功将冈瑟尔·阿坎努斯纳入被遗忘者阵营的工具。冈瑟尔最初不信任其他亡灵，担心他们仍然是天灾军团的奴隶；这颗宝石使他能够与比索·埃斯沙德重新建立联系，并向希尔瓦娜斯女士宣誓效忠。",al={"虚空宝石为何重要","冈瑟尔与被遗忘者","被遗忘者的虚空宝石"}}},fp="10,178,29.612.1,28.214.0,27.175.1,50.227.1"}
P.entries["item:ng-5"] = {n="NG-5",s="NG-5是硝化甘油的一种简写，这是一种以极其不稳定而著称的化合物。它是在石爪山脉为侏儒技师加克希姆·尘链所采购的，是其爆炸工程计划中不可或缺的催化剂。",h="NG-5是硝化甘油的一种简写，这是一种以极其不稳定而著称的化合物。它是在石爪山脉为侏儒技师加克希姆·尘链所采购的，是其爆炸工程计划中不可或缺的催化剂。",kw={"炸药","爆炸物","加克希姆·尘链","侏儒","ng-5","ng5","硝化甘油","石爪"},ang={["profession:Engineering"]="工程师们会认出NG-5就是硝化甘油，这是一种喜怒无常的化学催化剂，深受技师们的推崇，特别是在普通黑火药缺乏引爆重型军械所需的威力时。",["race:Gnome"]="使用不稳定的化学溶液炸掉整车的炸药来制造简单的干扰，这是典型的、高风险的侏儒式解决问题的方法。"},sec={{t="一种不稳定的试剂",b="NG-5的正式名称是硝化甘油，这是一种极其危险的化学溶液，必须在极端谨慎的情况下——或者以侏儒那种鲁莽的热情——进行处理。驻扎在石爪山脉的特工加克希姆·尘链需要这种物质作为关键的引燃化合物。据加克希姆所说，NG-5能提供引爆整车炸药所需的精确反应，从而制造一场大规模爆炸，作为他在该地区对抗敌人时所使用的混乱干扰手段。"}},faq={{q="什么是NG-5？",a="NG-5代表硝化甘油，这是一种高度不稳定且易挥发的化学混合物，主要用作高级爆破和侏儒工程学中的爆炸引燃试剂。",al={"什么是ng5","什么是硝化甘油","ng 5物品"}},{q="谁需要NG-5，为什么？",a="石爪山脉的侏儒工程师加克希姆·尘链需要这种化学品。它是可靠地引燃几车炸药的关键成分，目的是制造一场壮观的干扰。",al={"谁需要ng-5","加克希姆·尘链 ng-5","为什么要找ng5"}},{q="处理NG-5危险吗？",a="极其危险。供应商告诫送货人必须绝对小心地处理这种化合物，并开玩笑说，任何非加克希姆盟友的人如果不小心，最终很可能会把自己炸得粉身碎骨。",al={"ng5安全吗","ng-5炸药","ng5会爆炸吗"}}},fx={["43a87313"]={q="NG-5来自哪里？是谁制造的？",a="NG-5又名硝基甘油醚，是从加克希姆·尘链的一位熟人那里取得的；此人专门调制特殊化合物。它是一种极不稳定的炼金混合物，专为爆炸反应调制。对方交出药剂时再三警告：毫无戒心的信使很容易被炸得粉身碎骨。",al={"谁制造了ng-5","在哪里可以获得ng-5","ng-5的制造者"}}},fp="4,215,18.402.0,13.141.0,23.180.0,28.182.0"}
P.entries["item:nida-s-necklace"] = {n="希拉里的项链",s="希拉里的项链是一件珍贵的童年纪念品，遗失在赤脊山止水湖的湖面之下。这件小饰品是希拉里的父亲送给年幼的她的，后来在湖畔镇的孩子们在码头钓鱼时掉进了浑浊的湖水中。",h="希拉里的项链是一件珍贵的童年纪念品，遗失在赤脊山止水湖的湖面之下。这件小饰品是希拉里的父亲送给年幼的她的，后来在湖畔镇的孩子们在码头钓鱼时掉进了浑浊的湖水中。",kw={"effsee","闪光的泥土","希拉里","止水湖","湖畔镇","nida","nida的项链","赤脊山","肖恩"},ang={["faction:Alliance"]="湖畔镇的守卫在应对周围的威胁时捉襟见肘，因此像帮助当地孩子找回遗失的纪念品这样的小善事，就落到了往来的联盟冒险者身上。"},sec={{t="迷失于深处",b="年幼的希拉里和她的朋友肖恩在湖畔镇的湖岸边钓鱼时，不小心把她珍贵的项链掉进了止水湖。这件传家宝是她父亲送的礼物，有着巨大的情感价值。对栖息在深处的凶猛野兽和好斗的鱼人的恐惧使当地的孩子们只能待在码头上，项链也就沉没并埋在湖底的淤泥中，直到有冒险者愿意潜入浑浊的水中将其寻回。"}},faq={{q="这条项链是谁的？",a="这条项链属于希拉里，一个住在赤脊山湖畔镇的小女孩。这是她父亲送给她的特别礼物。",al={"谁拥有项链","nida项链拥有者","这是谁的项链","希拉里项链拥有者"}},{q="项链是怎么掉进止水湖的？",a="希拉里和她的同伴肖恩那天在水边钓鱼，项链不慎滑落并沉入湖底，埋进了一堆闪光的泥土里。",al={"它如何掉进湖里","为什么项链在水里","项链是如何丢失的"}},{q="为什么孩子们没有潜水下去找回它？",a="他们的父母严禁他们在止水湖中游泳。深水区潜伏着危险的水生捕食者和好斗的鱼人，这对当地居民构成了致命的威胁。",al={"为什么nida没有潜水去拿","为什么肖恩拿不到项链","为什么希拉里没有潜水去拿"}},{q="Effsee是谁？",a="Effsee是希拉里的宠物猫，它一直陪伴在湖畔镇的主人身边，并和它的小主人一起高兴地迎接项链的失而复得。",al={"那只小猫是谁","nida的猫","希拉里的猫"}}},fx={a22bd4db={q="希拉里的项链是从哪里来的？",a="这条项链是希拉里父亲送给她的礼物。它虽没有多少历史或魔法价值，却是送给湖畔镇一名小女孩的珍贵传家纪念物。",al={"谁制造了希拉里的项链","希拉里的项链来自哪里","谁把项链送给了希拉里"}},["14f3017c"]={q="为什么有人在寻找希拉里的项链？",a="希拉里在止水湖的码头附近钓鱼时弄丢了项链。她的父母不许孩子潜入怪物横行的湖水中，因此她的朋友肖恩请路过的冒险者冒险潜入湖底，替她找回这件珍贵的纪念品。",al={"为什么要找希拉里的项链","谁想要希拉里的项链","希拉里为什么想找回项链"}}},fp="17,207,18.316.0,33.121.0,46.102.0,47.157.0,14.123.0"}
P.entries["item:nightmare-shard"] = {n="噩梦碎片",s="噩梦碎片是一件水晶遗物，由菲拉·古风在检查了从哀嚎洞穴中回收的一块被污染的发光的碎片后交给信使。它蕴含着翡翠梦境纯净而受到扰动的精华，承载着令人不安的幻象，促使达纳苏斯和雷霆崖的德鲁伊高层立即发出警报并保持秘密。",h="噩梦碎片是一件水晶遗物，由菲拉·古风在检查了从哀嚎洞穴中回收的一块被污染的发光的碎片后交给信使。它蕴含着翡翠梦境纯净而受到扰动的精华，承载着令人不安的幻象，促使达纳苏斯和雷霆崖的德鲁伊高层立即发出警报并保持秘密。",kw={"翡翠梦境","菲拉·古风","发光的碎片","哈缪尔·符文图腾","在噩梦中","玛斯雷·驭熊者","噩梦碎片","哀嚎洞穴"},ang={["class:Druid"]="对于德鲁伊来说，这块碎片揭示了一个令人胆寒的事实：他们的神圣庇护所翡翠梦境已不再未受腐化侵扰，这也证实了人们对纳拉雷克斯在哀嚎洞穴中命运的担忧。",["faction:Horde"]="这块碎片将严峻的消息直接带到了雷霆崖的长者高地，在那里，哈缪尔·符文图腾致力于巩固牛头人在更广泛的塞纳里奥兄弟会中的地位。"},sec={{t="一种腐化的幻象",b="当菲拉·古风检查在哀嚎洞穴深处出土的神秘发光的碎片时，她意识到其能量远比预想的要黑暗。该碎片并没有反映出翡翠梦境宁静的生命力，而是折射出一种扭曲、非自然的苦难——一场清醒的噩梦。出于对它所代表含义的恐惧，她将这种被污染的精华束缚进噩梦碎片中，并命令将其立即送往塞纳里奥议会的长者领袖手中，不得延误。"},{t="噤声的预兆",b="当碎片被送到长者高地的大德鲁伊哈缪尔·符文图腾或达纳苏斯的玛斯雷·驭熊者手中时，两位大师在凝视其深处时都表现出了震惊和沮丧。其中蕴含的幻象动摇了他们的镇定，证实了他们心中对于梦境本身已经出了大问题的悄然猜疑。由于不愿在公众中散布恐慌，德鲁伊们迅速没收了碎片，并告诫信使不得再谈论他们所见之事。"}},faq={{q="什么是噩梦碎片？",a="这是一块由菲拉·古风托付给冒险者的碎片，其中包含了从哀嚎洞穴中带出的一件神器里提取的翡翠梦境精华。它散发出的不是宁静的自然能量，而是一种黑暗、腐化的梦境幻象。",al={"什么是噩梦碎片","噩梦碎片背景故事"}},{q="谁制造了噩梦碎片？",a="菲拉·古风在分析了从哀嚎洞穴带回的发光的碎片后，将噩梦碎片交给了信使。她意识到了其本质的严重性和腐化程度，便嘱托信使将其直接送交德鲁伊高层进行研究。",al={"谁制造了噩梦碎片","碎片来自哪里"}},{q="为什么德鲁伊领袖们对此感到如此惊恐？",a="凝视这块碎片向哈缪尔·符文图腾和玛斯雷·驭熊者揭示了翡翠梦境正在被一场噩梦主动扭曲的事实。由于这一揭示可能引发的危险和潜在恐慌，两位长者立即封锁了进一步的讨论，并将此事严格限制在塞纳里奥议会的高层成员之间。",al={"为什么哈缪尔感到担忧","为什么玛斯雷要隐藏这块碎片"}},{q="这块碎片需要被送到哪里？",a="部落冒险者被要求将其送到雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾处，而联盟旅行者则需将其带给达纳苏斯塞纳里奥议会的玛斯雷·驭熊者。",al={"我要把碎片交给谁","噩梦碎片任务提交"}}},fp="15,229,18.344.0,12.388.1,28.252.0,32.225.0,43.240.1,42.207.0"}
P.entries["item:nightsaber-fang"] = {n="夜刃豹的牙齿",s="从游荡在泰达希尔荒野枝干上的掠食性夜刃豹身上获取的尖牙。虽然这是一种常见的狩猎战利品，但当地一些动机可疑的林地居民也将这些牙齿视为原始试剂来搜寻。",h="从游荡在泰达希尔荒野枝干上的掠食性夜刃豹身上获取的尖牙。虽然这是一种常见的狩猎战利品，但当地一些动机可疑的林地居民也将这些牙齿视为原始试剂来搜寻。",kw={"多兰纳尔","牙齿","夜刃豹","试剂","萨特","泰达希尔","赛恩·腐蹄"},ang={["class:Hunter"]="击杀一只夜刃豹并取下它的牙齿证明了你对荒野的基本掌握，尽管向腐化的林地生物提供野兽部位扭曲了狩猎的精神。",["race:NightElf"]="夜刃豹是艾露恩女神珍视的同伴和象征，为了一个背信弃义的萨特而猎杀这些神圣的掠食者是非常可耻的行为。"},sec={{t="狩猎战利品",b="夜刃豹是卡利姆多北部本土最致命的自然掠食者之一，因其敏捷、凶猛以及与艾露恩深厚的精神联系而受到暗夜精灵的尊崇。在泰达希尔巨大的树枝上，这些猫科野兽在树冠下的阴影中狩猎。击杀一只夜刃豹可以获得尖牙，这是猎人技巧无可辩驳的证明，尽管森林中一些令人不快的人物为了不太高尚的仪式目的而搜寻它们。"},{t="萨特之试剂",b="多兰纳尔定居点外潜伏着赛恩·腐蹄，这是一只欺骗性的萨特，专门猎杀那些急切且缺乏经验的旅行者。赛恩声称需要林地试剂，诱骗初出茅庐的冒险者去收集夜刃豹的牙齿，以及枭兽羽毛和树林蜘蛛丝。交出这些掠食性试剂直接帮助了这个骗子，他在收到后公然嘲笑那些天真的英雄。"}},faq={{q="夜刃豹的牙齿从哪里来？",a="夜刃豹的牙齿取自徘徊在泰达希尔荒野中的掠食性夜刃豹，特别是在多兰纳尔周围的森林中。",al={"哪里获得夜刃豹的牙齿","谁掉落夜刃豹的牙齿","夜刃豹的牙齿来源"}},{q="谁在泰达希尔想要夜刃豹的牙齿？",a="赛恩·腐蹄，一个徘徊在多兰纳尔外大路旁的萨特，他将这些牙齿作为交给路过冒险者的任务的一部分进行索取。",al={"谁需要夜刃豹的牙齿","夜刃豹的牙齿交还","谁购买夜刃豹的牙齿"}},{q="赛恩·腐蹄为什么要夜刃豹的牙齿？",a="赛恩声称他需要动物试剂来在森林中开展他的业务，但他对工作确切的本质保密，并以诱骗轻信的旅行者为他服务为乐。",al={"为什么赛恩想要牙齿","赛恩·腐蹄试剂目的","赛恩的要求动机"}},{q="赛恩在要牙齿的同时还要求哪些其他试剂？",a="除了两颗夜刃豹的牙齿外，赛恩还要求两根枭兽羽毛和两片树林蜘蛛丝。",al={"赛恩还需要什么","赛恩要求的物品","赛恩的其他试剂"}}},fp="15,129,18.325.0,17.308.1,36.112.0,41.98.0,45.140.1,58.112.0"}
P.entries["item:nissa-s-remains"] = {n="妮萨的残骸",s="妮萨的残骸是阿加曼德·妮萨遗留于世的残躯。她曾是提瑞斯法林地北部显赫一时的阿加曼德家族的一名贵族女性。在第三次战争中，她被杀害并被复活成了天灾军团的无脑奴仆，如今，她和她的家人正遭到曾经的劳工们的追猎，他们渴望复仇。",h="妮萨的残骸是阿加曼德·妮萨遗留于世的残躯。她曾是提瑞斯法林地北部显赫一时的阿加曼德家族的一名贵族女性。在第三次战争中，她被杀害并被复活成了天灾军团的无脑奴仆，如今，她和她的家人正遭到曾经的劳工们的追猎，他们渴望复仇。",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","家族的死亡","妮萨·阿加曼德","妮萨的残骸","提瑞斯法林地"},ang={["faction:Horde"]="消灭复活的阿加曼德家族成员并清理他们的磨坊，可以确保提瑞斯法林地北部的安全，消除威胁到布瑞尔和幽暗城的残余天灾势力。",["race:Undead"]="对于被遗忘者来说，收复提瑞斯法意味着既要铲除他们昔日的天灾压迫者，也要消灭那些因愚蠢的傲慢而将普通劳工推向亡灵深渊的富有贵族。"},sec={{t="傲慢的遗产",b="在第三次战争之前，阿加曼德家族是提瑞斯法林地最富有、最有影响力的名门望族，他们在北部的群山中经营着繁荣的磨坊。当亡灵瘟疫席卷洛丹伦时，家族掌权者顽固地拒绝撤离。相反，他们加固了庄园，并说服了仆从和劳工坚守此地。那种傲慢让所有人付出了生命的代价。阿加曼德家族倒在了天灾军团的屠刀之下，被复活后，他们不再拥有引以为傲的独立，而是成了受巫妖王意志支配的蹒跚、无脑的行尸走肉。"},{t="苦涩的报复",b="在布瑞尔镇，在希尔瓦娜斯·风行者女王麾下重获自由的幸存者们并没有忘记那个家族致命的傲慢。库勒曼·法席恩，阿加曼德磨坊曾经的一名劳工，对他的前任雇主怀恨在心，因为是他们诱骗工人们步入了亡灵的深渊。他委托冒险者们除掉复活的阿加曼德家族成员，并回收他们的遗骸，比如妮萨的残骸。对于法席恩和其他被遗忘者而言，焚毁或摧毁这些遗物能带来一种冷酷的终结感和报复的快感。"}},faq={{q="妮萨·阿加曼德是谁？",a="妮萨是阿加曼德家族的一员，这是洛丹伦的贵族，在提瑞斯法林地拥有广袤的阿加曼德磨坊。当瘟疫席卷洛丹伦时，她与亲人一同丧命，并作为受巫妖王控制的亡灵爪牙被复活。",al={"妮萨是谁","妮萨背景故事","妮萨·阿加曼德"}},{q="为什么库勒曼·法席恩想要妮萨的残骸？",a="库勒曼·法席恩生前曾在阿加曼德磨坊工作。他痛恨这个家族，因为他们傲慢地拒绝撤离，劝说忠诚的工人们留下来送死。收集他们的遗骸让他得以向昔日的主子复仇。",al={"为什么库勒曼要残骸","为什么要杀阿加曼德家族","库勒曼·法席恩的动机"}},{q="这些残骸是在哪里收集的？",a="妮萨·阿加曼德徘徊在提瑞斯法林地北部的阿加曼德磨坊废墟中，和她复活的亲属以及无脑的天灾军团爪牙一起在破败的农舍间游荡。",al={"在哪里可以找到妮萨","妮萨·阿加曼德位置"}},{q="妮萨像被遗忘者一样保留了自由意志吗？",a="没有。与那些摆脱了巫妖王控制的被遗忘者不同，妮萨和她的家人依然作为无脑的亡灵被天灾军团奴役，并不具备幽暗城居民所拥有的感知能力和自由。",al={"妮萨是被遗忘者吗","妮萨有自由意志吗","妮萨是天灾军团吗"}}},fp="15,247,17.470.0,18.446.0,22.241.0,47.235.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="硝化甘油",s="硝化甘油是一种易挥发的化学物质，由驻扎在南贫瘠之地巴尔莫丹的矮人士兵和军官携带。它是他们挖掘作业所需的工业炸药，当然也可以被用来对付他们自己。",h="硝化甘油是一种易挥发的化学物质，由驻扎在南贫瘠之地巴尔莫丹的矮人士兵和军官携带。它是他们挖掘作业所需的工业炸药，当然也可以被用来对付他们自己。",kw={"巴尔莫丹","巴尔敦","贫瘠之地","爆炸物","加恩·石塔","硝化甘油","加恩的复仇"},ang={["profession:Engineering"]="工程师们会立刻认出硝化甘油是一种经典的复合炸药，当它与硝酸钠等氧化剂一起被多孔木浆吸收时，就会变得稳定且可引爆。",["race:Tauren"]="那些被用来在巴尔莫丹周围大地上留下创痕的易挥发化学品，是对石塔部落所遭受的工业破坏的一种痛苦提醒。"},sec={{t="工业拆除",b="巴尔敦矮人使用重型机械钻机和易挥发的化学品，在大肆破坏石塔牛头人的祖居地。为了在地面上炸出深洞并夷平山丘，巴尔莫丹挖掘场及其防御要塞的矮人人员都随身储备了大量的原始硝化甘油。无论是前线士兵还是像西里克·黑铸领主这样的军官，都会随身携带这种易挥发的液体，以维持那场持续的破坏性挖掘。"},{t="以彼之道，还施彼身",b="在勘探员卡兹戈姆死后，流离失所的牛头人勇士加恩·石塔试图彻底拆除这座入侵的矮人要塞。通过搜寻矮人的工程计划，加恩意识到，将没收的硝化甘油与木浆和硝酸钠混合，就能制造出一种威力足以反击巴尔莫丹防御驻军的爆炸装药。"}},faq={{q="硝化甘油是从哪里来的？",a="硝化甘油由驻扎在南贫瘠之地巴尔莫丹的矮人部队携带，包括巴尔敦士兵、步枪手、军官，以及要塞内的西里克·黑铸领主。",al={"在哪里可以找到硝化甘油","谁掉落硝化甘油","硝化甘油来源"}},{q="硝化甘油有什么用？",a="加恩·石塔将其与木浆和硝酸钠一起使用，调制成威力强大的爆炸装药，将矮人自己的拆除技术转而用于对付他们在巴尔莫丹的军事要塞。",al={"硝化甘油有什么用途","硝化甘油目的","加恩的复仇配方"}},{q="矮人们最初为什么要携带它？",a="巴尔莫丹的勘探员和驻军极度依赖炸药、蒸汽引擎和易挥发化学品来炸开大地，挖掘他们的考古遗址。",al={"为什么矮人有硝化甘油","巴尔莫丹爆炸物"}},{q="加恩·石塔是谁？",a="加恩·石塔是一位流亡的牛头人战士，当矮人在巴尔莫丹建立挖掘场和要塞并通工业破坏驱逐了他的部落时，他失去了自己的祖居地。",al={"加恩是谁","加恩·石塔"}}},fp="13,193,21.345.0,29.295.1,35.161.0,35.143.0,52.145.0,23.193.0"}
P.entries["item:nondescript-letter"] = {n="笔迹潦草的信件",s="笔迹潦草的信件是一封未加标记、密封的信件，交给刚刚苏醒并离开丧钟镇的被遗忘者。这封信由卡尔文·蒙泰古以跑腿的名义交给玩家，指示送信人沿着道路前往布瑞尔，找到恐惧之末旅店的旅店老板瑞尼。",h="笔迹潦草的信件是一封未加标记、密封的信件，交给刚刚苏醒并离开丧钟镇的被遗忘者。这封信由卡尔文·蒙泰古以跑腿的名义交给玩家，指示送信人沿着道路前往布瑞尔，找到恐惧之末旅店的旅店老板瑞尼。",kw={"潜行者的交易","布瑞尔","卡尔文·蒙泰古","丧钟镇","旅店老板瑞尼","笔迹潦草的信件","瑞尼"},ang={["class:Rogue"]="卡尔文·蒙泰古鬼鬼祟祟的姿态和瑞尼态度的骤变，带有典型的低等级潜行者阴谋和地下世界加密通讯的特征。",["race:Undead"]="对于刚刚复生的被遗忘者来说，携带这封信是他们离开丧钟镇的束缚，探索提瑞斯法林地更广阔定居点的最早动机之一。"},sec={{t="信使的差事",b="刚刚复生的被遗忘者在打算走出丧钟镇时，会遇到卡尔文·蒙泰古，一名在村庄边缘徘徊、行踪可疑的潜行者。卡尔文自称厌倦了与无脑的僵尸和蛛形纲生物战斗，请求旅行者将一个普通的、未加标记的信封沿着东面的路带到布瑞尔。这封信随手写给了名为瑞尼的旅店老板，它只是一个将旅行者赶出山谷并引向恐惧之末旅店的借口，尽管卡尔文承诺的丰厚报酬从一开始就显得苍白无力。"},{t="可疑的通信",b="信件送达布瑞尔后，旅店老板瑞尼最初试图用夸张而欢快的假象来掩饰，声称这封信一定是她在丧钟镇的圣洁母亲寄来的甜言蜜语。当她意识到信使看穿了她笨拙的表演时，她那愉快的态度瞬间转变为尖锐的恼怒。她一把夺过信件，拒绝透露是谁寄出的，也拒绝透露里面的内容，并粗暴地命令送信人离开，除非他们打算付钱开房。"}},faq={{q="笔迹潦草的信件是什么？",a="这是一个朴素、外观普通的信封，由丧钟镇的卡尔文·蒙泰古交给新晋的被遗忘者冒险者，旨在送给布瑞尔的旅店老板瑞尼。",al={"笔迹潦草的信件","这封信是什么","卡尔文的信"}},{q="是谁寄出的信，又是谁收到的？",a="驻扎在丧钟镇的潜行者卡尔文·蒙泰古将信交给信使。信的收件人是布瑞尔恐惧之末旅店的旅店老板瑞尼。",al={"谁寄的信","谁收到了信","寄信人"}},{q="信里到底写了什么？",a="这封信的具体内容并未向玩家透露。当被问及时，旅店老板瑞尼会卸下欢快的伪装，愤怒地告诉你，信件的来源和内容与你无关。",al={"信里写了什么","信件内容","你能读这封信吗"}},{q="为什么卡尔文·蒙泰古要送这封信？",a="卡尔文声称自己忙于对付当地的僵尸和蜘蛛，无法亲自跑腿。实际上，这次送递是为了引导旅行者离开丧钟镇，并向他们介绍布瑞尔提供的设施和休息点。",al={"为什么要送这封信","卡尔文的动机","为什么是布瑞尔"}}},fp="18,199,18.342.0,25.320.1,31.150.0,42.131.0,34.163.0,43.195.0"}
P.entries["item:nori-s-mug"] = {n="诺里斯的杯子",s="诺里斯的杯子是诺里斯·激流的私人酒杯，用于在丹莫罗寒冷的雪原上运送滚烫的晨酿。在为旅客送去热饮以抵御刺骨的高山严寒后，旅客们需要将空杯子归还给这位节俭的主人。",h="诺里斯的杯子是诺里斯·激流的私人酒杯，用于在丹莫罗寒冷的雪原上运送滚烫的晨酿。在为旅客送去热饮以抵御刺骨的高山严寒后，旅客们需要将空杯子归还给这位节俭的主人。",kw={"带回杯子","丹莫罗","德南·弗卡特","晨酿","诺里斯·激流","诺里斯的杯子"},ang={["race:Dwarf"]="对于在丹莫罗的风暴中艰难求生的矮人们来说，分享热饮是天性使然，但让好用的酒具流失在雪堆里却是不可原谅的浪费。"},sec={{t="信使的归途",b="在丹莫罗冰冻的山径上，一杯热气腾腾的晨酿是极少数能驱散严寒的慰藉之一。诺里斯·激流会将他的杯子交给旅客，让他们把新鲜、滚烫的饮品送到安威玛尔的德南·弗卡特手中。一旦喝完，这个坚固的杯子就必须踏上归途。正如诺里斯所说，杯子又不是长在树上的，在好客之道与冰雪荒原交汇之际，妥善保管耐用的矮人餐具是至关重要的事。"}},faq={{q="诺里斯的杯子是用来做什么的？",a="它是用来给安威玛尔的德南·弗卡特运送热气腾腾、滚烫的晨酿的容器。德南喝完暖身之后，空杯子必须被带回给诺里斯·激流。",al={"诺里斯的杯子的用途","杯子里装的是什么","诺里斯的杯子"}},{q="谁拥有这个杯子？",a="这个杯子属于诺里斯·激流，一位驻扎在丹莫罗的矮人，他非常珍视自己的财物，并坚持要求信使归还他的杯子，而不是让它们散落在雪地里。",al={"谁是诺里斯","杯子的所有者","这是谁的杯子"}},{q="为什么诺里斯坚持要拿回杯子？",a="在严酷的山地气候中，优质的陶器和坚固的酒杯是实用的必需品。正如诺里斯直言不讳地指出的那样，杯子可不是长在树上的，确保每一个借出的杯子都能回到自己手中，既是出于自尊，也是出于实用考虑。",al={"为什么归还杯子","为什么诺里斯想要拿回杯子","杯子又不是长在树上的"}},{q="杯子里喝的是什么？",a="里面装的是滚烫的晨酿，这是丹莫罗的矮人们非常珍视的一种浓郁热饮，用来抵御刺骨的寒冷并温暖心灵。",al={"杯子里装的是什么","什么是晨酿","晨酿饮品"}}},fp="10,154,18.339.0,28.137.0,18.103.0,45.128.0,28.88.0"}
P.entries["item:notched-rib"] = {n="锯齿肋骨",s="锯齿肋骨是从徘徊在提瑞斯法林地的无脑亡灵身上收集的一种骨头战利品。布瑞尔的亡灵卫兵迪林格尔收集这些伤痕累累的残骸，以此作为粉碎天灾军团在阿加曼德磨坊立足点的证明。",h="锯齿肋骨是从徘徊在提瑞斯法林地的无脑亡灵身上收集的一种骨头战利品。布瑞尔的亡灵卫兵迪林格尔收集这些伤痕累累的残骸，以此作为粉碎天灾军团在阿加曼德磨坊立足点的证明。",kw={"阿加曼德磨坊","布瑞尔","碎颅士兵","亡灵卫兵迪林格尔","锯齿肋骨","响骨士兵","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="对被遗忘者来说，收集这些破碎的骨头是针对巫妖王那些妄图将他们拖回奴役状态的无脑爪牙所进行的生存战争的一部分。"},sec={{t="残酷的战斗证明",b="集结在提瑞斯法林地北部平原的天灾军团由身披破损铠甲的复活骷髅组成。在他们的队伍中，碎颅士兵和响骨士兵会向任何遇到的活物或拥有自由意志的生物发起冲锋。切开他们脆弱的身躯会在骨骼结构上留下坑洼和划痕。为了确保被遗忘者侦察兵和志愿者确实是在清理这些无脑入侵者，而不是仅仅进行观察，亡灵卫兵需要实实在在的证据。一根布满战斗痕迹的锯齿肋骨，就是巫妖王的另一个奴仆已被粉碎的无可辩驳的证据。"},{t="守卫磨坊",b="阿加曼德磨坊是位于布瑞尔西北部的一个关键战略要地。如果天灾军团在废弃的农庄和风车间牢牢扎根，他们将拥有一个直接向提瑞斯法腹地发动进攻的集结地。亡灵卫兵迪林格尔监视着通往北方的道路，派遣勇士在骷髅军团巩固阵地前将其粉碎。运回布瑞尔的一堆堆锯齿肋骨表明被遗忘者的防线依然稳固，正在一点一点地磨灭天灾军团的先头部队。"}},faq={{q="什么是锯齿肋骨？",a="这是从占据提瑞斯法林地北部、被复活的天灾士兵身上取下的一块伤痕累累的骨头。它被带给亡灵卫兵迪林格尔，作为消灭敌人的实物证明。",al={"锯齿肋骨","什么是锯齿肋骨","锯齿肋骨物品"}},{q="锯齿肋骨从哪里来？",a="它们是从在布瑞尔西北部的阿加曼德磨坊巡逻的碎颅士兵和响骨士兵身上回收的。",al={"哪里可以找到锯齿肋骨","谁掉落锯齿肋骨","锯齿肋骨来源"}},{q="谁需要这些骨头？",a="驻扎在布瑞尔城外路边的亡灵卫兵迪林格尔收集这些骨头，以及焦黑的骷髅，以确认天灾军团的推进已被击退。",al={"谁需要锯齿肋骨","锯齿肋骨上交"}},{q="为什么天灾军团要在阿加曼德磨坊集结？",a="这些无脑亡灵正试图在磨坊建立一个集结基地。从那里，天灾军团可以轻松地向整个提瑞斯法林地发动袭击，并威胁到被遗忘者的定居点。",al={"阿加曼德磨坊的天灾军团","为什么磨坊有骷髅","阿加曼德磨坊的天灾威胁"}}},fp="11,94,20.425.0,18.445.0,22.169.0,32.119.0,22.142.0,46.155.0"}
P.entries["item:nugget-slug"] = {n="高强度齿轮",s="高强度齿轮是工业工程中使用的专用17.5规格机械紧固件。荆棘谷地精将它们囤积在淤泥沼泽的工具桶中，那些试图修理不稳定机械的修理工对此趋之若鹜。",h="高强度齿轮是工业工程中使用的专用17.5规格机械紧固件。荆棘谷地精将它们囤积在淤泥沼泽的工具桶中，那些试图修理不稳定机械的修理工对此趋之若鹜。",kw={"贫瘠之地","高强度齿轮","自鸣哨","淤泥沼泽","工具桶","荆棘谷地精","wenikee boltbucket"},ang={["profession:Engineering"]="每个工程师都知道，将专有的17.5规格硬件与不稳定的地精工程自鸣哨混合使用，就是在自找麻烦，会导致快速且爆炸性的解体。"},sec={{t="淤泥沼泽的工业紧固件",b="高强度齿轮是为严苛的工业装配制造的重型金属紧固件。这些部件精确规格为17.5号，是荆棘谷地精在各地采掘点部署的重型设备的重要组成部分。虽然作为普通贸易商品它们毫无用处，但对于处理定制地精硬件的修理工来说，它们却是必不可少的。"},{t="修理自鸣哨",b="Wenikee Boltbucket需要大量的高强度齿轮来检修一台从贫瘠之地回收的不稳定自鸣哨。由于荆棘谷地精习惯将工具桶散落在淤泥沼泽的钻探作业区，因此即使Wenikee最终的修理会导致突然的爆炸性故障，回收作业对于拾荒者来说依然有利可图。"}},faq={{q="什么是高强度齿轮？",a="高强度齿轮是一种用于重型机械的专用17.5规格金属紧固件或金属块。它们在复杂的工业机械（如石油钻机和自鸣哨）中作为结构硬件使用。",al={"什么是高强度齿轮","高强度齿轮背景故事","齿轮紧固件"}},{q="哪里可以找到高强度齿轮？",a="它们储存在淤泥沼泽周围的工具桶中，淤泥沼泽是位于贫瘠之地东北部的一个荆棘谷地精钻探营地。",al={"去哪里找高强度齿轮","高强度齿轮位置","淤泥沼泽工具桶"}},{q="为什么Wenikee Boltbucket需要它们？",a="Wenikee Boltbucket想要修理并调试一台回收的自鸣哨。由于她自己用完了17.5规格的紧固件，她便派遣冒险者去附近的荆棘谷地精营地打捞这些零件。",al={"谁需要高强度齿轮","为什么wenikee需要齿轮","修理自鸣哨"}},{q="使用这些高强度齿轮能修好自鸣哨吗？",a="没能成功。当Wenikee给机器装上打捞来的齿轮并开始维护工作时，自鸣哨在她面前突然发生了爆炸。",al={"机器能用吗","自鸣哨爆炸","wenikee修理结果"}}},fx={f3aea894={q="高强度齿轮从何而来？由谁制造？",a="这些特殊的十七点五口径弹丸是荆棘谷地精在淤泥沼泽使用的工业器材。他们的工人和工程师将其储存在工具桶中，散放在贫瘠之地东部的钻探和挖掘工地周围。",al={"高强度齿轮从何而来","谁制造高强度齿轮","高强度齿轮的来源"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:ogre-s-monocle"] = {n="食人魔的单片眼镜",s="食人魔的单片眼镜是一副巨大的眼镜，由居住在暮色森林南部沃古尔食人魔山的食人魔扎尔克·沃尔（Zzarc'Vul）佩戴。其巨大的镜片提供了维克托·安特拉斯在夜色镇组装一台复杂的观星望远镜所需的精确尺寸。",h="食人魔的单片眼镜是一副巨大的眼镜，由居住在暮色森林南部沃古尔食人魔山的食人魔扎尔克·沃尔（Zzarc'Vul）佩戴。其巨大的镜片提供了维克托·安特拉斯在夜色镇组装一台复杂的观星望远镜所需的精确尺寸。",kw={"cog","夜色镇","仰望星空","食人魔的单片眼镜","望远镜","维克托·安特拉斯","沃古尔食人魔山","扎尔克·沃尔"},ang={["faction:Alliance"]="从沃古尔食人魔手中夺回这枚镜片，既能消除南部森林中的一个危险威胁，又能帮助夜色镇饱受困扰的居民在星空中找到慰藉。",["profession:Engineering"]="Cog绘制的蓝图展现了典型的侏儒野心：在野外无法获得精密研磨镜片时，利用巨大的眼镜等非标准组件来达成目的。"},sec={{t="一枚奇特的镜片",b="虽然食人魔很少因博学而闻名，但扎尔克·沃尔不知何故得到了一副为他那庞大身躯量身定做的巨大单片眼镜。当夜色镇居民维克托·安特拉斯着手利用侏儒工程师Cog起草的蓝图建造一台观星仪器时，他发现标准的镜片太小了。事实证明，扎尔克·沃尔的眼镜是该地区唯一一片具备完成该设备所需的弯曲度和尺寸的抛光玻璃。"},{t="从沃古尔夺取它",b="想要获得这副单片眼镜，就必须闯入位于暮色森林南部阴影中的沃古尔食人魔山。扎尔克·沃尔居住在他的残暴同类之中，毫无主动交出这件独特饰品的意愿。想要得到这枚镜片，就意味着要在他的领地上击败这头野兽，然后将镜片带回夜色镇，这样维克托终于可以将目光投向夜空。"}},faq={{q="谁携带了食人魔的单片眼镜？",a="这副单片眼镜由扎尔克·沃尔持有，他是一位在暮色森林南部的沃古尔食人魔山中游荡的知名食人魔。",al={"谁掉落单片眼镜","谁有食人魔单片眼镜","扎尔克·沃尔物品"}},{q="为什么维克托·安特拉斯需要食人魔的目镜？",a="维克托正在根据侏儒Cog绘制的蓝图建造一台望远镜。该设备需要一个异常巨大的光学镜片，而扎尔克·沃尔的巨大单片眼镜是暮色森林中唯一符合规格的玻璃镜片。",al={"为什么需要单片眼镜","单片眼镜有什么用","望远镜镜片"}},{q="食人魔是怎么得到一副巨大的单片眼镜的？",a="资料来源并未解释扎尔克·沃尔是如何获得这副单片眼镜的。它只确定他拥有一副足够大，可以用于维克托望远镜的眼镜。",al={"为什么食人魔会有单片眼镜","食人魔阅读眼镜背景故事"}},{q="沃古尔食人魔山位于哪里？",a="沃古尔食人魔山位于暮色森林南部的山丘中，在夜色镇和西部边界之间的主路以南。",al={"沃古尔在哪里","暮色森林食人魔山"}}},fx={["94fbe42d"]={q="食人魔的单片眼镜是什么？",a="食人魔的单片眼镜是一枚尺寸巨大的光学镜片，由居住在暮色森林南部沃古尔食人魔山的显赫食人魔Zzarc'Vul佩戴。食人魔极少拥有如此精致的光学器具，而这枚巨大的玻璃镜片却特别适合用于重型光学设备。",al={"食人魔的单片眼镜是什么","食人魔单片眼镜物品","食人魔眼镜"}}},fp="14,159,14.367.0,22.323.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="秋葵",s="秋葵是一种在西部荒野的耕地上种植的蔬菜。它深受当地农户的喜爱，是该地区制作浓郁、即兴炖菜时必不可少的增稠剂。",h="秋葵是一种在西部荒野的耕地上种植的蔬菜。它深受当地农户的喜爱，是该地区制作浓郁、即兴炖菜时必不可少的增稠剂。",kw={"农作物","农场","秋葵","萨丁","萨尔玛·萨丁","蔬菜","西部荒野炖肉"},ang={["faction:Alliance"]="当暴风城的贵族享用着进口肉类时，边境的联盟农户却在西部荒野的废墟中靠种植秋葵这样顽强的作物生存。",["profession:Cooking"]="任何流浪厨师都知道，一锅好的炖菜需要的不仅仅是生肉；秋葵提供了必要的淀粉和质感，能将粗糙的荒野采集品变成一顿像样的热餐。"},sec={{t="萨丁农场的主食",b="虽然西部荒野大部分土地在迪菲亚兄弟会强盗和失控的收割傀儡的威胁下处于荒废状态，但像萨丁一家这样顽强的农夫依然设法从土壤中培育出了健康的蔬菜。秋葵在萨丁农场周围的耕地里长得低矮而翠绿。尽管乡村环境恶劣，但这种作物依然存活了下来，在来自暴风城的贸易和补给彻底断绝时，为当地农户提供了必要的食粮和营养。"},{t="西部荒野炖肉",b="秋葵最广为人知的用途是作为萨尔玛·萨丁著名的西部荒野炖肉中不可或缺的底料。它能与在尘土飞扬的平原上猎取的任何肉类（如秃鹫肉、野猪獠牙、海岸鱼人的眼睛）混合，切片的豆荚在受热后会分解，将稀薄的肉汤变成一顿饱腹又恢复体力的美餐。对于那些苦苦坚守在家园的定居者来说，新鲜的秋葵豆荚将零星的野外采集变成了热气腾腾、口味浓郁的晚餐。"}},faq={{q="西部荒野哪里有秋葵？",a="秋葵生长在位于西部荒野中央道路旁的萨丁农场的耕地里。旅行者可以在农夫萨丁的家园附近的垄沟里找到这些独特的绿色植物。",al={"秋葵位置","哪里寻找秋葵","秋葵生长地"}},{q="秋葵有什么用？",a="人们采集秋葵是为了送到萨丁农场给萨尔玛·萨丁，用来烹制她的招牌菜——西部荒野炖肉。其天然的淀粉质可以使汤汁浓稠，将秃鹫肉、野猪口鼻、鱼人眼球等粗糙的食材融合成一顿丰盛的餐点。",al={"秋葵用途","秋葵是做什么用的","为什么需要秋葵"}},{q="为什么秋葵对萨丁一家很重要？",a="由于贸易路线中断，王国提供的援助也寥寥无几，农户们必须完全依靠自己种植和狩猎来维持生计。秋葵是萨丁农场仅存的几种耕种作物之一，维持着这一家人和过往旅人的饮食。",al={"萨丁秋葵","为什么秋葵很重要"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:ordanus-head"] = {n="奥达努斯的头颅",s="“奥达努斯的头颅”是取自灰谷林中树居的守护者奥达努斯的恐怖战利品。它是受血精灵法师布莱林·火拳之托而获取的，是塞纳留斯的长子之一倒在奥术复仇之下的铁证。",h="“奥达努斯的头颅”是取自灰谷林中树居的守护者奥达努斯的恐怖战利品。它是受血精灵法师布莱林·火拳之托而获取的，是塞纳留斯的长子之一倒在奥术复仇之下的铁证。",kw={"灰谷","布莱林·火拳","塞纳留斯","丛林守护者","奥达努斯","奥达努斯的头颅","林中树居","石爪山脉","烈日石居"},ang={["class:Druid"]="对于德鲁伊而言，携带一颗塞纳留斯长子的头颅，是提醒人们奥术师对荒野守护者仍然怀有刻骨铭心的血海深仇的沉重警示。",["faction:Horde"]="击杀奥达努斯并将他的头颅交给布莱林，有助于巩固部落在石爪山脉和灰谷交界的争夺区域的立足点，并削弱当地暗夜精灵的领导层。"},sec={{t="往日的积怨",b="守护者奥达努斯是一位古老的丛林守护者，是森林之神塞纳留斯的年长子嗣之一。当布莱林·火拳奉其主人之命攀登石爪山脉时，她试图终结德鲁伊对山顶魔法的抑制，并向奥达努斯复仇。然而，在布莱林动手之前，这位守护者就被转移到了灰谷深处。利用奥术探知透过森林树冠进行窥探，火拳在林中树居的枝桠间找到了他的避难所，并要求取下他的头颅作为那位野性半神傲慢最终得到报应的证明。"},{t="傲慢的代价",b="布莱林对奥达努斯怀有旧怨，她很久以前就认识他，并憎恨那些试图抑制魔法流动的德鲁伊。生前，奥达努斯甚至自认为凌驾于古老的上层精灵贵族之上。通过取下他的头颅，火拳象征性地回击了塞纳留斯的传承，宣称没有任何荒野守护者能够阻挡原始魔法力量的回归。"}},faq={{q="守护者奥达努斯是谁？",a="守护者奥达努斯是一位古老的丛林守护者，也是塞纳留斯的年长子嗣。很久以前，他曾与暗夜精灵贵族的奥术修行者发生冲突，并以对奥术使用者怀有极深的傲慢而闻名。",al={"奥达努斯是谁","奥达努斯背景故事","奥达努斯是什么"}},{q="这个头颅是在哪里收集的？",a="这个头颅取自林中树居高耸木制平台上的守护者奥达努斯，林中树居是一处位于灰谷中部、防御森严的暗夜精灵树冠据点。",al={"奥达努斯的头颅在哪里找到","奥达努斯位置","林中树居奥达努斯"}},{q="为什么布莱林·火拳想要他的头颅？",a="布莱林·火拳很久以前就认识奥达努斯并鄙视他的傲慢，因为他甚至自认为凌驾于上层精灵之上。她还憎恨德鲁伊和塞纳留斯的子嗣试图阻止魔法的流动，以及在这一过程中将奥达努斯从山顶转移走，使她无法在之前得手。",al={"为什么布莱林想要奥达努斯的头颅","布莱林的积怨","为什么要杀死奥达努斯"}},{q="头颅被送达后会发生什么？",a="将“奥达努斯的头颅”送交给烈日石居的布莱林可以偿还她的血债，她会用承诺的强大礼物来奖励这位雇佣兵。",al={"奥达努斯的头颅任务提交","奥达努斯死后","布莱林·火拳任务奖励"}}},fx={e1459048={q="奥达努斯的头颅从何而来？",a="这件令人不寒而栗的战利品直接取自守护者奥达努斯。他是森林半神塞纳留斯最年长的儿子之一。人们曾以为他在石爪峰顶安然无恙，但奥达努斯逃到了灰谷，藏身于林中树居高处，最终还是被猎杀。",al={"奥达努斯头颅的来源","奥达努斯的头颅从何而来","奥达努斯的头颅属于谁"}}},fp="13,142,22.551.0,19.363.1,23.234.0,29.156.0,40.265.0,41.145.1"}
P.entries["item:orendil-s-cure"] = {n="奥雷迪尔的药剂",s="奥雷迪尔的药剂是草药师奥雷迪尔·阔叶在灰谷北部调配的一种药剂。它使用稀有的草药巴斯兰的头发制成，旨在治疗阿斯特兰纳遭受神秘且致命疾病折磨的瑞拉拉·怀特姆恩。",h="奥雷迪尔的药剂是草药师奥雷迪尔·阔叶在灰谷北部调配的一种药剂。它使用稀有的草药巴斯兰的头发制成，旨在治疗阿斯特兰纳遭受神秘且致命疾病折磨的瑞拉拉·怀特姆恩。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","奥雷迪尔·阔叶","奥雷迪尔的药剂","皮尔图拉斯·怀特姆恩","瑞拉拉"},ang={["profession:Herbalism"]="这种疗法展示了灰谷本土植物深厚的药用力量，尤其是巴斯兰的头发，它只在森林中特定的阴暗角落里生长。",["race:NightElf"]="对于阿斯特兰纳的暗夜精灵来说，拯救瑞拉拉是一项紧急的社区事务，将像奥雷迪尔这样的隐士的林地知识与对月神的虔诚信仰结合在一起。"},sec={{t="父亲的希望",b="当年轻的瑞拉拉·怀特姆恩在阿斯特兰纳身患重病时，常规疗法对她的病情毫无作用。她绝望的父亲皮尔图拉斯·怀特姆恩向奥雷迪尔·阔叶求助，这是一位居住在灰谷北部边缘的隐士，也是自然医药大师。奥雷迪尔利用从巴斯兰鬼屋的闹鬼废墟中采集的稀有植物巴斯兰的头发，调制出了这种特制的药剂。药剂的到来为皮尔图拉斯带来了之前几乎不曾有的希望，尽管这种药剂只能延缓病情，皮尔图拉斯必须求助于奥雷迪尔建议的其他疗法。"}},faq={{q="奥雷迪尔的药剂有什么用途？",a="这种药剂是为了安抚并治疗阿斯特兰纳的一位年轻暗夜精灵儿童瑞拉拉·怀特姆恩，她被一种突如其来的严重疾病所击倒。",al={"奥雷迪尔的药剂用途","药剂的作用","药剂的治疗对象"}},{q="谁制作了这种药剂？",a="它是由奥雷迪尔·阔叶制作的，他是一位居住在灰谷北部森林中的隐居暗夜精灵草药师，以其对森林植物和药物的精通而闻名。",al={"谁制作了奥雷迪尔的药剂","奥雷迪尔的药剂制作者"}},{q="制作它使用了什么成分？",a="关键成分是巴斯兰的头发，这是一种娇嫩且罕见的植物，采集自灰谷北部的巴斯兰鬼屋遗迹。",al={"药剂成分","奥雷迪尔的药剂里有什么"}},{q="这瓶药水能完全治愈孩子吗？",a="并不能完全治愈。皮尔图拉斯后来发现，奥雷迪尔的药剂只能延缓在他女儿体内蔓延的疾病，因此他寻求奥雷迪尔所建议的更强效的疗法：月神之泪。",al={"瑞拉拉痊愈了吗","瑞拉拉治好了吗"}}},fx={["8e86537e"]={q="奥雷迪尔的药剂是什么？",a="奥雷迪尔的药剂是由灰谷北部的草药师奥雷迪尔·阔叶调制的药剂。它专门用于治疗突发的严重疾病，是一场紧急救治行动的一部分，目的是挽救一名患上神秘疾病的暗夜精灵幼童。",al={"奥雷迪尔的药剂背景","奥雷迪尔的药剂是什么","奥雷迪尔的药剂"}},["6add91d1"]={q="为什么需要奥雷迪尔的药剂？",a="在阿斯特兰纳，皮尔图拉斯·怀特姆恩年幼的女儿蕾拉拉病入膏肓。常规疗法无效后，她的父亲绝望地向奥雷迪尔·阔叶求助。草药师调制了这份特制药剂，希望能在疾病夺走孩子的生命之前稳住她的病情。",al={"为什么需要奥雷迪尔的药剂","谁需要奥雷迪尔的药剂","为什么要运送奥雷迪尔的药剂"}}},fp="14,168,15.497.0,32.149.0,21.161.0,38.123.0,43.152.1"}
P.entries["item:oslow-s-toolbox"] = {n="奥斯洛的工具箱",s="奥斯洛的工具箱内装有湖畔镇的工头奥斯洛所急需的建筑工具。这批物资在从闪金镇运送途中被渡过止水湖，却遭到兽人投石车的轰炸而沉没。",h="奥斯洛的工具箱内装有湖畔镇的工头奥斯洛所急需的建筑工具。这批物资在从闪金镇运送途中被渡过止水湖，却遭到兽人投石车的轰炸而沉没。",kw={"工头奥斯洛","止水湖","湖畔镇","奥斯洛","赤脊山","沉没的箱子","丢失的工具","工具箱"},ang={["faction:Alliance"]="随着湖畔镇在黑石氏族的围攻下几乎与世隔绝，找回奥斯洛的补给物资对于保持城镇防御工事的完好至关重要。"},sec={{t="命中注定的横渡",b="维护湖畔镇的防御和基础设施是一项艰巨的挑战，尤其是在黑石兽人包围赤脊山的情况下。工头奥斯洛下令从闪金镇运来一套至关重要的建筑工具。由于通往湖畔镇的主桥已被敌军摧毁，这批货物不得不装上一艘小船横渡止水湖。当黑石氏族的部队用投石车炮击船只时，这次横渡戛然而止，小船和奥斯洛沉重的工具箱直接沉入了鱼人出没的深水之中。"}},faq={{q="为什么奥斯洛的工具箱会在湖底？",a="这批工具原本是从闪金镇运送过来的。由于湖畔镇的桥梁在围攻中被毁，物资必须乘船横渡止水湖。黑石兽人用投石车轰炸了那艘小船，导致船只沉没，工具箱也落入了湖底。",al={"为什么工具箱在水里","奥斯洛是怎么丢失工具的","沉没的工具箱传说"}},{q="这个工具箱是谁的？",a="这个工具箱属于工头奥斯洛，他是负责监督湖畔镇建筑和维修工作的负责人。如果没有合适的设备，想要在持续不断的攻击下维持城镇的防御工事几乎是不可能的。",al={"奥斯洛是谁","奥斯洛所有者","工头奥斯洛的工具"}},{q="工具是在止水湖的什么位置沉没的？",a="工具存放在止水湖中沉没的箱子里，就在那艘被毁小船的残骸附近，隐藏在湖岸边一个显眼的鱼人营地南侧的水下巨石之间。",al={"工具箱位置","沉没的箱子在哪里","船在哪里沉没的"}},{q="有什么威胁在看守那个沉没的箱子？",a="沉船残骸周围的水域里满是敌对的鱼人和凶猛的水生野兽，包括那些在湖中深水区徘徊的危险湖泊鞭尾鱼。",al={"工具箱附近的危险","止水湖的敌人","什么在守卫奥斯洛的工具"}}},fx={["543d5407"]={q="工头奥斯洛为什么需要找回他的工具箱？",a="湖畔镇遭到猛烈围攻，城镇与外界隔绝，必需物资也极度匮乏。身为城镇工头，奥斯洛需要工具来维护和修理湖畔镇的建筑与防御工事。由于闪金镇送来的货车无法通过被毁坏的桥梁，替换工具掉进了湖里，关键的建造工作因此停滞。找回工具对城镇的存续至关重要。",al={"奥斯洛为什么想要工具箱","奥斯洛为什么需要工具","为什么要找回奥斯洛的工具箱"}}},fp="15,182,18.392.0,49.231.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="奥斯瑞克的箱子",s="奥斯瑞克的箱子是一个沉重的包裹，里面装满了从暴风城发往西部荒野，支援哨兵岭困境中守军的全新铠甲。这些物资通过狮鹫航线运送，为人民军在西部荒野抵御不法团伙提供了至关重要的装备。",h="奥斯瑞克的箱子是一个沉重的包裹，里面装满了从暴风城发往西部荒野，支援哨兵岭困境中守军的全新铠甲。这些物资通过狮鹫航线运送，为人民军在西部荒野抵御不法团伙提供了至关重要的装备。",kw={"dungar longdrink","狮鹫","奥斯瑞克","奥斯瑞克的箱子","人民军","军需官刘易斯","哨兵岭","西部荒野"},ang={["faction:Alliance"]="每一批运抵哨兵岭的武器和盔甲，都有助于防止王国的西部边界彻底沦陷给迪菲亚潜行者。"},sec={{t="前线补给",b="西部荒野在迪菲亚潜行者的掠夺和豺狼人的袭击下苦苦挣扎，而暴风城军队却迟迟未到。驻扎在哨兵岭的人民军缺乏王室的正式支援，只能依靠零星的补给。奥斯瑞克的箱子里装满了从首都运往军需官刘易斯处的一批新铠甲，旨在直接分发给当地的民兵战士。"},{t="飞翼信使网络",b="从暴风城出发，穿过艾尔文森林，跨越边界将装备运往西部荒野，不仅路途缓慢，还充斥着强盗的伏击。为了避开地面道路，该箱子被托付给一名冒险者，通过位于暴风城Trade District的Gryphon Roost，搭乘狮鹫飞往哨兵岭的索尔处。这次快速交付证明了狮鹫在战时维持边境驻军补给方面所发挥的关键作用。"}},faq={{q="奥斯瑞克的箱子里有什么？",a="箱子里装有在暴风城制造的防护铠甲。军需官刘易斯会检查交付的物资，并立即准备将其分发给保卫哨兵岭的战士们。",al={"箱子里有什么","奥斯瑞克的箱子的内容","奥斯瑞克箱子内容"}},{q="奥斯瑞克是谁？",a="奥斯瑞克是一位常驻暴风城的护甲匠，他为驻守西部荒野的人民军准备了这批装备。",al={"奥斯瑞克是谁","谁寄送了奥斯瑞克的箱子"}},{q="谁负责接收这个箱子？",a="这批货物是发给军需官刘易斯的，他是负责管理西部荒野哨兵岭人民军补给和装备的军官。",al={"箱子运往何处","我应该把奥斯瑞克的箱子交给谁","箱子接收人"}},{q="为什么要通过狮鹫运送这个箱子？",a="强盗和不法分子使连接暴风城、艾尔文森林和西部荒野的道路变得极其危险。通过狮鹫从暴风城的Dungar Longdrink处直接飞往哨兵岭的索尔处，可以确保铠甲快速且安全地抵达。",al={"为什么要空运箱子","为什么要使用狮鹫","奥斯瑞克箱子飞行路线"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="一组软泥怪采样瓶",s="这是一套由铁炉堡的侏儒研究员拉里斯·空轮提供的专用空样本瓶。它旨在用于费伍德森林枯萎林地中的危险实地采样，瓶子经过特殊设计，可以安全地盛放受污染和被诅咒的软泥怪提取物，而不会被腐蚀。",h="这是一套由铁炉堡的侏儒研究员拉里斯·空轮提供的专用空样本瓶。它旨在用于费伍德森林枯萎林地中的危险实地采样，瓶子经过特殊设计，可以安全地盛放受污染和被诅咒的软泥怪提取物，而不会被腐蚀。",kw={"容器","被诅咒的","费伍德森林","铁炉堡","瓶子","拉里斯·空轮","软泥怪","工具包","软泥","受污染的"},ang={["faction:Alliance"]="收集这些样本有助于联盟跟上被遗忘者皇家药剂师协会所进行的不安研究的步伐。",["race:Gnome"]="拉里斯·空轮将这项软泥怪研究视为一个绝佳的机会，向铁炉堡的矮人展示收留流亡的侏儒是完全值得的。"},sec={{t="实地研究设备",b="这套由拉里斯·空轮为前往费伍德森林的无畏旅行者组装的工具包内含十二个空瓶，分为用于盛放被诅咒软泥怪和受污染软泥怪的容器。由于原始的软泥怪样本具有极强的腐蚀性，很容易腐蚀普通行李，因此必须使用坚固且密封的玻璃瓶，才能将这些酸性残留物跨越大陆运送回铁炉堡的技师工作台。"},{t="软泥怪之谜",b="空轮对软泥怪的兴趣远非简单的古怪爱好。他注意到被遗忘者的皇家药剂师协会经常在艾泽拉斯各地收集这些奇异的生物，他怀疑软泥怪可能隐藏着关于世界起源的深奥秘密。空轮推测，软泥怪可能是与这个星球诞生息息相关的原始分泌物，他依靠使用这套工具的现场特工来收集证据，以期在探险者协会中赢得声望。"}},faq={{q="一组软泥怪采样瓶里有什么？",a="该工具包内含十二个样本瓶：六个专门用于盛放被诅咒软泥怪的空瓶，以及六个用于盛放受污染软泥怪的空瓶。",al={"工具包内容","工具包里有什么","内部的软泥怪瓶"}},{q="谁提供了这组工具包？",a="它由在铁炉堡工作的侏儒学者兼研究员拉里斯·空轮分发给联盟的冒险者。",al={"谁提供瓶子","拉里斯·空轮的任务物品","哪里可以获得软泥怪工具包"}},{q="这些容器应该在什么地方使用？",a="它们旨在用于费伍德森林那腐化的荒野中，冒险者必须在那里击败受污染和被诅咒的软泥怪，直接从这些倒下的生物身上收集残留物样本。",al={"在哪里使用软泥怪瓶","软泥怪在哪个区域","软泥怪瓶的位置"}},{q="为什么拉里斯·空轮需要这些软泥怪样本？",a="拉里斯注意到被遗忘者的皇家药剂师协会一直在世界各地收集软泥怪，他想揭开其中的秘密。他还持有一种非传统的理论，认为软泥怪可能是与艾泽拉斯诞生相关的原始分泌物，并希望证明这一观点能让他获得探险者协会的地位。",al={"为什么要收集软泥","空轮的研究","拉里斯为什么需要软泥怪"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="彩色豺狼人臂章",s="彩色豺狼人臂章是游荡在艾尔文森林边缘的河爪豺狼人们佩戴的粗糙装饰品。西泉要塞收集这些有标记的臂章，作为完成消灭这些入侵族群悬赏任务的凭证。",h="彩色豺狼人臂章是游荡在艾尔文森林边缘的河爪豺狼人们佩戴的粗糙装饰品。西泉要塞收集这些有标记的臂章，作为完成消灭这些入侵族群悬赏任务的凭证。",kw={"悬赏","瑞尼尔副队长","艾尔文森林","豺狼人","彩色豺狼人臂章","河爪","石碑湖","西泉要塞"},ang={["faction:Alliance"]="收集这些臂章能直接支援西泉要塞，在暴风城正规军被调往他处时巩固王国的西部防线。"},sec={{t="河爪族的信物",b="河爪族群用绘有粗糙部落图案的臂章来标记他们的战士和拾荒者。这些彩色臂章是从艾尔文森林荒野边缘的河爪豺狼人身上收集的。然而对暴风城的守军来说，它们代表着一种日益严重的领土威胁，正不断逼近石碑湖和西泉要塞南方的林地。"},{t="西泉要塞的悬赏",b="随着暴风城军队在王国各地兵力吃紧，西泉要塞难以独自确保西部边境的安全，抵御不断侵扰的威胁。瑞尼尔副队长对这些入侵的豺狼人族群发布了常设悬赏令，指引冒险者去猎杀河爪斥候和河爪小崽。这些彩色臂章是击杀的有力证据，让要塞的副官们可以核算赏金，并削减那些正在侵扰附近农田的豺狼人数量。"}},faq={{q="为什么西泉要塞需要这些臂章？",a="西泉要塞的瑞尼尔副队长收集这些臂章作为猎杀河爪豺狼人的证据。由于要塞守军无法独自应对这些不断入侵的族群，暴风城会向任何带回这些信物的冒险者支付赏金。",al={"为什么需要臂章","谁想要彩色豺狼人臂章","瑞尼尔副队长悬赏"}},{q="哪些豺狼人佩戴这种彩色臂章？",a="它们由艾尔文森林的河爪豺狼人携带，具体来说是那些侵扰西泉要塞以南森林以及石碑湖沿岸的河爪斥候和河爪小崽。",al={"哪里掉落臂章","谁掉落彩色豺狼人臂章","哪些豺狼人有臂章"}},{q="为什么河爪豺狼人会出现在艾尔文森林？",a="河爪族群沿着艾尔文森林的边界向东推进，在石碑湖附近和森林边缘建立了营地。他们利用王国军事力量空虚的机会进行狩猎、拾荒，并威胁附近的定居点。",al={"为什么豺狼人会在这里","豺狼人入侵艾尔文","艾尔文森林的河爪氏族"}},{q="臂章上的彩绘有什么意义？",a="这些臂章用于识别从河爪豺狼人身上获取的战利品，并作为提供给瑞尼尔副队长的凭证。资料中并未说明这些彩绘图案代表具体的等级或含义。",al={"为什么它们是彩色的","豺狼人臂章标记"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="豹笼钥匙",s="豹笼钥匙是一把由白沙岗哨的维兹罗持有的小金属钥匙。它能打开一个坚固的笼子，笼子里关着一只被困在千针石林一处遇袭商队残骸中的愤怒猛兽。",h="豹笼钥匙是一把由白沙岗哨的维兹罗持有的小金属钥匙。它能打开一个坚固的笼子，笼子里关着一只被困在千针石林一处遇袭商队残骸中的愤怒猛兽。",kw={"半人马","超适应齿轮","豹笼钥匙","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="协助维兹罗有助于确保千针石林白沙岗哨周围道路的安全，免受半人马袭击造成的动荡后果影响。",["profession:Engineering"]="这把钥匙打开了关着技师不稳定原型的笼子，证明了古怪的发明家们会将他们最精密的机械藏在人们能想象到的最危险的地方。"},sec={{t="危险的锁",b="当一支旅行商队在白沙岗哨以北遭到半人马掠夺者的袭击和洗劫时，地精技师维兹罗侥幸逃得一命。在马车残骸和被劫掠的货物中，掠夺者们唯独留下了一样东西没动：一个装着一只凶猛稀有豹子的结实笼子。在那只猛兽的脖子上挂着维兹罗珍贵的发明：超适应齿轮。半人马们不愿靠近那头咆哮的野兽，因此对笼子敬而远之，这使得维兹罗的钥匙成为了打开笼门并取回装置的唯一途径。"}},faq={{q="谁提供了豹笼钥匙？",a="这把钥匙由在千针石林西北部白沙岗哨休息的地精技师维兹罗交给冒险者。",al={"谁给豹笼钥匙","哪里获得豹笼钥匙","豹笼钥匙来源"}},{q="这把钥匙能打开什么？",a="它能打开一个铁笼，这个铁笼位于白沙岗哨以北一处被毁商队的破碎马车之中，里面关着一只愤怒且危险的豹子。",al={"豹笼钥匙打开什么","豹笼位置","笼子在哪里"}},{q="为什么半人马没有洗劫那个笼子？",a="半人马洗劫了商队的其余部分，但笼子里那只被俘的豹子太过凶猛且具有威胁性，以至于连掠夺者都拒绝触碰它的笼子。",al={"为什么半人马留下豹子","半人马害怕豹子"}},{q="笼子里除了野兽还有什么？",a="维兹罗珍贵的超适应齿轮系在那只豹子的脖子上，这迫使任何想要收回该发明的人必须打开笼子，并直接面对那只猛兽。",al={"为什么要打开笼子","豹子身上有什么"}}},fx={b335554a={q="维兹罗为什么要取回豹笼钥匙？",a="维兹罗·轴闪把钥匙交给你，只是为了让你打开他那辆被毁货车上的笼子，杀死里面凶猛的豹子。那头野兽脖子上戴着他珍爱的超适应齿轮。他希望事情办妥后，你把钥匙和发明一并归还，好确认货车残骸和他的危险财物都已清点完毕。",al={"为什么需要豹笼钥匙","维兹罗为什么需要钥匙","为什么要豹笼钥匙"}}},fp="16,219,17.550.0,34.133.0,25.147.0,37.165.0,42.176.0"}
P.entries["item:parker-s-lunch"] = {n="帕克的午餐",s="帕克的午餐是达希在湖畔镇亲手制作的便当。这份午餐是为正在巡逻的卫兵帕克准备的，让我们得以一窥赤脊山守卫者们日常生活中的温情与慰藉。",h="帕克的午餐是达希在湖畔镇亲手制作的便当。这份午餐是为正在巡逻的卫兵帕克准备的，让我们得以一窥赤脊山守卫者们日常生活中的温情与慰藉。",kw={"免费的午餐","达希","卫兵帕克","湖畔镇","帕克的午餐","赤脊山"},ang={["faction:Alliance"]="由于暴风城迟迟未派援军，镇民与仅存的卫兵之间的地方团结正是让湖畔镇得以维持运作的关键。",["profession:Cooking"]="一份热气腾腾的便当往往是边境卫兵们在漫长的值守和面对荒野中敌对野兽时，仅有的慰藉。"},sec={{t="路上的餐点",b="尽管赤脊山正饱受豺狼人和黑石兽人的侵袭，日常生活中的微小温情依然在持续。湖畔镇旅店的招待达希为卫兵帕克打包了这份热气腾腾的午餐，而帕克正负责巡逻通往南方暮色森林那条危险的道路。赤脊山的驻军兵力匮乏，得不到暴风城的援助，卫兵们只能各自坚守着漫长而孤独的岗哨。送去这份包裹不仅能让哨兵填饱肚子，也让这两位镇民之间萌生了一段含蓄而持久的恋情。"}},faq={{q="是谁准备了帕克的午餐？",a="这份午餐是由湖畔镇旅店的招待达希准备的。她担心正在外执行危险巡逻任务的卫兵帕克，因此委托路过的冒险者将午餐安全送达。",al={"谁制作了帕克的午餐","谁给了我帕克的午餐","达希 赤脊山 午餐"}},{q="卫兵帕克在哪里？",a="卫兵帕克在从湖畔镇通往暮色森林边界的西南主干道上巡逻。他沿着那条路来回行进，时刻警惕着游荡的豺狼人。",al={"卫兵帕克的位置","卫兵帕克在哪里","寻找卫兵帕克"}},{q="卫兵帕克收到午餐后会做什么？",a="帕克被达希的体贴深深打动了。由于在艰苦的巡逻中能吃到热乎的食物，他心怀感激，不久便想方设法回报她的心意，寻求他人的帮助给她送去草药师种植的新鲜水仙花。",al={"帕克的午餐后续","达希与帕克","帕克对午餐的反应"}},{q="为什么达希不亲自送午餐？",a="湖畔镇外的道路上充斥着具有攻击性的赤脊山豺狼人和黑石入侵者。虽然卫兵帕克拥有战斗训练和盔甲，能够在外巡逻中生存，但像达希这样的普通镇民无法独自冒险进行这段旅程。",al={"为什么达希不能自己送","为什么要运送午餐到赤脊山"}}},fx={["2351e721"]={q="帕克的午餐是什么？",a="帕克的午餐是旅店助手达希准备的一份便餐。她特意将它打包起来，为卫兵帕克补充体力。帕克要花很长时间在镇子南边通往暮色森林的险恶道路上巡逻，工作十分辛苦。",al={"帕克的午餐是什么","帕克的午餐物品"}},b73a829b={q="为什么要把卫兵帕克的午餐送过去？",a="卫兵帕克驻守在湖畔镇相对安全的区域之外，沿着边境道路提防四处游荡的豺狼人和黑石兽人。他无法擅自离岗回旅店，只能依靠达希这样的镇民和路过的旅人送来食物，才能在执勤时填饱肚子。",al={"为什么要送帕克的午餐","帕克为什么想要午餐","卫兵帕克为什么需要午餐"}}},fp="14,153,19.390.0,28.133.0,32.148.0,52.143.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="装着半瓶水的瓶子",s="装着半瓶水的瓶子是一种被附魔的容器，用于在泰达希尔各地运输经过祝福的月井水。它由特纳隆·雷拳在奥达希尔交给年轻的暗夜精灵新兵，里面装着从幽影谷汲取的水，将被送往多兰纳尔定居点。",h="装着半瓶水的瓶子是一种被附魔的容器，用于在泰达希尔各地运输经过祝福的月井水。它由特纳隆·雷拳在奥达希尔交给年轻的暗夜精灵新兵，里面装着从幽影谷汲取的水，将被送往多兰纳尔定居点。",kw={"奥达希尔","科瑞萨斯·月怒","crown of the earth","多兰纳尔","月井","装着半瓶水的瓶子","幽影谷","特纳隆·雷拳","瓶子"},ang={["class:Druid"]="运输圣水是在为塞纳里奥议会持续不断的努力服务，以培育和检查世界之树的健康状况，这是一项必不可少的职责。",["race:NightElf"]="携带这个瓶子是一种成人礼，它将年轻的暗夜精灵带离幽影谷的避难所，让他们承担起照料泰达希尔的更广泛的责任。"},sec={{t="神圣的交付",b="在奥达希尔的枝桠间，卡多雷新兵们收集来自幽影谷幽静月井的圣水。特纳隆·雷拳将纯净的样本注入这个特制的容器中，为它在这棵世界之树上的旅程做好准备。瓶子目前只装了一半，因为它的旅程才刚刚开始；最终必须从泰达希尔各地收集更多圣水，以维护岛屿的健康。"},{t="前往多兰纳尔",b="携带这个瓶子需要穿过幽影谷南部的谷门，顺着鹅卵石路向西前往多兰纳尔。这段旅程标志着年轻的冒险者离开了幽影谷这个受保护的苗圃，走向泰达希尔更广阔的荒野。在多兰纳尔的中心月井处，科瑞萨斯·月怒会接管瓶子，指导仪式的下一阶段。"}},faq={{q="瓶子里装的是什么？",a="它装有从幽影谷圣池中收集的纯净月井水，由德鲁伊特纳隆·雷拳倒入容器中。",al={"瓶子里有什么","瓶中物","里面装的是什么水"}},{q="为什么它只装了一半？",a="幽影谷的月井只提供了第一个样本。要维护泰达希尔，需要持续不断地从树上多处月井收集水，直到容器装满为止。",al={"为什么只装了一半","为什么没装满"}},{q="我应该把瓶子交给谁？",a="带着瓶子离开幽影谷向南走，然后顺着鹅卵石路向西前往多兰纳尔。在那里，把它交给负责照看镇上月井的科瑞萨斯·月怒。",al={"谁来接收瓶子","我应该把它带到哪里","瓶子上交"}},{q="为什么要在这泰达希尔四处搬运月井水？",a="德鲁伊和女祭司们通过月井的水来监测和滋养泰达希尔。在月井之间运输水有助于在这棵刚刚长成的世界之树那困顿的枝桠上维持它们的祝福。",al={"为什么要运输月井水","水的用途","为什么要搬运水"}}},fp="23,158,17.272.0,18.325.0,26.106.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:pendant-of-shadow"] = {n="暗影坠饰",s="暗影坠饰是一件黑暗护身符，由盘踞在赤脊山伊尔加拉之塔顶端的叛变术士摩根斯佩戴。将其带给阿祖拉之塔的法师塞欧克瑞图斯，便能无可辩驳地证明这个邪恶的施法者在其险恶企图得逞之前已被消灭。",h="暗影坠饰是一件黑暗护身符，由盘踞在赤脊山伊尔加拉之塔顶端的叛变术士摩根斯佩戴。将其带给阿祖拉之塔的法师塞欧克瑞图斯，便能无可辩驳地证明这个邪恶的施法者在其险恶企图得逞之前已被消灭。",kw={"摩根","暗影坠饰","赤脊山","月神镰刀","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="应塞欧克瑞图斯之托找回这件黑暗护身符，凸显了法师在监督威胁王国的鲁莽施法者方面所肩负的持续责任。",["class:Warlock"]="摩根的事例代表了在追寻月神镰刀这类不稳定禁忌神器时，因引起阿祖拉之塔过度关注而带来的危险。"},sec={{t="黑暗术士的信物",b="暗影坠饰由盘踞在伊尔加拉之塔巢穴中的叛变术士摩根所持有，上面浸透了黑暗魔法。摩根试图揭开月神镰刀的奥秘，这件远古圣物蕴含着巨大且不稳定的力量。由于担心这名术士会给赤脊山和暴风城王国带来浩劫，法师塞欧克瑞图斯委派冒险者潜入伊尔加拉，终结摩根的阴谋，并从他手中夺回这件护身符作为他已死的证据。"}},faq={{q="我在哪里可以找到暗影坠饰？",a="暗影坠饰由术士摩根携带，他就住在赤脊山东北部的伊尔加拉之塔塔顶。",al={"暗影坠饰位置","暗影坠饰在哪里","如何获得暗影坠饰"}},{q="谁需要暗影坠饰？",a="这件护身符必须带给位于艾尔文森林东部的阿祖拉之塔中的法师塞欧克瑞图斯。",al={"谁回收暗影坠饰","暗影坠饰交付","塞欧克瑞图斯坠饰"}},{q="为什么塞欧克瑞图斯需要这件坠饰？",a="塞欧克瑞图斯需要这件坠饰作为摩根已被击杀，以及他寻求危险的月神镰刀的企图已被终结的有力证据。",al={"为什么塞欧克瑞图斯需要它","暗影坠饰的作用"}},{q="摩根持有这件坠饰构成了什么威胁？",a="摩根一直在搜寻难以捉摸的月神镰刀。塞欧克瑞图斯担心，如果这名黑暗术士成功获得了该神器，他将会在赤脊山及周边王国释放出毁灭性的力量。",al={"摩根在做什么","摩根背景故事"}}},fx={d0e37f9a={q="暗影坠饰是什么？",a="暗影坠饰是堕落术士摩根斯佩戴的一枚黑暗护符，他盘踞在赤脊山的伊尔加拉之塔顶端。这枚坠饰与摩根斯佩的邪恶野心和黑暗法术密切相关，是他落败的凭证，巫师塞欧克瑞图斯需要它，因为他担心若不加以制止，摩根斯佩会在暴风城掀起灾祸。",al={"暗影坠饰是什么","暗影坠饰的背景","暗影坠饰信息"}}},fp="17,192,23.404.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="海狮坠饰",s="海狮坠饰是一件神圣的德鲁伊护身符，象征着水生生物敏捷与耐力的结合。它在月光林地的雷姆洛斯神殿中组装，是德鲁伊新兵准备好掌握其水栖形态的证明。",h="海狮坠饰是一件神圣的德鲁伊护身符，象征着水生生物敏捷与耐力的结合。它在月光林地的雷姆洛斯神殿中组装，是德鲁伊新兵准备好掌握其水栖形态的证明。",kw={"水栖形态","德迪利特·星焰","玛斯雷·驭熊者","月光林地","海狮坠饰","remulos","图拉克·符文图腾"},ang={["class:Druid"]="组装这件护身符是德鲁伊训练中的一个关键里程碑，它解锁了在水中呼吸的能力，并能以海狮的形态轻松快速地游动。",["race:Tauren"]="对于走在塞纳里奥议会道路上的舒哈鲁人来说，将坠饰带回给图拉克·符文图腾既是对先祖的尊重，也是对月光林地教诲的传承。"},sec={{t="深渊之证",b="为了获得海狮的水生特性，德鲁伊必须证明自己能够战胜水中最大的危险。坠饰的制作需要回收两个截然不同的部分：一部分象征着在水生掠食者身边穿梭所需的敏捷，另一部分则赋予了长时间潜水所需的耐力。这两部分被带到月光林地的雷姆洛斯神殿，合二为一。"},{t="掌握之证",b="坠饰锻造完成后，需要呈交给长者导师——例如雷霆崖长者高地上的图拉克·符文图腾，或是达纳苏斯的玛斯雷·驭熊者。这件护身符是新兵在德迪利特·星焰指导下完成试炼的有力证明，长者们据此传授其变形为水栖形态的秘诀。"}},faq={{q="海狮坠饰的用途是什么？",a="它是德鲁伊新兵完成水生敏捷与耐力试炼的证明，表明他们已做好准备学习水栖变形形态。",al={"海狮坠饰的作用","海狮坠饰的用途","为什么要获取海狮坠饰"}},{q="坠饰是在哪里组装的？",a="这两部分——分别代表敏捷与耐力——必须在位于月光林地圣所内的雷姆洛斯神殿中结合在一起。",al={"如何制作海狮坠饰","在哪里组合坠饰碎片"}},{q="在雷霆崖我该把坠饰交给谁？",a="牛头人德鲁伊需将完成后的坠饰交给雷霆崖长者高地上的图拉克·符文图腾，以完成他们的训练。",al={"雷霆崖谁负责接收坠饰","图拉克·符文图腾坠饰","部落水栖形态交任务"}},{q="暗夜精灵也能获得这个坠饰吗？",a="可以。暗夜精灵德鲁伊在月光林地进行同样的试炼，他们将组装好的坠饰带给达纳苏斯的玛斯雷·驭熊者即可。",al={"联盟海狮坠饰","达纳苏斯海狮坠饰"}}},fp="23,158,19.295.0,16.315.0,51.128.0,31.114.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="匹瑞诺德王冠",s="匹瑞诺德王冠是奥特兰克陨落的王室家族所拥有的一件镶嵌祖母绿的传家宝，最初由铁炉堡的矮人工匠打造。在王国覆灭的混乱中，它下落不明，最终落入了一个游荡在奥特兰克废墟中的食人魔贪婪的手中，随后引起了暴风城收藏家们的兴趣。",h="匹瑞诺德王冠是奥特兰克陨落的王室家族所拥有的一件镶嵌祖母绿的传家宝，最初由铁炉堡的矮人工匠打造。在王国覆灭的混乱中，它下落不明，最终落入了一个游荡在奥特兰克废墟中的食人魔贪婪的手中，随后引起了暴风城收藏家们的兴趣。",kw={"奥特兰克","祖母绿","格雷博格","铁炉堡","贪婪者","匹瑞诺德","雷明顿","瑞治维尔","王冠"},ang={["faction:Alliance"]="这件文物是对匹瑞诺德家族痛苦的回忆，他们在第二次战争期间的背叛几乎摧毁了最初的洛丹伦联盟。",["race:Dwarf"]="这顶王冠见证了铁炉堡著名的宝石工艺，那里的珠宝大师为北方的人类王室切割并镶嵌了祖母绿。"},sec={{t="一件废弃王国的遗物",b="在奥特兰克的多山领地于第二次战争期间因背叛和战乱而崩塌之前，其统治家族是匹瑞诺德家族。在他们的珍宝中，就有这顶精致的王冠，这是委托铁炉堡的珠宝大师打造，并镶嵌了璀璨的祖母绿。当奥特兰克在艾登·匹瑞诺德国王的背叛下沦为废墟时，这件王室珠宝就此消失在高耸的山巅废墟之中。"},{t="守财奴的战利品",b="这顶王冠并没有被永远埋在雪下，而是被贪婪者格雷博格——一个在奥特兰克废墟中搜寻被遗弃财富的食人魔术士——发掘了出来。关于这件幸存遗物的消息传到了暴风城的富裕贵族雷明顿·瑞治维尔伯爵耳中，他渴望为自己的家族博物馆搜罗著名的遗物，于是发起了一项行动，试图从食人魔的手中夺回这顶王冠。"}},faq={{q="什么是匹瑞诺德王冠？",a="它是一件曾经属于奥特兰克王室匹瑞诺德家族的传家宝。它由铁炉堡的矮人珠宝大师打造，并装饰着精美的祖母绿，在奥特兰克覆灭时下落不明。",al={"匹瑞诺德王冠背景故事","这顶王冠是什么","奥特兰克王冠"}},{q="现在谁持有这顶王冠？",a="一位名叫贪婪者格雷博格的食人魔术士在奥特兰克冰封的废墟中发现了这顶王冠。他在这个废墟王国中搜寻更多遗失的财宝时，嫉妒地守护着它。",al={"王冠在哪里","谁掉落王冠","格雷博格的王冠"}},{q="为什么雷明顿·瑞治维尔伯爵想要它？",a="雷明顿·瑞治维尔伯爵为他在暴风城的家族博物馆收藏具有历史意义和威望的古董。从一个覆灭的人类王国回收一件真正的王室珠宝，可以为他的收藏提供一件令人印象深刻的镇馆之宝。",al={"谁想要王冠","雷明顿为何想要它","雷明顿·瑞治维尔的动机"}},{q="匹瑞诺德家族是谁？",a="匹瑞诺德家族是奥特兰克王国的统治王朝。在第二次战争期间，艾登·匹瑞诺德国王背叛了联盟，投靠了兽人部落，导致他的主权领土走向了崩溃和毁灭。",al={"匹瑞诺德家族","匹瑞诺德王室","奥特兰克的统治者"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:phial-of-scrying"] = {n="占卜之水",s="占卜之水是一个由黑海岸的知识古树奥努所提供的附魔容器。使用它时，它会显现出一个占卜水盆，让你能够在被腐化的林地间进行远程沟通。",h="占卜之水是一个由黑海岸的知识古树奥努所提供的附魔容器。使用它时，它会显现出一个占卜水盆，让你能够在被腐化的林地间进行远程沟通。",kw={"黑海岸","主宰之剑","奥努","占卜之水","占卜水盆","暮光之锤"},ang={["class:Druid"]="德鲁伊认为占卜水盆是自然之水与沟通魔法的和谐融合，让森林的守护者能够在被腐化的土地上交换低语。",["race:NightElf"]="对于黑海岸的暗夜精灵来说，像占卜之水这样古老的预言工具，对于在遭受外来邪教侵蚀的圣洁林地保持警惕至关重要。"},sec={{t="黑海岸的透镜",b="占卜之水被托付给深入黑海岸调查的侦察兵，它装有神秘的湖水，可以在地上召唤出一个临时的占卜水盆。该工具能够进行远程占卜，让前往诸如主宰之剑等危险地区的旅行者能够直接与奥努沟通，而无需立刻回到他的林地。"},{t="揭露邪教",b="奥努专门提供该水瓶以监视暮光之锤邪教徒令人不安的活动。通过在那柄被巨大的战刃刺穿的远古陨落主宰所在地建立占卜链接，侦察兵证实了黑暗邪教徒正活跃在这些古代遗骸周围，试图搜寻即使在死后仍残留的被遗忘的力量碎片。"}},faq={{q="占卜之水有什么用？",a="当打开瓶塞时，水瓶会在地上显现出一个魔法占卜水盆，让在野外探险的冒险者能够跨越遥远的距离联系并与知识古树奥努交谈。",al={"使用占卜之水","占卜水盆的功能","这个水瓶有什么用"}},{q="谁提供了占卜之水？",a="远古树人奥努在派遣黑海岸的侦察兵前往南方的主宰之剑进行侦察任务时，会将水瓶托付给他们。",al={"谁给的占卜之水","哪里能拿到水瓶"}},{q="如果水瓶丢失或用完了怎么办？",a="如果水瓶在任务完成前丢失或耗尽，奥努在黑海岸冥想时可以再给你一个。",al={"占卜之水丢失","获取另一个水瓶","更换水瓶"}},{q="为什么奥努要占卜主宰之剑？",a="奥努知道主宰之剑是某位远古领主陨落的地方，并要求你在那里搜寻暮光之锤邪教徒。随着调查的深入，他们的目的也随之揭晓。",al={"为什么占卜主宰之剑","奥努的战刃任务"}}},fp="16,185,23.284.0,19.312.1,34.151.0,34.129.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="克罗姆扎军旗的碎片",s="从科卡尔报复部队指挥官克罗姆扎尔督军的军旗上扯下的一块布条。这是给雷格萨·死门的一个确凿证据，证明来自凄凉之地的半人马入侵已被粉碎。",h="从科卡尔报复部队指挥官克罗姆扎尔督军的军旗上扯下的一块布条。这是给雷格萨·死门的一个确凿证据，证明来自凄凉之地的半人马入侵已被粉碎。",kw={"旗帜","半人马","反击","十字路口","死门","科卡尔","克罗姆扎尔","雷格萨"},ang={["faction:Horde"]="击败克罗姆扎尔并夺取他的军旗，能够阻止一场大规模的半人马攻势，从而确保杜隆塔尔、莫高雷和十字路口之间的北部通道安全。",["race:Tauren"]="半人马的侵略长期以来一直困扰着游牧部落，克罗姆扎尔先锋队的覆灭是通往莫高雷的道路安全的一个令人欣慰的信号。"},sec={{t="半人马入侵的战利品",b="在贫瘠之地的各处科卡尔酋长被系统性地击败后，一支愤怒的战团从凄凉之地向东进军，意图复仇。在克罗姆扎尔督军的带领下，这些入侵者袭击了十字路口西面的防御碉堡。从督军倒下的战旗上割下一块碎片，可以向雷格萨·死门提供无可辩驳的证据，证明这次袭击已被粉碎，且南部的贸易路线已为部落保住。"}},faq={{q="这个旗帜碎片有什么用？",a="这块撕下的布料被带给位于十字路口西面碉堡里的雷格萨·死门。它证明了克罗姆扎尔督军已被击杀，他的突袭部队也被粉碎，从而结束了对北贫瘠之地的防御。",al={"旗帜用途","为什么要保留旗帜","旗帜碎片有什么用"}},{q="克罗姆扎尔督军是谁？",a="克罗姆扎尔是从凄凉之地的荒野中派来的一名凶猛的科卡尔指挥官。为了回应当地科卡尔首领的死亡，他领导了针对部落前哨站的直接反击。",al={"克罗姆扎尔是谁","克罗姆扎尔背景故事","克罗姆扎尔督军"}},{q="科卡尔人为什么要袭击碉堡？",a="在部落勇士消灭了贫瘠之地的当地酋长——包括巴拉克、维罗戈和赫兹鲁——之后，愤怒的半人马从凄凉之地集结了增援部队，意图对十字路口西面的部落势力进行报复。",al={"为什么要反击","科卡尔入侵的原因","贫瘠之地反击的原因"}},{q="萨尔会知道这场胜利吗？",a="是的。收到旗帜碎片后，雷格萨·死门承诺会直接向奥格瑞玛的大酋长萨尔传达正式消息，嘉奖那些粉碎了入侵的保卫者。",al={"萨尔的奖励","萨尔知道吗"}}},fp="26,158,31.357.0,35.193.0,25.139.0,37.189.0,33.133.0"}
P.entries["item:plainstrider-beak"] = {n="陆行鸟的喙",s="陆行鸟的喙是从漫步在贫瘠之地灌木丛中的高大走禽身上采集的。十字路口的狩猎大师们收集这些喙，以此作为猎人已经清除威胁到定居点补给的当地鸟类的实物证明。",h="陆行鸟的喙是从漫步在贫瘠之地灌木丛中的高大走禽身上采集的。十字路口的狩猎大师们收集这些喙，以此作为猎人已经清除威胁到定居点补给的当地鸟类的实物证明。",kw={"贫瘠之地","十字路口","陆行鸟的喙","陆行鸟威胁","塞格拉·黑刺","陆行鸟"},ang={["class:Hunter"]="击倒陆行鸟并收集它们的喙为新手追踪者提供了在卡利姆多开阔平原上跟踪和获取猎物的入门课程。",["faction:Horde"]="清除十字路口东部的害兽鸟群，直接保护了维持部落前哨站补给的脆弱贸易和补给路线。"},sec={{t="狩猎的准则",b="环绕十字路口的辽阔大草原上生活着各种陆行鸟，包括大型、迅捷和暴躁的品种。虽然与卡利姆多中部那些更凶猛的野兽相比，它们是相对容易对付的猎物，但它们极具攻击性的觅食行为使它们成为了定居点周围持续存在的害兽。塞格拉·黑刺派遣抵达的猎人带回陆行鸟的喙，以确认鸟群已被清除出重要的补给线和仓库。"}},faq={{q="为什么塞格拉·黑刺需要陆行鸟的喙？",a="塞格拉·黑刺要求猎人清除陆行鸟，因为这些极具攻击性的鸟类经常骚扰十字路口周围的食物补给。喙是狩猎成功的切实证明，用以证实对当地补给线的威胁已经减轻。",al={"为什么要收集喙","塞格拉陆行鸟喙任务","为什么是喙"}},{q="哪些生物会掉落这些喙？",a="它们取自漫步在稀树草原上的各种陆行鸟，包括贫瘠之地中的大型陆行鸟、迅捷陆行鸟和暴躁陆行鸟。",al={"什么生物掉落陆行鸟的喙","陆行鸟的喙来源","哪里可以获得喙"}},{q="为什么并不是所有的陆行鸟被杀后都会提供喙？",a="在混乱的战斗中，特别是在对抗敏捷且剧烈挣扎的鸟类时，喙往往会破裂、粉碎或变得无法作为完整的狩猎战利品使用，因此只能收集到完好的标本。",al={"为什么掉率很低","陆行鸟的喙不掉落"}}},fp="17,164,21.291.0,50.186.0,34.101.0,54.141.0"}
P.entries["item:plainstrider-feather"] = {n="平原陆行鸟的羽毛",s="平原陆行鸟的羽毛是从游荡在莫高雷平原上的敏捷鸟类身上拔下的，是红云台地上的年轻猎人们收集的必需材料。纳拉其营地的牛头人主要用它们来制作服装和部落装饰品，同时也借此向为村庄提供资源的生物表达敬意。",h="平原陆行鸟的羽毛是从游荡在莫高雷平原上的敏捷鸟类身上拔下的，是红云台地上的年轻猎人们收集的必需材料。纳拉其营地的牛头人主要用它们来制作服装和部落装饰品，同时也借此向为村庄提供资源的生物表达敬意。",kw={"纳拉其营地","羽毛","格鲁尔·鹰风","莫高雷","平原陆行鸟","红云台地","狩猎开始"},ang={["class:Hunter"]="在红云台地潜行追踪敏捷的平原陆行鸟，为新成员提供了关于耐心、追踪和尊重猎物的基石试炼。",["race:Tauren"]="对于一名年轻的牛头人来说，从平原陆行鸟身上获取羽毛是学习不浪费大地母亲馈赠的重要第一课，即利用猎物的每一个部分来制作食物和衣服。"},sec={{t="猎人的第一份献礼",b="在红云台地，年轻的牛头人很早就学会了生存依赖于敏锐的追踪和狩猎。平原陆行鸟在草原高原上肆意奔跑，提供了维持生计所需的食物和实用材料。拔下它们坚韧的羽毛可以让营地制作传统的服装和装备。将这些羽毛与鲜肉一同呈献给格鲁尔·鹰风，展现了对部落需求的尊重，这也是迈向获得鹰风酋长认可并被雷霆崖接纳的最初考验。"}},faq={{q="平原陆行鸟的羽毛有什么用途？",a="纳拉其营地的牛头人主要用它们来制作服装和仪式用品。格鲁尔·鹰风会从新手猎人那里收集羽毛，以补充部落的物资储备。",al={"羽毛用途","平原陆行鸟的羽毛使用","为什么要收集羽毛"}},{q="谁在红云台地收集平原陆行鸟的羽毛？",a="格鲁尔·鹰风代表纳拉其营地请求收集这些羽毛，以补充村庄的库存，并以此测试年轻的猎人是否具备为部落贡献所需的纪律。",al={"谁想要羽毛","谁需要羽毛","格鲁尔·鹰风 羽毛"}},{q="在哪里可以找到平原陆行鸟？",a="它们游荡在红云台地的开阔草原上，以及莫高雷的草海平原各处。",al={"哪里可以找到平原陆行鸟","平原陆行鸟位置","羽毛刷取"}},{q="为什么格鲁尔·鹰风需要这些羽毛来进行部落仪式？",a="狩猎是牛头人文化的基石，既为了生存也为了竞技。带着肉和羽毛成功归来，证明了新成员在前往雷霆崖之前，有能力维持部落的生存。",al={"狩猎开始传说","牛头人试炼狩猎","为什么狩猎平原陆行鸟"}}},fp="20,215,25.409.0,40.155.0,52.185.0,33.91.0,64.189.0"}
P.entries["item:plainstrider-kidney"] = {n="平原陆行鸟的肾脏",s="这种器官取自漫步在贫瘠之地干旱平原上行动敏捷的平原陆行鸟。尽管对大多数旅行者来说它毫无食欲，但它却是卡利姆多异域酿酒传统中一种奇特而必不可少的成分。",h="这种器官取自漫步在贫瘠之地干旱平原上行动敏捷的平原陆行鸟。尽管对大多数旅行者来说它毫无食欲，但它却是卡利姆多异域酿酒传统中一种奇特而必不可少的成分。",kw={"酿酒师德罗恩","陈·风暴烈酒","平原陆行鸟","平原陆行鸟的肾脏","棘齿城","风暴烈酒","贫瘠之地"},ang={["class:Hunter"]="在草原上对平原陆行鸟进行野外处理考验着猎人的精准度，以确保这些内脏能够完好无损地与棘齿城的酿酒师进行交易。",["profession:Cooking"]="烹饪冒险家们或许会对将禽类肾脏发酵成烈酒感到却步，但在卡利姆多，野外生存往往依赖于充分利用猎物的每一个部位。"},sec={{t="一种非传统的酿酒配料",b="贫瘠之地的广袤大地栖息着一种被称为平原陆行鸟的高大走禽。虽然猎人们经常收集它们的羽毛和肉来制作工具和简单的口粮，但棘齿城的酿酒师德罗恩却出于完全不同的目的寻找它们的内脏。据这位古怪的酿酒师所说，平原陆行鸟的肾脏是酿造陈·风暴烈酒传说中烈性麦酒的必要配料，这种配料赋予了酒水一种通过非正统酿酒师传承下来的独特后劲。"}},faq={{q="平原陆行鸟的肾脏有什么用？",a="棘齿城的酿酒师德罗恩需要它们来重现传说中的风暴烈酒。他声称这个配方是云游熊猫人酿酒大师陈·风暴烈酒亲自传授给他导师的。",al={"平原陆行鸟的肾脏用途","为什么需要平原陆行鸟的肾脏","平原陆行鸟的肾脏目的"}},{q="为什么有人会用动物内脏酿酒？",a="卡利姆多的异域佳酿经常加入当地粗犷的野生动物身体部位，以获得浓烈、令人难忘的风味和独特的后劲。酿酒师德罗恩指出，制作这种强力而狂野的配方让他不禁想起了诸如穴居人啤酒之类的非传统创作。",al={"啤酒里的肾脏","为什么风暴烈酒里要有肾脏","酒精里的动物部位"}},{q="哪些生物会掉落这些肾脏？",a="它们是从横跨贫瘠之地的各种平原陆行鸟身上采集的，包括迁徙的、暴躁的和大型的平原陆行鸟。",al={"平原陆行鸟的肾脏在哪里掉落","谁掉落平原陆行鸟的肾脏","平原陆行鸟的肾脏来源"}},{q="除了肾脏之外还需要什么配料？",a="为了完成他的调配，酿酒师德罗恩要求五份平原陆行鸟的肾脏、五枚草原狮獠牙，以及一支雷霆蜥蜴的角。",al={"其他酿酒配料","德罗恩还需要什么","风暴烈酒配料"}}},fp="19,176,32.456.0,39.207.0,46.240.0,36.136.0,56.134.0"}
P.entries["item:plainstrider-meat"] = {n="平原陆行鸟肉",s="平原陆行鸟肉是刚从漫步于莫高雷平原的这些不会飞的鸟类身上猎取的新鲜猎物。对于在红云台地进行Coming of Age的年轻牛头人而言，收集这种食物不仅是过冬的重要储备，也是核心的成人礼。",h="平原陆行鸟肉是刚从漫步于莫高雷平原的这些不会飞的鸟类身上猎取的新鲜猎物。对于在红云台地进行Coming of Age的年轻牛头人而言，收集这种食物不仅是过冬的重要储备，也是核心的成人礼。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","莫高雷","平原陆行鸟","平原陆行鸟肉","红云台地","狩猎开始"},ang={["class:Hunter"]="敏捷的平原陆行鸟在莫高雷开阔的平原上，为年轻的猎手提供了关于追踪和射术的早期考验。",["race:Tauren"]="对于踏上红云台地的牛头人青年来说，狩猎平原陆行鸟是赢得鹰风酋长尊重并获得进入雷霆崖资格的第一个实际步骤。"},sec={{t="台地的补给",b="牛头人的生活与土地息息相关，在尊重自然与生存的实际需求之间保持着平衡。在红云台地上，纳拉其营地严重依赖于从周围草原上捕获的猎物。当村庄库存不足时，平原陆行鸟肉提供了必要的食物储备，而这些鸟类的羽毛则可作为制作衣物和礼仪装饰品的材料。"},{t="年轻猎手的试炼",b="狩猎平原陆行鸟是给予那些渴望赢得部落尊重的年轻人的最初考验之一。格鲁尔·鹰风会指导满怀希望的猎手在台地上追踪这些敏捷的鸟类，收集肉和羽毛，以在面见他的父亲鹰风酋长之前证明自己的追踪技巧和自立能力。"}},faq={{q="平原陆行鸟肉有什么用途？",a="平原陆行鸟肉由红云台地的年轻猎手们收集，用以补充纳拉其营地消耗殆尽的食物储备，完成了格鲁尔·鹰风布置的一项必要任务。",al={"为什么需要平原陆行鸟肉","平原陆行鸟肉任务","平原陆行鸟肉有什么用"}},{q="谁需要这种肉？",a="鹰风酋长之子，格鲁尔·鹰风，要求初入者猎杀台地上的平原陆行鸟，以补充部落的食物供应，并证明他们作为供养者的价值。",al={"谁需要平原陆行鸟肉","格鲁尔·鹰风 肉"}},{q="在哪里可以找到平原陆行鸟肉？",a="它从漫步于莫高雷草原的不会飞的平原陆行鸟身上获取，特别是在红云台地的起伏丘陵上。",al={"哪里可以获得平原陆行鸟肉","平原陆行鸟位置","刷平原陆行鸟肉"}},{q="为什么狩猎平原陆行鸟对牛头人来说很重要？",a="牛头人狩猎既是出于实际需要，也是一种精神修行。将猎物带回营地展示了对大地母亲的尊重、自立能力，以及维持部落生存的能力。",al={"牛头人狩猎文化","为什么要狩猎平原陆行鸟"}}},fp="17,155,23.317.0,22.225.0,35.116.0,23.135.0,37.96.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="平原陆行鸟的鳞片",s="从游荡在莫高雷辽阔平原上的陆行鸟身上采集到的坚韧鳞片。它是茂尔·祈雨用来治疗某种剧烈感染的传统疗法的关键成分。",h="从游荡在莫高雷辽阔平原上的陆行鸟身上采集到的坚韧鳞片。它是茂尔·祈雨用来治疗某种剧烈感染的传统疗法的关键成分。",kw={"血蹄村","茂尔·祈雨","玛兹拉纳奇","莫高雷","陆行鸟","疗法","鳞片","长颈陆行鸟"},ang={["race:Tauren"]="从大地上收集疗法体现了莫高雷年轻猎人所学的传统生存技能，利用平原野生动物的每一个部分来维持部落的生存。"},sec={{t="稀有材料",b="虽然陆行鸟最出名的是它们柔软的羽毛和精瘦的肉，但它们强壮的双腿上覆盖着坚韧的保护性鳞片。这些鳞片足以抵御严酷的灌木丛地形和捕食者的利爪。想要找到一片完整且适合制药的鳞片需要极大的耐心，因为只有莫高雷各地极少数的陆行鸟，其鳞片才坚硬到足以研磨并制成民间偏方。"},{t="治疗毒咬的偏方",b="当血蹄村的茂尔·祈雨遇到玛兹拉纳奇——一只因邪恶的红眼和剧毒咬伤而闻名的传奇陆行鸟时，他的肩膀受到了严重的创伤。茂尔陷入了神志不清的高烧中，他需要平原陆行鸟的鳞片，配合草原狼的心脏、平原狮的腿骨和猛鹫的胃，才能在感染蔓延导致致命后果之前将其清除。"}},faq={{q="平原陆行鸟的鳞片有什么用？",a="它是收集给血蹄村的茂尔·祈雨的重要药用成分。结合莫高雷其他掠食者的身体部位，它被熬制成一种疗法，用来治疗由邪恶的陆行鸟玛兹拉纳奇造成的感染性毒伤。",al={"平原陆行鸟的鳞片有什么用","平原陆行鸟的鳞片用途","为什么要用平原陆行鸟的鳞片"}},{q="去哪里寻找平原陆行鸟的鳞片？",a="这种鳞片可以通过狩猎在整个莫高雷的开阔草原上游荡的野生平原陆行鸟来获得。",al={"平原陆行鸟的鳞片哪里获得","如何获得平原陆行鸟的鳞片","平原陆行鸟的鳞片位置"}},{q="茂尔·祈雨为什么会被感染？",a="茂尔在穿越平原时，遭到了玛兹拉纳奇的伏击，肩膀被咬伤。玛兹拉纳奇是一只因剧毒咬伤和深红色眼睛而臭名昭著的可怕陆行鸟。这次咬伤让他陷入了无法通过普通休息治愈的、不断恶化的神志不清的高烧之中。",al={"茂尔是怎么生病的","为什么茂尔会生病","玛兹拉纳奇咬伤"}},{q="茂尔的疗法还需要哪些其他成分？",a="除了平原陆行鸟的鳞片，茂尔还需要草原狼的心脏、平原狮的腿骨和猛鹫的胃来完成这种药剂的配制。",al={"茂尔·祈雨的药材","玛兹拉纳奇的解药","玛兹拉纳奇的任务物品"}}},fp="18,157,17.160.0,28.325.1,40.206.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="平原陆行鸟的爪子",s="平原陆行鸟的爪子是一种从莫高雷本土大型、不会飞行的平原陆行鸟身上收集的锋利爪子。牛头人萨满在土地的水源遭到污染时，会使用这些爪子并结合其他自然试剂来制作神圣的净化图腾。",h="平原陆行鸟的爪子是一种从莫高雷本土大型、不会飞行的平原陆行鸟身上收集的锋利爪子。牛头人萨满在土地的水源遭到污染时，会使用这些爪子并结合其他自然试剂来制作神圣的净化图腾。",kw={"血蹄村","净化图腾","莫高雷","穆尔·雷角","平原陆行鸟","平原陆行鸟的爪子","污染水源","冰蹄水井"},ang={["class:Shaman"]="使用爪子等野兽的肢体部位来制作净化图腾，体现了牛头人传统的萨满修行，直接从这片土地的本土灵魂中汲取力量。",["race:Tauren"]="尊重莫高雷野生动物的牺牲是牛头人狩猎的核心，确保当遭遇地精的剥削时，每一个被猎杀的野兽都能帮助治愈大地母亲。"},sec={{t="平原的羁绊",b="大型且不会飞的平原陆行鸟游荡在莫高雷的开阔草地上，依靠强壮的双腿和锋利的爪子抵御掠食者，并在坚硬的草原土地上觅食。对于血蹄村的牛头人来说，狩猎野兽的每一个部位都带有精神共鸣。当荆棘谷地精污染了冰蹄水井等神圣源头时，萨满穆尔·雷角就在寻求平原陆行鸟的爪子和草原狼爪。在牛头人的仪式制作中，从本土掠食者和食腐动物身上收集试剂，可以让土地的精神精华被引导至能够净化非自然毒素的图腾中。"}},faq={{q="哪些生物会掉落平原陆行鸟的爪子？",a="平原陆行鸟的爪子可以从成年平原陆行鸟、平原陆行鸟长者以及臭名昭著的陆行鸟马兹拉纳奇身上收集，它们遍布莫高雷的草原。",al={"谁掉落平原陆行鸟的爪子","哪里获得平原陆行鸟的爪子","平原陆行鸟的爪子来源"}},{q="平原陆行鸟的爪子有什么用？",a="血蹄村的穆尔·雷角需要平原陆行鸟的爪子和草原狼爪来制作净化图腾，用于净化遭到污染的冰蹄水井。",al={"平原陆行鸟的爪子用途","为什么需要爪子","平原陆行鸟的爪子任务"}},{q="为什么穆尔·雷角需要动物部位来净化水源？",a="牛头人萨满教义依赖于与莫高雷自然之灵的和谐。通过将当地野生动物的元素结合到仪式图腾中，萨满可以召唤土地本身的原始力量，以击退荆棘谷地精引入的外来污染物。",al={"为什么需要动物爪","萨满净化仪式之爪"}},{q="是谁毒害了莫高雷的水井？",a="地精——具体说是活跃在莫高雷的荆棘谷地精的代理人——以及他们的爪牙污染了神圣的部落水井，破坏了当地环境并威胁着牛头人部落。",al={"谁污染了水井","谁毒害了莫高雷的水源","水污染罪魁祸首"}}},fp="18,192,19.575.0,41.136.0,38.163.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="博迪瑞格的订单",s="“博迪瑞格的订单”是一份由亡灵卫兵博迪瑞格在瑟伯切尔写下的军需申领单。它要求幽暗城的商人高顿·温德哈姆运送一批新的武器，以保证银松森林的被遗忘者驻军拥有充足的武装。",h="“博迪瑞格的订单”是一份由亡灵卫兵博迪瑞格在瑟伯切尔写下的军需申领单。它要求幽暗城的商人高顿·温德哈姆运送一批新的武器，以保证银松森林的被遗忘者驻军拥有充足的武装。",kw={"高顿·温德哈姆","哈德瑞克","卡洛斯·拉佐克","博迪瑞格","博迪瑞格的订单","瑟伯切尔","银松森林"},ang={["profession:Blacksmithing"]="在战斗持续消耗驻军物资的前线，锻造好的武器至关重要。",["race:Undead"]="这份申领单突显了幽暗城与瑟伯切尔等外围哨所之间的后勤生命线，确保了黑暗女王的士兵能够有足够的装备来对抗天灾军团。"},sec={{t="武装瑟伯切尔",b="银松森林对于被遗忘者而言是一处危险的前线，他们夹在不断入侵的天灾军团、野兽以及其他潜伏的威胁之间。在执行官哈德瑞克下令由亡灵卫兵博迪瑞格进行装备清点后，人们发现瑟伯切尔的库存虽然大多尚可，但急需补充武器。这份官方公文详细列出了维持驻守该哨所的亡灵卫兵们所需刀剑与装备。"},{t="经由蝙蝠管理员发送",b="由于在银松森林潮湿的地下墓穴中难以锻造武器，这份请求被发往幽暗城贸易区（Trade Quarter）的武器商高顿·温德哈姆。为了加快处理速度，信使将文件直接送交蝙蝠管理员卡洛斯·拉佐克，利用被遗忘者的飞行路线从首都进行快速补给。"}},faq={{q="“博迪瑞格的订单”上写了什么？",a="这是一份正式的申领单，列出了驻扎在瑟伯切尔的亡灵卫兵在常规战场损耗后所需要的武器补给。",al={"订单上写了什么","博迪瑞格的订单内容","博迪瑞格订单详情"}},{q="谁写了“博迪瑞格的订单”？",a="它是在执行官哈德瑞克的指示下，由亡灵卫兵博迪瑞格在清点瑟伯切尔军械库后起草的。",al={"谁写的","博迪瑞格订单的作者"}},{q="谁收到了这份订单？",a="它是发给在幽暗城贸易区（Trade Quarter）从事经营活动的武器商高顿·温德哈姆的。",al={"谁收到订单","博迪瑞格订单去往哪里","博迪瑞格订单的收件人"}},{q="为什么瑟伯切尔需要新武器？",a="在银松森林中，针对天灾军团和其他敌对势力的频繁小规模战斗，经常导致守卫的亡灵卫兵装备损坏或遗失。",al={"为何需要武器","瑟伯切尔武器短缺"}}},fp="14,76,20.337.0,24.276.0,34.128.0,25.111.0,23.96.0,40.151.0"}
P.entries["item:pork-belly-pie"] = {n="猪肉馅饼",s="猪肉馅饼是一种咸味的家常菜，由艾尔文森林的“伯妮斯”斯通菲尔德阿姨烘焙而成。尽管斯通菲尔德家族和马科伦家族之间有着长期且痛苦的世仇，但年轻的比利·马科伦却无法抗拒伯妮斯阿姨的手艺，他要求得到一个馅饼作为贿赂，才会透露关于一件失传的家族传家宝的信息。",h="猪肉馅饼是一种咸味的家常菜，由艾尔文森林的“伯妮斯”斯通菲尔德阿姨烘焙而成。尽管斯通菲尔德家族和马科伦家族之间有着长期且痛苦的世仇，但年轻的比利·马科伦却无法抗拒伯妮斯阿姨的手艺，他要求得到一个馅饼作为贿赂，才会透露关于...",kw={"伯妮斯·斯通菲尔德阿姨","回到比利那里","比利·马科伦","艾尔文森林","马科伦","猪肉馅饼","斯通菲尔德"},ang={["faction:Alliance"]="对于帮助艾尔文森林农村地区的联盟旅行者来说，像运送馅饼这样的跑腿任务，揭示了分裂暴风城农业中心地带那些琐碎却根深蒂固的争吵。",["profession:Cooking"]="这个馅饼突显了家常的舒适食物如何在当地争端中产生真正的作用，即使食谱本身仍然是伯妮斯阿姨严守的秘密。"},sec={{t="农场世仇间的贿赂",b="斯通菲尔德家族和马科伦家族在艾尔文森林的腹地为土地和尊严争执不休，积怨已久。尽管有着这样的敌意，年轻的比利·马科伦却有一个明显的弱点：他非常喜欢伯妮斯阿姨著名的猪肉馅饼。当一件贵重的家族项链丢失后，在冒险者送来一块热气腾腾的馅饼之前，比利拒绝分享他所知道的信息。伯妮斯虽然极不情愿——甚至尖刻地希望这个贪吃的小子被馅饼噎住——但这也证明了烹饪名声有时确实能打破最顽固的家族世仇。"}},faq={{q="猪肉馅饼有什么用？",a="这个馅饼是由伯妮斯·斯通菲尔德阿姨烘焙，用来贿赂年轻的比利·马科伦的。比利掌握着斯通菲尔德家族丢失的传家宝项链的关键线索，但他拒绝开口，直到他用伯妮斯阿姨做的菜满足了自己的胃口。",al={"馅饼用途","为什么是猪肉馅饼","馅饼怎么用"}},{q="谁烤了猪肉馅饼？",a="这个馅饼是伯妮斯·斯通菲尔德阿姨在斯通菲尔德农场新鲜烘焙的。尽管她非常厌恶比利·马科伦和他的家人，但为了找回丢失的家族项链，她还是做了这个馅饼。",al={"谁做的馅饼","馅饼烘焙师","斯通菲尔德奶奶的馅饼"}},{q="为什么比利·马科伦想要敌对家族的食物？",a="尽管斯通菲尔德家族和马科伦家族之间的世仇激烈而喧闹，但伯妮斯阿姨的厨艺在整个山谷都很有名。比起坚持家族的恩怨，比利更关心他的胃和美味的猪肉馅饼。",al={"为什么比利想要馅饼","为什么马科伦想要斯通菲尔德的食物"}},{q="玩家可以吃猪肉馅饼吗？",a="不能。这个馅饼是专为比利·马科伦准备的任务物品。无论听起来多么诱人，你都不能亲自食用它来恢复生命值或法力值。",al={"我能吃吗","猪肉馅饼可以吃吗"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="蓝铜粉",s="蓝铜粉是一种从希尔斯布莱德丘陵的碧玉矿洞中开采出来的矿石粉末试剂。军械大师瑟恩格里姆·火眼一直在寻找这种材料，用来淬炼并锻造适合部落勇士的残暴盔甲。",h="蓝铜粉是一种从希尔斯布莱德丘陵的碧玉矿洞中开采出来的矿石粉末试剂。军械大师瑟恩格里姆·火眼一直在寻找这种材料，用来淬炼并锻造适合部落勇士的残暴盔甲。",kw={"碧玉矿洞","蓝铜","残暴盔甲","希尔斯布莱德","蓝铜粉","试剂","瑟恩格里姆·火眼"},ang={["class:Warrior"]="获取蓝铜粉证明了你在远方的坚韧，收集瑟恩格里姆·火眼锻造狂野力量盔甲所需的专业试剂。",["faction:Horde"]="想要获得这种精炼粉末，就需要深入东部王国，直接从希尔斯布莱德丘陵的联盟手中夺取资源。"},sec={{t="一种稀有矿物化合物",b="蓝铜粉是一种从希尔斯布莱德丘陵地下的矿脉中提炼出来的粉末。碧玉矿洞的人类工人们深入地下开采这种独特的蓝色矿石，将其粉碎并打包，用于贸易和冶金。在技艺精湛的铁匠手中，这种粉末在加工高密度金属时能作为关键的助熔剂或添加剂，增强成品的耐久度，并赋予盔甲独特的韧性。"},{t="锻造残暴盔甲",b="虽然蓝铜粉原产于无尽之海彼岸由人类控制的隧道中，但部落的老牌铁匠们早已认可了它卓越的冶金特性。定居在贫瘠之地的年迈兽人军械师瑟恩格里姆·火眼，要求供应少量的这种矿石粉末，并搭配精铁和烈性试剂使用。将这种粉末混入熔炼过程，让他得以锻打出厚重而致命的板甲，这也是他大师级战斗盔甲的标志。"}},faq={{q="蓝铜粉有什么用途？",a="它是驻扎在贫瘠之地的军械大师瑟恩格里姆·火眼不可或缺的冶金组件。他将这种矿石粉末与铁锭以及易挥发的试剂结合，为部落的勇士们锻造出残暴盔甲。",al={"蓝铜粉用途","什么是蓝铜粉"}},{q="去哪里可以找到蓝铜粉？",a="它是由在东部王国希尔斯布莱德丘陵南海岸的碧玉矿洞中劳作的人类矿工开采出来的。",al={"哪里能找到蓝铜粉","蓝铜粉位置","谁掉落蓝铜粉"}},{q="为什么在贫瘠之地的军械师需要来自希尔斯布莱德的试剂？",a="瑟恩格里姆·火眼致力于寻找最优质的材料来打造配得上传奇勇士的盔甲。虽然铁并不难找，但碧玉矿洞的矿石所带来的特殊淬火品质，让他认为值得派遣勇士跨越重洋去获取它。",al={"为什么选择希尔斯布莱德","瑟恩格里姆矿石来源"}}},fp="16,151,23.270.0,20.352.0,34.132.0,36.132.0,67.212.0"}
P.entries["item:powers-of-the-void"] = {n="虚空灵能",s="《虚空灵能》是一本稀有的魔法典籍，原本保存在北郡修道院图书馆的禁书区。在一名变节的见习牧师偷走它并投靠迪菲亚潜行者之后，术士导师杜希拉·拉萨雷便试图将其追回，以进一步研习暗影魔法。",h="《虚空灵能》是一本稀有的魔法典籍，原本保存在北郡修道院图书馆的禁书区。在一名变节的见习牧师偷走它并投靠迪菲亚潜行者之后，术士导师杜希拉·拉萨雷便试图将其追回，以进一步研习暗影魔法。",kw={"迪菲亚潜行者","杜希拉·拉萨雷","小鬼","卡德加","北郡修道院","虚空灵能","被盗的书籍","被盗的典籍","术士"},ang={["class:Warlock"]="追回这本被盗的魔法书是年轻人类术士的基础测试，展现出足够的意志力方能获得召唤小鬼的秘密。",["race:Human"]="这本书在北郡的出现揭示了圣光会不仅保存着标准的教会文献，还收藏着危险的魔法记录，并将它们从学徒的视线中隐藏起来。"},sec={{t="一本北郡的禁书",b="北郡修道院的档案馆里收藏的远不止圣言和教会记录。在修道院图书馆的一个受保护区域内，存放着《虚空灵能》，这是一部关于暗影和虚空能量的学术著作，据推测是由大法师卡德加撰写。鉴于此类研究的危险性，修道院当局将其严加看管，并严禁普通访客接触。这使得北郡当地的术士导师杜希拉·拉萨雷无法染指此书，因为她一旦在禁书区附近徘徊，就会引起牧师们的怀疑。"},{t="迪菲亚的盗窃与追回",b="这本书最终离开了修道院，并非杜希拉亲自动手，而是源于内部的背叛。一名在北郡学习的见习牧师放弃了誓言，加入了迪菲亚潜行者，在逃往邻近的北郡农场时顺手牵羊带走了几本珍贵的书籍。杜希拉利用了窃贼的机会主义心理，派遣那些有前途的术士学徒直接潜入迪菲亚的强盗营地，从他们的帐篷里夺回这本书。追回这部典籍有着双重目的：既能让导师掌握这些黑暗知识，又能测试学徒是否拥有奴役异界恶魔所需的胆识。"}},faq={{q="什么是《虚空灵能》？",a="这是一本罕见的神秘学著作，详细介绍了黑暗能量和虚空概念，据信由大法师卡德加所写。它在被盗之前一直被锁在北郡修道院的禁书区内。",al={"什么是虚空灵能","虚空灵能之书","什么是被盗的典籍"}},{q="为什么这本书会被锁在北郡修道院里？",a="北郡修道院保存着历史档案，其中包括关于非法魔法的危险文献。详细记录虚空能量和恶魔学的书籍被严加锁好，以防止学徒和误入歧途的修行者滥用它们。",al={"为什么它在修道院里","牧师为什么会有它","北郡图书馆禁书区"}},{q="迪菲亚潜行者是如何得到这本书的？",a="一名修道院的见习牧师变节加入了迪菲亚潜行者，并从北郡的禁书图书馆带走了几本珍贵的书籍，将它们藏在北郡农场的强盗营地里。",al={"谁偷了书","迪菲亚偷窃的书籍","迪菲亚是如何得到它的"}},{q="为什么杜希拉·拉萨雷想要《虚空灵能》？",a="杜希拉是北郡常驻的术士导师。她觊觎书中深奥的知识以用于自己的黑暗法术，但如果她进入修道院戒备森严的图书馆档案馆，肯定会引发警报。",al={"为什么杜希拉想要它","谁想要这本书","杜希拉·拉萨雷与被盗典籍"}},{q="追回这本书向杜希拉证明了什么？",a="夺回这本书向杜希拉证明了学徒拥有指挥恶魔仆从所需的狡黠、力量和决心，从而使他们获得召唤第一个小鬼的指引。",al={"为什么术士需要这本书","召唤小鬼测试","被盗典籍奖励"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="草原狼前锋的牙齿",s="草原狼前锋的牙齿取自徘徊在雷霆崖周围平原上的凶猛狼群首领。在牛头人的传统中，这些牙齿被作为强力的祭品，用于净化和敬奉这片土地上珍贵的水源。",h="草原狼前锋的牙齿取自徘徊在雷霆崖周围平原上的凶猛狼群首领。在牛头人的传统中，这些牙齿被作为强力的祭品，用于净化和敬奉这片土地上珍贵的水源。",kw={"血蹄村","莫高雷","穆尔·雷角","草原狼前锋的牙齿","草原狼前锋","水井","狂鬃图腾"},ang={["class:Shaman"]="水井的灵魂必须通过大地的平衡来安抚，献上顶级掠食者的獠牙能稳固这种自然的和谐。",["race:Tauren"]="取下草原狼前锋的獠牙代表了猎人神圣的职责，即怀着敬意收获所需之物，并将这种原始的精粹归还给大地，以治愈受污染的土地。"},sec={{t="净化祭品",b="莫高雷的水井是牛头人的生命线，维护其精神上的纯净需要通过尊重与牺牲的仪式。为了净化狂鬃水井，血蹄村的穆尔·雷角需要收集潜伏在雷霆崖阴影下的草原狼前锋的牙齿。作为广袤草原上的顶级掠食者，这些前锋代表了荒野最原始的力量。献上它们的牙齿是对猎人、猎物以及大地之灵之间平衡的致敬。"}},faq={{q="草原狼前锋的牙齿有什么用途？",a="穆尔·雷角在净化狂鬃水井的仪式中需要用到八颗这样的牙齿，这是血蹄村附近最后一处被污染的水井。",al={"前锋牙齿的用途","莫高雷的狼牙有什么用","狂鬃图腾物品"}},{q="草原狼前锋在哪里徘徊？",a="草原狼前锋在莫高雷中部和北部的开阔草原上游荡，尤其是在雷霆崖基座周围的峭壁附近徘徊。",al={"草原狼前锋在哪里","狼王位置","草原狼前锋出没点"}},{q="为什么净化水井的仪式需要狼牙？",a="牛头人的仪式尊崇自然的平衡。净化水井需要直接从这片土地上凶猛的本土野兽身上获取神圣的材料，这象征着莫高雷野生动物的牺牲与生命力。",al={"为什么净化水源需要狼牙","穆尔·雷角的牙齿仪式背景"}}},fp="19,136,20.384.0,39.141.0,34.139.0,53.175.0"}
P.entries["item:prairie-wolf-heart"] = {n="草原狼的心脏",s="草原狼的心脏是从莫高雷草原上漫游的狼身上采集的重要器官。它是茂尔·祈雨在血蹄村调配的一种紧急民间药方中不可或缺的成分，用于对抗毒素感染。",h="草原狼的心脏是从莫高雷草原上漫游的狼身上采集的重要器官。它是茂尔·祈雨在血蹄村调配的一种紧急民间药方中不可或缺的成分，用于对抗毒素感染。",kw={"血蹄村","茂尔·祈雨","玛兹拉纳赫","莫高雷","草原潜行者","草原狼的心脏","狼心"},ang={["class:Hunter"]="在平原上追踪特定的狼群展示了对莫高雷狩猎对象和野兽生态的初步了解。",["race:Tauren"]="使用采集的动物部位来配制生存疗法，反映了牛头人在莫高雷荒野中务实且脚踏实地的传统。"},sec={{t="毒咬的疗法",b="平原上的狼是凶猛的掠食者，在莫高雷一望无际的草原上顽强地生存。茂尔·祈雨是一位居住在血蹄村的牛头人，他成了传说中的平原陆行鸟——玛兹拉纳赫的受害者，因此急需这些狼心。茂尔被那种生物带有剧毒且会引发高烧的毒液击中，他依靠传统的平原医药来阻止毒素蔓延。除了美洲狮骨和鸟胃等强效试剂外，刚被猎杀的草原狼身上提取的生命精华提供了所需的净化特性，以便在谵妄导致死亡之前配制出解药。"}},faq={{q="草原狼的心脏有什么用？",a="它是为血蹄村的茂尔·祈雨采集的。茂尔需要它和其他几种动物部位来酿制强效民间药物，以治疗臭名昭著的陆行鸟玛兹拉纳赫所造成的毒咬伤。",al={"狼心的用途","为什么需要狼心","草原狼心脏的目的"}},{q="从哪里可以获得草原狼的心脏？",a="它是从在莫高雷草海平原上猎食的草原狼、草原狼首领和草原潜行者尸体上获取的。",al={"狼心的位置","谁掉落狼心","如何找到草原狼的心脏"}},{q="为什么茂尔·祈雨需要动物器官来治疗他的伤口？",a="玛兹拉纳赫会造成可怕的感染性咬伤，导致高烧和谵妄。茂尔使用由强效试剂组成的传统牛头人平原疗法——狼心、美洲狮股骨、平原陆行鸟的鳞片和猛鹫的胃——来清除感染，防止其致命。",al={"为什么用狼心入药","茂尔的疗法"}},{q="任何狼心都可以用于这种疗法吗？",a="茂尔·祈雨只要求普通的狼心。用于疗法的狼心取自猎食莫高雷平原的草原狼、草原狼首领或草原潜行者。",al={"任何狼心都可以吗","哪些狼掉落它"}}},fp="18,91,28.355.0,38.170.0,43.125.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="草原狼的爪子",s="草原狼的爪子是从游荡在莫高雷平原上的掠食者身上采集的。像血蹄村的穆尔·雷角这样的萨满祭司，将它们用作有机材料，将大地的自然力量束缚在净化图腾中。",h="草原狼的爪子是从游荡在莫高雷平原上的掠食者身上采集的。像血蹄村的穆尔·雷角这样的萨满祭司，将它们用作有机材料，将大地的自然力量束缚在净化图腾中。",kw={"血蹄村","莫高雷","穆尔·雷角","平原陆行鸟的爪子","毒水","草原狼","草原狼的爪子","冰蹄水井"},ang={["class:Shaman"]="用当地动物的身体部位制作净化图腾，体现了利用大地的生命精髓来清除反自然腐蚀的元素原则。",["race:Tauren"]="对于牛头人来说，收获狼爪是一项神圣的管理职责，召唤土地上的原生野兽来治愈被地精贪婪所污染的祖先水井。"},sec={{t="平原的自然试剂",b="草原狼潜行在莫高雷的起伏草地上，与草原潜行者及其族群首领结群捕猎。虽然它们对年轻的猎人和当地的牲畜构成威胁，但这些生物与平原的精神平衡息息相关。牛头人萨满不仅将狼爪视为战利品，更视其为大地内在活力的重要传导物。"},{t="净化水井",b="当地精的冒险生意污染了莫高雷的神圣水资源储备时，萨满祭司穆尔·雷角需要借助土地本身的物理援助来抵消污染。狼爪与陆行鸟爪结合在一起，提供了制造净化图腾所需的原始精神共鸣，从而开始了净化冰蹄水井这一至关重要的工作。"}},faq={{q="什么生物会掉落草原狼的爪子？",a="它们是从在莫高雷平原上捕猎的草原狼、草原潜行者和草原狼首领身上采集的，主要位于血蹄村的西南部。",al={"谁掉落草原狼的爪子","在哪里获得草原狼的爪子","草原狼的爪子来源"}},{q="谁需要草原狼的爪子？",a="驻扎在血蹄村的牛头人萨满穆尔·雷角，请求采集这些物品以帮助制作净化图腾，从而恢复被污染的水井。",al={"谁需要草原狼的爪子","穆尔·雷角 狼爪","草原狼的爪子交还"}},{q="为什么净化水源需要狼爪？",a="牛头人萨满教义依赖于引导大地的自然活力来抵消腐蚀。狼爪与鸟爪结合，使萨满能够将莫高雷的生命之灵束缚在能够清除地精毒素的元素图腾中。",al={"为什么需要狼爪","草原狼的爪子背景故事","穆尔为什么要爪子"}},{q="这些爪子有助于净化哪口水井？",a="这些爪子是专门为冰蹄水井制作净化图腾而收集的，该水井已被地精入侵者及其代理人投毒。",al={"哪口井","冰蹄水井净化"}}},fp="16,184,30.334.0,19.314.0,39.162.0,28.126.0,42.198.0,44.116.0"}
P.entries["item:pridewing-venom-sac"] = {n="巨翼双足飞龙的毒囊",s="巨翼双足飞龙的毒囊是从石爪山脉暗色湖周围筑巢的致命双足飞龙身上采集而来的。阿斯特兰纳的暗夜精灵试图在情报显示部落特工采集这种强力毒素用于秘密暗杀后，将这些毒囊囤积并销毁。",h="巨翼双足飞龙的毒囊是从石爪山脉暗色湖周围筑巢的致命双足飞龙身上采集而来的。阿斯特兰纳的暗夜精灵试图在情报显示部落特工采集这种强力毒素用于秘密暗杀后，将这些毒囊囤积并销毁。",kw={"阿斯特兰纳","暗色湖","巨翼双足飞龙","辛德瑞尔·速火","石爪山脉","毒囊","双足飞龙"},ang={["faction:Alliance"]="拒绝让部落获取巨翼双足飞龙的毒液，对于保护石爪山脉和灰谷交界地带的前线巡逻队免受隐形刺客的袭击至关重要。",["race:NightElf"]="虽然哨兵领导层对不得不捕杀无辜的野生野兽感到遗憾，但为了保护精灵的生命免受涂毒刀刃的伤害，这一点比维持自然和谐更为重要。"},sec={{t="峭壁上的威胁",b="石爪山脉的巨翼双足飞龙是一种危险的飞行捕食者，它们栖息在灰谷南部的山峰上，特别是在暗色湖周围。虽然野生的双足飞龙天生带有剧毒，但来自塞拉摩的联盟情报显示，部落刺客已经开始采集它们的毒液，用于涂抹在针对暗夜精灵定居点的秘密突袭中所使用的刀刃上。为了保护族人并扰乱敌人的补给，阿斯特兰纳的哨兵雇佣斥候在部落获取毒液之前猎杀这些野兽并收集毒腺。"}},faq={{q="什么生物会掉落巨翼双足飞龙的毒囊？",a="这些毒囊是从居住在石爪山脉暗色湖附近峭壁上的各种双足飞龙身上获取的，包括幼年巨翼双足飞龙、天猎者、族群首领和配偶。",al={"在哪里获取巨翼双足飞龙的毒囊","谁掉落巨翼双足飞龙的毒囊","巨翼双足飞龙的毒素来源"}},{q="为什么阿斯特兰纳想要巨翼双足飞龙的毒囊？",a="辛德瑞尔·速火收到报告称，部落特工采集巨翼双足飞龙的毒液，用于涂抹在针对联盟的秘密暗杀中所使用的武器上。销毁或没收这些毒腺可以先发制人，阻止这些袭击。",al={"为什么要收集毒囊","辛德瑞尔·速火 毒液"}},{q="在灰谷是谁在收集这些毒囊？",a="驻扎在灰谷暗夜精灵城镇阿斯特兰纳的辛德瑞尔·速火，负责收集这些毒囊以保护她的人民免受秘密袭击。",al={"谁接收巨翼双足飞龙毒液","巨翼双足飞龙任务交还"}},{q="巨翼双足飞龙是部落的盟友吗？",a="不是。暗色湖周围的野生巨翼双足飞龙是野兽，它们不会主动帮助部落，尽管兽人特工利用它们带毒的生物特性来服务于自己的战争。",al={"巨翼双足飞龙属于部落吗","巨翼双足飞龙为兽人工作吗"}}},fx={e2bba8d5={q="什么是巨翼双足飞龙的毒囊？",a="巨翼双足飞龙的毒囊是一种从栖息在石爪山脉的巨翼双足飞龙身上采集的器官，其中含有这些长翼掠食者用来制服猎物的强效天然毒素。在暗夜精灵与部落脆弱的对峙中，这种毒液已成为备受青睐的秘密袭击武器，阿斯特兰纳的守卫因此提高了警惕。",al={"巨翼双足飞龙的毒囊是什么","巨翼双足飞龙的毒囊物品","巨翼双足飞龙的毒囊有哪些"}},["816b56c2"]={q="巨翼双足飞龙的毒囊来自哪里？",a="这些毒囊直接取自巨翼双足飞龙的身体——它们是凶猛的野生双足飞龙，栖居在石爪山脉的暗色湖附近。毒囊是野兽自身产生的天然器官，并非人工制品，因此必须在峭壁间猎杀双足飞龙，并赶在部落特工采集之前取出毒液。",al={"巨翼双足飞龙的毒囊来源","巨翼双足飞龙的毒囊来自哪里","哪些生物掉落巨翼双足飞龙的毒囊"}}},fp="19,205,21.468.0,43.99.0,45.192.0,42.133.0,51.135.0"}
P.entries["item:prismatic-punch-card"] = {n="彩色穿孔卡片",s="彩色穿孔卡片是诺莫瑞根这座陷落城市中级别最高的安全访问数据卡。通过一系列矩阵打孔机终端进行循序升级，它存储着铁炉堡的侏儒难民们迫切寻求的数据。",h="彩色穿孔卡片是诺莫瑞根这座陷落城市中级别最高的安全访问数据卡。通过一系列矩阵打孔机终端进行循序升级，它存储着铁炉堡的侏儒难民们迫切寻求的数据。",kw={"卡斯派普","数据救援","engineering labs","诺莫瑞根","矩阵打孔机","彩色穿孔卡片"},ang={["profession:Engineering"]="这种循序的穿孔卡片编程和自动化终端网络展示了诺莫瑞根的工匠们所建造的极高水平的计算机械。",["race:Gnome"]="这套复杂的打孔机安全系统是侏儒独创性和官僚主义的典范，即使在他们的家园沦陷后，依然未受干扰地留存了下来。"},sec={{t="安全问题",b="当侏儒们因穴居人入侵和诺莫瑞根的剧毒辐射而逃离家园时，大量的研究成果和市政记录被遗弃在城市深处。为了保护高等级系统，侏儒们使用了一套递进式的安全协议。访问位于下层Engineering Labs的矩阵打孔机3005-D终端，需要通过一系列穿孔卡片的循序升级来完成：从基础的白色穿孔卡片开始，在专用终端上依次通过黄色、蓝色和红色权限的升级，最终打孔制成彩色穿孔卡片。其编码的权限等级被异想天开地标注为“等待发明出一个全新的数字”。"},{t="重要的传输",b="大机械师卡斯派普目前驻扎在铁炉堡的难民区，他派遣勇敢的冒险者深入诺莫瑞根被污染的大厅，执行一项关键的数据回收任务。虽然卡斯派普称这些目标数据至关重要，生活中不可或缺，但印在最终彩色卡片上的二进制解码信息却揭示了一个关于侏儒日常市政生活的有趣真相：那是一条自动通知，告知卡斯派普他的衣物已经洗好，可以去领取了。"}},faq={{q="如何制作彩色穿孔卡片？",a="你可以通过将红色穿孔卡片插入位于诺莫瑞根下层Engineering Labs的矩阵打孔机3005-D终端来获得彩色穿孔卡片。达到这一阶段需要将基础的白色穿孔卡片在整个副本中的A、B、C型终端上进行循序升级。",al={"如何获得彩色穿孔卡片","制作彩色穿孔卡片","穿孔卡片升级顺序"}},{q="彩色穿孔卡片中存储了什么数据？",a="卡片声称其安全等级之高，需要等待发明一个新的数字才能定义，后面跟着一长串二进制代码。大机械师卡斯派普坚称这些数据至关重要。",al={"卡片上写了什么","穿孔卡片二进制翻译","解码后的穿孔卡片"}},{q="谁需要彩色穿孔卡片？",a="居住在铁炉堡的流亡侏儒工程师大机械师卡斯派普在任务“数据救援”中需要这张卡片。他认为卡片的内容是撤离诺莫瑞根时遗留下来的紧急且无价的信息。",al={"谁来上交彩色穿孔卡片","卡斯派普任务","谁需要这张卡片"}},{q="矩阵打孔机终端位于何处？",a="这些终端根据权限等级散布在诺莫瑞根各处。打孔机3005-A位于靠近地表的Train Depot和Workshop Entrance附近，B型位于Clean Zone后的宿舍区，C型位于副本更深处，而D型则位于下层的Engineering Labs。",al={"终端位置","打孔机在哪里","在哪里打孔"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-spider-silk"] = {n="新鲜的蜘蛛丝",s="新鲜的蜘蛛丝是从暮色森林的毒蛛身上采集而来的一种极其细致的丝线。暴风城的法师们委托采集这种珍稀材料，用以编织耐用且附魔的法袍，以匹配奥术艺术的资深修行者。",h="新鲜的蜘蛛丝是从暮色森林的毒蛛身上采集而来的一种极其细致的丝线。暴风城的法师们委托采集这种珍稀材料，用以编织耐用且附魔的法袍，以匹配奥术艺术的资深修行者。",kw={"黑寡妇幼蛛","食腐隐蛛","暮色森林","法师法袍","新鲜的蜘蛛丝","法师区","维恩·拉尔森"},ang={["class:Mage"]="暴风城的法师被直接派往暮色森林采集这些新鲜的丝线，作为获得适合其日益增长的奥术地位的法袍的一种试炼。",["profession:Tailoring"]="这些细腻而坚韧的丝线是从致命的蛛形生物身上采集的，代表了用于编织魔法服饰的天然纺织品的巅峰。"},sec={{t="奥术编织",b="并非随便什么丝线都能承受奥术法师所要求的附魔与磨损。虽然普通的蜘蛛丝在裁缝中很常见，但只有从暮色森林阴暗丛林中的食腐隐蛛和黑寡妇幼蛛身上获取的无瑕蛛丝才具备必要的韧性。暴风城法师区的法师们派遣他们刚崭露头角的学徒进入这些危险的丛林去收集新鲜的丝线，并委托当地的裁缝大师维恩·拉尔森将这些材料缝制成适合学徒穿戴的服饰。"}},faq={{q="新鲜的蜘蛛丝来自哪里？",a="它采集自潜伏在暮色森林中的蛛形纲生物，特别是那些在阴沉树冠下筑巢的食腐隐蛛和黑寡妇幼蛛。",al={"哪里可以获得新鲜的蜘蛛丝","谁掉落新鲜的蜘蛛丝","新鲜的蜘蛛丝地点"}},{q="谁用这种丝制作服饰？",a="维恩·拉尔森，一位在暴风城法师区经营的裁缝，他代表法师区将收集到的丝线缝制成精致的法袍。",al={"谁使用新鲜的蜘蛛丝","谁将丝线织成法袍","维恩·拉尔森法袍"}},{q="为什么法师需要这种特定的丝线？",a="法师们需要能反映他们日益增长的奥术造诣的服饰。只有来自暮色森林致命蜘蛛身上最纯净、无损的丝线，才能为学徒的法袍提供必要的强度和质量。",al={"为什么使用新鲜的蜘蛛丝","魔法蜘蛛丝的用途"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:prowler-claws"] = {n="徘徊者的爪子",s="徘徊者的爪子是收集自徘徊在贫瘠之地焦灼平原上的草原徘徊者的战利品。将其带给十字路口的塞格拉·黑棘，便是猎人能够追踪并制服卡利姆多最致命潜行掠食者的有力证明。",h="徘徊者的爪子是收集自徘徊在贫瘠之地焦灼平原上的草原徘徊者的战利品。将其带给十字路口的塞格拉·黑棘，便是猎人能够追踪并制服卡利姆多最致命潜行掠食者的有力证明。",kw={"贫瘠之地","十字路口","徘徊者的爪子","贫瘠之地的徘徊者","草原徘徊者","塞格拉·黑棘"},ang={["class:Hunter"]="击杀草原徘徊者并获得它们的爪子，是寻求学习潜行、追踪和近身野兽驯服艺术的年轻猎手的必经之路。",["faction:Horde"]="清除十字路口周围危险的徘徊者，有助于保护穿行在卡利姆多中部危险道路上的部落信使、商队和定居者。"},sec={{t="猎手的战利品",b="贫瘠之地的高草丛中潜藏着草原徘徊者，这是一种大型猫科掠食者，以耐心、狡猾和致命的突袭而闻名。猎杀它们是部落初出茅庐的战士和斥候的重要试炼。不同于平原陆行鸟或斑马等食草猎物，徘徊者会主动伏击任何进入其狩猎场的生物。获取它们锋利且弯曲的爪子，意味着必须击败这种依赖绝对隐蔽和领地攻击性的生物，向营地的女猎手证明猎人已反客为主。"},{t="给女猎手的证明",b="在十字路口，塞格拉·黑棘要求获取这些爪子，以衡量新兵是否准备好迎接更大的试炼。带回一把爪子证明了猎人已经掌握了在金色草原草丛中的追踪技巧，并能抵挡得住足以撕裂皮革与血肉的利爪。那些带着战利品归来的人证明了自己拥有在平原上潜伏的更致命野兽面前生存所需的警觉性。"}},faq={{q="我在哪里能获得徘徊者的爪子？",a="徘徊者的爪子取自草原徘徊者，它们游荡在整个贫瘠之地中部的草原上，特别是在十字路口西南方的平原区域。",al={"徘徊者的爪子位置","如何获得徘徊者的爪子","哪里能找到徘徊者的爪子"}},{q="谁需要这些爪子，为什么？",a="驻扎在十字路口的经验丰富的女猎手塞格拉·黑棘，要求猎人带给她七个徘徊者的爪子，以此作为测试他们追踪和对抗危险掠食者的战斗本领的一种方式。",al={"谁需要徘徊者的爪子","上交徘徊者的爪子","塞格拉的爪子任务"}},{q="为什么草原徘徊者被视为重要的狩猎目标？",a="与贫瘠之地的食草兽群不同，徘徊者是潜行的肉食动物，它们会在高草丛的隐蔽处主动跟踪旅人和猎物。猎杀它们是对冒险者规避伏击并击败致命、狡猾野兽能力的考验。",al={"为什么要狩猎徘徊者","徘徊者危险"}}},fp="13,168,23.428.0,22.334.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pure-hearts"] = {n="纯洁的心",s="纯洁的心是凯伦丁·哈加尔提供给幽暗城被遗忘者术士的仪式试剂。它们被用来诱惑并让魅魔穿越扭曲虚空显形，以便施术者可以击败并奴役这只恶魔。",h="纯洁的心是凯伦丁·哈加尔提供给幽暗城被遗忘者术士的仪式试剂。它们被用来诱惑并让魅魔穿越扭曲虚空显形，以便施术者可以击败并奴役这只恶魔。",kw={"凯伦丁·哈加尔","magic quarter","纯洁的心","魅魔","召唤","奴役","幽暗城"},ang={["class:Warlock"]="对于被遗忘者术士来说，获取并使用这些心代表了恶魔学识中的一个关键里程碑：证明自己在面对扭曲虚空的诱惑时拥有强大的精神意志。",["race:Undead"]="在幽暗城的腐烂与枯萎中，使用纯净无瑕的心来操纵恶魔的欲望，体现了被遗忘者所实践的那种冰冷、务实的巫术。"},sec={{t="虚空的诱饵",b="恶魔学识依赖于利用基本欲望和精神脆弱。为了在幽暗城的Magic Quarter召唤一只魅魔，凯伦丁·哈加尔向术士们提供了纯洁的心。当被放置在召唤法阵上时，这些未受玷污的精神精华会作为强效诱饵，将充满诱惑的恶魔从扭曲虚空引诱到凡人位面。一旦恶魔显形，术士就必须抵御她的魅惑心灵控制，并在战斗中将其击败。战胜魅魔确立了神秘学上的主导权，将她放逐回扭曲虚空，直到凯伦丁教会术士随意召唤她的法术。"}},faq={{q="纯洁的心有什么用？",a="它们是幽暗城Magic Quarter召唤法阵上使用的神秘催化剂，用于引诱并让魅魔穿越虚空显形，从而使术士能够与她战斗并将其奴役。",al={"纯洁的心用途","为什么使用纯洁的心","纯洁的心的作用"}},{q="谁提供了纯洁的心？",a="凯伦丁·哈加尔，位于洛丹伦废墟下方的Magic Quarter的被遗忘者术士训练师，他会将这些心交给准备好掌握魅魔召唤术的进阶施术者。",al={"谁给予纯洁的心","纯洁的心任务发布者"}},{q="为什么魅魔会被纯洁的心吸引？",a="魅魔以腐化、诱惑和污染纯真为生。无瑕且纯洁的心灵所散发出的光芒是扭曲虚空中无法抗拒的诱饵，将她们直接引向术士预先准备好的召唤法阵。",al={"为什么魅魔想要纯洁的心","纯洁的心的背景故事"}},{q="仪式结束后我能保留纯洁的心吗？",a="不能。一旦魅魔被召唤并被制服，纯洁的心的残余物必须交还给凯伦丁·哈加尔，作为完成奴役试炼的证明。",al={"我能保留纯洁的心吗","纯洁的心最后去了哪里"}}},fp="11,208,19.485.0,34.190.0,29.123.0,43.180.0,52.145.0"}
P.entries["item:purified-kor-gem"] = {n="净化过的科尔宝石",s="净化过的科尔宝石是一颗稀有的神圣水晶，是铁炉堡外武器锻造师乔丹·斯迪威尔所必需的材料。它曾经被黑暗能量侵蚀，必须从卡利姆多的深处寻回，并经过精灵魔法的净化，才能被铸造成圣光的武装。",h="净化过的科尔宝石是一颗稀有的神圣水晶，是铁炉堡外武器锻造师乔丹·斯迪威尔所必需的材料。它曾经被黑暗能量侵蚀，必须从卡利姆多的深处寻回，并经过精灵魔法的净化，才能被铸造成圣光的武装。",kw={"奥伯丁","黑暗深渊","被污染的科尔宝石","丹莫罗","乔丹·斯迪威尔","净化过的科尔宝石","正义试炼","桑德拉斯·风织"},ang={["class:Paladin"]="获取并净化这颗宝石证明了一位圣骑士的奉献精神，它引领着圣骑士从卡利姆多的深处回到丹莫罗，去锻造一把标志性的圣光武器。",["faction:Alliance"]="获取这颗净化过的宝石凝聚了联盟各方的努力，依靠奥伯丁的暗夜精灵智慧，来助力在丹莫罗山坡上工作的人类铁匠。"},sec={{t="从腐化到圣洁",b="这块宝石最初是以被污染的科尔宝石的形式，被潜伏在灰谷海岸深处、黑暗深渊里的邪恶娜迦所持有。为了清除石头上水底的暗影污秽，圣骑士必须前往奥伯丁寻找暗夜精灵桑德拉斯·风织。桑德拉斯通过运用奥术和自然艺术，清除了石头上的腐化，将其转化为光芒四射的净化过的科尔宝石。只有处于这种纯净状态下，它才能作为圣光之力的导管。"},{t="铁匠的杰作",b="在丹莫罗白雪皑皑的峭壁上，铁炉堡外，人类武器锻造师乔丹·斯迪威尔需要这颗宝石作为锻造大师级武器的关键组件。斯迪威尔长期以来一直持有打造一件足以配得上白银之手武器的设计图，却苦于没有奇异的材料来实现他的计划。净化过的科尔宝石，连同白石橡木和稀有矿石，提供了引导圣骑士正义之怒所必需的精神核心。"}},faq={{q="净化过的科尔宝石有什么用途？",a="它被带给驻扎在丹莫罗、铁炉堡大门外的铁匠乔丹·斯迪威尔。斯迪威尔将这颗神圣的宝石作为必需组件，为正在进行试炼的圣骑士锻造一把神圣的武器。",al={"净化过的科尔宝石用途","为什么需要科尔宝石","科尔宝石是做什么用的"}},{q="这颗宝石源自何处？",a="这块石头源自灰谷海岸线下的黑暗深渊地下废墟中，它作为一件被腐化的神器被娜迦所把持。",al={"科尔宝石来源","科尔宝石在哪里掉落","谁掉落科尔宝石"}},{q="谁来净化这颗宝石？",a="居住在黑海岸奥伯丁沿海定居点的精灵学者桑德拉斯·风织，负责清除被污染的科尔宝石上的黑暗能量，将其恢复到净化状态。",al={"如何净化科尔宝石","谁来净化科尔宝石","桑德拉斯·风织科尔宝石"}},{q="任何冒险者都能使用净化过的科尔宝石吗？",a="这颗宝石是专门为进行正义试炼的圣骑士所需求的。乔丹·斯迪威尔只为那些将净化后的水晶与其他稀有材料一起带给他的圣洁战士提供服务。",al={"科尔宝石是圣骑士专有的吗","任何人都能使用净化过的科尔宝石吗"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="腐烂的爪子",s="“腐烂的爪子”是那些在布瑞尔以西的树林中游荡的无脑亡灵身上掉落的腐烂断肢。亡灵卫兵迪林格尔收集这些爪子，作为旧桥附近日益严重的“天灾军团”威胁正受到压制的有力证据。",h="“腐烂的爪子”是那些在布瑞尔以西的树林中游荡的无脑亡灵身上掉落的腐烂断肢。亡灵卫兵迪林格尔收集这些爪子，作为旧桥附近日益严重的“天灾军团”威胁正受到压制的有力证据。",kw={"腐烂的任务","布瑞尔","亡灵卫兵迪林格尔","腐烂的爪子","残缺的尸骸","腐烂的死尸","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="对于刚离开丧钟镇的被遗忘者新兵来说，清除这些无脑的“天灾军团”是一个早期的警示：自由的代价，是必须时刻抵御那些他们曾经也是其中一员的无脑空壳。"},sec={{t="无脑者的战利品",b="即使在他们自己的家园，被遗忘者也无法完全逃脱巫妖王的魔爪。成群的无脑“天灾军团”——腐烂的死尸和残缺的尸骸——经常穿过东部边界，游荡进入提瑞斯法林地，聚集在道路上以及布瑞尔以西的旧桥附近。为了确保旅行者和驻军补给线的安全，亡灵卫兵会对这些游荡的恐怖生物悬赏。一只被砍下的腐烂的爪子，是证明又一具蹒跚而行的尸体被彻底消灭的无可辩驳的实物证据。"}},faq={{q="腐烂的爪子有什么用？",a="驻扎在布瑞尔的亡灵卫兵迪林格尔将它们作为赏金收集起来，以确认当地的被遗忘者新兵正在清除游荡在提瑞斯法林地的“天灾军团”。",al={"腐烂的爪子用途","为什么收集腐烂的爪子","谁需要腐烂的爪子"}},{q="腐烂的爪子从哪里来？",a="它们是从游荡在布瑞尔以西闹鬼树林中的腐烂死尸和残缺尸骸身上采集的，尤其是在旧河桥附近。",al={"哪里获得腐烂的爪子","腐烂的爪子掉落","腐烂的死尸掉落"}},{q="为什么“天灾军团”会出现在提瑞斯法林地？",a="在洛丹伦遭到毁灭后，巫妖王麾下残存的无脑“天灾军团”不断穿过边界向西涌入提瑞斯法，如果不主动清除，它们将威胁到道路和定居点。",al={"为什么布瑞尔附近有僵尸","提瑞斯法的天灾军团"}},{q="为什么被遗忘者不放任这些无脑亡灵游荡？",a="与希尔瓦娜斯女王麾下挣脱束缚、重获自由意志的被遗忘者不同，无脑的“天灾军团”只听从黑暗本能或巫妖王残留的命令，攻击视线内任何活着的或自由的亡灵。",al={"被遗忘者与无脑僵尸","为什么要杀其他亡灵"}}},fp="11,171,22.359.0,31.162.0,32.138.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="焚木镣铐",s="焚木镣铐是戴在银松森林南部焚木村深受困扰的居民身上的附魔枷锁。这些神秘的束缚带被注入了大法师阿鲁高的诡异魔法，似乎在夜幕降临时，这些村民陷入的黑暗命运中扮演着某种角色。",h="焚木镣铐是戴在银松森林南部焚木村深受困扰的居民身上的附魔枷锁。这些神秘的束缚带被注入了大法师阿鲁高的诡异魔法，似乎在夜幕降临时，这些村民陷入的黑暗命运中扮演着某种角色。",kw={"阿鲁高","道恩维沃尔","月怒","焚木","瑟伯切尔","镣铐","银松","狼人"},ang={["class:Mage"]="研究阿鲁高作品的法师会认出那些编织在普通钢铁中，被鲁莽使用的变形与束缚魔法。",["race:Undead"]="瑟伯切尔的被遗忘者学者将阿鲁高猖獗的巫术视为对他们边界的重大威胁，因此收集这些附魔束缚带对于中和影牙城堡的影响至关重要。"},sec={{t="阿鲁高的束缚魔法",b="被诅咒的焚木村隐藏着一个令人不安的秘密：白天，这里的居民过着正常的生活，看起来和普通人类无异，但夕阳西下时，他们会变异成野蛮的月怒狼人。大法师阿鲁高将这些村民禁锢在附魔镣铐之中，作为他扭曲的狼人巫术实验的一部分。驻扎在瑟伯切尔的被遗忘者奥术研究员达拉尔·道恩维沃尔正在研究这些镣铐，试图破解驱使这种双重存在的附魔。通过收集并分析束缚带上残留的能量，道恩维沃尔寻求对阿鲁高魔法更深层次的理解，希望以此解开这位疯狂大法师对该地区的控制。"}},faq={{q="焚木镣铐的用途是什么？",a="位于瑟伯切尔的达拉尔·道恩维沃尔请求获得这些镣铐以研究其上的附魔。通过汲取其中的魔法，他希望能破解大法师阿鲁高的法术，并找到摧毁这位大法师在银松森林势力的方法。",al={"焚木镣铐用途","为什么收集镣铐","达拉尔·道恩维沃尔 镣铐"}},{q="谁携带这些镣铐？",a="这些镣铐由银松森林南部焚木村被诅咒的居民携带，无论是在白天的伪装状态，还是在夜晚变身成为月怒狼人时，他们都佩戴着这些镣铐。",al={"焚木镣铐掉落","镣铐来源","哪里寻找焚木镣铐"}},{q="为什么村民会在夜晚变身？",a="大法师阿鲁高对焚木村的居民进行了鲁莽的魔法实验和附魔。这些镣铐维持着一种附魔，使他们在白昼能维持普通人类的模样，而一旦夜幕降临，他们就会显露出野蛮的狼人形态。",al={"为什么焚木会变成狼人","焚木村诅咒","焚木狼人秘密"}},{q="谁是达拉尔·道恩维沃尔？",a="达拉尔·道恩维沃尔是一位居住在银松森林瑟伯切尔的被遗忘者法师。他积极研究大法师阿鲁高留下的奥术异常现象，专注于剖析并打破这位大法师扭曲的诅咒。",al={"达拉尔·道恩维沃尔","达拉尔是谁"}}},fp="16,187,22.479.1,36.199.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="奎恩的药水",s="奎恩的药水是由药剂师伦弗利尔在瑟伯切尔配制的一种恢复性药剂。它旨在稳定并恢复受伤的死亡猎手奎恩·尤瑞克，他之前在银松森林的一次侦察巡逻中遭遇了灾难性的打击。",h="奎恩的药水是由药剂师伦弗利尔在瑟伯切尔配制的一种恢复性药剂。它旨在稳定并恢复受伤的死亡猎手奎恩·尤瑞克，他之前在银松森林的一次侦察巡逻中遭遇了灾难性的打击。",kw={"药剂师伦弗利尔","死亡猎手","伊瓦农场","奎恩·尤瑞克","奎恩的药水","瑟伯切尔","银松森林"},ang={["race:Undead"]="皇家药剂师协会很少在简单的前线治疗上浪费精力，除非这能直接挽救对于保卫银松森林边境至关重要的被遗忘者侦察兵。"},sec={{t="伦弗利尔的疗法",b="死亡猎手奎恩·尤瑞克在伊瓦农场附近遭到重创并丧失行动能力后，消息传到了瑟伯切尔的皇家药剂师协会。药剂师伦弗利尔匆忙配制了这种专用药剂，以帮助奎恩恢复。虽然伦弗利尔很少让轻微的前线伤亡分散他对希尔瓦娜斯女士更宏大、更邪恶的研究的注意力，但他还是提供了这种恢复药剂，让这位受伤的侦察兵能够重新站起来并继续旅行。"}},faq={{q="奎恩的药水有什么用？",a="这种药剂是为了帮助死亡猎手奎恩·尤瑞克恢复而配制的，他目前躺在银松森林北部的树林中受伤。喝下它能恢复他足够的生命力，使他能够再次旅行。",al={"奎恩药水用途","奎恩药水作用","为何配制奎恩药水"}},{q="谁酿造了这种药剂？",a="药剂师伦弗利尔，一位驻扎在瑟伯切尔墓穴中的皇家药剂师协会炼金术师，配制了这种药剂。",al={"谁制作了奎恩的药水","谁酿造的","伦弗利尔药水"}},{q="这种药剂需要送到哪里？",a="它必须被送到瑟伯切尔以北，交给奎恩·尤瑞克，他正躲在被称为伊瓦农场的农庄附近。",al={"我该把药水带到哪里","奎恩位置","奎恩·尤瑞克所在"}},{q="为什么奎恩·尤瑞克需要药剂？",a="奎恩曾是负责侦察银松森林北部的一支死亡猎手巡逻队成员。在伊瓦农场，侦察兵们遭到了食尸鬼伊瓦·血眼的袭击，奎恩因此受重伤并被困在那里。",al={"奎恩为何受伤","奎恩·尤瑞克发生了什么","奎恩受伤"}}},fp="14,163,16.417.0,32.163.0,23.123.0,43.116.0,41.169.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="兰恩·血牙的颅骨",s="兰恩·血牙的颅骨是取自灰谷腐化熊怪首领的一件令人毛骨悚然的战利品。将它带回给阿斯特兰纳的暗夜精灵，可以作为这片林地王国的凶猛威胁已被终结的有力证明。",h="兰恩·血牙的颅骨是取自灰谷腐化熊怪首领的一件令人毛骨悚然的战利品。将它带回给阿斯特兰纳的暗夜精灵，可以作为这片林地王国的凶猛威胁已被终结的有力证明。",kw={"灰谷","阿斯特兰纳","血牙的颅骨","血牙","熊怪","莱恩·狼行者","莱恩的净化","兰恩·血牙"},ang={["faction:Alliance"]="上交这件残酷的战利品，证明了联盟的勇士们在保卫灰谷脆弱边境时，与哨兵们并肩作战的英勇无畏。",["race:NightElf"]="对于暗夜精灵来说，取走这颗颅骨是一场沉重的胜利。虽然它告慰了泰罗尼斯未竟的任务，但也提醒着他们，恶魔的腐化已经如此深重地摧残了他们曾经的熊怪盟友。"},sec={{t="灰谷防御的战利品",b="灰谷的森林深受恶魔污染和荒野腐化的摧残，导致曾经爱好和平的熊怪部落陷入了疯狂的杀戮之中。而在这些敌对首领中，最凶残的莫过于兰恩·血牙。带回他的颅骨为暗夜精灵哨兵提供了他已倒下的确凿证据，打破了他对当地熊怪的控制，也为饱受困扰的阿斯特兰纳小镇带来了一丝喘息的机会。"},{t="纪念逝者",b="当这颗颅骨被呈交给阿斯特兰纳的哨兵莱恩·狼行者时，标志着由阵亡斥候泰罗尼斯所引发的一系列调查告一段落。这颗兰恩·血牙的颅骨与泰罗尼斯出发寻找并最终重铸的达图尔的变形魔棒一起被陈列出来，作为那些为保卫这片神圣森林而战的勇士们的见证。"}},faq={{q="兰恩·血牙是谁？",a="兰恩·血牙是灰谷腐化熊怪的首领，被暗夜精灵哨兵视为该地区最凶猛的威胁之一。",al={"兰恩·血牙是谁","兰恩·血牙背景故事","血牙是谁"}},{q="为什么哨兵需要他的颅骨？",a="阿斯特兰纳的莱恩·狼行者将这颗颅骨作为兰恩·血牙被击败的证明收下。这颗颅骨被与达图尔的变形魔棒放置在一起，作为胜利的象征，以纪念那些在保卫灰谷过程中牺牲的人们。",al={"为什么我需要这颗颅骨","莱恩·狼行者 颅骨","这颗颅骨有什么用"}},{q="泰罗尼斯是谁？",a="泰罗尼斯是莱恩·狼行者的多年好友，他曾协助灰谷的哨兵们。他曾出发寻找一颗属于已故法师达图尔制作的法杖的宝石，希望能借此减缓熊怪的攻击，但不幸在法拉希姆湖被鱼人杀害。他的任务后来由莱恩·狼行者和路过的冒险者们接手完成了。",al={"泰罗尼斯背景故事","泰罗尼斯是谁","泰罗尼斯 阿斯特兰纳"}}},fx={["4d0a3ce4"]={q="什么是兰恩·血牙的颅骨？",a="这是兰恩·血牙被砍下的颅骨。他是灰谷出没的凶狠危险的腐化熊怪之一。它被当作击败他的凭证，标志着他给哨兵和森林带来的恐怖终于结束。",al={"兰恩·血牙的颅骨","兰恩的颅骨是什么","兰恩·血牙的头颅"}},f5c7858d={q="兰恩·血牙的颅骨来自哪里？",a="在灰谷杀死兰恩·血牙后，便可直接取得他的颅骨。它不是凡人锻造或制作的神器，而是从这位酋长身上取得的骇人战利品。",al={"兰恩的颅骨来自哪里","谁制造了兰恩·血牙的颅骨","兰恩·血牙的颅骨来源"}}},fp="22,201,31.303.0,19.304.1,23.140.0,36.166.0,16.288.0"}
P.entries["item:raptor-head"] = {n="迅猛龙的头颅",s="一颗被砍下的迅猛龙的头颅，是证明在贫瘠之地猎杀野兽的血腥凭证。为了在发生不可思议的卫兵薪饷失窃事件后清理当地的兽群，十字路口的加兹罗格要求收集这些恐怖的战利品。",h="一颗被砍下的迅猛龙的头颅，是证明在贫瘠之地猎杀野兽的血腥凭证。为了在发生不可思议的卫兵薪饷失窃事件后清理当地的兽群，十字路口的加兹罗格要求收集这些恐怖的战利品。",kw={"贫瘠之地","十字路口","加兹罗格","迅猛龙的头颅","迅猛龙窃贼","被偷走的银币","日光"},ang={["class:Hunter"]="在贫瘠之地的干燥灌木丛中追踪日光迅猛龙，是对猎人智斗稀树草原上最凶猛、最狡猾的群居猎手能力的一次考验。",["faction:Horde"]="十字路口是部落在卡利姆多中部旅行的后勤心脏。清除盗窃的掠食者可以确保驻军的补给和薪饷安全。"},sec={{t="十字路口的赏金",b="贫瘠之地干旱平原上的生活已经够艰苦了，当地的野生动物还会袭击定居点的塔楼。当一个装有卫兵薪饷的箱子从十字路口的瞭望塔中消失时，守卫们当场抓获了一个意想不到的罪魁祸首：一只野生迅猛龙。加兹罗格感到既困惑又愤怒，立即对徘徊在稀树草原上的狡猾爬行动物下达了悬赏令。将砍下的迅猛龙的头颅带回哨所，证明了这些掠食害兽正在被扑杀，以防它们再偷走任何部落补给。"}},faq={{q="加兹罗格为什么要迅猛龙的头颅？",a="一批原本作为十字路口卫兵薪饷的白银从他们的塔楼中被直接偷走。令所有人难以置信的是，当场抓获的窃贼之一竟然是一只迅猛龙。加兹罗格希望在整个贫瘠之地追猎这些野兽，这样它们就无法再次袭击定居点了。",al={"为什么收集迅猛龙的头颅","加兹罗格 迅猛龙","迅猛龙的头颅悬赏"}},{q="为什么野生迅猛龙会偷窃白银？",a="加兹罗格承认他也不知道为什么野生野兽会对金属硬币感兴趣。然而，卡利姆多的迅猛龙以其令人不安的狡猾而闻名，这起事件让十字路口的卫兵们既感到尴尬，又急于报复。",al={"为什么迅猛龙想要白银","迅猛龙偷窃硬币","迅猛龙窃贼之谜"}},{q="哪些迅猛龙会有这种头颅？",a="在贫瘠之地中部和南贫瘠之地游荡的各种日光迅猛龙身上都可以获得头颅，包括日光鞭尾龙、尖啸龙和镰爪龙。伊沙穆哈雷和跳跃者塔克等臭名昭著的野兽也能提供头颅。",al={"哪里获得迅猛龙的头颅","哪些迅猛龙掉落头颅","贫瘠之地 迅猛龙"}},{q="上交头颅后会发生什么？",a="一旦加兹罗格收到十二颗头颅并看到迅猛龙的威胁被削减，注意力就会转向追踪那批失窃白银的真实去向。",al={"迅猛龙窃贼之后会发生什么","收集迅猛龙头颅之后"}}},fp="11,176,24.342.0,34.252.0,36.213.0,32.207.0,40.153.0"}
P.entries["item:rare-earth"] = {n="稀土",s="稀土是一种特制的富含矿物质的土壤包，从达纳苏斯采购，用于泰达希尔的植物学实验。它由多兰纳尔的信使发送给正在奥拉密斯湖畔营地进行研究的草药学家德纳兰。",h="稀土是一种特制的富含矿物质的土壤包，从达纳苏斯采购，用于泰达希尔的植物学实验。它由多兰纳尔的信使发送给正在奥拉密斯湖畔营地进行研究的草药学家德纳兰。",kw={"达纳苏斯","德纳兰","多兰纳尔","草药学","奥拉密斯湖","稀土","塞拉尔·刃叶"},ang={["profession:Herbalism"]="草药学家会赞赏像塞拉尔·刃叶和德纳兰这样的研究人员所付出的细致努力，他们研究特殊的土壤如何改变泰达希尔树苗的生长和特性。",["race:NightElf"]="对于照料年轻世界之树的暗夜精灵来说，在奥拉密斯湖进行的每一项植物学实验，都能为生命如何适应泰达希尔那未经驯化的枝干提供见解。"},sec={{t="达纳苏斯的土壤",b="泰达希尔新生的生态系统需要仔细的观察和培育，这促使岛上的草药学家们开始研究各种植物如何对外部或富含营养的土壤做出反应。这批稀土是由德纳兰直接从达纳苏斯征调的，他是一位古怪的植物学家，驻扎在奥拉密斯湖东岸。在运输途中耽搁并迟迟才到达多兰纳尔后，草药学家塞拉尔·刃叶委托南下的旅行者将这些易腐烂的土壤在药效消退前送到德纳兰手中。"}},faq={{q="稀土有什么用？",a="这些稀土是给德纳兰准备的，他是一位在奥拉密斯湖岸边扎营的草药学家和植物学研究员。他利用从达纳苏斯进口的特殊矿物化合物和肥沃土壤，来培育和试验泰达希尔的本土植物。",al={"稀土的用途","德纳兰用稀土做什么","稀土的目的"}},{q="谁把稀土寄给了德纳兰？",a="位于多兰纳尔镇的草药学家塞拉尔·刃叶负责保管这个包裹。它从达纳苏斯送达时已经晚了，于是她请求路过并前往南边奥拉密斯湖的冒险者代为转交。",al={"谁提供了稀土","你在哪里获得稀土","塞拉尔·刃叶的包裹"}},{q="为什么德纳兰担心这次运送？",a="这批货物在运往多兰纳尔的途中延误了，导致德纳兰在湖边等待了很长时间。在收到货物后，他立即担心这些土壤是否还保持着新鲜和活力，能否用于他的植物学实验。",al={"稀土是否毁坏了","德纳兰新鲜土壤","为什么土壤迟到了"}}},fp="10,167,17.315.0,28.203.0,36.170.0,43.177.0"}
P.entries["item:rattlecage-skull"] = {n="断骨骷髅的颅骨",s="断骨骷髅的颅骨是游荡在丧钟镇废墟边缘的无脑亡灵留下的残骸。被遗忘者术士学徒必须收集这些钙化的战利品交给温雅·玛山德，以展示他们初显的意志，并获得学习黑暗召唤术的资格。",h="断骨骷髅的颅骨是游荡在丧钟镇废墟边缘的无脑亡灵留下的残骸。被遗忘者术士学徒必须收集这些钙化的战利品交给温雅·玛山德，以展示他们初显的意志，并获得学习黑暗召唤术的资格。",kw={"丧钟镇","召唤小鬼","穿透面纱","断骨骷髅","断骨骷髅的颅骨","提瑞斯法林地","温雅·玛山德"},ang={["class:Warlock"]="对于被遗忘者术士来说，收集这些颅骨代表了他们修行过程中的第一个里程碑，证明了他们拥有奴役第一个恶魔所需的冷酷意志。",["race:Undead"]="粉碎低等、无知觉的骷髅这一行为，强调了被遗忘者通过纯粹意志建立统治的信仰，将拥有自由意志的亡灵与无脑的奴仆区分开来。"},sec={{t="新手的考验",b="在丧钟镇那暗无天日的边界内，对暗影魔法有天赋的新生被遗忘者会受到温雅·玛山德的指引。为了证明初学者有足够坚强的意志去驾驭位面之外的生物，温雅会要求他们去制服废弃铁匠铺附近的断骨骷髅。击倒这些低等亡灵并取回它们被切下的颅骨，既是对纪律的实践考验，也是在学习穿透虚空并奴役第一个恶魔仆从之前的基础仪式。"}},faq={{q="断骨骷髅的颅骨有什么用？",a="它们由丧钟镇的温雅·玛山德负责收集。被遗忘者术士必须带给她三个颅骨，以证明他们的专注与决心，随后她才会传授召唤并束缚小鬼的仪式。",al={"断骨骷髅的颅骨是什么","断骨骷髅的颅骨用途","谁需要断骨骷髅的颅骨"}},{q="断骨骷髅的颅骨从哪里来？",a="它们取自断骨骷髅的残骸，这些无脑的亡灵徘徊在丧钟镇废弃铁匠铺附近的杂草丛生的道路和摇摇欲坠的地面上。",al={"哪里获得断骨骷髅的颅骨","谁掉落断骨骷髅的颅骨","断骨骷髅的颅骨位置"}},{q="为什么温雅·玛山德要求在术士试炼中使用骷髅头？",a="温雅认为力量会避开无知者，而掌握力量需要将外在的力量通过意志来弯曲折服。屠戮这些无脑骷髅并夺取它们的头颅，证明了学徒拥有控制混乱能量的基本意志，而不是被其吞噬。",al={"为什么术士需要骷髅","温雅·玛山德的考验"}},{q="收集这些颅骨后能获得什么知识？",a="一旦上交了这些颅骨，温雅·玛山德就会传授召唤并束缚小鬼所需的秘密仪式，让年轻的术士获得他们第一个真正的恶魔仆从。",al={"收集断骨骷髅的颅骨有什么奖励","穿透面纱奖励"}}},fp="16,177,17.388.0,36.175.0,37.153.0,68.242.0,55.156.0"}
P.entries["item:raven-claw-talisman"] = {n="鸦爪神符",s="鸦爪神符是与猛禽德鲁伊紧密相连的暗夜精灵圣物。它被保存在泰达希尔的班奈希尔兽穴深处，是四件引导沉睡的德鲁伊从翡翠梦境安全归来的唤醒圣物之一。",h="鸦爪神符是与猛禽德鲁伊紧密相连的暗夜精灵圣物。它被保存在泰达希尔的班奈希尔兽穴深处，是四件引导沉睡的德鲁伊从翡翠梦境安全归来的唤醒圣物之一。",kw={"阿斯瑞达斯·熊皮","班奈希尔","兽穴","多兰纳尔","猛禽德鲁伊","鸦爪神符","唤醒圣物","泰达希尔"},ang={["class:Druid"]="这枚神符是猛禽德鲁伊的象征，体现了仪式焦点如何在德鲁伊游历翡翠梦境时守护其灵魂。",["race:NightElf"]="找回这件圣物不仅保护了古老的暗夜精灵传统，也保护了被棘皮熊怪的疯狂所威胁的沉睡同胞的生命。"},sec={{t="唤醒之匙",b="鸦爪神符被保存在班奈希尔兽穴内的一个指定宝箱中，这里是泰达希尔的猛禽德鲁伊们进入深层冥想沉睡的地下圣所。德鲁伊的冬眠是一种微妙的精神临界状态。如果德鲁伊与清醒世界的联系在没有适当仪式焦点的情况下被切断，他们的灵魂就有可能永远被困在翡翠梦境中。除了黑色羽毛、天蓝宝石和筑巢符文外，多兰纳尔的阿斯瑞达斯·熊皮还需要这枚神符来举行唤醒仪式，让沉睡者安全归来。"},{t="兽穴中的威胁",b="当受到腐蚀的棘皮熊怪占领了班奈希尔兽穴后，神圣的宝箱和沉睡的德鲁伊们立刻陷入了险境。熊怪的亵渎行为切断了圣所与外界的援助，使得这些圣物面临丢失或被毁的危险。阿斯瑞达斯·熊皮指派泰达希尔的守卫者们深入兽穴蜿蜒的土层走廊，在那些流离失所的德鲁伊永远迷失在翡翠梦境之前，夺回鸦爪神符。"}},faq={{q="鸦爪神符有什么用？",a="它是唤醒猛禽德鲁伊从翡翠梦境的深层冬眠中苏醒所需的四件神圣唤醒圣物之一。",al={"鸦爪神符的作用","鸦爪神符的目的","为什么我需要鸦爪神符"}},{q="鸦爪神符在哪里？",a="它位于泰达希尔多兰纳尔以西的班奈希尔兽穴的土层隧道内，存放在鸦爪之箱中。",al={"鸦爪神符在哪里","鸦爪之箱的位置","如何找到鸦爪神符"}},{q="谁需要鸦爪神符？",a="驻扎在多兰纳尔的暗夜精灵德鲁伊阿斯瑞达斯·熊皮，需要这枚神符来为他流离失所的同胞准备唤醒仪式。",al={"谁想要鸦爪神符","谁会拿走鸦爪神符","我应该把这个交给谁"}},{q="为什么没有它德鲁伊就无法醒来？",a="通过德鲁伊冬眠进入翡翠梦境涉及一种复杂而微妙的恍惚状态。如果没有唤醒圣物作为锚定唤醒仪式的特定焦点，沉睡者的灵魂可能会有永远迷失在翡翠梦境中的风险。",al={"为什么德鲁伊需要圣物才能醒来","为什么需要唤醒圣物","德鲁伊没有圣物能醒来吗"}}},fp="19,238,18.522.0,28.413.0,41.148.0,39.145.0,34.123.0,40.200.0"}
P.entries["item:razorflank-s-medallion"] = {n="卡尔加·刺肋的徽章",s="卡尔加·刺肋的徽章是卡尔加·刺肋随身携带的个人信物，这位老妪统治着剃刀沼泽。它是从野猪人据点的中心夺回的，是这位女族长已被击毙的有力证据。",h="卡尔加·刺肋的徽章是卡尔加·刺肋随身携带的个人信物，这位老妪统治着剃刀沼泽。它是从野猪人据点的中心夺回的，是这位女族长已被击毙的有力证据。",kw={"阿迦玛甘","卡尔加·刺肋","法芬德尔","隆布朗","剃刀沼泽","卡尔加·刺肋的徽章","萨兰纳尔"},ang={["faction:Alliance"]="夺回徽章能为阵亡的侦察兵赫拉拉斯和矮人探险家隆布朗复仇，确保通往菲拉斯的萨兰纳尔边境路线安全。",["race:NightElf"]="击杀卡尔加并取得她的徽章，使暗夜精灵能够安全地研究阿迦玛甘被腐蚀的神圣安息地。"},sec={{t="老妪陨落的证明",b="这枚徽章由卡尔加·刺肋亲自携带，代表着统领剃刀沼泽野猪人的老妪的权威。当萨兰纳尔的法芬德尔得知赫拉拉斯和矮人隆布朗等探险家遇害的消息后，他委托联盟冒险者直接打击这位野猪人领袖。上交这枚老妪的徽章即证实了她的死讯，让驻守在菲拉斯边境的暗夜精灵哨兵确信，聚集在沼泽中的势力已经失去了他们的首领。"}},faq={{q="谁携带着卡尔加·刺肋的徽章？",a="这枚徽章属于卡尔加·刺肋，她是剃刀沼泽野猪人的老妪和毋庸置疑的领袖。她将它随身携带在这个据点深处多刺的迷宫之中。",al={"谁掉落卡尔加·刺肋的徽章","卡尔加·刺肋的徽章来源","卡尔加的徽章"}},{q="谁想要这枚徽章？",a="驻扎在菲拉斯和千针石林之间萨兰纳尔哨站的法芬德尔需要这枚徽章。他需要以此作为卡尔加已被击杀的最终证据。",al={"谁需要卡尔加·刺肋的徽章","上交卡尔加·刺肋的徽章","法芬德尔徽章"}},{q="为什么法芬德尔需要卡尔加死亡的证据？",a="卡尔加在剃刀沼泽内集结了一股充满敌意的野猪人部队，威胁着周边地区，并导致了赫拉拉斯和隆布朗等侦察兵的死亡。带回这枚徽章能让暗夜精灵确信即时的威胁已被解除，并使他们能够继续对该地区进行调查。",al={"为什么要击杀卡尔加","徽章的用途","为何需要徽章"}}},fx={b119a669={q="什么是卡尔加·刺肋的徽章？",a="卡尔加·刺肋的徽章是卡尔加·刺肋随身携带的个人信物。她是居住在剃刀沼泽深处的野猪人老妪和首领。这枚徽章不只是装饰品，更是她统御剃刀沼泽中成群部族的鲜明象征，因此是她败亡的标志性战利品。",al={"什么是卡尔加·刺肋的徽章","卡尔加·刺肋的徽章背景","卡尔加·刺肋的徽章"}}},fp="22,178,25.417.0,35.115.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Reagent Pouch (shaman)",s="这种试剂袋是由潜伏在杜隆塔尔岩壁中的火刃氏族邪教徒携带的。萨满祭司如果想要与火焰沟通，就需要收集这些施法材料来提炼他们最初的火焰灵契。",h="这种试剂袋是由潜伏在杜隆塔尔岩壁中的火刃氏族邪教徒携带的。萨满祭司如果想要与火焰沟通，就需要收集这些施法材料来提炼他们最初的火焰灵契。",kw={"火刃氏族","call of fire","杜隆塔尔","尘风洞穴","火焰灵契","火焰图腾","试剂袋","泰尔夫·祖拉姆"},ang={["class:Shaman"]="取回这个袋子是获得火焰图腾之路上的一个关键考验，它教会了萨满祭司即使是被腐蚀的元素介质也可以被回收并用于维持平衡。",["class:Warlock"]="这些袋子反映了邪能邪教徒携带的标准巫术补给，其中装有的仪式元素是用于恶魔火焰法术，而非自然沟通。"},sec={{t="火焰的组件",b="为了制造火焰灵契并使年轻的萨满祭司与火焰之灵调和，特定的仪式催化剂至关重要。火刃氏族的邪教徒随身携带着装有试剂的小袋子，这些试剂专为恶魔火焰召唤而配制。隐士泰尔夫·祖拉姆利用这些收集来的粉末和油脂，再加上剃刀鬃毛野猪人的火焰焦油，调配出能够窥视火焰位面的药剂。"},{t="受污染的源头，纯净的幻象",b="尽管火刃氏族利用火焰进行破坏和邪能巫术，但他们袋子里的物理元素仍然与热量和燃烧的原始本质相连。萨满教义认为，所有的元素力量都存在于张力之中：火焰既是创造者，也是毁灭者。通过夺取邪教徒窃取的工具，萨满祭司可以回收这种元素介质，从而唤醒与灵魂之间真正的沟通。"}},faq={{q="试剂袋有什么用途？",a="它是泰尔夫·祖拉姆酿造火焰灵契所需的必要材料。喝下这种药剂后，萨满祭司将获得预言般的视野，这对于寻找元素之灵并获得火焰图腾至关重要。",al={"试剂袋用途","试剂袋有什么用","试剂袋萨满任务"}},{q="我在哪里可以找到试剂袋？",a="这种袋子可以从位于杜隆塔尔剃刀岭东北部岩石高地的尘风洞穴里的火刃氏族邪教徒身上获得。",al={"试剂袋掉落","如何获取试剂袋","火刃氏族袋子位置"}},{q="为什么萨满祭司需要术士的试剂？",a="火刃氏族在他们的袋子里储备了浸透了火焰魔法的原料。由于他们的仪式严重依赖火焰，这些试剂提供了现成的元素催化剂，可以被重新利用来酿造火焰灵契。",al={"为何使用术士物品","为何使用火刃氏族试剂","萨满祭司使用邪能物品"}}},fp="22,209,23.312.0,28.331.0,35.151.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="翻修过的书籍",s="翻修过的书籍是一本拼凑而成的黑暗秘法典籍，专为那些寻求扩大对恶魔仆从掌控能力的术士所编纂。它记载了从扭曲虚空中召唤并束缚猎犬所需的奥术知识与仪式。",h="翻修过的书籍是一本拼凑而成的黑暗秘法典籍，专为那些寻求扩大对恶魔仆从掌控能力的术士所编纂。它记载了从扭曲虚空中召唤并束缚猎犬所需的奥术知识与仪式。",kw={"束缚","龙喉氏族","猎犬","棘齿城","翻修过的书籍","斯坦哈德·法尔杉","秘法典籍"},ang={["class:Warlock"]="组装翻修过的书籍是一个必经的成人礼，它解锁了奴役猎犬并将这头恶魔吞噬魔法的欲望转向敌方施法者所需的黑暗仪式。"},sec={{t="重组的法典",b="翻修过的书籍碎片经过费尽心力的拼凑，成为了那本被称为“秘法典籍”的神秘教派著作的化身。无论是联盟还是部落的术士，都极力想要修复这些残破的书页，他们甚至愿意在交出完整的书稿之前，让那些渴望一窥其神秘内容的神秘学学者先进行阅览。"},{t="猎犬的关键",b="这份修复后的作品被带到了斯坦哈德·法尔杉面前，他是一位驻扎在贫瘠之地棘齿城港口附近的资深召唤大师。在夺自龙喉氏族施法者的奥术引导棒的辅助下，书中概述的仪式为斯坦哈德的学徒们提供了所需的精准咒语，帮助术士召唤、征服并束缚一头饥饿的猎犬为己所用。"}},faq={{q="翻修过的书籍有什么用途？",a="这本书包含召唤并征服猎犬所需的黑暗仪式和神秘教派教义。术士需要将其与引导棒一同交给棘齿城的斯坦哈德·法尔杉，以筹备束缚仪式。",al={"翻修过的书籍用途","为什么需要翻修过的书籍","翻修过的书籍用法"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位专家级召唤师，居住在贫瘠之地的棘齿城港口上方。他负责监督那些寻求奴役更危险恶魔实体的术士学徒所进行的严苛试炼。",al={"斯坦哈德是谁","斯坦哈德·法尔杉的角色"}},{q="为什么研究这本书的学者想要副本？",a="协助破译残页的学者们发现，这些神秘教派的奥术文本非常迷人且罕见。无论是矮人研究员还是被遗忘者研究员，都觉得他们平时的阅读材料与之相比太过匮乏，因此对书页中保存的稀有恶魔知识垂涎三尺。",al={"谁翻译的","翻修过的书籍与学者"}},{q="仪式除了典籍还需要什么？",a="斯坦哈德需要三根引导棒来让他的学徒们维持召唤仪式。这些木棒必须从盘踞在湿地的龙喉氏族施法者手中夺取。",al={"其他所需物品","翻修过的书籍需要什么辅助"}}},fp="18,179,22.239.0,20.291.1,40.184.0,22.160.0,51.197.0,54.145.0"}
P.entries["item:recruitment-letter"] = {n="募兵信",s="募兵信是一份发给从杜隆塔尔出发前往贫瘠之地服役的有为冒险者的官方公文。这份公文由斥候塔克林·寻路者签发，指示身强力壮的志愿者前往由卡加尔·战痕负责的边境哨所报到。",h="募兵信是一份发给从杜隆塔尔出发前往贫瘠之地服役的有为冒险者的官方公文。这份公文由斥候塔克林·寻路者签发，指示身强力壮的志愿者前往由卡加尔·战痕负责的边境哨所报到。",kw={"贫瘠之地","部落征召兵","十字路口","卡加尔·战痕","剃刀岭","募兵信","塔克林·寻路者"},ang={["faction:Horde"]="携带这封信代表着新兵从杜隆塔尔的本土防御转变为卡利姆多边境的现役军事服役。",["race:Orc"]="对于年轻的兽人来说，向卡加尔·战痕这样的老兵呈交一份已签署的服役信，是在萨尔大酋长领导下的新部落中赚取荣誉的关键一步。"},sec={{t="边境征兵",b="当年轻的战士和斥候在剃刀岭证明了自己的实力后，部落的目光转向了西边那片广阔、未被驯服的贫瘠之地。塔克林·寻路者会挑选出看起来有能力应付前线任务的有为新兵，并交给他们这封信。穿过怒水河大桥标志着一种成人礼：告别杜隆塔尔受庇护的红土地，加入部落的行列，防守那些野猪人、半人马以及联盟斥候。"},{t="向战痕报到",b="这封信的收件人是卡加尔·战痕，也就是管理着河对岸哨所的那位满脸风霜的老兵。卡加尔会对每位征召入伍的新兵进行评估，然后才会正式签署他们的入伍文件。然而，拿到这封信仅仅只是第一步；边境哨所的人手永远吃紧，任何签署了入伍文件的新兵都会被迅速指派到更西边的战略枢纽——十字路口。"}},faq={{q="是谁写了这封募兵信？",a="这封信是由塔克林·寻路者发放的。他是一名驻守在剃刀岭通往外部道路上的兽人斥候，时刻留意着向西进发的精干新兵。",al={"谁发放募兵信","谁写了这封信","塔克林·寻路者的信"}},{q="这封信需要送到哪里？",a="你需要将其送到怒水河大桥对岸、杜隆塔尔与贫瘠之地交界处的兽人瞭望哨，交给卡加尔·战痕。",al={"募兵信送到哪里","提交募兵信","交给谁"}},{q="信件签收后会发生什么？",a="卡加尔会签署文件以正式认可你的入伍，但会立即命令你深入平原，前往十字路口报到，那里急需增援。",al={"卡加尔签字后发生什么","募兵信后的后续任务"}},{q="为什么部落要在贫瘠之地征召冒险者？",a="贫瘠之地是一片广袤且危险的领土，连接着部落的主要定居点。由于当地的半人马部族、好战的刺鬃野猪人以及联盟的军事行动带来的持续威胁，前线指挥官急需每一双可以帮忙的手。",al={"为什么要征兵","为什么在贫瘠之地征兵"}}},fp="18,178,27.356.0,23.294.0,34.141.0,34.143.0,39.174.0,57.267.0"}
P.entries["item:red-burlap-bandana"] = {n="红色粗麻面罩",s="红色粗麻面罩是迪菲亚潜行者中低等级强盗和窃贼所佩戴的粗糙染料布面罩。在北郡山谷，维里副队长收集这些布料作为证明，以确认在修道院葡萄园附近侵扰的窃贼已被消灭。",h="红色粗麻面罩是迪菲亚潜行者中低等级强盗和窃贼所佩戴的粗糙染料布面罩。在北郡山谷，维里副队长收集这些布料作为证明，以确认在修道院葡萄园附近侵扰的窃贼已被消灭。",kw={"面罩","盗贼兄弟会","迪菲亚","面具","北郡","红色粗麻面罩","willem"},ang={["class:Rogue"]="对于一个初出茅庐的潜行者来说，从北郡笨拙的游荡者身上剥下红色面罩，这很好地说明了纪律散漫的不法分子会如何迅速让自己成为当地治安维护者的容易目标。",["faction:Alliance"]="这些红色面罩扩散到了北郡修道院的门口，这表明暴风城的王国边境地区正严重失去控制。"},sec={{t="兄弟会的标记",b="红色粗麻面罩戴在脸下半部，是迪菲亚潜行者普通成员的身份标志。这种面罩由廉价粗糙的织物制成，并浸泡在红色染料中，既能遮掩窃贼的面容，又象征着他们对日益壮大的叛军的忠诚。在北郡，年轻的新兵和普通暴徒带着这些头巾潜入东部的果园，却不知道当地守卫将这种显眼的红色织物视为一种残酷的赏金标记。"}},faq={{q="为什么维里副队长需要这些面罩？",a="维里副队长收集这些面罩是为了作为冒险者消灭了侵扰北郡修道院附近河流一带的迪菲亚暴徒的有形证明。由于窃贼们公开佩戴这种红色布料，上交这些面罩可以确认对当地强盗所悬赏的赏金是否已支付。",al={"为什么收集面罩","维里面罩","盗贼兄弟会上交"}},{q="谁会佩戴红色粗麻面罩？",a="这些面罩由隶属于迪菲亚潜行者的游荡者和暴徒佩戴，这是一个在艾尔文森林和西部荒野各地活动的有组织不法分子团伙。这种粗糙的红色织物既是伪装，也是他们向地下公会效忠的象征。",al={"谁戴红色面罩","迪菲亚面罩背景","谁掉落红色面罩"}},{q="为什么迪菲亚窃贼会在北郡活动？",a="迪菲亚侦察兵和强盗在北郡修道院东边的溪流对面建立了营地，以便搜刮和窃取补给。修道院的驻军兵力薄弱，使得低等级的强盗可以在附近的果园里横行。",al={"为什么迪菲亚在北郡","修道院附近的窃贼"}},{q="面罩的红色是怎么来的？",a="这些面罩只是用深红色染料处理过的廉价粗麻布。这种独特的颜色是迪菲亚潜行者的官方旗帜和制服，确保成员在野外能够互相辨认。",al={"为什么迪菲亚面罩是红色的","红色布料含义"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="红色皮质面罩",s="迪菲亚潜行者在西部荒野各处成员所佩戴的标志性服饰。它由染成深红色的皮革制成，既是一种实用的面罩，也是对抗暴风城王权的不容置疑的叛乱象征。",h="迪菲亚潜行者在西部荒野各处成员所佩戴的标志性服饰。它由染成深红色的皮革制成，既是一种实用的面罩，也是对抗暴风城王权的不容置疑的叛乱象征。",kw={"兄弟会","迪菲亚","加里安","面罩","红色皮质面罩","哨兵岭","西部荒野"},ang={["class:Rogue"]="这种深红色的面罩在人类领地中是地下土匪的代名词，是那些组织严密的盗贼们不可混淆的标志。",["faction:Alliance"]="从每一个倒下的歹徒身上剥下的红色面罩，都意味着威胁西部荒野饥饿农夫和受困民兵的强盗又少了一个。"},sec={{t="潜行者之印",b="在西部荒野尘土飞扬的田野和废弃的农场中，这些深红色的面罩遮住了拦路强盗、掠夺者和反叛劳工的面孔。对于驻扎在哨兵岭的人民民兵来说，这种头饰不仅仅是普通的布料，更是效忠于艾德温·范克里夫的暴徒兄弟会的铁证。哨兵加里安从路过的冒险者手中收集这些面罩，以监视兄弟会在整个地区的动向和日益减少的人数。"}},faq={{q="为什么迪菲亚成员要佩戴红色皮质面罩？",a="红色面罩是迪菲亚潜行者的统一制服。它在他们袭击农场和道路时掩盖了他们的身份，同时也公开宣示了他们效忠于艾德温·范克里夫针对暴风城的起义。",al={"迪菲亚面罩","为什么是红色面罩","迪菲亚面罩含义"}},{q="在西部荒野中是谁需要收集这些面罩？",a="驻扎在哨兵岭人民民兵处的哨兵加里安要求旅行者收集它们。他利用这些面罩来追踪帮派的部队调动，并确认流窜土匪的死亡情况。",al={"谁在收集红色面罩","加里安面罩任务","哨兵岭面罩上交"}},{q="这些面罩可以在哪里找到？",a="它们几乎可以从在西部荒野的营地、田野和矿井中为迪菲亚潜行者效力的任何流氓、拦路强盗或走私者身上获得。",al={"红色面罩掉落","农场红色面罩","红色皮质面罩掉落者"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="红色亚麻面罩",s="红色亚麻面罩是迪菲亚潜行者成员在艾尔文森林各地佩戴的标志性面部遮盖物。这种布料不仅能隐藏强盗的身份，而且本身是由优质亚麻织造而成，足智多谋的当地人经常将其回收利用，制成实用的服装。",h="红色亚麻面罩是迪菲亚潜行者成员在艾尔文森林各地佩戴的标志性面部遮盖物。这种布料不仅能隐藏强盗的身份，而且本身是由优质亚麻织造而成，足智多谋的当地人经常将其回收利用，制成实用的服装。",kw={"迪菲亚面罩","东谷","艾尔文森林","亚麻","红色亚麻面罩","萨拉·迪博雷恩"},ang={["class:Rogue"]="系在下颚上的一块深红色布料，已成为环绕首都的森林中强盗和扒手的标志性装扮。",["profession:Tailoring"]="这些面罩说明了在艾尔文森林的农村地区，原始织造的亚麻布依然非常珍贵，普通的织工会将强盗的颜色改造成工作服。"},sec={{t="迪菲亚的印记",b="虽然北郡山谷中地位较低的新兵和普通暴徒只能凑合使用粗麻布面罩，但艾尔文森林各地的迪菲亚正式成员都佩戴着这种红色亚麻面罩。鲜红色的布料既是制服，也是效忠于艾德温·范克里夫的盗贼兄弟会的象征；它既能掩盖面容，也是向暴风城王权发起叛乱的信号。"},{t="回收利用的布料",b="尽管它们与暴力勾当联系在一起，但这些面罩确实是用不错的布料裁剪而成的。像东谷伐木场的萨拉·迪博雷恩这样务实的定居者，经常会要求旅行者从亡命徒的营地里收集这些面罩。经过简单的清洗和缝补，这些违禁品便能变身为艾尔文森林劳动人民所需的结实衣物和绷带。"}},faq={{q="迪菲亚为什么佩戴红色亚麻面罩？",a="红色面罩既是制服，也是反抗暴风城的徽记。它在隐藏佩戴者身份的同时，也展现了对艾德温·范克里夫兄弟会的忠诚。",al={"迪菲亚面罩含义","为什么是红色面罩","迪菲亚红色面罩"}},{q="这些面罩与北郡佩戴的面罩有何不同？",a="在北郡山谷活动的暴徒佩戴的是粗糙的麻布面罩，而艾尔文森林中成熟的迪菲亚成员佩戴的则是更精细的红色亚麻面罩。",al={"粗麻布与亚麻布","北郡面罩","粗麻面罩"}},{q="谁需要收集这些面罩？",a="东谷伐木场的萨拉·迪博雷恩负责收集这些面罩。作为一名布料短缺的裁缝，她会将这些强盗面罩清洗、拆解，重新编织成实用的衣物。",al={"谁收集红色亚麻面罩","萨拉·迪博雷恩面罩","面罩任务提交"}},{q="哪些敌人会掉落红色亚麻面罩？",a="艾尔文森林中几乎所有的迪菲亚成员都会携带，包括迪菲亚强盗、伏击者、流氓法师、码头工人，以及像收货人莫根这样的头目。",al={"谁掉落红色亚麻面罩","哪里刷面罩","迪菲亚面罩掉落"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="红色毛纺面罩",s="红色毛纺面罩是由囚禁在暴风城监狱里的迪菲亚潜行者们制作的临时标志。它们是从监狱的羊毛毯子上撕下来的，即使身陷囹圄，它们也成为了他们反抗精神的象征。",h="红色毛纺面罩是由囚禁在暴风城监狱里的迪菲亚潜行者们制作的临时标志。它们是从监狱的羊毛毯子上撕下来的，即使身陷囹圄，它们也成为了他们反抗精神的象征。",kw={"迪菲亚","麦克·拉斯克","尼科瓦·拉斯克","红色毛纺面罩","暴风城","血色","监狱"},ang={["faction:Alliance"]="对于联盟的保卫者来说，回收这些面罩是为年轻的麦克·拉斯克伸张正义的一项严峻行动，也是对控制着城市监狱的暴徒的一次打击。",["profession:Tailoring"]="这些粗糙的面罩展示了即使是粗糙的羊毛毯，也能被绝望的囚犯之手拆解并重新利用。"},sec={{t="反抗的缝合",b="即使被锁在暴风城监狱高耸的石墙深处，迪菲亚潜行者成员也拒绝放弃他们的身份。囚犯们利用从监狱羊毛毯上撕下的碎片，秘密制作红色面罩作为识别标志。对于守卫来说，这些围巾是引发致命暴乱的违禁品；而对囚犯来说，它们宣告了即使身戴枷锁，他们的兄弟会和反叛精神依然存在。"},{t="祖母的复仇",b="在十四岁的监狱守卫麦克·拉斯克发现囚犯们撕毁毯子制作这些面罩后，这些面罩便恶名昭著。当他试图惩罚囚犯时，迪菲亚囚犯们从背后刺杀了他。在他死后，他悲痛欲绝的祖母尼科瓦·拉斯克四处寻找冒险者，请求他们进入骚乱不断的监狱，除掉暴徒，并取回深红色的布料作为复仇的证明。"}},faq={{q="监狱里的囚犯是从哪里得到这些面罩的？",a="迪菲亚囚犯通过撕碎监狱配发的羊毛毯来制作它们。尽管被解除了武装并被囚禁，他们仍将自己匮乏的寝具变成了在牢房内佩戴的反抗标志。",al={"面罩来自哪里","监狱面罩来源","他们如何制作红色面罩"}},{q="谁想要收集这些面罩？",a="暴风城中一位悲痛欲绝的祖母尼科瓦·拉斯克请求冒险者收集这些面罩。她十四岁的孙子麦克曾是一名监狱守卫，在发现囚犯制作面罩后被囚犯杀害。",al={"谁需要红色毛纺面罩","血色任务发布者","尼科瓦·拉斯克面罩"}},{q="为什么囚犯们如此在意佩戴红色的围巾？",a="迪菲亚潜行者戴着红色面具和面罩，作为他们主要的帮派颜色和制服。在铁窗之后，制作和佩戴这些布料碎片让囚犯们得以维持他们的等级、士气和团结。",al={"为什么是红色面罩","迪菲亚红色标志","红色面罩的含义"}},{q="哪些囚犯携带这些东西？",a="几乎监狱里任何骚乱的迪菲亚成员都携带着它们，包括迪菲亚俘虏、囚徒、囚犯、暴动者和罪犯。",al={"谁掉落红色毛纺面罩","监狱面罩掉落"}}},fx={["7f0c1a2a"]={q="什么是红色毛纺面罩？",a="红色毛纺面罩是暴风城监狱里被囚禁的迪菲亚潜行者成员制作的深红色围巾。囚犯们把监狱发放的毛毯撕碎并染色，制成这种布制信物，以公开展示他们对迪菲亚潜行者的效忠，并在铁窗之后维持帮派身份。",al={"什么是红色毛纺面罩","红色毛纺面罩物品","监狱里的红色面罩"}}},fp="16,190,20.381.0,25.381.0,54.176.0,35.220.0,60.154.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="剩余的最纯净的水",s="剩余的最纯净的水是水语者布莱恩调配的一种特殊药水的最后残留。携带这些强效水滴的萨满祭司需要穿越各个王国，去净化一座被天灾军团的不死瘟疫所腐蚀的神圣水之圣殿。",h="剩余的最纯净的水是水语者布莱恩调配的一种特殊药水的最后残留。携带这些强效水滴的萨满祭司需要穿越各个王国，去净化一座被天灾军团的不死瘟疫所腐蚀的神圣水之圣殿。",kw={"永恒之泉火盆","布莱恩","call of water","被腐蚀的化身","最纯净的水","银松森林","水之图腾"},ang={["class:Shaman"]="这些水滴代表了你掌握水元素试炼的最终成果。将它们从干旱的贫瘠之地带到银松森林那片遭受摧残的海岸，对于获得你的水之图腾至关重要。",["faction:Horde"]="萨满祭司的朝圣之旅连接了卡利姆多的部落领地与银松森林中被遗忘者那岌岌可危的据点，展示了精神复苏对抗天灾军团枯萎病的力量。"},sec={{t="污秽之水的疗法",b="这种浓缩的药剂通过在卡利姆多和洛丹伦各地的仪式性收集而制成，保留了纯净水的最本质精华，由隐士布莱恩在贫瘠之地调制。虽然药水的一部分被消耗掉以赋予萨满祭司洞察遥远元素的视野，但剩余的水滴却被妥善保存，用于一项更为危险的任务。这些水滴被带到银松森林瑟伯切尔附近那片受瘟疫侵蚀的海岸，作为永恒之泉火盆上至关重要的净化催化剂。在仪式火焰中，它们与一个堕落且被腐蚀的元素生物的护腕一同焚烧，这纯净之水切断了亡灵的腐蚀，召唤出一个未受污染的水之灵魂，与萨满祭司沟通，从而完成他们与元素的融合。"}},faq={{q="这些水滴有什么用途？",a="它们被放置在银松森林海岸的永恒之泉火盆上，并与一个被腐蚀的水元素生物的护腕一起使用。这一仪式可以净化被腐蚀的元素圣殿，并召唤出一个未受腐蚀的水之灵魂。",al={"剩余的水滴有什么用","剩余的水滴的用途","使用最纯净的水"}},{q="这些液体来自哪里？",a="它们是由布莱恩调制的一种净化药水的剩余部分，布莱恩是一位居住在南贫瘠之地的一座小山上的兽人萨满祭司，这些药水是在有志向的萨满祭司进行精神试炼期间创造的。",al={"谁制作了最纯净的水","水滴的起源","布莱恩的水滴"}},{q="为什么仪式要在那么远的银松森林进行？",a="银松森林海岸、瑟伯切尔以西的一座水之圣殿被亡灵瘟疫所腐蚀，导致其中的元素之灵变得敌对且扭曲。净化那处特定的水潭证明了萨满祭司在漫长旅途中的虔诚与造诣。",al={"为什么去银松森林","为什么要前往银松森林","银松森林水之圣殿"}},{q="当它们接触到火盆时会发生什么？",a="当它们与被腐蚀的护腕一起被倒在火盆的火焰上时，水滴会发出噼啪声并投入火中，引燃一段咒语，从而净化残留的瘟疫并召唤出一个纯净的水之化身。",al={"火盆仪式","火盆上发生了什么","永恒之泉火盆仪式"}}},fp="31,120,27.558.0,30.216.0,31.191.0,61.236.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="阿鲁高的拯救",s="“阿鲁高的拯救”是法师阿鲁高在早期进行狼人魔法实验时写下的一道咒语。这道咒语被遗弃在银松森林的一座破旧农舍中，达拉尔·道恩维沃尔正在搜寻它，以解开这位巫师的黑暗作品。",h="“阿鲁高的拯救”是法师阿鲁高在早期进行狼人魔法实验时写下的一道咒语。这道咒语被遗弃在银松森林的一座破旧农舍中，达拉尔·道恩维沃尔正在搜寻它，以解开这位巫师的黑暗作品。",kw={"阿鲁高","arugal's folly","达拉尔·道恩维沃尔","积满灰尘的法术书","月怒","阿鲁高的拯救","瑟伯切尔","银松森林"},ang={["class:Mage"]="被遗忘者法师们会对阿鲁高笨拙、鲁莽的涉猎持有与达拉尔·道恩维沃尔相同的职业蔑视，但也认识到不受控制的召唤奥术所固有的危险。",["race:Undead"]="对于被遗忘者来说，获得这道咒语是抵御威胁银松森林边界的野性狼人的早期关键一步。"},sec={{t="法师的残余",b="在占领影牙城堡之前，大法师阿鲁高曾躲藏在银松森林河桥以北的一座废弃麦田农场里。在那里，在被遗忘的农具和腐烂的地板之间，他将自己的奇异技艺记录在一套积满灰尘的法术书中。名为“阿鲁高的拯救”的卷轴就在这些笔记之中，概述了他涉足导致当地居民遭受诅咒的危险变形术时，所设计出的早期方法和魔法配方。"},{t="被遗忘者的审视",b="达拉尔·道恩维沃尔是一位在瑟伯切尔活动的有造诣的被遗忘者施法者，他对阿鲁高的出身几乎没有什么尊重，认为这位前达拉然巫师的才智脆弱而透明。即便如此，道恩维沃尔也认识到，了解狼人诅咒背后的确切机制迫在眉睫。通过找回“阿鲁高的拯救”，被遗忘者的特工为道恩维沃尔提供了反制阿鲁高蔓延的威胁并为希尔瓦娜斯女士保卫银松森林所需的基础奥术知识。"}},faq={{q="什么是阿鲁高的拯救？",a="这是叛逃法师阿鲁高写下的一种魔法配方。它并非治愈药水，而是一道书面咒语，包含了他在银松森林首次开始尝试狼人魔法时所使用的奥术技巧。",al={"什么是阿鲁高的拯救","阿鲁高的拯救物品","拯救咒语"}},{q="这份拯救被留在了哪里？",a="阿鲁高将其留在了位于银松森林横跨河流的桥梁以北，一座废弃麦田农场二楼的一套积满灰尘的法术书中。",al={"哪里可以找到阿鲁高的拯救","阿鲁高的拯救位置","农场法术书"}},{q="达拉尔·道恩维沃尔为什么要这道咒语？",a="达拉尔·道恩维沃尔试图分析阿鲁高所使用的特定魔法，以便被遗忘者能开发出反制手段，希望利用这位巫师自己的方法来对付他，从而保卫该地区。",al={"达拉尔为何需要拯救","达拉尔·道恩维沃尔拯救"}},{q="是谁在看守农场的法术书？",a="农场里到处都是阿鲁高的狼人奴仆。当有人试图动二楼那些积满灰尘的法术书时，一只月怒暗行者就会从阴影中跳出来，保卫它主人的财物。",al={"农场会有什么攻击","法术书伏击"}}},fp="16,96,18.379.0,17.373.0,29.171.0,33.142.0,42.120.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="提炼过的孢子",s="提炼过的孢子是一种从贫瘠之地各地收集的菌类样本中制备而成的挥发性乳剂。它由位于十字路口的药剂师赫布瑞姆所创，如果不尽快送往雷霆崖下方的药剂师扎玛那里进行稳定，这种混合物会迅速变质。",h="提炼过的孢子是一种从贫瘠之地各地收集的菌类样本中制备而成的挥发性乳剂。它由位于十字路口的药剂师赫布瑞姆所创，如果不尽快送往雷霆崖下方的药剂师扎玛那里进行稳定，这种混合物会迅速变质。",kw={"药剂师赫布瑞姆","药剂师扎玛","贫瘠之地","十字路口","乳剂","预见之池","提炼过的孢子","雷霆崖"},ang={["race:Tauren"]="被遗忘者药剂师在神圣的预见之池内对贫瘠之地的奇怪植物进行实验，这反映了在雷霆崖内建立的不安且务实的联盟。",["race:Undead"]="皇家药剂师学会不断在卡利姆多各地寻找新的生物化合物以帮助被遗忘者，他们依靠快速的信使将像赫布瑞姆这样的外勤研究员与像扎玛这样的实验室专家联系起来。"},sec={{t="挥发性混合物",b="在从贫瘠之地潮湿绿洲附近的蘑菇中获取奇怪的菌类孢子后，药剂师赫布瑞姆将其加工成一种被称为提炼过的孢子的活性化学乳剂。这种精细的提取过程将真菌生长物中的强效化合物悬浮在液体介质中，但该溶液在化学性质上并不稳定。它只能保持四十五分钟的活性，随后就会分解，导致无法用于科学研究。"},{t="送往预见之池",b="由于赫布瑞姆在他偏远的前哨站缺乏必要的设施或时间来完成提炼过程，必须尽快将这种乳剂直接送往他的被遗忘者同事——药剂师扎玛那里。扎玛位于雷霆崖灵魂高地下方的预见之池地洞中，她拥有为皇家药剂师学会重新封存和完成孢子处理所需的专业设备和试剂。"}},faq={{q="提炼过的孢子有什么用途？",a="它们是药剂师赫布瑞姆提取并转化为乳剂的真菌物质，供皇家药剂师学会进行研究。药剂师扎玛在雷霆崖使用这种强效混合物，以继续他们对蔓延在贫瘠之地的奇怪生长物的调查。",al={"提炼过的孢子的用途","扎玛如何处理孢子","为什么要提炼孢子"}},{q="为什么这种乳剂有时间限制？",a="赫布瑞姆制造的化学乳剂具有高度挥发性，一旦混合就开始变质。其活性只能维持四十五分钟，因此需要一名信使在它失效前将其迅速穿过平原运往雷霆崖。",al={"为什么提炼过的孢子有时间限制","为什么孢子会失效","提炼过的孢子的持续时间"}},{q="谁制造了这些孢子？",a="药剂师赫布瑞姆，一位驻扎在贫瘠之地十字路口的被遗忘者研究员，将从绿洲附近的蘑菇中采集的原始菌类孢子提炼成了这种不稳定的液体化合物。",al={"谁制作了提炼过的孢子","谁来提炼这些孢子","赫布瑞姆的孢子"}},{q="这种混合物需要送到哪里？",a="孢子必须送到药剂师扎玛手中。她居住在预见之池的深处，那是一个隐藏在牛头人主城雷霆崖灵魂高地下方的洞穴系统。",al={"把提炼过的孢子送到哪里","扎玛的位置","预见之池的位置"}}},fp="15,175,18.269.0,31.309.0,34.217.0,40.225.0,25.157.0,34.131.0"}
P.entries["item:renferrel-s-findings"] = {n="伦弗利尔的研究成果",s="《伦弗利尔的研究成果》是药剂师伦弗利尔在银松森林编写的一系列研究笔记。这些文件被托付给部落信使，并被送往塔伦米尔交给药剂师林度恩，旨在为被遗忘者研制新瘟疫提供关键数据。",h="《伦弗利尔的研究成果》是药剂师伦弗利尔在银松森林编写的一系列研究笔记。这些文件被托付给部落信使，并被送往塔伦米尔交给药剂师林度恩，旨在为被遗忘者研制新瘟疫提供关键数据。",kw={"研究成果","林度恩","新瘟疫","伦弗利尔","皇家药剂师学会","瑟伯切尔","塔伦米尔"},ang={["faction:Horde"]="运送伦弗利尔文件的信使有助于巩固部落在洛丹伦的立足点，连接起像瑟伯切尔和塔伦米尔这样孤立的哨所。",["race:Undead"]="这些文件中的研究服务于希尔瓦娜斯·风行者的终极野心：完善一种新瘟疫，以消灭天灾军团和侵犯被遗忘者领地的生者敌人。"},sec={{t="瘟疫研发",b="皇家药剂师学会正在黑暗女王希尔瓦娜斯·风行者女士的直接命令下不知疲倦地工作，以设计一种新瘟疫。要取得这一突破，散布在洛丹伦各地的研究人员必须持续合作。药剂师伦弗利尔驻扎在银松森林的瑟伯切尔，他编写了这些研究成果来记录自己的进展和实验，并将收集到的情报送往南部的塔伦米尔，以便其他研究人员能够在此基础上继续研究。"},{t="前往塔伦米尔",b="将这些文件从银松森林带入希尔斯布莱德丘陵，是被遗忘者炼金网络中的关键一环。在塔伦米尔，药剂师林度恩急切地等待着伦弗利尔的笔记，以便进行交叉比对，并推进他自己对抗生者和天灾军团的药剂研究。如果没有可靠的信使在充满争议的希尔斯布莱德道路上奔波，学会的分散式研究很快就会停滞。"}},faq={{q="《伦弗利尔的研究成果》里有什么？",a="该包裹包含药剂师伦弗利尔在银松森林工作期间收集的最新实验数据和研究笔记，特别涉及被遗忘者新瘟疫的合成。",al={"什么是研究成果","伦弗利尔的研究","笔记里有什么"}},{q="谁应该接收这项研究？",a="药剂师林度恩接收这些文件。他在位于希尔斯布莱德丘陵的被遗忘者定居点塔伦米尔进行瘟疫研究。",al={"谁接收伦弗利尔的研究成果","研究成果送往何处","交付目标"}},{q="为什么药剂师们要分享笔记？",a="希尔瓦娜斯·风行者女士向皇家药剂师学会施加了巨大的压力，要求他们发明一种新瘟疫。药剂师们相信，如果他们进行协调并比较研究结果，而不是孤立地工作，他们将更快地取得突破。",al={"为什么要分享研究成果","为什么要送给林度恩","药剂师交流"}},{q="药剂师伦弗利尔在哪里进行实验？",a="药剂师伦弗利尔驻扎在瑟伯切尔，这是位于银松森林中心的主要被遗忘者哨所。",al={"伦弗利尔在哪里","药剂师伦弗利尔的位置","谁写了伦弗利尔的研究成果"}}},fx={bf8d559a={q="伦弗利尔的研究成果从何而来？是谁编写的？",a="这些文献由药剂师伦弗利尔撰写。他是一位雄心勃勃的研究者，驻扎在银松森林的瑟伯切尔。在被遗忘者的命令下，他勤勉工作，写下这些笔记，记录自己调制实验性药剂的进展与突破。",al={"谁写了伦弗利尔的研究成果","伦弗利尔的研究成果从何而来","伦弗利尔的研究成果作者"}},["21b2c0f4"]={q="为什么有人想要伦弗利尔的研究成果？",a="皇家药剂师协会正承受着希尔瓦娜斯·风行者女士施加的巨大压力，必须研制出一种新瘟疫。伦弗利尔相信合作能加快这项阴暗的事业，于是将研究成果寄给了塔伦米尔的药剂师林度恩。林度恩迫切希望研究这位同僚的方法，并将其融入自己的工作。",al={"为什么要送交伦弗利尔的研究成果","谁想要伦弗利尔的研究成果","林度恩为什么想要伦弗利尔的研究成果"}},f680c460={q="什么是伦弗利尔的研究成果？",a="伦弗利尔的研究成果是药剂师伦弗利尔汇编的一批炼金笔记和研究文件。这些资料详细记录了他代表皇家药剂师协会开展的持续实验，并打算直接分享给洛丹伦的同行。",al={"什么是伦弗利尔的研究成果","伦弗利尔的研究成果物品","这些研究成果是什么"}}},fp="20,205,23.364.0,14.359.0,36.173.0,41.139.0,39.195.0,56.127.0"}
P.entries["item:resonite-crystal"] = {n="共鸣水晶",s="共鸣水晶是狗头人在石爪山脉的滚岩洞穴中挖掘出的稀有矿石样本。他们疯狂的挖掘行为引起了烈日石居的摩罗加尔的担忧。",h="共鸣水晶是狗头人在石爪山脉的滚岩洞穴中挖掘出的稀有矿石样本。他们疯狂的挖掘行为引起了烈日石居的摩罗加尔的担忧。",kw={"滚岩","水晶","土灵","狗头人","摩罗加尔","共鸣水晶","石爪山脉","泰坦"},ang={["class:Shaman"]="对于萨满祭司来说，共鸣水晶带有一种令人不安的共鸣，他们能够识别出泰坦造物留下的、长期埋藏在山脉之下的休眠原始大地魔法。",["profession:Mining"]="与普通的铜矿或锡矿脉不同，共鸣水晶是一种高度浓缩的矿物，其开采需要深入地下深处，穿过极具攻击性的狗头人。"},sec={{t="远古共鸣",b="隐藏在滚岩峡谷深处的共鸣水晶成了狗头人突然疯狂挖掘的焦点。虽然普通的洞穴矿工通常寻找的是平凡的矿石或闪亮的小饰品，但狗头人对这些特定矿脉的痴迷立刻引起了烈日石居萨满祭司们的警觉。经过仔细检查，这些石头散发出与原始世界塑造之力相连的微弱魔法共鸣。摩罗加尔将这些微弱的能量识别为土灵魔法的痕迹，这表明这些挖掘生物闯入了一个由泰坦打造的古老地层。"},{t="汲取大地",b="共鸣水晶的发现向石爪山脉的部落证实了一个令人不安的消息：狗头人挖掘工已经挖得足够深，以至于惊扰了古老的土灵。由于土灵是泰坦直接塑造用来雕琢和塑造世界基石的生物，残余的魔法固执地附着在周围的岩石上。通过收集这些水晶，部落特工希望能解读狗头人疯狂的意图，并将这种附魔石头的力量反过来对抗地下任何被惊扰的沉睡力量。"}},faq={{q="共鸣水晶在哪里可以找到？",a="共鸣水晶可以在滚岩洞穴中找到，这是一个位于石爪山脉东南边缘、滚岩峡谷深处的洞穴。",al={"共鸣水晶位置","共鸣水晶在哪获取","共鸣水晶刷取"}},{q="为什么狗头人在开采共鸣水晶？",a="狗头人们正在疯狂地开采这种稀有水晶，但摩罗加尔尚不清楚原因。他请求获得样本并调查洞穴深处，以了解他们的活动。",al={"为什么狗头人要挖矿","狗头人水晶阴谋","滚岩洞穴狗头人"}},{q="共鸣水晶中蕴含着什么样的力量？",a="摩罗加尔怀疑这些水晶与山脉下方令人不安的事物有关。在样本和来自洞穴的消息传到他手中后，这种水晶的魔法本质才被确定。",al={"共鸣水晶魔法","什么是共鸣水晶","共鸣水晶有魔法吗"}},{q="谁在研究这些水晶？",a="驻扎在石爪山脉烈日石居的牛头人摩罗加尔正在调查这些水晶，以了解狗头人活动突然激增的原因，并寻找对策来对抗被揭露的邪恶势力。",al={"谁想要共鸣水晶","摩罗加尔水晶","烈日石居共鸣水晶"}},{q="与水晶相关的土灵是什么？",a="土灵是据说由泰坦创造用来塑造大地的生物。在摩罗加尔的任务中，会对它们与共鸣水晶之间可能的联系进行调查。",al={"什么是土灵","土灵与泰坦的联系"}}},fx={c14b6c8c={q="什么是共鸣水晶？",a="共鸣水晶是一种稀有矿物晶体，产自石爪山脉的滚岩洞穴。狗头人疯狂采矿的行为惊动了摩罗加尔，他希望得到样本和洞穴的消息，以便展开调查。",al={"什么是共鸣水晶","共鸣水晶的背景","共鸣矿石"}},af246400={q="为什么有人想要共鸣水晶？",a="摩罗加尔想要矿石样本，以弄清狗头人疯狂采矿的原因，并查明滚岩峡谷下方有什么。他请一位冒险者探索洞穴并收集水晶。",al={"为什么要收集共鸣水晶","谁想要共鸣水晶","共鸣水晶的用途"}}},fp="16,139,17.340.1,17.367.1,34.129.0,45.178.0,44.170.0,31.184.0,60.146.0"}
P.entries["item:restabilization-cog"] = {n="自适应齿轮",s="自适应齿轮是从诺莫瑞根辐射废墟外游荡的麻风侏儒身上回收的精密机械部件。在卡拉诺斯，侏儒修补匠需要这些完好的零件来制造重组器，这是一种旨在逆转麻风突变的雄心勃勃的机器。",h="自适应齿轮是从诺莫瑞根辐射废墟外游荡的麻风侏儒身上回收的精密机械部件。在卡拉诺斯，侏儒修补匠需要这些完好的零件来制造重组器，这是一种旨在逆转麻风突变的雄心勃勃的机器。",kw={"丹莫罗","吉布温特","诺莫瑞根","卡拉诺斯","麻风侏儒","重组行动","拉兹·滑链","自适应齿轮"},ang={["profession:Engineering"]="自适应齿轮的精确公差凸显了经典的侏儒设计，旨在承受不稳定的摩擦力并平衡重组器等精密的机械组件。",["race:Gnome"]="对于丹莫罗的流亡侏儒来说，回收这些组件是一项沉重的职责——从被腐蚀的同胞身上拆卸机械，怀揣着为诺莫瑞根的陨落者研制出治疗方法的绝望希望。"},sec={{t="治愈之组件",b="当辐射在一次旨在消灭入侵穴居人的灾难性尝试中淹没诺莫瑞根时，无数侏儒被扭曲成了病态且具有敌意的麻风侏儒。尽管他们已经疯狂，但这些受折磨的流亡者身上仍然携带着精密的侏儒机械和可回收配件。修补匠奥齐·电环和拉兹·滑链相信这种可怕的转变是可以系统性逆转的。为了完成他们的重组装置原型机，他们依靠冒险者直接从诺莫瑞根大门外的受害者身上回收关键部件，包括用于平衡机器内部燃烧系统的完好自适应齿轮。"}},faq={{q="自适应齿轮有什么用？",a="自适应齿轮是卡拉诺斯的修补匠拉兹·滑链所需要的。它们与陀螺机械齿轮一起，是建造重组器的关键结构件，重组器是一项旨在治愈受辐射麻风侏儒的实验性发明。",al={"齿轮用途","自适应齿轮有什么用","为什么要收集齿轮"}},{q="这些齿轮在哪里可以找到？",a="它们由那些疯狂的麻风侏儒以及在丹莫罗西部诺莫瑞根外的大门和沟壑中游荡的精神错乱的吉布温特携带。",al={"自适应齿轮位置","谁掉落齿轮","在哪里刷齿轮"}},{q="重组器真的能治愈麻风侏儒吗？",a="拉兹·滑链和奥齐·电环相信，校准得当的机器可以逆转这种突变。然而，侏儒工程学以其极不稳定性而闻名，重组器是否真的能恢复他们族人的心智和身体，仍是一项正在进行且未经测试的尝试。",al={"重组器有效吗","有治愈麻风侏儒的方法吗"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:ring-of-zoram"] = {n="佐拉姆之戒",s="佐拉姆之戒是一件古老的暗夜精灵传家宝，其历史可以追溯到大分裂之前沉没的佐拉姆城的辉煌岁月。它曾由城市统治者佩戴，也是开启古代雕像上古锁具的钥匙，最近落入了入侵的沿海娜迦手中。",h="佐拉姆之戒是一件古老的暗夜精灵传家宝，其历史可以追溯到大分裂之前沉没的佐拉姆城的辉煌岁月。它曾由城市统治者佩戴，也是开启古代雕像上古锁具的钥匙，最近落入了入侵的沿海娜迦手中。",kw={"古代雕像","灰谷","维斯皮娅女士","佐拉姆之戒","鲁泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="从娜迦手中夺回这枚戒指，可以帮助暗夜精灵学者塔尔伦在灰谷充满争议的边界线上收回被窃的卡多雷历史。",["race:NightElf"]="这枚戒指象征着大分裂之前的一段实实在在的遗产，来自那个卡多雷帝国尚未因奥术傲慢和淹没大地的海洋而分崩离析的时代。"},sec={{t="沉没之城的戒指",b="在永恒之井崩塌、大洋吞没卡利姆多西部边缘之前，佐拉姆曾是暗夜精灵帝国的一颗沿海明珠。佐拉姆之戒曾属于这座城市的统治者，其内环上用暗夜精灵语刻着一段奇怪的密码。一万年前大分裂摧毁了这片大陆时，这枚戒指随城市一同沉没，埋没在如今佐拉姆海岸的汹涌潮汐之下。"},{t="娜迦的回收",b="数千年来，这枚戒指一直埋在淤泥和废墟之下，直到娜迦开始搜刮灰谷的海岸线。居住在北部海岸外小岛上的娜迦领袖鲁泽尔在沉没的残骸中发现了这件文物。像暗夜精灵塔尔伦这样的学者寻找这枚戒指，不仅是因为它的古老，还因为它能作为开启从深海打捞出的其他遗物的唯一钥匙，其中包括从海底回收的密封古代雕像。"}},faq={{q="佐拉姆之戒有什么用途？",a="在大分裂导致佐拉姆城沉没之前，这枚戒指属于佐拉姆的统治者，它是开启一道古代锁具的钥匙。如今，塔尔伦专门寻找它，是为了打开一个从淹没的废墟中回收的古代雕像。",al={"佐拉姆之戒的用途","这枚戒指有什么用","佐拉姆之戒背景故事"}},{q="谁拥有佐拉姆之戒？",a="这枚戒指是由入侵佐拉姆海岸的沿海娜迦从废墟中打捞出来的。它主要由他们的领袖鲁泽尔保管在北海岸外的一座岛上，不过另一位著名的娜迦维斯皮娅女士也曾被发现携带它。",al={"谁有这枚戒指","佐拉姆之戒掉落","如何获得佐拉姆之戒"}},{q="塔尔伦为什么要寻找这枚戒指？",a="塔尔伦试图揭开从佐拉姆海岸回收的古代雕像的秘密。如果没有佐拉姆之戒作为钥匙，雕像的古代机制就无法打开。",al={"塔尔伦为何要找戒指","塔尔伦的戒指任务"}},{q="佐拉姆城去了哪里？",a="佐拉姆是一座古老的暗夜精灵城市，坐落在卡利姆多西缘，存在于一万年前大分裂之前。当永恒之井内爆时，这座城市被摧毁并淹没在海浪之下，只留下了佐拉姆海岸。",al={"佐拉姆发生了什么","佐拉姆城背景故事"}}},fx={["7e40c0d5"]={q="什么是佐拉姆之戒？",a="佐拉姆之戒是一件古老遗物，曾由沉没之城佐拉姆的统治者佩戴，直到大分裂的巨浪将这座城市淹没。戒指内侧用暗夜精灵语写着一段奇怪的密码，而它正是开启一尊从遗迹中找到的雕像上的古老锁具的钥匙。",al={"什么是佐拉姆之戒","佐拉姆之戒的背景","佐拉姆之戒物品"}},["770adfa7"]={q="佐拉姆之戒从何而来？是谁制造的？",a="这枚戒指源自大分裂前的暗夜精灵城市佐拉姆，位于古卡利姆多的海岸。它曾属于城中统治者；一万年前，灾难性的巨浪淹没了佐拉姆，这件遗物也随之沉入海底，直到最近才被娜迦从遗迹中打捞出来。",al={"佐拉姆之戒的来源","谁制造了佐拉姆之戒","佐拉姆之戒从何而来"}}},fp="13,162,23.397.0,23.387.0,35.188.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Robo-Mechanical Guts",s="Robo-Mechanical Guts是取自游荡在Gnomeregan废墟中发生故障的构造体的可回收齿轮装置、导管和机械内脏。位于Stormwind的侏儒工程师需要这些特定的组件来维修重型隧道掘进机，以协助收复位于Dun Morogh的Gnomeregan。",h="Robo-Mechanical...",kw={"发条装置","丹莫罗","诺莫瑞根","旋钻挖掘机","robo-mechanical guts","shoni","暴风城"},ang={["profession:Engineering"]="每一团回收的线路和陀螺齿轮都提醒着人们曾经的侏儒自动化设计巅峰，如今却因辐射和与世隔绝而悲剧性地变得狂暴。",["race:Gnome"]="拆解你失去家园中那些失控的发条哨兵虽然苦乐参半，但重新利用它们的内部机械却提供了收复Gnomeregan所需的切实零件。"},sec={{t="舰队打捞",b="当大工匠Gelbin Mekkatorque和幸存的侏儒撤离Gnomeregan时，数以千计的自动机械、发条哨兵和工业机器人被遗弃在里面。在城市遭受辐射的余波中，这些机器继续在走廊里自主游荡。在Stormwind City，技师Shoni试图组装一支旋钻挖掘机舰队，以突破Gnomeregan的防御并收复这座失落的城市。由于缺乏新鲜原材料，她指派勇敢的冒险者闯入Gnomeregan受污染的大厅，去拆解功能完好的机器人内脏——弹簧、电线和陀螺仪组件——来重新装备这些挖掘机械。"}},faq={{q="Robo-Mechanical Guts有什么用？",a="它们被位于Stormwind City的Shoni收集，用于维修一支旋钻挖掘机舰队——这是一种专门的隧道掘进车辆，旨在支持收复Dun Morogh的Gnomeregan的行动。",al={"机器人内脏的用途","robo-mechanical guts的使用","为什么要收集机械内脏"}},{q="在哪里可以找到这些组件？",a="它们可以从游荡在Gnomeregan郊区和深处的各种敌对发条自动机、机械装置和受污染的敌对生物身上搜刮而来。",al={"在哪里获得robo-mechanical guts","机器人内脏掉落位置","gnomeregan机器人零件"}},{q="Shoni是谁？她为什么需要这么多零件？",a="Shoni是一位雄心勃勃的侏儒工程师，驻扎在Stormwind的Dwarven District。她的任务是准备一整支地下挖掘机部队——总数近四百台——以突破被占领的Gnomeregan废墟。",al={"shoni是谁","stormwind的shoni","旋钻挖掘机舰队"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:rocket-car-parts"] = {n="火箭车零件",s="火箭车零件是散落在千针石林闪光平原上，因高速碰撞而扭曲的金属残骸。这些由地精和侏儒赛车手驾驶实验性飞车突破极限所产生的残片，被那些试图将赛道事故变成快钱的机会主义者所收集。",h="火箭车零件是散落在千针石林闪光平原上，因高速碰撞而扭曲的金属残骸。这些由地精和侏儒赛车手驾驶实验性飞车突破极限所产生的残片，被那些试图将赛道事故变成快钱的机会主义者所收集。",kw={"工程学","侏儒","地精","克拉维尔·浓须","沙漠赛道","火箭车零件","回收","闪光平原","千针石林"},ang={["profession:Engineering"]="散落在盐碱地上的烧焦齿轮和损坏的排气管残骸，证明了地精和侏儒工程哲学中的极端混乱。",["race:Dwarf"]="当侏儒和地精只关心比赛本身时，像克拉维尔·浓须这样有进取心的矮人证明了真正的利润在于拾取他们留下的残骸。"},sec={{t="速度、残骸与精明的商业",b="位于闪光平原的沙漠赛道是地精和侏儒工程学之间永无止境、充满火药味的竞争舞台。为了追求无与伦比的陆地速度，赛车手们经常遭遇灾难性的故障、爆炸性的失火以及高速撞车事故，将金属碎片散布在盐碱地上。这些被丢弃的残余物——从弯曲的气缸、烧焦的齿轮到被压扁的金属板——并不会在原地停留太久。拾荒者和商人们，尤其是那位投机取巧的矮人克拉维尔·浓须，会雇佣过往的冒险者去梳理那片白茫茫的荒原并收集这些残骸。由于两支赛车队都急需备用机械来拼凑他们的下一个原型车，这些回收的残骸可以很容易地被转手卖回给那些造成事故的车队。"}},faq={{q="这些火箭车零件从何而来？",a="它们是沙漠赛道上持续不断的碰撞、爆炸和机械故障留下的后果。侏儒和地精飞行员经常在千针石林广阔的盐碱地上将极不稳定、实验性的火箭动力车辆开到报废。",al={"为什么盐碱地上有零件","火箭车残骸来源","零件来自何处"}},{q="谁会购买这些回收的残片？",a="像矮人克拉维尔·浓须这样的商人会从流浪者那里收集这些残骸，然后转手将回收的齿轮、金属板和零件卖回给那些总是需要备用材料来修理和改进赛车的地精和侏儒们。",al={"谁想要火箭车零件","克拉维尔·浓须 火箭零件","谁会购买残骸"}},{q="拾取这些零件有危险吗？",a="残骸本身是惰性的，尽管有时会带着猛烈撞击的残酷痕迹，例如夹在金属中的断肢。主要的危险来自盐碱地上充满敌意的野生生物，包括蛇怪、焦灼的蝎虫以及徘徊在残骸区周围的捕食性盐碱秃鹫。",al={"拾取零件安全吗","收集零件时的威胁"}},{q="侏儒和地精会在意这些零件来自失事的赛车吗？",a="完全不在意。地精和侏儒选手对回收材料都不感到反感。他们唯一的优先级就是获得可用的装置、齿轮和金属板，以便组装出足够快的赛车，在赛道上超越对方。",al={"赛车手在意残骸吗","为什么地精会重复利用垃圾"}}},fx={["9a01e74a"]={q="什么是火箭车零件？",a="它们是闪光平原上高速赛车事故留下的散落残骸，包括松脱的齿轮、汽缸、扭曲的金属板和拆下来的小玩意。这些零件曾安装在轰鸣的实验赛车上，那些赛车由参加沙漠赛道竞速的地精和侏儒速度狂人制造。",al={"什么是火箭车零件","火箭车零件的背景","这些零件是什么"}}},fp="16,342,34.812.0,46.251.0,31.246.0,36.309.0,68.237.0"}
P.entries["item:rod-of-channeling"] = {n="导能魔棒",s="导能魔棒是湿地龙喉氏族施法者所携带的一种奥术法器。想要掌握召唤地狱猎犬的术士必须收集几根这样的魔棒，以便斯坦哈德·法尔杉的侍僧们能在棘齿城安全地固定仪式法阵。",h="导能魔棒是湿地龙喉氏族施法者所携带的一种奥术法器。想要掌握召唤地狱猎犬的术士必须收集几根这样的魔棒，以便斯坦哈德·法尔杉的侍僧们能在棘齿城安全地固定仪式法阵。",kw={"怒牙营地","白骨守卫者","龙喉氏族","地狱猎犬","导能魔棒","暗影守卫者","斯坦哈德·法尔杉","卡巴尔法典"},ang={["class:Warlock"]="获取三根导能魔棒是完成“卡巴尔法典”试炼的关键里程碑，它提供了禁锢你的第一只地狱猎犬所需的束缚力量。"},sec={{t="禁锢之器",b="当术士试图禁锢像地狱猎犬这样不稳定的掠食者时，单纯的意志力往往是不够的。斯坦哈德·法尔杉需要三根匹配的魔棒，让他的侍僧们能够协同引导魔法，在施术者进行禁锢仪式时稳定召唤法阵。龙喉氏族的黑暗施法者，包括在湿地的怒牙营地及周边废墟中出没的白骨守卫者和暗影守卫者，都携带着这些用于他们邪恶勾当的法器。虽然这些魔棒通常因战斗而磨损或带有缺口，但它们依然是能够引导混乱虚空能量的强力法器。"}},faq={{q="导能魔棒有什么用？",a="这些魔棒是交给棘齿城上方的术士斯坦哈德·法尔杉的。他的侍僧们使用这些魔棒来引导并稳固召唤和禁锢敌对地狱猎犬所需的魔法阵。",al={"什么是导能魔棒","导能魔棒用途","为什么需要导能魔棒"}},{q="在哪里可以找到导能魔棒？",a="它们由驻扎在湿地的龙喉氏族施法者所持有，特别是龙喉白骨守卫者和暗影守卫者，尤其是在怒牙营地附近。",al={"哪里获取导能魔棒","谁掉落导能魔棒","导能魔棒位置"}},{q="为什么斯坦哈德需要三根魔棒？",a="斯坦哈德雇佣了多名侍僧来协助地狱猎犬的召唤仪式。每位助手都需要一个专门的法器，以便在术士制服野兽时安全地维持能量传导。",al={"为什么需要三根魔棒","为什么需要三根导能魔棒"}},{q="为什么龙喉氏族要使用这些魔棒？",a="龙喉氏族修炼着旧部落遗留下来的黑暗萨满教义和暗影法术。他们的白骨守卫者和暗影守卫者使用这些魔棒在湿地持续不断的领土战争中引导诅咒、死灵法术和暗影魔法。",al={"龙喉魔棒","为什么龙喉氏族有这些魔棒"}}},fp="17,198,22.466.0,39.146.0,38.134.0,33.145.0,39.228.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="罗尔夫和马拉凯的铭牌",s="罗尔夫和马拉凯的铭牌是两名在艾尔文森林东部巡逻时失踪的暴风城卫兵的服役信物。这些物品上印有王国的徽章，卫兵托马斯希望能找到它们，以确定他失踪同僚的命运。",h="罗尔夫和马拉凯的铭牌是两名在艾尔文森林东部巡逻时失踪的暴风城卫兵的服役信物。这些物品上印有王国的徽章，卫兵托马斯希望能找到它们，以确定他失踪同僚的命运。",kw={"东谷伐木场","艾尔文森林","卫兵托马斯","马拉凯","铭牌","鱼人","罗尔夫","暴风城卫兵"},ang={["faction:Alliance"]="这些铭牌是一个沉重的提醒：即使在联盟的中心地带，当地的卫兵在守护乡村贸易路线时也面临着致命的危险。",["race:Human"]="对于艾尔文森林的人类来说，这些信物象征着失去的儿郎与保卫者，他们的死亡凸显了在军队被调往他处时，王国所面临的脆弱性。"},sec={{t="残酷的证实",b="当卫兵罗尔夫和马拉凯在艾尔文森林东部的河岸边失踪时，他们的驻地指挥官卫兵托马斯就预感到了最坏的情况。找回他们个人的卫兵铭牌，为他们死于日益逼近的鱼人之手提供了无可辩驳的证据。对于暴风城的驻军来说，这些信物不仅仅是饰品，它们代表了那些在王国军事力量捉襟见肘时，挺身抵御日益严重的荒野威胁而牺牲的士兵。"},{t="服役信物",b="和许多暴风城卫队及乡村巡逻队的成员一样，人类卫兵随身携带着身份铭牌，用以证明他们效忠于王冠并享有相应的职权。将这些物品归还给卫兵托马斯，让他能正式确认他失踪部下的下落，将他们的牺牲记录在战地报告中，并就鱼人部落在贸易道路附近聚集一事发出警报。"}},faq={{q="什么是罗尔夫和马拉凯的铭牌？",a="它们是卫兵罗尔夫和马拉凯随身携带的正式服役身份铭牌。这两名暴风城卫兵在艾尔文森林东部被鱼人伏击并杀害。",al={"什么是铭牌","罗尔夫的铭牌","马拉凯的铭牌"}},{q="这些铭牌属于谁？",a="它们属于卫兵罗尔夫和马拉凯，他们是卫兵托马斯麾下的同僚，负责看守闪金镇和东谷伐木场之间的河流与道路。",al={"罗尔夫和马拉凯是谁","谁的铭牌"}},{q="我应该把这些铭牌交给谁？",a="交给卫兵托马斯，他正在连接闪金镇与东谷伐木场的道路旁的东侧桥梁上值守。",al={"谁想要铭牌","我在哪里上交铭牌","铭牌上交"}},{q="为什么这些铭牌对卫兵托马斯如此重要？",a="卫兵托马斯派这两名卫兵去巡逻，他一直担心他们遭遇了不测。收到他们的铭牌证实了他们的死讯，这让他能够记录下他们的牺牲，并向暴风城通报日益严重的鱼人威胁。",al={"为什么托马斯想要它们","卫兵托马斯的反应"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:rot-blossom"] = {n="腐败之花",s="腐败之花是一种邪恶、坏死的植物，生长在暮色森林被亵渎的坟墓之间。它们以受到枯萎病感染的土壤和亡灵残骸为食，因其强效且不详的炼金特性而备受追捧。",h="腐败之花是一种邪恶、坏死的植物，生长在暮色森林被亵渎的坟墓之间。它们以受到枯萎病感染的土壤和亡灵残骸为食，因其强效且不详的炼金特性而备受追捧。",kw={"althea ebonlocke","夜色镇","暮色森林","腐败之花","骷髅魔","骷髅恐怖兵","静谧花园墓场","僵尸药水"},ang={["faction:Alliance"]="冒险进入被诅咒的土壤来采集这些病态的花朵，同时也是为夜镇卫兵效力，有助于保持夜色镇边境远离贪婪的骷髅。",["profession:Herbalism"]="与受到阳光和雨水滋养的标准草药不同，腐败之花是纯粹以坏死腐烂物和墓地土壤为食的邪恶植物变异体，是研究腐化植物群的一个阴森样本。"},sec={{t="墓穴的植物群",b="暮色森林中反自然的腐化孕育出了诡异且令人不安的植物，其中最令人不安的莫过于腐败之花。这些病态的花朵扎根于静谧花园墓场等墓地的污秽土壤中，在死亡气息浓郁的地方茁壮成长。当地传言称，它们甚至可以在行尸走肉裂开的颅骨中扎根，尤其是那些徘徊在古坟间的骷髅恐怖兵和骷髅魔。对于夜色镇的当地居民来说，采集它们既是一项阴森的苦差事，也是一种危险的必要手段，因为翻动它们的土壤意味着必须面对那些不安息的亡者。"},{t="一种骇人的原料",b="尽管腐败之花令人厌恶，但它们在当地的药剂配方中却有着特殊用途。这种花朵含有酿造“僵尸药水”所需的黑暗精华，这是一种与暮色森林中骇人听闻的生存尝试息息相关的恶臭药剂。那些被派去采集这种花朵的人往往会无意中帮助夜镇卫兵，顺手铲除那些在闹鬼墓地中徘徊的骷髅。"}},faq={{q="在哪里可以找到腐败之花？",a="腐败之花生长在暮色森林墓地的腐化土壤中，尤其是在静谧花园墓场内，并且据称会从不死骷髅魔的遗骸中长出。",al={"腐败之花生长在哪里","腐败之花位置","寻找腐败之花"}},{q="腐败之花有什么用？",a="它们是当地酿酒师和炼金术士用来蒸馏一种名为“僵尸药水”的强效恶臭混合剂的关键原料。",al={"腐败之花的用途","为什么要采集腐败之花","腐败之花为什么有用"}},{q="为什么这些花会生长在骷髅里？",a="暮色森林中挥之不去的黑暗魔法感染了大地和不安息的亡者。腐败之花直接以坏死的腐化和腐烂为食，这使得它们可以在游荡的骷髅的颅骨和胸腔内发芽。",al={"骷髅里的腐败之花","骷髅恐怖兵之花","骷髅与腐败之花"}},{q="采集腐败之花如何帮助夜色镇？",a="任何冒险进入静谧花园等地采集花朵的人，必然会消灭那些困扰该地区的骷髅恐怖兵和骷髅魔，为 Althea Ebonlocke 和受困的夜镇卫兵提供了急需的支援。",al={"althea ebonlocke 腐败之花","夜镇卫兵腐败之花","帮助夜色镇"}}},fx={["93f3afdd"]={q="什么是腐败之花？",a="腐败之花是一种阴森的奇异植物，生长在暮色森林遭受污染的墓地里。它们不在肥沃的土壤中发芽，反而在腐朽之地茁壮生长，尤其喜欢在亡灵骷髅恐兽和骷髅恶魔的空洞头骨中扎根。这些花浸染着污秽能量，当地一些古怪居民会用腐败之花调制强效药剂，因此四处寻觅它们。",al={"什么是腐败之花","腐败之花物品"}}},fp="11,151,19.349.0,21.281.0,32.178.0,31.94.0,40.192.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="腐皮豺狼人的脓液",s="腐皮豺狼人的脓液是从那些盘踞在洛丹米尔湖中芬里斯岛上的亡灵腐皮豺狼人身上采集到的一种恶臭体液。药剂师伦弗利尔在瑟伯切尔收集这种物质的样本，旨在揭开这些豺狼人堕落的源头，并制定针对它们的战略。",h="腐皮豺狼人的脓液是从那些盘踞在洛丹米尔湖中芬里斯岛上的亡灵腐皮豺狼人身上采集到的一种恶臭体液。药剂师伦弗利尔在瑟伯切尔收集这种物质的样本，旨在揭开这些豺狼人堕落的源头，并制定针对它们的战略。",kw={"药剂师伦弗利尔","芬里斯岛","洛丹米尔湖","腐皮豺狼人","腐皮豺狼人的脓液","瑟伯切尔","银松森林"},ang={["race:Undead"]="对于被遗忘者来说，研究这种脓液是巩固银松森林东翼，并提升皇家药剂师学会对瘟疫科学掌握程度的关键军事情报。"},sec={{t="血液中的瘟疫",b="芬里斯岛上的腐皮豺狼人并非普通的野兽；它们身体明显腐烂，且被某种非自然的枯萎病所扭曲。它们的血管里流淌的并非正常的血液，而是一种支撑其躯体活动的有害脓液。皇家药剂师学会怀疑，这种液体中隐藏着这群豺狼人是如何被腐化，以及是谁在芬里斯岛那座废墟城堡中指挥它们的秘密。"},{t="药剂师的研究",b="药剂师伦弗利尔在瑟伯切尔收集这种脓液的药剂瓶，以分析其特性。通过分离驱动这些豺狼人的化学和魔法成分，被遗忘者希望在跨越洛丹米尔湖发动全面进攻之前，找出它们的弱点。"}},faq={{q="腐皮豺狼人的脓液从何而来？",a="它采集自居住在芬里斯岛上的腐皮豺狼人的尸体，该岛位于银松森林大陆以东的洛丹米尔湖中。",al={"哪里获得腐皮豺狼人的脓液","如何找到腐皮豺狼人的脓液","豺狼人脓液位置"}},{q="为什么药剂师伦弗利尔需要这种脓液？",a="伦弗利尔试图剖析这种奇异的液体，以发现是什么腐化了这些豺狼人，并找出被遗忘者在进攻该岛之前可以利用的任何物理或炼金术层面的弱点。",al={"为什么伦弗利尔需要脓液","伦弗利尔任务原因","腐皮豺狼人的脓液用途"}},{q="腐皮豺狼人是天灾军团吗？",a="它们是被瘟疫扭曲的亡灵豺狼人，但被遗忘者正在积极调查究竟是谁或什么力量创造了它们，并指挥它们在芬里斯岛上的行动。",al={"腐皮豺狼人是天灾军团吗","谁控制了腐皮豺狼人","什么是腐皮豺狼人"}},{q="所有的豺狼人都有这种脓液吗？",a="不。这种液体是腐皮氏族独有的，它们的血肉已被污秽的死灵枯萎病所腐蚀。",al={"所有豺狼人都掉落脓液吗","普通豺狼人的血液"}}},fp="14,188,21.335.0,19.249.0,36.130.0,46.166.0,32.142.0,30.108.0"}
P.entries["item:rough-quartz"] = {n="粗石英",s="粗石英是一种质朴的元素之石，由大地之魂赠予萨满学徒。虽然它小而未经雕琢，却是制作萨满第一根大地图腾所需的至关重要的精神核心。",h="粗石英是一种质朴的元素之石，由大地之魂赠予萨满学徒。虽然它小而未经雕琢，却是制作萨满第一根大地图腾所需的至关重要的精神核心。",kw={"call of earth","坎纳甘·地鸣","大地图腾","大地之魂","粗石英","试炼谷"},ang={["class:Shaman"]="粗石英代表了你与大地元素的第一次沟通，它稳固了你的法术，并标志着你作为一名真正的灵魂导管所踏上的道路。"},sec={{t="大地图腾之心",b="在未经训练的人眼中，粗石英看起来不过是沙漠里的普通砾石。但对于在杜隆塔尔或莫高雷与灵魂沟通的萨满来说，这是由大地之魂直接赐予的元素礼物。这种石头象征着耐力、耐心和坚定不移的力量。当把它交给试炼谷的坎纳甘·地鸣等长者时，石英会被嵌入大地图腾的木雕中，作为连接初出茅庐的萨满与艾泽拉斯大地母亲的精神焦点。"}},faq={{q="粗石英有什么用途？",a="它证明了萨满学徒已经与大地元素灵魂进行了沟通。年长的萨满在为入门者雕刻第一根大地图腾时，会使用这块砾石作为精神核心。",al={"粗石英的作用","粗石英用途","为什么需要粗石英"}},{q="谁会给你粗石英？",a="在杜隆塔尔或莫高雷进行Call of Earth仪式并与灵魂沟通后，它会由大地之魂赐予。",al={"哪里获得粗石英","粗石英掉落来源"}},{q="在杜隆塔尔我该把这块石头交给谁？",a="把它交给住在试炼谷的萨满训练师坎纳甘·地鸣，他会将其制作成你的大地图腾。",al={"粗石英上交地点","粗石英上交","谁接受粗石英"}},{q="这种石英还有其他用途吗？",a="没有。它纯粹是一种神圣的仪式物品，仅用于制作大地图腾，在普通交易中没有任何用途。",al={"粗石英可以出售吗","粗石英是否用于制作"}}},fp="12,149,24.435.0,40.178.0,31.143.0,40.127.0,38.109.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="海格纳的弹药",s="“海格纳的弹药”是一箱运往丹莫罗枪匠海格纳·重枪的弹药，但在运输途中遗失了。由于一名惊慌失措的信使在遭到饥饿的雪怪袭击时弃货逃走，这箱沉重的补给品现在被遗弃在灰色洞穴附近的雪地里。",h="“海格纳的弹药”是一箱运往丹莫罗枪匠海格纳·重枪的弹药，但在运输途中遗失了。由于一名惊慌失措的信使在遭到饥饿的雪怪袭击时弃货逃走，这箱沉重的补给品现在被遗弃在灰色洞穴附近的雪地里。",kw={"弹药","补给箱","丹莫罗","灰色洞穴","海格纳","洛斯洛尔","重枪","雪怪"},ang={["class:Hunter"]="对于在丹莫罗严寒中游荡的神射手来说，保持海格纳的火药干燥并储备充足的弹丸，是确保矮人枪械持续拥有弹药供应的关键。",["profession:Engineering"]="矮人工程师和技工非常依赖源源不断的弹丸和火药供应，以便测试他们制造的枪械和实验性武器。"},sec={{t="滞留的货物",b="海格纳·重枪在从寒脊山小径通往安威玛尔的山路上经营着一家路边武器店。由于铁炉堡的火枪手、登山者和矮人迫击炮小队经常在高山雪地中进行演习，他的补给消耗速度极快，简直就像火药遇火即燃一样。这批特殊的弹药是由洛斯洛尔从卡拉诺斯发出的，但却从未上架。负责运送的信使在灰色洞穴附近的掠食性雪怪出没区扎营，结果遭到袭击时因惊恐而逃命，将沉重的补给箱留在了野兽的猎场深处。"}},faq={{q="海格纳·重枪是谁？",a="海格纳·重枪是一位矮人枪匠，在通往安威玛尔的路上经营着一家商店。他主要为当地的神射手、猎人和军方炮手提供服务，这些人在丹莫罗的峭壁中训练时会迅速消耗弹药。",al={"重枪","海格纳是谁","枪械商人"}},{q="弹药箱是怎么丢失的？",a="一名负责运送该货箱的信使犯了一个错误，他在灰色洞穴的入口附近扎营。当洞穴中领地意识极强的雪怪袭击他的营地时，惊恐万分的信使落荒而逃，把沉重的货箱遗弃在了雪地里。",al={"为什么弹药会丢失","弹药发生了什么","信使弹药"}},{q="灰色洞穴在哪里？",a="灰色洞穴是一个开凿在卡拉诺斯西南方山脉中的洞穴系统。它是丹莫罗凶恶的雪怪的著名巢穴，使得周围的山坡对独行旅客来说十分危险。",al={"灰色洞穴位置","雪怪洞穴在哪里"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="符文羊皮纸",s="这是一封递交给试炼谷中渴望成为萨满的兽人新手的书面信函。它由训练师史克里克书写，并由高内克分发，号召受训者承担起作为精神领袖和元素之灵沟通者的职责。",h="这是一封递交给试炼谷中渴望成为萨满的兽人新手的书面信函。它由训练师史克里克书写，并由高内克分发，号召受训者承担起作为精神领袖和元素之灵沟通者的职责。",kw={"杜隆塔尔","高内克","羊皮纸","符文羊皮纸","萨满","史克里克","试炼谷"},ang={["class:Shaman"]="这份符文羊皮纸标志着你踏上了元素之道的第一步，将你置于史克里克的教导之下，学习祖先崇拜和元素掌握的知识。",["race:Orc"]="萨满传统的重现是新部落的核心，而这份羊皮纸代表了杜隆塔尔先祖智慧的延续。"},sec={{t="灵魂的召唤",b="在试炼谷那被烈日炙烤的峡谷中，新的兽人萨满在资深监督者的注视下开始了他们的训练。当新手为高内克执行初步试炼时，会收到这份布满符文的文档。这封信直接由当地的萨满教导员史克里克发出，作为正式召唤，引导他们去探寻元素沟通的深层奥秘。兽人文化不仅将萨满视为战场上的施法者，更视为生者与先祖之间不可或缺的调解人。这份简短的文书标志着从单纯的蛮力向崇敬先祖的严谨道路的转变。"}},faq={{q="什么是符文羊皮纸？",a="这是一份由高内克在试炼谷分发给兽人萨满新手的亲笔书信。它指示读者前往向萨满训练师史克里克报到，以开始正式的训练。",al={"符文羊皮纸","这个物品是什么","萨满羊皮纸"}},{q="谁写了这封羊皮纸？",a="这封羊皮纸是由驻扎在试炼谷的萨满训练师史克里克所写，他希望以此指导年轻的新手学习元素之道和先祖之灵的知识。",al={"谁发出的羊皮纸","羊皮纸作者"}},{q="为什么萨满在兽人中被视为天选者？",a="兽人萨满担任着精神向导和先祖沟通者的角色，他们倾听元素之灵的声音来指引族人。史克里克提醒学徒们，他们的职责既包括治愈盟友，也包括驾驭元素之怒来对抗敌人。",al={"为什么要成为萨满","兽人萨满职责"}}},fp="24,160,24.441.0,37.144.0,24.151.0,49.247.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Rune-Inscribed Pendant",s="Rune-Inscribed Pendant 是从运往安伯米尔的达拉然补给品中寻获的魔法饰品。这些吊坠受到肯瑞托的重视，被用作引导强大奥术能量的管道。",h="Rune-Inscribed Pendant 是从运往安伯米尔的达拉然补给品中寻获的魔法饰品。这些吊坠受到肯瑞托的重视，被用作引导强大奥术能量的管道。",kw={"奥利斯特","安伯米尔","达拉尔·道恩维沃尔","达拉然","肯瑞托","吊坠","rune-inscribed pendant","瑟伯切尔"},ang={["class:Mage"]="法师们很容易认出肯瑞托的工艺；刻在吊坠上的符文旨在引导高阶法术时稳定不稳定的能量流。",["race:Undead"]="对于守卫银松森林的被遗忘者来说，像这样截获的达拉然聚焦器提供了关于安伯米尔围墙后聚集的人类抵抗力量的重要情报。"},sec={{t="肯瑞托圣物",b="这枚吊坠是在运往安伯米尔达拉然飞地的制图补给箱中发现的，上面刻有复杂的奥术铭文。肯瑞托的高阶法师经常使用此类神器来聚焦并增强他们的施法能力。大量引导吊坠流入该地区引起了瑟伯切尔被遗忘者的警觉，这预示着一项巨大的魔法工程即将展开。"},{t="安伯米尔计划的线索",b="当被带到瑟伯切尔时，暗影牧师奥利斯特意识到了达拉然法师防御阵地所带来的威胁，但他将这件圣物转交给达拉尔·道恩维沃尔进行更深入的研究。道恩维沃尔认定该吊坠是法师行动的关键组成部分，并推断肯瑞托正在囤积奥术聚焦工具，以便在安伯米尔的边境后方开展大规模的防御或进攻行动。"}},faq={{q="Rune-Inscribed Pendant 有什么用？",a="肯瑞托的法师利用这枚吊坠来引导和控制大量的魔法能量流。它不仅仅是装饰品，更是复杂法术运作的奥术焦点。",al={"吊坠的作用","吊坠的用途","符文吊坠的用途"}},{q="这枚吊坠从哪里来？",a="它是从运往银松森林安伯米尔的补给品中截获的，肯瑞托的残部在那里构筑了坚固的防御工事。",al={"在哪里找到吊坠","吊坠的来源","它是在哪里发现的"}},{q="谁在瑟伯切尔研究这枚吊坠？",a="暗影牧师奥利斯特在结合缴获的地图进行简要检查后，将其送交给了瑟伯切尔的奥术专家达拉尔·道恩维沃尔，后者认出了这是肯瑞托的手笔。",al={"谁在研究吊坠","谁想要吊坠","达拉尔吊坠"}},{q="为什么被遗忘者对它感到担忧？",a="大批引导吊坠的运输表明，安伯米尔的肯瑞托正在筹备一项大规模的魔法工程，威胁到了被遗忘者对银松森林的控制。",al={"为什么被遗忘者会在意","安伯米尔的威胁","为什么吊坠很危险"}}},fx={bf28d080={q="Rune-Inscribed Pendant是什么？",a="这是一件由达拉然强大的法师制作并使用的奥术神器。肯瑞托经常借助此类坠饰聚集并引导巨大的魔法能量。它们并非普通饰物，而是强大奥术力量的导体。",al={"符文坠饰是什么","符文坠饰的身份","这是什么达拉然坠饰"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="符文石板",s="符文石板是送给试炼谷年轻暗矛巨魔萨满祭司的一则石质讯息。它由高内克亲手交出，指引有潜力的神秘修行者在兽人训练师史克里克的指导下，开始与元素进行正式的交流。",h="符文石板是送给试炼谷年轻暗矛巨魔萨满祭司的一则石质讯息。它由高内克亲手交出，指引有潜力的神秘修行者在兽人训练师史克里克的指导下，开始与元素进行正式的交流。",kw={"暗矛","杜隆塔尔","高内克","符文石板","萨满","史克里克","训练师","试炼谷"},ang={["class:Shaman"]="这块石板代表了萨满祭司掌握土、火、水、气四种元素迈出的正式第一步，提醒着学生们，他们的力量源于先祖之魂。",["race:Troll"]="对于暗矛巨魔来说，响应一名兽人训练师的召唤，凸显了巨魔与其新部落盟友之间日益增长的纽带和共同的精神道路。"},sec={{t="灵魂的召唤",b="这块刻有元素符文的石板，是刚踏上杜隆塔尔土地的初出茅庐的巨魔萨满祭司所收到的正式邀请。当一名学徒在试炼谷证明了自己的勇气后，监工高内克会递出这块由巨魔萨满伊什尤（Ishi-yo）送来的石头，指引学徒前往萨满训练师史克里克处。对于暗矛巨魔而言——他们拥有自己深厚的精神传统——这块石板标志着他们与兽人共同道路的开端，将古老的巨魔神秘主义与大酋长萨尔所倡导的萨满教义传统联系在了一起。"}},faq={{q="符文石板的用途是什么？",a="这块石板是高内克传递给试炼谷年轻巨魔萨满祭司的一则介绍性讯息。它指示学徒前往当地的萨满训练师史克里克处，开始他们正式的精神教育。",al={"石板用途","石板的作用","符文石板的使用"}},{q="谁发送了这块石板？",a="这块石板由巨魔萨满伊什尤（Ishi-yo）署名，正是她教导了学徒最初的课程。她将学徒引荐给驻扎在试炼谷大兽穴外的兽人萨满训练师史克里克，后者早已知晓他们的到来。",al={"谁写了石板","石板发送者","谁雕刻的石板"}},{q="谁会收到这块石板？",a="只有初到杜隆塔尔的新晋暗矛巨魔萨满祭司才会从高内克那里收到这块特殊的石板，作为他们的初始职业召唤。",al={"谁能获得符文石板","哪个职业获得石板"}}},fp="21,167,24.339.0,43.141.0,21.174.0,25.108.0"}
P.entries["item:rune-of-nesting"] = {n="筑巢符文",s="筑巢符文是保存在泰达希尔班奈希尔兽穴中的四件神圣觉醒圣物之一。它是德鲁伊通过微妙的仪式安全地将沉睡中的利爪德鲁伊从翡翠梦境中唤醒的必要组成部分。",h="筑巢符文是保存在泰达希尔班奈希尔兽穴中的四件神圣觉醒圣物之一。它是德鲁伊通过微妙的仪式安全地将沉睡中的利爪德鲁伊从翡翠梦境中唤醒的必要组成部分。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","筑巢宝箱","利爪德鲁伊","翡翠梦境","觉醒圣物","筑巢符文"},ang={["class:Druid"]="对于德鲁伊来说，筑巢符文代表了塞纳里奥议会的神圣仪式，凸显了在神圣避难所被攻破时，沉睡的同胞所面临的脆弱处境。",["race:NightElf"]="兽穴的亵渎和这些觉醒圣物的丢失，突显了困扰着泰达希尔野生动物和熊怪的腐蚀正在日益加剧。"},sec={{t="唤醒的神圣焦点",b="暗夜精灵德鲁伊会在地下兽穴中进行深度的周期性冬眠，以便通过翡翠梦境与自然交流。从这种深沉的恍惚状态中醒来不仅仅是苏醒那么简单，这需要借助神圣器具引导的精确仪式。保存在班奈希尔兽穴蜿蜒密室中筑巢宝箱里的筑巢符文，正是这一过程的锚点。连同鸦爪神符、黑色羽毛和天蓝宝石一起，该符文充当了将利爪德鲁伊召回清醒世界的媒介。"},{t="班奈希尔的危机",b="当受到腐蚀的棘皮熊怪占领了班奈希尔兽穴时，兽穴中沉睡的守卫者陷入了迫在眉睫的危险之中。无法接触到这些圣物，德鲁伊们就有可能被永久困在翡翠梦境中，而入侵者则会亵渎他们的圣地。找回筑巢符文及其配套的圣物，阿斯瑞达斯·熊皮才能在多兰纳尔准备必要的仪式，安全地唤醒这些处于危险之中的德鲁伊。"}},faq={{q="筑巢符文有什么用？",a="它是阿斯瑞达斯·熊皮进行仪式所需的四件觉醒圣物之一，该仪式能安全地将利爪德鲁伊从翡翠梦境的深沉睡眠中唤醒。",al={"筑巢符文有什么用","筑巢符文的用途"}},{q="筑巢符文在哪里可以找到？",a="它储存在筑巢宝箱内，位于泰达希尔多兰纳尔以西的班奈希尔兽穴的地下隧道中。",al={"筑巢符文在哪里","筑巢宝箱的位置"}},{q="为什么沉睡的德鲁伊不能自己醒来？",a="在冬眠期间进入翡翠梦境是一种微妙的、恍惚的状态。没有神圣圣物和觉醒仪式的引导，回归是不可能的，这会让他们的意识漂流不定，而肉体则暴露在危险之中。",al={"为什么德鲁伊需要觉醒仪式","为什么德鲁伊无法醒来"}},{q="除了筑巢符文外，还需要哪些圣物？",a="完整的仪式需要四件觉醒圣物：筑巢符文、鸦爪神符、黑色羽毛和天蓝宝石。",al={"其他的觉醒圣物","觉醒圣物道具"}}},fp="15,191,28.504.0,19.370.0,37.221.0,35.139.0,58.228.0,59.140.0"}
P.entries["item:runes-of-summoning"] = {n="召唤符文",s="召唤符文是由幽暗城Magic Quarter的术士训练师凯伦丁·哈加尔提供的一种仪式物品。它们用于将一个不受束缚的虚空行者召唤到召唤法阵中，以便有抱负的术士将其意志折服。",h="召唤符文是由幽暗城Magic Quarter的术士训练师凯伦丁·哈加尔提供的一种仪式物品。它们用于将一个不受束缚的虚空行者召唤到召唤法阵中，以便有抱负的术士将其意志折服。",kw={"凯伦丁·哈加尔","magic quarter","召唤符文","束缚仪式","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="被遗忘者术士使用这些符文来证明他们对虚空的统治力，将混乱的暗影转化为持久、忠诚的爪牙。",["race:Undead"]="在幽暗城的地下深处，被遗忘者修行者无视古老的禁忌，在洛丹伦废墟的正下方束缚虚空实体。"},sec={{t="在Magic Quarter的征服",b="在幽暗城Magic Quarter黑暗的角落里，被遗忘者的暗影技艺修行者研究着如何操纵虚空。凯伦丁·哈加尔只将召唤符文交给那些已经准备好掌控虚空行者的术士。修行者通过在哈加尔所在平台下方的活跃召唤法阵中使用符文，撕裂虚空的结构，引出一只必须被压制并束缚为仆从的生物。"}},faq={{q="召唤符文是用来做什么的？",a="它们被用于幽暗城Magic Quarter的召唤法阵中，将一只不受束缚的虚空行者从虚空拉入物质世界，让术士能够击败并征服它。",al={"召唤符文的用途","召唤符文的作用","如何使用召唤符文"}},{q="谁提供了召唤符文？",a="位于幽暗城Magic Quarter的被遗忘者术士训练师凯伦丁·哈加尔，会在束缚虚空行者的最后阶段训练中提供它们。",al={"谁给予召唤符文","召唤符文训练师","凯伦丁·哈加尔符文"}},{q="符文必须在何处激活？",a="它们必须被带到位于Magic Quarter中凯伦丁·哈加尔平台正下方的紫色召唤法阵处。",al={"在哪里使用召唤符文","召唤符文位置","幽暗城召唤法阵"}},{q="实体被召唤后会发生什么？",a="虚空行者会立即发动攻击。术士必须通过魔法和武力将其压制。一旦被击败，该实体就会被契约束缚，凯伦丁·哈加尔便会传授召唤它的永久法术。",al={"使用符文后会发生什么","虚空行者压制","召唤虚空行者之后"}}},fp="18,205,32.371.0,41.210.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:sack-of-murloc-heads"] = {n="一袋鱼人的头颅",s="“一袋鱼人的头颅”是在希尔斯布莱德丘陵沿岸收集的一袋令人毛骨悚然的战利品。作为针对当地海岸害虫采取军事行动的证明，法尔林·奥里涅尔中尉将它转手交给路过的冒险者，让他们送往南海镇交给治安官雷德帕斯。",h="“一袋鱼人的头颅”是在希尔斯布莱德丘陵沿岸收集的一袋令人毛骨悚然的战利品。作为针对当地海岸害虫采取军事行动的证明，法尔林·奥里涅尔中尉将它转手交给路过的冒险者，让他们送往南海镇交给治安官雷德帕斯。",kw={"赏金","法尔林·奥里涅尔","头颅","希尔斯布莱德","治安官雷德帕斯","鱼人","南海镇"},ang={["faction:Alliance"]="这次交付生动地展示了南海镇的守军在维持这片联盟北部飞地时所面临的物流窘境和繁琐沉重的日常负担。"},sec={{t="官僚主义与沿海祸害",b="南海镇始终处于辛迪加亡命徒、被遗忘者散兵游勇以及聚集在海岸的野生鱼人的围攻之下。为了从城镇领导层获得资金和支持，当地军官必须证明海岸威胁正在被积极肃清。法尔林·奥里涅尔中尉收集了断头作为证据，但由于这些货物令人作呕——再加上他自己容易反胃——促使他将这袋还在滴水的包裹交给路人，而不是亲自将这些恐怖的证据送交给治安官雷德帕斯。"}},faq={{q="什么是“一袋鱼人的头颅”？",a="这是一个装满了从希尔斯布莱德西部海滩收集的鱼人断头的麻布袋。它作为南海镇指挥官管辖区域内海岸平定的实质性证据。",al={"头颅袋","鱼人袋","这是什么物品"}},{q="为什么法尔林中尉不亲自送去？",a="法尔林觉得提着一袋发臭的腐烂鱼人脑袋令人反感。为了保持制服和双手的整洁，他把这件令人不快的苦差事转交给了南海镇里乐于助人的冒险者。",al={"为什么法尔林让你来带","法尔林的借口","偷懒的法尔林"}},{q="谁会收到这袋头颅？",a="这袋战利品将被送交给治安官雷德帕斯，他是负责南海镇防御工作的指挥官，负责评估城镇的安全状况并要求防御工作有确凿的证明。",al={"谁来接收头颅","我该带到哪里去","向治安官雷德帕斯交任务"}},{q="为什么南海镇需要鱼人头颅作为证明？",a="鱼人不断袭击海岸线并威胁港口。军官们被要求核实巡逻队是否在维持边界安全，而这种实实在在的战利品能确保没有士兵在偷懒闲逛时冒领功劳。",al={"为什么要收集鱼人头颅","击杀证明"}}},fx={["3f14ed35"]={q="一袋鱼人的头颅来自哪里？是谁制作的？",a="这袋东西装着你在希尔斯布莱德丘陵南部海岸猎杀的鱼人的头颅。法尔林·奥里涅尔中尉将它们装在一起，准备呈交给他的长官，不过他很快就把这包令人作呕的东西交还给你，让你代他送去。",al={"谁制作了一袋鱼人的头颅","这袋头颅来自哪里","谁交来一袋鱼人的头颅"}}},fp="20,241,29.437.0,33.196.0,47.175.0,22.139.0,50.252.0"}
P.entries["item:sack-of-supplies"] = {n="装满货物的袋子",s="这些物资袋属于一批原本计划运送给奥格瑞玛城外地精工程师雷兹拉克的货物。这批货物在穿越杜隆塔尔时，被栖息在烈风峡谷峭壁上的尘风鹰身人拦截了。",h="这些物资袋属于一批原本计划运送给奥格瑞玛城外地精工程师雷兹拉克的货物。这批货物在穿越杜隆塔尔时，被栖息在烈风峡谷峭壁上的尘风鹰身人拦截了。",kw={"杜隆塔尔","尘风鹰身人","加兹鲁维","烈风峡谷","雷兹拉克","装满货物的袋子"},ang={["faction:Horde"]="从当地掠食者手中回收遗失的物资，可以确保奥格瑞玛这座新兴首府周边的边疆建设工作不会因昂贵的延误而中断。"},sec={{t="被劫掠的商队",b="雷兹拉克是一位由加兹鲁维从棘齿城雇佣的工程师，他依靠穿越杜隆塔尔的定期商队来运送支援部落建设工程的物资。然而，杜隆塔尔的荒野绝非温顺之地。当一批预定的货物经过奥格瑞玛以南的峡谷道路时，遭到当地尘风鹰身人的伏击和抢掠。这些凶残的生物将货物拖到了烈风峡谷深处的巢穴中，并将物资袋散落在鹰身人筑巢点的泥土和碎石之间。"}},faq={{q="这些物资袋里装着什么？",a="这些袋子里装着代表加兹鲁维工程业务运送的建筑材料和贸易货物，用于支援奥格瑞玛附近的兽人建筑项目。没有它们，雷兹拉克就无法获得完成工作的物资，陷入困境。",al={"物资袋内容物","袋子里装了什么","雷兹拉克的物资"}},{q="谁偷走了这些物资？",a="这些物资是被尘风鹰身人偷走的，这是一种栖息在烈风峡谷高处裂隙和沟壑中的野蛮鸟类种族。",al={"谁拿走了物资","谁偷了袋子"}},{q="雷兹拉克是谁？",a="雷兹拉克是一位地精工程师，由加兹鲁维从棘齿城派遣而来，协助部落在杜隆塔尔进行建设和基础设施铺设。",al={"谁是雷兹拉克","雷兹拉克背景故事"}}},fp="16,158,19.390.0,34.200.0,23.129.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="含盐的蝎毒",s="含盐的蝎毒是一种从徘徊在千针石林闪光平原的蝎虫身上采集而来的腐蚀性液体。由于其中富含来自荒漠地表的天然盐分，它被那些试图研制易挥发、超高温燃料的侏儒火箭赛车手视为珍宝。",h="含盐的蝎毒是一种从徘徊在千针石林闪光平原的蝎虫身上采集而来的腐蚀性液体。由于其中富含来自荒漠地表的天然盐分，它被那些试图研制易挥发、超高温燃料的侏儒火箭赛车手视为珍宝。",kw={"菲兹尔·铜栓","沙漠赛道","含盐的蝎毒","蝎虫掠夺者","蝎虫恐怖者","蝎毒","闪光平原","千针石林"},ang={["profession:Engineering"]="在闪光平原上进行研发的发明家们，眼光从来不局限于传统的石油和煤炭，他们正试图将有机毒素作为易挥发的助燃剂进行测试。",["race:Gnome"]="只有侏儒的奇思妙想才会想到利用致命的沙漠毒液，将其与负催化剂结合，并注入火箭发动机中，仅仅是为了在单圈时间上缩短几秒钟。"},sec={{t="一种易挥发的燃烧剂",b="在闪光平原干旱广袤的土地上爬行的蝎虫，已经适应了矿物质极为丰富的环境。经过数代的繁衍，蝎虫掠夺者和蝎虫恐怖者这类野兽的毒液已经吸收了大量的当地盐分。侏儒技师，例如菲兹尔·铜栓，并不把它们用来调配解毒剂或普通毒药，而是将这种腐蚀性的化合物视为一种极具潜力的、用于高性能发动机燃料的添加剂。"},{t="为赛道竞争注入燃料",b="在沙漠赛道上，侏儒和地精之间的工程学竞争促使发明家们在他们的火箭车中测试越来越危险的材料。菲兹尔·铜栓认为，将含盐的蝎毒煮沸，通过特殊的催化剂进行处理，再混入推进剂罐中，就能产生足够的热量，从而在盐碱地上甩开地精赛车手。"}},faq={{q="什么生物会产出含盐的蝎毒？",a="它采集自徘徊在千针石林盐碱地上的危险蝎虫，尤其是蝎虫掠夺者和蝎虫恐怖者。",al={"谁掉落含盐的蝎毒","在哪里获得蝎毒","蝎毒来源"}},{q="为什么这种毒液这么咸？",a="这些蝎虫完全生活在闪光平原覆盖着矿物质的地表上。它们的生理构造会吸收干涸湖床上高密度的盐分，从而使它们的毒腺中富含独特的盐类浓度。",al={"为什么它是咸的","盐碱地毒液解释","蝎虫与盐的背景故事"}},{q="谁需要这种毒液，为什么？",a="驻扎在沙漠赛道的侏儒工程师菲兹尔·铜栓，正在寻找这种毒液来配制一种实验性的燃料混合物，这种燃料燃烧时产生的热量足以推动他的火箭车赢得胜利。",al={"谁需要蝎毒","菲兹尔为什么想要蝎毒","菲兹尔·铜栓的任务物品"}}},fx={["9840b612"]={q="含盐的蝎毒是什么？",a="这是一种富含矿物质的强效液体，采自出没于闪光平原的蝎子。干旱酷烈的盐碱盆地使当地的蝎子恐魔和掠夺者体内的毒液含盐量异常高。这种毒液作为天然毒素固然致命，但其活跃的化学特性让它对侏儒技师而言更像一种有趣的原始试剂，而非单纯的毒药。",al={"含盐的蝎毒是什么","含盐的蝎毒","平原上的蝎毒"}}},fp="19,253,27.425.0,27.377.0,43.138.0,26.212.0,29.185.0"}
P.entries["item:samophlange-item"] = {n="Samophlange (item)",s="塞莫弗兰奇是一种神秘的机械部件，是从贫瘠之地的自动控制台深处回收而来的。尽管它外表复杂，但即使是那些寻求它的地精机械师，也弄不清它究竟有何用途，这始终是个工程学谜题。",h="塞莫弗兰奇是一种神秘的机械部件，是从贫瘠之地的自动控制台深处回收而来的。尽管它外表复杂，但即使是那些寻求它的地精机械师，也弄不清它究竟有何用途，这始终是个工程学谜题。",kw={"贫瘠之地","控制台","棘齿城","塞莫弗兰奇","斯布特瓦夫","工匠联合会","地下矿道"},ang={["profession:Engineering"]="工程师们会把塞莫弗兰奇视为过度复杂设计的典型例子，其错综复杂的外表下隐藏着一种极其脆弱的机制，一触碰到地面就会散架。"},sec={{t="令人困惑的装置",b="在贫瘠之地的某个控制台内，隐藏在迷宫般多余的线路和空管之后，便是塞莫弗兰奇。要把它从外壳中取出来，需要在一堆故意让人困惑的机器里翻找好一阵子。在未受过训练的人看来，它似乎是发条和蒸汽驱动技术的关键枢纽。但对地精工匠来说，这是一个让人无法抗拒的机械谜题，本来是要运往地下矿道的工匠联合会——尽管由于它结构脆弱，通常在还没被研究透彻之前，就因为随意搬运而损坏了。"},{t="好奇心与灾难",b="当被回收并带给棘齿城的斯布特瓦夫后，这位工程师打算将该部件送走，供联合会的高级智囊进行解剖和研究。然而，地精的好奇心总是会战胜职业谨慎。仅仅是把这个精密的装置放下以检查其内部构造，往往就足以让它破碎成废铁。"}},faq={{q="什么是塞莫弗兰奇？",a="这是一种奇怪的机械部件，是从贫瘠之地的控制台核心中提取出来的。其真正的用途尚不清楚，因为周围的机器里塞满了管道和电线，看起来并没有什么实际用途。",al={"塞莫弗兰奇有什么用","塞莫弗兰奇的用途","这是什么物品"}},{q="谁想要塞莫弗兰奇？",a="驻扎在棘齿城港口的工程师斯布特瓦夫，请求旅行者找回这个部件，以便他研究一番，最终将其送往工匠联合会。",al={"谁需要塞莫弗兰奇","我该把塞莫弗兰奇交给谁"}},{q="斯布特瓦夫怎么处理它？",a="虽然他计划将其送往地下矿道，让工匠联合会的研究人员进行彻底检查，但他自己想先仔细看看。当他把它放在地上准备检查时，这个脆弱的装置立刻就坏了。",al={"斯布特瓦夫 塞莫弗兰奇","塞莫弗兰奇发生了什么"}},{q="塞莫弗兰奇是从哪里来的？",a="它被安置在贫瘠之地北部的一个精细操作控制台内，隐藏在层层混乱且看似无用的工程结构之后。",al={"塞莫弗兰奇位置","在哪里可以找到"}}},fp="18,139,22.396.0,25.268.1,22.204.0,26.124.0,34.155.1,36.131.0"}
P.entries["item:samophlange-manual"] = {n="主动式负载平衡器说明书",s="《主动式负载平衡器说明书》是一本技术操作指南，详细介绍了这种神秘的主动式负载平衡器的内部构造。它被荆棘谷地精严密保管，其散落的页面包含了地精工程师修复和操作这种奇怪装置所需的说明。",h="《主动式负载平衡器说明书》是一本技术操作指南，详细介绍了这种神秘的主动式负载平衡器的内部构造。它被荆棘谷地精严密保管，其散落的页面包含了地精工程师修复和操作这种奇怪装置所需的说明。",kw={"贫瘠之地","boss copperplug","石矿洞","工程学","说明书","rilli greasygob","主动式负载平衡器","斯布特瓦夫","荆棘谷地精"},ang={["faction:Horde"]="找回说明书可以让奥格瑞玛的部落阵营地精在荆棘谷地精的眼皮底下研究并改造其企业钻探机械。",["profession:Engineering"]="这本说明书代表了荆棘谷地精的独家技术，展示了地精技师如何疯狂地保护商业机密和功能蓝图，防止同行窥探。"},sec={{t="装置的秘密",b="工程蓝图和操作手册在地精企业中被视若珍宝，而《主动式负载平衡器说明书》也不例外。在荆棘谷地精工作期间，一位名叫Boss Copperplug的野心勃勃的监工对该装置的相关知识进行了严格保密，只将零散的页面分发给最忠诚的下属，以保持对机器的控制。当该装置落入荆棘谷地精之外的人手中时，如果无法从石矿洞的监工及其部下那里收集到这些被撕碎并散布的文档，修理它就成了不可能完成的任务。"},{t="对手的野心",b="在与荆棘谷地精断绝关系后，地精工程师Rilli Greasygob在奥格瑞玛定居，希望能掌握主动式负载平衡器的制造技术。由于在之前的工作中未曾得到Copperplug的赏识，Rilli只能依靠进取的旅行者来找回说明书的封面和散页。重构这本说明书为与部落合作的地精技师提供了一个难得的机会，让他们得以一窥荆棘谷地精的独家工程技术。"}},faq={{q="什么是主动式负载平衡器说明书？",a="这是一本工程手册，详细介绍了如何操作和修理主动式负载平衡器——这是一种荆棘谷地精在贫瘠之地使用的复杂而奇特的机械装置。",al={"什么是主动式负载平衡器说明书","主动式负载平衡器书籍","主动式负载平衡器指南"}},{q="谁最初拥有这本说明书？",a="它被驻扎在贫瘠之地东北部石矿洞的荆棘谷地精监工Boss Copperplug所私藏。Copperplug对其中的秘密严加防范，只将个别页面分发给最信任的工人。",al={"谁拥有说明书","boss copperplug的说明书","谁编写了说明书"}},{q="为什么说明书被撕成了几页？",a="Boss Copperplug故意将这本书拆开，以防止竞争对手或不受信任的下属了解整个装置的运作原理。他保留了说明书封面，并将五页特定的页面分发给了他的矿工和操作员。",al={"为什么要找说明书页面","散落的说明书页面","为什么缺少页面"}},{q="谁想要阅读完整的说明书？",a="在奥格瑞玛工作的工程师Rilli Greasygob需要重组后的说明书，以了解并修理从贫瘠之地找回的损坏的主动式负载平衡器。",al={"谁需要说明书","rilli greasygob","谁想要主动式负载平衡器说明书"}},{q="主动式负载平衡器有什么用途？",a="荆棘谷地精之外似乎没有人知道。该公司曾在贫瘠之地淤泥沼泽西南的一个小型研究点对其进行实验，即使是研究过它的工程师也对其用途知之甚少。",al={"主动式负载平衡器有什么作用","主动式负载平衡器的目的","主动式负载平衡器用途"}}},fp="18,177,26.365.0,18.352.0,31.117.0,32.197.0,34.201.0,39.147.0,31.252.0"}
P.entries["item:sample-ichor"] = {n="脓液样本",s="这个小瓶里装的是一种精炼提取物，来源于维持银松森林腐皮豺狼人生存的那种污秽液体。这种物质经过药剂师伦弗利尔的提炼，分解出了基本成分，其中残留着死灵法术和术士魔法的痕迹。",h="这个小瓶里装的是一种精炼提取物，来源于维持银松森林腐皮豺狼人生存的那种污秽液体。这种物质经过药剂师伦弗利尔的提炼，分解出了基本成分，其中残留着死灵法术和术士魔法的痕迹。",kw={"药剂师伦弗利尔","比索·埃斯沙德","magic quarter","腐皮豺狼人","腐皮起源","脓液样本","银松森林","幽暗城"},ang={["class:Mage"]="比索·埃斯沙德依靠专门的占卜咒语来读取样本中的残留物，这展示了在面对黑暗巫术时，经典奥术分析的价值。",["class:Warlock"]="药剂师伦弗利尔特别在脓液中检测到了与死灵术交织在一起的术士艺术，暗示邪能实践在束缚这些亡灵野兽的过程中起到了作用。"},sec={{t="解开腐皮之谜",b="徘徊在银松森林的腐皮豺狼人绝非普通的野兽。在收集了这些生物及其残骸的样本后，皇家药剂师协会的药剂师伦弗利尔将这种邪恶的液体分解为其组成元素。他的化学分析显示，这些脓液是通过黑暗流派的融合人工制造出来的：死灵仪式与术士魔法交织在了一起。由于其背后的工艺涉及到了超出普通炼金术范畴的奥术学科，伦弗利尔将这个样本打包并送往幽暗城，以便比索·埃斯沙德通过占卜进行检查。"}},faq={{q="什么是脓液样本？",a="这是由药剂师伦弗利尔从腐皮豺狼人的体液中制备的精炼提取物。伦弗利尔将其分离成基本成分，以分析用于制造这些行尸走肉般野兽的魔法手段。",al={"脓液样本","什么是脓液","什么是脓液样本"}},{q="谁需要查看这个样本？",a="该样本必须交给驻扎在幽暗城Magic Quarter的比索·埃斯沙德，他是一位亡灵法师。比索在占卜和魔法传统方面的专业知识使他能够识别出标准炼金术无法辨别的魔法痕迹。",al={"我该把脓液交给谁","脓液样本交付","比索·埃斯沙德 脓液"}},{q="脓液里含有哪种魔法？",a="伦弗利尔在液体中检测到了术士魔法与死灵魔法的结合。在检查该小瓶时，比索·埃斯沙德指出其中交织着强大的远古附魔，需要更深奥的占卜咒语才能彻底揭开其面纱。",al={"脓液里有什么魔法","脓液魔法类型","腐皮魔法"}},{q="为什么药剂师们不自己完成分析？",a="虽然皇家药剂师协会擅长炼金术、毒素和身体瘟疫，但解读复杂的奥术结构需要专业的术士。比索·埃斯沙德擅长识别魔法流派并解开超出药剂师常规设备处理能力的深奥咒语。",al={"为什么药剂师把它送给比索","为什么不放弃腐皮脓液"}}},fp="12,166,24.406.0,25.214.0,29.213.0,39.198.0,59.243.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="赞吉尔的药剂样品",s="这个瓶子里装着巫医赞吉尔调制的一种强力混合药剂样本，是在贫瘠之地的一次秘密潜入行动中回收的。该样本由一名受到其衰弱影响的特工携带，并被送往海对岸的塔伦米尔，希望能借此研制出解毒剂并揭开制毒术的致命秘密。",h="这个瓶子里装着巫医赞吉尔调制的一种强力混合药剂样本，是在贫瘠之地的一次秘密潜入行动中回收的。该样本由一名受到其衰弱影响的特工携带，并被送往海对岸的塔伦米尔，希望能借此研制出解毒剂并揭开制毒术的致命秘密。",kw={"改良药剂","希尔斯布莱德","毒药","潜行者","瑟尔格·希诺特","淤泥沼泽","塔伦米尔","赞吉尔"},ang={["class:Rogue"]="运送这种危险样本是部落潜行者的成年礼，将直接引导他们学习瑟尔格·希诺特关于调制、处理和施用致命毒药的高级课程。",["faction:Horde"]="运输这种危险的药剂需要跨越大陆的旅程，依靠连接卡利姆多和洛丹伦被遗忘者领地的飞艇塔和既有道路。"},sec={{t="毒素标记",b="在潜入淤泥沼泽附近的荆棘谷地精之塔并从加里维克斯的保险箱里偷走赞吉尔药剂的储备后，一名特工不幸中了赞吉尔邪恶药剂的毒。申苏尔命令这名受感染的特工带着药剂样本横跨无尽之海。想要找到治愈方法，就必须找到驻扎在希尔斯布莱德丘陵塔伦米尔的药剂师瑟尔格·希诺特，他拥有分离毒素并破解其成分所需的罕见专业知识。"},{t="制毒术的秘密",b="这份样本不仅仅关乎医疗紧急情况；对于想要掌握其职业阴暗艺术的部落潜行者来说，它是一份无价的标本。瑟尔格·希诺特分析这种改良药剂不仅仅是为了净化受感染的信使，也是为了演示在外野战时调制和处理强力毒药所需的精确化学工艺。"}},faq={{q="这种药剂是什么？",a="这是与巫医赞吉尔有关的一种炼金药剂的标本，是在前往贫瘠之地淤泥沼泽附近的荆棘谷地精之塔执行任务时回收的。它含有一种强力毒素，会对任何直接接触它的人造成持续的衰弱影响。",al={"赞吉尔的药剂是什么","赞吉尔的改良药剂样本","赞吉尔毒药样本"}},{q="为什么要把它交给瑟尔格·希诺特？",a="瑟尔格·希诺特是驻扎在希尔斯布莱德丘陵塔伦米尔的一名技术精湛的药剂师。他拥有中和药剂效果所需的专业知识，能在毒素造成永久性伤害前配置出可靠的解药。",al={"瑟尔格·希诺特是谁","为什么要带去塔伦米尔","赞吉尔药剂的解药"}},{q="赞吉尔是谁？",a="被放逐者赞吉尔是一位臭名昭著的丛林巨魔巫医，以制造致狂药剂、毒药和诱变剂而闻名。他的剧毒配方已经传播到他原生丛林之外，并流向了像荆棘谷地精这样的雇佣兵和工业组织。",al={"赞吉尔是谁","被放逐者赞吉尔","赞吉尔背景故事"}},{q="如何前往塔伦米尔送达药剂？",a="旅行者必须乘坐从杜隆塔尔到提瑞斯法林地幽暗城的飞艇。从那里出发，沿主路向南穿过银松森林，沿路标向东进入希尔斯布莱德丘陵，直到到达塔伦米尔镇。",al={"如何前往塔伦米尔","前往希尔斯布莱德","塔伦米尔路线指引"}}},fp="34,223,13.424.0,22.208.1,21.227.0,41.188.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="钳嘴龟壳样本",s="钳嘴龟壳样本是从贫瘠之地的淡水绿洲中采集到的一种坚固龟壳。它因残留的生命力而引人注目，被送往无尽之海彼岸，以协助塞纳里奥议会研究如何恢复银松森林那片枯萎的林地。",h="钳嘴龟壳样本是从贫瘠之地的淡水绿洲中采集到的一种坚固龟壳。它因残留的生命力而引人注目，被送往无尽之海彼岸，以协助塞纳里奥议会研究如何恢复银松森林那片枯萎的林地。",kw={"贫瘠之地","穆拉·符文图腾","绿洲","钳嘴龟壳样本","瑟伯切尔","银松森林","钳嘴龟","龟壳"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，研究绿洲钳嘴龟的坚韧生命力，提供了关于生命如何坚持不懈以及受腐蚀的土地如何有朝一日得到治愈的关键课程。",["race:Tauren"]="运送这种甲壳凸显了牛头人对大地母亲的承诺，展示了他们愿意将援助和自然治愈延伸到远在海彼岸的亡灵盟友身上。"},sec={{t="绿洲生命之火花",b="栖息在贫瘠之地郁郁葱葱、带有异常能量的绿洲中的钳嘴龟，其甲壳具有惊人的活力。与普通的甲壳物质不同，新鲜的钳嘴龟壳样本在脱离生物体后，依然能保留微弱的内在光芒和有力的脉动。对于观察这片土地生态剧变的牛头人德鲁伊来说，这些甲壳体现了卡利姆多荒野中坚韧、适应力强的火花，表明大自然即使在严酷干旱的环境中也能蓬勃发展。"},{t="治愈遥远的土地",b="牛头人博物学家认识到这种甲壳中潜藏的生命力，便派遣信使跨越海洋，将样本送到瑟伯切尔的穆拉·符文图腾手中。穆拉驻扎在银松森林那片受腐蚀的广袤土地上，她试图通过寻找治愈这些受折磨的北方土地的方法来帮助被遗忘者。通过检查钳嘴龟甲壳中保存的持久生命力，她希望能够分离出那些可以使衰败的森林重获生机，并促使枯竭的土壤重新长出新芽的秘密。"}},faq={{q="是什么让这个钳嘴龟壳如此特别？",a="与脆弱的普通骨骼不同，这种甲壳保留了内在的光泽，而且在收集之后似乎依然跳动着生命力。它来自在贫瘠之地奇异的淡水绿洲周围繁衍生息的钳嘴龟，那里的自然能量异常充沛。",al={"为什么甲壳很特别","什么是钳嘴龟壳","发光的甲壳"}},{q="谁需要这个样本？",a="这个甲壳是给穆拉·符文图腾的，她是一位居住在银松森林瑟伯切尔的牛头人德鲁伊。她远赴东部王国，协助被遗忘者，并研究如何让垂死的土地恢复生机。",al={"谁想要这个甲壳","我该把甲壳带到哪里","穆拉·符文图腾任务"}},{q="为什么要将贫瘠之地的甲壳远送到银松森林？",a="银松森林是一片正在衰败、遭受腐蚀的林地，而贫瘠之地的绿洲却突然爆发出了顽强且持久的生命力。德鲁伊们认为，研究卡利姆多野兽体内锁定的强大生命力，或许能为治愈洛丹伦那片受腐蚀的土壤提供启示。",al={"为什么要送往银松森林","甲壳与银松森林的联系"}},{q="这甲壳危险或带有腐蚀吗？",a="不。甲壳散发出的是纯净的生命力，而非黑暗魔法。虽然贫瘠之地绿洲中突然出现的过度生长现象十分神秘，但德鲁伊们认为这种残留的能量是一种值得培育的自然韧性。",al={"甲壳邪恶吗","甲壳被腐蚀了吗"}}},fp="20,166,21.357.0,21.351.0,38.200.0,22.151.0,51.211.0,34.176.0"}
P.entries["item:samuel-s-remains"] = {n="塞缪尔的遗骸",s="塞缪尔的遗骸是塞缪尔·菲普斯的残存遗体，他曾是提瑞斯法林地的居民，死于天灾军团之手。这些遗骸由冒险者在丧钟镇附近寻回，并被安葬在他妻子玛拉的墓旁，以实现她临终前的夙愿。",h="塞缪尔的遗骸是塞缪尔·菲普斯的残存遗体，他曾是提瑞斯法林地的居民，死于天灾军团之手。这些遗骸由冒险者在丧钟镇附近寻回，并被安葬在他妻子玛拉的墓旁，以实现她临终前的夙愿。",kw={"丧钟镇","玛拉·菲普斯","玛拉的墓地","玛拉的遗愿","新兵艾尔雷斯","塞缪尔·菲普斯","塞缪尔的遗骸"},ang={["race:Undead"]="安葬塞缪尔的遗骸是了解被遗忘者身份的早期课题：尊重这些悲剧性的逝者，标志着自由亡灵与天灾军团盲目奴仆之间关键的道德分界线。"},sec={{t="悲剧的重逢",b="在亡灵瘟疫席卷洛丹伦之前，塞缪尔·菲普斯与他的妻子玛拉过着平静的生活。当瘟疫降临时，塞缪尔不幸罹难，并被迫沦为天灾军团中毫无思想的奴仆。玛拉虽然逃过了亡灵的命运，却最终死于她深爱的丈夫之手。尽管结局如此惨烈，她临终前的愿望并非复仇，而是死后能长相厮守：她恳求在塞缪尔那被诅咒的躯体得到安息后，将自己葬在塞缪尔身旁。丧钟镇的新兵艾尔雷斯招募了新觉醒的被遗忘者，去追踪游荡在定居点东北方向的塞缪尔，取回他的骸骨，并将其安葬在当地墓地的第一排。"}},faq={{q="谁是塞缪尔·菲普斯？",a="塞缪尔·菲普斯是第三次战争前居住在提瑞斯法林地的一名人类。当天灾瘟疫入侵时，他不幸身亡，并作为巫妖王麾下的一名亡灵奴仆复生。在毫无思想的饥饿感驱使下，他最终杀害了自己的妻子玛拉。",al={"塞缪尔·菲普斯","塞缪尔是谁","塞缪尔背景故事"}},{q="在哪里可以找到塞缪尔的遗骸？",a="它们是从塞缪尔·菲普斯本人身上找回的，他游荡在丧钟镇东北方向道路沿线的废弃营地中。终结他毫无思想的生存状态，即可取回他的遗骸。",al={"寻找塞缪尔的遗骸","塞缪尔·菲普斯在哪里","塞缪尔位置"}},{q="为什么被遗忘者会将他安葬在妻子的身旁？",a="玛拉临终前的愿望是能与她深爱的丈夫葬在一起，尽管正是他杀害了她。新兵艾尔雷斯尊重了这一请求，以证明刚刚获得自由的被遗忘者依然拥有同情心、对逝者的尊重，以及将他们与天灾军团区分开来的人性。",al={"为什么要安葬塞缪尔","玛拉的墓地","玛拉的遗愿"}}},fp="16,91,16.533.0,21.223.0,33.186.0,45.260.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="阿库麦尔蓝宝石",s="阿库麦尔蓝宝石是生长在黑暗深渊地下隧道沿壁的、散发着微光且充满了水元素力量的矿簇。不断入侵的纳迦已经开始采集这些宝石，这促使大地之环必须在它们强大的奥术力量被利用之前将其收回。",h="阿库麦尔蓝宝石是生长在黑暗深渊地下隧道沿壁的、散发着微光且充满了水元素力量的矿簇。不断入侵的纳迦已经开始采集这些宝石，这促使大地之环必须在它们强大的奥术力量被利用之前将其收回。",kw={"阿库麦尔","黑暗深渊","水晶","耶努萨克雷","纳迦","蓝宝石","水之灵","佐拉姆海岸"},ang={["class:Mage"]="其天然的水元素饱和度使得这些原始蓝宝石作为强大的奥术组件导管而备受珍视。",["class:Shaman"]="像耶努萨克雷这样的大地之环萨满祭司可以轻易察觉到禁锢在这些宝石中的水之灵，并将纳迦的采集行为视为一种元素威胁。"},sec={{t="深渊之宝",b="阿库麦尔蓝宝石是在灰谷佐拉姆海岸的黑暗深渊水下洞穴入口处发现的，它们是富含元素能量的结晶体。水之灵紧紧附着在上面，使它们成为了极佳的魔法催化剂。当斥候报告说地下的纳迦已经开始大肆从洞穴墙壁上开采这些矿簇时，萨满祭司耶努萨克雷寻求冒险者的协助以将其没收。如果任由这些宝石留在蛇人手中，它们很可能会被用于助长毁灭性的奥术仪式。"}},faq={{q="什么是阿库麦尔蓝宝石？",a="它们是镶嵌在黑暗深渊洞壁上的鲜艳蓝宝石晶体。由于与水元素之灵紧密相连，它们蕴含着深厚的奥术与元素共鸣。",al={"这是什么水晶","阿库麦尔蓝宝石背景故事","这些宝石是什么"}},{q="纳迦为什么要收集这些蓝宝石？",a="虽然它们的确切意图尚不明确，但耶努萨克雷怀疑纳迦打算利用这些水晶中富含的水元素和奥术能量，在淹没的神庙中进行危险的巫术活动。",al={"纳迦为什么想要蓝宝石","纳迦采集水晶"}},{q="谁在寻找这些蓝宝石？",a="驻扎在灰谷佐拉姆海岸佐拉姆加前哨站的大地之环萨满祭司耶努萨克雷，委托旅行者收集这些宝石，以免它们落入纳迦之手。",al={"谁想要阿库麦尔蓝宝石","谁负责回收阿库麦尔精华"}},{q="这些晶体与野兽阿库麦尔有直接联系吗？",a="尽管是以栖息在深渊中的多头蛇怪阿库麦尔命名的，但这些晶体是在洞穴墙壁上自然生长的。它们的命名仅仅是因为它们靠近潜伏在遗迹深处的黑暗存在。",al={"与阿库麦尔的联系","它是来自阿库麦尔吗"}}},fx={["12f03799"]={q="阿库麦尔蓝宝石来自哪里？是谁制作的？",a="这些大型蓝宝石簇天然生长在黑暗深渊初始洞穴的岩壁上。它们并非由凡人雕琢，而是在洞窟环境能量浸润下形成的天然矿物。水之精魂会自然依附于这些水晶，赋予它们与生俱来的元素力量。",al={"阿库麦尔蓝宝石的来源","谁制作了阿库麦尔蓝宝石","阿库麦尔蓝宝石来自哪里"}}},fp="19,211,16.443.0,30.162.0,44.182.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="天蓝宝石",s="天蓝宝石是暗夜精灵保存在班奈希尔兽穴中的四件神圣唤醒圣物之一。它是将沉睡的猛禽德鲁伊从翡翠梦境中安全唤醒所必需的焦点。",h="天蓝宝石是暗夜精灵保存在班奈希尔兽穴中的四件神圣唤醒圣物之一。它是将沉睡的猛禽德鲁伊从翡翠梦境中安全唤醒所必需的焦点。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","天空之箱","猛禽德鲁伊","翡翠梦境","唤醒圣物","天蓝宝石"},ang={["class:Druid"]="这颗蓝宝石体现了在将灵魂投射到翡翠梦境时所需的谨慎仪式，证明了如果没有神圣的锚点，交流是多么容易变得致命。",["race:NightElf"]="保护班奈希尔兽穴中的神圣圣物对于在日益严重的腐蚀中维护泰达希尔脆弱的秩序至关重要。"},sec={{t="唤醒仪式",b="在泰达希尔的树根深处，猛禽德鲁伊在班奈希尔兽穴中通过冬眠与荒野进行交流。从这种深度的恍惚状态回归清醒世界是一个脆弱且危险的过程。为了保障这一过渡，德鲁伊们依靠四件被称为唤醒圣物的圣物：黑色羽毛、鸦爪神符、筑巢符文和天蓝宝石。如果没有这颗产生共鸣的宝石，将沉睡的灵魂从翡翠梦境中唤回所需的和谐就会不完整，使他们面临被永久困住的危险。"},{t="班奈希尔的威胁",b="当受到腐蚀的木喉部族熊怪占领兽穴时，这些神圣的圣物被遗留在了装饰华丽的存放处。天蓝宝石被保存在蜿蜒地下通道中的天空之箱内。由于德鲁伊们仍在沉睡，而熊怪在他们周围横行霸道，对于多兰纳尔的阿斯瑞达斯·熊皮来说，在沉睡者永远迷失之前，取回这颗宝石及其同伴圣物是一件紧急的事情。"}},faq={{q="什么是天蓝宝石？",a="它是一颗神圣的宝石，是存放在班奈希尔兽穴中的四件唤醒圣物之一。它与三件鸟类护符协同工作，以安全地引导猛禽德鲁伊离开翡翠梦境。",al={"天蓝宝石传说","这颗宝石是什么","天空蓝宝石"}},{q="天蓝宝石存放在哪里？",a="它被保存在天空之箱内，位于泰达希尔中部班奈希尔兽穴的地下迷宫中。",al={"在哪里找到天蓝宝石","天空之箱位置","蓝宝石位置"}},{q="为什么现在需要这颗蓝宝石？",a="受到腐蚀的木喉部族熊怪入侵了班奈希尔兽穴，使沉睡的德鲁伊们陷入了极大的危险之中。深陷恍惚状态的德鲁伊无法自行醒来；阿斯瑞达斯·熊皮需要这颗蓝宝石和其他圣物来进行精细的唤醒仪式，以免这些沉睡者永远迷失。",al={"为什么要获取蓝宝石","唤醒圣物的用途"}},{q="谁在使用这件神器？",a="猛禽德鲁伊和像阿斯瑞达斯·熊皮这样的仪式守护者在集体仪式中使用它，以唤醒沉睡的兄弟们，使他们结束与自然的深度交流。",al={"谁在使用天蓝宝石","德鲁伊仪式宝石"}}},fp="15,178,19.459.0,23.400.0,28.199.0,34.132.0,37.298.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="萨拉·巴鲁的请求",s="《萨拉·巴鲁的请求》是一封由铁炉堡的一位悲痛的遗孀亲笔写下的书信。由于她在悲伤中无法直接面对君主，她将这封信托付给了一位值得信赖的联盟勇士，将其呈交给国王麦格尼·铜须。",h="《萨拉·巴鲁的请求》是一封由铁炉堡的一位悲痛的遗孀亲笔写下的书信。由于她在悲伤中无法直接面对君主，她将这封信托付给了一位值得信赖的联盟勇士，将其呈交给国王麦格尼·铜须。",kw={"国王的致敬","high seat","铁炉堡","magni bronzebeard","萨拉·巴鲁","萨拉·巴鲁的请求"},ang={["faction:Alliance"]="萨拉只将她的请愿托付给因效力于联盟而受到认可的勇士，相信他们的声望能使她的恳求获得王室的接见。",["race:Dwarf"]="对于矮人来说，将萨拉的信息带到High Seat是一种深厚的亲情表现，确保即使在悲痛之中，也没有任何山民或公民会被国王麦格尼所忽视。"},sec={{t="遗孀的恳求",b="《萨拉·巴鲁的请求》写于个人悲剧的阴影之下，代表了对铁炉堡王座的一项卑微恳求。萨拉因悲痛欲绝而无法亲自前往High Seat，因此她寻求一位向联盟展示了忠诚与英勇的冒险者来传达她的话语。这封信旨在请求国王麦格尼·铜须的关注，使这位君主注意到效力于王国的普通矮人家庭所遭受的私下哀悼与牺牲。"}},faq={{q="什么是《萨拉·巴鲁的请求》？",a="这是一封由萨拉·巴鲁亲笔写给国王麦格尼·铜须的信，请求他在她私下哀悼时予以关注。",al={"萨拉·巴鲁的请求","铁炉堡遗孀信件","萨拉的信"}},{q="为什么萨拉·巴鲁需要其他人来递交这封信？",a="萨拉感到悲痛欲绝，她认为在这种情绪状态下出现在铁炉堡国王面前会影响她的请求，因此她转而依靠一位联盟勇士。",al={"为什么要递送信件","为什么萨拉不能亲自去","萨拉的悲痛"}},{q="谁会收到这封信？",a="这封信是直接写给并在铁炉堡的High Seat呈交给国王麦格尼·铜须的。",al={"谁会收到请求","递交给谁","麦格尼的信"}},{q="递交这封信会带来什么结果？",a="将信呈交给国王麦格尼会引起他对萨拉·巴鲁丧亲之痛的关注，并促成一项纪念她阵亡家人的王室回应。",al={"请求任务线","国王的致敬链接","接下来会发生什么"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="萨瑞鲁斯·法伯尼的头颅",s="萨瑞鲁斯·法伯尼的头颅是一个可怕的战利品，是从一位亵渎了卡利姆多北部水域的亡灵术士身上获取的。这个头颅被从贫瘠之地带回灰谷边境，证明了那个爱管闲事的法师确实已经死在了哨兵的手中。",h="萨瑞鲁斯·法伯尼的头颅是一个可怕的战利品，是从一位亵渎了卡利姆多北部水域的亡灵术士身上获取的。这个头颅被从贫瘠之地带回灰谷边境，证明了那个爱管闲事的法师确实已经死在了哨兵的手中。",kw={"贫瘠之地","鬼雾峰","头颅","法师召唤者","萨瑞鲁斯·法伯尼","银风避难所","维尔莉妮·星坠","水元素"},ang={["faction:Alliance"]="执行这次打击需要深入贫瘠之地内敌对的部落领土，消灭一个危险的流氓施法者。",["race:NightElf"]="取下法伯尼的头颅满足了哨兵们对这位亵渎了大地之灵、鲁莽的奥术亵渎者的复仇。"},sec={{t="亵渎者的末日",b="亡灵施法者萨瑞鲁斯·法伯尼盘踞在贫瘠之地北部的鬼雾峰之巅，通过腐蚀并奴役大群水元素，引来了暗夜精灵的愤怒。在银风避难所的哨兵维尔莉妮·星坠察觉到他卑劣的行径后，派出了勇士跨越边境深入部落领地，以终结他那鲁莽的实验。砍下这位法师的头颅是星坠唯一认可的证据，用以确认他那嘲弄的笑容已被永远抹去，从而为动荡的灰谷水域争取到了一丝安宁。"}},faq={{q="萨瑞鲁斯·法伯尼是谁？",a="萨瑞鲁斯·法伯尼是一名亡灵法师，他在贫瘠之地北部的鬼雾峰建立了据点。他通过扭曲并召唤大量水元素引起了暗夜精灵的愤怒，这促使哨兵维尔莉妮·星坠下令将其处死。",al={"萨瑞鲁斯是谁","萨瑞鲁斯·法伯尼背景故事","法伯尼是谁"}},{q="哨兵维尔莉妮·星坠为什么要他的头颅？",a="维尔莉妮·星坠需要绝对的确定性，确认这位傲慢的术士已经死亡。萨瑞鲁斯在亵渎该地区水之灵的同时，还公开嘲讽过她。带回他被砍下的头颅是她唯一愿意接受的证据，以证明这一威胁已被消除。",al={"为什么要拿他的头","维尔莉妮·星坠 头颅","死亡证明"}},{q="萨瑞鲁斯·法伯尼在哪里？",a="他盘踞在鬼雾峰的最高处，那是一座位于贫瘠之地北部边缘的崎岖山峰，就在灰谷边界的南面。",al={"在哪能找到法伯尼","萨瑞鲁斯位置","鬼雾峰法师"}},{q="法伯尼为什么要亵渎水元素？",a="法伯尼利用奥术召唤将大量水元素纳入麾下，并在过程中腐蚀了它们。他这种鲁莽的操控干扰了流经灰谷附近的自然平衡，从而引来了哨兵们迅速的报复。",al={"为什么要腐蚀元素","水元素腐蚀","法伯尼动机"}}},fx={a996e76e={q="萨瑞鲁斯·法伯尼的头颅来自哪里？",a="这个被砍下的头颅来自萨瑞鲁斯·法伯尼。他是一名被遗忘者法师，在贫瘠之地北部的鬼雾峰盘踞。法伯尼在灰谷边境附近行动，亵渎水元素、不断挑衅暗夜精灵。最终，哨兵维尔莉妮·星坠派遣一位冒险者深入敌境，终结了他的嘲弄行径。",al={"萨瑞鲁斯头颅的来源","法伯尼的头颅来自哪里"}}},fp="24,193,18.481.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="萨科斯的爪子",s="萨科斯的爪子是萨科斯的断肢。萨科斯是一只在试炼谷南面峭壁徘徊的巨大蝎虫。这件战利品曾被受了重伤的巨魔哈纳祖重创，它既是野兽被击杀的证明，也是受伤猎人挽回最后尊严的慰藉。",h="萨科斯的爪子是萨科斯的断肢。萨科斯是一只在试炼谷南面峭壁徘徊的巨大蝎虫。这件战利品曾被受了重伤的巨魔哈纳祖重创，它既是野兽被击杀的证明，也是受伤猎人挽回最后尊严的慰藉。",kw={"爪子","杜隆塔尔","哈纳祖","残破的爪子","萨科斯","蝎虫","试炼谷"},ang={["faction:Horde"]="对于试炼谷的新手来说，获得这件战利品标志着他们在杜隆塔尔严酷荒野中所要经历的最早的勇气与武力测试之一。",["race:Troll"]="将这只残破的爪子带给哈纳祖，能让这位垂死的暗矛族人得到一丝尊严，让他知道在生命终结之前，他最后的那一击在野兽身上留下了伤疤。"},sec={{t="复仇的战利品",b="在试炼谷狩猎时，一位名叫哈纳祖的暗矛巨魔青年与一只名为萨科斯的巨大蝎虫展开了搏斗。在萨科斯的毒刺刺穿他的胸膛并将他遗弃在附近的一棵树下苟延残喘之前，哈纳祖对这只生物的巨大螯钳发动了致命一击。砍下这条残破的肢体是这只怪物蝎虫已被击杀的铁证。对于哈纳祖来说，握住这只受损的爪子证实了他那孤注一掷的打击留下了不可磨灭的印记，这让他体内流淌着毒液的同时，还能燃起一丝转瞬即逝的战士荣耀。"}},faq={{q="为什么爪子是残破的？",a="这只爪子是在萨科斯和巨魔猎人哈纳祖之间的一场殊死决斗中被摧毁的。尽管萨科斯用毒刺刺穿了哈纳祖的胸膛使其受到致命伤，但巨魔在蝎虫夹住他的腿之前，对野兽的螯钳发动了狂暴的一击。",al={"为什么爪子断了","谁打碎了萨科斯的爪子","萨科斯的爪子背景故事"}},{q="谁想要萨科斯的爪子？",a="哈纳祖想要这只爪子。他受了重伤，躺在试炼谷的一棵树下，害怕自己会死在那里。他希望这只蝎虫被杀，以此维护自己的荣誉。看到任务完成，能让他更有毅力坚持下去，直到高内克派人救援。",al={"谁需要萨科斯的爪子","交给谁","哈纳祖的爪子"}},{q="这只爪子是从哪里来的？",a="它取自萨科斯，这是一只体型庞大且极具攻击性的蝎虫，在杜隆塔尔试炼谷南部的悬崖高地上徘徊。",al={"萨科斯位置","萨科斯在哪里","哪里获得残破的爪子"}}},fp="22,207,21.473.0,24.194.0,33.222.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="萨尔图斯的爪子",s="萨尔图斯的爪子是从潜伏在湿地维尔加挖掘场上方的那头迅猛龙首领身上割下的一只断爪。它向矮人奥莫尔·铁衣提供了确凿的证据，证明那头造成考古发掘工作被摧毁的凶猛野兽已被击杀。",h="萨尔图斯的爪子是从潜伏在湿地维尔加挖掘场上方的那头迅猛龙首领身上割下的一只断爪。它向矮人奥莫尔·铁衣提供了确凿的证据，证明那头造成考古发掘工作被摧毁的凶猛野兽已被击杀。",kw={"挖掘","奥莫尔·铁衣","迅猛龙","萨尔图斯","爪子","湿地","维尔加"},ang={["class:Hunter"]="追踪像萨尔图斯这样狡猾的兽群首领并取得一只爪子作为战利品，是对射击技巧和野兽控制能力的经典考验。",["race:Dwarf"]="取回这只爪子，为那些在国王麦格尼·铜须的授意下，为探险者协会效力而丧生的矮人考古学家们带来了迟来的复仇。"},sec={{t="复仇的奖赏",b="当迅猛龙群 overrun 维尔加挖掘场并屠杀了矮人探险队时，奥莫尔·铁衣只能在上面的山脊上眼睁睁地看着这一切，无力阻止这场大屠杀。他认定其中一头巨大而凶猛的迅猛龙——萨尔图斯——就是这场袭击背后的头目。为了替倒下的同胞寻求报复，奥莫尔要求处死这头野兽，并索要它的一只利爪作为证明。割下这只爪子，标志着萨尔图斯对这座古代矮人遗迹的恐怖统治宣告终结。"}},faq={{q="萨尔图斯的爪子从何而来？",a="这只爪子取自萨尔图斯，这是一头大型迅猛龙首领，在湿地俯瞰维尔加挖掘场的西部山脊上徘徊。",al={"谁掉落萨尔图斯的爪子","萨尔图斯位置","如何获得爪子"}},{q="谁想要萨尔图斯的爪子？",a="奥莫尔·铁衣，一名驻扎在维尔加挖掘场上方眺望台的矮人，他索要这只爪子是为了确认那头屠杀了他的队员的野兽已经被处决。",al={"谁接收爪子","在哪里上交爪子","奥莫尔·铁衣任务"}},{q="为什么奥莫尔·铁衣需要萨尔图斯死亡的证据？",a="奥莫尔认为萨尔图斯领导了那群驱逐并杀害了矮人挖掘工的迅猛龙。他将这只爪子视为替倒下的同事伸张正义和寻求了结的象征。",al={"为什么要杀萨尔图斯","萨尔图斯做了什么"}},{q="挖掘场的矮人们发生了什么事？",a="这次矮人挖掘工作本是为了探险者协会发掘古代文物，但野生迅猛龙伏击了工人们，屠杀了其中大部分人，并将幸存者赶到了附近的山脊上。",al={"维尔加挖掘场背景故事","为什么挖掘场有迅猛龙"}}},fx={["28fc0e8a"]={q="什么是萨尔图斯的爪子？",a="这是从萨尔图斯身上取下的一只断爪。萨尔图斯是一只凶暴的迅猛龙，据信它率领着那群袭击维尔加挖掘场的野兽。奥莫尔·铁衣要这只爪子作为确凿证据，证明野兽已被杀死，也证明那些阵亡的矮人挖掘者已经得以报仇。",al={"什么是萨尔图斯的爪子","萨尔图斯的爪子背景"}}},fp="17,159,21.404.0,39.137.0,28.179.0,57.162.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="萨丝拉的祭品",s="萨丝拉的祭品是由取自泰达希尔巨型蜘蛛萨丝拉夫人的银色丝囊制成的。在女祭司艾茉拉的委托下，冒险者会将此祭品献于Temple of the Moon的喷泉，以净化这只生物身上的腐化并安抚其灵魂。",h="萨丝拉的祭品是由取自泰达希尔巨型蜘蛛萨丝拉夫人的银色丝囊制成的。在女祭司艾茉拉的委托下，冒险者会将此祭品献于Temple of the Moon的喷泉，以净化这只生物身上的腐化并安抚其灵魂。",kw={"达纳苏斯","艾露恩","萨丝拉夫人","女祭司艾茉拉","萨丝拉的祭品","银色丝囊","蜘蛛","泰达希尔","temple of the moon"},ang={["class:Priest"]="服务于The Sisterhood of Elune的祭司们将此仪式视为一种庄严的神圣怜悯行为，利用圣水来净化污秽，而不是仅仅处理掉一只被杀死的野兽。",["race:NightElf"]="对于暗夜精灵来说，杀死受腐化的野生生物是一项沉重的职责；将萨丝拉夫人的灵魂归还给艾露恩的恩典，确保了泰达希尔上的生命最终能够摆脱疯狂而重生。"},sec={{t="圣水净化",b="萨丝拉夫人曾是泰达希尔受人尊敬的生物，后来却沦为了蔓延在这棵巨树枝干上的疯狂与腐化的牺牲品。在The Sisterhood of Elune的授意下，冒险者们取回她的银色丝囊并非仅仅是为了战利品，而是作为一种神圣的供品。通过将这些残骸浸入Temple of the Moon的圣泉中，毒害萨丝拉心智的邪恶污秽得以被洗净。这一仪式解脱了她饱受折磨的灵魂，使她的精魂能够平静地在圣所中显现，并让她获得了在艾露恩的恩典下重生的承诺。"}},faq={{q="什么是萨丝拉的祭品？",a="萨丝拉的祭品是一种仪式用品，取材于在泰达希尔被击杀的受腐化巨型蜘蛛萨丝拉夫人的银色丝囊。The Sisterhood of Elune利用它进行净化仪式，以涤荡该生物的灵魂。",al={"什么是丝囊","萨丝拉的祭品物品","萨丝拉夫人供品"}},{q="为什么必须将丝囊放入喷泉中？",a="达纳苏斯Temple of the Moon中央的喷泉中蕴含着献给艾露恩的圣水。将萨丝拉的残骸浸入池中可以洗去导致她疯狂的邪恶腐化，从而将她的灵魂从痛苦中解脱出来。",al={"为什么要用神殿喷泉","为什么要献祭萨丝拉","喷泉的作用"}},{q="献上祭品后会发生什么？",a="当放入圣水中时，腐化会被清除，萨丝拉夫人的幽灵形态会出现，并平静地绕着水池漫步，象征着她的灵魂已获得安宁。",al={"喷泉处会发生什么","萨丝拉的灵魂显现","喷泉事件"}},{q="谁负责监督这一仪式？",a="女祭司艾茉拉，The Sisterhood of Elune的一名仆从，驻守在Temple of the Moon，她指示冒险者去安息这只生物并将其残骸献给女神。",al={"谁给予萨丝拉的祭品任务","女祭司艾茉拉任务","谁净化了萨丝拉"}}},fp="19,171,31.538.0,28.187.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="萨特的角",s="萨特的角是人们从危害灰谷古老森林的堕落萨特身上收割的冷酷战利品。这些角既受到寻求报复的哀伤森林居民的垂涎，也受到以棘齿城为基地的投机商人的青睐，它们是燃烧军团的又一名仆从已倒下的有力证据。",h="萨特的角是人们从危害灰谷古老森林的堕落萨特身上收割的冷酷战利品。这些角既受到寻求报复的哀伤森林居民的垂涎，也受到以棘齿城为基地的投机商人的青睐，它们是燃烧军团的又一名仆从已倒下的有力证据。",kw={"安妮莉亚","林歌神殿","伊莉亚娜","夜道谷","皮克希尔","萨特的角","萨提纳尔","碎木岗哨","萨维亚"},ang={["faction:Horde"]="部落战士以碎木岗哨为基地，在清除威胁其伐木作业的邪恶萨特的同时，还能从前往棘齿城的地精买家那里获利。",["race:NightElf"]="对于卡多雷来说，取下萨特的角是一项痛苦的职责，这清理了他们祖传森林中那些自愿用遗产交换恶魔奴役的同胞。"},sec={{t="复仇与贸易的战利品",b="灰谷萨特弯曲的角是恶魔腐化在这片圣林中扎根的鲜明象征。对于艾森娜神殿的树妖伊莉亚娜来说，收集这些被砍下的角，是为了她逝去的姐妹安妮莉亚而感到的悲伤与复仇。然而，对于像在碎木岗哨歇脚的旅行地精皮克希尔这样的外来商人来说，这些角则代表着纯粹的商机。中立港口棘齿城对萨特的角的需求激增，使这些被杀恶魔的恐怖残骸变成了任何敢于狩猎其携带者的人的暴利商品。"},{t="清除腐化据点",b="萨特的角无法从普通供货商处买到，它们必须直接从潜伏在林地阴暗角落的野兽身上割下来。萨特在灰谷各地都设有据点，最臭名昭著的要数萨维亚的腐化树林、萨提纳尔的阴影深谷以及夜道谷的废墟。清除这些据点可以消除大地上残留的恶魔污染，同时确保存有哀伤的守护者和急切的商人所需的屠杀证明。"}},faq={{q="伊莉亚娜为什么要萨特的角？",a="伊莉亚娜寻求萨特的角是为了替她惨遭灰谷萨特杀害的姐妹安妮莉亚复仇。从被杀的恶魔身上取下这些角，能为她提供对方数量正在减少的证明，并告慰她姐妹的亡魂。",al={"伊莉亚娜的角","安妮莉亚与萨特","林歌神殿任务"}},{q="皮克希尔为什么要收集萨特的角？",a="皮克希尔是一位在前往棘齿城途中寄宿于碎木岗哨的进取旅行者。她得知萨特的角在那个地精港口能卖出高价，因此在出发前雇佣冒险者代她进行危险的狩猎。",al={"皮克希尔与碎木岗哨","皮克希尔为什么需要角","棘齿城的萨特之角"}},{q="在哪里最容易找到带有这种角的萨特？",a="萨特居住在灰谷各处的几个被腐化的区域。主要的聚集地位于东北部的萨维亚和萨提纳尔，以及森林中东部的夜道谷。",al={"灰谷的萨特位置","萨特在哪里","萨特营地"}},{q="萨特是什么，为什么它们会有角？",a="萨特是古代暗夜精灵，在上古之战期间通过签订恶魔契约而转变成了野兽般的恶魔生物。它们山羊般的蹄子、尾巴和邪恶的角，正是燃烧军团赋予其恶魔腐化的身体标志。",al={"什么是萨特","萨特为什么有角"}}},fx={["2131c67f"]={q="什么是萨特的角？",a="萨特的角是从灰谷潜伏的萨特头上砍下来的弯曲邪恶之角。作为古代暗夜精灵遭受恶魔腐化后的产物，萨特长着这些骇人的畸角，象征着他们所受的诅咒。对于冒险者来说，这些角主要是萨特覆灭的冷酷证明，或是在卡利姆多各地交易的珍贵异域奇物。",al={"什么是萨特的角","萨特之角物品","萨特的角是什么"}},["8a39621c"]={q="为什么有人想要萨特的角？",a="不同阵营想要萨特之角的原因各不相同。对于林歌神殿的树妖伊莉亚娜来说，这些角是她向杀害妹妹安妮莉亚的腐化恶魔复仇的确凿凭证。与此同时，像皮克希尔这样的投机商人会收集它们，在繁忙的棘齿城出售；那里对异域炼金材料、奇珍和野兽部件的需求一直很旺盛。",al={"谁想要萨特的角","为什么收集萨特的角","为什么需要萨特的角"}}},fp="11,168,34.354.0,30.366.0,35.186.0,36.231.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="草原狮的獠牙",s="草原狮的獠牙是取自游荡在贫瘠之地干旱平原上的掠食性大型猫科动物的沉重尖牙。虽然这对于旅行者来说是常见的狩猎战利品，但它们却有着一种异域用途：作为酿酒大师陈·风暴烈酒那传说中烈性麦芽酒的酿造配料。",h="草原狮的獠牙是取自游荡在贫瘠之地干旱平原上的掠食性大型猫科动物的沉重尖牙。虽然这对于旅行者来说是常见的狩猎战利品，但它们却有着一种异域用途：作为酿酒大师陈·风暴烈酒那传说中烈性麦芽酒的酿造配料。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","迪舒","修玛","棘齿城","草原狮的獠牙"},ang={["class:Hunter"]="在贫瘠之地的金色灌木丛中猎杀凶猛的狮群，是对于追踪技巧的真正考验，能够获得既在战斗中致命、又对当地酿酒师极具价值的危险尖牙。"},sec={{t="一种奇特的酿酒配料",b="贫瘠之地的大型猫科动物——从徘徊者和女猎手，到由族长统治的雄伟狮群，以及像修玛这样的野兽——都长有锋利且厚重的獠牙。虽然大多数击倒这些掠食者的人只把它们的牙齿当作炫耀勇武的简单证明，但棘齿城的酿酒师德罗恩却为了某种更具灵气的工艺而寻找它们。德罗恩将这些獠牙与平原陆行鸟的肾脏以及雷蜥蜴的角一起使用，以此重现陈·风暴烈酒那著名的同名佳酿，这种酒有着一种极其强烈的后劲，很少有凡人的喉咙能轻易承受。"}},faq={{q="为什么酿酒师德罗恩需要草原狮的獠牙？",a="位于棘齿城的酿酒师德罗恩正在重现陈·风暴烈酒的同名佳酿配方，该配方是通过他的导师传授给他的。这些獠牙是重现这种烈性酒独特风味和后劲所需的三种贫瘠之地本土试剂之一。",al={"为什么啤酒需要獠牙","德罗恩狮獠牙","酿酒师德罗恩配方"}},{q="哪些野兽身上带有草原狮的獠牙？",a="它们可以从任何在贫瘠之地游荡的草原狮狮群成员身上割下，包括草原高鬃狮、族长、族母、女猎手、徘徊者，以及像迪舒和修玛这样的稀有野兽。",al={"狮獠牙哪里掉落","谁掉落狮獠牙","草原狮的獠牙来源"}},{q="狮子真的有獠牙吗？",a="在卡利姆多那崎岖的荒野中，草原大型猫科动物过大的犬齿长得非常突出且厚实，以至于当地的猎人和边疆开拓者俗称其为“獠牙”。",al={"为什么狮子牙齿被称为獠牙","狮獠牙与犬齿的区别","狮獠牙解剖学"}}},fp="18,118,28.438.0,51.239.0,39.194.0,29.151.0"}
P.entries["item:scaber-stalk"] = {n="粗柄蘑菇",s="粗柄蘑菇是一种罕见的蘑菇，在黑海岸峭壁之泉后方隐秘且潮湿的洞穴中生长。它们因其独特的属性而受到草药师和炼金术师的珍视，巴瑞萨斯·月影也在寻找这种蘑菇来制作他的药剂。",h="粗柄蘑菇是一种罕见的蘑菇，在黑海岸峭壁之泉后方隐秘且潮湿的洞穴中生长。它们因其独特的属性而受到草药师和炼金术师的珍视，巴瑞萨斯·月影也在寻找这种蘑菇来制作他的药剂。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","粗柄蘑菇"},ang={["profession:Herbalism"]="虽然不是标准的贸易草药，但这些地下生长的蘑菇为了解独特的洞穴气候和侵蚀阴影如何改变当地真菌生物学提供了宝贵的见解。",["race:NightElf"]="谨遵古树之林的警告，暗夜精灵在采集这些洞穴蘑菇时极为谨慎，因为峭壁之泉附近存在着腐化的气息。"},sec={{t="一种罕见的真菌标本",b="粗柄蘑菇是深藏在黑海岸东北部群山中，位于峭壁之泉后方洞穴深处的稀有蘑菇。与普通的森林植物不同，这些苍白的柄状真菌严格生长在幽闭且潮湿的地下洞穴网络中。它们那遥远且危险的栖息地使得采集工作极为罕见，这导致像奥伯丁的巴瑞萨斯·月影这样的炼金术师不得不招募那些敢于深入黑暗的勇士。"},{t="瀑布中的阴影",b="采集粗柄蘑菇远比普通的采集工作更危险。古树之林的古老树灵曾向当地的暗夜精灵发出警告，因为它们感应到一股邪恶的力量正在峭壁之泉的洞穴中滋生。虽然炼金术师将这种蘑菇与罕见的毒帽蘑菇一同视为实验药水的珍贵材料，但采集它们不可避免地会使采集者面对潜伏在山脉之下的某种恶意。"}},faq={{q="粗柄蘑菇生长在哪里？",a="粗柄蘑菇仅生长在黑海岸东北部山区峭壁之泉后方的潮湿洞穴内。",al={"粗柄蘑菇位置","粗柄蘑菇在哪里","粗柄蘑菇洞穴"}},{q="谁需要粗柄蘑菇？",a="居住在奥伯丁的暗夜精灵学者巴瑞萨斯·月影正在寻找粗柄蘑菇，以及毒帽蘑菇，用来调制一种特殊的药剂。",al={"谁使用粗柄蘑菇","巴瑞萨斯·月影的蘑菇","谁需要粗柄蘑菇"}},{q="为什么巴瑞萨斯·月影不亲自去采集这些蘑菇？",a="巴瑞萨斯收到了来自古树之林的警告，不让他靠近那个洞穴，因为那里的树灵感应到一股危险的新邪恶势力在瀑布后方栖息。",al={"为什么不自己去采集","巴瑞萨斯的警告","峭壁之泉洞穴警告"}},{q="还有什么植物与粗柄蘑菇一起生长？",a="洞穴内还生长着致命的毒帽蘑菇，这是巴瑞萨斯进行炼金研究所需的另一种罕见标本。",al={"洞穴里的其他蘑菇","毒帽蘑菇和粗柄蘑菇","峭壁之泉的蘑菇"}}},fp="12,100,22.344.0,21.355.1,28.103.0,24.98.0,58.143.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="老瞎眼的鳞片",s="老瞎眼的鳞片取自那名盘踞在西部荒野海岸的臭名昭著的鱼人领袖。它是从野兽皮上割下的，用来向西部荒野灯塔的幽灵葛瑞森船长证明他已经伏诛，这是确凿无疑的证据。",h="老瞎眼的鳞片取自那名盘踞在西部荒野海岸的臭名昭著的鱼人领袖。它是从野兽皮上割下的，用来向西部荒野灯塔的幽灵葛瑞森船长证明他已经伏诛，这是确凿无疑的证据。",kw={"葛瑞森船长","海岸威胁","鱼人","老瞎眼","老瞎眼的鳞片","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="对于在无尽之海航行并前往暴风城水域的联盟水手来说，终结老瞎眼有助于确保西部荒野的灯塔保持明亮，从而拯救未来的船只免于撞上岩石。"},sec={{t="海岸灾星的战利品",b="西部荒野的海岸本就因为暗礁和狂暴的风雨而危机四伏，而老瞎眼的存在更是将这里的危险程度从航行隐患提升到了屠杀级别。据盘踞在西部荒野灯塔的幽灵葛瑞森船长所言，这只鱼人拥有远超其野蛮同类的狡诈，常会集结意志薄弱的鱼人袭击海岸。在葛瑞森的船撞上礁石的那晚，老瞎眼吓跑了灯塔看守的家人，导致灯塔熄灭；当这一家人回来重新点亮灯塔时，他又发动袭击并残忍地杀害了他们。从这只生物身上取下一枚鳞片是平息这名复仇之魂，并证明海岸已清除这头最凶猛掠食者的唯一方法。"}},faq={{q="老瞎眼的鳞片有什么用？",a="这枚鳞片是用来向盘踞在西部荒野灯塔岩岛上的幽灵葛瑞森船长证明老瞎眼已死的证据。葛瑞森寻求向老瞎眼复仇，因为正是他在船长遭遇致命海难的那晚导致灯塔熄灭，随后又杀害了灯塔看守一家。",al={"谁想要这枚鳞片","老瞎眼的鳞片上交","老瞎眼的鳞片用途"}},{q="谁是老瞎眼？",a="老瞎眼是一只臭名昭著且狡诈凶残的鱼人领袖，经常在西部荒野的沙滩上徘徊。与普通的鱼人不同，他展现出了组织并胁迫同类对海岸前哨站发动协同致命袭击的能力。",al={"谁是老瞎眼","老瞎眼背景故事","老瞎眼"}},{q="为什么老瞎眼要袭击灯塔？",a="老瞎眼起初袭击灯塔是为了赶走看守和他的家人，让海岸陷入黑暗。当看守们回来重新点亮灯火时，老瞎眼又集结同类发起了第二次袭击，杀害了全家人，导致船只无法看清凶险的海岸暗礁。",al={"为什么攻击灯塔","灯塔突袭","老瞎眼灯塔"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="血色十字军臂章",s="血色十字军臂章是血色十字军成员佩戴的徽记，标志着他们对根除一切亡灵生物的狂热忠诚。在丧钟镇，执行官阿伦要求用这些臂章作为证明，以确信新生的被遗忘者已经反击了那些侵入他们领地的狂热分子。",h="血色十字军臂章是血色十字军成员佩戴的徽记，标志着他们对根除一切亡灵生物的狂热忠诚。在丧钟镇，执行官阿伦要求用这些臂章作为证明，以确信新生的被遗忘者已经反击了那些侵入他们领地的狂热分子。",kw={"丧钟镇","执行官阿伦","血色十字军臂章","血色皈依者","血色十字军","血色新兵","提瑞斯法林地"},ang={["race:Undead"]="对于刚被复活的被遗忘者来说，收集这些臂章是了解活人世界仇恨的残酷入门课，让他们明白生存需要对十字军进行无情的反击。"},sec={{t="狂热的徽记",b="无论是血色新兵还是新近加入的皈依者，他们的袖子上都佩戴着血色十字军臂章，这是血色十字军最显著的标志。对于从丧钟镇刚刚苏醒的被遗忘者来说，这些红色的布条代表着就在家门口的致命威胁。十字军并不区分天灾军团的无脑爪牙和黑暗女王麾下拥有自由意志的臣民；在他们眼中，任何行尸走肉都必须被付之一炬。执行官阿伦将收集这些臂章作为一项残酷的试炼，以此确认丧钟镇东南部的敌方侦察兵已被消灭，并证明新生的被遗忘者有能力保卫他们初生的国度。"}},faq={{q="为什么执行官阿伦需要血色十字军臂章？",a="执行官阿伦需要这些臂章作为证明，表明丧钟镇东南部那处不断扩张的血色十字军营地正在被清理。十字军对新觉醒的被遗忘者构成了直接的生存威胁，收集这些信物可以确保他们的前哨侦察兵和新兵已被清除。",al={"为什么收集臂章","阿伦的臂章任务","血色十字军臂章的用途"}},{q="谁佩戴这些臂章？",a="这些臂章由驻扎在丧钟镇附近的低阶血色十字军成员佩戴，具体包括血色新兵、血色皈依者以及信使梅文·科格尔。",al={"谁掉落血色十字军臂章","哪里可以找到臂章"}},{q="为什么血色十字军憎恨被遗忘者？",a="在极端狂热的驱使下，血色十字军拒绝承认巫妖王无脑的天灾军团与拥有自由意志的被遗忘者之间有任何区别。他们视所有亡灵为必须被彻底根除的憎恶。",al={"为什么血色十字军攻击亡灵","十字军与被遗忘者","血色狂热分子"}},{q="这些臂章可以在哪里找到？",a="营地位于提瑞斯法林地丧钟镇的东南部，坐落在定居点边缘之外的山丘中。",al={"血色营地位置","丧钟镇血色营地","血色皈依者在哪里"}}},fp="15,158,21.498.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="血色十字军文件",s="这些截获的文件是由一名丧钟镇附近的血色十字军信使携带的。其中包含了发给血色十字军在提瑞斯法林地各地战场指挥官的命令，为被遗忘者提供了针对十字军区域领导层所需的精确军事情报。",h="这些截获的文件是由一名丧钟镇附近的血色十字军信使携带的。其中包含了发给血色十字军在提瑞斯法林地各地战场指挥官的命令，为被遗忘者提供了针对十字军区域领导层所需的精确军事情报。",kw={"布瑞尔","丧钟镇","执行官阿伦","执行官塞加德","meven korgal","血色十字军文件","血色信使","关键情报"},ang={["race:Undead"]="携带这些截获的文件，标志着一名刚苏醒的被遗忘者完成了丧钟镇的墓地试炼，开始参与由布瑞尔指挥的更广泛的战争。"},sec={{t="截获的命令",b="信使 Meven Korgal 在丧钟镇东南方的十字军营地携带了这些文件。这些指令由大领主下令签发，收件人是血色十字军提瑞斯法区域指挥部的队长们：Perrine 队长需进一步加固西南塔楼并收集布瑞尔亡灵的情报，Vachon 队长需镇压北部塔楼附近的亡灵动向，Melrose 队长则需监视瘟疫之地的边界。这些文件揭示了驻扎在提瑞斯法林地各处的血色指挥官的姓名、职位和命令，使原本例行的信使任务变成了这些狂热者一次灾难性的情报泄露。"},{t="送往布瑞尔",b="执行官阿伦很快意识到，丧钟镇当地的部队无法充分利用这些情报的全部价值。相反，这份缴获的卷宗成为了一名刚苏醒的被遗忘者离开丧钟镇的“通行证”。文件经由东北方向穿过炉灰庄园送达布瑞尔，并直接交给布瑞尔城镇大厅外的执行官塞加德。掌握了这些命令后，被遗忘者的军事领导层正计划对盘踞在林地各处的血色指挥官实施迅速的斩首行动。"}},faq={{q="是谁携带了这些文件？",a="它们是由 Meven Korgal 携带的，这名血色十字军信使是在丧钟镇东南方的十字军营地中被发现的。",al={"谁掉落了这些","血色信使","meven korgal"}},{q="文件中包含什么信息？",a="这份文件包含大领主下达给血色十字军提瑞斯法区域指挥部各队长的指令：Perrine 队长需加固西南塔楼并侦察布瑞尔的亡灵，Vachon 队长需处理北部塔楼附近的亡灵动向，Melrose 队长则需监视瘟疫之地的边界。",al={"文件上写了什么","文件内容"}},{q="谁需要查看这些文件？",a="在为丧钟镇的执行官阿伦取回这些文件后，它们被委托给你送交给执行官塞加德，他在布瑞尔城镇大厅外统筹区域军事行动。",al={"我应该送到哪里","我应该把文件交给谁"}},{q="为什么这些文件对被遗忘者很重要？",a="缴获的命令准确指出了十字军在整个提瑞斯法林地的军官部署，使被遗忘者占据上风，得以清除敌方领导层并粉碎这些狂热者的区域士气。",al={"为什么被遗忘者想要它们","血色文件的重要性"}}},fp="25,265,18.511.0,17.430.0,33.115.0,41.313.0,33.184.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="血色十字军徽记之戒",s="血色十字军徽记之戒是驻扎在提瑞斯法林地的血色十字军成员佩戴的一枚印戒。对于布瑞尔的被遗忘者守卫而言，这些戒指是又一名狂热者被从洛丹伦的土地上清除的恐怖证明。",h="血色十字军徽记之戒是驻扎在提瑞斯法林地的血色十字军成员佩戴的一枚印戒。对于布瑞尔的被遗忘者守卫而言，这些戒指是又一名狂热者被从洛丹伦的土地上清除的恐怖证明。",kw={"布瑞尔","亡灵卫兵伯吉斯","执行官塞加德","死亡证明","血色十字军","血色十字军徽记之戒","提瑞斯法林地","瓦里玛萨斯"},ang={["faction:Horde"]="收集这些戒指有助于新生的部落通过削弱环绕在幽暗城周围的狂热十字军，从而巩固其在东部王国的立足点。",["race:Undead"]="对于被遗忘者来说，从死去的十字军手中夺下这些戒指，就是直接宣告提瑞斯法属于亡者，这是在执行黑暗女王和瓦里玛萨斯的命令。"},sec={{t="狂热的信物",b="提瑞斯法林地的每一名血色十字军战斗人员——从新晋的教徒和狂热的修士，到诸如Melrache和Perrine这样的资深队长——都携带着一枚徽记之戒。这些戒指上刻有十字军燃烧的徽章，在充满偏执的组织内部，它们是辨识兄弟姐妹的凭证。然而对于外人和敌人来说，这些饰品有着完全不同的用途：它们是洛丹伦最狂热的人类残余分子最显著的标识。"},{t="恐惧魔王的悬赏",b="在希尔瓦娜斯女士的恐惧魔王副官瓦里玛萨斯的直接指令下，布瑞尔的亡灵卫兵伯吉斯正在积极收集这些戒指。被遗忘者认为血色十字军是爬满他们新领土的一种无法容忍的瘟疫。对于被遗忘者新兵来说，将成堆的这些戒指带回布瑞尔被视为无可辩驳的死亡证明，以及对幽暗城王座效忠的直接体现。"}},faq={{q="谁佩戴这些徽记之戒？",a="几乎驻扎在提瑞斯法林地的每一名血色十字军成员都佩戴着一枚。这包括新教徒、传教士、狂热者和先锋等普通士兵，以及像Captain Perrine、Captain Melrache和Captain Vachon这样的前线军官。",al={"谁会掉落戒指","哪些十字军拥有戒指","戒指持有者"}},{q="为什么亡灵卫兵伯吉斯想要血色十字军徽记之戒？",a="亡灵卫兵伯吉斯收集这些戒指作为血色十字军正在被屠戮的实物证明。在瓦里玛萨斯和黑暗女王颁布的法令下，布瑞尔的被遗忘者卫戍部队利用这些戒指来衡量新兵的忠诚度以及在清除洛丹伦人类方面的效率。",al={"为什么要收集戒指","死亡证明的原因","伯吉斯的戒指"}},{q="戒指上的徽记代表什么？",a="这枚戒指上带有血色十字军的标志，象征着他们铲除洛丹伦所有亡灵生物的圣战。十字军带着强烈的自豪感佩戴它，将其视为正义的勋章，尽管他们的偏执驱使他们屠杀任何不属于他们组织的人。",al={"血色象征","什么是徽记","戒指标志"}},{q="瓦里玛萨斯在收集这些戒指中扮演什么角色？",a="瓦里玛萨斯是Sylvanas Windrunner在幽暗城的首席副官。他负责监督消灭提瑞斯法林地敌对人类的战略军事行动，这使得根除血色十字军成为执行官塞加德和亡灵卫兵伯吉斯等被遗忘者指挥官的首要任务。",al={"瓦里玛萨斯的命令","为什么瓦里玛萨斯需要戒指","恐惧魔王的介入"}}},fp="21,147,18.322.0,23.328.0,31.232.0,56.255.0,45.250.0,58.260.0"}
P.entries["item:scavenged-goods"] = {n="破烂装备",s="破烂装备是指散落在丧钟镇各处的装备箱内，各种被遗弃的零碎物资和装备。新苏醒的被遗忘者会回收这些物资，以确保源源不断的新兵能够得到武装和遮体。",h="破烂装备是指散落在丧钟镇各处的装备箱内，各种被遗弃的零碎物资和装备。新苏醒的被遗忘者会回收这些物资，以确保源源不断的新兵能够得到武装和遮体。",kw={"亡灵卫兵萨尔坦","丧钟镇","装备箱","被遗忘者补给","破烂装备","在丧钟镇搜集物资"},ang={["race:Undead"]="对于被遗忘者而言，搜集废弃装备是生存的必要手段，这印证了一个残酷的事实：生者绝不会给予他们任何援助或怜悯。"},sec={{t="自力更生",b="当新的被遗忘者从丧钟镇墓地破土而出时，他们醒来时身上几乎只有腐烂的裹尸布。周围的定居点和王国对这些亡灵毫不伸出援手，使他们完全依赖于能够搜集到的任何东西。亡灵卫兵萨尔坦负责统筹收集藏在村庄各处补给箱中的废弃武器、工具和衣物，并直接分发给下一批苏醒的新兵。"}},faq={{q="破烂装备有什么用？",a="亡灵卫兵萨尔坦收集这些装备是为了武装从墓地苏醒的被遗忘者新兵。如果不从附近的板条箱中回收残余物资，新苏醒的亡灵就不得不赤手空拳、衣不蔽体地闯入提瑞斯法林地。",al={"破烂装备用途","为什么要收集破烂装备","萨尔坦如何处理破烂装备"}},{q="在哪里可以找到这些物资？",a="它们是从丧钟镇各处小屋外面和废弃建筑物周围的装备箱中回收的。",al={"在哪里寻找破烂装备","破烂装备位置","装备箱在哪里"}},{q="谁需要这些破烂装备？",a="驻守在丧钟镇的军官亡灵卫兵萨尔坦，指导新觉醒的被遗忘者收集这些补给，以教会他们自力更生，并为即将到来的后续人员做好准备。",al={"谁想要破烂装备","亡灵卫兵萨尔坦任务"}}},fp="15,167,22.334.0,34.185.0,28.102.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="食腐狼的爪子",s="食腐狼的爪子是采集自丧钟镇山丘上游荡的幼年和杂色狼的断肢。刚苏醒的被遗忘者会收集它们，交给当地的看护者缝制成粗糙的防护装备。",h="食腐狼的爪子是采集自丧钟镇山丘上游荡的幼年和杂色狼的断肢。刚苏醒的被遗忘者会收集它们，交给当地的看护者缝制成粗糙的防护装备。",kw={"丧钟镇","新兵艾尔雷斯","杂色食腐狼","食腐狼的爪子","被诅咒者","幼年食腐狼"},ang={["profession:Tailoring"]="新兵艾尔雷斯用狼爪和蝙蝠翅膀进行的粗糙装配，展示了临时缝合工艺是如何支撑起初生的被遗忘者聚落的。",["race:Undead"]="在腐烂的躯体和匮乏的装备中苏醒，从当地的掠食者身上收集部位，往往是组装足以抵御提瑞斯法林地危险的护甲的第一步。"},sec={{t="丧钟镇的拼凑护甲",b="对于刚回到丧钟镇的人来说，资源十分匮乏。随着天灾军团和血色十字军不断逼近提瑞斯法林地，每一块皮毛和骨头都会被投入到实际用途中。暗影牧师萨维斯的助手新兵艾尔雷斯，会将这些当地食腐狼的爪子和蝙蝠翅膀收集起来，为刚从坟墓中爬出、神志不清的被遗忘者制作实用的衣物和护甲。"}},faq={{q="食腐狼的爪子有什么用？",a="它们由丧钟镇的新兵艾尔雷斯收集，她会将这些原始的动物部位裁剪成基础护甲和缝合衣物，供新加入的被遗忘者使用。",al={"食腐狼的爪子用途","爪子的用途","为何收集爪子"}},{q="在哪里可以找到它们？",a="它们取自幼年食腐狼和杂色食腐狼，这些野狼在丧钟镇周围的林地和田野间游荡。",al={"爪子掉落位置","在哪里获得爪子","哪种狼掉落爪子"}},{q="谁需要这些爪子？",a="新兵艾尔雷斯，她负责协助暗影牧师萨维斯救治受伤的新兵、裁剪装备，并为被派往战场的人员提供补给。",al={"谁需要食腐狼的爪子","爪子任务发布者","新兵艾尔雷斯的爪子"}}},fp="13,190,27.418.0,33.131.0,23.117.0,24.158.0"}
P.entries["item:scorched-spider-fang"] = {n="烧焦的蜘蛛牙",s="烧焦的蜘蛛牙是一种特殊的锻造材料，采集自潜伏在湿地潮湿洞穴中的掠食性蛛形生物。矮人护甲商弗伦·长须需要大量的这种经受过高温淬炼的尖牙，为经验丰富的战士锻造坚固的火焰之眼锁甲。",h="烧焦的蜘蛛牙是一种特殊的锻造材料，采集自潜伏在湿地潮湿洞穴中的掠食性蛛形生物。矮人护甲商弗伦·长须需要大量的这种经受过高温淬炼的尖牙，为经验丰富的战士锻造坚固的火焰之眼锁甲。",kw={"穴居潜行者","火焰之眼锁甲","弗伦·长须","水蛭潜行者","烧焦的蜘蛛牙","暴风城","湿地"},ang={["class:Warrior"]="收集五十颗这样的尖牙是弗伦·长须布置的艰巨考验之一，旨在测试你的耐力，并为你标志性的锁甲护甲提供原材料。",["profession:Blacksmithing"]="弗伦将烧焦的甲壳和尖牙融入锁甲环的方法，展现了超越传统冶炼的稀有矮人护甲工艺传统。"},sec={{t="矮人铁匠的配方",b="锻造能够格挡利刃并抵御剧烈冲击的护甲，需要的不仅仅是普通的铁。在暴风城繁忙的街区，技艺精湛的铁匠弗伦·长须使用了一种晦涩的冶金技术，将兽类部件与稀有试剂融合在一起。弗伦要求从沼泽地的大型蛛形生物身上获得五十颗烧焦的尖牙，利用它们致密、带有毒性且天然坚硬的成分来强化锁甲环的淬火工艺。"},{t="湿地的潜行者",b="这些尖牙直接采集自栖息在湿地深陷的山谷和洞穴中的致命蛛形生物，主要是穴居潜行者和水蛭潜行者。尽管沼泽环境潮湿腐烂，这些掠食者却拥有异常坚硬、灼热的下颚。要收集到弗伦所要求的数量，需要深入幽深的洞穴，并清理掉成群的怪物害虫。"}},faq={{q="烧焦的蜘蛛牙有什么用？",a="它们是为弗伦·长须收集的，他是位于暴风城的一名护甲商。他需要五十颗尖牙，外加石爪山脉和剃刀沼泽的组件，为联盟战士锻造一件极其耐用的胸甲。",al={"烧焦的蜘蛛牙有什么用","烧焦的蜘蛛牙用途","谁需要烧焦的蜘蛛牙"}},{q="我在哪里可以找到烧焦的蜘蛛牙？",a="它们取自湿地内的蛛形生物，特别是潜伏在当地潮湿洞穴、山坡和挖掘洞穴中的水蛭潜行者和穴居潜行者。",al={"烧焦的蜘蛛牙掉落地点","哪种蜘蛛掉落烧焦的蜘蛛牙","哪里刷烧焦的蜘蛛牙"}},{q="为什么铁匠需要这么多蜘蛛牙来制造护甲？",a="弗伦·长须采用了非传统的矮人锻造方法。这些硬化尖牙所具备的矿物质密度高、耐火的特性，被用作一种非常规的硬化剂，在与燃素和兽角一起处理时，可以加固锁甲环。",al={"为什么需要50颗牙","为什么弗伦需要蜘蛛牙"}},{q="任何冒险者都能收集并上交这些尖牙吗？",a="虽然任何穿过湿地的旅行者都可以击杀蜘蛛并采集它们的下颚，但弗伦·长须只为寻求获得火焰之眼锁甲的准战士承接这一锻造项目。",al={"烧焦的蜘蛛牙是战士专属吗","谁可以上交烧焦的蜘蛛牙"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scroll-of-messaging"] = {n="通讯卷轴",s="通讯卷轴是一张附有特定魔法传信法术的魔法羊皮纸。它是在石爪山脉为侏儒工程师加克希姆·尘链所获得的，有着不同寻常的用途：提供引爆远程爆炸物所需的魔法触发器。",h="通讯卷轴是一张附有特定魔法传信法术的魔法羊皮纸。它是在石爪山脉为侏儒工程师加克希姆·尘链所获得的，有着不同寻常的用途：提供引爆远程爆炸物所需的魔法触发器。",kw={"爆炸物","加克希姆·尘链","ng-5","远程引爆器","通讯卷轴","石爪山脉","荆棘谷地精"},ang={["faction:Alliance"]="这卷卷轴在帮助联盟特工破坏荆棘谷地精的机械并拖延他们在石爪山脉的环境破坏方面发挥了关键作用。",["profession:Engineering"]="秉承侏儒创新的精神，这卷卷轴展示了理论奥术魔法如何被重新利用为机械拆除工程的远程接收器。"},sec={{t="一份不稳定的讯息",b="虽然名义上是一种用于远程通讯的奥术文书，但加克希姆·尘链对通讯卷轴有着更具破坏性的应用计划。通过将它的传送咒语与不稳定的NG-5炸药结合，这位侏儒计划制造一种远程引爆的爆炸装置。由此产生的爆炸旨在石爪山脉的荆棘谷地精伐木场制造大规模骚乱，为特工们提供潜过守卫、窃取专属工程蓝图和机密信件的机会。"}},faq={{q="通讯卷轴有什么用途？",a="尽管这卷轴上写的是传信法术，但加克希姆·尘链利用其传送魔法来制作远程触发器。当它与爆炸性的NG-5结合时，可以让他从安全距离引爆炸药。",al={"通讯卷轴用途","通讯卷轴有什么作用","为什么加克希姆需要卷轴"}},{q="谁会收到这卷卷轴？",a="这卷卷轴是送交给加克希姆·尘链的，他是一位在石爪山脉活动的联盟侏儒工程师。",al={"谁收到通讯卷轴","我该把通讯卷轴带给谁","卷轴接收者"}},{q="为什么加克希姆需要远程爆炸物？",a="加克希姆需要在当地的荆棘谷地精行动中制造一场大规模的转移注意力事件。由此产生的混乱可以为潜入他们的基地、窃取宝贵的工程计划以及收回旨在阻止他们疯狂砍伐森林的文件提供掩护。",al={"加克希姆使用爆炸物的原因","为什么炸掉荆棘谷地精","石爪山脉的骚乱"}},{q="什么是NG-5？",a="NG-5是加克希姆·尘链使用的一种爆炸性化学装药。配合通讯卷轴上刻写的魔法信号，它就组成了一种简易的远程引爆装置。",al={"ng-5","什么是ng-5","ng-5炸药"}}},fx={["2071477e"]={q="什么是通讯卷轴？",a="通讯卷轴是一张带有奥术法术的魔法羊皮纸。加克希姆·尘链想要找到它，将其作为一种非常规催化剂，与他不稳定的爆炸物NG-5结合，以便制造一种可远程引爆的炸药，用来对付石爪山的荆棘谷地精。",al={"什么是通讯卷轴","通讯卷轴的背景","关于通讯卷轴"}}},fp="19,151,18.328.0,41.155.0,25.84.0,39.220.0,13.134.0"}
P.entries["item:sea-creature-bones"] = {n="海洋生物的骸骨",s="海洋生物的骸骨是从黑海岸雾气缭绕的海岸线上冲上岸的巨大海洋生物尸体上采集到的骨骼样本。这些遗骸被直接送往达纳苏斯的Temple of the Moon，是针对这些巨兽为何会搁浅在海滩上的持续调查的核心。",h="海洋生物的骸骨是从黑海岸雾气缭绕的海岸线上冲上岸的巨大海洋生物尸体上采集到的骨骼样本。这些遗骸被直接送往达纳苏斯的Temple of the Moon，是针对这些巨兽为何会搁浅在海滩上的持续调查的核心。",kw={"奥伯丁","搁浅的海洋生物","黑海岸","灰雾鱼人","温尼斯·布莱葛","薄雾海","海洋生物的骸骨","temple of the moon"},ang={["class:Druid"]="古老海洋掠食者无法解释的死亡预示着卡利姆多外海存在严重的扰动，这令任何致力于维护生态平衡的守护者感到不安。",["race:NightElf"]="黑海岸突然发生的大规模搁浅事件深深困扰着暗夜精灵，他们崇尚自然界的和谐，并将这些搁浅视为需要Temple of the Moon关注的黑暗预兆。"},sec={{t="海岸边的征兆",b="黑海岸雾气笼罩的海滩最近目睹了大量巨大海洋生物的惊人涌入——包括远比当地浅滩原生生物巨大的巨型长尾鲨——它们纷纷冲上浅滩直至死亡。这一景象被暗夜精灵视为一种不祥的征兆。温尼斯·布莱葛是一位被Temple of the Moon派往奥伯丁的调查员，她负责从这些搁浅的利维坦巨兽身上收集骨骼样本，并通过角鹰兽运往达纳苏斯进行仔细检查。"},{t="腐肉与食腐动物",b="回收这些骨骼充满了危险，因为巨大的尸体不可避免地会吸引当地的食腐动物。海岸边的灰雾鱼人经常成群结队地涌向死亡或垂死的利维坦巨兽，啃食遗骸并积极捍卫它们的觅食地。虽然鱼人的力量远不足以独自猎杀如此巨大的生物，但它们在薄雾海沿岸的投机行为迫使调查员和冒险者必须突破这些食腐群落的包围，才能获取用于研究的可用骨骼碎片。"}},faq={{q="为什么这些生物会冲上岸？",a="确切的原因尚不清楚。虽然偶尔发生的搁浅是自然界的风险，但其突然且剧烈的增加被艾露恩的祭司们认为是不自然且令人担忧的，这促使她们展开了正式调查。",al={"为什么长尾鲨会搁浅","黑海岸死亡鲸鱼","为什么生物在黑海岸搁浅"}},{q="谁需要这些骨骼？",a="驻扎在奥伯丁的调查员温尼斯·布莱葛代表达纳苏斯的Temple of the Moon收集这些骨骼，学者和祭司们希望借此查明是什么在扰动海洋。",al={"谁回收骨骼","谁收集海洋生物的骸骨","温尼斯·布莱葛 黑海岸"}},{q="是鱼人杀死了这些巨兽吗？",a="不。当地的灰雾鱼人力量太弱，无法击倒那种体型的海洋生物。它们只是食腐动物，在尸体搁浅后聚集在一起啃食残骸。",al={"鱼人杀了长尾鲨吗","灰雾鱼人杀死海怪"}},{q="骨骼是从哪里回收的？",a="它们直接从搁浅在黑海岸线上的巨型尸体上获取，特别是奥伯丁以南的沙滩和薄雾海沿岸。",al={"海洋生物的骸骨获取地点","搁浅海洋生物地点"}}},fp="18,228,22.418.0,22.351.0,39.215.0,22.194.0,40.160.0,35.139.0"}
P.entries["item:sea-turtle-remains"] = {n="海龟的残骸",s="海龟的残骸是沿着黑海岸沿岸从巨型海龟尸体上打捞出来的骨骼样本。它们是奥伯丁的暗夜精灵研究人员调查令人担忧的海洋生物搁浅激增现象时的重要标本。",h="海龟的残骸是沿着黑海岸沿岸从巨型海龟尸体上打捞出来的骨骼样本。它们是奥伯丁的暗夜精灵研究人员调查令人担忧的海洋生物搁浅激增现象时的重要标本。",kw={"奥伯丁","搁浅的海龟","黑海岸","温尼斯·布莱葛","海龟的残骸","泰达希尔","temple of the moon","被冲上岸"},ang={["class:Druid"]="野生海洋巨兽的不自然死亡，预示着一种更深层的腐化正在破坏卡利姆多海岸的自然平衡。",["race:NightElf"]="在你们的祖居海岸外发生的大规模海洋生物搁浅是一个不祥的征兆，尤其是考虑到种种怀疑都指向了环绕泰达希尔的水域。"},sec={{t="令人不安的搁浅",b="巨型海洋生物开始在黑海岸那雾气弥漫的海岸线上纷纷搁浅，而另一些则沉没在靠近沉船残骸的近海区域。驻扎在奥伯丁的温尼斯·布莱葛负责监督从这些尸体上采集骨骼碎片和组织样本的工作。达纳苏斯的Temple of the Moon急需这些样本，因为有理论担心这些野兽可能是为了逃避环绕着新长成的世界之树泰达希尔的水域中某种不自然的扰动。"},{t="浅滩的拾荒者",b="回收这些残骸是一项危险的工作。海岸边的鱼人部落经常聚集在这些巨大的尸体周围，将骨头啃食干净并在旁边筑巢。学者们需要新鲜的骨骼碎片和组织，以免拾荒者破坏任何可能解释这些生物致命迁徙原因的幸存证据。"}},faq={{q="这些残骸有什么用途？",a="这些残骸由奥伯丁的温尼斯·布莱葛负责收集。她会将它们准备好，送往达纳苏斯的Temple of the Moon交给学者和女祭司，她们正试图查明为什么有这么多海洋生物死在黑海岸。",al={"为什么要收集海龟残骸","海龟骨骼的用途","黑海岸海龟任务"}},{q="为什么海龟会在黑海岸搁浅？",a="确切原因仍在调查中，但研究人员担心海洋生物是在逃离泰达希尔周围水域中令人不安的东西。这些搁浅事件并非孤立存在，预示着大范围的生态危机。",al={"为什么海龟在死亡","黑海岸海龟搁浅","搁浅的海洋生物"}},{q="这些尸体在哪里可以找到？",a="巨型海龟的骨架散落在黑海岸的海岸线上，有些位于奥伯丁以西靠近沉船的浅水中，另一些则散落在被鱼人营地包围的海滩上。",al={"海龟残骸位置","在哪里可以找到海龟骨架"}},{q="谁在研究这些残骸？",a="奥伯丁的研究员温尼斯·布莱葛负责收集这些发现，并直接向达纳苏斯Temple of the Moon的The Sisterhood of Elune提交详细报告。",al={"谁需要这些残骸","温尼斯·布莱葛"}}},fp="18,169,19.406.0,26.291.0,32.222.0,53.224.0,32.181.0,30.149.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="神秘访客的资料",s="神秘访客的资料是一份由典狱官塞尔沃特撰写的机密报告，内容关于一名神秘男子探访了关押在暴风城监狱中的迪菲亚首领巴基尔·斯瑞德。其中的内容有助于追踪一名在暴风城的政治和犯罪领域潜行的秘密特工。",h="神秘访客的资料是一份由典狱官塞尔沃特撰写的机密报告，内容关于一名神秘男子探访了关押在暴风城监狱中的迪菲亚首领巴基尔·斯瑞德。其中的内容有助于追踪一名在暴风城的政治和犯罪领域潜行的秘密特工。",kw={"巴隆斯·阿历克斯顿","巴基尔·斯瑞德","麦里克","mathias shaw","密封的资料","监狱","典狱官塞尔沃特"},ang={["class:Rogue"]="携带这份档案本身就是一堂关于情报工作的实战课：通过将外貌描述与军情七处的情报进行交叉比对，假名、伪造文件和监狱探访等阴谋统统被揭露出来。",["faction:Alliance"]="这份文件暴露了暴风城内部安全体系中令人不安的漏洞，证明了阴谋分子可以使用伪造的证件大摇大摆地穿过监狱大门。"},sec={{t="神秘的赞助人",b="多年来，囚犯巴基尔·斯瑞德一直被关在监狱的牢房里，从未有人探视。这一惯例被打破了，一名沉默寡言的男子开始每周一到两次来到这里，并持有完全合法的身份证件。典狱官塞尔沃特注意到了这些不同寻常的造访，并为这名男子撰写了一份外貌描述，此人的证件上写着名字叫“麦里克”。典狱官封存了这份资料，以防在合适的调查人员采取行动之前被他人窥视。"},{t="从石匠到间谍",b="当这份描述被送到城市建筑师巴隆斯·阿历克斯顿手中时，他并没有立刻认出对方，只是隐约怀疑这名访客可能是与迪菲亚兄弟会叛乱有关的特工。阿历克斯顿很快将密封的信封转交给了暴风城情报机构军情七处的首领马迪亚斯·肖尔大师。肖尔一眼就识破了伪装：这份描述与一名代号包括“马尔森”的致命雇佣兵吻合，此人目前正在为格雷戈尔·莱斯科瓦尔勋爵干脏活。"}},faq={{q="这份描述是谁写的？",a="由暴风城监狱的典狱官塞尔沃特撰写并封存。当一名身份不明的人物开始定期探访被关押的迪菲亚头目巴基尔·斯瑞德时，他产生了怀疑。",al={"谁写的","描述作者","谁撰写的笔记"}},{q="纸上描述的访客是谁？",a="他出示的证件名字是麦里克。典狱官塞尔沃特记录了他的外貌，以便调查人员确认其身份。",al={"谁在探访斯瑞德","麦里克是谁","访客身份"}},{q="访客为什么要见巴基尔·斯瑞德？",a="在多年无人问津后，斯瑞德开始频繁接受探访，这引起了塞尔沃特的怀疑。通过这份密封的资料，人们正在调查这名访客的目的。",al={"为什么探访斯瑞德","斯瑞德访客的目的"}},{q="这份密封文件应该送到哪里？",a="这份文件首先被送往暴风城的城市建筑师巴隆斯·阿历克斯顿处。在阿历克斯顿检查后发现对该描述并不熟悉，他指示你将其直接送到位于Old Town的军情七处总部，交给马迪亚斯·肖尔大师。",al={"送到哪里","谁需要这份资料"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="密封的信封",s="这个密封严实的信封里装有荆棘谷地精的机密技术文件和被盗的设计图。这些文件由被放逐的地精工程师Fizziks收集，其中包含意图送往棘齿城交给斯布特瓦夫的专有设计方案。",h="这个密封严实的信封里装有荆棘谷地精的机密技术文件和被盗的设计图。这些文件由被放逐的地精工程师Fizziks收集，其中包含意图送往棘齿城交给斯布特瓦夫的专有设计方案。",kw={"蓝图","fizziks","棘齿城","密封的信封","斯布特瓦夫","石爪山脉","超级收割机6000型","荆棘谷地精"},ang={["faction:Horde"]="将这些文件从石爪山脉带往南方，有助于棘齿城的中立地精破坏荆棘谷地精那种激进且剥削性的伐木作业。",["profession:Engineering"]="信封里装有超级收割机6000型的技术图纸，代表了地精手中最具有破坏力且利润丰厚的机械自动化装置之一。"},sec={{t="企业间谍",b="当地精工程师Fizziks被突然从石爪山脉的荆棘谷地精伐木作业中驱逐时，他并没有空手离开。他将内部手册、操作规程和技术规范塞进这个信封，设法在监工眼皮底下走私出了公司机密。在这些被盗的记录中，最珍贵的是“超级收割机6000型”的技术图纸，这是一种破坏力惊人的工业伐木机械。"},{t="送往棘齿城",b="Fizziks并没有把这些危险的商业机密埋藏起来，而是将信封向南寄给了斯布特瓦夫，这位工程师居住在棘齿城的中立地精港口。虽然热砂港的商业竞争对手对Fizziks并无多少个人好感或信任，但信封内设计方案的工程价值是不可否认的。这些文件清晰地展示了荆棘谷地精的机械天赋，并让独立工程师们有机会利用荆棘谷地精先进的伐木技术。"}},faq={{q="密封的信封里有什么？",a="信封里装有荆棘谷地精的内部文件、技术操作手册以及超级收割机6000型的蓝图，这些都是Fizziks在仓促离开时顺手拿走的。",al={"信封内容","密封的信封里有什么","密封的信封物品"}},{q="是谁准备了这个信封？",a="这个信封是由Fizziks准备的，他是一位不满的地精工程师，在石爪山脉的伐木场被荆棘谷地精解雇了。",al={"谁制作了信封","谁给出了密封的信封","fizziks的信封"}},{q="谁打算接收它？",a="它写着收件人是斯布特瓦夫，一位居住在贫瘠之地棘齿城港口镇的地精修补匠。",al={"谁得到了信封","信封寄往何处","斯布特瓦夫交付"}},{q="为什么斯布特瓦夫想要这些文件？",a="虽然斯布特瓦夫不喜欢荆棘谷地精，也对Fizziks持怀疑态度，但这些文件包含了宝贵的改进方案和设计图，使外部修补匠能够理解并采用该公司强大的机械设计。",al={"为什么斯布特瓦夫想要它","棘齿城的荆棘谷地精技术"}}},fp="15,110,19.334.0,19.377.0,35.194.0,25.151.0,30.106.0,43.184.0"}
P.entries["item:sealed-note-to-elling"] = {n="给埃林的密信",s="“给埃林的密信”是由暴风城的渔夫乔贞写的一份机密快件。这封信是寄给Trias' Cheese的老板埃林·提亚斯的，它是围绕一位失踪外交官的秘密调查的早期线索。",h="“给埃林的密信”是由暴风城的渔夫乔贞写的一份机密快件。这封信是寄给Trias' Cheese的老板埃林·提亚斯的，它是围绕一位失踪外交官的秘密调查的早期线索。",kw={"埃林·提亚斯","乔贞","给埃林的密信","暴风城","失踪的外交官","trade district","提亚斯的奶酪店"},ang={["class:Rogue"]="熟悉暴风城暗影网络的潜行者们都知道，埃林·提亚斯绝不仅仅是一个卖切达干酪的商人，因此这种秘密通信在他们的行内看来并不足为奇。",["faction:Alliance"]="传递乔贞的信件是为王室直接效劳，推动了一项对暴风城政治稳定至关重要的调查。"},sec={{t="一次安静的交接",b="在暴风城繁忙的街道上携带一封密信似乎是一件平凡小事，但乔贞的严格指示明确了其中的利害关系：务必将羊皮纸亲手交给埃林·提亚斯，并保持沉默。虽然提亚斯表面上表现得像Trade District里一位温和的奶酪商人，但这封秘密信件将关于失踪外交官的调查直接指向了他的柜台，暗示着这里隐藏着比奶酪贸易深得多的网络。"}},faq={{q="密信里写了什么？",a="在交给埃林·提亚斯之前，这封信一直保持密封。它包含乔贞的报告和一份介绍，引导信使向提亚斯进行更深入的询问，以调查外交官的失踪。",al={"密信内容","密信写了什么","信件内容"}},{q="为什么奶酪小贩会收到秘密情报？",a="埃林·提亚斯在Trade District经营着一家不起眼的奶酪店作为公开掩护。在围裙之下，提亚斯在城中拥有庞大的耳目地下网络，这使他成为处理敏感调查时不可或缺的资产。",al={"为什么是埃林·提亚斯","为什么是奶酪店","提亚斯是间谍吗"}},{q="乔贞是谁？",a="乔贞是一名渔夫，可以在暴风城的英雄谷水边找到他。他与埃林·提亚斯和德拉维主教有着某种渊源，主教经常指派他处理需要避开窥视目光的机密事务。",al={"谁写的信","乔贞背景故事","守望者乔贞"}},{q="外交官失踪案是怎么回事？",a="一位被派往塞拉摩会见Jaina Proudmoore的暴风城外交官从未抵达目的地，皇家当局正在悄悄调查每一条可疑线索，以免引起街道上的恐慌。",al={"失踪外交官背景故事","外交官是谁","为什么要调查失踪外交官"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="给守夜人巴库斯的密信",s="给守夜人巴库斯的密信是一份由奶酪大师兼情报贩子埃林·提亚斯所写的机密公文。这封信寄给了一名在夜色镇外巡逻的守夜人，要求对方帮他一个私人忙，收集关于迪菲亚潜行者在暮色森林活动的各种情报。",h="给守夜人巴库斯的密信是一份由奶酪大师兼情报贩子埃林·提亚斯所写的机密公文。这封信寄给了一名在夜色镇外巡逻的守夜人，要求对方帮他一个私人忙，收集关于迪菲亚潜行者在暮色森林活动的各种情报。",kw={"夜色镇","暮色森林","埃林·提亚斯","守夜人","密信","失踪的外交官","守夜人巴库斯"},ang={["class:Rogue"]="提亚斯利用一名普通卫兵作为局部地区的情报线人，是收集城墙之外隐秘情报的教科书式示范。",["faction:Alliance"]="这封信件展示了当官方渠道失效时，非正式的情报手段和个人关系是如何维系联盟那支离破碎的领土的。"},sec={{t="守夜人的一言",b="当乔贞的那封密信将他卷入对失踪外交官的搜寻时，奶酪商埃林·提亚斯不情愿地同意动用他自己的人脉。他写下了这封蜡封信件给守夜人巴库斯，一位驻扎在暮色森林的守夜人卫兵。提亚斯派遣一名冒险者穿过阴森的森林，将这封信亲手送达。他利用与巴库斯长期建立的交情，确保能获得任何关于迪菲亚潜行者在夜色镇附近游荡的报告。"},{t="提亚斯深远的目光",b="虽然表面上只是Trade District里的一名销售精美奶酪的商人，但提亚斯与暮色森林一名镇守卫兵的通信，揭示了他情报网络之广大。夜色镇的守夜人以排外和不信任外人而闻名，他们在亡灵和野兽的持续威胁下勉强求生。然而，巴库斯对提亚斯来信的热情回应证明了，这位看似谦卑的店主拥有着远超暴风城城墙之外的忠诚与尊重。"}},faq={{q="谁写了这封信？",a="这封信是由暴风城Trade District里提亚斯奶酪店的老板埃林·提亚斯所写，他暗地里是一名技术高超的间谍和情报贩子。",al={"谁写了给守夜人巴库斯的密信","密信作者","谁给的信"}},{q="为什么要寄给守夜人巴库斯？",a="守夜人巴库斯是夜色镇守夜人的一员，也是埃林·提亚斯的一名可靠线人。提亚斯需要他分享关于迪菲亚潜行者在暮色森林周边活动的任何当地目击消息或传闻。",al={"守夜人巴库斯是谁","为什么要寄给巴库斯","巴库斯的职责是什么"}},{q="守夜人巴库斯在哪里？",a="守夜人巴库斯在暮色森林夜色镇外通往北方的路上巡逻，监视着通往城镇的森林小径。",al={"巴库斯在哪里","守夜人巴库斯位置","找到守夜人巴库斯"}},{q="送达信件后会发生什么？",a="巴库斯认出了提亚斯的名字和信中的自信，他放下了对游荡冒险者通常持有的戒心，并同意协助调查周边森林中可疑的活动。",al={"巴库斯说了什么","送达信件后"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:searing-collar"] = {n="灼热项圈",s="灼热项圈是隐藏在杜隆塔尔骷髅石中的火刃氏族成员所佩戴的仪式项圈。这些项圈被加热以灼伤佩戴者的血肉，被邪教徒用来让自己与恶魔力量产生共鸣。",h="灼热项圈是隐藏在杜隆塔尔骷髅石中的火刃氏族成员所佩戴的仪式项圈。这些项圈被加热以灼伤佩戴者的血肉，被邪教徒用来让自己与恶魔力量产生共鸣。",kw={"火刃氏族","恶魔","杜隆塔尔","邪能","玛格洛兹","灼热项圈","骷髅石"},ang={["class:Warlock"]="术士们认为灼热项圈虽然粗糙，但却是将邪能腐蚀直接引导进凡人肉体的有效导管。",["race:Orc"]="对于那些努力将族人从恶魔奴役的遗产中解放出来的兽人来说，在杜隆塔尔的家门口发现邪教徒使用这些项圈，是一个阴影依然挥之不去的严峻提醒。"},sec={{t="腐蚀的工具",b="在奥格瑞玛东部骷髅石那阴暗的洞穴中，火刃氏族聚集于此进行黑暗仪式。邪教徒、信徒和暴徒将灼热项圈戴在脖子上，甘愿承受烙印并灼烧皮肤的酷热。隐士玛格洛兹研究着这些残酷的装置，推测灼烧感和束缚在金属上的黑暗附魔是为了让佩戴者直接与恶魔能量产生共鸣。调查这些项圈后发现，它们是恶魔腐蚀渗透进兽人社会的重要渠道，而这一切就发生在部落的眼皮底下。"}},faq={{q="什么是灼热项圈？",a="灼热项圈是火刃氏族邪教徒佩戴在脖子上的仪式项圈。它会灼烧佩戴者的血肉并引导恶魔能量，从而使邪教徒与黑暗魔法产生共鸣。",al={"什么是灼热项圈","灼热项圈背景故事","项圈的作用是什么"}},{q="谁佩戴这些项圈？",a="隐藏在骷髅石内的火刃氏族成员都会佩戴它们，包括邪教徒、狂热者、暴徒、学徒和信徒。",al={"谁在使用它们","谁掉落灼热项圈","火刃氏族项圈"}},{q="为什么邪教徒要灼烧自己的血肉？",a="火刃氏族将这些灼热的金属作为仪式媒介。通过忍受灼烧和恶魔附魔，邪教徒使他们的肉体和灵魂与恶魔力量产生了共鸣。",al={"为什么要灼烧血肉","为什么要佩戴灼热项圈","项圈的目的"}},{q="谁想检查这些灼热项圈？",a="玛格洛兹，一位在杜隆塔尔露营的调查员，他收集这些项圈是为了研究其中的附魔，并揭开火刃氏族黑暗影响背后的秘密。",al={"谁需要灼热项圈","谁在研究这些项圈","玛格洛兹 项圈"}}},fp="14,171,25.454.0,25.149.0,24.136.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="灼热珊瑚",s="灼热珊瑚是一种稀有且坚韧的矿物物质，采自湿地海岸的活铁珊瑚。它深受技师和铁匠的青睐，因其具备非凡的热性能，可以被熔炼并锻造成防护装甲。",h="灼热珊瑚是一种稀有且坚韧的矿物物质，采自湿地海岸的活铁珊瑚。它深受技师和铁匠的青睐，因其具备非凡的热性能，可以被熔炼并锻造成防护装甲。",kw={"弗伦·长须","铁珊瑚","铁炉堡","克洛克莫特·斯帕纳斯潘","米奈希尔港","灼热珊瑚","战士护甲","湿地"},ang={["class:Warrior"]="采集灼热珊瑚是证明你对铁炉堡的大师级护甲匠们忠诚的关键一步，这将为你赢得一件专为抵御前线激烈战斗而定制的护胸甲。",["profession:Blacksmithing"]="灼热珊瑚的结合展示了侏儒的独创性与经典矮人金属工艺的创新融合，将海洋矿物转化为了淬火板甲。"},sec={{t="一种稀有的沿海资源",b="灼热珊瑚仅生长在湿地米奈希尔港以南海岸的寒冷海水中。尽管这种独特的海洋生物在寒冷的咸水中茁壮成长，但它却能产出一种能够承受极端高温的富矿材料。采集者们冒着湿地险恶的浪潮和海岸掠食者的威胁，将这些坚硬的结构撬下来。"},{t="在锻造中的应用",b="虽然在传统的矮人冶金学之外，但灼热珊瑚引起了铁炉堡好奇心旺盛之辈的注意。像克洛克莫特·斯帕纳斯潘这样的侏儒工匠采用了资深护甲匠弗伦·长须的技艺，将珊瑚直接熔炼并捶打进金属合金中，为有抱负的战士们制造轻便且极其耐用的护甲。"}},faq={{q="灼热珊瑚生长在哪里？",a="灼热珊瑚采自米奈希尔港以南海岸沿线的海床。它生长在浅海沿岸水域下方的天然铁珊瑚床内。",al={"灼热珊瑚位置","哪里可以找到灼热珊瑚","铁珊瑚位置"}},{q="铁炉堡里谁需要灼热珊瑚？",a="居住在铁炉堡工匠区的侏儒技师克洛克莫特·斯帕纳斯潘正在寻找灼热珊瑚。他利用这种材料来试验从传奇矮人护甲匠弗伦·长须那里学到的锻造方法。",al={"谁使用灼热珊瑚","克洛克莫特·斯帕纳斯潘 珊瑚","弗伦·长须 珊瑚"}},{q="珊瑚如何能被锻造成护甲？",a="灼热珊瑚具有异常致密且耐热的结构。当在熔炉中熔炼并锤炼进金属合金时，它能强化复合装甲板，从而制造出极其坚韧的防护装备。",al={"珊瑚锻造","可以熔炼珊瑚吗","灼热珊瑚冶金学"}},{q="采集灼热珊瑚危险吗？",a="珊瑚本身一旦找到就很容易采集，但采集过程需要游过湿地海岸外的开阔水域，那里有野生鱼人和好斗的水生野兽出没。",al={"灼热珊瑚很烫吗","采集铁珊瑚"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="保险箱",s="保险箱是一个包裹得严严实实的包裹，里面装满了药水、炼金试剂以及其他准备运往东部王国的杂货。它被委托给在贫瘠之地的旅行者，必须被送到繁忙的棘齿城港口，以赶上外出的潮汐。",h="保险箱是一个包裹得严严实实的包裹，里面装满了药水、炼金试剂以及其他准备运往东部王国的杂货。它被委托给在贫瘠之地的旅行者，必须被送到繁忙的棘齿城港口，以赶上外出的潮汐。",kw={"贫瘠之地","黑水湾","药水","棘齿城","试剂","保险箱","航运","码头管理员迪兹维格"},ang={["faction:Horde"]="通过棘齿城进行航运，提醒了部落的旅行者们，地精港口在卡利姆多和东部王国之间提供了至关重要的中立贸易联系。",["profession:Herbalism"]="试剂的安全包装突显了跨海的炼金术士和草药师是多么依赖边境贸易路线来交换原材料。"},sec={{t="信使的货物",b="卡利姆多与东部王国之间的贸易路线依赖于由信使、沙漠商队和地精商船组成的脆弱链条。当穿过贫瘠之地的陆路商队错过预定的出发时间时，像这个保险箱一样易碎的货物就必须由独立的旅行者运送到海岸。里面装着准备运给无尽之海彼岸合作伙伴的炼金物品、药水和各种试剂。考虑到货物既易碎又贵重，这个箱子被严密封存，以确保它能经受住贫瘠之地干旱的小径和远洋运输中咸湿的海水喷溅。"},{t="通过棘齿城港口",b="陆路运输的终点是棘齿城的码头，由码头管理员迪兹维格监管。棘齿城的港口是物资跨海运往黑水湾等地点的首要中立枢纽。在热砂港的账目下运营，迪兹维格确保无论是小包裹还是重型货物都能得到正确的登记，并装载到下一艘离港的船只上，为旧大陆和边境地区提供了至关重要的商业纽带。"}},faq={{q="保险箱里装的是什么？",a="箱子里装有准备送往东部王国合作伙伴的一系列易碎的药水、炼金试剂和其他补给品。",al={"箱子物品","箱子里装什么","保险箱物品"}},{q="这个箱子要被送到哪里？",a="它必须通过步行送到棘齿城码头的码头管理员迪兹维格那里。从那里开始，迪兹维格会把它预订到一艘横跨海洋驶往旧大陆黑水湾的商船上。",al={"箱子目的地","保险箱去哪"}},{q="为什么这个箱子是交给冒险者而不是商队？",a="发货人没有时间亲自前往棘齿城，而预定的贸易商队已经出发，因此需要一名雇佣信使来赶上潮汐。",al={"为什么我有这个箱子","错过商队"}},{q="谁在棘齿城接收这个箱子？",a="码头管理员迪兹维格在棘齿城码头接收箱子，将其记录在他的航运账本中，然后将其装载到下一艘顺潮出海的船上。",al={"谁接收箱子","迪兹维格箱子"}}},fp="12,147,17.373.0,27.382.0,32.111.0,30.137.0,62.177.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="森内尔的报告",s="“森内尔的报告”是由山地探险者森内尔·白须撰写并发送的一份文件，详述了丹莫罗的霜鬃巨魔威胁。它记载了受王室指令委托的调查结果，收件人为铁炉堡的参议员巴林·红石。",h="“森内尔的报告”是由山地探险者森内尔·白须撰写并发送的一份文件，详述了丹莫罗的霜鬃巨魔威胁。它记载了受王室指令委托的调查结果，收件人为铁炉堡的参议员巴林·红石。",kw={"巴林·红石","霜鬃","铁炉堡","magni bronzebeard","议会","森内尔·白须","森内尔的报告","报告"},ang={["faction:Alliance"]="运送“森内尔的报告”有助于丹莫罗的防御，同时还能游走于铁炉堡统治阶层那棘手的内部政治之中。",["race:Dwarf"]="携带“森内尔的报告”揭示了国王麦格尼·铜须的王室法令与铁炉堡议会所要求的传统权威之间尖锐的政治分歧。"},sec={{t="王室指令",b="这份战地报告在针对盘踞在丹莫罗岩壁中的霜鬃巨魔进行侦察任务后起草，包含了旨在呈报给矮人议会的山地探险者观察记录。驻扎在寒冷山麓的森内尔·白须写下了这份文件，并附上了他兄弟格瑞林关于寒脊山谷的报告，其中说明了格瑞林是奉国王麦格尼·铜须的圣旨行事。森内尔委托冒险者将这些发现直接送到铁炉堡High Seat的参议员巴林·红石手中，并谨慎地建议信使隐瞒他为了完成这份报告所寻求的外部帮助。"},{t="High Seat中的摩擦",b="这份文件在送达王廷后立即引起了轩然大波。在阅读了白须的叙述后，参议员巴林·红石感到愤怒，不仅是因为报告中提到的巨魔威胁，更是因为上面盖有的行政权力印章。麦格尼绕过立法监督，而白须则依据未经核准的王室命令行事，这加剧了矮人议会内部长期存在的不满情绪，凸显了国王麦格尼的果断统治与要求程序控制的愤怒参议员之间存在的政治张力。"}},faq={{q="什么是“森内尔的报告”？",a="这是一份由山地探险者森内尔·白须撰写的正式书面公文，总结了他对丹莫罗霜鬃巨魔的调查情况，旨在直接送达铁炉堡的矮人议会。",al={"森内尔的报告","这份报告是什么","报告"}},{q="谁应该接收这份报告？",a="该报告的收件人是参议员巴林·红石，一位身处铁炉堡High Seat、国王麦格尼·铜须王座附近的刻薄矮人政客。",al={"谁收到报告","我把报告给谁","报告收件人"}},{q="为什么红石参议员在阅读报告时如此愤怒？",a="参议员红石感到愤怒，是因为附件中来自森内尔的兄弟格瑞林·白须的报告揭示了格瑞林是在国王麦格尼的授权下行事，而非咨询矮人议会。红石对王室在没有议会批准的情况下就国防事务采取单方面行动感到愤恨。",al={"巴林为什么生气","参议员为什么生气","红石的反应"}},{q="为什么森内尔要求你不要提及帮助过他？",a="森内尔·白须希望他的上级相信他在冰雪覆盖的山丘中完全靠自己完成了危险的侦察工作，他想维护自己作为一名勤奋且称职的山地探险者的声誉。",al={"为什么保持沉默","森内尔的秘密","森内尔的功劳"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="塞瑞娜·血羽的头颅",s="塞瑞娜·血羽的头颅是取自贫瘠之地北部无水岭鹰身人女族长的恐怖战利品。十字路口的达索克·快刀要求以此作为她已死的证明，并打算将其悬挂在部落的补给马车上，作为震慑后续空中袭击的严酷手段。",h="塞瑞娜·血羽的头颅是取自贫瘠之地北部无水岭鹰身人女族长的恐怖战利品。十字路口的达索克·快刀要求以此作为她已死的证明，并打算将其悬挂在部落的补给马车上，作为震慑后续空中袭击的严酷手段。",kw={"十字路口","达索克·快刀","无水岭","鹰身人","雷克萨","塞瑞娜·血羽","塞瑞娜·血羽的头颅","巫翼"},ang={["class:Rogue"]="达索克·快刀欣赏干净利落、毫不留情的手段，并称赞那些能够潜入敌人巢穴后方、毫不手软地处决目标的雇佣兵。",["faction:Horde"]="车队是连接杜隆塔尔与莫高雷以及各偏远岗哨的生命线；将塞瑞娜的头颅悬挂在补给马车上，传达了部落对这片荒野绝对统治的明确信息。"},sec={{t="路上的警告",b="无水岭的巫翼鹰身人长期以来一直困扰着往来贫瘠之地北部的贸易，但在塞瑞娜·血羽的领导下，她们的袭击变得尤为凶残。她针对部落补给线的袭击源于对她姐妹的私人仇恨，她的姐妹死于兽王雷克萨之手。为了彻底摧毁鹰身人群体的士气，兽人潜行者达索克·快刀下令追杀塞瑞娜。他并不想让她的死默默无闻，而是想要她的头颅，将其挂在下一支出发的车队上——这对从上方峭壁窥视的任何鹰身人来说，都是一个血淋淋的严厉警告。"}},faq={{q="为什么达索克·快刀想要塞瑞娜·血羽的头颅？",a="达索克需要塞瑞娜·血羽已死的无可辩驳的证明，他打算将她的头颅悬挂在部落补给车队的顶端。他希望展示这位女族长的遗骸能恐吓幸存的巫翼鹰身人，并阻止她们袭击过往的旅人。",al={"为什么要拿走塞瑞娜的头颅","达索克 塞瑞娜的头颅","达索克如何处理头颅"}},{q="为什么塞瑞娜·血羽要袭击部落车队？",a="塞瑞娜的袭击源于她对部落的复仇。她的姐妹血羽死于半食人魔勇士雷克萨之手，于是塞瑞娜通过袭击整个贫瘠之地的部落补给线和旅人来寻求报复。",al={"为什么塞瑞娜袭击车队","塞瑞娜·血羽的动机","贫瘠之地的鹰身人袭击"}},{q="这个战利品来自哪里？",a="它取自塞瑞娜·血羽，这位女族长栖息在贫瘠之地西北部尽头的无水岭峭壁之中。",al={"在哪里寻找塞瑞娜的头颅","塞瑞娜·血羽的位置","如何获得塞瑞娜的头颅"}}},fp="13,206,21.420.1,47.195.0,53.175.1,33.129.0"}
P.entries["item:serpentbloom"] = {n="毒蛇花",s="毒蛇花是一种罕见的地下草药，仅生长在哀嚎洞穴的幽深之处。其强大的天然特性引起了被遗忘者皇家药剂师学会的浓厚兴趣。",h="毒蛇花是一种罕见的地下草药，仅生长在哀嚎洞穴的幽深之处。其强大的天然特性引起了被遗忘者皇家药剂师学会的浓厚兴趣。",kw={"药剂师扎玛","贫瘠之地","草药","皇家药剂师学会","毒蛇花","雷霆崖","哀嚎洞穴"},ang={["profession:Herbalism"]="受过训练的草药师拥有敏锐的眼光，能够在别人眼中只有潮湿岩石的地方找到这些罕见的洞穴花朵。",["race:Undead"]="获取毒蛇花能直接帮助药剂师扎玛和皇家药剂师学会，助力他们在这片陌生的土地上搜寻能增强被遗忘者实力的植物资源。"},sec={{t="一种罕见的地下植物",b="毒蛇花仅生长在贫瘠之地地底，即哀嚎洞穴阴暗潮湿的隧道之中。这种植物扎根于受翡翠梦境能量肆意扭曲的生态系统中，在远离阳光的地方茁壮成长，茎叶之间常有毒蛇筑巢。由于洞穴系统充斥着敌对野兽和堕落的德鲁伊，很少有人能带着完好的样本活着回来。"},{t="药剂师的兴趣",b="药剂师扎玛在雷霆崖下方的预见之池开展工作，代表幽暗城的皇家药剂师学会收集毒蛇花。被遗忘者一直在卡利姆多各地搜寻剧毒、奇特且具有强大化学潜力的植物，以支持他们为黑暗女王进行的研究。扎玛认为，大量采集毒蛇花可能会在被遗忘者的炼金术研究方面取得宝贵的突破。"}},faq={{q="毒蛇花生长在哪里？",a="毒蛇花只生长在哀嚎洞穴的最深处，这是一个位于贫瘠之地、十字路口西南方的迷宫式洞穴网络。它附着在洞穴阴暗潮湿的角落地面上。",al={"哪里寻找毒蛇花","毒蛇花位置","哀嚎洞穴草药"}},{q="为什么皇家药剂师学会想要毒蛇花？",a="驻扎在雷霆崖的皇家药剂师学会特工药剂师扎玛正在寻找这种植物进行研究。被遗忘者会研究来自卡利姆多各地的异常且危险的植物，以开发新的化学药剂，并支持Sylvanas Windrunner的宏伟目标。",al={"谁想要毒蛇花","药剂师扎玛草药","为什么要采集毒蛇花"}},{q="为什么采集毒蛇花很危险？",a="除了哀嚎洞穴本身遍布迅猛龙、鳄鱼和堕落德鲁伊的危险外，这种草药本身也经常栖息着毒蛇。触碰这种植物往往会惊动这些潜伏的毒蛇并发动攻击。",al={"毒蛇花的危险","毒蛇花毒蛇"}},{q="草药师能更容易找到毒蛇花吗？",a="是的。受过草药学训练的人天生就能敏锐地察觉植被的生长，并能追踪洞穴地面阴暗角落里的毒蛇花丛。",al={"通过草药学寻找毒蛇花","追踪毒蛇花"}}},fx={bee22cd2={q="毒蛇花是什么？",a="毒蛇花是一种极为罕见的植物，原生于贫瘠之地哀嚎洞穴最幽暗的深处。这种草药扎根于潮湿的地下区域，因其类似蛇类的特性而与众不同——惊扰它时，常会引出盘踞在根部周围的凶猛毒蛇。",al={"毒蛇花是什么","毒蛇花草药","毒蛇花介绍"}}},fp="12,206,25.409.0,19.424.0,29.205.0,56.276.0,41.232.0,45.164.0"}
P.entries["item:sethir-s-journal"] = {n="塞希尔的日记",s="《塞希尔的日记》是泰达希尔难以捉摸的萨特“古老的塞希尔”随身携带的个人记录。通过潜行手段获得后，其内容证实了卡利姆多大陆上的腐蚀正在向这座世界之树蔓延，情况令人担忧。",h="《塞希尔的日记》是泰达希尔难以捉摸的萨特“古老的塞希尔”随身携带的个人记录。通过潜行手段获得后，其内容证实了卡利姆多大陆上的腐蚀正在向这座世界之树蔓延，情况令人担忧。",kw={"黑海岸","命运的召唤","神谕林地","萨特","古老的塞希尔","塞希尔的日记","塞尤娜","泰达希尔"},ang={["class:Rogue"]="取回这本日记证明了，在正面战士和外交官完全失败的地方，巧妙的潜入和偷窃手段依然可以揭示关键的情报。",["race:NightElf"]="这本日记提供了令人不安的证据，表明泰达希尔并不能免受正在卡利姆多大陆蔓延的远古恶魔污染的影响。"},sec={{t="关于腐蚀的线索",b="泰达希尔的建立是为了寄托恢复精灵永恒之力的希望，但一种肉眼不可见的疾病正日益在它的枝桠间生根。达纳苏斯的塞尤娜怀疑，潜伏在神谕林地附近边缘枝干上的孤独萨特——古老的塞希尔掌握着答案。由于直接的外交斡旋和正面武力只会导致往昔的侦察兵丧命，通过悄悄的顺手牵羊，人们成功取回了塞希尔的日记。这些文字揭示了一个残酷的真相：那种正在毒害海对岸黑海岸森林与水域的神秘枯萎病，已经蔓延到了泰达希尔。"}},faq={{q="什么是《塞希尔的日记》？",a="这是一本由古老的塞希尔所携带的日记，他是一只生活在泰达希尔神谕林地附近边缘枝干上的敌对萨特。日记中记录着困扰该地区的腐蚀蔓延的细节。",al={"什么是塞希尔的日记","塞希尔的日记背景故事","塞希尔的日记拥有者"}},{q="如何获得这本日记？",a="由于此前试图与塞希尔谈判或战斗的尝试都以失败和死亡告终，这本日记必须通过潜行，直接从他的背包中偷取。",al={"如何获得塞希尔的日记","塞希尔的日记获取位置","偷窃塞希尔"}},{q="日记揭示了什么？",a="据潜行者训练师塞尤娜所说，这本日记证明了那种正在毒害黑海岸森林和水域的奇怪疾病，已经成功潜入了泰达希尔。",al={"塞希尔的日记内容","塞希尔的日记里有什么"}},{q="谁是古老的塞希尔？",a="塞希尔是一只孤独的萨特，他在神谕林地边缘的一根僻静枝干上筑巢。他以暴力对待入侵者而闻名，手中掌握着关于世界之树腐蚀蔓延的重要情报。",al={"塞希尔是谁","古老的塞希尔"}}},fp="16,147,19.518.1,25.197.0,28.132.0,29.135.0,26.208.0"}
P.entries["item:sevren-s-orders"] = {n="塞弗伦的命令",s="“塞弗伦的命令”是由布瑞尔的执政官塞弗伦亲笔书写的公文。这些命令指示一名久经考验的被遗忘者特工前往幽暗城的Magic Quarter，向强大的法师比索·埃斯沙德报到。",h="“塞弗伦的命令”是由布瑞尔的执政官塞弗伦亲笔书写的公文。这些命令指示一名久经考验的被遗忘者特工前往幽暗城的Magic Quarter，向强大的法师比索·埃斯沙德报到。",kw={"比索·埃斯沙德","布瑞尔","magic quarter","执政官塞弗伦","游荡的巫妖","塞弗伦的命令","幽暗城"},ang={["class:Mage"]="对于奥术施法者而言，递送这些命令可以获得与被遗忘者王国中最顶尖的施法者之一比索·埃斯沙德面谈的机会。",["race:Undead"]="携带塞弗伦的印章标志着一名特工从提瑞斯法地区的本地服务，转变为直接协助幽暗城的奥术精英。"},sec={{t="前往首都的传唤",b="随着被遗忘者不断巩固对洛丹伦废墟的控制，那些在提瑞斯法林地对抗天灾军团时证明了自身价值的熟练特工被传唤往南前往首都。这些由执政官塞弗伦签发的书面命令，作为正式的介绍信和凭证，呈交给Magic Quarter中黑暗女王麾下最重要的奥术施法者之一——比索·埃斯沙德。虽然塞弗伦对于任务的具体内容知之甚少，只知道涉及到与一名游荡的巫妖接触，但这道传唤拥有幽暗城高等法师们的绝对权威。"}},faq={{q="是谁写了这些命令？",a="这些命令是由提瑞斯法林地布瑞尔镇的被遗忘者主管执政官塞弗伦起草的。",al={"塞弗伦的命令的作者","塞弗伦是谁","谁下达了塞弗伦的命令"}},{q="谁是这些命令的接收者？",a="它们是写给位于幽暗城Magic Quarter的被遗忘者高阶法师比索·埃斯沙德的。",al={"谁接收了这些命令","我该把塞弗伦的命令带到哪里","比索·埃斯沙德是谁"}},{q="命令中提到的任务是什么？",a="任务涉及招募一名游荡的巫妖来协助被遗忘者，这是一项危险的任务，需要一名已经在对抗天灾军团的战斗中证明过自己能力的特工。",al={"关于巫妖的任务是什么","比索想要什么","游荡的巫妖任务"}},{q="为什么选择我来递送它们？",a="比索请求一名在对抗天灾军团方面有可靠能力的特工。执政官塞弗伦认为你在提瑞斯法林地的表现足以胜任比索的危险任务。",al={"为什么是我","为什么塞弗伦选中我"}}},fp="15,144,22.466.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shadowhide-pendant"] = {n="暗皮坠饰",s="暗皮坠饰是游荡在赤脊山的暗皮豺狼人所佩戴的粗糙装饰性护身符。作为执行悬赏令的合法证据，收集这些坠饰意味着当地的防御者正在执行湖畔镇针对那些与流亡法师Morganth勾结的豺狼人的法律。",h="暗皮坠饰是游荡在赤脊山的暗皮豺狼人所佩戴的粗糙装饰性护身符。作为执行悬赏令的合法证据，收集这些坠饰意味着当地的防御者正在执行湖畔镇针对那些与流亡法师Morganth勾结的豺狼人的法律。",kw={"拜里弗·科纳彻尔","豺狼人","湖畔镇","fangore中尉","morganth","坠饰","赤脊山","暗皮","所罗门的法律"},ang={["class:Warrior"]="暗皮豺狼人是极具侵略性、身体强壮的对手，他们的队伍考验着保护通往湖畔镇道路的前线防御者。",["faction:Alliance"]="像湖畔镇这样的边境定居点从暴风城守军那里获得的援助很少，这使得当地镇长必须依靠忠诚的联盟冒险者来维护王国法律。"},sec={{t="反抗的信物",b="这些坠饰由暗皮氏族的战士、蛮兵和施法者携带，既是粗糙的个人图腾，也是等级徽章。在赤脊山的深山中，该氏族在Fangore中尉的统领下集结，并受到了奥术流亡者Morganth的蛊惑。对于湖畔镇的居民来说，这些护身符并非仅仅是原始的饰品；它们是标识这个有组织的威胁的记号，这些豺狼人正代表着王国的敌人骚扰着整个地区的定居点。"},{t="湖畔镇的正义",b="根据所罗门镇长的权威和暴风城的法律，主动协助已知的王国罪犯将被判处死刑。由于缺乏足够的皇家援军，Lakeshire Town Hall里的拜里弗·科纳彻尔只能依靠独立的冒险者来维持和平。上交十个暗皮坠饰可以作为这些服从Morganth命令的豺狼人已受到边境正义制裁的实证。"}},faq={{q="什么是暗皮坠饰？",a="它是赤脊山的暗皮豺狼人氏族成员佩戴的一种护身符。当地镇长接受这些坠饰，作为入侵的豺狼人已被击杀以保卫镇区的证据。",al={"什么是暗皮坠饰","暗皮坠饰背景故事","赤脊山坠饰"}},{q="为什么拜里弗·科纳彻尔想要这些坠饰？",a="拜里弗·科纳彻尔收集它们是为了作为根据所罗门法律执行悬赏的证据。由于暗皮氏族正在与叛逃巫师Morganth勾结，威胁当地民众，镇政府认为每一个从属的豺狼人都是应当处以极刑的敌人。",al={"为什么要收集坠饰","拜里弗·科纳彻尔悬赏","科纳彻尔任务"}},{q="谁携带这些坠饰？",a="它们在暗皮氏族的各个阶层中均有携带，从普通的潜行者、蛮兵和狂暴豺狼人，到赤脊山荒野中的“沉默者”Rohh和Fangore中尉这样的角色。",al={"谁会掉落坠饰","哪些豺狼人有坠饰","暗皮坠饰来源"}},{q="暗皮氏族和Morganth之间是什么关系？",a="Morganth是一位潜伏在东部丘陵的奥术流亡者，他利用自己邪恶的力量控制了暗皮豺狼人，将他们作为步兵来恐吓湖畔镇并实施他的阴谋。",al={"豺狼人与morganth","为什么豺狼人要为morganth工作","暗皮与morganth"}}},fp="18,142,18.349.0,19.337.0,29.220.0,46.266.0,27.152.0,66.219.0"}
P.entries["item:shaman-voodoo-charm"] = {n="萨满巫毒符咒",s="萨满巫毒符咒是一件邪恶的仪式饰品，由盘踞在班奈希尔兽穴深处的Gnarlpine熊怪萨满所携带。这件符咒散发着邪恶的气息，引导着一种能够将沉睡的德鲁伊的灵魂从其肉体中剥离的不自然魔法。",h="萨满巫毒符咒是一件邪恶的仪式饰品，由盘踞在班奈希尔兽穴深处的Gnarlpine熊怪萨满所携带。这件符咒散发着邪恶的气息，引导着一种能够将沉睡的德鲁伊的灵魂从其肉体中剥离的不自然魔法。",kw={"班奈希尔兽穴","翡翠梦境","熊怪","gnarlpine","奥本·怒爪","萨满巫毒符咒","沉睡的德鲁伊","泰达希尔"},ang={["class:Druid"]="对于德鲁伊而言，这件符咒代表着对神圣沉睡的恐怖亵渎，它利用黑暗魔法将做梦者困在翡翠梦境中，同时操控他们的肉体。",["race:NightElf"]="在班奈希尔兽穴中发现这些符咒，揭示了Gnarlpine部族对卡多雷最神圣的公共安息地之一的亵渎达到了何种程度。"},sec={{t="扭曲的魔法",b="泰达希尔的Gnarlpine部族已经陷入了疯狂和腐化，但在班奈希尔兽穴中，他们的萨满所掌握的力量远超一般的荒野巫术。通过使用这些奇异的巫毒咒符，萨满们发现了一种将沉睡的德鲁伊的意识从凡世领域剥离，并将其无助地困在翡翠梦境中的方法。通过将灵魂与躯壳分离，熊怪能够操纵空洞的肉体，将受人尊敬的暗夜精灵守护者变成毫无思想的守卫，屠杀任何闯入兽穴的人。"},{t="解开诅咒",b="当德鲁伊奥本·怒爪成为这一仪式的受害者时，他的灵魂被困在了翡翠梦境中，而他那被操纵的躯体却在兽穴深处肆虐。通过帷幕的感应，奥本委托冒险者去击杀Gnarlpine萨满并取回一枚他们的巫毒咒符。通过检查这件饰品中蕴含的邪恶附魔，奥本希望能解读出熊怪的扭曲技艺，并找到破解他被窃躯体上禁锢的方法。"}},faq={{q="萨满巫毒符咒有什么用？",a="Gnarlpine萨满利用这种符咒来实施一种强大的仪式，将沉睡的德鲁伊的灵魂从其肉体中剥离，将思想困在翡翠梦境中，同时操纵空洞的肉体来攻击入侵者。",al={"巫毒符咒用途","符咒的作用","萨满符咒用法"}},{q="谁携带这些符咒？",a="这些符咒由居住在泰达希尔班奈希尔兽穴蜿蜒深处的Gnarlpine萨满携带。",al={"谁掉落符咒","萨满巫毒符咒在哪里找到","gnarlpine萨满符咒"}},{q="为什么奥本·怒爪需要一个符咒？",a="奥本·怒爪目前被困在翡翠梦境中，而他那被操纵的躯体正在到处肆虐。他需要检查符咒的邪恶气息和魔法结构，以便找出破解熊怪附魔的方法。",al={"为什么奥本需要它","奥本·怒爪的符咒","沉睡德鲁伊物品"}},{q="为什么熊怪会拥有巫毒魔法？",a="虽然传统的熊怪萨满崇敬自然之灵和元素，但笼罩泰达希尔的腐化迫使Gnarlpine部族开始研习黑暗、扭曲的魔法。这件符咒所拥有的那种不自然、邪恶的气息，与传统的自然崇拜截然不同。",al={"为什么熊怪使用巫毒","熊怪巫毒背景知识"}}},fp="19,139,17.414.0,20.373.1,41.178.0,25.89.0,32.180.0,34.198.0"}
P.entries["item:shard-of-water"] = {n="水灵碎片",s="水灵碎片是在萨满祭司与水之灵交流过程中收集到的元素遗留物。将其送交给贫瘠之地海岸的水之先知伊斯伦，可以作为学徒已理解水的生命赋予本质并战胜其腐蚀的有力证明。",h="水灵碎片是在萨满祭司与水之灵交流过程中收集到的元素遗留物。将其送交给贫瘠之地海岸的水之先知伊斯伦，可以作为学徒已理解水的生命赋予本质并战胜其腐蚀的有力证明。",kw={"贫瘠之地","call of water","水之先知伊斯伦","水灵碎片","银松森林","水之图腾"},ang={["class:Shaman"]="获得这枚碎片意味着你与水灵调和的最后一步，标志着你为获得水之图腾所进行的漫长旅程的结束。"},sec={{t="元素纯净之证",b="对于寻求掌握元素之力的萨满祭司来说，与水进行交流需要对平衡、生命和守护有深刻的理解。在“Call of Water”的试炼中，萨满祭司会被指引去对抗渗入自然泉水的腐蚀——甚至需要横跨海洋前往如银松森林这样的受灾之地。水灵碎片是在净化这些受污染的水源后获得的。将这枚水晶信物带回贫瘠之地岩石嶙峋的海岸，交给水之先知伊斯伦，即证明了学徒的价值，并提供了铸造水之图腾所需的最后一把钥匙。"}},faq={{q="水灵碎片有什么用途？",a="它是你在贫瘠之地东海岸为水之先知伊斯伦进行试炼的证明。向她出示这枚碎片，即完成了你与水灵的交流，并让你获得水之图腾。",al={"水灵碎片用途","水灵碎片作用","为什么我有水灵碎片"}},{q="谁需要这个物品？",a="水之先知伊斯伦，一位住在商旅海岸棘齿城以南小屋里的萨满祭司，她需要这枚碎片来确认你成功净化了受污染的水源。",al={"谁需要水灵碎片","水灵碎片交还地点","水之先知伊斯伦 碎片"}},{q="为什么试炼地点设在那么远的银松森林？",a="水代表着治愈与守护，然而腐蚀会扼杀生命。银松森林那被污染的水源是对萨满祭司在深度腐化中恢复元素和谐能力的严峻考验。",al={"银松森林水之任务","为什么是银松森林","萨满 银松森林"}}},fp="14,108,25.408.0,36.171.0,23.135.0,48.158.0"}
P.entries["item:shaw-s-report"] = {n="肖尔的报告",s="《肖尔的报告》是一份由军情七处的大师马迪亚斯·肖尔撰写的机密情报，旨在呈交给西部荒野的格里安·斯托曼。报告概述了情报机构所掌握的关于石匠工会及其领袖艾德温·范克里夫的信息，以及他们在暴风城重建后与王室产生的矛盾。",h="《肖尔的报告》是一份由军情七处的大师马迪亚斯·肖尔撰写的机密情报，旨在呈交给西部荒野的格里安·斯托曼。报告概述了情报机构所掌握的关于石匠工会及其领袖艾德温·范克里夫的信息，以及他们在暴风城重建后与王室产生的矛盾。",kw={"迪菲亚兄弟会","艾德温·范克里夫","格里安·斯托曼","mathias shaw","肖尔的报告","军情七处","石匠工会","西部荒野"},ang={["class:Rogue"]="该报告突显了马迪亚斯·肖尔大师的能力与手段，他是暴风城间谍网络的无可争议的主宰，也是军情七处的领袖。",["faction:Alliance"]="这份文件揭露了暴风城内部的腐败，详细叙述了对王国建筑师的欠债是如何引发了一场威胁到王国农田的暴动。"},sec={{t="关于石匠工会的情报",b="《肖尔的报告》从暴风城军情七处的秘密总部被送往哨兵岭，它为人民民兵团提供了关于谁在指挥蹂躏西部荒野的强盗的首份清晰解释。这份文件详细说明了艾德温·范克里夫领导下的石匠工会如何在第一次战争的破坏后，历尽艰辛地重建了暴风城。当王室和贵族拒绝在工程完工后给予石匠们公正的报酬时，苦涩的怨恨便开始滋生。肖尔的情报确立了这些流离失所、心怀不满的工匠与目前正在侵扰王国边境领地的犯罪起义之间的关键联系。"}},faq={{q="《肖尔的报告》是什么？",a="这是一份由暴风城秘密情报机构军情七处的领导者马迪亚斯·肖尔大师汇编并密封的情报档案，寄给格里安·斯托曼。它包含了王室关于石匠工会和艾德温·范克里夫历史的情报。",al={"肖尔的报告","肖尔写了什么","肖尔的报告内容"}},{q="报告揭示了关于艾德温·范克里夫的什么信息？",a="报告确认范克里夫是石匠工会的前任首领，曾负责监督第一次战争后暴风城的重建工作。报告解释说，范克里夫和他的工匠们是因为被王国统治者拒绝支付合理的报酬才发起反叛的。",al={"报告中的范克里夫","报告里关于范克里夫的说法"}},{q="为什么格里安·斯托曼需要这份报告？",a="斯托曼领导着人民民兵团，在西部荒野防御有组织的强盗袭击。在没有正规王国军队支援的情况下，他依赖马迪亚斯·肖尔的间谍工作来揭露谁在指挥这些不法之徒，以及他们真正的动机是什么。",al={"为什么要给格里安送报告","斯托曼为何需要报告"}},{q="斯托曼对这份报告有何反应？",a="斯托曼感到非常不安。他认出艾德温·范克里夫曾是一位勤劳且成就卓著的工匠，难以相信这样一位受人尊敬的建造者竟然会堕落为恶棍，除非有更确凿的证据。",al={"格里安的反应","斯托曼的反应"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shimmering-frond"] = {n="发光的树叶",s="发光的树叶是一种从泰达希尔神谕林地中生长的奇异发光植物上采集到的样本。其不寻常的光芒和扭曲的灵气表明，这是一种完全不属于世界之树枝桠的外来物种。",h="发光的树叶是一种从泰达希尔神谕林地中生长的奇异发光植物上采集到的样本。其不寻常的光芒和扭曲的灵气表明，这是一种完全不属于世界之树枝桠的外来物种。",kw={"植物学","德纳兰","奥拉密斯湖","神谕林地","发光的树叶","奇异的多叶植物","悲伤沼泽","泰达希尔"},ang={["class:Druid"]="一种入侵性的沼泽植物在泰达希尔新生的枝桠上繁茂生长，这是一种值得任何德鲁伊关注的奇特生态异常现象。",["profession:Herbalism"]="在泰达希尔漫游的草药师们一定会钦佩这种悲伤沼泽的原生物种跨越重洋并在异国土壤中茁壮成长所展现出的非凡生命力。"},sec={{t="来自远方的样本",b="当漫步于神谕林地周围的苍翠树冠时，旅行者可能会偶然发现一种散发着脉动光芒的奇异植物。从这种植物上采摘下的叶片以一种不自然的方式捕捉着穿透林地的光线，闪烁着充满活力的光泽。德纳兰是一位在奥拉密斯湖畔照料花圃的植物学家，他一眼就认出这种叶子是原产于东部王国遥远的悲伤沼泽的物种。远隔无尽之海的沼泽种子是如何在刚升起的泰达希尔上扎根并繁茂生长的，这仍然是一个引人入胜的谜团，促使德纳兰将这些样本种在自己的土壤中进行研究。"}},faq={{q="发光的树叶来自哪里？",a="这种叶子是从泰达希尔神谕林地中一种奇异的多叶植物上采集的。该植物因其叶片在森林光线下闪烁着的扭曲、脉动的光芒而引人注目。",al={"在哪里可以获得发光的树叶","发光的树叶位置","奇异的多叶植物"}},{q="谁对发光的树叶感兴趣？",a="德纳兰是一位在奥拉密斯湖畔进行植物学研究的暗夜精灵博物学家，他渴望检查这一样本。他对泰达希尔各处扎根的奇异植被有着浓厚的兴趣。",al={"谁想要发光的树叶","把发光的树叶交给谁","德纳兰 发光的树叶"}},{q="为什么这种植物在泰达希尔如此不寻常？",a="这种植物并非卡利姆多或世界之树的原生物种。德纳兰认出它是原产于悲伤沼泽浑浊水域的物种，那里远在无尽之海彼岸的东部王国，因此它在泰达希尔的繁茂存在令人颇感意外。",al={"为什么发光的树叶很特别","植物起源","悲伤沼泽的植物"}},{q="把叶子交给德纳兰后会发生什么？",a="德纳兰会立即将样本种植并培育在奥拉密斯湖畔的花圃中，以对其快速生长和奇异特性进行测试。",al={"德纳兰用它做什么","发芽的树叶背景故事"}}},fp="16,160,20.435.0,42.154.0,42.177.0,47.189.0,47.114.0"}
P.entries["item:shimmerweed"] = {n="微光草",s="闪光草是一种独特的草药，由丹莫罗雪山之巅闪光岭上的霜鬃巨魔所培育。虽然巨魔采集它是为了进行部落仪式，但当地的矮人酿酒师垂涎其辛辣而独特的风味，将其用于实验性的麦芽酒中。",h="闪光草是一种独特的草药，由丹莫罗雪山之巅闪光岭上的霜鬃巨魔所培育。虽然巨魔采集它是为了进行部落仪式，但当地的矮人酿酒师垂涎其辛辣而独特的风味，将其用于实验性的麦芽酒中。",kw={"烈酒村","丹莫罗","霜鬃","完美的黑啤酒","雷杰德·麦酒","闪光岭","闪光草"},ang={["profession:Herbalism"]="虽然闪光草不属于标准的野外植物学家工具包，但它展示了区域性植物群如何经常被用于当地的酿造传统和仪式炼金术。",["race:Dwarf"]="果然不出矮人足智多谋的本性所料，如果悬崖边长着一种奇怪的植物，终究会有人试着把它发酵成啤酒。"},sec={{t="巨魔的作物",b="在丹莫罗低地高处，霜鬃巨魔在闪光岭的冰冷岩架上照料着一片片闪光草。巨魔们采集并将其储存在营地各处的编织篮中，依靠它来维持他们神圣而神秘的仪式。在巨魔社会之外，很少有登山者会注意这种草药，尽管其强效的特性已经吸引了富有创造力的外来者的目光。"},{t="一种秘密配料",b="在附近的烈酒村，酿酒大师雷杰德·麦酒对这种草药产生了浓厚的兴趣。雷杰德坚信酿酒是他的天职，他试图酿造出终极的矮人黑啤酒，并怀疑闪光草那浓烈且鲜明的风味可能就是缺失的那一块拼图。他经常雇佣冒险者潜入霜鬃巨魔的营地，躲避敌对的巨魔，并将成捆的草药运回来倒入他的发酵桶中。"}},faq={{q="闪光草生长在哪里？",a="闪光草生长在丹莫罗烈酒村西北部一座冰冷的丘陵——闪光岭上。它由霜鬃巨魔培育和采集，并被储存在他们营地周围的篮子里。",al={"闪光草位置","哪里可以找到闪光草","闪光岭植物"}},{q="霜鬃巨魔用闪光草做什么？",a="霜鬃巨魔将闪光草用于他们神秘的部落仪式和庆典中。虽然外人并不了解这些仪式的具体细节，但这种草药在他们在闪光岭的文化和精神活动中发挥着积极的作用。",al={"巨魔使用闪光草","为什么巨魔需要闪光草"}},{q="为什么雷杰德·麦酒想要闪光草？",a="雷杰德·麦酒正在烈酒村努力酿造完美的矮人黑啤酒。在发现这种野生草药中有一种独特的味道后，他想把新鲜的闪光草投入他的实验性麦芽浆中，看看它能否带来他的配方所需要的那种浓郁口感。",al={"雷杰德·麦酒任务","谁想要闪光草","为什么要用闪光草酿酒"}},{q="闪光草在丹莫罗以外的地方生长吗？",a="在杜隆塔尔等干旱地区也采集到过各种闪光草，像德雷克塔尔这样的先知非常看重这种植物，用它来制作强效的草药混合剂和药酒，这证明了这种草药能够适应卡兹莫丹冰冻山峰以外的环境。",al={"闪光草 杜隆塔尔","丹莫罗以外的闪光草"}}},fp="11,155,15.324.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="辛德瑞尔的便笺",s="《辛德瑞尔的便笺》是一封书面信函，详细记录了近期在阿斯特兰纳和灰谷沿岸观察到的腐蚀情况。这封信由暗夜精灵哨兵辛德瑞尔·速火撰写，是一份穿过森林向东送往德鲁伊凯尼斯·微风的情报报告。",h="《辛德瑞尔的便笺》是一封书面信函，详细记录了近期在阿斯特兰纳和灰谷沿岸观察到的腐蚀情况。这封信由暗夜精灵哨兵辛德瑞尔·速火撰写，是一份穿过森林向东送往德鲁伊凯尼斯·微风的情报报告。",kw={"灰谷","阿斯特兰纳","林歌神殿","凯尼斯·微风","夜歌森林","辛德瑞尔·速火","辛德瑞尔的便笺"},ang={["class:Druid"]="将辛德瑞尔的观察结果带给凯尼斯·微风，有助于其他德鲁伊揭开困扰森林的非自然枯萎病的根源。",["race:NightElf"]="这封信函展示了保卫灰谷定居点的哨兵与研究其生态疾病的塞纳里奥德鲁伊之间持续的合作。"},sec={{t="穿越森林的信函",b="随着动荡在灰谷四处蔓延，暗夜精灵哨兵和德鲁伊们相互配合，监视着林地的边界。这份报告由阿斯特兰纳的哨兵辛德瑞尔·速火撰写，详细描述了在西海岸和中央林冠沿线发现的令人不安的骚乱。信件的收件人是凯尼斯·微风，一位驻扎在东部夜歌森林中林歌神殿的德鲁伊。通过派遣信使传达她的一手观察结果，辛德瑞尔协助了凯尼斯对悄然潜入圣地的腐蚀进行的调查。"}},faq={{q="什么是《辛德瑞尔的便笺》？",a="这是一份由哨兵辛德瑞尔·速火撰写的实地报告，详细说明了在阿斯特兰纳附近和灰谷沿岸发现的骚乱和疑似腐蚀迹象。",al={"这是什么便笺","辛德瑞尔的便笺","便笺里写了什么"}},{q="谁应该收到这封便笺？",a="这封便笺的收件人是凯尼斯·微风，一位位于灰谷东部边缘——即夜歌森林——的林歌神殿的暗夜精灵德鲁伊。",al={"我应该把它交给谁","它要送往哪里","这封便笺是写给谁的"}},{q="为什么要写这封便笺？",a="凯尼斯·微风请求获取关于西部森林异常事件的情报，他担心一种阴险的腐蚀正在林地中扎根。辛德瑞尔整理了她的观察结果，以帮助他评估威胁。",al={"为什么要写这封便笺","辛德瑞尔提到的腐蚀是什么","报告的目的"}},{q="辛德瑞尔·速火住在哪里？",a="辛德瑞尔·速火是一位驻扎在灰谷中部阿斯特兰纳定居点的暗夜精灵哨兵。",al={"辛德瑞尔在哪里","辛德瑞尔·速火的位置","谁发送了这个"}}},fx={ed6c40b2={q="辛德瑞尔的便笺来自哪里？是谁写的？",a="这份便笺由哨兵辛德瑞尔·速火在阿斯特兰纳写下。它是一份正式的实地报告，详细记述了她在灰谷海岸沿线及周围林地观察到的令人不安的事件。",al={"谁写了辛德瑞尔的便笺","谁制作了辛德瑞尔的便笺","辛德瑞尔便笺的来源"}}},fp="16,190,26.481.0,25.141.0,33.121.0,25.196.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="一箱靴子",s="一箱由藏宝海湾的商人崔斯里克发出的鞋履，原定送往棘齿城供加兹鲁维的贸易网络使用。它在商旅海岸附近被南海海盗拦截，并被藏在港口南面的营地中。",h="一箱由藏宝海湾的商人崔斯里克发出的鞋履，原定送往棘齿城供加兹鲁维的贸易网络使用。它在商旅海岸附近被南海海盗拦截，并被藏在港口南面的营地中。",kw={"藏宝海湾","崔斯里克","加兹鲁维","棘齿城","一箱靴子","南海海盗","被盗财物"},ang={["class:Rogue"]="潜入沿海的南海海盗营地需要避开密集的海盗巡逻队，因此悄悄接近是收回加兹鲁维被盗货物最安全的方式。"},sec={{t="被劫掠的货物",b="经营一个地精贸易港口需要源源不断的物资，加兹鲁维安排了从藏宝海湾的一位服装供应商崔斯里克那里运来一批新靴子。这批货物从未抵达棘齿城的码头。在商旅海岸徘徊的南海海盗伏击了运输船，将装有货物的箱子搬运到了他们位于港口南面的海滩营地。海盗们将窃得的货物散落在他们的帐篷和棚屋里，使得加兹鲁维没能如期收到货物，直到雇佣冒险者佣兵去搜寻海岸线为止。"}},faq={{q="是谁寄出了这批靴子？",a="这批靴子是由藏宝海湾的崔斯里克寄出的，他是一位在地精港口经营服装和补给品商店的地精商人。",al={"谁制作了靴子","靴子从哪里来","崔斯里克的靴子"}},{q="谁应该收到这批靴子？",a="棘齿城的总工程师兼负责人加兹鲁维订购了这些鞋履，以支持当地的劳动力和商业运作。",al={"谁拥有这些靴子","加兹鲁维的靴子货运"}},{q="这些靴子是怎么落到海盗手中的？",a="南海海盗在贫瘠之地的海岸线沿途拦截了这艘货船，劫掠了船只，并将箱子搬运回了他们棘齿城南面的营地。",al={"为什么南海海盗会有靴子","谁偷了靴子"}},{q="这批货物可以在哪里找到？",a="箱子位于棘齿城以南海岸线上的南海海盗营地内，被藏在他们劫掠的货物之中。",al={"靴子位置","一箱靴子在哪里","寻找靴子货物"}}},fp="17,206,17.352.0,32.80.0,38.152.0,42.145.0,32.112.0"}
P.entries["item:shipment-of-iron"] = {n="一箱铁材",s="一箱存放在希尔斯布莱德农场人类铁匠铺的原材料。它是当地武器生产的重要物资，因此成为被遗忘者部队的优先目标，旨在切断供给希尔斯布莱德镇民的补给线。",h="一箱存放在希尔斯布莱德农场人类铁匠铺的原材料。它是当地武器生产的重要物资，因此成为被遗忘者部队的优先目标，旨在切断供给希尔斯布莱德镇民的补给线。",kw={"希尔斯布莱德之战","达萨利亚","希尔斯布莱德农场","一箱铁材","塔伦米尔","维林坦"},ang={["faction:Horde"]="在战役转向南海镇之前，拒绝向希尔斯布莱德提供补给会严重削弱农民的武装抵抗能力。",["profession:Blacksmithing"]="这批储备代表了山谷中人类武器生产的命脉；没有生铁锭，维林坦的熔炉就完全无法运作。"},sec={{t="助长反抗",b="在希尔斯布莱德丘陵持续不断的冲突中，人类农民对塔伦米尔进行了出人意料的顽强抵抗。这种战斗能力很大程度上直接源于位于希尔斯布莱德农场西南边缘的铁匠铺，铁匠维林坦和他的学徒们在那里昼夜不停地工作，将大批运来的铁材打造为武器和盔甲。为了瓦解农民的抵抗意志，被遗忘者指挥官下令熄灭熔炉，除掉铁匠，并将储备的金属据为己有以支持部落的战争努力。"}},faq={{q="一箱铁材存放在哪里？",a="这箱铁材就放在位于希尔斯布莱德农场西南边缘的铁匠铺内，由铁匠维林坦和他的学徒们严密守卫。",al={"一箱铁材位置","铁材在哪里","希尔斯布莱德铁材位置"}},{q="为什么被遗忘者想要这些铁材？",a="夺取这些铁材可以切断武装当地人类民兵的武器供应线。高级执行官达萨利亚也打算在进攻转向夷平南海镇时，将这些金属储备用于支持部落的战争机器。",al={"为什么要偷铁材","塔伦米尔铁材","希尔斯布莱德之战铁材用途"}},{q="这些铁材最初是谁在使用的？",a="铁匠维林坦和他的四名学徒用这些铁材为镇民和田间工人装备武器，将普通的农民变成了对抗亡灵的武装民兵。",al={"谁拥有这些铁材","维林坦的铁材","希尔斯布莱德铁匠"}},{q="是谁下令回收这批铁材的？",a="坐镇塔伦米尔指挥被遗忘者行动的高级执行官达萨利亚，在希尔斯布莱德之战期间下达了直接命令，要求屠杀铁匠并夺取铁材。",al={"谁发布任务","达萨利亚铁材任务"}}},fx={["8a003d21"]={q="一箱铁材是什么？",a="一箱铁材是存放在希尔斯布莱德农场人类铁匠铺中的一批原料金属。它是铁匠维林坦和他的学徒锻造武器与护甲的主要材料，这些装备供当地抵抗被遗忘者的希尔斯布莱德居民使用。",al={"一箱铁材是什么","一箱铁材","希尔斯布莱德的铁材货物"}}},fp="16,211,22.473.0,35.157.0,37.218.0,35.178.0,46.152.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="“Shipping Schedule”是一份由迪菲亚潜行者在杰罗德码头的码头管理员持有的物流文件。它概述了在赤脊山和西部荒野之间通过艾尔文森林运送非法货物的路线，引起了暴风城情报机构的密切关注。",h="“Shipping Schedule”是一份由迪菲亚潜行者在杰罗德码头的码头管理员持有的物流文件。它概述了在赤脊山和西部荒野之间通过艾尔文森林运送非法货物的路线，引起了暴风城情报机构的密切关注。",kw={"迪菲亚潜行者","码头管理员","艾尔文森林","杰罗德码头","mathias shaw","shipping schedule","军情七处","走私"},ang={["class:Rogue"]="从码头管理员的口袋中获取这份时间表，是对于渴望加入军情七处行列的预备特工在潜行和偷窃能力上的一次决定性测试。"},sec={{t="杰罗德码头的走私活动",b="在闪金镇南部的纳兹费瑞提河艾尔文森林岸边，迪菲亚潜行者夺取了杰罗德码头的控制权，将其作为他们河流运输的枢纽。通过这个隐秘的码头，迪菲亚潜行者在赤脊山和西部荒野之间大量运输违禁品，顺着水路在暴风城卫兵的眼皮底下溜过。“Shipping Schedule”记录了这些秘密行动，由码头管理员贴身严密保管。"},{t="军情七处的瞄准镜下",b="军情七处领袖马迪亚斯·肖尔大师委托窃取这份时间表，以绘制迪菲亚的补给链并测试新晋特工。潜入码头仓库并从码头管理员口袋中偷走文件，既能为王国提供可行的情报，也是一项入职测试。如果特工被抓住，军情七处将否认一切联系，不会留下任何指向暴风城军情七处总部的痕迹。"}},faq={{q="什么是“Shipping Schedule”？",a="这是迪菲亚潜行者在杰罗德码头的码头管理员所保存的一份行动日志。它详细记录了在艾尔文森林内陆水域运往赤脊山和西部荒野之间的违禁品和补给品的运输情况。",al={"迪菲亚船运时间表","这份文件是什么","码头管理员时间表"}},{q="谁想要找回这份时间表？",a="暴风城情报机构军情七处的负责人马迪亚斯·肖尔大师。他利用这些情报追踪迪菲亚的走私网络，并评估外勤中表现出色的潜行者。",al={"谁需要这份时间表","马迪亚斯·肖尔时间表","谁拿走了shipping schedule"}},{q="在哪里可以找到这份时间表？",a="这份文件由迪菲亚码头管理员携带，位于艾尔文森林闪金镇南部的纳兹费瑞提河畔，杰罗德码头的码头仓库内。特工必须潜入建筑物并通过偷窃或击杀掠夺的方式从他身上获得。",al={"shipping schedule位置","码头管理员在哪里","如何获取时间表"}},{q="杰罗德码头是做什么用的？",a="杰罗德码头被迪菲亚强盗占领，作为中转站使用。他们利用其水路通道在王国境内走私非法货物，直接将他们在赤脊山的行动与在西部荒野的据点联系起来。",al={"杰罗德码头 迪菲亚","迪菲亚为什么占领杰罗德码头","迪菲亚码头 艾尔文"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:sida-s-bag"] = {n="塞达的背包",s="塞达的背包是居住在米奈希尔港的塞达的个人背包。在一次前往铁须之墓的游览途中，她被一只蠕动的软泥怪整个人吞掉，这个背包及其神秘的内容物需要彻底搜寻湿地的酸性软泥怪才能找回。",h="塞达的背包是居住在米奈希尔港的塞达的个人背包。在一次前往铁须之墓的游览途中，她被一只蠕动的软泥怪整个人吞掉，这个背包及其神秘的内容物需要彻底搜寻湿地的酸性软泥怪才能找回。",kw={"丹莫德","铁须之墓","米奈希尔港","软泥怪","塞达","塞达的背包","湿地"},ang={["faction:Alliance"]="米奈希尔港饱受困扰的难民和镇民完全依赖过往的旅行者来处理从被淹没的湿地中爬出来的掠食性恐怖生物。"},sec={{t="惊慌的防御",b="当塞达每周例行前往丹莫德附近的铁须之墓时，她发现自己遭到了该地区令人恐惧的滴水软泥怪的伏击。面对逼近的淤泥，她惊慌失措地将自己的个人背包直接扔向了其中一只生物。然而这并没有赶走野兽，软泥怪反而直接将背包吞噬进了它那胶状的身体里。这一干扰为塞达赢得了宝贵的逃生时间，让她得以逃回安全的米奈希尔港，却将她的财物困在了一只未知的软泥怪体内。"},{t="从淤泥中回收",b="因为徘徊在铁须之墓的波动软泥怪（从深红品种到巨大品种）看起来大同小异，找到这个背包需要不停地猎杀沼泽软泥怪，直到被吞掉的背包完好无损地掉落出来。尽管浸泡在酸性的消化黏液中，这个耐用的背包还是保存了其中的内容物。一旦归还给塞达，她会急切地取回自己的物品并丢弃那破损的、沾满粘液的外壳，将洗净的容器交给替她勇敢闯入沼泽的人。"}},faq={{q="为什么塞达的背包在软泥怪体内？",a="塞达在造访铁须之墓时遭到滴水软泥怪的袭击而惊慌失措。为了逃命，她绝望地将背包扔向其中一只怪物，怪物立即将其吞没并整个咽了下去。",al={"软泥怪怎么得到背包","背包为何在淤泥中","塞达如何丢失背包"}},{q="哪些软泥怪携带着塞达的背包？",a="塞达无法分辨这些软泥怪，因此湿地东北部铁须之墓周围的任何掠食性软泥怪——包括深红软泥怪、黑色软泥怪或巨大软泥怪——都有可能吞掉了它。",al={"哪里寻找塞达的背包","什么掉落塞达的背包","哪只软泥怪有背包"}},{q="为什么塞达要造访铁须之墓？",a="塞达每周都会从米奈希尔港长途跋涉去造访丹莫德附近的这座古老矮人墓穴，不过她将这些例行造访背后的个人原因深藏在心底。",al={"塞达与铁须的联系","为什么去铁须之墓"}},{q="塞达的背包里装了什么？",a="塞达迅速将找回的物品倒在地上并收集起来，没有展示它们是什么，只是提到里面的东西太重要了，不能任由它们在软泥怪体内溶解。",al={"塞达从背包里拿出了什么","背包内容物"}}},fx={["113113dd"]={q="塞达的背包是什么？",a="塞达的背包是居住在米奈希尔港的塞达的私人背包。她照常前往湿地的铁须之墓时遭到软泥怪袭击，慌乱逃跑之际把背包扔向其中一只软泥怪。那只软泥怪将背包整个吞下，背包就此困在它胶状的身体里。",al={"塞达的背包是什么","塞达的背包","谁是塞达的背包"}},afbd2451={q="塞达为什么想要拿回她的背包？",a="塞达急需的是丢失背包里锁着的东西，而不是背包本身。你从铁须之墓的软泥怪残骸中把背包撬出来并交还给米奈希尔港的塞达后，她会立刻把沾满黏液的东西倒在地上，捡起里面的物品，再把空背包还给你。",al={"塞达为什么想要她的背包","塞达的背包为什么","为什么有人想要塞达的背包"}}},fp="10,261,18.338.0,24.421.0,34.157.0,29.204.0,37.155.0,27.179.0"}
P.entries["item:signed-recruitment-letter"] = {n="签过字的募兵信",s="签过字的募兵信是由前沿哨所的卡加尔·战痕签发的官方公文。它带有卡加尔的印记，将新兵调往贫瘠之地的腹地，前往十字路口报到。",h="签过字的募兵信是由前沿哨所的卡加尔·战痕签发的官方公文。它带有卡加尔的印记，将新兵调往贫瘠之地的腹地，前往十字路口报到。",kw={"征兵","十字路口","前沿哨所","卡加尔·战痕","sergra darkthorn","签过字的募兵信","贫瘠之地","thrall"},ang={["class:Shaman"]="这份文件将你送交到Sergra Darkthorn的麾下服役，她是一位备受推崇的兽人萨满，受Thrall所托，负责协助巩固贫瘠之地的防线。",["faction:Horde"]="这封募兵信代表了你从杜隆塔尔的基础服役生涯转向部落前线更广阔的军事体系。"},sec={{t="新兵调令",b="作为贫瘠之地的东部门户，前沿哨所负责评估从杜隆塔尔跨越怒水河而来的新来者。一旦新兵向卡加尔·战痕证明了自己的准备就绪，他就会盖章并签署这封介绍信。它作为军事命令，指引新兵沿路向西前往十字路口，Sergra Darkthorn在那里负责协调这片干燥平原上的后勤行动和领土防御。"},{t="哨所之间的紧张关系",b="虽然这封信是部落的官方文件，但卡加尔并不掩饰他对等待新兵的那位军官的个人鄙视。他认为Sergra Darkthorn是一位说话尖酸刻薄的萨满，只会对士兵们夸夸其谈，并公开质疑大酋长Thrall对她的高度评价。尽管心存疑虑，但在获得十字路口的进一步指派之前，必须将这份公文直接送到Sergra手中。"}},faq={{q="签过字的募兵信有什么用？",a="这封信是一份官方的军事调动文件。它向十字路口的Sergra Darkthorn证明，卡加尔·战痕已经在前沿哨所对你进行了审查，并认为你已准备好在贫瘠之地服役。",al={"募兵信的作用","募兵信的使用","贫瘠之地的签过字的募兵信"}},{q="谁签署了这封信？",a="卡加尔·战痕，一位负责监管杜隆塔尔和贫瘠之地边界前沿哨所的兽人老兵。他在新兵完成边界的初步职责后会签署这封信。",al={"谁写了这封信","卡加尔的信","谁签了字"}},{q="我要把这封信交给谁？",a="你要把信交给Sergra Darkthorn，一位驻扎在十字路口中心枢纽的有影响力的兽人萨满。",al={"信交给谁","信的接收者","信件接收人"}},{q="为什么卡加尔会说Sergra Darkthorn的坏话？",a="卡加尔认为Sergra是一位尖酸刻薄、难以相处的军官，在有工作要做时却只会浪费时间空谈。尽管大酋长Thrall对她评价很高，卡加尔仍然对她的领导能力持怀疑态度。",al={"卡加尔与sergra的矛盾","卡加尔为什么讨厌sergra"}}},fp="25,151,22.398.0,23.339.0,53.190.0,22.184.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Silithid Egg (The Barrens)",s="异种蝎卵是筑巢在南贫瘠之地的这种昆虫生物的发育中的幼体。这些卵簇被埋在巨人旷野周围的土丘中，部落的研究人员为了探寻这些入侵虫群的起源和智力，正在收集它们。",h="异种蝎卵是筑巢在南贫瘠之地的这种昆虫生物的发育中的幼体。这些卵簇被埋在巨人旷野周围的土丘中，部落的研究人员为了探寻这些入侵虫群的起源和智力，正在收集它们。",kw={"十字路口","掘地铲","寻找异种蝎卵","巨人旷野","科兰","土丘","异种蝎","异种蝎卵","贫瘠之地"},ang={["faction:Horde"]="在十字路口附近出现智慧虫群对卡利姆多中部的部落贸易路线和领土构成了令人不安的威胁。"},sec={{t="神秘的虫群",b="在巨人旷野干旱的盆地中，奇异的类昆虫生物已经开始翻动土地，筑起高耸的土丘。在这些巢穴深处，埋藏着它们的卵，它们深埋在坚硬的土壤之下，并由领地意识极强的虫群看守。部落对于异种蝎了解甚少，但驻守在十字路口的斥候已经注意到，这些生物展现出的协调行为和惊人智力远超普通的野兽。收集尚未孵化的卵为奥格瑞玛的学者提供了研究这种新兴威胁的生命周期和本质的最好机会。"},{t="发掘与危险",b="要获取这些卵，需要用特制的掘地铲撬开异种蝎的土丘。惊动这些卵簇是危险的工作；异种蝎对靠近其地下育儿室的入侵者反应激烈，会围攻任何威胁到它们未孵化幼虫的生物。对于像巨魔科兰这样的研究人员来说，在虫群进一步蔓延到整个卡利姆多之前，获取完整、未破损的样本对于分析至关重要。"}},faq={{q="什么是异种蝎卵？",a="它们是昆虫般的异种蝎尚未孵化的卵簇，筑巢于南贫瘠之地的土丘内，特别是在整个巨人旷野随处可见。",al={"异种蝎卵","什么是异种蝎卵","异种蝎土丘"}},{q="谁在收集这些卵？",a="驻守在十字路口的巨魔研究员科兰代表奥格瑞玛的导师们收集这些卵，以研究异种蝎奇特的生理结构和行为。",al={"谁需要这些卵","科兰的任务","收集卵的任务发布者"}},{q="为什么要研究异种蝎？",a="部落对异种蝎知之甚少。科兰指出，它们表现出的智力和协调能力远超普通的野生动物，这引起了部落首领们对它们突然出现在贫瘠之地的担忧。",al={"为什么要研究异种蝎","异种蝎威胁","异种蝎聪明吗"}},{q="如何收集这些卵？",a="必须使用改良的掘地铲小心地从异种蝎土丘中挖掘出来，同时还要抵御保卫巢穴的凶猛虫群。",al={"如何获取卵","掘地铲","收割异种蝎卵"}}},fp="26,165,18.429.0,21.294.0,23.125.0,31.141.0,35.199.0,26.111.0"}
P.entries["item:silixiz-s-tower-key"] = {n="希里克斯的塔楼钥匙",s="希里克斯的塔楼钥匙是一把小钥匙，由淤泥沼泽附近荆棘谷地精塔楼外的工头希里克斯携带。属于破碎手氏族的部落特工受命在一次秘密破坏任务中，直接从这位工头的口袋里偷走它。",h="希里克斯的塔楼钥匙是一把小钥匙，由淤泥沼泽附近荆棘谷地精塔楼外的工头希里克斯携带。属于破碎手氏族的部落特工受命在一次秘密破坏任务中，直接从这位工头的口袋里偷走它。",kw={"贫瘠之地","工头希里克斯","破碎手氏族","申苏尔","希里克斯","淤泥沼泽","塔楼钥匙","荆棘谷地精"},ang={["class:Rogue"]="获取希里克斯的塔楼钥匙是部落盗贼加入破碎手氏族的一项关键试炼，要求必须精通潜行和开锁技能。",["faction:Horde"]="这把钥匙是抵制荆棘谷地精的剥削行为以及威胁贫瘠之地北部的化学实验的一件重要战利品。"},sec={{t="潜行者的试炼",b="淤泥沼泽以北的荆棘谷地精行动安保严密，其核心是一座由总工头普兹克·加里维克斯监管的孤立瞭望塔。在布满地精雇佣兵的营地外，工头希里克斯随身携带着破碎手特工被指示偷取并保存的塔楼钥匙。对于从奥格瑞玛开展行动的破碎手盗贼网络来说，获取这把钥匙并非蛮力所能及；战地特工必须潜入营地而不被发现，并干净利落地偷走工头的口袋，在攀登进入有毒的上层之前证明他们对潜行技巧的掌握。"}},faq={{q="我在哪里能找到工头希里克斯？",a="工头希里克斯驻扎在贫瘠之地东北部，淤泥沼泽正北方的荆棘谷地精塔楼外。",al={"希里克斯位置","工头希里克斯在哪里","寻找希里克斯"}},{q="我能通过杀死工头希里克斯来获取钥匙吗？",a="不能。钥匙无法从他的尸体上拾取。特工必须使用潜行，并在他活着时直接从他身上偷取，才能获得该物品。",al={"希里克斯钥匙掉落","我能杀掉希里克斯吗","拾取希里克斯的钥匙"}},{q="谁需要这把钥匙？",a="这把钥匙是由破碎手联络人布置的任务目标，需要交付给驻扎在奥格瑞玛阴影中的盗贼训练师申苏尔。",al={"谁想要这把钥匙","上交希里克斯的钥匙","希里克斯的塔楼钥匙任务"}},{q="这把钥匙有什么用？",a="这把钥匙象征着已潜入淤泥沼泽附近的荆棘谷地精塔楼，并需要连同加里维克斯的头颅和赞吉尔的改良药剂一起上交给破碎手。",al={"希里克斯的钥匙能开什么","希里克斯的钥匙用途","使用塔楼钥匙"}}},fp="19,182,18.458.0,32.115.0,48.103.0,22.99.0,25.210.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="银色清晨号的保险箱",s="银色清晨号的保险箱是一个坚固的箱子，静静地躺在黑海岸外海银色清晨号沉船的残骸之中。它里面装着那艘船已故船长的私人物品和航海日志，这些东西是在遭遇沿海鱼人伏击时遗失的。",h="银色清晨号的保险箱是一个坚固的箱子，静静地躺在黑海岸外海银色清晨号沉船的残骸之中。它里面装着那艘船已故船长的私人物品和航海日志，这些东西是在遭遇沿海鱼人伏击时遗失的。",kw={"奥伯丁","黑海岸","高尔博德·钢手","保险箱","鱼人","沉船","银色清晨号"},ang={["race:Dwarf"]="高尔博德·钢手承担起让牺牲船长获得尊严，并将其遗物归还给幸存船友的责任。",["race:NightElf"]="这个保险箱保存了一位卡多雷船长的最终手稿和遗物，他在卡利姆多北部海岸附近保卫船只时牺牲。"},sec={{t="沉没的残骸",b="银色清晨号在航行前往奥伯丁港口的途中遭遇了灾难。沿海鱼人蜂拥而至，袭击了这艘船，将其拖入了港口以北黑暗的海浪之中。船长在袭击中丧生，沉船则留在了波涛之下，成为了被这些生物占据的凄惨纪念碑。在淹没的船体中，依然存放着船长的个人保险箱，里面装有船只的航海日志和私人财物。找回这些遗物，能为岸上幸存的船员带来最后的慰藉。"}},faq={{q="银色清晨号的保险箱位于何处？",a="这个保险箱位于银色清晨号的沉没残骸内，那是一艘倾覆的船只，沉在奥伯丁以北、黑海岸外海的海底。",al={"保险箱位置","银色清晨号保险箱在哪里","银色清晨号残骸"}},{q="银色清晨号发生了什么事？",a="当银色清晨号在海上航行前往奥伯丁时，遭到了当地鱼人的伏击。船只被攻陷、损毁并沉入波涛之中，船长也因此丧生。",al={"银色清晨号为何沉没","银色清晨号背景故事","船只如何沉没"}},{q="保险箱里装有什么？",a="这个箱子里装有银色清晨号船长的私人物品和航海日志，它们在深海中被保存了下来。",al={"银色清晨号内部物品","保险箱里有什么"}},{q="谁在寻找这个保险箱？",a="驻扎在奥伯丁的矮人高尔博德·钢手，请求勇敢的游泳者潜入残骸中找回保险箱，以便已故船长的幸存船员能妥善地纪念他们。",al={"谁需要保险箱","谁给予任务","上交保险箱"}}},fp="24,165,15.379.0,46.143.0,36.151.0,27.76.0,27.167.0"}
P.entries["item:silvery-spinnerets"] = {n="银色丝囊",s="银色丝囊采集自泰达希尔北部的巨型蜘蛛萨丝拉。这些丝囊曾经用来编织捕捉治愈性夜露的蛛网，供Temple of the Moon使用；现在，艾露恩的女祭司们正寻求它们，旨在通过神圣的重生仪式来纪念这只倒下的生物的灵魂。",h="银色丝囊采集自泰达希尔北部的巨型蜘蛛萨丝拉。这些丝囊曾经用来编织捕捉治愈性夜露的蛛网，供Temple of the Moon使用；现在，艾露恩的女祭司们正寻求它们，旨在通过神圣的重生仪式来纪念这只倒下的生物的灵魂。",kw={"萨丝拉","女祭司艾茉拉","萨丝拉的祭品","银色丝囊","月之泪","temple of the moon","涌泉湖"},ang={["class:Priest"]="对于艾露恩的仆人们来说，回收这些丝囊并非一份除害合同，而是一场神圣的葬礼仪式，旨在请求月亮母亲为这只生物进行救赎。",["race:NightElf"]="萨丝拉的悲剧结局给卡多雷敲响了警钟，提醒他们即使是受艾露恩钟爱的生物，也难逃正在侵蚀泰达希尔的蔓延苦难。"},sec={{t="神圣蛛网与腐蚀",b="萨丝拉曾经被视为艾露恩的宠儿，她因在涌泉湖附近的月光下编织闪烁的蛛网而闻名。她那银色的丝线能够汇聚夜间的薄雾，形成珍贵的治愈之露，深受达纳苏斯的The Sisterhood of Elune喜爱。不幸的是，在泰达希尔枝叶间蔓延的腐蚀并没有放过她。萨丝拉陷入了狂暴的疯狂，对自己和周围森林的族群构成了威胁。女祭司艾茉拉请求旅行者终结这只蜘蛛的痛苦，并回收她的丝囊作为一种仁慈的行为，为这位大枝叶上受人尊敬的居民画上句号。"},{t="重生的祭品",b="回收的丝囊并非仅仅是为了当作战利品或制作材料。相反，The Sisterhood of Elune会将它们直接呈献给Temple of the Moon中央喷泉处的月亮女神。通过这种被称为萨丝拉的祭品的圣化仪式，女祭司们祈祷艾露恩能接纳这只生物的灵魂，净化侵蚀了她肉体的疯狂，并赐予她在重生中获得平静。"}},faq={{q="在哪里可以获得银色丝囊？",a="它们是从萨丝拉身上获取的，这是一只出没于泰达希尔北部边界，涌泉湖附近的巨型蜘蛛。",al={"银色丝囊在哪里","银色丝囊掉落","谁掉落银色丝囊"}},{q="女祭司艾茉拉为什么要这些丝囊？",a="女祭司艾茉拉寻求将它们作为神圣的祭品献给艾露恩。这项仪式旨在纪念萨丝拉曾经的纯洁，并祈求女神净化这只野兽的灵魂，赐予她安宁与重生。",al={"艾茉拉为什么需要丝囊","月之泪的用途"}},{q="萨丝拉的蛛网为什么很特别？",a="萨丝拉编织的闪光银丝能够在月光下捕获夜晚的薄雾。从她蛛网上收集的露水拥有强大的恢复魔法，The Sisterhood of Elune将其储存在Temple of the Moon中用于治疗。",al={"萨丝拉的蛛网","萨丝拉做了什么"}},{q="如果萨丝拉是神圣的，为什么要杀死她？",a="她与泰达希尔其他被腐蚀的野生动物一样，陷入了无法治愈的疯狂。她的攻击性对森林构成了威胁，也危及了她的后代，因此女祭司们认为杀死她是一种悲伤的仁慈之举。",al={"为什么要杀萨丝拉","萨丝拉为什么会发疯"}}},fp="18,256,29.454.0,23.309.1,40.105.0,47.200.0,37.229.0,46.219.0"}
P.entries["item:simple-memorandum"] = {n="简易备忘录",s="《简易备忘录》是一份下发给在寒脊山谷训练的诺莫瑞根新手战士的官方通知。这是一份简短的侏儒指令，要求新兵向安威玛尔的战士训练师斯兰·库尔曼报到，为夺回诺莫瑞根的战争做好准备。",h="《简易备忘录》是一份下发给在寒脊山谷训练的诺莫瑞根新手战士的官方通知。这是一份简短的侏儒指令，要求新兵向安威玛尔的战士训练师斯兰·库尔曼报到，为夺回诺莫瑞根的战争做好准备。",kw={"安威玛尔","寒脊山谷","丹莫罗","诺莫瑞根","简易备忘录","斯兰·库尔曼","战士训练"},ang={["class:Warrior"]="这张纸条代表了战士从初步的小规模冲突转向在安威玛尔接受斯兰·库尔曼的正规战斗指导的第一步。",["race:Gnome"]="对于侏儒流亡者来说，这份备忘录提醒着他们共同的目标：与他们的矮人盟友并肩磨练战斗技能，为最终解放诺莫瑞根做好准备。"},sec={{t="前往安威玛尔的传唤",b="寒脊山谷的新手冒险者在对抗当地野生动物和穴居人威胁并证明自己的实力时，经常会收到介绍信。对于年轻的侏儒战士来说，这份备忘录是一份正式命令，要求他们向安威玛尔的驻地战士训练师斯兰·库尔曼报到。矮人老兵们深知，尽管侏儒可能依赖智慧和机械装置，但夺回诺莫瑞根需要纯粹的体能决心和战斗纪律。这份备忘录指示持信人放下初步任务，寻求关于战争艺术的个性化指导。"}},faq={{q="什么是《简易备忘录》？",a="这是一份下发给在寒脊山谷工作的侏儒新手战士的书面信息，指示他们向安威玛尔内的矮人战士训练师报到。",al={"简易备忘录","这是什么纸条","备忘录物品"}},{q="谁写了《简易备忘录》？",a="上面没有签名。斯登·粗臂猜测它来自斯兰·库尔曼，但文中提到了夺回我们的家园诺莫瑞根，所以这是一份侏儒指令，命令你向安威玛尔的矮人战士训练师斯兰报到。",al={"谁写了备忘录","谁发送了纸条","简易备忘录的作者"}},{q="阅读《简易备忘录》后会发生什么？",a="一旦你阅读了这份文件，就可以把它带给安威玛尔内的斯兰·库尔曼。他会认可你收复失地的决心，并为你提供基础战士技能的训练。",al={"我该如何处理备忘录","我该把它带到哪里","上交简易备忘录"}},{q="为什么是矮人在训练侏儒战士？",a="诺莫瑞根陷落后，侏儒难民在铁炉堡和安威玛尔的庇护下定居。像斯兰·库尔曼这样的矮人老兵已承诺提供他们的军事专长，以帮助流亡的盟友进行训练，并最终夺回他们那座被辐射污染的城市。",al={"为什么斯兰要训练侏儒","矮人训练侏儒"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="简易符文",s="简易符文是一块刻有铭文的石制信物，交给在寒脊山谷训练的矮人新兵。它充当战士训练师斯兰·库尔曼的传唤令，指引新兵前往安威玛尔接受指导。",h="简易符文是一块刻有铭文的石制信物，交给在寒脊山谷训练的矮人新兵。它充当战士训练师斯兰·库尔曼的传唤令，指引新兵前往安威玛尔接受指导。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人符文","简易符文","斯兰·库尔曼","战士训练"},ang={["class:Warrior"]="对于矮人战士来说，这块刻有铭文的石头标志着他们在资深教官斯兰·库尔曼指导下进行正式军事训练的第一步。",["race:Dwarf"]="斯兰·库尔曼的符文向年轻的矮人承诺了战斗的基础：斧柄的握法、护甲的重量以及真实战斗中流下的汗水。"},sec={{t="战火的召唤",b="简易符文上刻着基础的战斗标记，会被分发给那些已经开始清理寒脊山谷周围威胁的有潜质的新兵。它并非魔法护身符，而是驻扎在安威玛尔的战士训练师斯兰·库尔曼发出的正式传唤石。年轻的战士在阅读上面的铭文指引后，应当直接向斯兰报到，以学习基本的战斗技巧，并听取关于在丹莫罗险恶荒野中生存的实用建议。"}},faq={{q="简易符文有什么用途？",a="简易符文是交给寒脊山谷的见习战士的教学石板。阅读它可以指引新兵前往安威玛尔，向斯兰·库尔曼报到进行正式训练。",al={"简易符文的使用","符文有什么作用","简易符文任务物品"}},{q="简易符文是谁寄出的？",a="它由驻扎在安威玛尔的矮人战士训练师斯兰·库尔曼寄出，他会留意在山谷周围协助清理威胁的有潜质的战士。",al={"谁写的符文","谁给了我简易符文","符文的发送者"}},{q="我该把简易符文带去哪里？",a="把它带到位于寒脊山谷中心地带的安威玛尔大熔炉大厅，交给斯兰·库尔曼。",al={"我该去哪里","符文上交","斯兰·库尔曼的位置"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="简易符记",s="“简易符记”是授予幽影谷暗夜精灵新手战士的一种普通训练信物。作为战士训练师奥莉希亚的召集令，它标志着一名年轻战士正式投身于泰达希尔的武装防御事业。",h="“简易符记”是授予幽影谷暗夜精灵新手战士的一种普通训练信物。作为战士训练师奥莉希亚的召集令，它标志着一名年轻战士正式投身于泰达希尔的武装防御事业。",kw={"奥莉希亚","ilthalaine","卡多雷战士","幽影谷","简易符记","泰达希尔","战士训练"},ang={["class:Warrior"]="对于卡多雷战士来说，这枚简单的信物是你的第一份凭证，它将引领你接触保卫泰达希尔所需的武艺传统。",["race:NightElf"]="这枚符记凸显了卡多雷所面临的紧迫局势，像奥莉希亚这样的训练师正在招募任何有能力的人手，以遏制世界之树枝叶间日益增长的腐蚀。"},sec={{t="武装的召唤",b="在幽影谷那受庇护的树荫下，年轻的暗夜精灵们在管理员伊尔萨莱恩的指引下寻找人生的使命。对于羽翼未丰的战士们，伊尔萨莱恩会转交一枚由奥莉希亚派出的信使送来的简易符记。这枚符记上刻有指引新兵前往报到的铭文，象征着在这个世界之树多事之秋，正规军事训练的开始。"},{t="防卫的重担",b="当交给奥莉希亚时，这枚符记将开启一段关于卡多雷目前紧迫局势的对话。泰达希尔近期的生长、森林野兽所遭受的腐蚀，以及对菲拉斯等遥远土地的重新发现，使暗夜精灵的守卫力量捉襟见肘。符记本身并非强力的神器，而是一份实用的凭证，象征着新兵已被接纳为守卫者的一员，肩负起保护族人免受新兴威胁侵害的重任。"}},faq={{q="什么是简易符记？",a="这是一枚由幽影谷的管理员伊尔萨莱恩交给暗夜精灵新手战士的入门刻印信物。它指示持有者前往奥莉希亚处进行正式的战士训练。",al={"简易符记物品","简易符记有什么用","这枚符记是什么"}},{q="是谁发送了简易符记？",a="这枚符记由一名信使代表奥莉希亚发送，她是幽影谷当地的战士训练师，希望能开始训练新的战士以保卫泰达希尔。",al={"谁制造了这枚符记","谁发送了简易符记"}},{q="我该怎么处理它？",a="阅读上面的铭文，并将其交给位于幽影谷奥达希尔底部的奥莉希亚，即可开始你的战士训练。",al={"简易符记在哪里上交","谁收走简易符记"}},{q="这枚符记赋予什么特殊能力吗？",a="不。它只是一份书面通知和凭证，旨在向导师介绍有志成为战士的新手。",al={"符记力量","简易符记属性"}}},fp="12,143,17.360.0,21.381.0,25.193.0,27.143.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="普通石板",s="普通石板是一封交给抵达试炼谷的暗矛巨魔新手战士的公函。由高内克派发，它指引这些刚出道的战斗人员去向当地的战士训练师弗朗恩报到。",h="普通石板是一封交给抵达试炼谷的暗矛巨魔新手战士的公函。由高内克派发，它指引这些刚出道的战斗人员去向当地的战士训练师弗朗恩报到。",kw={"暗矛","杜隆塔尔","弗朗恩","高内克","普通石板","大兽穴","试炼谷","战士训练师"},ang={["class:Warrior"]="这块石板标志着巨魔战士与弗朗恩的正式会面，开启了他们在部落内的战斗指导。",["race:Troll"]="对于在杜隆塔尔与兽人并肩开辟家园的暗矛巨魔来说，收到这份征召意味着他们有责任去加强前线阵列。"},sec={{t="战斗召唤",b="在试炼谷那严酷的红色土地上，新兵们很快就会投入工作。对于寻求战士之道的年轻巨魔来说，高内克会递给他们这块简单的石板或羊皮纸。它由巨魔塔斯尔所写，收件人为大兽穴附近驻守的军械大师弗朗恩，作为在杜隆塔尔进行军事训练的正式介绍信。它敦促新兵挺身而出，展现自己并证明他们愿意在部落的旗帜下挥舞武器。"}},faq={{q="普通石板是什么？",a="这是一封由高内克发给试炼谷中有抱负的巨魔战士的入门书信。它要求他们阅读信件并寻找弗朗恩进行专业的战斗训练。",al={"普通石板","这块石板是什么","巨魔战士石板"}},{q="谁发送了这块石板？",a="这封信由巨魔塔斯尔署名，他将新兵引荐给驻扎在试炼谷大兽穴外的战士训练师弗朗恩。",al={"谁发送了普通石板","谁写了这块石板","石板发送者"}},{q="我要把石板带到哪里？",a="把它交给弗朗恩，他就在试炼谷大兽穴入口外的阴凉处休息。",al={"我该把普通石板给谁","石板要带到哪里","弗朗恩位置"}},{q="谁会收到这块石板？",a="普通石板是专门提供给在试炼谷开始试炼的巨魔战士的。",al={"任何人都能获得普通石板吗","哪个职业能获得普通石板"}}},fp="13,84,19.272.0,26.118.0,21.121.0,27.83.0,25.102.0"}
P.entries["item:singed-scale"] = {n="烧焦的鳞片",s="烧焦的鳞片是从杜隆塔尔带电的雷霆蜥蜴身上采集到的，经过电击硬化、烧焦的甲片。对于努力掌握防御战斗艺术的年轻部落战士来说，获取这些鳞片是一种成人礼。",h="烧焦的鳞片是从杜隆塔尔带电的雷霆蜥蜴身上采集到的，经过电击硬化、烧焦的甲片。对于努力掌握防御战斗艺术的年轻部落战士来说，获取这些鳞片是一种成人礼。",kw={"前沿哨所","闪电皮兽","防御之道","烧焦的鳞片","雷霆蜥蜴","雷霆山","犹塞克"},ang={["class:Warrior"]="对于成长中的战士来说，将这些鳞片带给犹塞克，标志着他们在理解守护之道和学习为部落筑起一道坚不可摧的盾牌方面迈出了核心的一步。",["faction:Horde"]="前沿哨所进行的试炼确保了守卫杜隆塔尔和贫瘠之地边境的卫兵和先锋拥有坚韧不拔的体魄。"},sec={{t="耐力考验",b="对于部落的先锋老兵来说，真正的战士不仅仅是用斧头饮血，更在于他们能够承受多少打击来保护盟友。在杜隆塔尔西部的雷霆山干旱峡谷中，闪电皮兽和雷霆蜥蜴身上噼啪作响，蕴含着不稳定的风暴能量。狩猎这些野兽需要战士忍受无情的电击和沉重的物理打击。从它们皮上撕下的漆黑、焦灼的鳞片，是战士抵御严酷攻击并能在弱者倒下的地方屹立不倒的有力证明。"},{t="盾牌之道",b="在位于杜隆塔尔和贫瘠之地边界的前沿哨所，老兵犹塞克要求初学者在传授知识前必须交出五片这样的鳞片。在犹塞克眼中，初学者必须具备内在的体魄，才能理解姿态和战术防御的微妙准则。呈上这些鳞片证明了战士具备足够的坚毅，能将厚皮、重甲和精算的步法结合起来，成为部落敌人面前一道坚不可摧的墙。"}},faq={{q="烧焦的鳞片有什么用？",a="烧焦的鳞片是战斗耐力的证明。战士训练师犹塞克需要五片鳞片来验证初学者是否具备学习高级防御技术所需的体魄。",al={"烧焦的鳞片用途","谁需要烧焦的鳞片","烧焦的鳞片任务"}},{q="在哪里可以找到烧焦的鳞片？",a="它们采集自生活在雷霆山的雷霆蜥蜴和闪电皮兽，那里是杜隆塔尔西部的一处峡谷，与贫瘠之地隔河相望。",al={"烧焦的鳞片位置","在哪获取烧焦的鳞片","如何获得烧焦的鳞片"}},{q="为什么鳞片会被烧焦？",a="雷霆蜥蜴天生就能在体内引导闪电和雷暴。持续不断的元素能量劈啪作响，烧焦并熏黑了它们的外皮，使鳞片呈现出烧焦的质感。",al={"为什么是烧焦的","鳞片为什么会被烧焦"}},{q="犹塞克是谁？他为什么在意这些鳞片？",a="犹塞克是一位驻扎在贫瘠之地东部前沿哨所的老兵。他负责训练部落的年轻战士进行防御作战，但坚持要求他们在接受指导前，必须先证明自己面对致命野兽时的原始韧性。",al={"犹塞克是谁","犹塞克"}}},fp="12,171,19.382.0,21.397.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:skeleton-finger"] = {n="骷髅的手指",s="一根从徘徊在暮色森林受诅咒的树林和墓地中的行尸走肉身上搜刮来的断裂骨指。夜色镇的伊瓦夫人收集这些可怕的残肢，并配以食尸鬼獠牙和蜘蛛毒液来制作防护护身符。",h="一根从徘徊在暮色森林受诅咒的树林和墓地中的行尸走肉身上搜刮来的断裂骨指。夜色镇的伊瓦夫人收集这些可怕的残肢，并配以食尸鬼獠牙和蜘蛛毒液来制作防护护身符。",kw={"夜色镇","暮色森林","食尸鬼的牙齿","伊瓦夫人","骷髅突袭者","骷髅的手指","惩罚图腾"},ang={["class:Mage"]="研究民间占卜的法师会发现，伊瓦夫人将骷髅指骨和天然毒素转化为报复性附魔的方法，是某种民间巫术与顺势魔法的独特融合。",["class:Paladin"]="圣骑士可能会对亵渎骷髅遗骸并携带其断肢感到战栗，但在暮色森林这片可怕的阴影中，将邪恶之骨重新利用来保护生者是一种残酷的必要手段。"},sec={{t="不安者的遗骨",b="暮色森林那片受诅咒的树林被不安的死者遗骸所淹没，从骷髅突袭者和战士，到死灵法师和恶魔应有尽有。虽然普通旅人会避免触碰这些复活死者的污秽遗骸，但算命师和神秘学家却非常看重它们冰冷的本质。夜色镇的驻地先知伊瓦夫人收集这些骷髅的手指，将它们残留的死灵能量束缚进一种被称为惩罚图腾的报复性魔法结界中。"}},faq={{q="哪些生物会掉落骷髅的手指？",a="骷髅的手指是从暮色森林各处发现的各种骷髅不死生物身上采集到的，包括骷髅突袭者、治疗者、守卫者、战士、恐怖魔、恶魔以及骷髅法师。",al={"骷髅的手指哪里掉落","什么怪掉落骷髅的手指","骷髅的手指来源"}},{q="在暮色森林里谁需要骷髅的手指？",a="居住在夜色镇的占卜师伊瓦夫人，需要它们作为附魔防护结界所需的仪式组件的一部分。",al={"谁需要骷髅的手指","骷髅的手指任务发布者","骷髅的手指有什么用"}},{q="什么是惩罚图腾？",a="这是一种由伊瓦夫人利用骷髅的手指、食尸鬼獠牙和蜘蛛毒液制作的附魔结界。她将这些黑暗能量编织成一种光环，旨在对任何试图攻击携带者的人进行报复性的伤害。",al={"惩罚图腾的作用","伊瓦夫人制作什么"}},{q="为什么伊瓦夫人需要不死生物的遗骸来制作防护符咒？",a="伊瓦夫人的仪式引导了当地怪物身上残留的腐化与攻击性。通过将暮色森林的骷髅、食尸鬼和毒虫的暴力本质结合在一起，她将它们残留的恶意转化为一种惩罚敌意攻击者的结界。",al={"为何使用骨头魔法","为什么图腾需要骷髅的手指"}}},fx={["7c732e26"]={q="骷髅的手指是什么？",a="骷髅的手指是从暮色森林荒芜的树林和墓穴中游荡的骷髅怪物身上截下的干枯骨骼碎片。该地区受到死灵污染，这些骨指因此得以保存下来，仍残留着让亡灵躁动不安、继续活动的黑暗魔法气息。",al={"骷髅的手指是什么","辨认骷髅的手指"}},a7de6990={q="骷髅的手指来自哪里？",a="这些手指来自在暮色森林闹鬼的墓地和遗迹中被唤起的骷髅遗骸。它们并非人工制作，而是直接从活动的尸体上取下，例如骷髅战士、骷髅魔、骷髅看守和骷髅掠夺者。这些亡者在树林中穿行，受到一种神秘而不断蔓延的污染侵蚀，才得以活动。",al={"骷髅的手指来源","骷髅的手指从哪里来","骷髅的手指是谁制作的"}}},fp="15,175,21.379.0,38.121.0,39.80.0,32.189.0,63.206.0"}
P.entries["item:skin-of-sweet-rum"] = {n="一袋蜂蜜酒",s="一袋蜂蜜酒是一种特制的烈酒，产自闪金镇的Lion's Pride Inn。湖畔镇的酒吧老板丹尼尔急需这种酒来维持他酒馆的库存，因为黑石兽人切断了赤脊山的常规贸易路线。",h="一袋蜂蜜酒是一种特制的烈酒，产自闪金镇的Lion's Pride Inn。湖畔镇的酒吧老板丹尼尔急需这种酒来维持他酒馆的库存，因为黑石兽人切断了赤脊山的常规贸易路线。",kw={"酒吧老板丹尼尔","干涸的时刻","闪金镇","湖畔镇","lion's pride inn","一袋蜂蜜酒","蜂蜜酒"},ang={["faction:Alliance"]="采购这种酒凸显了黑石兽人的入侵给保卫暴风城王国东部边界的小型定居点带来的后勤压力。"},sec={{t="湖畔镇的稀有慰藉",b="在饱受战争摧残的湖畔镇，酒馆的补给正处于极度匮乏的状态。黑石兽人的入侵阻塞了通往赤脊山的补给道路，酒吧老板丹尼尔不得不竭力满足那些处于困境中的城镇卫兵和难民的饮酒需求。为了补充他那空空如也的货架，丹尼尔派遣旅行者穿过王国去搜集各地的特产，其中包括一个装满了闪金镇Lion's Pride Inn酿制和供应的独特甜味朗姆酒的皮囊。"}},faq={{q="我在哪里可以找到一袋蜂蜜酒？",a="一袋蜂蜜酒可以直接从位于艾尔文森林闪金镇的Lion's Pride Inn的旅店老板或酒吧老板那里购买。",al={"蜂蜜酒位置","哪里购买蜂蜜酒","谁出售蜂蜜酒"}},{q="谁需要这种酒？",a="湖畔镇酒馆的老板酒吧老板丹尼尔在任务“干涸的时刻”中，需要一袋蜂蜜酒以及其他几种地方特产酿造的酒来补充他匮乏的库存。",al={"谁需要蜂蜜酒","蜂蜜酒交任务","蜂蜜酒任务"}},{q="为什么湖畔镇的酒会告罄？",a="赤脊山黑石兽人入侵的突然升级切断了贸易路线，延误了运往镇上的补给。由于普通的商队马车无法安全通行，当地的库存几乎已经见底。",al={"为什么他们没有酒了","为什么湖畔镇干涸","干涸的时刻原因"}},{q="除了这种酒之外，还需要哪些其他的烈酒？",a="除了来自闪金镇的一袋蜂蜜酒之外，酒吧老板丹尼尔还需要来自西部荒野的一桶Thunderbrew Lager、来自暴风城的一桶葡萄酒，以及来自夜色镇的一瓶月光酒。",al={"干涸的时刻酒类","丹尼尔的酒单","需要的其他酒"}}},fx={efbd5e13={q="一袋蜂蜜酒是什么？",a="一袋蜂蜜酒是一个装满甜酒的皮水囊，在艾尔文森林的闪金镇出售。它是南部艾泽拉斯人类王国珍视的几种地方特色烈酒之一。",al={"蜂蜜酒是什么","一袋蜂蜜酒的信息","蜂蜜酒"}}},fp="17,122,28.316.0,37.117.0,19.142.0,39.154.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="粘稠的血液",s="粘稠的血液是从银松森林粘丝洞内的蛛形纲生物身上采集而来的一种炼金试剂。它是皇家药剂师学会研究旨在消灭天灾军团和人类的新瘟疫的关键毒性成分。",h="粘稠的血液是从银松森林粘丝洞内的蛛形纲生物身上采集而来的一种炼金试剂。它是皇家药剂师学会研究旨在消灭天灾军团和人类的新瘟疫的关键毒性成分。",kw={"法拉尼尔","新瘟疫","伦弗利尔","皇家药剂师学会","银松森林","粘稠的血液","粘丝洞","蛛网蛛"},ang={["faction:Horde"]="被遗忘者的药剂师们欢迎这些原材料，以保卫洛丹伦，并用他们自己制造的武器与天灾军团作战。",["race:Undead"]="提供粘稠的血液可以直接帮助希尔瓦娜斯女王和皇家药剂师学会研制针对阿尔萨斯和活人文明的终极生物武器。"},sec={{t="一种有毒的蒸馏物",b="这种有毒的血淋巴从潜伏者、突袭者以及它们的巢母克雷丝·影纱身上采集而来，因其剧毒特性而受到被遗忘者炼金术士的青睐。药剂师伦弗利尔发现，将其与从灰熊心脏中提取的毒素一同提炼后，这种血液便构成了一种极其致命的药剂的基础。流体中的化合物表现出严重的污染性，使其成为药剂师协会化学实验的理想生物催化剂。"},{t="推动新瘟疫",b="在幽暗城大药剂师法拉尼尔的指导下，皇家药剂师学会收集像粘稠的血液这样的试剂，以研制出具有毁灭性的新瘟疫。面对压倒性的天灾军团大军和敌对的人类残党，被遗忘者寻求通过生物战来获取优势。法拉尼尔分析了这种血液的毒性效力，旨在设计出一种足以消灭亡灵和活体血肉的强效传染病。"}},faq={{q="粘稠的血液有什么用途？",a="皇家药剂师学会利用粘稠的血液来研制被遗忘者的新瘟疫。当它与从熊心中提取的毒素混合时，会产生一种不稳定的混合物，大药剂师法拉尼尔正在研究这种混合物，以消灭天灾军团的亡灵和活着的人类。",al={"粘稠的血液用途","为什么要收集蜘蛛血液","法拉尼尔用粘稠的血液做什么"}},{q="粘稠的血液在哪里可以找到？",a="它采集自粘丝洞内及周边的蛛网蛛尸体——包括潜伏者、突袭者和克雷丝·影纱——这是一个位于银松森林西北部，布满蛛网、阴沉灰暗的林地。",al={"去哪里获取粘稠的血液","粘稠的血液位置","谁掉落粘稠的血液"}},{q="谁需要这些样本？",a="位于银松森林瑟伯切尔的药剂师伦弗利尔委托收集这些血液，并指示冒险者将采集到的流体直接送往幽暗城药剂师区的药剂师协会找大药剂师法拉尼尔。",al={"谁需要粘稠的血液","粘稠的血液任务发布者"}},{q="为什么被遗忘者需要当地野兽的毒液？",a="皇家药剂师学会不断从洛丹伦被腐蚀的动物群中分离出天然毒素。银松森林巨型蛛形纲生物天生的毒液提供了原始的生物病原体，可以被浓缩并制成合成瘟疫武器。",al={"为什么需要蜘蛛毒液","药剂师野兽研究"}}},fp="16,227,18.318.0,22.341.0,34.245.0,32.183.0,27.173.0,49.221.0"}
P.entries["item:sleepers-key"] = {n="沉睡者的钥匙",s="沉睡者的钥匙是由暗夜精灵德鲁伊所制作的三把附魔钥匙之一，用于封印他们位于石爪峰猛禽洞穴内的神圣宝库。它被安全地保存在一个需要用守门人的钥匙开启的隐秘储藏箱中，是打开德鲁伊宝藏所需的三把钥匙之一。",h="沉睡者的钥匙是由暗夜精灵德鲁伊所制作的三把附魔钥匙之一，用于封印他们位于石爪峰猛禽洞穴内的神圣宝库。它被安全地保存在一个需要用守门人的钥匙开启的隐秘储藏箱中，是打开德鲁伊宝藏所需的三把钥匙之一。",kw={"守门人的钥匙","沉睡者储藏箱","沉睡者的钥匙","石爪峰","猛禽洞穴","猛禽洞穴宝藏","大兽穴"},ang={["class:Druid"]="猛禽洞穴的钥匙和储藏箱展示了暗夜精灵德鲁伊的多层防御体系，利用隐藏的储藏箱和带锁的机关来封印强大的遗物。",["faction:Horde"]="获取沉睡者的钥匙是深入石爪峰核心的精心策划的突袭的一部分，旨在剥离暗夜精灵的防御结界，夺取他们宝藏中封存的遗物。"},sec={{t="德鲁伊的保障",b="猛禽洞穴开凿在石爪峰的高处，是卡利姆多德鲁伊的堡垒与圣所。暗夜精灵守护者深知他们神圣的遗物和强大的宝藏可能会招致不必要的关注，因此设计了一套错综复杂的锁和隐藏储藏箱系统来保护他们的宝藏。沉睡者的钥匙就是这道防御结界的三分之一。它被放置在洞穴深处一个隐蔽的储藏箱中，只能通过入口附近隐藏的守门人的钥匙来获取。与利爪钥匙和古墓钥匙一起，沉睡者的钥匙必须被嵌入猛禽洞穴宝藏的石锁中，才能解除结界并展现其中封存的远古物品。"}},faq={{q="沉睡者的钥匙有什么用途？",a="沉睡者的钥匙与古墓钥匙和利爪钥匙一起使用，可以打开猛禽洞穴宝藏，这是一个隐藏在石爪峰大兽穴深处的受结界保护的石制宝库。",al={"沉睡者的钥匙有什么用","沉睡者的钥匙用途","猛禽洞穴宝藏钥匙"}},{q="沉睡者的钥匙是如何被锁起来的？",a="德鲁伊将其放在了猛禽洞穴西北隧道中的沉睡者储藏箱里。打开那个储藏箱需要守门人的钥匙，德鲁伊将这把钥匙藏在洞穴入口附近的一盏不起眼的灯笼里。",al={"沉睡者的钥匙在哪里","打开沉睡者储藏箱","守门人的钥匙需求"}},{q="为什么德鲁伊要用多把钥匙来隐藏他们的遗物？",a="暗夜精灵德鲁伊制作了复杂的保障措施，以确保即使洞穴遭到袭击，他们强大的物品和神圣的传家宝也不会落入敌人手中。将钥匙分散在不同的隐秘储藏箱中，确保了入侵者无法轻易掠夺他们的宝藏。",al={"为什么要这么多钥匙","猛禽洞穴防御","德鲁伊宝藏谜题"}},{q="为什么它被称为沉睡者的钥匙？",a="德鲁伊从未解释过这个名字。这把钥匙只是与沉睡者储藏箱同名，而沉睡者储藏箱就是猛禽洞穴中存放它的那个隐藏宝箱。",al={"谁是沉睡者","沉睡者的钥匙名称含义"}}},fx={["0a862a33"]={q="沉睡者的钥匙是什么？",a="沉睡者的钥匙是石爪峰暗夜精灵德鲁伊制作的三把专用钥匙之一。它藏在猛禽洞穴深处一个上锁的储物箱里，是守护德鲁伊圣物核心宝库的防护系统中不可或缺的一环。",al={"沉睡者的钥匙是什么","沉睡者的钥匙背景","关于沉睡者的钥匙"}},["8275ad63"]={q="沉睡者的钥匙从何而来？是谁制作的？",a="这把钥匙由在石爪峰建立猛禽洞穴的德鲁伊打造。为了保护强大的神器免遭入侵者染指，他们设计了一套复杂的安保方案，将钥匙锁在一个专用箱子里，名为沉睡者的储藏箱。",al={"沉睡者的钥匙是谁制作的","沉睡者的钥匙来源","沉睡者的钥匙从哪里来"}},["3884172c"]={q="为什么有人想要沉睡者的钥匙？",a="部落想要这把钥匙，以绕过德鲁伊层层设下的防御，打开猛禽洞穴宝库。它与利爪钥匙和古墓钥匙合在一起，可以开启石爪峰的石制密室，取出德鲁伊藏在其中的强大圣物。",al={"为什么要找沉睡者的钥匙","为什么需要沉睡者的钥匙","谁想要沉睡者的钥匙"}}},fp="13,147,19.564.0,35.148.0,38.200.0,56.252.0,35.141.0"}
P.entries["item:smoky-iron-ingot"] = {n="烟雾铁锭",s="烟雾铁锭是由石爪山脉狂风峭壁的狗头人熔炼出的粗加工金属锭。兽人护甲匠非常看重这种锭，将其视为锻造适合部落勇士穿戴的坚固锁甲的原材料。",h="烟雾铁锭是由石爪山脉狂风峭壁的狗头人熔炼出的粗加工金属锭。兽人护甲匠非常看重这种锭，将其视为锻造适合部落勇士穿戴的坚固锁甲的原材料。",kw={"残暴护甲","狗头人","烟雾铁锭","石爪山脉","萨恩格·火眼","勇士","狂风峭壁"},ang={["class:Warrior"]="对于部落勇士来说，获取这些铁锭是在石爪山脉的一次耐力考验，它们是锻造残暴链甲衫的重要材料。",["profession:Blacksmithing"]="这些铁锭粗糙的质量反映了狗头人挖掘工原始的熔炼方法，与受过训练的铁匠所采用的精炼技术形成了鲜明对比。"},sec={{t="粗糙的狗头人冶金术",b="在石爪山脉狂风峭壁那布满煤烟的隧道深处，狗头人挖掘着岩层，从矿脉中开采出未精炼的矿石，并在简陋且冒烟的炉火上进行熔炼。产出的烟雾铁锭远称不上纯净——上面覆盖着厚厚的残渣和木炭——但其密度足以保留足够的抗拉强度。"},{t="锻造残暴护甲",b="几乎失明的兽人护甲匠萨恩格·火眼，在俯瞰贫瘠之地的一处简陋营地中工作，他在为部落的精锐勇士制作护甲时，特意要求使用这种铁锭。将这种烟雾缭绕的金属与精炼铁锭、蓝铜粉以及挥发性燃素结合，便可作为锻造残暴链甲衫的坚韧核心。"}},faq={{q="烟雾铁锭从何而来？",a="烟雾铁锭由居住在石爪山脉东部狂风峭壁挖掘场和隧道中的狗头人携带，包括挖掘工、石匠、害虫、地卜师以及他们的监工。",al={"哪里能找到烟雾铁锭","烟雾铁锭位置","谁会掉落烟雾铁锭"}},{q="烟雾铁锭有什么用途？",a="响应萨恩格·火眼号召的勇士们会收集这种铁锭，这位护甲大师居住在贫瘠之地十字路口附近的山峰上。他需要十五块这种铁锭来锻造那件标志性的残暴链甲衫。",al={"烟雾铁锭用途","烟雾铁锭有什么用","残暴护甲任务物品"}},{q="为什么这些铁锭被称为“烟雾”铁锭？",a="狗头人在昏暗的隧道中采用简陋、低燃烧温度的熔炼技术。产出的金属保留了来自他们烟雾弥漫的地下熔炉中的煤烟、木炭灰和灰烬，而不是被精炼成光亮的成品。",al={"为什么它是烟雾状的","烟雾铁背景故事"}},{q="任何铁匠都能用这种铁锭锻造吗？",a="不能。烟雾铁锭是不规则、覆盖着煤灰的铁锭，无法用于标准的贸易锻造。只有像萨恩格·火眼这样的专业铁匠才知道如何将它们融入定制的战斗装备中。",al={"玩家可以锻造烟雾铁吗","烟雾铁是贸易商品吗"}}},fp="16,197,23.244.0,24.293.0,37.180.0,36.194.0,40.157.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="闷烧余烬",s="闷烧余烬是从焦炭谷的狂暴火元素身上获取的余热残留。暗夜精灵哨兵追踪着这些余烬，将其作为森林遭受破坏、火元素肆虐的地区正逐渐被平定的确凿证据。",h="闷烧余烬是从焦炭谷的狂暴火元素身上获取的余热残留。暗夜精灵哨兵追踪着这些余烬，将其作为森林遭受破坏、火元素肆虐的地区正逐渐被平定的确凿证据。",kw={"燃烧毁灭者","燃烧破坏者","焦炭谷","狂暴灵魂","凯拉·影矛","流浪烈焰之灵","闷烧余烬","石爪山脉","荆棘谷地精"},ang={["class:Druid"]="德鲁伊将这些余烬视为自然因工业贪婪而失衡的悲剧证明，未受束缚的元素之怒阻碍了被灰烬覆盖的土壤重新焕发生机。",["race:NightElf"]="对于暗夜精灵来说，焦炭谷陷入火海是卡利姆多身上一道令人心碎的伤疤。收集这些余烬是一种庄严的职责，旨在清除外来的亵渎，让这片土地在艾露恩的注视下重归宁静。"},sec={{t="焦炭谷的残留物",b="荆棘谷地精的无情砍伐和工业破坏撕裂了焦炭谷，使森林陷入火海，并释放出深埋地底的毁灭性力量。随之而来的是活体火元素——燃烧破坏者、燃烧毁灭者和游荡的流浪烈焰之灵，它们涌遍了整个焦黑的盆地。这些闷烧余烬是火元素被熄灭后留下的灰烬核心，证明了山谷中横行的火势正在被系统性地扑灭。"}},faq={{q="闷烧余烬从何而来？",a="闷烧余烬是从石爪山脉南部焦炭谷中出没的火元素身上收集的，包括燃烧破坏者、燃烧毁灭者和流浪烈焰之灵。",al={"哪里可以找到闷烧余烬","谁掉落闷烧余烬","闷烧余烬来源"}},{q="为什么凯拉·影矛想要这些余烬？",a="凯拉·影矛寻求这些余烬，作为焦炭谷中横行的火元素正被消灭的确凿证据。她相信，只要这些狂暴的灵魂依然不受控制地游荡，这片伤痕累累的土地就永远无法在艾露恩的恩泽下愈合。",al={"为什么收集闷烧余烬","凯拉·影矛余烬","狂暴灵魂目标"}},{q="是什么导致火元素出现在焦炭谷？",a="荆棘谷地精使用激进的机械和不加区别的焚烧来清理古老的森林。他们鲁莽的开采破坏了土地的稳定，挖掘并释放了敌对的烈焰与岩石元素，最终将这些地精赶了出去。",al={"焦炭谷发生了什么","为什么石爪山脉有火元素","荆棘谷地精火元素"}}},fx={["4d13fc7e"]={q="什么是闷烧余烬？",a="闷烧余烬是肆虐焦炭谷的毁灭性火元素被消灭后留下的燃烧残骸。燃烧掠夺者、游荡的火焰之灵和燃烧毁灭者等生物被击败后，这些发光的残余物仍会持续燃烧，成为它们在这片毁灭森林中横冲直撞的烈焰已被平息的实证。",al={"什么是闷烧余烬","闷烧余烬背景"}}},fp="17,160,28.398.0,37.182.0,45.206.0,62.278.0"}
P.entries["item:snellig-s-snuffbox"] = {n="斯涅利格的鼻烟盒",s="斯涅利格的鼻烟盒是人们从失落的舰队残骸中，从不得安息的亡灵大副斯涅利格身上取回的一件个人遗物。将这件小饰品带回米奈希尔港交给大副菲兹莫斯，可以证明他那受诅咒的前船员终于得到了安息。",h="斯涅利格的鼻烟盒是人们从失落的舰队残骸中，从不得安息的亡灵大副斯涅利格身上取回的一件个人遗物。将这件小饰品带回米奈希尔港交给大副菲兹莫斯，可以证明他那受诅咒的前船员终于得到了安息。",kw={"受诅咒的船员","菲兹莫斯","库尔提拉斯","失落的舰队","斯涅利格","鼻烟盒","第三舰队","湿地"},ang={["faction:Alliance"]="收回阵亡的库尔提拉斯水手的遗物并让他们受诅咒的灵魂得到安息，是为联盟的一位老海军盟友效力时的严峻职责。"},sec={{t="第三舰队的纪念品",b="当库尔提拉斯的第三舰队在湿地北岸搁浅时，其水手和军官们并没能安然辞世。由于船上隐藏的宝藏所关联的一种神秘而黑暗的力量，这些溺亡的船员化作备受折磨的灵魂和骷髅亡灵再次站了起来。其中就包括大副斯涅利格，他至今仍徘徊在最靠近海岸的那艘沉船的腐朽船舱里。即使在死后，他也紧紧抓着他的鼻烟盒——那是他在海上凡人生活的一件微小而平凡的纪念物。对于这场灾难中唯一的幸存者，大副菲兹莫斯来说，找回这件小小的遗物提供了一个切实的证据，证明他失去的船员中至少有一位已经从永恒的折磨中解脱了出来。"}},faq={{q="什么是斯涅利格的鼻烟盒？",a="这是一个小型的个人容器，曾经属于库尔提拉斯第三舰队的一名军官，大副斯涅利格。它由湿地北岸外海域沉船上的亡灵余烬所携带。",al={"什么是这个物品","斯涅利格的鼻烟盒","鼻烟盒"}},{q="我在哪里可以找到斯涅利格的鼻烟盒？",a="这只鼻烟盒是从大副斯涅利格身上掉落的，他徘徊在湿地西北部失落的舰队中，最靠近岸边的那艘沉船的船舱里。",al={"斯涅利格在哪里掉落鼻烟盒","寻找斯涅利格","大副斯涅利格的位置"}},{q="谁想要这个鼻烟盒？",a="第三舰队唯一的幸存者，大副菲兹莫斯，请求冒险者将鼻烟盒带回米奈希尔港，作为斯涅利格已经得到安息的证明。",al={"谁需要这个鼻烟盒","我应该把它交给谁","菲兹莫斯的任务"}},{q="为什么大副斯涅利格会受到诅咒？",a="据菲兹莫斯所说，第三舰队其中一艘船上藏着的一件黑暗而可怕的宝藏，导致了船队在搁浅时全军覆没，并让他们的灵魂被困在腐朽的木材中，无法安息。",al={"为什么斯涅利格是亡灵","失落的舰队诅咒","第三舰队的诅咒"}}},fp="18,187,29.637.0,27.168.0,35.152.0,24.173.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="地鼠指挥棒",s="地鼠指挥棒是一根由棘齿城的哥布林企业家麦伯克·米希瑞克斯提供的训练杆。它被用来指挥训练有素的地鼠寻找并挖出深埋在剃刀沼泽中珍贵的蓝叶薯。",h="地鼠指挥棒是一根由棘齿城的哥布林企业家麦伯克·米希瑞克斯提供的训练杆。它被用来指挥训练有素的地鼠寻找并挖出深埋在剃刀沼泽中珍贵的蓝叶薯。",kw={"蓝叶薯","指挥棒","地鼠","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","贫瘠之地"},ang={["profession:Cooking"]="虽然蓝叶薯在全球范围内被视为精致的烹饪美味，但挖掘它们需要训练有素的动物和驯兽师的棍棒，而不是标准的厨房工具。"},sec={{t="鼠辈之棒",b="蓝叶薯是艾泽拉斯各地垂涎欲滴的美味，但如果没有专门的帮助，想要找到它们几乎是不可能的。这些根茎深埋在剃刀沼泽布满荆棘的地下深处，完全隐藏在视线之外。为了在不亲自冒险进入野猪人巢穴的情况下利用这个有利可图的市场，棘齿城的商人麦伯克·米希瑞克斯训练了嗅觉敏锐的地鼠来挖掘这些块茎。地鼠指挥棒是冒险者用来指挥这些受训生物的工具，引导它们嗅出并找出五十步以内的根节点。"}},faq={{q="地鼠指挥棒有什么用？",a="该指挥棒用于命令受训的地鼠在剃刀沼泽布满荆棘的隧道中寻找隐藏的蓝叶薯。当对着被召唤出的地鼠使用时，该棒会促使生物追踪气味并挖出根节点。",al={"如何使用指挥棒","指挥棒有什么用","指挥棒用途"}},{q="在哪里可以获得地鼠指挥棒？",a="你可以在贫瘠之地棘齿城的麦伯克·米希瑞克斯作坊外直接拾取它，旁边还有一个装有受训地鼠的板条箱和一本说明书。",al={"在哪里获得指挥棒","指挥棒位置","谁提供指挥棒"}},{q="为什么麦伯克·米希瑞克斯想要蓝叶薯？",a="蓝叶薯是稀有的美味，可以卖给世界各地富有的烹饪界人士以赚取丰厚的利润。由于它们只生长在贫瘠之地深处的野猪人领地，麦伯克雇佣冒险者来采集它们。",al={"为什么需要块茎","蓝叶薯用途","为什么麦伯克需要块茎"}},{q="找到块茎后我能留下指挥棒吗？",a="不能。一旦你收集了所需的块茎，麦伯克要求你将指挥棒和运输板条箱以及收获的块茎一起带回棘齿城还给他。",al={"我能留下指挥棒吗","归还指挥棒"}}},fx={["8cc828c2"]={q="什么是地鼠指挥棒？",a="地鼠指挥棒是嗅鼻公司获得专利的驯养工具，与地精商人麦伯克·米希瑞克斯在棘齿城训练的地鼠配套使用。它专门用于指挥受训的嗅鼻地鼠，向它们发出信号，让它们挖出埋藏隐秘的美味，而普通侦察者根本无从发现这些东西。",al={"什么是指挥棒","嗅鼻指挥棒","什么是地鼠指挥棒"}},["9fdd5faa"]={q="地鼠指挥棒来自哪里？由谁制造？",a="这根指挥棒是嗅鼻公司的专利产品，公司所有者Marwig Rustbolt在《地鼠训练手册》中说明了它的用法。棘齿城的麦伯克·米希瑞克斯训练嗅鼻地鼠采集稀有美味，并将指挥棒、箱子和手册放在一起，让雇来的帮手能够妥善控制这些小家伙。",al={"谁制造了指挥棒","指挥棒的来历","指挥棒来自哪里"}},fb1cfa60={q="为什么有人想要地鼠指挥棒？",a="在剃刀沼泽的荆棘丛下，光凭肉眼根本找不到稀有的蓝叶块茎。指挥棒至关重要，因为它能驱使受训的嗅鼻地鼠嗅探五十步之外的气味并挖出块茎，然后把块茎交给麦伯克·米希瑞克斯，就能获得丰厚报酬。",al={"为什么需要这根棒子","为什么要找指挥棒","为什么要获取地鼠指挥棒"}}},fp="25,89,17.431.0,47.186.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="地鼠训练手册",s="《地鼠训练手册》是一本来自地鼠公司（Snuff Inc.）的马维格·锈栓（Marwig Rustbolt）所撰写的指导手册，放置在棘齿城的地精企业家麦伯克·米希瑞克斯身边。手册中概述了如何部署并引导受过训练的地鼠来定位埋藏在剃刀沼泽中的稀有蓝叶薯。",h="《地鼠训练手册》是一本来自地鼠公司（Snuff Inc.）的马维格·锈栓（Marwig...",kw={"蓝叶薯","地鼠","手册","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽"},ang={["profession:Cooking"]="手册概述了蓝叶薯的搜寻过程，这种地下根茎被艾泽拉斯各地的美食家和商人视为稀有美味。"},sec={{t="地精操作指南",b="这份简短的指南由地鼠公司的老板马维格·锈栓撰写，详细介绍了如何使用该公司受过训练的地鼠。这些野兽拥有敏锐的嗅觉，能够在五十步之外探测到埋在地下的蓝叶薯。手册指导探矿者使用通风箱释放地鼠，并用指挥棒引导其挖掘本能，指挥这种生物穿过剃刀沼泽中充满敌意的荆棘和野猪人隧道，以获取这种珍贵的烹饪美味。"}},faq={{q="《地鼠训练手册》的用途是什么？",a="它用于指导如何使用麦伯克·米希瑞克斯所训练的地鼠。冒险者阅读它以了解如何将动物从笼子中放出，并使用指挥棒引导它们在剃刀沼泽内定位埋藏的蓝叶薯。",al={"手册有什么用","为什么要阅读手册","手册用途"}},{q="我在哪里可以找到这本手册？",a="这本手册存放在贫瘠之地的棘齿城，就在麦伯克·米希瑞克斯附近，旁边还有采集薯块所需的特制笼子和指挥棒。",al={"手册位置","书在哪里","如何获取手册"}},{q="为什么需要地鼠来寻找蓝叶薯？",a="蓝叶薯生长在剃刀沼泽地底深处，人类几乎无法发现它们。受过训练的地鼠拥有敏锐的鼻子，能在五十步之外探测到埋藏薯块的气味。",al={"为什么要用地鼠","没有地鼠能找到薯块吗"}},{q="是谁编写了这本手册？",a="手册由地鼠公司的老板马维格·锈栓签署，他编写此手册是为了教导新主人如何喂养、遛行并用专利指挥棒指挥他们的地鼠。",al={"手册作者","谁制作了它"}}},fx={["1c231f00"]={q="什么是地鼠训练手册？",a="这是一本说明手册，与受训的嗅鼻地鼠和指挥棒配套提供。手册指导冒险者如何在剃刀沼泽的地下隧道中操控这种生物，并说明如何命令地鼠嗅出难以发现的地下蓝叶块茎。",al={"什么是地鼠训练手册","地鼠训练手册是什么","什么是这本手册"}}},fp="26,212,26.399.0,54.170.0,28.114.0,59.160.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="硝酸钠",s="硝酸钠是一种易挥发的化学试剂，由驻扎在南贫瘠之地巴尔莫丹的矮人挖掘者和守军携带。尽管铁炉堡远征军进口它是为了炸开古老的岩石，但被流放的牛头人加恩·石塔试图将其收回，以组装针对入侵者的爆炸装置。",h="硝酸钠是一种易挥发的化学试剂，由驻扎在南贫瘠之地巴尔莫丹的矮人挖掘者和守军携带。尽管铁炉堡远征军进口它是为了炸开古老的岩石，但被流放的牛头人加恩·石塔试图将其收回，以组装针对入侵者的爆炸装置。",kw={"巴尔莫丹","巴尔邓","黑炉","加恩·石塔","硝化甘油","加恩的复仇","硝酸钠","木浆"},ang={["profession:Engineering"]="工程师们很容易认出硝酸钠、硝化甘油和木浆的组合是稳定炸药的标准配方，这突显了加恩的简易爆破装置背后那不容置疑的逻辑。",["race:Tauren"]="对于牛头人来说，使用矮人的化学品是对传统方法的痛苦背离，但加恩·石塔认为，为了报复其祖居领地的毁灭，采取绝望的手段是正当的。"},sec={{t="工业爆破",b="巴尔邓探险队带着重型推土机和爆破试剂，撕开了石塔部落的祖居地。为了炸开南贫瘠之地坚硬的岩层，矮人们依赖于易挥发的化合物。硝酸钠是高级炸药中关键的稳定剂和氧化剂，通常由巴尔邓步枪手、士兵和军官在挖掘点和附近的堡垒内携带。"},{t="反击与报复",b="在部落家园遭到破坏后，加恩·石塔密切观察了入侵者并搜集了他们的工程图纸。加恩意识到常规攻击无法轻易突破戒备森严的要塞，于是密谋将矮人的工业爆破物资反过来对付他们。通过将掠夺来的硝酸钠与硝化甘油和木浆混合，这位被流放的牛头人制作了简易炸药，旨在动摇巴尔莫丹的根基。"}},faq={{q="硝酸钠在贫瘠之地有什么用途？",a="铁炉堡的矮人们将其作为炸药的化学成分，用来炸开他们挖掘场地的岩石地形。加恩·石塔打算将其与硝化甘油和木浆结合，制造强大的爆破装置来反击巴尔莫丹要塞。",al={"硝酸钠用途","硝酸钠有什么作用"}},{q="硝酸钠来自哪里？",a="它由驻扎在南贫瘠之地巴尔莫丹的矮人军队持有。士兵、步枪手、军官以及像塞瑞克·黑炉领主这样的指挥官手头都携带有这种试剂。",al={"谁掉落硝酸钠","哪里获得硝酸钠"}},{q="为什么加恩·石塔需要这种化学品？",a="加恩的祖传村庄因矮人的挖掘而毁于一旦。由于缺乏重型攻城设备，他研究了矮人的图纸以复制他们的采矿炸药，旨在用他们自己的军械拆除其防御阵地。",al={"为什么加恩想要硝酸钠","加恩·石塔爆炸物"}},{q="硝酸钠本身危险吗？",a="硝酸钠本身是一种氧化剂和化学盐，而不是即时爆炸物。当与燃料源和硝化甘油等对震动敏感的化学品适当混合时，它才会变得危险且易挥发。",al={"硝酸钠是炸药吗"}}},fp="14,161,21.312.0,25.368.1,47.189.0,36.176.0,44.224.0,39.199.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="所罗门写给夜色镇的求救信",s="《所罗门写给夜色镇的求救信》是一封由湖畔镇的所罗门镇长亲笔写给艾尔罗·埃伯洛克公爵的紧急书信。面对黑石兽人和豺狼人日益严重的威胁，这封信恳求夜色镇的领导层派遣他们的精锐民兵——守夜人，以加强湖畔镇捉襟见肘的防御。",h="《所罗门写给夜色镇的求救信》是一封由湖畔镇的所罗门镇长亲笔写给艾尔罗·埃伯洛克公爵的紧急书信。面对黑石兽人和豺狼人日益严重的威胁，这封信恳求夜色镇的领导层派遣他们的精锐民兵——守夜人，以加强湖畔镇捉襟见肘的防御。",kw={"夜色镇","暮色森林","湖畔镇","艾尔罗·埃伯洛克公爵","所罗门镇长","前往夜色镇的信使","守夜人","赤脊山","所罗门的求救信"},ang={["faction:Alliance"]="这封信展示了大联盟南部领土的破碎，各个遥远的定居点必须为了生存而在彼此间乞求援助，而暴风城却对此漠不关心。",["race:Human"]="对于人类旅行者来说，携带这份公文凸显了赤脊山边境地区和暮色森林阴影丛林共同面临的危险。"},sec={{t="一声绝望的求援",b="湖畔镇正处于被入侵的黑石兽人、豺狼人和鱼人淹没的边缘，而暴风城实际上并未派来任何官方援军。绝望之中，所罗门镇长起草了这份正式请求，递交给夜色镇的艾尔罗·埃伯洛克公爵，恳请他派遣守夜人成员北上前往赤脊山。这份文件反映了艾泽拉斯南部中央军事支援系统的严重瘫痪，迫使各个独立的人类定居点为了生存不得不彼此求助。"},{t="夜色镇的严峻困境",b="尽管所罗门的请求十分紧急，但这更凸显了湖畔镇对其邻居所遭受的真正恐怖的孤立。暮色森林本身就受到亡灵、凶猛野兽和弥漫黑暗的围困，守夜人仅仅是为了守住村庄边界就已经竭尽全力。送信的信使不但没有发现未曾启用的生力军，反而发现这里也是一座饱受困扰、完全无力抽调防御力量去援助赤脊山的城镇。"}},faq={{q="《所罗门写给夜色镇的求救信》是什么？",a="这是一封由湖畔镇的所罗门镇长写给夜色镇的艾尔罗·埃伯洛克公爵的正式书信。信中紧急请求夜色镇提供他们的民兵——守夜人的援助，以协助赤脊山抵御黑石兽人和豺狼人。",al={"所罗门写给夜色镇的信","什么是所罗门的求救信","湖畔镇写给暮色森林的信"}},{q="为什么湖畔镇要求助夜色镇而不是寻求暴风城的军事援助？",a="由于政治惰性和内部纷争，暴风城的中央政府在很大程度上未能向其边远领土提供充足的驻军。在被迫独自防守湖畔镇以抵御日益升级的入侵时，所罗门镇长转而向邻近的人类城镇寻求帮助，希望能获得盟军的支持。",al={"为什么要向夜色镇求援","为什么不找暴风城","所罗门为什么需要守夜人"}},{q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵是暮色森林中夜色镇的镇长和首席行政长官。他负责管理该镇，并协调守夜人的行动，这是一支致力于阻挡潜伏在森林中恐怖生物的民间防御力量。",al={"埃伯洛克公爵是谁","夜色镇镇长","艾尔罗公爵"}},{q="夜色镇真的能抽调守夜人去帮助湖畔镇吗？",a="不能。暮色森林深陷于自己的噩梦之中，被亡灵、野性狼人和黑暗魔法所包围。守夜人的人手仅够勉强维持夜色镇的警戒线，根本无法抽调哪怕一名战士前往赤脊山。",al={"夜色镇会帮忙吗","守夜人会来吗","埃伯洛克公爵派卫兵了吗"}}},fx={a3b7e1d6={q="所罗门写给夜色镇的求救信来自哪里？由谁写的？",a="这封信由赤脊山湖畔镇的领袖所罗门镇长亲笔写下。黑石兽人步步紧逼，而暴风城又无法派来王室援军。为了争取邻近聚居地的援助，所罗门在湖畔镇的镇政厅亲自写下了这封紧急求援信。",al={"谁写了所罗门的求救信","所罗门写给夜色镇的求救信的来历"}},["5061acb5"]={q="艾尔罗·埃伯洛克公爵为什么想要所罗门写给夜色镇的求救信？",a="艾尔罗·埃伯洛克公爵需要这封信，因为信中正式详述了湖畔镇岌岌可危的防御状况，以及所罗门镇长直接提出的军事援助请求。作为夜色镇的镇长和夜行者指挥官，埃伯洛克依靠这样的官方信件了解联盟邻邦面临的威胁，并评估自己的城镇能否抽调卫兵。",al={"为什么要递送所罗门的求救信","埃伯洛克为什么需要这封信","所罗门写给夜色镇的求救信的用途"}}},fp="27,169,24.376.0,23.242.1,36.197.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="所罗门写给西部荒野的求救信",s="所罗门写给西部荒野的求救信是一封由湖畔镇的所罗门镇长亲笔写下的紧急求援信。由于急需增援以对抗黑石兽人和豺狼人，所罗门将这份急件送往西部荒野的格里安·斯托曼手中，希望刚刚成立的人民民兵能够伸出援手，因为暴风城的皇家军队迟迟没有回应。",h="所罗门写给西部荒野的求救信是一封由湖畔镇的所罗门镇长亲笔写下的紧急求援信。由于急需增援以对抗黑石兽人和豺狼人，所罗门将这份急件送往西部荒野的格里安·斯托曼手中，希望刚刚成立的人民民兵能够伸出援手，因为暴风城的皇家军队迟迟...",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","人民民兵","赤脊山","所罗门的求救信","暴风城军队","西部荒野"},ang={["faction:Alliance"]="该文件突显了联盟腹地日益严重的行政瘫痪，偏远城镇必须依靠当地志愿者，而不是王室部队。",["race:Human"]="对于南方各省的人类来说，这一呼吁揭示了由于国王失踪和政治上的疏忽，边境土地变得何等脆弱，同时也反映了农村定居点所承受的巨大压力。"},sec={{t="绝望的求援",b="随着黑石氏族和敌对豺狼人的威胁笼罩着赤脊山，所罗门镇长发现自己孤立无援，处境岌岌可危。来自暴风城的皇家军队迟迟未能派遣正规部队来保卫该地区的边界。由于无法再等待王国首都的官方支持，所罗门写下了这封求救信，试图从正规军事体系之外招募援助。在获悉西部艾尔文森林一带正在组建一支志愿防御力量后，他直接向人民民兵求助。"},{t="跨越边境的求援",b="这封信直接寄给格里安·斯托曼，一位正在组织西部荒野边境防御的资深战士。所罗门希望斯托曼能抽调人手增援湖畔镇，直到暴风城王室最终派出正规预备队。这份文件由一名担任信使的冒险者负责递送，它反映了暴风城周边领地行政协调的脱节，当地镇长只能自行协商互助协议。"}},faq={{q="什么是所罗门写给西部荒野的求救信？",a="这是一份由湖畔镇的所罗门镇长所写的正式请愿书，请求西部荒野的格里安·斯托曼和人民民兵派遣军事增援，以协助保卫赤脊山。",al={"什么是所罗门求救信","所罗门写给西部荒野的求救信","湖畔镇 西部荒野 信件"}},{q="为什么所罗门镇长向西部荒野求助而不是向暴风城求助？",a="所罗门指出，暴风城军队似乎出现了异常情况，尽管湖畔镇的危机不断加剧，但皇家部队却迟迟未到。由于没时间等待王室的回应，所罗门转而求助于附近任何愿意帮忙的战斗力量。",al={"为什么求助西部荒野","为什么不求助暴风城","为什么要向西部荒野求援"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是人民民兵的领袖，这是一支由当地农民和定居者组成的草根防御组织，旨在保护西部荒野免受迪菲亚潜行者的侵害。",al={"谁是斯托曼","格里安·斯托曼的角色"}},{q="是什么威胁迫使所罗门发出这封信？",a="湖畔镇正面临黑石兽人的侵略，以及赤脊山各地豺狼人的劫掠，这使得当地的镇卫队已不堪重负。",al={"为什么湖畔镇身处险境","什么威胁着赤脊山"}}},fx={["7804da1c"]={q="所罗门写给西部荒野的求救信来自哪里？由谁写的？",a="这封信由身处困境的赤脊山湖畔镇镇长所罗门亲笔写下。暴风城军队未能派出承诺的援军保护他的人民，他在绝望之下亲自写下这封紧急信件，向附近的盟友求援。",al={"谁写了所罗门写给西部荒野的求救信","所罗门的求救信来自哪里","所罗门求救信的作者"}},["6d6e291d"]={q="格里安·斯托曼为什么想要所罗门写给西部荒野的求救信？",a="格里安·斯托曼领导着西部荒野的人民军，这封信让他得知湖畔镇的危急处境。所罗门希望人民军能抽调战士，增强赤脊山日渐衰弱的防御力量，同时镇民仍在等待暴风城安度因国王宫廷的消息和援军。",al={"为什么要递送所罗门的求救信","斯托曼为什么想要这封求救信","这封信有什么用"}}},fp="26,212,24.405.0,26.353.0,35.147.0,72.164.0,25.151.0,53.113.0"}
P.entries["item:soran-ruk-fragment"] = {n="索兰鲁克宝珠的碎片",s="索兰鲁克宝珠的碎片是从一颗恶魔囚禁宝珠上崩落的残片，这颗宝珠曾束缚着一名失宠的燃烧军团仆从的灵魂。尽管碎片被分散到了灰谷深处的邪教徒手中，但每一块碎片依然散发着残留的邪能。",h="索兰鲁克宝珠的碎片是从一颗恶魔囚禁宝珠上崩落的残片，这颗宝珠曾束缚着一名失宠的燃烧军团仆从的灵魂。尽管碎片被分散到了灰谷深处的邪教徒手中，但每一块碎片依然散发着残留的邪能。",kw={"黑暗深渊","杜安·卡汉","邪能","索兰鲁克宝珠","索兰鲁克","暮光侍僧"},ang={["class:Warlock"]="像索兰鲁克宝珠这样的恶魔囚禁容器是术士们梦寐以求的导管，他们试图在无需直接奴役恶魔的情况下束缚并操纵原始的邪能。"},sec={{t="破碎的囚牢",b="当燃烧军团的恶魔触怒了他们的主宰时，他们的灵魂有时会被判处终身监禁在特制的宝珠中，并作为原始力量的导管分发给邪能施法者。索兰鲁克宝珠就遭遇了这样的命运，但在其历史中的某个时刻，它碎裂了。其中一半碎成了更小的碎片，落入了潜伏在黑暗深渊水下废墟中的暮光之锤邪教徒手中，他们利用这些残留的恶魔精华进行他们自己的黑暗勾当。"},{t="在贫瘠之地的重构",b="尽管已经破碎，但每一块碎片都保留了被囚禁实体的一丝生命力。在南贫瘠之地，隐居的学者杜安·卡汉花了一辈子时间研究这些恶魔容器，他本人持有一颗类似的宝珠，即扎尔甘宝珠。通过收集三块小碎片以及保存在银松森林的那块较大的碎片，一位雄心勃勃的术士可以将这件圣物重新锻造，使其再次成为强大的工具。"}},faq={{q="什么是索兰鲁克？",a="索兰鲁克是燃烧军团的一名恶魔，因触怒了恶魔领袖而失宠。作为惩罚，它的灵魂被抽出并囚禁在一颗水晶宝珠中，作为凡人术士和法师的能量源。",al={"索兰鲁克是谁","索兰鲁克传说","索兰鲁克是恶魔吗"}},{q="这些碎片在哪里可以找到？",a="这些小碎片由佐拉姆海岸黑暗深渊洞穴大厅中的暮光侍僧携带。",al={"索兰鲁克宝珠的碎片获取地点","谁掉落索兰鲁克宝珠的碎片","索兰鲁克宝珠的碎片位置"}},{q="暮光之锤为什么会有这些碎片？",a="即使破碎了，这些碎片依然保留着被囚禁恶魔的魔法精华。暮光之锤的邪教徒搜集这些腐化的神器，以助长他们的黑暗仪式并引导禁忌魔法。",al={"为什么邪教徒会有这些碎片","暮光之锤索兰鲁克"}},{q="谁能修复索兰鲁克宝珠？",a="杜安·卡汉是一位住在南贫瘠之地靠近千针石林边界的隐士，他专门研究并重铸军团的恶魔宝珠。",al={"谁修复宝珠","在哪里上交索兰鲁克宝珠的碎片","杜安·卡汉宝珠"}}},fp="18,148,18.413.0,29.377.1,18.220.0,32.115.0,49.188.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="南海宝藏",s="南海宝藏是存放在Southsea Freebooter船只Tide Razor深处货舱中的珍贵财宝。卑鄙的维尼克斯在棘齿城悬赏寻找它，回收这批宝藏考验着初出茅庐的窃贼们的开锁和潜入技巧。",h="南海宝藏是存放在Southsea Freebooter船只Tide Razor深处货舱中的珍贵财宝。卑鄙的维尼克斯在棘齿城悬赏寻找它，回收这批宝藏考验着初出茅庐的窃贼们的开锁和潜入技巧。",kw={"大饼干","开锁","波莉","棘齿城","碎手氏族","南海宝藏","tide razor","卑鄙的维尼克斯"},ang={["class:Rogue"]="回收南海宝藏对成长中的潜行者来说是一次试炼，既能提供实战开锁练习，又能让人接触到被称为碎手氏族的神秘组织。",["faction:Horde"]="Southsea Freebooters经常骚扰贫瘠之地和棘齿城港口的贸易，因此窃取他们的核心藏宝对当地当局来说是一种受欢迎的干扰。"},sec={{t="致命抢劫",b="海盗船Tide Razor停泊在棘齿城南部的商旅海岸，是Southsea Freebooters的前哨基地和训练场。在它最底层的货舱深处，藏着一批令人垂涎的掠夺品，被称为南海宝藏。卑鄙的维尼克斯是棘齿城的一名地精无赖，他认为这是对有志成为扒手的窃贼们的终极考验。据维尼克斯所说，最后五名被派去窃取宝箱的特工都送了命，原因是船上的警惕海盗以及守卫货舱的一只极其凶猛的守护者。"},{t="波莉的纪念品",b="设法绕过海盗训练师并打开目标宝箱锁的窃贼们会发现一个恶毒的惊喜在等着他们。真正的南海宝藏并没有随意地放在箱子里，而是由一只异常敌对的鹦鹉波莉看守着。战胜这只凶猛的鸟类——通常需要借助维尼克斯的大饼干装置这样的地精工程学产品——是将宝藏取出并完好无损地带回棘齿城的唯一方法。"}},faq={{q="南海宝藏在哪里？",a="这批宝藏存放在Tide Razor上，这是一艘停泊在贫瘠之地棘齿城南海岸边的Southsea Freebooter船只。它位于海盗训练区下方的最底层货舱内。",al={"宝藏在哪里","tide razor位置","如何找到南海宝藏"}},{q="谁想要南海宝藏？",a="卑鄙的维尼克斯是一名驻扎在棘齿城的不择手段的地精，他雇佣秘密特工潜入船只并代他取回战利品。",al={"谁发布的任务","谁是卑鄙的维尼克斯","谁想要它"}},{q="为什么宝箱打开后是空的？",a="打开宝箱的锁会触发守卫货舱的极度凶猛的鹦鹉波莉出现。击败波莉才是真正获得南海宝藏的方法。",al={"波莉从哪里来","为什么波莉会出现","为什么宝箱里没有宝藏"}},{q="什么是大饼干，为什么需要它？",a="大饼干是卑鄙的维尼克斯提供的一种实验性地精装置。它旨在削弱异常凶猛的空中威胁——特别是潜伏在海盗船货舱内的致命守护鹦鹉波莉。",al={"什么是大饼干","如何击败波莉","敌对鹦鹉"}},{q="Southsea Freebooters把这艘船用来做什么？",a="Tide Razor是Southsea Freebooters的集结地和贼窝，二层设有练习用锁箱，船员们可以在那里训练他们的扒手。",al={"什么是tide razor","贫瘠之地的海盗窝","southsea船只货舱"}}},fx={c9f033cd={q="什么是南海宝藏？",a="南海宝藏是南海海盗藏匿的战利品，存放在他们停泊于贫瘠之地海岸附近的船只“潮汐剃刀”号上。宝藏深藏于船舱之中，由一只凶名远扬的海盗鹦鹉波莉看守，代表着这些海盗沿商旅海岸劫掠所得的不义之财。",al={"什么是南海宝藏","南海宝藏物品","南海宝藏是什么类型的宝藏"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="鬼梳",s="鬼梳是一种空灵的梳理工具，用于与暮色森林中那些The Restless Dead互动。它被设计成可以穿透无形的形态，被带给悲伤的灵魂盲眼玛丽，以收集幽灵的发丝。",h="鬼梳是一种空灵的梳理工具，用于与暮色森林中那些The Restless Dead互动。它被设计成可以穿透无形的形态，被带给悲伤的灵魂盲眼玛丽，以收集幽灵的发丝。",kw={"盲眼玛丽","梳子","夜色镇","暮色森林","幽灵","幽灵的发丝","鬼梳"},ang={["faction:Alliance"]="带着梳子前往夜色镇以南，这是一次鲜明的提醒，让人想起曾经生活在暮色森林的农场主们所遭受的悲惨命运。",["profession:Tailoring"]="鬼梳表明，在黑暗之地进行裁缝工作需要不寻常的采集方法，即从心甘情愿的幽灵那里获取空灵纤维，而不是进行传统的剪毛。"},sec={{t="一种针对The Restless Dead的工具",b="普通的器具无法触碰或梳理灵魂，这使得凡人工匠几乎无法收集这些空灵的材料。鬼梳专门用于与幽灵形态互动，可以滑过那些本应无形的秀发。它被带到夜色镇以南的废弃农场，在那里，哭泣的幽灵盲眼玛丽正孤独地哀鸣。玛丽从梳理她那破败头发的熟悉动作中找到了慰藉，她乐意使用这把梳子，留下了编织幽灵的发丝所需的空灵纤维。"}},faq={{q="鬼梳有什么用？",a="这把梳子被交给盲眼玛丽，一个居住在夜色镇南方的哭泣幽灵。当她用它梳理头发时，它会收集空灵的发丝，这些发丝随后可以被纺成超自然的线。",al={"鬼梳的用途","为什么我需要鬼梳","这把梳子有什么作用"}},{q="盲眼玛丽是谁？",a="盲眼玛丽是一个受折磨的灵魂，徘徊在夜色镇以南山丘上的一间废弃房屋里。悲剧使她陷入疯狂，她挖出了自己的双眼，并始终恐惧别人发现她在死后是如此丑陋。",al={"盲眼玛丽背景故事","那个拿着梳子的幽灵是谁","盲眼玛丽"}},{q="为什么不能使用普通的梳子？",a="没有特殊的魔法或附魔，灵魂无法被普通的物理工具触碰。鬼梳是专门设计用来与幽灵那无形的头发进行互动的。",al={"为什么要用鬼梳","普通梳子与幽灵"}}},fx={e893aa2f={q="什么是鬼梳？",a="鬼梳是一种专门附魔、能够与无形之物互动的灵体梳理工具。普通工具会直接穿过幽灵，无法产生效果，而这把梳子却能触碰、理顺并收集幽灵的发丝。",al={"什么是鬼梳","鬼梳","鬼梳是什么"}}},fp="13,95,24.426.0,35.162.0,18.186.0,37.128.0"}
P.entries["item:spells-of-shadow"] = {n="暗影法术研究",s="《暗影法术研究》是一本黑暗魔典，由潜伏在奥格瑞玛怒焰裂谷下的灼热之刃邪教徒携带。书中充满了燃烧军团赐予的邪能魔法，幽暗城的被遗忘者领导层正计划将其回收。",h="《暗影法术研究》是一本黑暗魔典，由潜伏在奥格瑞玛怒焰裂谷下的灼热之刃邪教徒携带。书中充满了燃烧军团赐予的邪能魔法，幽暗城的被遗忘者领导层正计划将其回收。",kw={"扭曲虚空的魔法","怒焰裂谷","灼热之刃","暗影法术研究","sylvanas windrunner","毁灭之力","幽暗城","瓦里玛萨斯"},ang={["class:Warlock"]="这本典籍代表了来自军团的直接恶魔恩惠，展示了像灼热之刃这样的非法教派是如何运用暗影和虚空法术的。",["race:Undead"]="回收这本魔典直接服务于Sylvanas Windrunner，通过获取奥格瑞玛地下的危险恶魔知识来增强幽暗城对抗天灾军团的力量。"},sec={{t="灼热之刃的魔典",b="隐藏在怒焰裂谷的熔岩深处，灼热之刃——一个依附于暗影议会的分裂教派——的成员们正掌握着由燃烧军团恶魔大师授予的黑暗仪式。他们最珍视的宝物之一便是《暗影法术研究》，这是一本包含阴险的暗影与邪能魔法的典籍。该教派的邪教徒和术士们在杜隆塔尔部落的脚下密谋时，随身携带着这本书。"},{t="黑暗女王的野心",b="有关灼热之刃获得恶魔馈赠的消息传到了幽暗城的Royal Quarter。Sylvanas Windrunner和她的恐惧魔王副官瓦里玛萨斯认为，如此强大的遗物浪费在这些目光短浅的邪教徒手中简直是暴殄天物。瓦里玛萨斯派遣部落的冒险者深入裂谷，去夺取《暗影法术研究》及其配套典籍《扭曲虚空的魔法》，并将这些力量引导至被遗忘者对抗天灾军团和巫妖王的事业中。"}},faq={{q="什么是《暗影法术研究》？",a="这是一本由怒焰裂谷的灼热之刃邪教徒所持有的恶魔魔法书，其中包含了燃烧军团赐予的暗影魔法馈赠。",al={"暗影法术研究书","什么是暗影法术研究","怒焰裂谷暗影法术书"}},{q="谁想要这本书？",a="瓦里玛萨斯，Sylvanas Windrunner的恐惧魔王顾问，代表黑暗女王寻找这本典籍。他居住在幽暗城的Royal Quarter。",al={"谁需要暗影法术研究","谁提交暗影法术研究任务","暗影法术研究任务发布者"}},{q="在哪里可以找到这本书？",a="这本书由位于奥格瑞玛城下方的怒焰裂谷网络中的灼热之刃邪教徒和术士持有。",al={"暗影法术研究位置","如何获得暗影法术研究","怎么获取暗影法术研究"}},{q="为什么被遗忘者想要这本魔典？",a="Sylvanas Windrunner相信，燃烧军团赐予的黑暗馈赠与其留在那些低级的邪教徒手中，不如由被遗忘者来更好地利用，她利用这些魔法来加强她对抗天灾军团和巫妖王的战争。",al={"为什么sylvanas windrunner想要这本书","为什么瓦里玛萨斯想要暗影法术研究"}}},fp="16,152,26.341.0,24.436.0,29.141.0,20.135.0,28.102.0,39.191.0"}
P.entries["item:spotted-sunfish"] = {n="斑点太阳鱼",s="斑点太阳鱼是赤脊山止水湖原生的一种淡水鱼。它们因肉质鲜美而在当地闻名，是湖畔镇码头的主要商品，但日益严重的鱼人威胁使捕捞工作变得危险重重。",h="斑点太阳鱼是赤脊山止水湖原生的一种淡水鱼。它们因肉质鲜美而在当地闻名，是湖畔镇码头的主要商品，但日益严重的鱼人威胁使捕捞工作变得危险重重。",kw={"码头管理员巴伦","止水湖","湖畔镇","鱼人","赤脊山","卖鱼","斑点太阳鱼"},ang={["profession:Cooking"]="像斑点太阳鱼这样的原生淡水鱼构成了止水湖的饮食支柱，使它们成为了赤脊山旅店餐桌上的常客。"},sec={{t="珍贵的渔获",b="止水湖长期以来一直以其出产的斑点太阳鱼而闻名，这种鱼在当地商人和游客中总能卖出不错的价格。码头管理员巴伦在湖畔镇的码头维持着稳定的鱼类贸易，为这座压力重重的小镇供应食物并带来商业收入。然而，在浅滩游荡的侵略性鱼人部落干扰了正常的捕鱼活动，它们经常会囤积自己的渔获，冒险者必须通过武力夺回这些鱼。"}},faq={{q="哪里可以找到斑点太阳鱼？",a="它们生长在赤脊山的止水湖水域中。垂钓者虽然可以直接从湖中钓到它们，但当地的鱼人也一直在大肆捕捞，使得湖岸边的鱼人营地成为了获取这些鱼的重要地点。",al={"获取斑点太阳鱼的地点","斑点太阳鱼位置","止水湖鱼类"}},{q="谁会购买或需要斑点太阳鱼？",a="湖畔镇码头的码头管理员巴伦会收购大批斑点太阳鱼。他一直在进行这种美味佳肴的贸易，并会向愿意为他提供新鲜渔获的人支付报酬。",al={"谁需要斑点太阳鱼","码头管理员巴伦的鱼","卖鱼任务"}},{q="为什么鱼人身上会有这些鱼？",a="生活在止水湖沿岸的鱼人会通过觅食和偷猎当地野生动物来养活不断壮大的部落。它们就像人类渔民一样从湖中捕捞太阳鱼，并将其储存在浅滩旁的营地里。",al={"鱼人斑点太阳鱼","为什么鱼人掉落鱼"}},{q="不钓鱼能获得它们吗？",a="可以。码头管理员巴伦指出，没有携带鱼竿的旅行者可以直接击败止水湖岸边充满敌意的鱼人，然后拿走它们收集到的鱼。",al={"不用鱼竿获取太阳鱼","没有鱼竿如何获取太阳鱼"}}},fx={["723094c5"]={q="什么是斑点太阳鱼？",al={"什么是斑点太阳鱼","斑点太阳鱼信息","斑点太阳鱼背景"}},["1a933976"]={q="斑点太阳鱼来自哪里？",a="斑点太阳鱼原生于赤脊山止水湖的清凉湖水中。它们并非人工制作或养殖，而是直接从湖中捕获的野生鱼类，可以在码头和岸边垂钓，也可以从当地鱼人偷猎者手中夺回。",al={"斑点太阳鱼的来源","斑点太阳鱼来自哪里","斑点太阳鱼来源"}}},fp="15,152,14.305.0,32.151.0,34.109.0,36.126.0,36.135.0"}
P.entries["item:stalker-claws"] = {n="草原捕食者的爪子",s="草原捕食者的爪子是从游荡在莫高雷草海平原上的草原捕食者身上获取的利爪。牛头人萨满祭司将它们作为雕刻传统净化图腾的重要材料，用以净化受污染的水井。",h="草原捕食者的爪子是从游荡在莫高雷草海平原上的草原捕食者身上获取的利爪。牛头人萨满祭司将它们作为雕刻传统净化图腾的重要材料，用以净化受污染的水井。",kw={"净化图腾","莫高雷","穆尔·雷角","草原捕食者","草原捕食者的爪子","雷角图腾","水井"},ang={["class:Shaman"]="野生平原捕食者的爪子驾驭着大自然狂野的纯粹，是绑定和增强净化图腾的必需材料。",["race:Tauren"]="收集这些爪子，履行了你们部落的神圣职责，以恢复被粗心的工业入侵者所毒害的神圣水域。"},sec={{t="平原上的捕食者",b="莫高雷的草原是致命的天然捕食者的家园，其中就包括潜行的草原捕食者。这些野兽凭借原始的本能和致命的精准生存，这是大地母亲设计中不可或缺的平衡。穆尔·雷角想要治愈这片遭受破坏的土地，他需要这些爪子并非出于对动物的恶意，而是因为它们捕猎时所展现出的纯粹、自然的凶猛，蕴含着抵御人为腐化所必需的精神共鸣。"},{t="净化水井",b="当地精企业开始在整个卡利姆多中部进行钻探和采矿时，化学毒素渗入了为牛头人祖传水井供水的地下水层。雷角水井尤其深受这种邪恶污染的毒害。通过将草原捕食者的爪子和平原狮的爪子结合在一起制作成雷角之井净化图腾，部落萨满祭司能够创造出一种精神媒介，用以清除大地天然泉水中的污垢和不自然的淤泥。"}},faq={{q="草原捕食者的爪子从哪里来？",a="它们是通过在莫高雷的草丘上狩猎草原捕食者获取的，主要分布在血蹄村的东部和西部。",al={"草原捕食者的爪子位置","谁掉落草原捕食者的爪子","草原捕食者的爪子来源"}},{q="穆尔·雷角为什么需要这些爪子？",a="穆尔·雷角使用这些爪子，连同平原狮的爪子，来制作雷角之井净化图腾。平原本土捕食者与生俱来的纯粹与力量，正是净化受污染水井所必需的。",al={"为什么要收集草原捕食者的爪子","穆尔·雷角的目的","草原捕食者的爪子用途"}},{q="雷角水井为什么会受污染？",a="该水井正遭受因莫高雷的地精行动所引起的人为工业污染，这些行动破坏了自然平衡，并毒害了当地的地下水位。",al={"谁毒害了水井","雷角水井为什么生病","雷角水井污染"}},{q="收集到爪子后该做什么？",a="一旦收集完毕，穆尔会将这些爪子雕刻成净化图腾，然后必须将其直接带到雷角水井，以清除残留的腐化。",al={"what comes next","收集爪子后的下一步","净化图腾仪式"}}},fp="13,150,23.389.0,19.363.0,33.139.0,43.178.0,42.141.0,42.175.0"}
